window.HARDTRP.receive("112272",[[112273,"2026-07-13T08:51:56",9,"Начало темы.\n\n@dunchev — Дм этой темы.",112272,null],[112289,"2026-07-13T09:54:29",17,"Каждый из героев получил одинаковое письмо, запечатанное выцветшим гербом деревни.\n\nТем, кто ещё способен держать оружие и не боится войти в Багровию.\n\nЯ, Колун Индирович, бургомистр деревни Багровой, прошу вашей помощи.\nГраф Сад фон Зрович преследует мою дочь Ирину. Его слуги приходят по ночам, а стены моего дома уже не выдержат нового нападения.\nДоберитесь до Багровой. Защитите Ирину и увезите её туда, куда не дотянется рука графа.\nЗа её спасение я отдам вам всё, что осталось в казне деревни: серебро, монеты и ценности, собранные за последние годы. Больше мне предложить нечего.\nНе медлите. Здесь каждая ночь может стать последней.\n\nКолун Индирович. Бургомистр деревни Багровой\nНа обороте письма бурое пятно, а печать продавлена дважды, будто письмо запечатывали дрожащей рукой.\n\nПо тем или иным причинам вы решились откликнуться за мольбу о помощи, тем более, что награда обещана очень приличная.",112272,null],[112290,"2026-07-13T09:56:58",17,"Туман сомкнулся вокруг дороги внезапно.\n\nСначала исчезли дальние деревья. Потом влажная белизна скрыла обочины и поглотила следы позади. Звуки стали глухими, ваши шаги, скрип ремней, дыхание.\n\nТуман лип к одежде холодными каплями. Под ногами мягкая земля постепенно сменилась старой каменной дорогой. Крупные плиты ушли в грязь, многие раскололись, между ними пророс чёрный мох.\n\nСправа и слева тянулся лес. Стволы стояли близко к дороге, ветви цеплялись друг за друга над головами.",112272,null],[112291,"2026-07-13T09:58:12",17,"Дорога шла вниз ещё около часа. Впереди проступили первые крыши. Низкие, тёмные, местами провалившиеся.\nНа столбе у дороги прибита деревянная доска\n\n\"БАГРОВАЯ\"\n\nПоследние две буквы исцарапаны ножом.\nГде-то за домами один раз звонит колокол. На холме небольшая церквушка.\n\nДеревня Багровая. Графство Сада Фон Зровича. Небольшой клочек земли, где властвует правитель этих земель. Солнца тут никогда не видно, небо затянуто плотными свинцовыми тучами, и не понять день сейчас или уже вечер, утро... ночь?\n\nДоговорённости с Веспираллем дают ему делать на своей земле, что он хочет, оплачивая дань вовремя.\n\nДорога спускается между покосившимися домами. Дождь давно кончился, но грязь всё ещё блестит в колеях. Над крышами висит низкий дым. Ставни закрыты даже там, в окнах нет света.",112272,null],[112292,"2026-07-13T09:59:10",17,"/ Тут и начинается эта история\n\n@QURTZZ @Evreiskui_Department @FSmit7",112272,null],[112295,"2026-07-13T10:09:40",60,"//О, славянский страд",112289,null],[112296,"2026-07-13T10:13:40",60,"—Да... Мрачное местечко. Кто как не обустроит свой уютный уголок.. Ща посмотрим, где тут помочь надо. На словах всё несложно: найдём бабу, запакуем и увезём к черту на куличики, пока нам не вставили палки в колёса. Дай бог, чтоб только в колёса..\n\nАльфарий хоть и выглядит хмуро, но от собственных реплик едва усмехается. За его спиной светится двуручный меч, пока сам стадюймовый варвар двигается в деревню, озираясь по сторонам. Очевидно, что тут жизнь ой как не хороша..\n\n—Хм.. Возможно нам даже стоит двигаться чуть незаметнее.",112291,null],[112297,"2026-07-13T10:15:14",31,"Тарх оглядвыется. Да, словно и не уезжал из дома...",112272,null],[112299,"2026-07-13T10:17:51",17,"/ @Evreiskui_Department Ты живой, сынок? Пора ЗА РАБОТУ",112272,null],[112303,"2026-07-13T10:22:01",31,"//это место уже начало забирать людей...",112272,null],[112304,"2026-07-13T10:23:12",17,"/ Ну можете пока походить побродить осмотреться",112272,null],[112305,"2026-07-13T10:24:32",31,"пользуясь своим затрапезным внешним видом, не отличимым от большинства местных крестьян, оглядываюсь в поисках этих самых местных. Может получится что то разузнать из их болтовни?",112272,null],[112311,"2026-07-13T10:29:08",17,"Местных на улице сейчас почти нет\n\nУ обочины стоит тощий мужчина в длинной, не по размеру большой рубахе. Одной рукой он держит за плечо мальчика лет шести, другой протягивает старухе небольшой мешок.\n\nСтаруха принимает его и ставит мужчине под ноги корзинку, накрытую клетчатой тканью. Из-под ткани пахнет тёплым тестом, корицей.\n\nМальчик тянется к корзинке.\n\n— Пап, мне два.\nМужчина бьёт его по руке.\n\n— Дома.\n\nСтаруха замечает героев. Её взгляд задерживается на крыльях Немеи, затем на изменённом глазе Альфария.\n— Свежие лица. Берите пирожки, только что испекла.\n\nПод тканью лежат пять тёмных пирожков. \n\nЗапах пирожков просто космический, такое ощущение что это лучшее что вы чувствовали когда либо. Обильно начинается слюноотделение у вас всех.",112272,null],[112313,"2026-07-13T10:32:36",31,"*пользуюсь тем что старуха отвлечена внешностью моих спутников, просто наблюдаю. Но брюхо едва ли не стонет о желания сожрать пирожок*",112272,null],[112315,"2026-07-13T10:35:13",17,"/Внимание кинь",112313,null],[112317,"2026-07-13T10:37:32",31,"/roll d20+1 приглядываюсь и принюхиваюмь",112315,null],[112319,"2026-07-13T10:37:58",17,"Ты замечаешь что мешок который мужик передал старушке - дёрнулся изнутри чучуть",112272,null],[112320,"2026-07-13T10:39:02",36,"//Кью опутывает их грибами",112319,null],[112321,"2026-07-13T10:39:39",31,"*мысли* Там, кажется, что то живое. Надеюсь, просто кролик или курица, будущая начинка для пирогов",112272,null],[112322,"2026-07-13T10:40:22",60,"Альфарий подходит ближе, кивает в знак приветствия и нюхает пирожки, пытаясь понять их состав, в основном начинку. Это даже не поиск отравы, просто попытка распознать содержимое, чтоб выбрать что повкуснее\n\n—Добра вам, люди. Мы тут по делу, наверное заметно.",112311,null],[112324,"2026-07-13T10:42:39",17,"Пироги все с мясом, пахнут восхитительно. \n\nМужик зыркает на тебя и лишь дергает мальчика за руку, тянет в сторону лачуги, забирая корзинку с пирогами с собой. Не отвечает.\n\n— Деловые люди. Как замечательно. Вы угощайтесь, бесплатно!\n\nСтарушка протягивает один пирожок Альфу",112322,null],[112326,"2026-07-13T10:44:35",60,"Варвар без лишних раздумий берёт пирог и делает укус.\n\n—Бвагодавствую, ставуфка.\n\nГоворит Альф, пережевывая мясо",112324,null],[112327,"2026-07-13T10:45:52",17,"Вкус не передать словами, сочнейшее мясо, насыщает тебя так, как никогда в жизни и нежнейшее тесто, это лучший пирожок, нет лучший укус в твоей жизни.",112326,null],[112332,"2026-07-13T11:01:44",17,"— Ты тоже бери мужик, и ты крылатая\n\nСтарушка достала пару пирожков и протягивает остальным",112321,null],[112335,"2026-07-13T11:04:19",31,"с недоверием все таки беру и кусаю пирожок",112332,null],[112336,"2026-07-13T11:05:39",17,"Очень вкусно, очень сочно, очень насыщает.\n\nКажется что вокруг уже не так грязно, не так мерзко, не так серо. Тебе определенно стало лучше от этого пирожка.\n\nСтарушка улыбается мило. \n\n— Ребятушки, а чем так у вас у сумок воняет, вы не чуете?",112272,null],[112339,"2026-07-13T11:08:50",60,"—Из сумок? Да не было там ничего толком..\n\nВарвар доедает пирог и оборачивается к своему рюкзаку, проверяя содержимое на наличие того, что может вонять. Быть может он забыл вытащить протухшее мясо на прошлой неделе",112336,null],[112340,"2026-07-13T11:09:30",17,"А внутри действительно тебе в ноздри бьёт запах гнили, все твои съестные запасы, пойки, всё сгнило и ужасно воняет",112272,null],[112341,"2026-07-13T11:10:01",31,"Перевожу взгялд на сумку, знаю что она пустая и вонять там нечему, но всеже проверяю",112272,null],[112342,"2026-07-13T11:10:20",17,"/ Если пайков у тебя не было там не воняет",112272,null],[112343,"2026-07-13T11:11:16",60,"—У меня.. Странная херня, ладно. Мне нужно будет пополнить запасы жратвы.\n\nВарвар вынимает продовольствие и выкидывает в канаву\n\n—Сожрут собаки, похеру. В общем. Мы тут по делу. Нам нужна одна мадама, за которой кое-кто охотится. Нет у вас тут таких примечательных мадамов?",112340,null],[112344,"2026-07-13T11:13:49",17,"— Ой, я не отсюда, но знаю, если нужна мадама это к бургомистру деревни идите, его дом вооон там самый большой.\n\nОна показывает длинным пальцем в сторону пригорья холма, там большой дом.",112343,null],[112345,"2026-07-13T11:23:08",31,"*вспоминаю текст письма*\n\n- да, пожалуй нам именно к бургомистру и нужно",112272,null],[112348,"2026-07-13T11:26:01",17,"/Еврейский департамент пропащий, ладна запомним, ждём пока придёт третий наш игрок",112272,null],[112351,"2026-07-13T11:29:01",7,"/ да теперь, я на дачу ехал инета не было",112299,null],[112352,"2026-07-13T11:29:32",7,"/я же писал что в пути буду и не сразу освобожусь",112348,null],[112354,"2026-07-13T11:29:35",17,"/ Читай вникай, представь перса артом и парой фраз",112272,null],[112355,"2026-07-13T11:29:36",7,"/ нет?",112272,null],[112362,"2026-07-13T11:35:56",7,"/ я читаю",112272,null],[112363,"2026-07-13T11:39:22",60,"//какой у тебя Промт на такую зернистость?",112361,null],[112364,"2026-07-13T11:39:44",17,"/ in the style of classic fantasy oil painting, heavy brushstrokes, impasto technique, rich color tones, dramatic Renaissance-style chiaroscuro lighting, masterpiece quality, painted on canvas, 4k.",112272,null],[112366,"2026-07-13T11:43:42",7,"*Немейя ступала за ребятками. Она осматривала деревню, в этом ужасном место. Везде слякоть, грязь, огня не хватает для освещения и слегка прохладно. Запах гнили ударяет в ноздри, от чего хочется только лишь вырвать. Так или иначе, она себя по пути сама отвлекала на огонёк в воздухе и услышав бабушку, хватает пирог. Она держит его в руке и пока не кушает, не голодна. А про \"крылатую\", пытается за спину сложить их.*\n\n— Запах гнили убивает... Ребята, есть наводки — ступаем к бургомистру.\n\n*Говорит с неким не то, что недовольством, а скорее неким раздражением от окружения. Параллельно думает про себя.*\n\n\" Надо просто помочь перебрать девушку в безопасное место и все будет хорошо... Ничего сложного. \"",112272,null],[112367,"2026-07-13T11:43:52",7,"/ пост есть, готов в путь ступать",112272,null],[112370,"2026-07-13T11:47:57",17,"/ У тебя тоже все пайки сгнили после перехода через туманы, так что минусуем, еды у тебя только 1 пирожок еще не съеденый",112366,null],[112371,"2026-07-13T11:50:29",17,"Вы подходите к большому дому, сразу заметно на деревянных стенах следы от котей и клыков, царапины и оторванные куски, будто выгрызли, окна заколочены досками изнутри. \n\nВы у большой деревянной двери",112272,null],[112372,"2026-07-13T11:50:36",7,"/ будет что сжечь 💅",112370,null],[112373,"2026-07-13T11:54:07",7,"*По пути к большому дому, девушка в угол выкидывает все пойки в траву. Пока никто не видит из местных, еле удержалась, чтобы не поджечь. Однако позже присоединилась к товарищам и решает первой постучаться.*\n\n— Здравствуйте, здесь Ирина Сан Фон? \n\n*Говорит не громко, достаточно, чтобы через дверь были слышны слова.*",112371,null],[112375,"2026-07-13T11:54:31",7,"/ Добрыня и монголы, кадр как Добрыня пытается мирно зайти",112272,null],[112377,"2026-07-13T11:55:06",17,"Мужской голос из-за двери через некоторое время спрашивает\n\n— Что вам нужно, и кто вы? Вас прислал граф?",112373,null],[112378,"2026-07-13T11:56:23",7,"Немейя\n— Угу, мы от некого графа... Колун Индирович... Вроде...  Листовка с собой, можем показать. Откройте пожалуйста.",112272,null],[112379,"2026-07-13T11:57:48",31,"- мы скорее не от графа, а против графа//",112272,null],[112380,"2026-07-13T11:59:22",7,"/ я знаю, я персонажа отыгрываю",112272,null],[112381,"2026-07-13T11:59:51",7,"/ бля ща дополню, забыл написать",112272,null],[112383,"2026-07-13T12:00:33",7,"/ все",112272,null],[112385,"2026-07-13T12:00:52",17,"— Если вы от этого ублюдка, то валите отсюда подобру по здорову! Этот скот не получит мою сестру, так и передайте ему!",112272,null],[112388,"2026-07-13T12:02:19",7,"Немейя\n— Так мы ее в безопасное место отвезти хотим. Вот письмо ваше, но герб какой то... Выцвевший. \n\n/ Получиться письмо просунуть под дверью?",112272,null],[112390,"2026-07-13T12:02:51",17,"/ Да",112272,null],[112391,"2026-07-13T12:03:23",7,"/ сую свое письмо под дверь, чтобы прочитали",112390,null],[112393,"2026-07-13T12:05:55",17,"Шуршание за дверью",112272,null],[112398,"2026-07-13T12:07:17",17,"— Вы шутите так, да? Это письмо от моего отца, господи как же низко мы пали, что готовы отдать всё, но ради спасения... Ладно, входите в дом быстро! Только подождите я уберу барикаду\n\nЗа стеной стуки и звуки волочения мебели, мужчина двигает и наконец отворяет дверь\n\n— Входите быстрее.",112272,null],[112402,"2026-07-13T12:08:29",60,"Альфарий не тупит и не медлит, торопливо проталкивая свою тушу в проём",112398,null],[112403,"2026-07-13T12:09:16",7,"*Немейя мгновенно прошла вовнутрь, с сложенными крыльями, дабы много места не занимать в проёме.*",112272,null],[112404,"2026-07-13T12:09:36",17,"Внутри помещение скудное, большинство мебели разломано и кусками забиты окна, другая часть в виде барикады закрывает дверь\n\nМужчина это достаточно молодой юноша задвигает барикаду назад",112272,null],[112406,"2026-07-13T12:10:52",60,"—Ну здрасьте, приехали.. Еда у нас прогнила, так что задерживаться сильно тому подавно не надо. Есть знакомые за пределами этой.. Деревни? Куда подальше надо смотаться.",112404,null],[112408,"2026-07-13T12:11:16",31,"//я офф на полчасика, работать заставляют. Если что, я со всем согласный с группой рюкзак//",112272,null],[112410,"2026-07-13T12:12:36",17,"Когда он наконец закончил он образется к вам\n\n— Я Исмарк Индирович, сын бургомистра, который написал это письмо.\n\nОн трясет бумагой\n\n— Ирина иди сюда. наемники пришли помочь. \n\nСо второго этажа по лестнице спускается молодая красивая девушка, у нее под глазами темные пятна от недостатка сна и от частых слёз. А лицо бледное\n\n— Это моя сестра Ирина, граф, будь он не ладен, хочет забрать её в жены, но мы не согласны, она не согласна.\n\nДевушка кивает",112272,null],[112412,"2026-07-13T12:13:38",17,"Исмарк",112272,null],[112413,"2026-07-13T12:13:44",17,"Ирина",112272,null],[112414,"2026-07-13T12:13:45",17,"— К сожалению наш отец... Скончался. Мы уже несколько дней терпим осаду от тварей и его сердце не выдержало. Так, что платить вам, если спасёте мою сестру буду я.",112272,null],[112416,"2026-07-13T12:15:56",60,"—Оп... Соболезную. Тогда тем более не медлим. Подальше уедем, если этому тут ничего не препятствует. Желательно замаскировать сестру вашу.. Под кого-то более неприметного. Ну грязью измазать и свалить, чтоб проблем не схлопотать. А я точно знаю, что лучше грязь на лице, чем остриё в спине..",112414,null],[112417,"2026-07-13T12:18:17",7,"*Немейя посмотрела на Ирину и решает запомнить. Ее точно трогать не стоит, что говорить о Исмарке.*\n\n— Угу... Погиб... Печально, ну давайте тогда быстро замаскируем Ирину и... Мм... Либо грязь, либо тонна одежды. А также запах поменять, не люблю чёртовых собак...",112272,null],[112419,"2026-07-13T12:19:58",17,"Девушка хватает брата за рукав рубахи\n\n— Исмарк, мы не можем оставить отца. Ты знаешь, его неупокоеная душа будет преследовать меня до скончания веков. Прошу, брат. Мы должны провести погребальный обряд, иначе его душа не будет свободна.\n\nИсмарк дергает руки и рукав выскальзывает у девушки из рук\n\n— Знаю! Погоди, дело говорят, нужно готовить тебя к побегу из деревни...\n\nОн подходит к заколоченному окну и смотрит в щель\n\n— ОНИ ИДУТ! К Оружию! Защитите Ирину любой ценой, прошу вас!",112416,null],[112420,"2026-07-13T12:22:33",60,"—Каво, с оружием.. Да ну нахер..\n\nНедовольствует варвар, его кожа древенеет, черный глаз тенью расползается на треть лица, он выхватывает двуручник из-за спины и подходит к двери, готовя атаку, как только дело запахнет керосином\n\n—Звездец гнилюкам.",112419,null],[112430,"2026-07-13T12:27:02",7,"*Девушка услышав \"к оружию\", мгновенно приулыбнулась. Она создала в руках еще большее пламя, с улыбкой на лице.*\n\n— Только не выдохнитесь, пока будете сражаться. \n\n*Говорит с улыбкой на лице и жаждой сожжения.*",112272,null],[112431,"2026-07-13T12:27:23",7,"/ через 16 минут придет и напишет пост",112408,null],[112449,"2026-07-13T12:39:22",31,"- В дом один вход? нужно понять, сколько тут возможностей проникнуть внутрь.\n\n*вилы в руках, вторая рука на рукоятке серпа*",112272,null],[112451,"2026-07-13T12:41:16",31,"Могу  спрятатся в тени здоровенного варвара? Ну чтобы при возможности нанести удар из укрытия?//",112272,null],[112464,"2026-07-13T13:01:55",7,"/ Ирину может укрыть попытаешься?",112451,null],[112465,"2026-07-13T13:01:58",7,"/ ты же воин?",112272,null],[112466,"2026-07-13T13:02:23",31,"я обыватель, недовоин можно сказать//",112465,null],[112467,"2026-07-13T13:02:32",31,"местный ХБ-класс//",112272,null],[112468,"2026-07-13T13:03:42",31,"//но в целом идея разумная, мне и правда лучше держаться позади варвара-танка и быть последним рубежом обороны//",112272,null],[112473,"2026-07-13T13:56:46",60,"//ща походу будут дверь выбивать",112272,null],[112474,"2026-07-13T13:57:01",60,"—Сколько их там??",112419,null],[112476,"2026-07-13T14:01:02",7,"/ выбили дверь, а их встретили огненными ладонями по лицу",112473,null],[112478,"2026-07-13T14:04:18",60,"//волшебной палкой на к6+к4+13 урона",112476,null],[112479,"2026-07-13T14:05:51",7,"/ эх, я такую шайтан машину замутил\nНаношу в ближней дистанции урон заклинания + 2 модификатора харизмы + 2d4 отдельно урона с + модификатор харизмы",112478,null],[112480,"2026-07-13T14:07:18",60,"//пахнет.. Духом хоубрюшным.. Тут им прям вонять будет, раз приемы Мидгарда встроены в базу",112479,null],[112481,"2026-07-13T14:07:23",60,"//но звучит гуд",112272,null],[112482,"2026-07-13T14:07:28",60,"//туда же адепт стихийный",112272,null],[112483,"2026-07-13T14:08:17",7,"/ 4 уровень от черты",112482,null],[112484,"2026-07-13T14:08:40",7,"/ а так от хб только урон к огню в форме огненной вуали и д4 кость. Остальное не хб",112272,null],[112486,"2026-07-13T14:51:26",17,"— Ирина на второй этаж!\n\nИсмарк бежит вместе с ней, Тарх видимо тоже",112272,null],[112487,"2026-07-13T14:51:43",60,"//умные",112486,null],[112488,"2026-07-13T14:51:48",60,"//не как я",112272,null],[112489,"2026-07-13T14:52:05",17,"Из щелей видно как по улице крадётся толпа",112272,null],[112490,"2026-07-13T14:52:21",17,"Со стороны леса выходит стая",112272,null],[112491,"2026-07-13T14:52:22",60,"//ну во-первых они не похожи на женихов",112489,null],[112492,"2026-07-13T14:52:33",17,"Все они медленно но верно движутся к дому бургомистра",112272,null],[112493,"2026-07-13T14:52:37",60,"//а во вторых ауф",112490,null],[112494,"2026-07-13T14:53:09",60,"//дверь забаррикадирована. Сколько времени нужно, чтоб сдвинуть баррикаду?",112492,null],[112495,"2026-07-13T14:53:21",17,"/ 1 действие",112272,null],[112496,"2026-07-13T14:53:36",60,"//фигня вопрос. Как далеко мужики и волки?",112272,null],[112497,"2026-07-13T14:53:48",17,"// в 30 пока что",112272,null],[112498,"2026-07-13T14:54:55",60,"Альфарий решает не ждать, пока враг выбьет укрытие, и использовать дверь и стены как положено. Он сметает баррикаду мощным толчком рук и бьет себя ладонью по лбу, чтоб рассверипеть ещё больше\n\n—Покажем им мою мать!",112272,null],[112499,"2026-07-13T14:55:19",60,"//бонуской ярость поддерживаю, ес что, да",112272,null],[112500,"2026-07-13T14:55:54",17,"// Гости ближе",112272,null],[112501,"2026-07-13T14:56:11",60,"//насколько?",112500,null],[112502,"2026-07-13T14:56:31",17,"// Движутся потехоньку, щас узнает действия остальных и придут",112272,null],[112503,"2026-07-13T14:56:35",60,"//и, думаю, @QURTZZ @Evreiskui_Department пора дать по жопе господам. Дверку я разблокировал",112272,null],[112504,"2026-07-13T14:59:49",7,"/ тэк... Ну ничего сделать не получиться, кроме обстрела гостей издали",112502,null],[112505,"2026-07-13T15:00:16",31,"Я ушел на второй этаж, выступаю как телохранитель Ирины, прячусь за дверь и готовлюсь пощекотать серпом кишки тем, кто туда сунется",112272,null],[112506,"2026-07-13T15:00:24",7,"/ ну делать нечего, описываю как кидаю огненный снаряд",112272,null],[112507,"2026-07-13T15:02:03",17,"Когда ты поднялся на второй этаж ты увидел его. Бургомистра этой деревни. Их отца. На кухонном столе лежит тело в красивом костюме и цветах. Руки сложены на груди. А лицо его земленистое, серое.",112505,null],[112508,"2026-07-13T15:02:18",7,"/ думац надо... На лестнице второго этажа постоять, чтобы кинуть огненные ладони в большее количество",112272,null],[112509,"2026-07-13T15:02:45",60,"//тьфу, зараза, дед, не пугай нахер",112507,null],[112510,"2026-07-13T15:03:41",7,"/ это обманка, это лич!",112509,null],[112511,"2026-07-13T15:05:50",7,"/ не мне реально ничего умного кроме метания огненного снаряда не пришло.",112272,null],[112512,"2026-07-13T15:05:58",7,"/ хотя... Лес...",112272,null],[112513,"2026-07-13T15:06:09",7,"/ @dunchev в лесу насколько сухие деревья?",112272,null],[112514,"2026-07-13T15:06:24",17,"/ Мокрые и влажные от тумана и измороси",112272,null],[112515,"2026-07-13T15:06:46",7,"/ *Грустные звуки поджигателя*",112272,null],[112516,"2026-07-13T15:07:13",31,"Могу осмотреть на предмет укусов на шее? А то ребята что бегут к нам на вампирские  мысли наводят//",112507,null],[112517,"2026-07-13T15:09:18",7,"/ хм, может... Может сжечь поместье? Или дома чьи-то.... Сместить фокус",112272,null],[112518,"2026-07-13T15:09:47",17,"/ Да, кидай внимание",112516,null],[112519,"2026-07-13T15:10:00",7,"/ но по ощущениям к нам идут зомби, а не крестьяне. К нам же люди идут?",112518,null],[112520,"2026-07-13T15:10:08",17,"/ Опиши заготовленое действие и я начну в РП",112515,null],[112521,"2026-07-13T15:10:25",17,"/ Мертвецы явно, кто то ползёт, кто то свежий, кто то нет",112519,null],[112522,"2026-07-13T15:11:23",31,"/roll d20+1",112518,null],[112524,"2026-07-13T15:12:37",17,"Ты осматриваешь труп, шею в основном и точно не находишь никаких укусов. Ниодного.\n\nНо вот между делом взгляд падает на Ирину, она от страха взяла себя за косу и прикрылась ей, а на оголенной шее ты видишь две четкие отметины, от клыков.",112522,null],[112525,"2026-07-13T15:12:41",7,"/ отхожу от выхода на угол так, чтобы не выходить. Как только подойдут все мертвецы, кастую огненные ладони... Ладно была не была, использую огненную вуаль. Буду сносить много зомбаков. @FSmit7 рекомендую к лестнице отойти за Немейю. Говорю как персонажу, просто заготавливаю действие",112520,null],[112526,"2026-07-13T15:12:43",17,"На Исмарке ничего нет",112272,null],[112527,"2026-07-13T15:13:01",17,"/  А зачем ты ставишь / пока ты не написал в РП это, этого нет",112525,null],[112528,"2026-07-13T15:13:22",7,"/ ну пиздец",112524,null],[112529,"2026-07-13T15:13:38",17,"/ Можно ваще без меты хуярить, было бы желание",112272,null],[112530,"2026-07-13T15:13:40",7,"/ понял, щас будет",112527,null],[112531,"2026-07-13T15:14:07",60,"//где там святая вода..",112524,null],[112532,"2026-07-13T15:14:21",7,"/ щас будет святой огонь инквизиции",112531,null],[112533,"2026-07-13T15:14:58",31,"Ебатся сраться... Я думал старика добью пока спит, а тут готовая Вампирша///",112272,null],[112534,"2026-07-13T15:15:07",17,"/ Ладно понял ты заготовил дрочить пока кто то не войдёт океееей",112525,null],[112535,"2026-07-13T15:16:07",17,"Удар в дверь, стук в заколоченые окна которых четыре по стенам первого этажа\n\nМертвецы здесь\n\nВолки скалятся за стеной, царапают стены и входы\n\nОсада началась",112272,null],[112537,"2026-07-13T15:16:59",17,"/r -1 Зомби1 -1 Зомби2 +2 Волки1 +2 Волки2",112272,null],[112539,"2026-07-13T15:17:29",17,"/ Инициативу киньте заготовки сработают по триггеру",112272,null],[112540,"2026-07-13T15:17:41",17,"/r +3 Исмарк",112272,null],[112542,"2026-07-13T15:17:57",17,"Волки1 (0/3)\nВолки2 (0/3)\nАльф\nЛетучие мыши (3/3)\nЗомби2 (0/4)\nНемея\nИсмарк\nНетопыри\nТарх\nРидли\nЗомби1 (0/4)\nЗомби3 (4/4)",112272,null],[112543,"2026-07-13T15:18:05",31,"//я пока не отсвечиваю?//",112272,null],[112544,"2026-07-13T15:18:13",17,"/ Кидай",112543,null],[112545,"2026-07-13T15:18:30",31,"/roll d20+1",112272,null],[112547,"2026-07-13T15:18:36",17,"Тарх видит что два окна на втором этаже не заколочены",112272,null],[112548,"2026-07-13T15:19:58",60,"/r +1 снова хожу последний наверное",112272,null],[112550,"2026-07-13T15:20:15",7,"/r d20 +2 ини",112539,null],[112553,"2026-07-13T15:23:35",17,"Волки запрыгивают на мертвецов и лезут по их телам к окну второго этажа\n\nВ суицидальном прыжке один из волков бьётся мордой о стекло",112272,null],[112554,"2026-07-13T15:23:39",17,"/r +2 Акробатика",112272,null],[112556,"2026-07-13T15:23:50",17,"/r 2d6 По стеклу",112272,null],[112558,"2026-07-13T15:24:22",60,"//волки тоже зомби?",112272,null],[112559,"2026-07-13T15:24:46",17,"Часть стекла выбито внутрь но рама еще держится\n\nИсмарк кричит \n\n— Холера! Это что такое?!\nТарху повернулся и орёт\n—  Парень! Помогай!",112272,null],[112560,"2026-07-13T15:24:59",17,"Он встаёт с мечом напротив окна\n\nИрина вскрикивает",112272,null],[112561,"2026-07-13T15:25:25",17,"Другая часть стаи грызут доски барикады на третьем окне снизу",112272,null],[112562,"2026-07-13T15:25:39",17,"/r 4d6+9",112272,null],[112564,"2026-07-13T15:26:12",17,"Три волка выгрызают дыру и выносят несколько досок внутрь",112272,null],[112565,"2026-07-13T15:26:23",17,"/ Ход Альфа",112272,null],[112566,"2026-07-13T15:26:28",60,"//сюда бы облако кинжалов на лестницу..",112272,null],[112567,"2026-07-13T15:26:38",60,"//в моей досягаемости есть две цели?",112565,null],[112568,"2026-07-13T15:26:43",7,"/ огненные ладони приятно тоже",112566,null],[112569,"2026-07-13T15:26:57",60,"//ладошки разовые только",112568,null],[112570,"2026-07-13T15:27:11",7,"/ не без минусов",112569,null],[112571,"2026-07-13T15:27:55",9,"//Облако огненных кинджалов",112566,null],[112572,"2026-07-13T15:27:59",60,"//в общем если есть два врага, то я врубаю инвиз, атакую приёмом двурука и делаю прыг на лестницу",112272,null],[112573,"2026-07-13T15:29:16",60,"Альфарий был готов к атаке. И решил атаковать первым. Он слегка замерцал, а затем растворился, очутившись прямо перед мордами волков, замахиваясь над оконной рамой\n\n—Салам, ёпта!\n\nА затем сияющий двуручник обрушивается им на головы, угрожая быстрой расправой",112272,null],[112574,"2026-07-13T15:29:27",7,"/ а можно? 👉👈",112571,null],[112575,"2026-07-13T15:29:31",17,"/ Нет они все за стенами",112567,null],[112576,"2026-07-13T15:29:50",60,"//значит дверку открыл пинком",112575,null],[112577,"2026-07-13T15:29:56",60,"//если такая возможность есть",112272,null],[112578,"2026-07-13T15:30:01",17,"/ Через окно волков можно достать кста",112272,null],[112579,"2026-07-13T15:30:10",60,"//ну значит тогда для начала их",112578,null],[112580,"2026-07-13T15:30:11",17,"/ Она открывается внутрь)",112272,null],[112581,"2026-07-13T15:30:19",60,"//ща подправим",112272,null],[112582,"2026-07-13T15:31:10",60,"/roll +d20 кто не рискует тот не пьёт кротовуху",112573,null],[112584,"2026-07-13T15:31:17",60,"//ну видимо мимо",112272,null],[112585,"2026-07-13T15:31:26",60,"//хотя хз, че там по кд волков",112272,null],[112586,"2026-07-13T15:32:48",31,"//ну волки броню не носят//",112272,null],[112587,"2026-07-13T15:33:10",7,"/ ровно в кд если оригинальные волки",112585,null],[112588,"2026-07-13T15:33:31",31,"//Помогу братан, помогу, ты только доживи до моего ухода по инициативе//",112559,null],[112589,"2026-07-13T15:33:41",17,"/ Попал да",112272,null],[112590,"2026-07-13T15:33:56",60,"/roll d6+d4+13 каждому",112589,null],[112592,"2026-07-13T15:35:04",17,"Ты ужасно полоснул двоих волков через узкую щель\n\nИ оба они погибли",112272,null],[112593,"2026-07-13T15:35:37",17,"Зомби ломяться в дверь",112272,null],[112594,"2026-07-13T15:35:58",60,"//там ещё один остался из тех, что мог кусать. В целом трупики будут блокировать подход к окошку, поэтому Альф остается рядом",112272,null],[112595,"2026-07-13T15:36:15",60,"//но так, подальше от двери, чтоб огненные ладошки не задели",112272,null],[112596,"2026-07-13T15:36:20",17,"/r 4d8+4 По двери",112272,null],[112598,"2026-07-13T15:36:52",17,"Давление мёртвых тел выносит дверь срывая с петель, барикады там небыло и четверо зомби вваливаются в комнату",112272,null],[112599,"2026-07-13T15:37:09",17,"/ Че там огненные ладони заготовка",112272,null],[112600,"2026-07-13T15:37:40",60,"//растения против зомби второй слой обороны",112272,null],[112601,"2026-07-13T15:37:48",60,"//альфарий тот ещё баклажан",112272,null],[112602,"2026-07-13T15:39:26",7,"/ сл 14 спасбросок ловкости",112599,null],[112603,"2026-07-13T15:39:46",7,"/ и все кто в 5 футах от меня получат доп 2д4",112272,null],[112604,"2026-07-13T15:40:26",7,"/ а Немейя либо вишня, либо на высоком уровне гриб судьбы",112601,null],[112605,"2026-07-13T15:40:50",7,"/ после атаки опишу",112272,null],[112606,"2026-07-13T15:41:07",7,"/ ну чтобы описывал огонь нормально",112272,null],[112607,"2026-07-13T15:41:30",17,"/r -1 Четверо зомби в отряде проходят спас ловкости",112272,null],[112609,"2026-07-13T15:41:42",17,"/ ХАХА!",112272,null],[112610,"2026-07-13T15:41:58",17,"/ Это \"зомби съели моих соседей\"",112600,null],[112611,"2026-07-13T15:42:29",60,"//ну вот, спойлеры пошли",112610,null],[112612,"2026-07-13T15:42:32",7,"/r 3d6 +4",112272,null],[112614,"2026-07-13T15:42:41",7,"/ 8 урона огнём\nНайс",112272,null],[112615,"2026-07-13T15:43:58",17,"Твой огонь в этом месте... поменялся\n\nСейчас из ладоней исходит синее холодное пламя\n\nНо зомби кажется горят так, как и должны\n\nВдруг у тебя схватило дыхание будто ударили под дых",112272,null],[112616,"2026-07-13T15:44:03",17,"/r d100",112272,null],[112618,"2026-07-13T15:44:23",17,"/Все свободные верёвки и цепи в пределах 30 футов оживают и пытаются опутать ближайшее существо: Ловкость против Сл.",112272,null],[112619,"2026-07-13T15:44:47",7,"*Немейя стояла в оглу, ожидая подходящего момента. Она приготовила свое пламя в руках, после чего покрылась огнём вся. Как только вылезли зомби, она выпускает целый минигейзер в лицо. Сама девушка очень ярко горит и сжигает все на своем пути.*",112272,null],[112620,"2026-07-13T15:44:56",7,"/ окак",112618,null],[112621,"2026-07-13T15:46:27",7,"/ веревки могут ещё сгореть... Если я не сожгу поместье xD",112618,null],[112622,"2026-07-13T15:46:28",60,"//много тут верёвок? У меня одна точно есть",112618,null],[112623,"2026-07-13T15:46:33",7,"/ а вот цепи страшно",112272,null],[112624,"2026-07-13T15:46:35",17,"Цепь на которой висела люстра вдруг оживает и сбрасывает люстру на зомби, зашибая двоих\n\nСама же цепь, хватает за шею Немею\n\nИз угла где находится Альф верёвка будто живая набрасывается ему на шею как удавка\n\nНаверху веревка лежащая под столом резко обматывает Ирину, та кричит но крик прерывается\n\nИсмарк в шоке\n\n— ЧТО ЗА БЕСОВСТВО!?",112272,null],[112625,"2026-07-13T15:46:44",17,"/ Много много))",112622,null],[112626,"2026-07-13T15:47:05",60,"//спас ловкости, да? Не силы",112624,null],[112627,"2026-07-13T15:47:14",17,"/ Дада",112272,null],[112628,"2026-07-13T15:47:16",60,"/roll +1 могём как умеем",112272,null],[112630,"2026-07-13T15:47:21",17,"/ ОПУТАН АХАХАХАХ",112272,null],[112631,"2026-07-13T15:47:23",60,"//ага, да, бизнес",112272,null],[112632,"2026-07-13T15:47:26",31,"/roll d20+1",112272,null],[112634,"2026-07-13T15:47:33",7,"/r d20 +2",112624,null],[112636,"2026-07-13T15:47:35",17,"/ СЛ10",112272,null],[112637,"2026-07-13T15:47:53",60,"//друг калеба по кубам",112629,null],[112638,"2026-07-13T15:47:56",31,"Вывернулись))//",112272,null],[112639,"2026-07-13T15:47:57",7,"/ жаль цепи урон не получают",112272,null],[112640,"2026-07-13T15:51:45",17,"/ Твой Ход Немея",112272,null],[112641,"2026-07-13T15:51:51",17,"/ Это была заготовка",112272,null],[112642,"2026-07-13T15:52:09",7,"/ цепь не опутала",112641,null],[112643,"2026-07-13T15:52:12",7,"/ найс",112272,null],[112644,"2026-07-13T15:52:15",17,"После падения люстры только два обгоревших Зомби встают",112272,null],[112645,"2026-07-13T15:52:43",7,"/ хммм",112644,null],[112646,"2026-07-13T15:52:52",7,"/ только два зомбака осталось значит",112272,null],[112647,"2026-07-13T15:53:02",7,"/ насколько плохо выглядят?",112272,null],[112648,"2026-07-13T15:53:14",7,"/ условно на соплях держатся?",112272,null],[112649,"2026-07-13T15:53:19",17,"/ Обожженые но кажется им плевать",112272,null],[112650,"2026-07-13T15:54:06",7,"/ я подхожу поближе и тронув их, наношу урон",112272,null],[112651,"2026-07-13T15:54:12",7,"/ это свободное действие",112272,null],[112652,"2026-07-13T15:54:23",7,"/ тронуть ничего же не стоит",112272,null],[112653,"2026-07-13T15:54:37",60,"//ну так-то касание это атака, но... Я хз",112272,null],[112654,"2026-07-13T15:54:40",17,"/ Не погоди кинь своё позорное ХБ сюда",112272,null],[112655,"2026-07-13T15:54:42",17,"/ Я решу",112272,null],[112656,"2026-07-13T15:54:48",7,"/ смари",112272,null],[112657,"2026-07-13T15:55:08",17,"/ Касание это атака 100% еще блять коснись зомби",112272,null],[112658,"2026-07-13T15:55:58",7,"Ну тоесть условно я хоть на них прям иду в лоб",112272,null],[112659,"2026-07-13T15:56:56",17,"/ Кароче тут по вордингу. Касаешься ты, так что не",112272,null],[112660,"2026-07-13T15:57:04",7,"/ ну как скажешь",112659,null],[112661,"2026-07-13T15:57:05",17,"/ Должно касаться существо, например сделать захват",112272,null],[112662,"2026-07-13T15:57:12",7,"/ ну или удар",112661,null],[112663,"2026-07-13T15:57:39",7,"/ тогда я сюравно подхожу и наношу 2д4 +4 урона огнем ( Пламя Флегетоса все еще вроде работает )",112272,null],[112664,"2026-07-13T15:58:15",7,"/да работает, до конца следующего хода",112272,null],[112665,"2026-07-13T15:58:21",7,"/r 2d4 +4 огонь",112272,null],[112667,"2026-07-13T15:58:27",7,"/ перекид",112272,null],[112669,"2026-07-13T15:58:40",7,"/ 12 урона огнем всем ближайшим",112272,null],[112670,"2026-07-13T15:58:43",17,"Оба зомби сгорают в синем пламени",112272,null],[112671,"2026-07-13T15:59:23",7,"/ итак, кто еще вблизи естью",112272,null],[112672,"2026-07-13T15:59:45",17,"/Нет",112671,null],[112673,"2026-07-13T15:59:45",7,"/ снаружи волки за окнами?",112272,null],[112674,"2026-07-13T16:00:07",17,"/ Да Вторая группа зомби ломяться в окна и волки по ним прыгают на второй этаж",112272,null],[112675,"2026-07-13T16:02:11",17,"Улица выводит Ридли к двухэтажному дому за почерневшей каменной оградой. Окна закрыты досками, крыша местами провалилась, входная дверь выбита\n\nВо дворе движутся мертвецы. Один наваливается плечом заколоченное окно, двое скребут ставни, оставляя на дереве тёмные полосы. Между ними рыщут волки с мокрой свалявшейся шерстью. Они бросаются на дом, такого ты не видел, волки осаждают это строение.\n\nВнутри слышны звуки боя и крики, ты заметил вспышку синего пламени.\n\nВ кармане Ридли лежит письмо Колуна Индировича.. Под одеждой холодеет знак Багрового Савана — металлический медальон, обёрнутый красной нитью.\n\nТы слышишь шорохи из за угла дома рядом, видишь как еще мертвецы стягиваются медленно плетясь к этому зданию.\n\nЧто ты будешь делать?",112272,null],[112676,"2026-07-13T16:02:18",7,"/ так меня зовут, но я подхожу к окну где ломятся мертвецы и в радиусе 5 футов от меня получают 12 урона, а также кастую прям на баррикаду огненные ладони",112674,null],[112677,"2026-07-13T16:02:32",7,"/ спас ловкости",112272,null],[112678,"2026-07-13T16:02:32",17,"/Hard",112675,null],[112679,"2026-07-13T16:02:51",17,"/ Нет не получают блокируют доски",112676,null],[112680,"2026-07-13T16:03:09",7,"/ а доски не сгорят получив 12 урона?",112679,null],[112681,"2026-07-13T16:03:16",17,"/ Пламя флегестоса раскажи че это, огненые ладони улучшеные или как?",112272,null],[112682,"2026-07-13T16:03:16",7,"/ тогда подожду когда сами сломают",112272,null],[112684,"2026-07-13T16:03:58",7,"/ перекид 1 на уровне с заклинаний и д4 ближайшим существам",112272,null],[112685,"2026-07-13T16:04:16",17,"/ Если попадают атакой",112272,null],[112686,"2026-07-13T16:04:20",17,"/ Че ты мне лечишь",112272,null],[112687,"2026-07-13T16:04:40",17,"/ Если не попадают не получают",112272,null],[112688,"2026-07-13T16:04:48",7,"/ окак",112685,null],[112689,"2026-07-13T16:04:53",7,"/ ну буду знать",112686,null],[112690,"2026-07-13T16:04:55",17,"/ Бля я в ахуе",112272,null],[112691,"2026-07-13T16:04:57",7,"/ тогда 8 урона",112272,null],[112692,"2026-07-13T16:05:07",17,"/ Зомби сгорели авансом, считаем что потратил огненые ладони",112272,null],[112693,"2026-07-13T16:05:15",17,"/ Да откуда",112691,null],[112694,"2026-07-13T16:05:18",7,"/ ну там и стою",112272,null],[112695,"2026-07-13T16:05:56",7,"/ а, забей",112690,null],[112696,"2026-07-13T16:06:02",7,"/ позже опишу",112272,null],[112697,"2026-07-13T16:06:53",17,"Исмарк бросается к Ирине и режет веревку которая её хищно опутывает",112272,null],[112698,"2026-07-13T16:06:58",17,"/Тарх",112272,null],[112699,"2026-07-13T16:07:17",31,"К нам уже залезли или только рвутся?/",112272,null],[112700,"2026-07-13T16:07:34",17,"Волк ударился мордой и спрыгнул, враги внизу",112272,null],[112701,"2026-07-13T16:08:04",31,"То есть тут в комнате никого?/",112272,null],[112702,"2026-07-13T16:08:11",31,"Кроме нас троих?/",112272,null],[112703,"2026-07-13T16:09:02",17,"Нет",112272,null],[112704,"2026-07-13T16:09:54",9,"//О, уже? Чё так резко, ну сейчас",112678,null],[112705,"2026-07-13T16:10:43",31,"Подбегаю к окну, выглядываю, не лезет ли кто, или может под окном торчит?",112272,null],[112706,"2026-07-13T16:11:57",17,"Лезет волк",112705,null],[112707,"2026-07-13T16:12:39",31,"/roll d20+1 херачу ему в морду вилами со словами пшел нах морда шерстяная",112706,null],[112709,"2026-07-13T16:13:00",17,"Но промахиваешься, волк отпрянул назад и ты не достал его",112272,null],[112710,"2026-07-13T16:13:48",31,"У меня ксть черта матчер древкового оружия, могу дотянуться до него ручкой вил?/",112709,null],[112712,"2026-07-13T16:14:25",9,"— Кажется у кого-то проблемы. — *Цепи соскользнула с предплечья на запястья. Нежить скореевсего тянется к живым и им надо помочь, вот толтко воевать снаружи... плохая идея, внутри можно забарикадироваться. Бежит в выбитую дверь коли туда никто не ломится, значит и попасть внутрь будет легче.*",112675,null],[112713,"2026-07-13T16:14:35",17,"Да",112710,null],[112714,"2026-07-13T16:15:07",31,"/roll d20+1 разворачиваю вилы и обратным хватом бью по башке волку",112713,null],[112716,"2026-07-13T16:15:08",17,"Внизу вы видите как в дверь забегает парень в странной маске и цепях",112272,null],[112717,"2026-07-13T16:15:40",31,"По волку два раза мимо, мля.//",112272,null],[112718,"2026-07-13T16:15:43",17,"/Кидай инициативу Ридли",112272,null],[112719,"2026-07-13T16:15:43",31,"Ход//",112272,null],[112721,"2026-07-13T16:16:35",9,"— Живы? У двери пока никого нет, лучше убежать. Снаружи огромная толпа. — *Он сразу же высказал что думает о ситуации.*",112272,null],[112722,"2026-07-13T16:16:48",9,"/roll 1d20 иня",112272,null],[112724,"2026-07-13T16:17:42",17,"Группа зомби выносит окно",112272,null],[112725,"2026-07-13T16:17:49",17,"/r 4d8+4",112272,null],[112727,"2026-07-13T16:18:16",17,"И лезут в окно\n\nЧетверо Зомби попадают в помещение",112272,null],[112728,"2026-07-13T16:18:20",17,"/Ридли ходи",112272,null],[112729,"2026-07-13T16:19:21",9,"*Смотрит мгновение на ситуацию внутри.*\n\n//Хотя бы скажи + - кто тут и насколько большая комната, там раздуплимся",112272,null],[112730,"2026-07-13T16:20:27",17,"/ Комната приличная 15х20, часть занимает лестница\n\nВнутри 4 Зомби\n\nСнаружи еще 4 Волка\n\nТы видел как к дому тянутся еще зомби но они пока не добрались",112272,null],[112731,"2026-07-13T16:20:49",9,"*Ридли, член какого-то культа или колдун не понятно. Но вродь нормальный малый, с варваром (имя забыл) уже немного знаком.*",112272,null],[112732,"2026-07-13T16:22:14",9,"*Облик парня становится жутким, немного неестественным, конечности немного вытянулись и стали бледнее, теперь не срываясь под подолами мантии.*",112272,null],[112733,"2026-07-13T16:22:25",9,"/roll 1d10 временные от ужасающего",112272,null],[112735,"2026-07-13T16:22:52",9,"/roll 1d20+3 подойду и ударю зомби, опишу по результату",112272,null],[112737,"2026-07-13T16:23:10",17,"/ А попал у зомби 8кд",112272,null],[112738,"2026-07-13T16:23:43",9,"*Ридли тут же двинулся на монстров и смазал ближайшему по голове кулаком обмотанным цепями.*",112272,null],[112739,"2026-07-13T16:23:59",9,"/roll 1d4+2 урон дробящий",112272,null],[112741,"2026-07-13T16:24:05",9,"//Ход",112272,null],[112742,"2026-07-13T16:24:33",9,"//Ну, или спас мудрости сл 11 если у зомби нет имуна от испуга ужасного облика",112272,null],[112743,"2026-07-13T16:25:04",9,"//Забыл, 1 огнём ещё от сосуда",112740,null],[112744,"2026-07-13T16:25:39",17,"Один Волк Запрыгивает через левое окно и кусает Альфа\n\nЕще три волка запрыгивают справой стороны через окно, один вгрызается в Немею, еще два игнорируя всех пробегаю к лестнице\n\n/Можно Дать Провоцирку от варвара, Ридли и Тифлингши",112272,null],[112745,"2026-07-13T16:26:00",7,"/ + ур колдуна",112734,null],[112746,"2026-07-13T16:26:22",9,"//Неа, он обыватель, +0 уровня колдуна)",112745,null],[112747,"2026-07-13T16:26:40",7,"/r d20 +4 кинжалом в дых",112744,null],[112749,"2026-07-13T16:26:45",31,"Обыватель создан для страдания))//",112746,null],[112750,"2026-07-13T16:26:52",7,"/r d4 +2",112748,null],[112752,"2026-07-13T16:27:12",7,"/ считается ли это касанием, хз",112751,null],[112753,"2026-07-13T16:27:18",17,"/r +4 Ам по Варвару +d20+4 Ам по Немее",112272,null],[112755,"2026-07-13T16:27:32",7,"/ опа",112754,null],[112756,"2026-07-13T16:27:40",7,"/ ну попал",112272,null],[112757,"2026-07-13T16:27:50",9,"//Могу провоцированную?",112744,null],[112758,"2026-07-13T16:27:59",60,"//я сделал самое очевидное имя.. Альфа. Рий.😁",112731,null],[112759,"2026-07-13T16:28:02",9,"/roll 1d20+3 провоцирка",112272,null],[112761,"2026-07-13T16:28:12",17,"/r 2d4+2 Альфу 2d4+2 Немее",112272,null],[112763,"2026-07-13T16:28:32",9,"/roll 1d4+2+1 одиничка огнём а то дробящий и спас мудрости от испуга опять",112272,null],[112765,"2026-07-13T16:28:41",7,"/ он выполнил условия для Пламя флегетоса и сам меня коснулся",112762,null],[112767,"2026-07-13T16:29:06",60,"/roll -d20+5 отпусти меня паскудная верёвка, не мешай мне гэмблить!",112744,null],[112770,"2026-07-13T16:29:34",60,"//половиню яростью вроде",112762,null],[112771,"2026-07-13T16:29:37",7,"/r d4 +4 +4",112272,null],[112773,"2026-07-13T16:29:45",7,"/перекид единицы",112272,null],[112774,"2026-07-13T16:29:48",7,"/r d4",112272,null],[112776,"2026-07-13T16:29:56",7,"/ 12 урона огнем",112272,null],[112777,"2026-07-13T16:30:10",7,"/ перечитал, память освежил, косяков больше нет",112272,null],[112778,"2026-07-13T16:30:22",7,"/ за прошлые извиняюсь, я щас как белка в колесе",112272,null],[112779,"2026-07-13T16:30:31",60,"//а звучит-то мощно",112772,null],[112780,"2026-07-13T16:32:00",17,"Волк сгорает заживо после укуса Немеи в синем пламени",112776,null],[112781,"2026-07-13T16:32:39",60,"//зомби с 8 кд вкуснота, конечно, но мне надо веревочку содрать, напрягает",112272,null],[112782,"2026-07-13T16:33:03",60,"//чей ход?",112272,null],[112783,"2026-07-13T16:33:12",7,"/ угу",112779,null],[112784,"2026-07-13T16:35:41",17,"/ Твой ход",112272,null],[112786,"2026-07-13T16:36:03",17,"На лестнице два волка прорвались на второй этаж\n\n— Останови их парень!",112272,null],[112788,"2026-07-13T16:36:10",60,"Массивный фирболг вдруг оказывается связан какой-то обыкновенной верёвкой, что его невероятно напрягает. Он хочет разорвать ее, но хочет так же и прибить тех, кто всё это устроил, не понимая, что дело в магии",112272,null],[112789,"2026-07-13T16:36:47",60,"//Я чё могу, значца, а ничего. Могу чек силы на освобождение забубенить?",112272,null],[112790,"2026-07-13T16:37:03",17,"/ Действием разрезать веревку",112272,null],[112791,"2026-07-13T16:38:39",60,"Альфарий моментально напрягается, разрывая верёвку на себе, и мчится наверх, чтобы не позволить прибить главную цель. Будучи той ещё махиной, он буквально прижимает Ирину к углу, где нет окон, и встаёт в оборонительную\n\n—Тут мяса свежего нет, всё сгнило, ищите в другом месте!\n\n//Веревку порвал, наверх убежал, продлил ярость, ход закончил",112790,null],[112792,"2026-07-13T16:39:39",60,"//если что-то провоцирую, то пожалуйста, лупите варвару лицо",112272,null],[112793,"2026-07-13T16:41:18",60,"//И да, поскольку альф фирболг, его слова понимают животные. И растения... Но я их — нет",112791,null],[112794,"2026-07-13T16:41:36",17,"/r +4 Волк +4 Зомби лупят варвару по жопе",112792,null],[112796,"2026-07-13T16:41:47",17,"/r 4d4+2 КУСЬ ЗА ЖОПУ",112272,null],[112798,"2026-07-13T16:42:58",31,"И нету больше жопы//",112797,null],[112799,"2026-07-13T16:43:00",9,"*Взгляд перемещается на волков, живыели они? Или тоже зомби. Живые должны испугаться его облика...*",112272,null],[112800,"2026-07-13T16:43:46",7,"/ фраза жопа отпадет обрела буквальный смысл бытия",112798,null],[112801,"2026-07-13T16:43:47",17,"/ Ты догнал волков, вы у лестницы сверху",112791,null],[112804,"2026-07-13T16:45:04",17,"/Немея получается ход",112272,null],[112808,"2026-07-13T16:46:01",7,"/ итак. Два волка остались, зомби один",112272,null],[112810,"2026-07-13T16:49:01",7,"/ тэкс огненный снаряд и остается создать",112272,null],[112811,"2026-07-13T16:49:28",7,"/ в кучке никого нет, велик шанс задеть Альфа",112272,null],[112812,"2026-07-13T16:49:37",60,"//а мне крит?",112795,null],[112813,"2026-07-13T16:49:40",7,"/ и потерять ячейку",112272,null],[112814,"2026-07-13T16:49:46",7,"/ да, по тебе",112812,null],[112815,"2026-07-13T16:49:55",17,"/Тут тебе крит",112796,null],[112816,"2026-07-13T16:49:57",60,"//я понял",112814,null],[112817,"2026-07-13T16:50:02",60,"//я говорю, что тоже крит хочу",112272,null],[112818,"2026-07-13T16:50:33",17,"/Внизу 1 волк он был около варвара и еще 4 Зомбича",112810,null],[112819,"2026-07-13T16:50:40",17,"/Два волка наверху",112272,null],[112820,"2026-07-13T16:51:09",60,"//Тяжело, но я ещё живой",112272,null],[112822,"2026-07-13T16:52:23",7,"/ значит бегу мимо волка не провоцируя от него атак и я хочу сжечь 4 зомби.\nТакже интересно, поместье горит в огне? Просто огненные ладони массовая атака и я буквально горю",112815,null],[112824,"2026-07-13T16:53:18",17,"Нет твой синий огонь не поджигает поместье",112272,null],[112825,"2026-07-13T16:53:31",17,"/r -1 Спас ловкости",112272,null],[112827,"2026-07-13T16:53:37",17,"/ Еще спас кидает Ридли",112272,null],[112828,"2026-07-13T16:53:41",7,"/ везет как обычно",112826,null],[112830,"2026-07-13T16:53:45",9,"//у меня цепи тож слегка огнём искрятся, ничё страшного, просто у зомби минирование и ожоги в форме цепей",112822,null],[112832,"2026-07-13T16:53:59",9,"/roll 1d20 ловкость с бонусом ноль",112272,null],[112834,"2026-07-13T16:54:17",60,"//у альфа только пукан пока искрится",112830,null],[112835,"2026-07-13T16:54:18",7,"/r 3d6 +4",112272,null],[112837,"2026-07-13T16:54:25",7,"/ 6 по зомбакам",112272,null],[112838,"2026-07-13T16:54:29",9,"//Это урон?",112272,null],[112839,"2026-07-13T16:54:37",17,"/ Да урон огнём тебе",112272,null],[112841,"2026-07-13T16:54:42",7,"/ да, огненные ладони",112838,null],[112842,"2026-07-13T16:54:45",17,"/ Тебя сожгла тифлингша",112272,null],[112843,"2026-07-13T16:54:52",17,"/ Ты забыл крикнкуть \" Я СВОЙ\"",112272,null],[112844,"2026-07-13T16:54:56",31,"Вот и помер Ридли//",112272,null],[112845,"2026-07-13T16:55:00",9,"//Временные минус и еще треть хитов в придачу",112272,null],[112847,"2026-07-13T16:55:12",9,"//Временные спасли",112272,null],[112849,"2026-07-13T16:55:26",7,"/ свой горит, чужой\nНеважно. Важно, что горит",112843,null],[112850,"2026-07-13T16:55:46",17,"Зомби сильно обгорели но ни один из них не упал. Бедняга Ридли, обожженый тоже стоит",112272,null],[112853,"2026-07-13T16:56:31",17,"Исмарк наверху бежит к Лестнице и не даёт Волкам так легко пройти к Ирине\n\nНаносит укол волку",112272,null],[112855,"2026-07-13T16:56:37",9,"//Ээээ. Я то в отключке, когда. Червонец бы точно, а этот хер выключится если только его убить)",112272,null],[112856,"2026-07-13T16:56:44",17,"/r +4 Ныа",112272,null],[112859,"2026-07-13T16:56:57",9,"//еще 8 хитов есть",112272,null],[112860,"2026-07-13T16:57:05",17,"/r 2d6+3 Туда",112272,null],[112862,"2026-07-13T16:57:13",17,"/А сколько у тебя хитов я думал мало",112855,null],[112863,"2026-07-13T16:57:30",9,"// Был0 12 и 9 временных",112272,null],[112864,"2026-07-13T16:57:44",60,"//нежить колдун",112863,null],[112865,"2026-07-13T16:58:01",17,"/ Про временные не знал, да и когда они",112863,null],[112866,"2026-07-13T16:58:27",17,"/Тарх ходи",112272,null],[112867,"2026-07-13T16:58:28",7,"/ вот здесь",112734,null],[112868,"2026-07-13T16:58:30",9,"//Минуту держаться, а так 2 хода прошло всего, я вошёл в ужасный облик",112272,null],[112869,"2026-07-13T16:58:32",60,".",112734,null],[112870,"2026-07-13T16:58:38",17,"Одного волка Исмарк сильно проколол в морду",112272,null],[112871,"2026-07-13T16:58:57",17,"/Я заменил описание ты стоишь",112868,null],[112872,"2026-07-13T16:58:59",60,"//тыкать надо до конца",112870,null],[112873,"2026-07-13T16:59:19",31,"/roll d20+1 бью того же волка вилами",112870,null],[112875,"2026-07-13T16:59:26",9,"//У меня как у обывателя пародия на сосуд гения начальная и вот фишка нежити с чертой дрочуна, но и усё",112272,null],[112876,"2026-07-13T16:59:33",31,"/roll d6+1",112272,null],[112878,"2026-07-13T16:59:43",60,"//чисто я",112875,null],[112879,"2026-07-13T17:00:02",31,"Волчара сдох? Второго могу бонусным действием древком огреть?/",112272,null],[112880,"2026-07-13T17:00:40",60,"//вот будет у меня безрассудка, тогда не надо будет мучаться с инвизом..",112272,null],[112883,"2026-07-13T17:02:02",17,"Да, раненый волк погиб",112879,null],[112884,"2026-07-13T17:02:09",17,"/ Да, можешь",112879,null],[112886,"2026-07-13T17:02:19",31,"/roll d20+1",112272,null],[112888,"2026-07-13T17:02:32",31,"Древко пролетаем мимо второго волка",112272,null],[112889,"2026-07-13T17:02:36",31,"/ход",112272,null],[112890,"2026-07-13T17:03:01",60,"//сейчас будет тык от колдунчика",112272,null],[112891,"2026-07-13T17:03:11",60,"//сколько ещё видимых целей осталось?",112272,null],[112892,"2026-07-13T17:04:48",17,"/ Ридли \n\nВнизу 4 обгоревших зомби сверху 1 волк",112272,null],[112893,"2026-07-13T17:05:02",9,"//Тоесть я сверху?",112272,null],[112894,"2026-07-13T17:07:01",60,"//ну звездец ауфчику\nНадеюсь",112892,null],[112895,"2026-07-13T17:08:04",9,"/roll 1d20+3 по волку бом он же рядом надеюсь я вродь сверху был",112272,null],[112897,"2026-07-13T17:08:15",9,"//Ну, не бом",112272,null],[112898,"2026-07-13T17:08:36",60,"//он вроде окружен, если ты тоже сверху. Ибо он хотел съесть Ирину, а я ее прикрыл",112272,null],[112899,"2026-07-13T17:08:37",9,"//Хотя можно было бы окружить, но я хз что где когда поэтому без",112272,null],[112900,"2026-07-13T17:08:45",17,"/Нет ты снизу где 4 зомби тебя же жгли только что вместе с ними",112893,null],[112901,"2026-07-13T17:08:52",17,"/По зомби попал",112272,null],[112902,"2026-07-13T17:09:11",9,"/roll 1d4+2+1 одиничка огнём и дробящий зомби",112272,null],[112904,"2026-07-13T17:09:50",9,"/roll 1d20+2 захват бонусным если живы зомби потому что могу",112272,null],[112906,"2026-07-13T17:09:51",17,"Зомби пал к твоим ногам",112272,null],[112907,"2026-07-13T17:09:58",9,"//Умер?",112272,null],[112908,"2026-07-13T17:10:01",17,"/Да",112272,null],[112909,"2026-07-13T17:10:53",9,"*Просто вырубает рандомного зомби с удара. Смотрит кто рядом с ним из врагов.*\n\n//Могу ли отойти без провоцирки смотрю",112272,null],[112910,"2026-07-13T17:10:54",60,"//если волчок ща опять мне крит всадит, варвару гг",112272,null],[112911,"2026-07-13T17:12:36",7,"/ или нет :)",112910,null],[112912,"2026-07-13T17:12:55",60,"//ну... Он должен быть 14 на кубах урона, чтоб меня снесло",112911,null],[112913,"2026-07-13T17:13:06",60,"//для 4д4+2 это выполнимо, в целом",112272,null],[112914,"2026-07-13T17:13:45",17,"/неа три провоцирки",112909,null],[112915,"2026-07-13T17:14:25",9,"*Стоит и сверлит зомби багровыми пронизывающими глазами из под маски.*\n\n//Ход",112272,null],[112916,"2026-07-13T17:14:51",60,"//ну давай давай нападай!",112272,null],[112917,"2026-07-13T17:15:10",17,"Три зомби внизу атакуют Ридли и Немею\n\nОдин по тифлингу и двое на Ридли, один его пытается схватить, а второй вгрызается в шею",112272,null],[112918,"2026-07-13T17:15:11",9,"//Если ьы щнал другое сделал. Мне снесли хп много, надо было свалить. Я мог 🫠",112272,null],[112919,"2026-07-13T17:15:45",17,"/r +3 Захват",112272,null],[112920,"2026-07-13T17:15:46",9,"/roll 1d20+2 атлетика чтобы не схватил гад",112272,null],[112923,"2026-07-13T17:15:56",17,"Ты схвачен",112272,null],[112924,"2026-07-13T17:16:15",17,"/r +d20+3 Удар зомби по Ридли +3 Удар по Немее",112272,null],[112926,"2026-07-13T17:16:35",17,"/r d8+1 Ныа Дробящий",112272,null],[112928,"2026-07-13T17:16:40",9,"//По мне с преимуществом потому что окружон?",112272,null],[112929,"2026-07-13T17:18:07",7,"/ он меня тронул?:)",112925,null],[112930,"2026-07-13T17:18:08",17,"/ Нет потому что тебя хватили",112928,null],[112931,"2026-07-13T17:18:12",7,"/ кд 12",112272,null],[112932,"2026-07-13T17:18:19",60,"Захват не дает преимущества",112930,null],[112933,"2026-07-13T17:18:24",17,"/Да тронул пусть",112929,null],[112934,"2026-07-13T17:18:25",60,"//эт не опутывание",112272,null],[112935,"2026-07-13T17:18:31",7,"/ ( Николай: да как же ты зае )",112929,null],[112936,"2026-07-13T17:18:37",17,"/Ну блять он обошел его сзади окружил",112932,null],[112937,"2026-07-13T17:18:42",17,"/ Че вы доебались до мастера",112272,null],[112938,"2026-07-13T17:18:45",7,"/4 урона огнём",112933,null],[112939,"2026-07-13T17:19:17",60,"//я планировал собирать альфа через захваты и урон от хватки. Если захват будет давать преимущество, то этим будет пользоваться варвар",112937,null],[112940,"2026-07-13T17:19:25",17,"Стёкла на втором этаже окончательно выбивают нетопыри. Огромные летучие мыши.",112272,null],[112941,"2026-07-13T17:19:43",17,"На улице в воздухе тучи летучих мышей",112272,null],[112942,"2026-07-13T17:19:44",60,"//а ведь можно хватать и тащить к тиммейту, чтоб окружать..",112939,null],[112943,"2026-07-13T17:19:49",7,"/ сколько раундов прошло?",112272,null],[112944,"2026-07-13T17:19:56",17,"Группа зомби вваливается в помещение через дверь еще четыре трупа позади Ридли",112272,null],[112945,"2026-07-13T17:19:59",17,"Кажется это конец",112272,null],[112946,"2026-07-13T17:19:59",60,"//ну здрасьте",112940,null],[112947,"2026-07-13T17:20:38",17,"Ирина Вскрикивает зажмуривается и опустив голову молится перебирая четки в углу",112272,null],[112948,"2026-07-13T17:21:04",17,"Исмарк Оборачивается и руки его опускаются\n\n— Графа не остановить...",112272,null],[112949,"2026-07-13T17:21:31",17,"В этот момент волк вгрызается в Тарха",112272,null],[112950,"2026-07-13T17:21:37",17,"/r +4 Ам",112272,null],[112952,"2026-07-13T17:21:57",60,"//давать дёру от волков подавно не вариант. Нетопыри.. Хз, тем более летают",112272,null],[112953,"2026-07-13T17:22:13",17,"/r +4 Нетопыри +2 Летучие мыши -1 Зомби3",112272,null],[112955,"2026-07-13T17:22:50",7,"/ ощущение, что еще какая нибудь шняга выпадет и мы должны потом пойти за Ириной",112272,null],[112956,"2026-07-13T17:23:15",60,"//сейчас будет сюжетный взрыв или чье-то героическое самопожертвование",112955,null],[112957,"2026-07-13T17:23:25",60,"//как хорошо, что я не успел поиграть в страда до этого",112272,null],[112958,"2026-07-13T17:23:47",17,"/ Ждем врыва, терпим",112272,null],[112959,"2026-07-13T17:23:57",60,"//мне ходить?",112958,null],[112960,"2026-07-13T17:24:01",17,"/Да",112272,null],[112961,"2026-07-13T17:24:10",17,"/Тарх 14 попал?",112951,null],[112962,"2026-07-13T17:24:25",60,"//рядом с волком есть еще какая-нибудь херь? Ну мышь например в радиусе мой атаки",112960,null],[112963,"2026-07-13T17:24:30",17,"Нет",112272,null],[112964,"2026-07-13T17:24:39",60,"//а если подойду поближе?",112272,null],[112965,"2026-07-13T17:24:45",60,"//на пару шагов",112272,null],[112966,"2026-07-13T17:25:40",60,"//надо задеть побольше, шанс попасть маловат, чтоб соло тыкать",112272,null],[112967,"2026-07-13T17:26:01",17,"//Зомби внизу. Нетопыри на другом конце у тела Бургомистра там где Ирина, в окнах. Мыши подлетят после твоего хода и начнут лезть из всех щелей",112272,null],[112968,"2026-07-13T17:26:15",60,"//говново",112967,null],[112969,"2026-07-13T17:26:21",60,"//тогда тык волчонка",112272,null],[112970,"2026-07-13T17:26:34",60,"/r +5 он вроде был раненый, должно хватить",112272,null],[112972,"2026-07-13T17:26:45",60,"/roll 2d6+3+d4",112272,null],[112974,"2026-07-13T17:26:48",7,"/ я пролететь в второй этаж смогу? Или туда только лестница ведет нету вида с 1 этажа на второй",112967,null],[112975,"2026-07-13T17:27:00",31,"Сколько он откусил то?/",112951,null],[112976,"2026-07-13T17:27:14",9,"//Возле меня кто-то из союзников есть?)",112272,null],[112977,"2026-07-13T17:28:12",60,"Альф впадает в раш. Он громко бухтит на своём, неистово размахивая мечом\n\n—А НУ СВАЛИЛИ ОТСЮДА, СУКИ УШАСТЫЕ!! А-А-А-А-А, ВАШУ МАТЬ!\n\nВарвар несётся прямо на летучих мышей, пытаясь в тупую прибить их мечом к полу",112272,null],[112978,"2026-07-13T17:28:24",60,"/roll d20 гэмблинг",112272,null],[112980,"2026-07-13T17:28:33",9,"//Я вижу николай очень любит окружение даже если враги неразумны. Но лан. Живём",112272,null],[112981,"2026-07-13T17:28:38",60,"/roll d6+d4+13 бам обоим сразу",112272,null],[112983,"2026-07-13T17:28:51",60,"//потому что говно механика",112980,null],[112984,"2026-07-13T17:29:06",60,"//Ее надо либо юзать всем, либо не юзать вообще",112272,null],[112985,"2026-07-13T17:29:22",60,"//те же волки имеют тактику стаи. А тут окружение. То же самое почти, смысла не имеет",112272,null],[112986,"2026-07-13T17:29:35",60,"//надеюсь двоих прикончил и волка тоже",112982,null],[112987,"2026-07-13T17:29:53",60,"//вторая атака ес что бонуской от мастера большого оружия",112272,null],[112988,"2026-07-13T17:30:03",9,"//Я ток разумными врагами юзаю окружение игроков, а они пусть сами как хотя все равно монстры сильнее",112272,null],[112989,"2026-07-13T17:30:25",60,"//пофиг, гэмблим",112272,null],[112990,"2026-07-13T17:34:32",17,"/r 2d4+2",112975,null],[112992,"2026-07-13T17:35:09",17,"/А кому обоим, там 1 волк",112981,null],[112993,"2026-07-13T17:35:21",60,"//я убил волка, побежал к мышам",112992,null],[112994,"2026-07-13T17:35:33",17,"/Значит зомби разумные, вообще страновато что волки вместе с зомби штурмуют какой то дом",112988,null],[112995,"2026-07-13T17:35:36",60,"15 по укушенному волку",112973,null],[112996,"2026-07-13T17:35:39",17,"/ Возможно ими кто то управляет",112272,null],[112997,"2026-07-13T17:35:49",60,"//да быть не может",112996,null],[112998,"2026-07-13T17:35:56",60,"//это просто предвыборная кампания",112272,null],[113000,"2026-07-13T17:36:20",17,"/ Такс че там за второй удар",112272,null],[113001,"2026-07-13T17:36:24",17,"/ Волк погиб",112272,null],[113002,"2026-07-13T17:36:28",60,"//мастер большого оружия",113000,null],[113003,"2026-07-13T17:36:33",60,"//опустил хиты волка до 0",112272,null],[113004,"2026-07-13T17:36:36",17,"/Что это",112978,null],[113005,"2026-07-13T17:36:46",60,"//поэтому могу бонуской сделать еще тык",112272,null],[113006,"2026-07-13T17:36:53",17,"/ Ну ок, только по кому?",112272,null],[113007,"2026-07-13T17:37:07",60,"//по мышам, которые на другом конце второго этажа",113006,null],[113008,"2026-07-13T17:37:13",60,"//или мне скорости не хватит?",112272,null],[113009,"2026-07-13T17:37:44",60,"//Ссанный мидгард",112272,null],[113010,"2026-07-13T17:37:54",60,"//варвар с даблтаргетом на 1 уровне",112272,null],[113011,"2026-07-13T17:38:07",17,"/Хватило по нетопырю но он живой еле еле",112272,null],[113012,"2026-07-13T17:38:21",60,"//жирные типы",113011,null],[113013,"2026-07-13T17:38:24",60,"//конец хода",112272,null],[113014,"2026-07-13T17:39:07",17,"В помещения влетает рой летучих мышей снизу и все они набрасываются на Ридли которого держит зомби",112272,null],[113015,"2026-07-13T17:39:13",17,"/r +4 Hjq",112272,null],[113017,"2026-07-13T17:39:45",17,"Еще один рой влетает сверху и кусают Варвара",112272,null],[113018,"2026-07-13T17:39:50",17,"/r +4",112272,null],[113020,"2026-07-13T17:40:05",17,"/r 2d4 Колющий",112272,null],[113023,"2026-07-13T17:40:28",17,"И еще рой на Немею влетает",112272,null],[113024,"2026-07-13T17:40:31",17,"/r +4",112272,null],[113026,"2026-07-13T17:40:37",17,"/r 2d4",112272,null],[113028,"2026-07-13T17:41:17",31,"Походу, тут все и ляжем//",112272,null],[113031,"2026-07-13T17:43:52",60,"//ща будет сюжетный твист",113028,null],[113032,"2026-07-13T17:43:54",60,"//или...",112272,null],[113033,"2026-07-13T17:43:58",60,"//а что если...",112272,null],[113035,"2026-07-13T17:44:05",60,"//Коля решил нас просто загасить",112272,null],[113036,"2026-07-13T17:44:05",9,"//Ровно мой кд",113016,null],[113038,"2026-07-13T17:44:54",60,"//ща нас вырубят и проснёмся в тюряге",112272,null],[113039,"2026-07-13T17:45:01",9,"//Мне нарится, так обычно и помирают герои",113035,null],[113040,"2026-07-13T17:45:15",60,"//дома у одного старого любителя понаблюдать",113038,null],[113041,"2026-07-13T17:46:04",9,"//Пох даж если без трусов оставят, всё важное при мне.",113038,null],[113043,"2026-07-13T17:50:51",17,"/Ход Немея",112272,null],[113044,"2026-07-13T17:51:13",17,"Исмарк Рубит нетопыря наверху\n\n— ПОГАНАЯ ТВАРЬ, СГИНЬ!",112272,null],[113045,"2026-07-13T17:51:20",17,"/r +5 Исмарк даёт жару",112272,null],[113047,"2026-07-13T17:51:24",17,"/Не даёт",112272,null],[113048,"2026-07-13T17:51:32",17,"Но Промахивается по еле живому Нетопырю",112272,null],[113049,"2026-07-13T17:51:38",17,"Закрывает собой сестру",112272,null],[113050,"2026-07-13T17:51:52",17,"/@Evreiskui_Department",112272,null],[113102,"2026-07-13T18:14:17",60,"//посменно работаем",113049,null],[113105,"2026-07-13T18:14:54",31,"Он там в одного всех вынесет, зачем нас звал вообще?/",113102,null],[113107,"2026-07-13T18:15:01",60,"//ща покусаем",113102,null],[113113,"2026-07-13T18:15:50",31,"Вроде писали что играем до 17-00 по Москве? Я так понимаю продолжения завтра будет?//",112272,null],[113117,"2026-07-13T18:16:15",60,"//ну наверное, поглядим",113113,null],[113119,"2026-07-13T18:16:35",31,"Ну я могу до 20 по Москве//",112272,null],[113128,"2026-07-13T18:19:11",17,"/ Я иногда буду писать",112272,null],[113129,"2026-07-13T18:19:15",17,"/ Департа ход",112272,null],[113131,"2026-07-13T18:19:21",17,"/ Он вола ебет",112272,null],[113133,"2026-07-13T18:19:30",9,"//Я в 0 лежу скорей всего, мыши попали если там урон не 1",112272,null],[113134,"2026-07-13T18:19:42",17,"/ @Evreiskui_Department солнце ещё высоко!",112272,null],[113135,"2026-07-13T18:19:46",31,"У меня 6 ХП))/",112272,null],[113136,"2026-07-13T18:19:52",17,"/r 2d4 По ридли",112272,null],[113138,"2026-07-13T18:20:06",9,"//-5 в итоге",112272,null],[113140,"2026-07-13T18:20:21",31,"Если выживу, подниму, у меня есть набор лекаря//",112272,null],[113142,"2026-07-13T18:21:06",9,"*Теряет сознание от потери крови. Конечности втягиваются обратно, он кажется меньше и не таким страшным и внушительны как обычно. Конечно, под саванном все ещё молодой парень.*",112272,null],[113150,"2026-07-13T18:24:07",7,"/ простите братья славяне",112272,null],[113152,"2026-07-13T18:24:18",7,"/ инет пропал",112272,null],[113153,"2026-07-13T18:24:27",7,"/ щас момент",112272,null],[113157,"2026-07-13T18:25:20",7,"/  не пали",113131,null],[113162,"2026-07-13T18:25:53",7,"/ и вообще я с тобой секретом поделился",112272,null],[113163,"2026-07-13T18:25:57",31,"//стоило один раз выебать вола...",112272,null],[113164,"2026-07-13T18:26:05",7,"/ рекомендую",113163,null],[113170,"2026-07-13T18:27:02",7,"/ итак кого бы ушатать. Волк который ударить мог здесь? А также хочу узнать кто упал, кого  поднять нада",113140,null],[113172,"2026-07-13T18:27:33",31,"//я отыгрываю крестьянина из глубинки, у которого есть навык обращения с животными. Мало ли что там было, в глубинке то...",113164,null],[113180,"2026-07-13T18:28:55",17,"Волки мертвы все около тебя рой летучих мышей, ещё один рой около лежащего Ридли.\n\nТам же двое зомби\n\nИ ещё чертверо вломились через дверь внизу просто месиво \n\nСверху скажу если пойдешь наверх \n\nНо бедолага который тебе помогал лежит",112272,null],[113185,"2026-07-13T18:29:48",7,"/ пробежать к нему без спровоцированных не получиться видимо",113180,null],[113188,"2026-07-13T18:30:01",7,"/ мне нужно касание хоть стабилизировать",112272,null],[113191,"2026-07-13T18:30:21",17,"/ты будешь окружён толпой",112272,null],[113195,"2026-07-13T18:31:17",7,"/ ну помочь ничем не можем",113191,null],[113198,"2026-07-13T18:31:56",7,"/ 3 хита из 8\nЛечу кричу привлекая на себя внимание и убегаю наверх, стараясь не провоцировать атаки и на второй этаж",112272,null],[113201,"2026-07-13T18:32:20",7,"/ опишу когда будет 100% шанс это сделать, чтобы не было приколов нелогичных",112272,null],[113206,"2026-07-13T18:33:11",17,"/ Провоцируя от роя",112272,null],[113208,"2026-07-13T18:33:44",17,"/r +4 Ооооой летучих мышееей",112272,null],[113211,"2026-07-13T18:33:51",17,"/r 2d4",112272,null],[113215,"2026-07-13T18:34:12",7,"/ 4урона и адское возмездие ударить чтоль",113209,null],[113216,"2026-07-13T18:34:32",7,"/ тэк сколько я использовал ладошки огненные\n2 раза или 3....",112272,null],[113219,"2026-07-13T18:35:01",7,"/ не буду рисковать с запором ячеек ничего не делаю",112272,null],[113229,"2026-07-13T18:37:09",60,"//ты 1 лвл?",113216,null],[113234,"2026-07-13T18:37:40",7,"/ да",113229,null],[113235,"2026-07-13T18:37:44",60,"//у тебя две ячейки, друже",112272,null],[113238,"2026-07-13T18:37:51",60,"//всего две",112272,null],[113241,"2026-07-13T18:38:17",7,"/ разве?._. \nВсегда же было 3",113235,null],[113243,"2026-07-13T18:38:57",7,"/ ну тогда реально мисс ход",112272,null],[113247,"2026-07-13T18:39:30",60,"//3 на 2 уровне",113241,null],[113248,"2026-07-13T18:39:40",60,"//ну пиу снарядом, не?",113243,null],[113251,"2026-07-13T18:39:55",7,"/ не, лоханулся пропустил рой перед носом",113248,null],[113252,"2026-07-13T18:40:08",7,"/ хотел наверх свалить",112272,null],[113257,"2026-07-13T18:41:07",9,"//Я бы в лампу свалил в прошлый ход, пересидеть, но прошляпил. Спишем на подростковый максимализм персонажа",112272,null],[113262,"2026-07-13T18:41:55",17,"Нетопыри кусают варвара.",112272,null],[113264,"2026-07-13T18:42:04",17,"/r +5 q +5 q",112272,null],[113269,"2026-07-13T18:42:28",17,"/r 2d6+3 Клыки впиваются в плоть",112272,null],[113274,"2026-07-13T18:42:53",17,"Второй промахивается он еле живой, и пытается отлететь",112272,null],[113275,"2026-07-13T18:43:01",17,"/ Провокация Альф?",112272,null],[113280,"2026-07-13T18:43:25",60,"//так точно. Атакую двоих, ибо приём позволяет выбрать две цели при любой атаке",113275,null],[113282,"2026-07-13T18:43:32",60,"//ну то бишь тех, кого не добил",112272,null],[113283,"2026-07-13T18:43:42",17,"/ Ебаный прием",112272,null],[113285,"2026-07-13T18:43:48",60,"/roll +5 не убежииииишь!",112272,null],[113288,"2026-07-13T18:43:52",60,"//убежит",112272,null],[113295,"2026-07-13T18:44:23",17,"И Марк колет на отходе гада",112272,null],[113298,"2026-07-13T18:44:30",17,"/r +5",112272,null],[113302,"2026-07-13T18:44:48",60,"В глазах варвара потихоньку темнеет. Он почти без сил машет мечом, что-то невнятно бормоча, пока голубая кровь сочится из его ран. Она ведь.. Не должна быть голубой, правда?",112272,null],[113303,"2026-07-13T18:44:49",17,"/r d6+3",112272,null],[113326,"2026-07-13T18:47:48",9,"//Мой ход был? Спасы я не буду бросать на виду, накопятся сколько — кину, не люблю метагейм",112272,null],[113349,"2026-07-13T18:51:35",9,"//Можете проверить кто-то бонусным хотяб подойти поближе, тогда кину, а так неметагеймлю)",112272,null],[113354,"2026-07-13T18:52:00",60,"@QURTZZ твой ход вроде",112542,null],[113357,"2026-07-13T18:52:29",31,"Жду отмашки мастера",113354,null],[113548,"2026-07-13T19:28:29",17,"На отходе раненого нетопыря достал И Марк и тот рухнул на землю у стены",112272,null],[113550,"2026-07-13T19:28:37",17,"/ Ходи, не надо ждать",113357,null],[113553,"2026-07-13T19:28:59",17,"/ Надо выживать. Внизу толпа. Ридли лежит. Немея по-моему тоже.",112272,null],[113557,"2026-07-13T19:30:00",31,"У меня тут наверху один волк?/",112272,null],[113568,"2026-07-13T19:31:22",17,"/ Нет. Он был убит варваром. Тут рой летучих мышей и нетопырь. Огромная тварь у окон. На лестнице два трупа волков",112272,null],[113572,"2026-07-13T19:31:32",17,"Рой тоже у окна",112272,null],[113573,"2026-07-13T19:32:12",31,"/roll d20+1 бью видами по нетопырю",112272,null],[113578,"2026-07-13T19:32:23",31,"Попал?",112272,null],[113581,"2026-07-13T19:32:44",31,"/roll d6+1 если попал, то вот урон",112272,null],[113585,"2026-07-13T19:32:53",31,"Хуевый урон//",112272,null],[113589,"2026-07-13T19:33:12",31,"/roll d10 Бонусом использую Второе дыхание",112272,null],[113591,"2026-07-13T19:33:24",31,"Хуево использовал//",112272,null],[113602,"2026-07-13T19:34:16",17,"/ База)",112272,null],[113605,"2026-07-13T19:34:32",31,"Рак кубов ебет жестоко//",112272,null],[113606,"2026-07-13T19:34:44",17,"Нетопырю ты продырявил чуть перепонку на крыле он даже не заревел",112272,null],[113611,"2026-07-13T19:35:02",31,"/ход",112272,null],[113616,"2026-07-13T19:36:10",17,"Через тела зомби переступают и движутся на второй этаж все толпой толкая друг друга \n\nОни уже преодолели лестницу",112272,null],[113620,"2026-07-13T19:36:31",60,"//ща я им шкаф скину в подарок",113616,null],[113625,"2026-07-13T19:36:48",17,"/ Альф",112272,null],[113627,"2026-07-13T19:36:53",60,"//Альф может сотку одной рукой поднять, угостим зараз чем-нибудь",112272,null],[113636,"2026-07-13T19:37:41",17,"Перед тобой ещё один нетопырь и рой летучих мышей кружится под потолком рядом",112272,null],[113638,"2026-07-13T19:37:42",60,"//только не могу отойти, надо добить мышек",112272,null],[113644,"2026-07-13T19:38:06",60,"//до обоих дотянусь?",113636,null],[113648,"2026-07-13T19:38:50",17,"/ Да. Они технически рядом в 5 от тебя",112272,null],[113650,"2026-07-13T19:38:53",60,"/roll d20 и снова чистые кубы ради большого бо-бо. Кому попало, тому достанется. А если не дотянусь, значит могу отойти безопасно",112272,null],[113653,"2026-07-13T19:38:57",60,"//ага",112272,null],[113654,"2026-07-13T19:38:58",17,"/ рой просто в твоём прсотрантве",112272,null],[113656,"2026-07-13T19:38:59",60,"//принял",112272,null],[113661,"2026-07-13T19:39:26",60,"//взять и отпустить предмет я ведь могу свободным действием, так?",112272,null],[113666,"2026-07-13T19:39:56",17,"/ Да",112272,null],[113668,"2026-07-13T19:40:00",60,"//тут на этаже есть что-нибудь тяжелое?",112272,null],[113671,"2026-07-13T19:40:11",60,"Желательно побольше, но чтоб спихнуть по лестнице можно было",112272,null],[113672,"2026-07-13T19:40:13",17,"Рядом есть труп бургомистра",112272,null],[113676,"2026-07-13T19:40:29",17,"Шкаф был разбит как и тумбы для заделывания окон",112272,null],[113679,"2026-07-13T19:40:40",60,"Если он не кмс по суммо, то этого не хватит",113672,null],[113680,"2026-07-13T19:40:43",31,"/труп на столе лежит, стол можно опрокинуть, все какой то барьер/",112272,null],[113681,"2026-07-13T19:40:47",17,"Стол на котором лежит труп бургомистра",112272,null],[113683,"2026-07-13T19:41:10",17,"Ну он упитанный 80кило есть",113679,null],[113684,"2026-07-13T19:41:27",60,"//а со столом сколько?",113683,null],[113697,"2026-07-13T19:43:41",17,"/ Со столом кило 100",112272,null],[113704,"2026-07-13T19:45:08",60,"—Осквернение умерших? Не, не слышал!\n\nНа последнем издыхании Альф растворяется в воздухе, а затем стол вдруг поднимается в воздух и летит прямо к лестнице, после чего замирает на секунду и падает вниз на мертвецов\n\n—ДЯДЮШКА КОЛУН ЕЩЁ НЕ ДОГОВОРИЛ!!!\n\nРаздаётся голос из воздуха\n\n//Бонуской невидимый, схватил стол, отбежал к лестнице и дал бургомистру последний шанс отомстить. Если кто-то будет кидать спасы или я буду кидать урон, то я снова стану видимым",112272,null],[113715,"2026-07-13T19:46:57",17,"— Нет! Так нельзя!\n\nИсмарк это запомнит\n\n\n— Отец!\n\nИрина это запомнит",112272,null],[113716,"2026-07-13T19:47:13",60,"//по хорошему ещё и сам альф туда прыгнуть должен, но он не переживёт",113704,null],[113719,"2026-07-13T19:47:20",60,"//АГА, ЗАПОМНЯТ. ЕСЛИ ВЫЖИВУТ",113715,null],[113721,"2026-07-13T19:47:23",17,"/ Давай",112272,null],[113723,"2026-07-13T19:47:29",60,"//не-не-не",113721,null],[113724,"2026-07-13T19:47:30",17,"/ Даю тебе прыгать",112272,null],[113725,"2026-07-13T19:47:34",31,"- ваш отец бы сам это одобрил, он вас защищает даже после смерти!",113715,null],[113726,"2026-07-13T19:47:34",60,"//я сверху останусь",112272,null],[113729,"2026-07-13T19:47:39",17,"/ Кидай 2д6",112272,null],[113730,"2026-07-13T19:47:48",60,"//щас еще сделаю колуну нокаутирующий",113726,null],[113731,"2026-07-13T19:48:03",17,"— Это кощунство! Наш бедный отец не заслужил такого!",113725,null],[113735,"2026-07-13T19:48:11",60,"/r 2d6 чем больше труп, тем больнее нежити",113729,null],[113739,"2026-07-13T19:48:37",60,"—ОН ОТЕЦ. ОН РАСТИЛ ВАС И ОТДАЛ ЗА ВАС ЖИЗНЬ. СМЕРТИ ВАШЕЙ ОН ХОТЕЛ?!",113731,null],[113742,"2026-07-13T19:48:43",17,"/r -d20-1 Ловкая нежить?",112272,null],[113748,"2026-07-13T19:49:35",17,"Одного зомби зашибло трупом бургомистра и столом которые метнул варвар\n\nОн больше не встал. Но четверо поднялись",112272,null],[113755,"2026-07-13T19:50:22",60,"//зато свалились с лестницы",113748,null],[113758,"2026-07-13T19:50:37",60,"//Я буду оттягивать неизбежное до конца",112272,null],[113759,"2026-07-13T19:50:46",17,"Рой летучих мышей сверху набросились на Тарха\n\nА внизу с лестницы ещё больше два роя на Варвара",112272,null],[113762,"2026-07-13T19:51:16",17,"/r +4 Тарху +4 Альфу +4 Альфу",112272,null],[113764,"2026-07-13T19:51:19",60,"//у меня 2 хп, любое попадание убьет",113759,null],[113767,"2026-07-13T19:51:24",17,"/r 2d4",112272,null],[113770,"2026-07-13T19:51:31",60,"//А НЕТ",112272,null],[113771,"2026-07-13T19:51:34",17,"/ Везучий",112272,null],[113772,"2026-07-13T19:51:38",31,"Меня не задело/",112272,null],[113773,"2026-07-13T19:51:38",60,"//1 хп!",112272,null],[113780,"2026-07-13T19:52:16",31,"Исмарк ?/",112272,null],[113783,"2026-07-13T19:52:35",31,"Или Немея еще стоит?/",112272,null],[113785,"2026-07-13T19:53:09",17,"Исмарк кромсает нетопыря рядом\n\n— Мы не сдадимся ему!\n\nПозади сестра тянет его за штанину\n\n— Хватит, хватит прошу, отдай меня ему! Сохрани жизни!\n\nИсмарк оборачивается и видит заплаканное лицо сестры \n\n— Ирина, нет! Так нельзя!",112272,null],[113786,"2026-07-13T19:53:21",17,"/r +5 По нетопырю",112272,null],[113789,"2026-07-13T19:53:34",17,"Удар проходит мимо тварь ловка",112272,null],[113792,"2026-07-13T19:53:46",60,"//меня совсем немножко смущают в целом результаты всех кубов",112272,null],[113793,"2026-07-13T19:53:50",17,"/ Тарх. Около тебя рой и нетопырь",112272,null],[113794,"2026-07-13T19:53:57",60,"//что за противостояние говна и мочи",113792,null],[113808,"2026-07-13T19:55:28",31,"Могу я ударить по нетопырю, но не острикм, а как по бкйсбольному мЧику, плашмя, чтобы он отлетел в сторону роя и его развеял, или может кого там поранил? И да, Истмарк тут же тусит, нетопырь окружен же, у меня есть преимущество для такого удара?/",112272,null],[113818,"2026-07-13T19:57:21",17,"Рой это не иллюзия это много летучих мышей его нельзя развеять",113808,null],[113820,"2026-07-13T19:57:32",17,"Толкнуть можешь но нетопырь может летать",112272,null],[113823,"2026-07-13T19:58:00",17,"/ Да, можешь бить с преимуществом по нетопырю",112272,null],[113824,"2026-07-13T19:58:07",31,"Это смотря с какой силой ударить))//",113820,null],[113825,"2026-07-13T19:58:08",17,"/ Рой нельзя окружить в принципе",112272,null],[113829,"2026-07-13T19:58:31",60,"//логика в днд, чтооооо",113825,null],[113830,"2026-07-13T19:58:35",31,"А нетлпыря?/",113825,null],[113834,"2026-07-13T19:59:06",9,"//Вот заклом по площади бы рой развеять, мммм, если мастер разрешит конечн. По механу то у них всех 1 пул хп, а по факту куча мобов, так что тут уже хрен знает.",113818,null],[113841,"2026-07-13T19:59:48",31,"Я просто думал что если с достаточной силой ударю по нетопырю, то он сам станет чем то вроде импровизированного оружия и сможет нанести урон Рою/",112272,null],[113848,"2026-07-13T20:00:42",31,"Ладно, бью по нетопырю",112272,null],[113850,"2026-07-13T20:00:48",31,"/roll d20+1",112272,null],[113852,"2026-07-13T20:00:55",17,"/ Он огромный летучий мыш",112272,null],[113853,"2026-07-13T20:01:01",31,"Да заебал рак кубов//",112272,null],[113854,"2026-07-13T20:01:06",17,"/ Преимущество от окружения есть у тебя",112272,null],[113856,"2026-07-13T20:01:15",31,"/roll d20+1",112272,null],[113858,"2026-07-13T20:01:25",31,"Один хер",112272,null],[113859,"2026-07-13T20:01:31",31,"Ладно, бонусом/",112272,null],[113860,"2026-07-13T20:01:31",17,"/ Но нет ты всего лишь крестьянин с вилами",112272,null],[113864,"2026-07-13T20:01:54",31,"/r +d20+1",112272,null],[113866,"2026-07-13T20:02:03",60,"//я его услышал",113862,null],[113867,"2026-07-13T20:02:06",31,"Пиздец не прет//",112272,null],[113868,"2026-07-13T20:02:16",31,"/ход",112272,null],[113869,"2026-07-13T20:02:23",60,"//поэтому кидаемся бургомистрами",113867,null],[113870,"2026-07-13T20:02:32",60,"//им не нужно попадание, они самонаводящиеся",112272,null],[113871,"2026-07-13T20:02:42",31,"Давай Ириной кидаться)/",113869,null],[113878,"2026-07-13T20:03:29",60,"//получается зомби сейчас опять полезут",112272,null],[113883,"2026-07-13T20:03:39",60,"//а у меня нет второго бургомистра",112272,null],[113888,"2026-07-13T20:04:23",31,"Там падште нехай 20 выкидывают и встают)))//",112272,null],[113896,"2026-07-13T20:05:12",60,"//я ща сам туда прыгну",113888,null],[113910,"2026-07-13T20:07:32",31,"Ладно, давай уже сдохнем и я спать пойду))",112272,null],[113914,"2026-07-13T20:08:00",31,"Бля, когдя я так сказал в прошлый раз, мы херачили потом еще 8 часов и в итогетда, сдохли//",112272,null],[113921,"2026-07-13T20:08:47",9,"//Чую сдохнуть нам не дадут просто так а ещё и заса, тоесть посадят и будут тыкать разными штуками — пытать.",112272,null],[113981,"2026-07-13T20:17:15",31,"Ладно, я спать. Завтра сдохну//",112272,null],[113995,"2026-07-13T20:19:07",60,"//доброй ночи",113981,null],[114110,"2026-07-13T20:51:44",17,"Четыре зомби добираются до варвара и валят его на пол стеной из плоти",112272,null],[114111,"2026-07-13T20:51:51",17,"/r +4 +4 +4 +4",112272,null],[114115,"2026-07-13T20:52:00",17,"/ Лежит",112272,null],[114121,"2026-07-13T20:52:31",60,"//эт точно",112272,null],[114122,"2026-07-13T20:52:31",17,"Под грудой тел мертвецов Альф наконец отпускает ярость",112272,null],[114125,"2026-07-13T20:52:51",17,"Летучие мыши грызут Тарха",112272,null],[114126,"2026-07-13T20:53:02",17,"/ Все три роя",112272,null],[114127,"2026-07-13T20:53:12",17,"/r +4 +4 +4",112272,null],[114130,"2026-07-13T20:53:28",17,"И облепив парня они тоже валят его на пол",112272,null],[114131,"2026-07-13T20:53:51",60,"Варвар не выдерживает. Он выжал из себя всё, что мог, и теперь очевидно, что осквернение тела Колуна было его последним глотком жизни, прежде чем он захлебнулся смертью. Увидит ли он свет вновь? Не сейчас станет нам известно...",112272,null],[114132,"2026-07-13T20:54:01",17,"Исмарк в отчаянии видя что это конец колет нетопыря\n\n— Мы умрем но не сдадимся!",112272,null],[114133,"2026-07-13T20:54:15",17,"/r +5 Последний укол",112272,null],[114135,"2026-07-13T20:54:37",17,"Нетопырь хватает его меч за лезвие клыками и вырывает из рук отбрасывая в сторону",112272,null],[114136,"2026-07-13T20:54:57",17,"Сам запрыгивает на Исмарка всей тушей",112272,null],[114137,"2026-07-13T20:55:03",17,"Заносит клыки чтобы умертвить его",112272,null],[114138,"2026-07-13T20:55:15",17,"И в этот момент стук в дверь внизу. Двери правда нет так что стук по косяку",112272,null],[114139,"2026-07-13T20:55:31",17,"Время замирает. Нет это все твари замерли. Боятся шелохнутся",112272,null],[114140,"2026-07-13T20:56:00",60,"//Аркадий паровозов?",112272,null],[114241,"2026-07-13T21:44:10",17,"Нетопырь отрывается от шеи Исмарка.\n\nЗомби одновременно прекращают движение. Рой под потолком сворачивается в плотную чёрную воронку.\n\nВ разбитом проёме стоит высокий худой мужчина в тёмном военном кафтане. Его лицо пересекают тонкие шрамы. На поясе висит изогнутый клинок.\n\nОн ещё раз касается косяка.\n\n— Его сиятельство. Граф Сад фон Зрович прибыл. Хозяева встречайте.",112272,null],[114242,"2026-07-13T21:44:50",17,"Рахадин. Его правая рука.",112272,null],[114250,"2026-07-13T21:50:50",17,"За его спиной улица изменилась.\n\nОт чёрной кареты до самого крыльца расстелена длинная красная дорожка. Она лежит поверх грязи, луж, выбитых досок и тел.\n\nКарету держит двойка чёрных лошадей. Из их ноздрей выходит дым, между зубами пробегают красные искры.\n\nПо обе стороны дорожки сидят сотни летучих мышей, сложив крылья.",112272,null],[114265,"2026-07-13T22:02:23",60,"Альфарий бы высказал свою точку зрения и то, что он думает насчет абсолютной негигиеничности такого расклада и несколькой резкости глашатаев графа, но временно сдох и не может сейчас разговаривать",114250,null],[114300,"2026-07-13T22:28:33",17,"Из кареты выходит женщина в багровом платье. Она поправляет длинную перчатку и остаётся возле открытой дверцы.\n\nЛюдмила Велисевич. Но имени вы не узнаете.\n\nСледом появляется граф.\n\nСад фон Зрович неторопливо ступает на красную дорожку. Грязь не касается его сапог. Он подходит к крыльцу и останавливается перед разбитым порогом.",112272,null],[114301,"2026-07-13T22:29:25",17,"Сад Фон Зрович. Граф",112272,null],[114302,"2026-07-13T22:29:52",17,"Его спутница. Людмила Василевич.",112272,null],[114303,"2026-07-13T22:32:43",60,"//ну стиль картинки рисовки конечно кайфовый",114301,null],[114304,"2026-07-13T22:32:54",17,"Граф оглядывает разрушенный вход.\n\n— Какая досада. Я пришёл слишком поздно.\n\nОн остаётся снаружи.\n\n— И всё же войти без приглашения было бы невежливо.\n\nРахадин склоняет голову.\n\n— Убрать беспорядок?\n\nСад едва заметно шевелит пальцами.\n\n— Разумеется.",112272,null],[114305,"2026-07-13T22:34:26",60,"//я понимаю, авторские права, но... Имя...",114304,null],[114306,"2026-07-13T22:35:14",17,"Рой обрушивается на комнаты.\n\nНетопыри цепляются за одежду, ремни и волосы. Зомби подхватывают тела за руки и ноги.\n\nС первого этажа вытаскивают Ридли и Немею.\n\nСо второго волокут Тарха, Альфария и Исмарка. Ирину несут следом.\n\nЧерез несколько мгновений все лежат на крыльце перед графом.",112272,null],[114307,"2026-07-13T22:37:16",17,"Оставшиеся зомби собирают тела своих павших и складывают их у стены.\n\nЛетучие мыши подхватывают обрывки плоти, щепки, выбитые зубы и клочья одежды. Рой проходит над двором чёрной волной.\n\nКрасная дорожка снова чиста.\n\nВо дворе становится тихо.",112272,null],[114308,"2026-07-13T22:37:41",17,"/ ладно Будет как оригинальный Страд",114305,null],[114309,"2026-07-13T22:38:05",17,"Сад поднимает руку.\n\nПальцы Немеи судорожно сжимаются. В её груди вспыхивает жар.\n\nЗнак Багрового Савана под одеждой Ридли становится ледяным, затем обжигает кожу.\n\nИз лёгких Тарха вырывается хриплый вдох.\n\nПравый глаз Альфария открывается первым. В его зрачке на мгновение отражаются башни под чёрной водой.",112272,null],[114310,"2026-07-13T22:38:11",17,"/ У вас 1 хит",112272,null],[114311,"2026-07-13T22:38:15",60,"//не, оставляй, у альфария будет бесконечный потенциал для шуток за спиной и так выглядит куда оригинальнее)",114308,null],[114312,"2026-07-13T22:38:16",17,"/ Вы приходите в сознание",112272,null],[114313,"2026-07-13T22:39:15",17,"Исмарка выгибает от кашля.\n\nИрина побелела она не имеет даже плакать.\n\nСердца снова начинают биться. Кровь движется по жилам. Боль возвращается вместе с сознанием.\n\nРаны остаются на месте.\n\nГраф опускает руку.\n\n— Вот так гораздо приличнее. Я предпочитаю разговаривать с теми, кто способен услышать и  отвечать.",112272,null],[114314,"2026-07-13T22:40:16",17,"Ирина приподнимается.\n\nИсмарк пытается встать вместе с ней, но будто бы придавлен аурой этого господина графа.\n\nСад переводит взгляд на девушку.\n\n— Ирина. Ваш дом разрушен. Ваш отец мёртв. Ваш брат истекает кровью у моих ног.",112272,null],[114315,"2026-07-13T22:41:07",17,"Граф протягивает ей руку.\n\n— Время пришло. Пойдёмте со мной. Вы станете моей новой невестой.\n\nОн обводит взглядом лежащих на крыльце людей.\n\n— Нападения прекратятся. Ваш брат и эти наёмники сохранят жизни. А деревня вздохнет спокойно.",112272,null],[114316,"2026-07-13T22:41:31",17,"Исмарк цепляется за край платья Ирины.\n\n— Не смей…\n\nСлова заканчиваются кашлем.\n\nИрина смотрит на брата. Потом на Немею, Ридли, Тарха и Альфария.\n\nЕё пальцы медленно разжимают руку Исмарка.",112272,null],[114317,"2026-07-13T22:41:43",17,"/ Реакции есть тут?",112272,null],[114318,"2026-07-13T22:42:31",17,"Ирина поднимается.\n\n— Вы оставите их в живых?\n\n— Я уже оставил.\n\n— И больше никто не придёт к этому дому?\n\nГраф слегка улыбается.\n\n— Этому дому больше нечего мне предложить.",112272,null],[114319,"2026-07-13T22:42:54",17,"Ирина делает шаг к красной дорожке.\n\n— Тогда...\n\nГлубокий вдох. \n\n— Я... я пойду.\n\nЛюдмила открывает дверцу кареты шире. Рахадин отступает в сторону.\n\nСад продолжает держать руку протянутой.",112272,null],[114320,"2026-07-13T22:43:27",60,"Первым следует не тяжелый, глубокий вдох, а абсолютная сосредоточенность в этой тишине, глухой и глубокой, где в ушах слышен лишь звон и шум глубин, куда более гротескных и ужасных, чем сам граф и любое подобное ему существо. Лежа на земле, Альфарий видит вовсе не графа: искаженный жемчужиной взор заставляет его созерцать обрывки сознания великого древнего, дремлющего в глубинах то ли пучины, то ли космоса. Но.. Варвар боится не смерти. А контроля. Осознания того, что его жизнь уже поделена меж чужими. Он закусывает губу, сжимая ладони в кулаки, и поднимается на ноги медленно, не произнося ни слова, лишь затуманенным взором сверля сейчас даже не графа: Ирину. Он.. Даже сам не понимает, какие чувства испытывает. Но это и не по его части.",114309,null],[114321,"2026-07-13T22:45:15",17,"Граф смотрит на каждого из вас по очереди.\n\nОн не торопит Ирину.\n\nДо его протянутой руки остаётся один шаг.",112272,null],[114322,"2026-07-13T22:45:42",60,"Темпест хотел бы вмешаться, но сил не было: не было и контроля над собой. Немой крик с закрытым ртом словно рвал берсерка на части изнутри: \"Нельзя так поступать с бургомисторм\". Он отдал за это жизнь. А что делает она? Отдает свою свободу взамен на чужие жизни. Но..\n\n\nЧто на самом деле дороже? Свобода.. Или жизнь?",114319,null],[114323,"2026-07-13T23:37:10",9,"*Ридли очнулся, но, он понимает что сделал много ошибок, тянется к ране на боку, укус порванный саван. Ему нечего сказать грифу, он молчит, перед ним некто с кем он не справится и он это осознаёт. Рука сама тянется к маске.*",112272,null],[114324,"2026-07-13T23:38:19",9,"*Боль? Тяжесть? Усталость? Это всё отмашки, жизнь. Обещание стоит многого, но... какова цена манер...*",112272,null],[114325,"2026-07-13T23:39:47",9,"*Ридли снимает маску и капюшон, под ними бледная кожа, красные пронизывающие глаза, и лицо застывшее без эмоций словно маска.*\n\n//Секунду ищу где тот бля арт",112272,null],[114327,"2026-07-13T23:42:35",9,"*Просто учтивость, не носить головные уборы в доме и при уважаемых господах. Лёгкий поклон, но приветствовать он не собирается, молчит.*",112272,null],[114328,"2026-07-13T23:43:35",9,"//Пардоньте, это всё что планировал, это ооооооччччееееееннннньььььь старый арт оригинального Ридли, из самых глубин...",112272,null],[114338,"2026-07-14T04:32:26",31,"Тарх смотрит мутным взглядом на прибывшего за девушкой графа. Он уже видел чудовищ, но тот вампир был больше животным, чем человеком. А этот на животное не походил, но внушал куда больше страха. Хотелось свернуться клубком и плакать. Что он, простой человек, мог бы противопоставить?\n\nА потом проснулась злоба, та самая что была и дома, когда он увидел как Ревенанты подняли его мёртвых родителей как зомби, и отправили работать, лишив посмертного покоя. Тогда Тарх не сдался, не сдастся и теперь. Да, пока он слаб, но он точно найдет способ стать сильнее\n\nКак же хочется спать...",112272,null],[114339,"2026-07-14T07:08:44",7,"/ были бы, не лежал бы с 0 хитов и не отобрали бы возможность ночью посидеть",114317,null],[114340,"2026-07-14T07:10:33",17,"/ Все с 1 хитом. Граф вас оживил",112272,null],[114341,"2026-07-14T07:11:21",7,"/ отлично!",112272,null],[114342,"2026-07-14T07:15:30",7,"*Немейя еле встала на ноги. Она задавалась вопросом, почему пламя во время битвы было голубым... Но это сейчас не так важно, она стоит напротив нечестивого, что буквально заставляет ее сгорать. Но ничего не делает, она просто стоит слегка дрожа, с недовольным лицом. Холод окутывает все тело, кроме груди, где искра ещё не погасла.*",112272,null],[114343,"2026-07-14T07:15:48",7,"/ ну чтож, видимо будем за Ириной по пятам идти",112272,null],[114344,"2026-07-14T08:05:34",31,"нас только что летучие мыши отмудохали. нам надо искать не прямой путь, пойдем по пятам - сдохнем))//",114343,null],[114345,"2026-07-14T08:06:37",17,"/Кто тохояет заявку? Ну там внимание проницательность и тд",112272,null],[114346,"2026-07-14T08:06:45",17,"/ Я так понял всем ссыкотно",112272,null],[114347,"2026-07-14T08:07:55",31,"мы просто отыгрываем тяжелое поражение и упадок моральных сил//",112272,null],[114348,"2026-07-14T08:08:09",31,"хотя, давай//",112272,null],[114349,"2026-07-14T08:09:15",31,"Тарх скидывает усилием воли сонливость, злоба на графа пересиливает. поднимаю голову, смотрю, оценива, может что т бросится в глаза? какая то деталь, что поможет его позже прижать?",112272,null],[114350,"2026-07-14T08:10:00",31,"/roll d20+1 на внимательность",112272,null],[114351,"2026-07-14T08:10:00",17,"/ Проницательность",112272,null],[114353,"2026-07-14T08:11:18",31,"/roll d20",114351,null],[114355,"2026-07-14T08:11:23",17,"Он выглядит неуязвимым. Обсолютная власть. Обсолютная сила. По внешнему виду его и его свиты ты понимаешь, что это недосягаемый уровень",112272,null],[114356,"2026-07-14T08:11:27",17,"/ Взяли 18",112272,null],[114357,"2026-07-14T08:12:05",31,"можно описание свиты? или там только Людмила?/",112272,null],[114358,"2026-07-14T08:12:11",17,"Но так же ты понимаешь, ещё одно. Он смотрит не на Ирину. Он смотрит на вас. Он намерено медлит. Он ждёт от вас чего того, проверяет вашу решимость.",112272,null],[114359,"2026-07-14T08:12:42",17,"/ Рахадин. И Людмила. Более никого.",114241,null],[114360,"2026-07-14T08:14:40",17,"Сад задерживает взгляд на каждом из героев.\n\n— Немея. Тарх. Альфарий Темпест. Ридли.\n\nОн произносит имена медленно, словно уже встречал их прежде.\n\n— Добро пожаловать в моё графство. Надеюсь, Багровия окажется гостеприимнее, чем её жители.\n\nГраф слегка склоняет голову.\n\n— Я — Сад фон Зрович. Отныне вы мои гости. И мне очень интересно наблюдать за вами. Так зачем же вы прибыли в мои владения?",112272,null],[114361,"2026-07-14T08:19:03",31,"Если вы знаете наши имена, то явно знаете и для чего мы прибыли, ваша... светлость?\n\n*Тарх не уверен что к этому сществу применимо слово \"светлость\"*",112272,null],[114362,"2026-07-14T08:30:37",9,"//Чую зомби и летучие мыши к нам будут лезть каждый вторник. Я щас карту и чутка лор к ней бубеню, могу отвлекаться.",112272,null],[114363,"2026-07-14T08:35:46",17,"— Может быть я имею некие догадки. Но доподлинно я не знаю, поэтому интересуюсь у вас. Каждый гость, кто попадает в Багровию уникален. И очень мне интересен. Рассжите чего вы хотите достичь? Успеха? Почитания? Богатства? Силы? Может быть... Знаний?\n\nИрина замерла. А граф опустил руку. Он явно хочет поговорить с вами.",114361,null],[114364,"2026-07-14T08:38:36",31,"- мы пришли чтобы защить госпожу Ирину. Но теперь она сама и по своей воле ушла к вам, и я в растерености. Если на то будет ваша воля, как правителя этих земель, то я бы задержался тут. Моя родная страна в полной разрухе, нет смысла туда возвращаться",114363,null],[114365,"2026-07-14T08:38:59",31,"*по своей воле, как же. кусы на ее шее я помню* Мысли ТАрха",112272,null],[114366,"2026-07-14T08:46:07",9,"— Ищу пробуждение или... смерть... судьба редко благосклонна, скорее найду последнее. — *Ридли без страха поднял глаза, неуязвимый? Вампиры это тень самих себя, обман, правда... в этих землях солнце не спуститься на землю и не покажет \"истину\" развеяв тень.* — Блага и сила. Со всем \"уважением\", ваша, светлось — не намерен ничего просить. То чего не достиг сам — иллюзия которая не стоит ничего.\n\n*Ридли немного по другому видит ситуацию, он ещё совсем не в курсе дела что тут происходит.*\n\n— Благодарю за статус гостя. Пожалуй большего и не надо. — *Как бы Парня не учили быть сдержанным, его учили ищбавлять нежить, где-то крошечный червячок грыз его подбивая быть немного агрессивнее в отношении графа, но здравый смысл не давал совершить самоубийство.*\n\n//А ещё у меня амулет ордена бесоёбит что странно, но ладно, буду думаю что это что-то типа фонаря поиска, для сюжетки его и слелаю раз надо.",112272,null],[114367,"2026-07-14T08:54:55",7,"/ к сожалению да, я ссыкло ( Персонаж боится, был бы варвар пути зверя уже бы сразу кинулся и там бы умер )",114346,null],[114368,"2026-07-14T08:55:18",7,"/ после работы здесь, но могу пропадать, не теряйте",112272,null],[114370,"2026-07-14T09:02:05",7,"*Немейя услышав вопрос, вначале не особо желала отвечать. Однако она выдохнув, посмотрела вниз. Возможно сюда придут жители что помогут, а может и стража... Стража... Ни одного стражника не было замечено. Это может было все спланировано графом... Может все зомби это здешние мирные жители... Она чувствует, как начала проникаться некой злостью, сама не понимала из-за чего... Это просто было нечестным... Но подобрав слова говорит.*\n\n— Узнать о даре, что позволяет создавать пламя, восхищаться им. Открыть в себе талант на большее использование сил... И раз большинство ответило на ваш вопрос, можете утолить наш интерес к знаниям. Почему именно в этом богами забытом месте вам нужна конкретно эта девушка Ирина? \n\n*Несмотря на сильное желание сжечь, напасть, она держит себя в руках. Вместо этого лишь слегка хриповатым от боли, но спокойным голосом говорит и желает лишь узнать только это. Также проверить позже себя и свой огонь. Беспокойство, что огонь поменял цвет начало ее тревожить только после битвы... Она рассчитывала часть дома сжечь, во время атаки...*",114363,null],[114371,"2026-07-14T09:12:27",60,"—Мне сказали прийти и помочь. Обещали награду. Но теперь нахер моральные принципы. Я хочу жить. А как такое существо пользуется своей силой ради насильной любви.. Так себя вести может только чмо. Демонстрация силы топит мораль в говне. Да и не было никогда морали.\n\nАльф принял поражение, но он не будет подлизываться. Фирболг выскажет всё, что думает, просто потому что зол на факт происходящего. Сегодня ему.. Не повезло. И возможно это будет последняя неудача, но честная, без обманок.\n\n—У меня нет никакого уважения и страха пред теми, кто мучает живых неживыми. Я видел херь пострашнее... Но даже эта херь не поступала так в моих снах.",114363,null],[114378,"2026-07-14T10:06:52",17,"Сад выслушивает всех до конца. Даже слова Альфария не стирают улыбку с его лица.\n\nСначала он смотрит на Тарха.\n\n— Остаться вы можете. Багровия охотно принимает тех, кому больше некуда возвращаться. Со временем она становится единственным домом, который они помнят. Добро пожаловать.\n\nЗатем его взгляд переходит к Ридли.\n\n— Пробуждение и смерть часто стоят рядом. В моих землях вам выпадет не мало возможностей.\n\nОн чуть склоняет голову, заметив амулет.\n\n— Говорить о силе можно. Посмотрим, сможете ли выдержать её прикосновение.\n\nСад поворачивается к Немее.\n\n— Боги давно мертвы, но остались их отголоски, и даже в Баровии можно найти удивительные чудеса. Огонь, всё ещё отвечает тем, кто умеет его звать. Но не заигрывайтесь, любая магия опасна. Особенно в моих владениях.\n\nНа вопрос об Ирине он несколько мгновений молчит.\n\n— В её лице сохранилось то, что однажды было у меня отнято. Но ничто не исчезает бесследно. Иногда просто обретает новое имя.\n\nПоследним он смотрит на Альфария.\n\n— В ваших словах много грязи, ярости и честности. Для первого разговора этого вполне довольно.\n\nУлыбка графа становится едва заметно шире.\n\n— Вы видели нечто страшнее меня во сне. Надеюсь, однажды оно проснётся вместе с вами. Мне будет интересно сравнить.\n\nСад снова протягивает Ирине руку.\n\n— Благодарю за откровенность, господа. Теперь я знаю, чем каждого из вас можно испытать.",112272,null],[114381,"2026-07-14T10:08:58",7,"/ готов поспорить, что Сад натравит на Немею огнетушитель",112272,null],[114387,"2026-07-14T10:15:57",31,"анти-дракона//",114381,null],[114388,"2026-07-14T10:16:08",7,"*Немейя скрипит зубами. Ее распирает от гнева, руки накаляются до такой степени, что начали буквально дымиться. Однако она держит себя в руках, дабы не умереть. Она хотела себя излечить, но осматривает окружающих, кто сильней ее изранен.*",112272,null],[114389,"2026-07-14T10:16:22",7,"/ кто там в крови захлёбывается?",112272,null],[114391,"2026-07-14T10:16:48",31,"нас всех граф поднял, надо просто отдохнуть//",114389,null],[114392,"2026-07-14T10:17:15",31,"граф свалил?/",112272,null],[114393,"2026-07-14T10:18:00",7,"/ еще нет, он с Ириной болтать решил. Вот и распирает Немейю от злости",114392,null],[114394,"2026-07-14T10:19:38",17,"— Что ж. Если никто не возражает. Нам пора откланяться. Приятно было познакомиться. \n\nПозади в доме зомби закончили уборку и выходят строем. Тело бургомистра лежит на полу даже руки ему сложили на груди\n\nПауза",112272,null],[114397,"2026-07-14T10:24:11",31,"- мы должны помочь Исмарку с погребением.",112272,null],[114419,"2026-07-14T10:36:04",7,"*Девушка просто в злости, начинает осматривать зомби. Тяжело вздохнув, она не трогает Графа.*\n\n— Угу... Удачной помолвки... Вам... \n\n*Произносит скрепя зубами, стараясь без негатива. Еда сгнила, денег мало... Задание провалено...*",112272,null],[114433,"2026-07-14T10:42:21",9,"//Пох, у меня еда в сосуде, правда там всего дней на 40, не разгуляешься ^^",112272,null],[114434,"2026-07-14T10:43:08",36,"//пффф 40 дней. Фигня какая",114433,null],[114435,"2026-07-14T10:43:32",17,"/ Так я правильно понял возражений нет",112272,null],[114436,"2026-07-14T10:43:43",17,"/ Альф, Ридли",112272,null],[114437,"2026-07-14T10:44:27",7,"/ а что сделаю?\nКину огненный снаряд в лицо и сам получу огнетушителем по лицу?",114435,null],[114438,"2026-07-14T10:44:34",9,"//Ты к чему это? Обьясняй, я мож не выкупил чего, читал пробежкой (ипут меня в последнее время)",114436,null],[114439,"2026-07-14T10:44:59",7,"/ кинуть на внимание есть желание может, на проницательность",114438,null],[114440,"2026-07-14T10:45:05",7,"/ анализ",112272,null],[114442,"2026-07-14T10:47:56",9,"//Да тут и ежу понятно, граф сильный, мы игрушки и тд. Он развлекается, стопроцентов он будет нас м5тать туда сюда. Я не знаю что с едой и тд, но мой перс пока пирожки с маком не ел. А так в целом что смотреть, лица их запомнил, знаю где примерно живут и отлично. Не щнаб что дм хочет. Мы не на свадьбе чтобы выкрикивать \"я возражаю\" хотя учитого характер вампира могло сработать. Но это не в стиле моего перса. А кидать на анализ насколько вампир охуенен? — он охуенен и силён)))",112272,null],[114443,"2026-07-14T10:48:55",60,"Альф переводит взор на Ирину\n\n—Это последнее решение. Больше выбора не будет. Свободе конец.\n\n//Я хочу понять, что она сейчас чувствует. Наверное, проницательность",114378,null],[114445,"2026-07-14T10:50:07",9,"//Пытается смириттся с судьбой, обида и бессилие. Надежда в глазах гаснет. Лан, я чет задушнил сам, и не дм, надо расслабится",114443,null],[114449,"2026-07-14T10:52:15",60,"Темпест лишь отмахивается. Он не испытывает какой-то особой злобы к графу, скорее в целом к ситуации. Ему неприятна эта встреча отчасти потому, что он почти умер. А это.. Больно, как минимум. Даже его тушка так много не выдержит.\n\n—Охеренно знакомы, ну его..",114394,null],[114475,"2026-07-14T11:00:30",17,"/ Я ничего не хочу)) просто каждый играет как хочет своего персонажа) а я смотрю )",112272,null],[114477,"2026-07-14T11:01:35",7,"/ я вот и стараюсь хаотичность отыгрывать чутка",112272,null],[114482,"2026-07-14T11:03:12",17,"— Она никогда твоей не станет, чудовище. Я умру но не оставлю попыток вернуть свою сестру.\n\nИсмарк дёргается в бессильной ярости вперёд и тут же Рахадин оказывается у него мягко останавливая его рукой и лезвие у шеи",112272,null],[114485,"2026-07-14T11:04:17",17,"— Исмарк, не надо, прошу. Живи. Защити жителей деревни, наследник отца не должно просто исчезнуть.\n\nИсмарк смотрит на нее и слеза катится по щеке \n\n— Ирина я...\n\n— Знаю, я все знаю.",112272,null],[114486,"2026-07-14T11:05:10",17,"Сад смотрит на Исмарка поверх плеча Рахадина.\n\n— Вы унаследовали от отца упрямство. Казну, дом и людей, которые ещё дышат. Постарайтесь не потерять всё за одну ночь.\n\nГраф едва заметно поднимает два пальца.\n\nРахадин убирает клинок от шеи Исмарка, но остаётся рядом.",112272,null],[114489,"2026-07-14T11:05:43",17,"Ирина опускается перед братом на колени и касается его щеки.\n\n— Не ходи за мной. Похорони отца. Позаботься о людях.\n\nИсмарк прижимает её ладонь к лицу.\n\n— Я найду тебя.\n\n— Я знаю.\n\nОна осторожно высвобождает руку и поднимается.",112272,null],[114491,"2026-07-14T11:06:33",9,"*Подходит, не спеша и ложит руку на поечо, сжимает.*\n\n— Мёртвый — не сможешь. — *Намекает Исмарку (надеюсь это тот парень) успокоится немного, он все равно сейчас ничего не сможет.*",112272,null],[114493,"2026-07-14T11:07:09",17,"Сад обводит взглядом стоящих на крыльце героев.\n\nНикто не произносит ни слова против боле.\n\n— Порой молчание сохраняет жизнь лучше любого оружия. Запомните это чувство. В Багровии оно станет вашим спутником. \n\nОн протягивает Ирине руку.\n\nОна поднимается. На этот раз она принимает её.",112272,null],[114495,"2026-07-14T11:07:51",17,"Людмила встречает Ирину у кареты и подаёт ей затянутую в перчатку ладонь.\n\n— Осторожнее, дорогая. Ступень высокая.\n\nИрина садится внутрь. Людмила устраивается рядом. Граф занимает место напротив них.\n\nПеред тем как дверца закрывается, Сад обращается к героям\n\n— Гостите столько, сколько сможете.",112272,null],[114499,"2026-07-14T11:08:22",17,"Рахадин занимает место возничего и натягивает поводья.\n\nКошмары срываются с места. Из-под их копыт вылетает красный жар, но мокрая земля не загорается.\n\nКрасная дорожка поднимается следом за колёсами, сворачивается длинной багровой лентой и исчезает в тумане вместе с каретой.\n\nИсмарк остаётся на ступенях. Его рука всё ещё протянута туда, где только что стояла сестра.",112272,null],[114500,"2026-07-14T11:09:09",17,"Карета унеслась в замок, на высоком холме виднеются его шпили.\n\nМолния в этот момент пронзает небеса и замок подсвечивается светом электрической стихии.",112272,null],[114501,"2026-07-14T11:09:35",17,"Все зомби и волки ушли в канавы и лес. Трупы утащили с собой. Осталось только тело бургомистра.",112272,null],[114510,"2026-07-14T11:12:28",9,"— Забавное место. — *Парень налевает маску и капюшон, после кивает варвару, они встречались недавно, убили звонаря.* — Не ожидал увилеть тебя здесь, похоже тогда мы разошлись в одну сторону.",112272,null],[114511,"2026-07-14T11:12:38",17,"/ Каждый герой получает по 300 опыта.",112272,null],[114513,"2026-07-14T11:12:55",60,"Гнев постепенно пропал с лица фирболга, оставив только каменную строгость. Он повернулся к дому\n\n—Похороним мужика, пожрём и спать. С остальным разберёмся потом. Надо раны залатать, я уже промок в крови, зараза.\n\nОн говорит это практически без эмоций. Перед его взором от вспышки молнии на секунду всплывает лик древнего, но Альф лишь хмурится, дважды моргнув. Сейчас ему не до этого",112272,null],[114515,"2026-07-14T11:13:22",9,"*Достает письмо и передаёт Исмарку.*\n\n— Как понял. Это было ваше, немного опоздал.",112272,null],[114517,"2026-07-14T11:13:59",9,"//Мне тоже?",114511,null],[114518,"2026-07-14T11:14:34",7,"*Немейя делает вдох выдох... Вдох, выдох... Пора успокоиться, это не поможет ситуации... Надо ей помогать Ирине? Стоит ли это жизни... Это не стоит денег... Но граф напрямую повлиял на ее дар. Она начинает себя ощупывать в области шеи, как будто ищет место укуса. Не настолько глупа она, чтобы не понять. Вампир могущественный только что все отвесил по шее...*\n\n— Ребята, я ни на что не намекаю, поищите у себя укусы. Кому помочь встать, у кого раны сильные?",112272,null],[114520,"2026-07-14T11:15:35",31,"ы с тобой взяли второй уровень обывателя? чисто бросить на повышение ХП? больше же ничего не растет на этом уровне?/",114517,null],[114521,"2026-07-14T11:15:54",9,"//Пошли во флуд, покажу",114520,null],[114529,"2026-07-14T11:19:10",17,"— Да. Но все оказалось тщетно. Пойдёмте в дом, нужно решать, что делать дальше. И... Похоронить отца.",114515,null],[114533,"2026-07-14T11:20:22",31,"- да. мертвые должны лежать в земле\n\n*личное убежждение от предыстории. когданибудь  ее напишу*",112272,null],[114534,"2026-07-14T11:20:42",9,"*Смотрит на свой потрёпанный саван, плевать. Потом зашьёт или попросит кого нибудь. Идёт в дом, Альфарий с ним так и не заговорил, хотя с варваром они говорили лишь единожды до этого.*",112272,null],[114535,"2026-07-14T11:21:19",7,"/ @dunchev я нащупал на шее где то укус?",112272,null],[114538,"2026-07-14T11:22:07",17,"Укуса на шее нет.\n\nГраф сказал, что магия опасна. Особенно в его владениях, возможно он как то влияет на плетение тут.",114518,null],[114539,"2026-07-14T11:22:28",31,"- кстати об укусах. я заметл на шее Ирины укус. Это к вопросу о самостоятельности ее решения добровольно уйти к графу",112272,null],[114543,"2026-07-14T11:24:26",9,"— Если убить старшего вампира и его никто не заменит все выродки потеряют силы или умрут если долго на этом свете. Это несбыточная вещь в наших реалиях. — *Садится где-то в доме, отдохнуть.*",112272,null],[114546,"2026-07-14T11:24:56",17,"Вы все заходите в дом.\n\nИсмарк находит бинты и чистую воду. Промывает раны и бинтует их. Так же предлагает и вам.\n\nКогда он слышит об укусе на шее сестры. Он поднимает глаза на Тарха.\n\n— Да. Этот монстр явился сюда посреди ночи, в ее комнату. И оставил ей этот подарок, маньяк. Но сестра не изменилась. Мы с отцом перепугались, начали искать помощи и это письмо\n\nОн достает пергамент Ридли\n\n— Мы написали в отчаянии. Разослали его воронами. А потом начались нападения.",112272,null],[114548,"2026-07-14T11:26:02",17,"— Ты много знаешь о вампирах. Учился у кого то? На сколько я знаю граф уничтожил всех охотников на нечисть. Был тут давно давно орден. Мать рассказывала как сказку на ночь.",114543,null],[114551,"2026-07-14T11:26:30",17,"— А ещё он как то собрал всё серебро у кого хоть монетка была. Пропали.",112272,null],[114554,"2026-07-14T11:27:02",9,"— Не уверен, но пока укушенный не выпьет крови проклятие его не может поглотить. — *На вопрос о вампирах покачал головой.* — Записи, я цмею читать. О их достоверности меня не спрашивай, источники слишком разные, люди приукрашивают многое. Только узнать на практике.",112272,null],[114556,"2026-07-14T11:28:19",9,"//Думаю в целях соблюдения задумок и сюжетов может быть чутка по разному от вампира к вампиру",112272,null],[114557,"2026-07-14T11:28:34",17,"— Вот значит как. Граф хочет чтобы она выпила его крови? Сволочь.",114554,null],[114558,"2026-07-14T11:29:02",7,"*Не обнаружив укусы, Немейя чувствует себя измотанной. Она осматривая свои ранки, покрывает себя пламенем и сжигает кровь. Раны восстанавливаются, однако идти все также тяжко. Пройдя за Истмарком, она садится в доме на пол. Выслушивала всех, но ничего не говорила. Она знает о вампирах лишь то, что через текущую воду пройти не могут и крупы обязаны рассыпанные собирать.*",112272,null],[114560,"2026-07-14T11:30:21",31,"а как он попал в дом? она ег пригласила?",114546,null],[114561,"2026-07-14T11:30:47",17,"— Ему не нужно приглашение.",112272,null],[114562,"2026-07-14T11:31:37",9,"— Его дом, его земля. На то чем владеет он сам правило не распространяется.",112272,null],[114563,"2026-07-14T11:32:20",7,"Немейя\n— Ребят, у вас крупы есть? Если их смешать и бросить, они не обязаны будут все это собрать?",112272,null],[114565,"2026-07-14T11:32:26",31,"- насоько я знаю, полное преображение в вампира возможно только через смерть обращаемого",112272,null],[114567,"2026-07-14T11:33:07",31,"- нам нужно больш информации, без этогог нам никак не вытащить Ирину из его лап",112272,null],[114568,"2026-07-14T11:33:58",17,"— Ты о чем это?",114563,null],[114572,"2026-07-14T11:34:40",9,"— Не верь всему из народа, чеснок скорей всего не подействует. — *Смотрит на ретивого крестьянина.*",114563,null],[114574,"2026-07-14T11:35:01",31,"//мне кажется что фишка с тем что вампри крупу собирать должен это только на тупых упырей срабоатет. это слишком умный//",112272,null],[114576,"2026-07-14T11:35:34",9,"//Ты обмащался чесноком? Вампир — \"Мммм, уже приправленно\"",114574,null],[114577,"2026-07-14T11:35:36",7,"Немейя\n— У нас был один охотник на нежить, в приюте. Он рассказывал про вампиров, а я просто слушала. Может поможет, я не знаю. Помимо этого не может через ручей они не могут пройти, текучая водичка типо. Что ещё там было...",112272,null],[114580,"2026-07-14T11:36:17",17,"— На счет крупы не слышал, про воду, да. Слухи ходят у озера что-то случилось.",112272,null],[114581,"2026-07-14T11:36:28",17,"/Длинный отдых",112272,null],[114583,"2026-07-14T11:36:33",31,"- самое дейстенное - это кол в сердце\n\n*посматриваю на ручку своих вил и подумываю, что надо бы заострить. на всякий случай*",112272,null],[114584,"2026-07-14T11:37:41",17,"— В Багровой не безопасно. Граф тут хозяйничает как хочет. Но есть один городок. Валаки. Говорят там нет власти графа. И люди живут спокойно. Интересно - как?",112272,null],[114586,"2026-07-14T11:40:21",7,"Немейя\n— Угу, не во власти графа — во власти каких нибудь политических шишек инквизиции. Спокойно или нет, зависит от правителей.  Честно говоря, я идей не могу придумать... Он магию здесь контролирует, мое пламя голубым стало... Будто...",112272,null],[114588,"2026-07-14T11:41:37",9,"— Полный контроль? Ты бы не зажгла и свечу, скорее частичный. — *Высказал вслух мысль.*",114586,null],[114589,"2026-07-14T11:41:38",17,"— Как погребальное пламя. Когда сжигаем мертвецов, пламя такое же становится. Поможете мне похоронить отца? Его нужно отпеть в церкви и сжечь на погребальном костре",112272,null],[114590,"2026-07-14T11:42:07",17,"— Я заплачу...",112272,null],[114591,"2026-07-14T11:43:21",9,"*Просто кивнул, о деньгах? Пока не нужны и брать не собирался если там копейки, просто сделает.*",112272,null],[114593,"2026-07-14T11:43:53",7,"*Немейя хотела с радостью сказать, что она с радостью бы сожгла, однако... Она меняет тон и встает.*\n\n— Я помогу... Поможете подготовить все? И если есть, что сказать.. Можешь сейчас отцу сказать. Я подожду.",112272,null],[114594,"2026-07-14T11:45:49",31,"- я помогу. денег не нужно",112272,null],[114595,"2026-07-14T11:46:22",17,"— Носилки, которые потом на погребальный костер водрузим сколочу быстро. А вы пока отдыхайте. Нужно будет отнести тело в церковь на холме. Там дорога скользкая нужна будет помощь. Отец Донавич проведет обряд упокоения. И у церкви на заднем кладбище сожжем его бренное тело.",112272,null],[114596,"2026-07-14T11:46:47",17,"Исмарк кладет руку на холодную руку своего отца и смотрит ему в закрытые очи \n\nВздыхая печально",112272,null],[114597,"2026-07-14T11:47:06",9,"//Длинный защитать отдых? Звучит как короткий)",112272,null],[114599,"2026-07-14T11:49:32",17,"/ Длинный, Исмарк без сил, утром пойдёте",114597,null],[114601,"2026-07-14T11:50:50",7,"*Немейя не понимает по нормальному тоску Истмарка, да и не будто бы плевать не должно... Она встает и подойдя, трогает его по плечу.*\n\n— Эй, не расстраивайся. Все поправимо, я без денег согласна помочь. Лично я да. Однако ты возьми себя в руки, тебе есть что защищать. Учитывая, как ты будучи муравьем доставил неприятностей человеку, он бы гордился тобой. Ты будешь примером для окружения, чтобы не впали все в пустоту.",114596,null],[114603,"2026-07-14T11:51:43",17,"— Мне сестру нужно спасать, как то... Но тут столько еще людей, они пропадут. Это терзает моё сердце.",114601,null],[114605,"2026-07-14T11:53:22",7,"Немейя\n— Сестру доверь тем, кого сам пошлёшь. Двоя — троя согласны помочь чуть ли не просто так. Дальше только дело за тобой, ты должен решительно заняться своим поселением. Стражников набрать, людьми заняться.",112272,null],[114611,"2026-07-14T11:55:05",17,"/Убеждение",114605,null],[114613,"2026-07-14T11:55:28",7,"/r d20 +6 воодушевляем",112272,null],[114616,"2026-07-14T11:55:31",31,"- а еще ты местный. и можешь рассказать о том, что тут и как. может и людей знаешь, кто сможет или захочет помочь",112272,null],[114617,"2026-07-14T11:55:31",17,"/ С преимуществом, он сам понимает что людям больше пользы принесет чем в попытке суицидальной найти сестру",112272,null],[114619,"2026-07-14T11:55:44",7,"/ туда",114618,null],[114621,"2026-07-14T11:56:52",17,"— В деревне людей мало, в основном фермеры, у нас нет тут мануфактур. Есть церковь, там отец Донавич, можете зайти помолиться. Я бы вам советовал дойти до городка Валаки, всё таки почему их граф не трогает? Я бы начал оттуда",114616,null],[114628,"2026-07-14T11:59:53",31,"- тогда после похорон пообщаемся со святым отцом. А потом уже отправимся в город",112272,null],[114630,"2026-07-14T12:01:27",17,"Твоя собственная речь вдохновила не только Исмарка но и тебя саму\n\nОн развернулся и взглянул на тебя. Уверено кивнул. \n\n— Ты права, я знаю что должен делать. Я не опущу руки, не сдамся. Я начну возрождение деревни, соберу ресурсы и буду пытаться любыми способами вернуть сестру. Если есть такие авантюристы готовые помочь, значит надежда не умрёт.",114618,null],[114632,"2026-07-14T12:01:36",17,"/Немейя получает вдохновение",112272,null],[114634,"2026-07-14T12:02:27",60,"—Почему-то мне кажется..\n\nНачинает хрипло Альф\n\n—Что деревню надо бы переместить чуть-чуть за линию ГНИЛОГО ТУМАНА И ГРЕБАННОЙ НЕЖИТИ, нет?",114630,null],[114636,"2026-07-14T12:06:54",60,"Альф поднимается на ноги, тяжело вздыхая и кряхтя\n\n—И совесть свалить отсюда мне не позволяет... Ладно. Можешь считать, Исмарк, что я с тобой.\n\nФирболг подходит ближе, кладёт тяжелую ладонь ему на плечо\n\n—Что скажешь делать, то и буду делать. Ибо без этого делать мне нехер. Совсем. Быть может этот туман и магия немного ослабят влияние той херни, которую я видел. Оптимизм тут в говно, но страдать и плакать я точно не собираюсь. Напишем свою мелодию и сами под неё спляшем.",112272,null],[114637,"2026-07-14T12:10:45",9,"//Я помню с преимуществом кинул спас ловкости варваром. 2 куба чистые 20 😏👌",112272,null],[114638,"2026-07-14T12:10:54",17,"— Тут есть проблема. Туман он... живой. Кто в него уходит не возращается живым. Но вот его ходячий труп часто потом бродит без цели. Войти в графство можно. Выйти нельзя. Только с разрешения графа. И есть еще тут народ, цигане. Они по какой то причине могут ходить через туман, привозят бывает вина, ткани и продают тут по деревням и в городах.\\",114634,null],[114639,"2026-07-14T12:12:33",60,"—Так вот о каком гостеприимстве говорил этот урод.. Каким хером он вообще граф? Ему нравится людей мучать? У вас тут суицид не распространен?",114638,null],[114640,"2026-07-14T12:12:39",9,"— Древний народ, знает намного больше. — *Коментарий о цыганях.*",112272,null],[114641,"2026-07-14T12:13:23",9,"— Я быв в Веспирали. Люди в графстве в сравнении ещё неплохо живут.",114639,null],[114642,"2026-07-14T12:14:39",31,"- Интересно, если цыгане могут ходить через туман, то могут ли они вывезти кого то отсюда?",112272,null],[114643,"2026-07-14T12:15:13",60,"//в багажнике и в узбекистан — да, могут",114642,null],[114644,"2026-07-14T12:15:23",60,"//но точно ли оно тебе надо?",112272,null],[114646,"2026-07-14T12:16:15",60,"—Странная штука. Я спокойно жил у себя в клане, пока не увидел скользкое многоглазое говно.",114641,null],[114648,"2026-07-14T12:21:53",9,"— Этим людям некуда идти. Соседи не пускают беженцев за окрестности проклятого города Веспираль. Люди болеют, умирают а нежить обнимается с живыми и часто сохраняет разум. Я читал историю возникновения этого места, могу немного расказать, но это ничего не даст. Просто знай что солнце и надежда не достигает этих земель. Выехать можно только дорого контрабандой или имея связи извне. — *Задумался и кивнул.* — Я могу покинуть Веспираль, но не посвящённым в таинства этот способ недоступен, легче заплатить контрабандистам или торговцу. А с туманом. — *Прикинув в уме описание Исмарка.* — Не могу вспомнить, не встречался с таким, нужна помощь древнего народа, цыган, раз они знают секрет.",114646,null],[114649,"2026-07-14T12:22:24",9,"//Если что, у моего перса о влияния на этой локе, не расчитывайте)",112272,null],[114650,"2026-07-14T12:23:04",17,"— Спасибо. Я ценю. Правда.",114636,null],[114651,"2026-07-14T12:23:54",17,"— Лучше узнать у них, я не знаю. Может стоило раньше обратиться к ним, чтобы увезти Ирину. Но странно, что граф их не трогает.",114642,null],[114652,"2026-07-14T12:24:36",7,"/ ребят, я щас вернусь",112272,null],[114653,"2026-07-14T12:24:41",31,"в оющем, три точки интереса - священник, город и цыгане//",112272,null],[114654,"2026-07-14T12:24:42",7,"/ меня забирают",112272,null],[114655,"2026-07-14T12:24:55",7,"/ не теряйтк",112272,null],[114663,"2026-07-14T12:58:10",17,"/ Я в больницу отъеду, буду писать по возможности, можете познакомиться между собой теснее пока",112272,null],[114664,"2026-07-14T12:59:56",7,"/ я пока рыбачить не начал, могу отписывать",112272,null],[114693,"2026-07-14T14:20:46",17,"/ Такс ну чё всем похуй чё это за тифлинг крылатый демон, чё это за амбал с огромным дрыном, чё это за парень в маске и цепях, который появился внезапно \n\nНу крестьянин понятный человек))",112272,null],[114694,"2026-07-14T14:21:19",60,"//ща я доиграл дуэльку чуть-чуть глазки отдохнут и буду писать",112272,null],[114695,"2026-07-14T14:21:24",60,"//верно эля сказала",112272,null],[114699,"2026-07-14T14:23:09",9,"//Ну я пытался с Альфом поговорить, он не в настроении. А тифлингша ток если сама подойдёт, мы вродь поболтали немного пока но демоны и полудемоны для аасимара воспитанного как защитника не слишком)",112272,null],[114702,"2026-07-14T14:24:32",60,"//поговорит, у него сейчас самый сок",114699,null],[114727,"2026-07-14T14:50:13",9,"//Я тод оф на час или два, считайте перс задремал",112272,null],[114739,"2026-07-14T15:12:27",60,"—Эу, сколько реплик.. Я немного не географ. Я Альфарий. У меня есть меч и жажда жизни. А пока они есть, со мной будет и надежда. И, мать вашу, даже в этом тумане гребаная надежда не сдохнет! Погуляем, посмотрим, что тут можно сделать. Может и фронт работ нам обозначат, раз свалить отсюда так просто нельзя. Хочу уйти громко хлопнув дверью, но не оставшись чмом.\n\nАльфарий как следует выспался. Проколы от клыков на его теле практически полностью зажили благодаря чудесному существу голубой крови, поставляемой из той самой жемчужины, которая, видно, действительно прижилась где-то внутри фирболга.",114648,null],[114761,"2026-07-14T16:37:54",7,"*Немейя почувствовав некое удовлетворение, кивает Истмарку. Она похлопала по спине его и пошла к остальным ребятам. Осмотрев каждого, она начала обдумывать свои будущие перспективы и отношения с остальными. Однако уснула. Проснушвись  в отряде, она осмотрелась.*\n\n— Хей ребят... Всем добрейшего утра... Давайте друг другу представимся. Столько пережили, немного друг о друге расскажем. Мы же в ближайшее время команда, распределим роли и просто поболтаем. Как сказал Альфарий, как раз прогуляемся и осмотримся. \n\n*Говорит девушка, потянувшись спиной и крыльями. Голос был спокойным и бодрым, некотором смысле нежным.*",112272,null],[114762,"2026-07-14T16:38:06",7,"/ я чутка пост поменял, извините что пропал, вроде предупреждал",112272,null],[114763,"2026-07-14T16:38:27",17,"/ Да все норм. Вам бы тут познакомится вот да",112272,null],[114764,"2026-07-14T16:42:19",60,"—Мы знакомы один вечер. И одна смертельная битва это тоже не \"столько пережили\". Я не понимаю, откуда черпается такой оптимизм. Но у тебя есть крылья.. Летать это круто. Но варвары не умеют летать. Наша участь дарить мимолётный полёт другим, не в силах взлететь самостоятельно. Шучу, ля.",114761,null],[114765,"2026-07-14T16:42:20",7,"/ этим и займусь, как общительная и безбашенная дама с огоньком",112272,null],[114766,"2026-07-14T16:45:28",17,"/ Как будете готовы перейти далее к похоронам. Сообщите",112272,null],[114767,"2026-07-14T16:46:48",7,"*Слегка приулыбнувшись от смеха, Немейя отвечает.*\n— Черпаю с подобных шуток оптимизм. Как никак, не плакать же примерно всегда. И между прочим, знакомы уже довольно таки долго хотя бы для знакомства. Я же сгораю от любопытства, кто из вас каждый себя представляет.",114764,null],[114776,"2026-07-14T17:28:05",9,"— Ридли. Хранитель, посвящённый в таинства, не путайте с посланниками Тёмного Спасииеля, разум мой чист. — *Наконец нормально представился парень и протянул неестественно белую, идеальную руку из под подолов мантии Альфарию, лишь следы от цепей слегка омрачали мрамор кожи.*",112272,null],[114777,"2026-07-14T17:29:02",60,"—Я уже сказал, что я Альфарий.\n\nВарвар ждёт руку без особого фанатизма: тут это неуместно",114776,null],[114779,"2026-07-14T17:29:35",60,"—И я впервые слышу про спасителя. Как будто в изоляторе жил все свои годы..",112272,null],[114780,"2026-07-14T17:30:03",9,"*С тифлингом ограничелся лишь кивком, не сильно распинался. Немного видно неприязнь, но он её скрфвает, это скорее в подкорке заложенно где-то.*",112272,null],[114781,"2026-07-14T17:30:57",9,"— Веспираль в изоляции от внешнего мира. Наоборот — просто не туда попал.",114779,null],[114803,"2026-07-14T17:50:24",31,"- я Тарх. Я просто крестьянин, сам не очень понимаю что тут забыл, но мне везет на всякую нечисть. На родине, в Элазии, сейчас половина страны под некромантами, там я с этим боролся, партизанил, пока не попался и не был отправлен на корм вампиру. Выжил чудом, меня вытащили какие то странные ребята, которые того же вампира уработали. Я решил, что это был знак свыше и свалил куда подальше. От Лича к мать его, вампиру. Судьба видать такая",112272,null],[114804,"2026-07-14T17:50:25",7,"/ на проницательность хочу кинуть, дабы увидеть что не так",114780,null],[114809,"2026-07-14T17:52:21",9,"//Сложность 8)",112272,null],[114810,"2026-07-14T17:52:22",7,"/r d20 +2",112272,null],[114812,"2026-07-14T17:52:33",31,"- чутка умею лечить, только вот удар держу слабо. Мне лучше за спиной у кого то большого и крепкого быть, если что подлечу, ну или вилами прикрою. Их бы еще навозом помазать, чтобы раны гнойные выходили...",112272,null],[114814,"2026-07-14T17:55:23",9,"*Твоя раса, тифлинг, проблемы с этим. Правда Ридли не агрессирует, скорей игнорирует и старается не обращать внимание на это.*",114804,null],[114815,"2026-07-14T17:55:36",60,"—Стой, что, кто?\n\"Лича\" и \"вампиру\" это что?\n\nПохоже кое-кто даже сказок не читал.",114803,null],[114816,"2026-07-14T17:56:24",9,"— Могущественная нежить.",114815,null],[114817,"2026-07-14T17:57:11",9,"//Вопрос, дм позволит еду достать из сосуда себе и поесть? Я просто ничего об этом не нашёл нормально.",112272,null],[114818,"2026-07-14T17:57:15",31,"- Лич это мертвый колдун, на юге моей страны много почитателей у одного из них",114815,null],[114819,"2026-07-14T17:57:16",60,"—Да екарный бабай, ещё больше оживших трупаков...",114816,null],[114820,"2026-07-14T17:57:23",9,"//Хочу паёк списать.",114817,null],[114821,"2026-07-14T17:57:40",31,"- говорю же, везет мне на них. Ну или весь мир у нас такой, говенный",114819,null],[114823,"2026-07-14T17:58:34",60,"—Я впервые вижу ползучих мертвецов.. Хотя это возможно лучше чем летающие осьминоги размером с дом..",114821,null],[114824,"2026-07-14T17:59:18",7,"*Немейя с интересом слушала ребят. Про синего здоровяка она итак знала... По крайней мере имя помнила... Старалась... Имена тяжело запоминаются... Послушала Тарха, нашла некую иронию, что и сам наемник подметил. Также послушала Ридли... Она чувствовала какое то предвзятое отношение, но после зажигает с щелчка пальцев пламя. Яркое и ослепительное пламя, что выглядит довольно таки необычно.*\n\n— Я Немейя. Если тяжело мое имя будет произнести, то можете называть просто Пламя. Я скажем так в прошлом сиротка, в текущем наёмник. У меня проблема к пламени, если небрежно выразиться — фанатизм. Не знаю откуда, но мне просто нравится. И вообще, я люблю смотреть как горит огонь, также болтать, если выдаётся возможность. Очень приятно с вами познакомиться, мальчики. Надеюсь, что конфликтов у нас не будет, стараюсь не обижать товарищей. Я умею... Лечить и сжигать заживо. В ближнем бою еще более опасна, но отсутствие брони делает все грустным.",112272,null],[114827,"2026-07-14T18:03:15",31,"Ну что, все познакомились, айда деда хоронить?/",112272,null],[114828,"2026-07-14T18:04:18",7,"/ только скажите, я сожгу деда",112272,null],[114829,"2026-07-14T18:04:38",17,"/ Занят ребят",112272,null],[114830,"2026-07-14T18:04:49",7,"/ ну я бы не отказался от социалки щас",114828,null],[114831,"2026-07-14T18:04:56",31,"Я так понимаю кго отпеть надо, и нам в церковь сгонять/",114828,null],[114832,"2026-07-14T18:05:13",17,"/ Отпеть в церкви",112272,null],[114833,"2026-07-14T18:07:58",9,"— Специализируюсь на демонах и нечисти. — *Счёлкнул пальцами и схватил пространство, там появился крохотный чертёнок с рожками и окологуманоидным телом, запахло серой, (шляпа вредителей, считайте крыса), парень его кинул на пол пока не цапнул. Оно тут же стало на ноги и боязливо начало убегать куда то в щель или в нору.* — Пока учусь. Имею несколько фокусов в запасе.",112272,null],[114837,"2026-07-14T18:12:13",7,"Немейя\n— Демонах говоришь? Хе-хе, я не демон, если что. Не перепутай меня, пожалуйста, хе-хе.",112272,null],[114840,"2026-07-14T18:14:06",9,"*Взглянул на неё.*\n\n— Склонны возвращаться к корням. — *Не хочет коментировать, слова не возьмут его, время нужно.*",114837,null],[114841,"2026-07-14T18:15:04",7,"Немейя\n— А что с моими корнями? У меня обычная семья... Вроде была... Не знаю, врать не буду.",112272,null],[114846,"2026-07-14T18:18:22",9,"— Время ответит. — *Не хочет обсуждать, он понимает что конфликт не вытянет, поэтому старается не обращать внимания на свои предрассудки.*",114841,null],[114848,"2026-07-14T18:21:11",7,"Немейя\n— Ты какой то не общительный. Если захочешь позже общаться, я готова всегда поговорить.",112272,null],[114872,"2026-07-14T18:25:40",9,"— Хорошо, запомню. Предлагаю пока просто заняться делом.",114848,null],[114876,"2026-07-14T18:26:28",9,"//Ещё актуально, я учитываю запас еды и туды сюды",114817,null],[114878,"2026-07-14T18:26:40",7,"/ мне мастер разрешал такие трюки",114876,null],[114879,"2026-07-14T18:27:11",7,"/ просто говорю как факт",112272,null],[114880,"2026-07-14T18:28:14",60,"—Ну времени у нас, грубо говоря, дохера. Успеем, теперь бежать некуда.. Если мы хотим дать деревне толчок, то надо толкнуть себя под задницу. У меня есть чудный дар.. Но я вообще хер знает, как его использовать. Деревья никогда мне не отвечают.",114872,null],[114884,"2026-07-14T18:31:25",7,"Немейя\n— А что у тебя за дар? Говорить с деревьями?",112272,null],[114903,"2026-07-14T18:42:12",17,"— Нам бы поесть чего нибудь\n\nИсмарк лезет в последний выживший шкафчик, достаёт два пайка и делит их пополам протягивает вам\n\n— Еды почти нет. Но чем богат тем и делюсь",114817,null],[114909,"2026-07-14T18:45:14",9,"//Мне разрешают вытягивать то что у меня?)",112272,null],[114912,"2026-07-14T18:45:34",7,"/ сгнило как прошло через туман",114909,null],[114913,"2026-07-14T18:45:37",7,"/ скорее всего",112272,null],[114914,"2026-07-14T18:46:43",9,"//То что в сосуде?",112272,null],[114916,"2026-07-14T18:47:27",9,"//Я жду когда дм решит, да или нет. А так хз",112272,null],[114921,"2026-07-14T18:49:59",17,"/ В сосуде не сгнило",112272,null],[114923,"2026-07-14T18:50:05",17,"/ Вытаскивай",112272,null],[114924,"2026-07-14T18:50:16",17,"/ Кто пирожок пробовал?",112272,null],[114925,"2026-07-14T18:51:08",7,"/ я планировал попробовать, вместо того, чтобы есть то что половину дали. Варвару нужнее будет",114924,null],[114926,"2026-07-14T18:51:25",9,"*Ридли сжимает край мантии, запонку из внутренней стороны, а в другой руке появляются полностью сухие хлебцы из каши, солонины и злаков.*\n\n//- 2 рациона",112272,null],[114929,"2026-07-14T18:52:56",9,"— Есть нужно полноценно, поделюсь. Только бы сварить в чём-то.",112272,null],[114930,"2026-07-14T18:53:31",17,"— Котелок найдется очаг тоже уцелел.",112272,null],[114932,"2026-07-14T18:53:39",17,"/Ток как ты хлебцы вариать собрался я не пон",112272,null],[114933,"2026-07-14T18:53:44",9,"*И правда, это были скорее козинаки в солоду и меду, чтобы не портились, твердые, а вот если разварить.*",112272,null],[114936,"2026-07-14T18:54:27",9,"//Там тупо каши с добавками и хнёй всякой, можно и в сухомятку но зубы спасибо не скажут)",114932,null],[114937,"2026-07-14T18:55:22",17,"Исмарк даёт тебе котелок с водой и показывает на очаг где есть немного дров и можно котелок повесить",112272,null],[114938,"2026-07-14T18:55:48",7,"*Немейя отвлекается и начинает с интересом наблюдать за тихоней хранителем. Она смотрела и наблюдала за процессом постепенной готовки.*",112272,null],[114939,"2026-07-14T18:55:50",9,"*Ридли занимается готовкой, получается немного сладкая каша с курагой. У него есть и другие... но он не намерен есть солёное сейчас.*",114937,null],[114941,"2026-07-14T18:56:19",17,"/Спичек не найдется?",114938,null],[114946,"2026-07-14T18:57:53",7,"/ достаточно коснуться",114941,null],[114948,"2026-07-14T18:59:41",9,"*Ридли оьматывает цепи вокруг рук, те немного греются и искрят, пока дерево не загорится. Это не магия, не совсем, сила откуда-то.*\n\n//Сосуд то ифритовский 😏👌",112272,null],[114952,"2026-07-14T19:00:58",31,"Я",114924,null],[114953,"2026-07-14T19:00:59",17,"/Ты представляешь как ты без ожогов сам? Может уступить разведение огонька пироманту, с цпями мува не понял",114948,null],[114956,"2026-07-14T19:01:29",9,"//Типа атакую дерево и 1 урона огнем механически",112272,null],[114957,"2026-07-14T19:01:55",17,"/ )) атакер",112272,null],[114958,"2026-07-14T19:01:59",17,"/ Ладно пофиг",112272,null],[114965,"2026-07-14T19:02:49",7,"*Немийя смотрит на извращенный способ сожжения и просто ожидает. Она наблюдает за огнём почти не моргая, иногда осматривая процесс готовки.*",114948,null],[114966,"2026-07-14T19:03:07",9,"//Эта хня годится чтобы поджигать основном, бонус мастерства 1, и 1 огнём в итоге, используем как можем",112272,null],[114969,"2026-07-14T19:04:35",9,"— Огонь ифрита. — *Коротко обьяснил откуда это пока готовил.* — Дар, пока он ничего не может сделать. — *Обтяснять что это дар пленённого ифрита против его воли он не собирался ^^ .*",114965,null],[114977,"2026-07-14T19:06:13",60,"//Йа",114924,null],[114998,"2026-07-14T19:11:12",9,"*Всё таки немного то ли смущало, то ли раздражало что за ним так внимательно наблюдают.*",114969,null],[115001,"2026-07-14T19:12:00",7,"/ как ты получил плюшки от и Нежити и Гения, не ясно",114966,null],[115002,"2026-07-14T19:12:02",7,"/ но ладно",112272,null],[115008,"2026-07-14T19:14:23",9,"//Как обыватель мог выбрать 3 навыка, но взамен ток с ними. Короче этот перс лорно воспитан типа в культе Багрового Савана, оттуда и нахватался с чем контактировал. Но бля, все это не скейлится и не улучшится, он слаб. Попробуй набери 20 лвлов чтобы стать приключенцем первого)",115001,null],[115011,"2026-07-14T19:15:04",7,"/ тоесть обыватель этот лвл ап не получит",115008,null],[115013,"2026-07-14T19:15:37",9,"//Если интересно, могу то хб дать почитать, там немного. Го тут не флудить",112272,null],[115015,"2026-07-14T19:16:38",7,"/ во флуд скинь",115013,null],[115017,"2026-07-14T19:18:06",7,"*Немейя просто наблюдала и за огнем и за процессом готовки. В глазах будто искриться желание лишь наблюдать пристально. Слова не прошли мимо, однако она выглядела довольно таки странной даже.*",114998,null],[115020,"2026-07-14T19:18:36",17,"/ Мне нужно оф. Все кто ел пирожки. Вам еда любая кажется пресной. Невкусной и очень слабо насыщает",112272,null],[115021,"2026-07-14T19:18:52",17,"/ Но это кажется обычным. Непонятно что из за пирожков",112272,null],[115022,"2026-07-14T19:19:34",31,"Пирожки то небось непростые, чтоже за мяско там было? Оно мекало, бекало, хрюкало или задавало глупые вопросы?//",112272,null],[115025,"2026-07-14T19:20:17",31,"Раз мастер офф, то я т спасть пойду. Предлагаю завтра с утра похоронить таки деда и потрещать со священником//",112272,null],[115027,"2026-07-14T19:21:04",7,"/ я пока не против социалки",112272,null],[115028,"2026-07-14T19:21:28",60,"//на самом деле мы попали в арбу",115022,null],[115029,"2026-07-14T19:21:56",60,"//только если это действительно окажется арбой, то Альф сделает то же, что тогда сделали с арбой...",112272,null],[115034,"2026-07-14T19:26:22",9,"*Слегка сладковатая мультизлаковая каша от меда и солода с курагой. Она варилась до этого, а после была высушена и прожаренна в солоде и меду, поэтому сварилась быстро немного покипев.*\n\n— Держи. — *Немея слишком внимательно наблюдала, поэтому счел что ей нужнее или та голодна, насыпал побольше.*",115017,null],[115042,"2026-07-14T19:28:24",7,"*Увидев еду, Немейя обрадовалась. Она конечно была рада впервые за день поесть, однако огонь в ее глазах больше интереса давал. Даже когда останутся угли, девушка будет именно за ними и наблюдать. Так или иначе, прям на этом месте она начинает кушать.*\n\n— Вау, спасибо!",112272,null],[115048,"2026-07-14T19:30:57",9,"//Как подружиться с подозрителтным тифлингом? Покормите его.",112272,null],[115052,"2026-07-14T19:33:59",7,"/ с Немейей достаточно перед лицом поджечь спичку\nОна будет смотреть до тех пор на нее, пока та не потухнет, если не экстренная ситуация",115048,null],[115053,"2026-07-14T19:34:36",60,"//У меня в голове родилась настолько мерзкая идея теперь, что я ее даже озвучивать не хочу...",115052,null],[115057,"2026-07-14T19:35:11",7,"/ в лс",115053,null],[115058,"2026-07-14T19:35:21",60,"//НЕ-А",115057,null],[115059,"2026-07-14T19:35:28",7,"/ дыа",115058,null],[115061,"2026-07-14T19:35:43",60,"//я лучше пойду скинусь из окна",112272,null],[115062,"2026-07-14T19:35:58",9,"//Мне тожинтересно, но некоторые вещи лучше не знать ,)",112272,null],[115064,"2026-07-14T19:36:18",60,"//ля, когда-нибудь альф это сделает",112272,null],[115065,"2026-07-14T19:36:28",60,"//но точно не сейчас",112272,null],[115076,"2026-07-14T19:39:50",7,"/ а мне теперь интересно",112272,null],[115077,"2026-07-14T19:39:56",7,"/ и меня мало что удивляет",112272,null],[115078,"2026-07-14T19:40:04",7,"/ максимум подыграть моя могет",112272,null],[115094,"2026-07-14T19:56:21",31,"А если в ее присутствии не зажигать огонь, а цинично его тушить различными способами?/",112272,null],[115099,"2026-07-14T20:03:35",7,"/ боль",115094,null],[115104,"2026-07-14T20:05:32",31,"Вот и пытка от графа придумалась//",112272,null],[115113,"2026-07-14T20:08:16",7,"/ огнетушитель",115104,null],[115114,"2026-07-14T20:08:28",7,"/ рп будем ребят?",112272,null],[115720,"2026-07-15T05:41:56",31,"всем доброе утро. Во сколько продолжим?/",112272,null],[115721,"2026-07-15T06:11:27",7,"/ Добри, ну я скоро буду готов",112272,null],[115722,"2026-07-15T07:15:00",17,"Вы восстановили баррикаду, заколотили окна, для этого разобрали забор.\n\nИсмарк предложил вам несколько перин без кроватей, досточно мягких. Дл кого то возможно впервые пришлось спать на перине. Вы уложили их на полу.\n\nПеред сном вы пообщались и перекусили. Правда у некоторых все мысли были только о пирожках той странной бабушки.\n\nВ эту ночь каждый видел кошмар. Для каждого он был свой. Но выспаться хорошо это помешало. Так что каждый из вас проснулся все ещё уставшим, хоть и стало лучше немного.",112272,null],[115723,"2026-07-15T07:16:19",17,"Исмарк заварил травяной чай разлил по стаканам и передал вам. \n\nНосилки уже были готовы и он аккуратно переложил на них тело отца. \n\n— Пейте чай и будем начинать погребение. До церкви недалеко но идти в горку.",112272,null],[115724,"2026-07-15T07:37:50",31,"Залпом выпиваю чай\n\n- готов. Давайте уже отправляться",112272,null],[115725,"2026-07-15T07:42:58",17,"/ Обварился кипятком))",115724,null],[115726,"2026-07-15T07:43:48",31,"Помеха на социалку?)) молчу весь день, общаясь жестами?))///",115725,null],[115727,"2026-07-15T07:44:02",31,"Или бросаю на понимание спас мудрости?)//",112272,null],[115728,"2026-07-15T07:44:33",9,"*Чай и правда немного успокаивает, пил его не спеша. Кошмары, кошмары сталы уже как родные. Хоть и не самый сильный здесь, Парень помогает с носилками.*",112272,null],[115729,"2026-07-15T07:44:53",17,"/ Не будем на ровном месте жестить. Дождался пока остынет и залпом выпил это я так подкалыаю",112272,null],[115730,"2026-07-15T07:46:46",9,"//Мой дедушка пил кипяток, жив до сих пор. Типо кипела вода, наливал в чашку, килал заварку, минута, край две и уже пил этот окроп! Старики терминаторы какие-то, поверьте на слово.",115726,null],[115731,"2026-07-15T07:47:22",31,"У меня тесть так делает//",115730,null],[115732,"2026-07-15T07:49:22",17,"/ ну я на самом деле вспомнил, что у меня тоже дед так делал) Нервные окончания во рту сожжены были видать)",112272,null],[115733,"2026-07-15T07:53:42",9,"//Крестьянин вырастет варваром еси доживёт",112272,null],[115734,"2026-07-15T07:54:30",17,"На улице, как на зло, моросит дождь. Земля и камни остатки мостовой мокрые и скользкие\n\nПо тропинке на холм вы несёте носилки с телом бургомистра.\n\nВот уже видны большие двустворчатые двери церкви. Не вооруженным глазом заметны отметины от когтей на дверях.\n\nВнутри человек стоит и каменного алтаря на котором лежит книга он молится.\n\nРазруха. Скамьи поломаны частично, разбросаны. Часть габеленов святых на стенах порваны. \n\n— Отец Донавич. Проведите обряд упокоения для моего отца.\n\nСвященник поворачивается. Это престарелый мужчина в черной рясе. Видно что лицо его впалое, очень исхудавшее, цвет кожи серый. Под глазами черные мешки. \n\n— Конечно Исмарк. Принесите тело нашего бургомистра ближе к алтарю.",112272,null],[115735,"2026-07-15T07:55:10",17,"Священник отец Донавич.",112272,null],[115736,"2026-07-15T07:58:32",9,"//Священник отец Донатович! Донатьте не церковь 😎👍",115735,null],[115740,"2026-07-15T08:32:00",31,"Скорее всего да//",115733,null],[115741,"2026-07-15T08:33:46",31,"Тащим гроб на отпевание видимо/",112272,null],[115742,"2026-07-15T08:34:40",7,"*Как только девушка получила на руки чай, она начала его пить мгновенно. Чай слегка успокаивал, но вкус заставлял чаще это пить.*\n\n— Спасибо за чай, тёпленький. С кашей самое то. Мёда не хватает добавить в чаёк. \n\n*С этими словами девушка выпила чай в течении одной минуты. После положила кружку на столик и начала морально готовиться к скучному отпеванию.*",115723,null],[115743,"2026-07-15T08:34:50",7,"/ а я считай залпом выпил",112272,null],[115744,"2026-07-15T08:34:54",7,"/ ь",112272,null],[115746,"2026-07-15T09:02:20",60,"//да я сам так делаю...",115730,null],[115747,"2026-07-15T09:17:00",7,"/ я обожаю кипяток, про меня шутят, что у меня огнестойкость из майна, когда в бане два часа сидел и не хотел выходить",115746,null],[115748,"2026-07-15T10:14:05",31,"*берусь за гроб, видимо вместе с Исмарком, несем его к алатарю*",112272,null],[115749,"2026-07-15T10:17:20",7,"/ ну у меня 8 силы, я не буду таскать",115748,null],[115750,"2026-07-15T10:18:47",60,"Альф спокойно поднимает гроб и несёт куда надо",115748,null],[115757,"2026-07-15T11:41:23",17,"Отец Донавич берет книгу в руку в другой у него цепь с крестом\n\nОн начинает борматать молитву, обрывки фраз и непонятный диалект\n\nВы все стоите около тела ожидая завершения обряда\n\nВ этот момент из под досок пола вы слышите громкий крик, голос молодого юноши искаженный агонией\n\n— ОТЕЦ! ПРОШУ ПОКОРМИ МЕНЯ! Я ГОЛОДЕН, ОТЕЕЕЕЦ!",112272,null],[115758,"2026-07-15T11:41:39",17,"Священник не обращает внимания продолжает молитву упокоения",112272,null],[115759,"2026-07-15T11:49:56",60,"Альф слегка наклоняет голову, глядя через плечо священника на предположительный вход в подвал. Сейчас он мешать не будет, ибо прерывать молитву просто так нельзя. Но отметит это, как только чтение закончится",115757,null],[115760,"2026-07-15T11:51:36",60,"//можно проницательность на реакцию священника, если он пытается скрыть эмоции, или ему просто пофиг?",112272,null],[115761,"2026-07-15T12:01:15",17,"/ Можно не спрашивать и кидать. Это всегда привествуется",115760,null],[115762,"2026-07-15T12:02:52",31,"Ну, некоторым мастерам не нравится когда кидают кубы просто так//",115761,null],[115763,"2026-07-15T12:03:39",17,"/ мне нравится. Любую заявку обработаю по броску и дам полезной инфы",112272,null],[115764,"2026-07-15T12:03:52",17,"/ Если совсем не в тему так и скажу. Это тут не подойдёт замени на",112272,null],[115765,"2026-07-15T12:10:09",60,"/r +1",115761,null],[115767,"2026-07-15T12:10:26",60,"/r +3 а это внимательность чтоб найти спуск вниз",112272,null],[115770,"2026-07-15T12:37:53",17,"Он точно знает кто кричит. Для него это кажется обычным. Пытается не обращать внимания. Он смертельно устал.",115762,null],[115771,"2026-07-15T12:38:14",17,"Дверь в подвал видно невооруженным глазом",115767,null],[115772,"2026-07-15T12:42:51",60,"//у меня даже при себе еды нет, выходит",112272,null],[115773,"2026-07-15T12:43:46",60,"Альф немного хмурится, но по-прежнему не вмешивается. Ждёт конца.",115770,null],[115774,"2026-07-15T12:49:30",17,"Молитва продолжает. Продолжаются и крики\n\n— ОТЕЦ! ТЫ ДОЛЖЕН ПОКОРМИТЬ МЕНЯ! МНЕ ПЛОХО ОТЕЦ! Я ТАК ДАВНО НЕ ЕЛ!\n\nУдары.\n\nСнизу в доски пола кто то бьёт с силой и яростью. Этого не достаточно чтобы пробить пол, но доски подпрыгивают и вы чувтвуете эти толчки.\n\nБУМ\n\nБУМ\n\nБУМ",112272,null],[115775,"2026-07-15T13:06:00",60,"Альф тихо отходит от процессии и приоткрывает дверь подвала, если она не заперта. Если заперта, то говорит\n\n—Эу, пацан, подожди немного. Тут мужик помер, ща дочитает твой отец молитву и будет еда.\n\n//Сколько ему лет по голосу?",115774,null],[115776,"2026-07-15T13:06:53",17,"/ 16-18",115775,null],[115777,"2026-07-15T13:07:21",17,"Дверь заперта на ней засов и амбарный замок.",115775,null],[115778,"2026-07-15T13:08:04",17,"— Дядя, я умираю с голоду, прошу вас, умоляю, покормите. ОТЕЕЕЦ Я ГОЛОДЕН, УМОЛЯЮ! ДАЙ МНЕ ПОЕСТЬ!",115775,null],[115779,"2026-07-15T13:09:07",60,"//сколько предположительно времени до конца отпевания осталось?",115778,null],[115780,"2026-07-15T13:10:49",17,"/ Давай подойждем по 1 посту от каждого или скип если они не хотят и я сразу закончу отпевание",112272,null],[115781,"2026-07-15T13:11:09",60,"@QURTZZ Hard @Evreiskui_Department",115780,null],[115802,"2026-07-15T13:28:39",31,"Заканчиваем отпевание и зададим святому отцу пару вопросов, что тут за херня творится?/",112272,null],[115803,"2026-07-15T13:29:54",9,"//Ща ща, ток вернулся",112272,null],[115806,"2026-07-15T13:32:20",9,"— Молитву прерывать нельзя, у меня есть еда, всегда готов делиться с страждущими. — *Бормочет под нос, едва слышно, он часто ждал сам. Иногда дольше чем мог выдержать.*\n\n*Голова слегка наклоняется, он хочет понять откуда звук, это совсем рядом с ним? Парень его услышит если он негромко скажет?*",112272,null],[115808,"2026-07-15T13:34:47",17,"Звук из подпола, там подвал или что то такое.",115806,null],[115810,"2026-07-15T13:35:51",9,"*Взгляд на отца и Исмарка, те просто не реагируют и заняты своим делом?*",112272,null],[115830,"2026-07-15T13:46:10",17,"Нет. Исмарк озирается по сторонам и на пол, он тоже знает что молитву нельзя прерывать, но эти крики... Его пугают.",115810,null],[115833,"2026-07-15T13:46:33",9,"//Исмарк, Ирина, а забрали кого?",112272,null],[115836,"2026-07-15T13:50:12",7,"/ я через минут 10-15 появится смогу ,_,",112272,null],[115842,"2026-07-15T13:54:15",17,"/Да да) Тут ошибочка Ирину забрали я тупанул",115833,null],[115843,"2026-07-15T13:54:23",9,"*Раз отец занят и не смотрит, тихо меняет местоположение и становится там где шам из под полы. Немного прилегает к доскам и говорит.*\n\n— Подожди немного. Закончится молитва я сам попрошу чтоьы отец тебя покормил.",112272,null],[115845,"2026-07-15T13:54:55",9,"*Ридли ещё не разобрался в ситуации, поэтому более не обещал, и постарался тихо вернутся на место.*",112272,null],[115850,"2026-07-15T13:56:38",17,"— НЕ МОГУ ЖДАТЬ! Я УМИРАЮ С ГОЛОДУ! ОТЕЕЕЦ ПОСЛУШАЙ ИХ! ПОКОРМИ МЕНЯ!",115843,null],[115856,"2026-07-15T13:58:14",31,"Тарх, философски:\n\n- раз ечть силы орать, значит и подождать чуток сможешь",112272,null],[115864,"2026-07-15T14:01:40",9,"— Не трать силы или голод убьёт тебя быстрее. — *Дал совет и стоит ждёт окончания молитвы.*",115850,null],[115875,"2026-07-15T14:11:51",7,"*Немейя стоит в сторонке. Она не любит грустные места, особенно похороны. Кроме скуки ничего не навязывают, только грусть и тяжесть на душу кладут. Она начала искать ветки в округе, дабы их поджечь и наблюдать за тем, как они горят.*\n\n\" Не люблю такие такие моменты. Никогда не нравились похороны. \" ( Мысли ) \n/ Немейя рядом походит, такие моменты только в тоску вгоняют",112272,null],[115876,"2026-07-15T14:13:47",17,"Заканчивается молитва \n\nИ священник закрывает книгу.\n\n— Теперь...\n\n— ОТЕЦ! ПОЖАЛУЙСТА! ПОКОРМИ!\n\n— Теперь нужно сложить погребальный костер и сжечь тело. Да будет душа его в лучшем мире свободна.",112272,null],[115877,"2026-07-15T14:14:18",17,"— ОТЕЕЕЕЦ\n\nСнова удары прямо под Ридли\n\nБам\n\nБам\n\nБам",112272,null],[115878,"2026-07-15T14:15:36",9,"— Аминь. — *Помолчал немного  а потом спросил.* — Это ваш сын или послушник церкви святой отец? — *Прямо указал на шум внизу.*",115876,null],[115881,"2026-07-15T14:18:48",7,"*Немейя краем уха услышала про костёр. Она услышав что то ей интересное, подходит к погребальному костру и ждёт, когда деда положат.*\n\n\" А вот смотреть, как горит огонь, могу всегда. \"",112272,null],[115882,"2026-07-15T14:19:05",17,"Он нехотя тебе отвечает понимая отпираться бессмысленно \n\n— Да, мой сын. Он... Заболел.",115878,null],[115883,"2026-07-15T14:20:01",17,"Ты замечаешь как по главной улице города идут толпы мертвецов в ржавых доспехах, с рваными флагами. Они волочат свои туши медленно в сторону дороги к замку графа.",115881,null],[115887,"2026-07-15T14:23:31",9,"*Кивает.*\n\n— Могу сделать небольшое пожертвование в церковь, у меня нет злата и серебра, но еду похоже здесь не просто достать. Прошу, покормите своего сына. — *Достаёт из подола рукава все ещё порванной мантии еще один паёк, этот более мясной из солонины и все так же упакован связан нитью в провосчёную бумагу.* — Уверен дело не только в этом, но я пообещал что попрошу вас его покормить. Своё обещание я выполнил.",115882,null],[115888,"2026-07-15T14:23:55",9,"//Все так же из сосуда, - 1 рацион",112272,null],[115890,"2026-07-15T14:25:12",17,"— Смиренно вас благодарю",115887,null],[115892,"2026-07-15T14:25:25",31,"- святой отец, а чем болен ваш сын? И какой именно голод его мучит?\n\n*выделяю слово голод голосом\"",112272,null],[115893,"2026-07-15T14:26:22",17,"— Я точно не знаю. И поэтому изолировал его. Врачей из Валаки я так же не дождался. Сейчас пускать к нему их опасно, он стал... Буйный.",115892,null],[115894,"2026-07-15T14:26:55",7,"*Немейя увидев зомби, что идут с разными флагами, вначале даже вздрогнула.*\n\n— Эй, ребят... А это нормально?\n\n*Она пальцем указывает на зомби в главной улице города.*",112272,null],[115897,"2026-07-15T14:28:29",9,"*Посмотрел в ту сторону, не слишком предал этому значения. Скорее всего \"парад нежити, граф хвастается армией\", вернулся к разговору.*",115894,null],[115899,"2026-07-15T14:28:37",17,"Исмарк отвечает \n\n— Не подходите близко и все обойдется. Это последний штурм мертвецов. Каждый четверг мертвецы идут в свою последнюю атаку на замок Ривекрофт. Резиденцию графа. Куда он увез мою сестру. \n\n— Издевательская шутка от графа. Они снова и снова терпят поражение.",112272,null],[115900,"2026-07-15T14:30:28",9,"— Было восстание и граф напоминает всем чем оно закончилось. — *Пробормотал догадку под нос, и просто кивнул.*",112272,null],[115901,"2026-07-15T14:30:37",7,"*Немейя смотря на этот недоштурм... Обдумывает какой будто бы план. Раз они штурмуют, то можно... Можно попытаться пробиться по дороге, что вытоптана ими. Вначале умалчивает, дабы позже предложить. Из сумки она достаёт пирожок и осматривает его со всех сторон.*\n\n— Выглядит вкусно... Но удержусь... Может кто голодает.",112272,null],[115902,"2026-07-15T14:31:03",17,"— Я пока соберу древесину для костра отец Донавич.\n\n— Да, юноша, прошу поторопитесь\n\nОтец Донавич пошатывается и падает на Исмарка тот его ловит и ставит на ноги\n\n— Простите я... Просто устал",112272,null],[115904,"2026-07-15T14:33:31",17,"/ заявки?",112272,null],[115905,"2026-07-15T14:33:44",7,"*Услышав приказ, девушка начинает осматриваться. Где можно будет добыть дрова. Она смотрит налево, затем направо. Везде осматривается.*\n/ хочу помочь с дровами, чтобы деда сжечь",115904,null],[115906,"2026-07-15T14:33:57",17,"/ выживание",112272,null],[115907,"2026-07-15T14:34:01",7,"/r d20",112272,null],[115909,"2026-07-15T14:34:25",7,"/а еще спеть пока дед будет гореть песню про деда Максима",112272,null],[115910,"2026-07-15T14:34:38",17,"Забор у церковного сарая или отходить в лес",112272,null],[115912,"2026-07-15T14:36:00",7,"/ у забора дрова\nНайс",115910,null],[115913,"2026-07-15T14:37:04",7,"*Немейя взлетает при помощи крыльев и осматриваясь внимательней, обнаружила дрова у церковного сарая. Подлетая, она хватает бревна и сколько смогла утащить за два таких перелета, столько и потащила.*",112272,null],[115915,"2026-07-15T14:37:26",17,"/ забор и есть дрова. Надо его ломать",112272,null],[115917,"2026-07-15T14:38:41",7,"/ сжигать буду и таскать тогда",115915,null],[115919,"2026-07-15T14:38:55",7,"/ вместо топора прожигать забор",112272,null],[115920,"2026-07-15T14:39:28",9,"//Беда когда в пати пиромант камикадзе 😏👌",112272,null],[115921,"2026-07-15T14:39:32",17,"Исмарк помогает тебе понимая, что в лес идти плохая идея\n\n— Когда налажу дела в деревне. Я и забор восстановлю",112272,null],[115922,"2026-07-15T14:40:17",7,"/ такая и была задумка :>",115920,null],[115924,"2026-07-15T14:41:03",9,"— Простите за беспорядок отец.\n\n*Ридли идёт помогать, с того края где не зяняты, преимущественно не мешает, без фанатизма.*",112272,null],[115925,"2026-07-15T14:42:01",17,"Донавич присел на одну из ещё не разбитых скамей. \n\n— Ничего. Беспорядок это ерунда.",112272,null],[115933,"2026-07-15T14:45:03",17,"/ Ну видимо ждём Смита чтобы он сделал то что хочет. \n\nСтавлю что он вынесет дверь без стука",112272,null],[115935,"2026-07-15T14:46:14",7,"/ ставлю 100 баксов что он промолчит",115933,null],[115936,"2026-07-15T14:46:14",31,"- святой отец, позволите нам осмотреть вашего сына? Я чуток соображаю в лекарском деле, да и Немея тоже",112272,null],[115937,"2026-07-15T14:47:11",60,"//I'm here",115933,null],[115938,"2026-07-15T14:47:20",17,"— О... Может не стоит. Это может быть опасно. Он буйный, понимаете. Но не ведает что творит, бедный больной ребенок. \n\n— Говорил я ему не нужно было идти в слуги к графу. Плохая это была затея",115936,null],[115939,"2026-07-15T14:47:27",17,"/ Убеждение",115936,null],[115940,"2026-07-15T14:47:27",9,"*Ложит руку на плечо.*\n\n— Смотри на вздымающийся от ударов доски. Ты хочешь быстро умереть? Немея может \"случайно\" сжечь церковь.",115936,null],[115941,"2026-07-15T14:47:30",17,"/ Или обман",112272,null],[115942,"2026-07-15T14:48:14",60,"На самом деле первым делом Альф пойдет взять еды. Например хотя бы один пирожок, если сумеет отыскать старушку и объяснить ей ситуацию",112272,null],[115943,"2026-07-15T14:48:26",31,"У меня есть умение деревенское гостеприимство, дает доверие сельских жителей, за кго счет могу получить преимущество?/",115939,null],[115945,"2026-07-15T14:49:12",17,"/ Давай",115943,null],[115946,"2026-07-15T14:49:19",31,"/roll +d20-1",112272,null],[115948,"2026-07-15T14:49:30",17,"Ты вышел из церкви. Старушки с тележкой нет",115942,null],[115954,"2026-07-15T14:52:18",60,"—Ааааай... Похер!\n\nАльф тяжелым шагом возвращается.\n\n—Ридли. Ты говорил, у тебя ещё есть припасы. Сейчас разберемся, чё за мрак тут творится.\n\nОн поворачивается к священнику, подходя к двери в погреб. Очевидно, что если ему не откроют, великану хватит сил выломать себе новый путь. Сам Альф и понятия не имеет, что игры с вампирами часто кончаются укусами и возможно сынишка хочет крови. Но альф готов вдарить посильнее, если тот действительно попытается напасть\n\n—Откройте дверь, старче. Если мы хотим деревню оживить, нам сына церковного терять нельзя.",115948,null],[115955,"2026-07-15T14:55:03",9,"— Ты можешь наоборот стать его смертью. Что будет если поймёшь что это гуль или вурдалак коротый захочет просто тобой пообедать? — *Качает головой.* — Надо ждать худшего, не думаю что проблема лишь в том что он чем-то заболел Альф.",115954,null],[115956,"2026-07-15T14:56:21",17,"— Он больной мальчик, покалечит вас или себя. Не надо так, прошу. Просто нужно дождаться докторов из Валаки и... и... они найдут лекарство!",115954,null],[115957,"2026-07-15T14:56:26",60,"—Если он стал очередным бескровным ублюдком, то я просто звездану ему в башку и мы в любом случае закроем этот гештальт. Не хватало, чтоб ещё убил кого-то. А смерть не лечится, можете не искать эликсир",115955,null],[115958,"2026-07-15T14:56:47",17,"— Нет, пожалуйста, не причиняйте ему вред.",115957,null],[115960,"2026-07-15T14:57:36",31,"Мое убеждение не проканало?/",112272,null],[115962,"2026-07-15T14:58:41",60,"Альф несколько грозно смотрит на священника\n\n—Когда они прибудут? Вы понимаете, что время идёт ну вообще не на дни? Мы.. Как минимум его осмотрим. Я не боюсь боли. И не собираюсь тупо смотреть на эту херь и слышать, как кто-то дохнет, пока мы хороним другого. Это гребаное лицемерие, вашу мать!",115956,null],[115963,"2026-07-15T14:58:55",9,"— Смерть не лечится. Проклятие — возможно. — *Прикинул.* — С другой стороны Альф тоже прав. У меня есть цепи, могу одолдить несколько святой отец.",112272,null],[115964,"2026-07-15T14:59:14",17,"— пусть тогда сперва этот господин его осмотрит, а вы.. вы подержите. Он говорит что разбирается.",115960,null],[115965,"2026-07-15T14:59:36",9,"//Сколько нас!",112272,null],[115966,"2026-07-15T14:59:42",17,"— Я уже.. Приковал его.",115963,null],[115967,"2026-07-15T14:59:56",17,"— ОТЕЦ Я ГОЛОДЕН, НЕ МОГУ БОЛЬШЕ ЖДАТЬ! Я УМИРАЮ!",112272,null],[115968,"2026-07-15T15:00:13",17,"Удары по полу в этот раз другие более сильные лавка с Донавичем подпрыгнула",112272,null],[115969,"2026-07-15T15:00:31",60,"—Подержу. Обязательно.\n\nАльф впадает в ярость и ждёт отпирания двери",115964,null],[115970,"2026-07-15T15:00:39",9,"— Хорошо. Но цепи изнашиваются, всё же я оставлю вам несколько после осмотра. Если они не решат его убить.",115966,null],[115971,"2026-07-15T15:01:50",9,"*Не преукрашивал ситуацию вообще.*\n\n— Простите святой отец, некоторые решения тяжело принимать. Мы пойдём смотреть? Может в вашем присутствии он будет спокойнее.",115970,null],[115974,"2026-07-15T15:02:56",17,"- Д-да...\n\nДонавич встал и пошел к двери, он дрожащей рукой открыл абмарный замок и убрал засов от бруска.\n\nдверь была открыта",112272,null],[115975,"2026-07-15T15:03:22",9,"*Держится рядом со святым оцом, поддерживает старика.*",115974,null],[115976,"2026-07-15T15:03:25",7,"/ а я забор разбираю",112272,null],[115977,"2026-07-15T15:04:12",17,"К времени этого разговора вы с Исмарком уже сложили погребальный костёр и вернулись в зал. Отец Донавич как раз шел отпирать подвал",115976,null],[115978,"2026-07-15T15:04:45",31,"- Немея, нужно твое декарское мастерство!\n\nКричу и зову помочь с диагнозом пацану, если я не справлюсь",115976,null],[115979,"2026-07-15T15:05:25",9,"//Короче, куптл я значит 40 рационов чтобы не парится, есть ведь сосуд. А оказалось дороже золота в этом месте просто жрачку пронести 😂👍",112272,null],[115981,"2026-07-15T15:06:29",7,"*Немейя закончив подготовки, услышала, что ее зовут. Она начинает идти, оглядывая назад и говорит.*\n\n— Щас, вернусь. Меня что то позвали просто.\n\n*С этими словами, девушка направляется в церковь и говорит.*\n\n— Ребят, что случилось?",112272,null],[115982,"2026-07-15T15:08:17",60,"—Надо одного пацанёнка осмотреть. Кушать больной хочет. И хер знает кого.\n\nАльф зажигает свет в подвале, если есть такая возможность и там темно, и осторожно спускается вниз, озираясь по сторонам",115981,null],[115986,"2026-07-15T15:18:47",31,"Раз все тут, то заходим. Впереди наверное Альф как самый сильный и живучий в ярости/",112272,null],[115990,"2026-07-15T15:21:34",7,"/ я позади Альфа пройду",115986,null],[115991,"2026-07-15T15:22:50",7,"*Услышав, девушка приготовилась к худшему. Она в медицине понимала столько же, сколько и о личах. Почти ничего, однако попытается сделать, что в своих силах.*\n\n— Угу... Голодный ребенок в подвале на цепях. Ну посмотрим.",112272,null],[115992,"2026-07-15T15:27:24",31,"Я исходил из твоих предложений подлечить партию, поэтому и предположил что а тебя нсть навык медицины//",115991,null],[115993,"2026-07-15T15:27:52",9,"//Заклы хила ^^",115992,null],[115994,"2026-07-15T15:28:06",7,"/ лечение ран есть, а мудрость 10. Медицины как навыка нету :)\nА ещё есть уход за умирающим и будет малое восстановление",115992,null],[115995,"2026-07-15T15:29:59",31,"Ну ладно, я хоть и с чертой лекарь, в навыка нет почему то, как то странно)) ну может мастер разрешит нам бросить каждому на медицину, типа консилиум?))//",112272,null],[115996,"2026-07-15T15:30:50",7,"/ ну у меня больше отыгрыш что пламя феникса и сжигая может излечить",112272,null],[115997,"2026-07-15T15:31:36",60,"//мне кажется медицину даже не придется кидать",115995,null],[115998,"2026-07-15T15:34:31",31,"Вероятно, но персонаж пока не уверен))//",115997,null],[116003,"2026-07-15T15:53:06",9,"//Ммм, я ебанутый, наверное. Или персонаж? Не уверен 🤔",112272,null],[116004,"2026-07-15T15:53:21",9,"//Жду что мы увидим, посмотрим.",112272,null],[116019,"2026-07-15T16:10:42",17,"Дверь под лестницей открывается с тяжёлым скрежетом. Из подвала тянет сыростью, старой кровью и гниющей соломой.\n\nКаменные ступени уходят вниз, в тесную темноту. На стенах видны длинные царапины, местами выбит раствор. Снизу звякает цепь.\n\n— Отец… я голоден.\n\nГолос молодой, хриплый, сорванный криком.\n\nКогда свет достигает пола, среди обломков гробов видна фигура. Худой юноша стоит у дальней стены, прижавшись к камню ладонями. Кожа серого цвета, губы покрыты засохшей кровью. Его глаза отражают свет красным блеском.\n\nОн втягивает воздух и резко поворачивает голову к героям.\n\n— Вы живые.",112272,null],[116021,"2026-07-15T16:11:16",17,"Дору. Сын священника.",112272,null],[116028,"2026-07-15T16:16:45",9,"— Ты не живой? — *Ридли спросил его прямо.*",112272,null],[116029,"2026-07-15T16:17:04",17,"— Я голодный...",116028,null],[116058,"2026-07-15T16:26:28",9,"//Я предпочту подождать остальных. Хотя.",112272,null],[116060,"2026-07-15T16:27:42",9,"— Отец. Он есть обычную пищу? — *Спросил Ридли, а после обратился к парню.* — Ты все ещё ешь как человек? Или тебе хочется чего-то другого.\n\n*Присел на безопасном расстоянии вне досягаемости длинны цепи.*",112272,null],[116068,"2026-07-15T16:35:38",17,"— Отец покормит меня, своей кровью. Ничего другого мне не надо. остальное на вкус как помои, как земля! Отец прошу, сжалься.\n\nДонавич прижимается спиной к камню подвала и книгу сжимает крепко у груди\n\n— Господь утренний всемогущий...",116060,null],[116076,"2026-07-15T16:39:51",7,"*Немейя осматривает Дору. Она присматривается к клыкам и прикусив нижнюю губу выдыхает.*\n\n— Он же... Вампир... Кажись от голода умирающий.\n\n*Говорит уже не так весело девушка, смотря на бедолагу. Обращённый уже не сможет спастись...*",112272,null],[116077,"2026-07-15T16:40:08",31,"/roll d20 на анализ. Пытаюсь по внешним признакам понять, парень уже отродье или это что то иное?",112272,null],[116079,"2026-07-15T16:40:18",31,"Анализ это не моё, мда//",112272,null],[116082,"2026-07-15T16:41:17",31,"- кто это с тобой сделал, парень?\n\nУчастливо спрашиваю, присаживаясь рядом с парнем? Граф?",112272,null],[116083,"2026-07-15T16:41:46",9,"— Отец скоро упадёт без сил. — *Подумал и кивнул.* — Дайте мне чашу и кинджал.",116068,null],[116123,"2026-07-15T16:59:15",17,"— Я...  Я... Мысли путаются... Дайте еды, умоляю...",116082,null],[116125,"2026-07-15T16:59:45",17,"Исмарк испугано передаёт тебе и чашу и кинжал",116083,null],[116127,"2026-07-15T17:00:32",7,"Немейя\n— Я думаю... Это не лучшая идея... Но и мучаться так... Делай, что удумал.",112272,null],[116128,"2026-07-15T17:00:40",7,"/ щас убьют Дору",112272,null],[116136,"2026-07-15T17:03:08",9,"*Ридли редет руку и стачивает кровь.*",112272,null],[116137,"2026-07-15T17:03:50",9,"/roll 2d4 урон пусть, наточу кровушки скок смогу, крови у человека не так и много",112272,null],[116139,"2026-07-15T17:04:01",9,"//Крепкий зараза",112272,null],[116140,"2026-07-15T17:05:09",7,"/ не лучшая идея",112272,null],[116141,"2026-07-15T17:05:33",9,"*Ридли точит крови в чашу, а после заживляет рану (исцеляющие руки от расы).*\n\n— Немного, но держи. — *Протягивает и ставит так чтобы парень мог дотянутся.*",112272,null],[116142,"2026-07-15T17:06:06",9,"//Пох, и персу интересно и мне, почему нет?",116140,null],[116143,"2026-07-15T17:06:29",7,"/ ничего против не говорю, дублирую коммент персонажа)",116142,null],[116148,"2026-07-15T17:12:51",9,"— Может мы узнаем что-то. — *Обращаеися к Немее.* — Хорошая идея илитнет, разве тебе не интересно? И даже отродье, даже если не может ослушаться хозяина, всё ещё человек. Я видел как такие жили среди людей, просто необходимо вовремя уталять голод.",116127,null],[116154,"2026-07-15T17:17:45",7,"Немейя\n— Поступай как знаешь, но выглядит откровенно противно. Голод утолиться, дальше что? Я многое и не знаю, но не теряй контроль над ситуацией.",112272,null],[116157,"2026-07-15T17:18:41",31,"- ну, утолив голод, он хотя бы сможет что то сказать. Или убьет нас всех, хех",112272,null],[116158,"2026-07-15T17:18:50",17,"— Ближе прошу, я не дотянусь, цепь слишком короткая\n\nОн показывает тебя кусок цепи которым прикован к стене",116141,null],[116171,"2026-07-15T17:26:35",9,"*Закатывает глаза, явно с подозрением. Берет запонку в одну руку а чашу в другую.*\n\n— Хорошо, только не нападай, мои друзья не столь доброжелательны. — *Подает чашу.*\n\n//Заготовленное дейсвие исчезнуть в сосуд если тот попытается атаковать",112272,null],[116173,"2026-07-15T17:27:02",7,"/ можно я заготовлю действие?",112272,null],[116174,"2026-07-15T17:27:47",7,"/ при помощи огненного снаряда создаю снаряд пламени и если тот кинеться, при помощи управления над огнём перед лицом кровосиси его перенесу, чтобы отпугнуть.",112272,null],[116182,"2026-07-15T17:32:04",17,"Юноша вот вот дотянется до чаши с кровью Ридли, но тут рагорается пламя в руке Немеи. Он щурится от света и закрывает лицо предплечьем. На нём висит грязная рубаха, слишком широкая для исхудавшего тела. Запястья покрыты старыми следами от верёвок.\n\nОн отступает к стене, вжимается в неё.\n\n— Не надо, уберите огонь, пожалуйста.\n\nГолос дрожит. Цепь у его ноги волочится по полу.\n\n— Отец сказал, что здесь безопасно. Он обещал, что найдёт лекарство.\n\nОн смотрит на оружие героев, затем на лестницу.\n\n— Вы пришли меня убить?",116171,null],[116185,"2026-07-15T17:33:19",60,"—Ешь. Мы ждём лекарей. Но никто не хочет получить укус. Это мера предосторожности, хотя я нихера не понимаю, зачем в доме огонь.",116182,null],[116187,"2026-07-15T17:34:05",7,"*Девушка закатывая глаза, тяжело выдохнула.*\n\n— Положи на пол чашу с кровью, рядом с ним, чтобы дотянуться мог, после потушу.\n\n*Девушка сказала с недовольством, даже с грустью последнюю фразу.*",112272,null],[116188,"2026-07-15T17:34:08",17,"/Ридли у тебя раса какая? нежить? Кровь у тебя нормальная или мертвеца?",112272,null],[116189,"2026-07-15T17:39:17",9,"//Аасимар защитник, но он живой считай. Может ритуалами подпорчена но сойдёт вампиру на безрыбье думаю.",112272,null],[116192,"2026-07-15T17:40:15",9,"— Ладно. — *Поставил чашу поближе.* — Прости, они слишком осторожны.",116187,null],[116193,"2026-07-15T17:40:25",31,"А было бы прикольно травануть кровью нежити))//",112272,null],[116194,"2026-07-15T17:40:38",7,"/ пламя мгновенно тухнет. Немейе больно",116192,null],[116195,"2026-07-15T17:40:58",7,"/ или кусает сосуд Элементаля",116193,null],[116196,"2026-07-15T17:41:11",7,"/ вместо крови бодрящий заряд огня",112272,null],[116222,"2026-07-15T17:57:32",17,"Огонь гаснет. Дору медленно отводит руку от лица.\n\nРидли ставит чашу на камни и подталкивает её ногой. Цепь скребёт по полу. Юноша опускается на колени, тянется и хватает чашу обеими руками.\n\nПервый глоток он делает осторожно.\n\nЗатем начинает пить жадно. Кровь стекает по подбородку, пальцы сжимаются на краях чаши. Через несколько секунд Дору отрывается от неё и тяжело дышит.\n\nКрасный блеск в его глазах становится ярче. Щёки слегка наливаются цветом.\n\nДору допивает кровь и медленно опускает чашу. Дрожь в его руках стихает. Он проводит языком по окровавленным губам и несколько раз моргает, словно впервые различает лица вокруг.\n\n— Я помню вас… Нет. Других. Нас было много.\n\nДонавич делает шаг вперёд, всё ещё прижимая книгу к груди.\n\n— Он ушёл добровольно. Сказал, что будет служить графу в замке. Что сможет защитить деревню, если заслужит его расположение.\n\nДору резко поворачивается к отцу.\n\n— Я не служил ему…\n\nОн хватается за голову. Цепь звякает о камень.\n\n— Я нёс… что-то. В нижние залы. Там была дверь… и женщина в красном…\n\nЕго голос снова становится хриплым. Взгляд опускается на пустую чашу.\n\n— Ещё немного. Тогда я вспомню.",112272,null],[116238,"2026-07-15T18:06:31",31,"Хмм, у давай и я чуток нацежу в чашу",112272,null],[116239,"2026-07-15T18:06:59",31,"Бросить на урон при кровопускании?/",112272,null],[116242,"2026-07-15T18:08:29",9,"//Я по наитию бросал на глаз, потому что кробь так бы важна в организме. Могло и сильно похереть и не сильно от пол чаши, вот и кинул 2д4 по наитию. А так дма спроси",112272,null],[116243,"2026-07-15T18:09:16",9,"— Если только кто-то ещё, если дам больше точно появится слабость.",112272,null],[116245,"2026-07-15T18:09:57",17,"/д4 достаточно Хард просто мазахист",116238,null],[116246,"2026-07-15T18:10:09",31,"/roll d4",112272,null],[116249,"2026-07-15T18:10:33",31,"Аккуратно надрезаю ладонь и сцеживаю кровь в чашу",112272,null],[116252,"2026-07-15T18:11:16",17,"/Как же два обывателя щас бафают босса, чтобы все тут сдохли, ммм сказочные",112272,null],[116268,"2026-07-15T18:15:50",31,"Мы верим в силу воли пацана, вот он сейчас крови напьется и будет добрый и хороший))//",116252,null],[116289,"2026-07-15T18:24:24",9,"//Пойду шерстить инвентарь в поисках спасательного каната",112272,null],[116292,"2026-07-15T18:26:10",17,"Тарх проводит лезвием по ладони. Кровь тяжёлыми каплями падает в чашу.\n\nДору поднимает голову ещё до того, как чаша наполняется. Ноздри раздуваются. Цепь медленно натягивается по камню.\n\n— Этот запах… другой.\n\nОн смотрит на Тарха, не отрываясь.\n\nКогда чашу ставят на пол, Дору подползает к ней и пьёт короткими жадными глотками. Пальцы с треском сжимают глиняный край.\n\nПустой сосуд выпадает из его рук.\n\n— Колокол…\n\nОн поднимает взгляд на потолок подвала.\n\n— В замке звонили три раза. После третьего удара открывалась дверь. Ко мне приводили человека.\n\nДору закрывает уши ладонями.\n\n— Рахадин заставлял меня считать. Первый. Второй. Третий.\n\nДонавич прижимает книгу к груди крепче.\n\n— Сын, здесь колокол зовёт только на молитву и погребение.\n\nДору резко смотрит на него.\n\n— Погребение…\n\nЦепь натягивается. Кольцо в стене тихо скрипит.\n\n— Граф знал, что бургомистра будут хоронить. Он сказал: «Когда прозвучит третий удар, мальчик откроет мне церковь».\n\nДору переводит взгляд с отца на лестницу.\n\n— Я не помню, кого он пришлёт. Помню только глаза между могильных камней… и что двери должны остаться открытыми.\n\nДору смотрит на кровь, оставшуюся на ладони Тарха.\n\n— Там была девушка. Кажется… из этой деревни.\n\nОн протягивает пустую чашу.\n\n— Ещё немного крови, прошу. Я почти вижу её лицо.",112272,null],[116306,"2026-07-15T18:36:31",31,"Ну что, кто еще подкормит нашего жопонадирателя?)))////",112272,null],[116307,"2026-07-15T18:36:56",7,"/ дублирую второй раз коммент Немейи",112272,null],[116308,"2026-07-15T18:37:07",7,"/ по моему это не удачная идея",112272,null],[116309,"2026-07-15T18:38:27",60,"//если альф нальет ему своей крови детей Ктулху, это явно ничем хорошим не кончится",116306,null],[116311,"2026-07-15T18:38:41",60,"//Я НЕ ХОЧУ ВАМПИРА КТУЛХУ",112272,null],[116312,"2026-07-15T18:39:21",7,"/ Налевай, я захотел",116311,null],[116313,"2026-07-15T18:40:06",9,"— Думаю мы услышали достаточно. К нам прийдут на похо похороны после третьего удара колокола. — *Ридли встал и подошёл к священнику.* — Как бы не была сильна воля вашего сына отец когда колокол ударит третий раз он сломает все цепи даже оставив здесь свои руки или голову и встретит гостя на погребение. Сил после нашей крови ему хватит с лихвой.",112272,null],[116319,"2026-07-15T18:42:33",7,"*Немейя чувствует неладное. Это просто выглядит, как издевательство. Как бы резко не хотелось сжечь Дору, даже это было бы милосерднее. Чем собственно и будет, если бы ей позволили сжечь его и избавить от мук. Вздохнув, она перед тем, как выйти, передает пирожок в руках Альфу.*\n\n— На, возьми. У меня аппетит совсем пропал... Я лучше отойду, выглядит отвратительно. Не хватало, чтобы он еще вылез из своих оков.",112272,null],[116321,"2026-07-15T18:43:44",17,"— Нет. Не уходите. Дайте ещё немного. В деревне есть шпионка графа и я вспомню кто она. Саботажница. Диверсантка. Прошу вас!",112272,null],[116322,"2026-07-15T18:44:38",7,"/ опа, могу кинуть на проницательность?",112272,null],[116323,"2026-07-15T18:45:51",9,"— Я буду помогать святому отцу, ты не будешь голодать так сильно. Но и ты побереги отца, Дора. Мы бы могли тебя просто убить, но святой отец искренне заботится о тебе, позаботься о нём и ты, может мы сможем избавить тебя от проклятия.",116321,null],[116324,"2026-07-15T18:45:56",7,"/r d20 +2",112272,null],[116326,"2026-07-15T18:46:06",7,"/ детектор лжи включён",116325,null],[116327,"2026-07-15T18:46:51",7,"/ пиздеж карается нагретыми до красна цепями",112272,null],[116333,"2026-07-15T18:49:36",60,"Альф вздыхает. Информация нужна. Он не умный, но это понять не сложно. Напрягшись, он укалывает себя кончиком кинжала и тонкой, но упорной струйкой голубая, мутная, но чем-то даже светящаяся кровь великана, поражённого проказой глубин, наполняет чашу. Варвар ставит её перед новорожденным вампиром без единого слова. Он не знает, насколько это опасно.",116321,null],[116334,"2026-07-15T18:49:53",17,"/ Щас ГМ пост",112272,null],[116337,"2026-07-15T18:51:35",9,"//Ну, нам пизда если он это съест, с кровью аасимара подпорченой ритуалами, этой и отбитого крестьянина что не маловажно там только крови феникса не зватает, ег разопрёт как тумбочку. Хотя от такого набора я бы описал что он лопнул просто в кровавом тумане ^^",116333,null],[116347,"2026-07-15T18:58:34",9,"//У меня есть гениальная идея! Вырастим своего мегавампира, будем шнягой разной кормить пока он не мутирует окончательно",112272,null],[116348,"2026-07-15T18:58:51",9,"//И графа может сожрёт заодно",112272,null],[116349,"2026-07-15T19:01:09",17,"Голубая кровь Альфария тонкой струёй стекает в чашу. В мутной жидкости мерцают крупицы холодного света.\n\nДору подаётся вперёд.\n\n/ Проницательность - критический успех\nВ поверхности чаши Немея видит ближайшие мгновения: цепь ползёт через весь подвал, разматываясь из-под грязной соломы. Сукин сын скрывал ее длину под охапкой сена. Он стучал в пол далеко не у стены, он уже давно может добраться до любого из вас и цепь на шее ему не помешает. Но он выманивал вашу кровь перед этим. Восстанавливал силы. Дору пролетает мимо Альфария. Его пальцы смыкаются на руке Тарха, прямо поверх свежего пореза.\nВидение гаснет.\n\nДору уже держит чашу.\n\nОн пьёт медленно. После первого глотка по его шее расходятся тёмные прожилки. После второго под кожей перекатывается тусклое синее свечение. Последние капли он слизывает с края.\n\nТишину нарушает тяжёлый удар сердца.\n\nВ камнях под ногами проступает влага. Изо рта Дору вырывается облачко холодного пара. Правый глаз на мгновение становится чёрным и гладким, похожим на жемчужину со дна моря.\n\n— Шпионка…\n\nОн улыбается, показывая окровавленные клыки.\n\n— Да кто знает кто она, я просто выдумал этот бред\n\nДору разжимает левую руку.\n\nЦепь, которую он всё это время удерживал у бедра, падает на пол. Из-под соломы выскальзывает один виток, второй, третий. Железо с грохотом разматывается почти до лестницы.\n\nДонавич отступает к стене.\n\n— Дору…\n\nЮноша втягивает воздух. Его голова поворачивается к Тарху.\n\n— Твоя была лучше.\n\nОн бросается мимо Альфария. Цепь хлещет по полу. Пальцы Дору вытягиваются в чёрные когти и тянутся к окровавленной руке Тарха.",112272,null],[116351,"2026-07-15T19:01:19",17,"/Инициатива",112272,null],[116352,"2026-07-15T19:01:38",17,"/У Немеи есть ход вне инициативы",112272,null],[116353,"2026-07-15T19:02:28",17,"/r +4 Дору",112272,null],[116356,"2026-07-15T19:02:55",17,"/r +5 Когти Дору по Тарху",112272,null],[116358,"2026-07-15T19:03:06",17,"/r 1d6+3 рубящий урон",112272,null],[116360,"2026-07-15T19:03:21",17,"/Тарх схвачен Сл атлетика 13",112272,null],[116361,"2026-07-15T19:03:26",31,"/roll d20+1",112272,null],[116363,"2026-07-15T19:03:34",31,"Это инициатива была",112272,null],[116364,"2026-07-15T19:03:39",17,"/r +5 Укус по сваченому Тарху сразу же",112272,null],[116366,"2026-07-15T19:04:11",17,"/r 1d6+3 колющий урон d6 некротический и лечение такое же как этот урон",112272,null],[116368,"2026-07-15T19:04:21",17,"/Обывателю пиздец",112272,null],[116369,"2026-07-15T19:04:27",17,"/Как бы что и требовалось доказать",112272,null],[116370,"2026-07-15T19:04:52",17,"/ Монстр имеет Атаку если она попадает наносит еще одну и всё",112272,null],[116371,"2026-07-15T19:04:56",17,"/ Обывателю пизда",112272,null],[116372,"2026-07-15T19:05:04",7,"/ ну щас устрою",116352,null],[116373,"2026-07-15T19:05:09",7,"/ момент",112272,null],[116374,"2026-07-15T19:05:21",9,"//Так, что делаем",112272,null],[116375,"2026-07-15T19:05:26",17,"/ Ходи, только ты можешь тарха спасти. Я достал табличку дикой магии баровии",112272,null],[116376,"2026-07-15T19:05:40",31,"У меня вроде 2 ХП",112272,null],[116377,"2026-07-15T19:05:46",31,"Если я правильно посчитал",112272,null],[116378,"2026-07-15T19:06:00",17,"/Похвально, значит у тебя более 20 хитов?",116376,null],[116379,"2026-07-15T19:06:01",31,"Но это пизда в любом случае))//",112272,null],[116380,"2026-07-15T19:06:21",9,"/roll 1d20 иня, я не понимаю что происходит, так что откликните когда мой зод, попытабсь вклиниться",112272,null],[116382,"2026-07-15T19:06:47",17,"/ Ну а что не понял? Он напал на Тарха и усилился от крови",116380,null],[116383,"2026-07-15T19:06:59",17,"/ А цепь была длинная, всё",112272,null],[116384,"2026-07-15T19:07:07",31,"Нет, 15/ 2 сам отдал, 8 от первого удара и 3 от второго, разве не 13?/",116378,null],[116385,"2026-07-15T19:08:54",60,"//могу провоцирку дать?",116349,null],[116386,"2026-07-15T19:09:03",31,"А, там еще некротика, ну да, пизда мне//",112272,null],[116387,"2026-07-15T19:09:03",17,"/ Со второго 9 колющего когтями и 3 некротикой яд вампира",116366,null],[116388,"2026-07-15T19:09:09",17,"/ да",116385,null],[116389,"2026-07-15T19:09:46",60,"/roll +5 ну так чисто чтоб было видно что не втыкаю",116388,null],[116391,"2026-07-15T19:09:52",7,"*Немейя увидев сей беспредел, мгновенно покрывается пламенем. Она бросается на Дору, покрываясь пламенем и руками давит глаза. Параллельно, пока пыталась выжечь глаза, она уже прочитала заклинание.*\n\n— Сукин ты не исправимый сын, я обращу тебя в пепел. \n\n/ Бонусным использую огненную вуаль и кастую огненные ладони прям ему в лицо, стараясь минимальное количество людей задеть.",116352,null],[116392,"2026-07-15T19:10:12",7,"/r 3d6 +4 +4",112272,null],[116394,"2026-07-15T19:10:31",31,"Так его нахуй// а я теперь прожарен ещё до кучи//",112272,null],[116395,"2026-07-15T19:10:31",9,"//Урон огонь 🔥",116393,null],[116396,"2026-07-15T19:10:58",7,"/ не, ты меня же не трогаешь  и не атакуешь",116394,null],[116397,"2026-07-15T19:11:10",7,"/ первый бой показал мои ошибки и я их учел",112272,null],[116398,"2026-07-15T19:11:11",60,"//есть пробитие?",116390,null],[116399,"2026-07-15T19:11:47",60,"/roll +1 инициатива",112272,null],[116401,"2026-07-15T19:11:49",7,"/ если что 21 урона так от закла, а 4 урона от прикосновения что атакую",112272,null],[116402,"2026-07-15T19:11:55",31,"//Тарх при смерти и ему снится чудесный сон про прожаренного вампира. Во сне ору: отжарь кровососа!//",112272,null],[116403,"2026-07-15T19:12:10",7,"/ обойдешься",116402,null],[116404,"2026-07-15T19:12:18",7,"/ будешь смотреть как тот сгорает",112272,null],[116405,"2026-07-15T19:14:53",60,"/roll 2d6+d4+3 бумк магической тыкалкой",112272,null],[116407,"2026-07-15T19:16:12",17,"/r +3 Исмарк",112272,null],[116409,"2026-07-15T19:16:43",17,"Дору / 37\nТарх \nАльф \nИсмарк\nНемея \nРидли",112272,null],[116410,"2026-07-15T19:17:33",7,"/ я же не кидал ини вроде.",112272,null],[116411,"2026-07-15T19:17:36",7,"/ ладно пуфик",112272,null],[116412,"2026-07-15T19:17:42",17,"/ Как работает у моего монстра сопротивление к немагическим атакам рубящий колющий и тд, тут игнорится, пукалка магическая? Или работает как в ярости у варвара?",116405,null],[116414,"2026-07-15T19:18:07",17,"/Кинь",116410,null],[116417,"2026-07-15T19:19:02",7,"/r d20 +2",112272,null],[116419,"2026-07-15T19:19:16",7,"/ справедливо",112272,null],[116424,"2026-07-15T19:20:44",60,"//если там написано, что сопрот только к немаг атакам, то нет, ибо любое магическое оружие наносит магический урон",116412,null],[116426,"2026-07-15T19:21:24",60,"//то же касается лука и стрел. Магический лук+ немагическая стрела= магический урон. Немагический лук+ магическая стрела= маг урон.",116424,null],[116428,"2026-07-15T19:22:51",60,"//так что волшебная пукалка, которую мне выдали, тут подходит просто превосходно, спасибо❤️",112272,null],[116447,"2026-07-15T19:28:06",31,"//когда нибудь я научусь спрашивать от окружающих вещах, заходя в локацию, когда нибудь обязательно. Вот жопой чую, там стоит бочка со святой водой, которую святой отец использует для того чтобы гнать святой самогон///",112272,null],[116454,"2026-07-15T19:29:58",60,"//(я знал, что пацан мог как-то двинуться дальше на цепи, ибо он барабанил в потолок буквально, но не говорил, ибо мета)",116447,null],[116457,"2026-07-15T19:30:48",31,"Гу почему, ты сог бы е у сказать, а как ты дотянулся до потолка, если цепь короткая? Он же ее нам показал//",116454,null],[116460,"2026-07-15T19:32:22",7,"/ я говорил что идея говно его кормить",112272,null],[116461,"2026-07-15T19:32:36",7,"/ говорил:)",112272,null],[116462,"2026-07-15T19:32:44",7,"/ но никто не послушал",112272,null],[116464,"2026-07-15T19:33:00",31,"Да пофиг. Валите его, потом меня похороните//",112272,null],[116468,"2026-07-15T19:33:47",17,"Отбросив тело Тарха на солому, Дору прыгнул на стену и поп отолку убежал от тифлингши и варвара подальше, он спрыгнул с ускорение оттолкнувшись от деревянного потолка прямо на Ридли",112272,null],[116469,"2026-07-15T19:33:53",9,"//Церковь близко",116464,null],[116470,"2026-07-15T19:33:56",17,"/Провокация Немея, у Альфа нет реакции",112272,null],[116471,"2026-07-15T19:34:12",17,"/r +5 Когти",112272,null],[116473,"2026-07-15T19:34:16",17,"/ Попал?",112272,null],[116475,"2026-07-15T19:34:30",9,"//Нууу, попал. Ладно.",116468,null],[116478,"2026-07-15T19:35:02",7,"/r d20 +4",116470,null],[116480,"2026-07-15T19:35:09",17,"/r d6+3 рубящий",112272,null],[116482,"2026-07-15T19:35:15",17,"/ Попал",116478,null],[116483,"2026-07-15T19:35:24",7,"/r d4 +2 +4",112272,null],[116485,"2026-07-15T19:35:34",7,"/ 4 немаг рубящего, 4 огня",112272,null],[116489,"2026-07-15T19:36:13",17,"/ Огонь откуда?",112272,null],[116490,"2026-07-15T19:36:31",7,"/ урон при косании",116489,null],[116491,"2026-07-15T19:36:40",7,"/ хз считается ли, твоё усмотрение",112272,null],[116493,"2026-07-15T19:36:45",17,"/ Ну помоему опять не то, ладна похуй щас лень дрочить тебя",112272,null],[116494,"2026-07-15T19:37:29",17,"Дору шипит когда Немея жарит его своей огненной вуалью",112272,null],[116495,"2026-07-15T19:37:37",17,"/Блять забыл дикую магию кинь д100",112272,null],[116496,"2026-07-15T19:37:46",17,"/ А вы че не напоминаете!",112272,null],[116497,"2026-07-15T19:37:54",7,"/ у меня Альцгеймер",116496,null],[116498,"2026-07-15T19:38:05",7,"/ мастер, кинь д100 позазв",112272,null],[116499,"2026-07-15T19:38:14",17,"/ Ты кидай",112272,null],[116502,"2026-07-15T19:38:54",60,"//щас опять поймаем верёвки",116496,null],[116505,"2026-07-15T19:39:33",7,"/r d100",116499,null],[116507,"2026-07-15T19:39:35",31,"Ща дикой магии призовём сюда солнце и оно сможет вампиркныша к херам///",112272,null],[116512,"2026-07-15T19:40:22",60,"//высоко",116506,null],[116513,"2026-07-15T19:40:42",60,"//у чародея дикой магии на 99-100 реген всех чарок, кста. Но тут не та таблица",112272,null],[116514,"2026-07-15T19:40:44",7,"/ прикиньте щас сам начну урон от огня получать",116512,null],[116526,"2026-07-15T19:42:07",60,"//тарх лежит уже?",112272,null],[116527,"2026-07-15T19:42:09",17,"/На минуту вы начинаете видеть глазами ближайшего крошечного существа. Собственные глаза в это\nвремя ничего не видят; связь можно разорвать действием.",116514,null],[116528,"2026-07-15T19:42:18",17,"/Перекинь провокацию у тебя помеха ты слепой",112272,null],[116531,"2026-07-15T19:42:47",17,"Взор Немеи вдруг переходит в крысу в углу комнаты, она видит себя и остальных сбоку",112272,null],[116536,"2026-07-15T19:43:15",7,"/ боль",116531,null],[116537,"2026-07-15T19:43:21",31,"Да/",116526,null],[116543,"2026-07-15T19:44:38",17,"После ужасной атаки когтями, Ридли чувствует как его обнимает Дору так крепко что начинает хрустеть позвоночник, а отродье уже впивается ему в шею",116480,null],[116544,"2026-07-15T19:44:43",17,"/r +5",112272,null],[116546,"2026-07-15T19:45:07",17,"/r d6+3 Колющий d6 некра и отхил",112272,null],[116548,"2026-07-15T19:45:12",9,"//Он ходит 3 раза?",112272,null],[116550,"2026-07-15T19:45:28",7,"/ нет, раунд внезапности был и щас ини наша",112272,null],[116551,"2026-07-15T19:45:28",17,"/ Нет он сходил до инициативы, как внезапный раунд. Потом как первый в ини",112272,null],[116552,"2026-07-15T19:45:34",9,"//Хм, скок урона я получил всего",112272,null],[116553,"2026-07-15T19:45:42",7,"11",116552,null],[116555,"2026-07-15T19:45:50",9,"//За все время?",112272,null],[116556,"2026-07-15T19:45:50",17,"/ У него атака, если попала еще укус. Первая атака автоматически захватывает по 13 сложности атлетики",112272,null],[116557,"2026-07-15T19:45:57",60,"И ещё 9",116481,null],[116560,"2026-07-15T19:46:20",9,"//Такс, тоесть меня били 2 раза да?",112272,null],[116561,"2026-07-15T19:46:41",60,"//когти и укус",112272,null],[116564,"2026-07-15T19:47:08",9,"//Что тогда, оф перс бещ сознания. Я думал успею спрятаться, а тут и удары и укусы в мой ход)",112272,null],[116565,"2026-07-15T19:47:12",17,"/ 9 рубящий от когтей. 8 колющий 3 некра всего 20",116552,null],[116566,"2026-07-15T19:47:17",31,"Мой ход вроде? Бросать спас от смерти?/",112272,null],[116567,"2026-07-15T19:47:34",17,"/Нужно отойти",112272,null],[116569,"2026-07-15T19:47:40",7,"/ максимум не превысил, так что да",116566,null],[116571,"2026-07-15T19:48:01",31,"Спас от смерти это же просто д20?/",112272,null],[116573,"2026-07-15T19:48:15",9,"//Я просто чутка не уследил когда вампир ходит и почему так много раз, сорян",112272,null],[116574,"2026-07-15T19:48:15",31,"/roll d20",112272,null],[116576,"2026-07-15T19:48:24",31,"Охохо, первый провал///",112272,null],[116577,"2026-07-15T19:48:42",9,"//Думал мы уже по ине бежим и после немеи я",112272,null],[116580,"2026-07-15T19:49:12",7,"/ двоих стабилизировать надо, а я действие одно могу делать",112272,null],[116581,"2026-07-15T19:49:18",7,"Блеат",112272,null],[116582,"2026-07-15T19:49:31",17,"/Ходите дальше ребят. Броски от смерти не бросаем. СЧитаем раунды и бросаем кучей",112272,null],[116584,"2026-07-15T19:49:41",60,"Альфарий тяжело вздыхает. Убивать. Опять. Он не хочет этого. Но надо. Хотя бы немного. Он медленно вытягивает меч из-за спины, нарочито со скрежетом волоча его по каменному полу, высекая искры, подходя к Дору со спины и спокойным, но холодным голосом обозначая\n\n—Мы дали тебе поесть. Ты обманул нас, хотя мы могли дать больше. Ты бы жил. Паскуда.\n\nИ варвар тут же атакует",116582,null],[116586,"2026-07-15T19:50:02",60,"/roll +d20 гэээмблинг",112272,null],[116588,"2026-07-15T19:50:31",60,"Попрошу с него спас силы или ловкости на его выбор. При провале он падает ничком",112272,null],[116589,"2026-07-15T19:50:36",17,"/ Забыл сказать",112272,null],[116591,"2026-07-15T19:50:43",17,"/ В нём твоя кровь, так что",112272,null],[116593,"2026-07-15T19:50:48",17,"/ надо бы бить с помехой",112272,null],[116599,"2026-07-15T19:51:11",17,"/ Но не сказал так что сам виноват",112272,null],[116600,"2026-07-15T19:51:15",60,"//поздно сказал, провоцирка была без помехи",116595,null],[116601,"2026-07-15T19:51:16",17,"/ У него 54 хита, бей урон",112272,null],[116602,"2026-07-15T19:51:20",17,"/ Возможно он всё",112272,null],[116603,"2026-07-15T19:51:32",17,"/ 37 уже у него есть",112272,null],[116606,"2026-07-15T19:51:34",60,"/roll 2d6+2d4+13 бам",116601,null],[116609,"2026-07-15T19:51:42",17,"/ Ну конечно",112272,null],[116610,"2026-07-15T19:51:54",17,"/ Убили пацана. Донавич убитый горем будет",112272,null],[116611,"2026-07-15T19:51:56",31,"А он же лечился от укусов?/",116603,null],[116612,"2026-07-15T19:51:58",17,"/ Описывай",112272,null],[116613,"2026-07-15T19:52:15",17,"/ Ну да, там 34 но все равно варвар разрубил",116611,null],[116614,"2026-07-15T19:52:24",60,"//нелеталочка, написал ж, \"немножко убить\". Не хочу лишать его жизни. Нам надо найти лечение вампиризма",116610,null],[116616,"2026-07-15T19:52:32",17,"/ок",112272,null],[116625,"2026-07-15T19:54:05",60,"//могу забубенить помеху и сказать, что промазал, если это был босс",112272,null],[116626,"2026-07-15T19:54:24",60,"//не хочу так просто фигню устраивать этим мбо",112272,null],[116627,"2026-07-15T19:54:43",17,"/ Да давай без фигни",112272,null],[116628,"2026-07-15T19:54:45",17,"/ )",112272,null],[116629,"2026-07-15T19:54:53",17,"/ ну умер и умер нелетально, дальше пойдем",112272,null],[116630,"2026-07-15T19:54:59",17,"/  У меня еще заготовлено дохуя",112272,null],[116632,"2026-07-15T19:55:15",17,"/ Эта моя любимая компания и я ее ниразу не водил, просто ахуенная на мой вкус",112272,null],[116638,"2026-07-15T19:56:06",31,"Вроде это вообще самая известная кампания, во всяком случае я о ней слышал и до того как начал играть))//",116632,null],[116639,"2026-07-15T19:56:45",7,"*Немейя теряется в пространстве. Она ходит и видя себя от другого лица, подходит к Тарху. Тронув его, тот мгновенно покрылся пламенем. Вместо того, чтобы сгореть, он стабилизируется. Тоже самое проводит с Ридли. Однако еле как нащупав, она смотрит на вампира с точки зрения крысы. Она не проявляет к вампиру милосердия и в огненной вуали, создает пламя огненного снаряда. Она направляет всю огненную энергию в тварь, что напала первой.*\n\n— Гори урод блять. К тебе с понимаем, а ты чуть не убил двоих! Пока от тебя пепла не останется, я не успокоюсь!",112272,null],[116640,"2026-07-15T19:56:59",7,"/ сори ребят, но у моего персонажа свои планы",116629,null],[116642,"2026-07-15T19:57:11",7,"/ она пытается сжечь вампира",112272,null],[116643,"2026-07-15T19:57:36",7,"/ но стабилизировала Тарха и Ридли",112272,null],[116646,"2026-07-15T19:58:16",31,"Охуенное решение, лучшее из возможных, без шуток. Так этих ебучих кровососов//",116642,null],[116647,"2026-07-15T19:59:11",31,"Я что то слабину дал, персонаж бы не дал крови такой херне, мой проеб в плане отыгрыша. Спишем на ментальное воздействие))///",112272,null],[116648,"2026-07-15T19:59:16",31,"Или эффект пирожка//",112272,null],[116652,"2026-07-15T19:59:36",7,"/ а у меня персонаж хаотичен",112272,null],[116653,"2026-07-15T19:59:43",7,"/ нейтрально хаотичен",112272,null],[116654,"2026-07-15T19:59:44",60,"//я нечаянно удалил весь пост, который писал..",112272,null],[116666,"2026-07-15T20:01:12",17,"Отец Донавич бросается к горящему телу сына\n\n— Нет пожалуйста! Он просто мальчик, просто детя! Он был отправлен графом, нет, Дору!",112272,null],[116667,"2026-07-15T20:01:17",17,"Закрывает его собой",112272,null],[116668,"2026-07-15T20:01:19",31,"//надо не забывать, пока я живой, я этих тварей ненавижу и не верю им не под каким видом//",112272,null],[116669,"2026-07-15T20:01:21",17,"Тушит пламя",112272,null],[116672,"2026-07-15T20:01:36",31,"И сгорает сам?/",116669,null],[116676,"2026-07-15T20:01:56",17,"Ему больно, он ещё дышит. Пытается защитить сына",116672,null],[116679,"2026-07-15T20:02:26",7,"/ Немейя не остановится, она кайфует от процесса и вампир это заслужил",112272,null],[116680,"2026-07-15T20:02:42",7,"/ так что если никто не сделает что то, я опишу как еще священника сжег",112272,null],[116684,"2026-07-15T20:03:09",31,"Ну тебе только Альф может помешать, мы с Ридли без сознания/",112272,null],[116686,"2026-07-15T20:03:14",60,"Альфарий одним ударом разбивает радужную реальность вампира, опуская его.. Нет, буквально вбивая в землю и заставляя выпустить из рук Ридли. Да-да: полутораметровый кусок заточенной стали оказывается куда больнее для позвоночника и самооценки, чем острые клыки вампира. Фактор, который игнорировать в этом городке больше не получится. Тем не менее, Альф не снижает концентрации. Он хватает вырубленного вампира за шкирку и тащит его к стене. Мощными руками он буквально заворачивает цепи в узел, полностью обездвиживая гада\n\n—Не убивать. Мы дождёмся лекарей. Лекарство важнее. Помогите другим.",112272,null],[116687,"2026-07-15T20:03:17",17,"/ Да опиши. Если никто не остановит. У Ридли и Тарха нет сил сейчас.",112272,null],[116691,"2026-07-15T20:04:01",31,"А, там еще Исмарк же где то/",112272,null],[116695,"2026-07-15T20:04:41",60,"//а я остановлю",116687,null],[116696,"2026-07-15T20:04:43",17,"Исмарк не вмешивается.",112272,null],[116697,"2026-07-15T20:04:55",60,"//потащил его к стенке",112272,null],[116698,"2026-07-15T20:04:56",17,"/ решайте между собой. Тифлинг сжигает обоих",112272,null],[116700,"2026-07-15T20:05:11",17,"/ но ещё не сжег",112272,null],[116713,"2026-07-15T20:07:01",7,"*Девушка поддерживает пламя магическое на теле вампира. Горящая от злости Немейя смотрит на Альфа и говорит очень громко.*\n\n— ДА СМЕРТЬ ЕМУ ТОЛЬКО ПОМОЖЕТ, ОН УЖЕ ОБРАЩЁННЫЙ. РАЗБЕЙ ИЛЛЮЗИЯ СЧАСТЬЯ И ПОСМОТРИ НА ФАКТЫ, ДВОЯ УЖЕ МЕРТВЫ, А ВАШЕГО СЫНОЧКА НЕ СПАСТИ. ДАЙТЕ ЕГО СЖЕЧЬ, ОН ЗАСЛУЖИВАЕТ УЧАСТИ СГОРЕТЬ!\n\n*Девушка говорила и параллельно, чуть ли не дьявольски начала хохотать. Она просто в шоке, что монстра такого защищают. Он чуть не убил двоих, двоих! А его защищают... Это... Это нечестно.*",116686,null],[116730,"2026-07-15T20:08:37",7,"/ дайти сжечь, вампир хорошо гореть",112272,null],[116733,"2026-07-15T20:08:45",60,"—Убери огонь. Ты этим нихера не сделаешь. Ты можешь отрезать ему по пальцу, но никогда этим не добьёшься ничего, потому что говорит ну ясен хер не тот пацан, которого знает отец. А Ридли укусили. Ещё одного вампира в деревню хочешь? Население итак не растёт, ты сама столько не нарожаешь, даже если захочется.\n\nАльф быстро подходит к Немейе, заслоняя ей обзор на вампира и угрожающе нависая\n\n—Убери, мать твою, огонь. Этот мужик теперь путь к исцелению и инструмент, пеплом он никому нахер не сдался.",116713,null],[116756,"2026-07-15T20:12:43",7,"*Немейя очень сильно начинает злиться. Пламя частично выходит из под контроля и пол начинает постепенно прогорать.*\n\n— Вы придурки меня в прошлый раз не послушались, а теперь какой результат?! Сколько вампирам лет, думаешь нет лекарства?! Даже я тупая неначитаная дура это понимаю, а вот про детей и нарожать с твоей стороны было очень оскорбительным. Отойди сам, пока он не убил больше народу. Нас было четверо, а стало двоя.\n\n*Девушка говорила откровенно яростно и очень ярко светилась. Кажется, что это ее не убедило ибо факты на ее стороне.*",112272,null],[116773,"2026-07-15T20:16:24",60,"—Я слышу о них впервые. И может знаю немного. Но мне уже сказали, что если один укусит, то и второй станет этим говном. Ридли укушен. Убьёшь этого: подпишешь казнь второму. Ту же казнь. Сожжёшь его? Лучше сделай сразу. Но, клянусь, сука, если ты это сделаешь, я прогоню меч тебе через глотку. Чужие жизни не игрушка, и даже аббератная херня в моём мозгу это знает. Ими не торгуют.\n\nГоворит альф, непреклонно стоя на месте",116756,null],[116783,"2026-07-15T20:18:01",7,"/ они стабилизированы",116773,null],[116787,"2026-07-15T20:18:35",60,"//поменял",112272,null],[116800,"2026-07-15T20:22:04",7,"*Немейя чувствуя, что силы покидают и разговоры приведут лишь к тому, что она будет со всеми в ссоре, оставляет лишь глубокие ожоги на теле вампира.*\n\n— Учти, на твоей совести. А то, как ты описал мое убийство просто великолепно блять. Больше не подходи ко мне.\n\n*Слышно много обиды в некотором роде. Девушку распирает просто от несправедливости, так или иначе. Смирившись с тем, что ей не удастся убрать лишнего, она подходит сначала к Тарху.*\n\n— Посмотрим как они будут гореть.\n\n*Касаясь его груди, он покрылся огнем. Однако вместо ожогов, раны начали мгновенно заживать... Кроме укуса на шее. Тоже самое проворачивает и с Ридли.*\n\n— Просыпайтесь, Сони... Я чувствую себя вымотанной...",112272,null],[116803,"2026-07-15T20:22:21",7,"/ Немейя очень сильно обиделась на Альфа ( Привет бг3 )",112272,null],[116807,"2026-07-15T20:23:59",7,"/ @QURTZZ Hard",112272,null],[116811,"2026-07-15T20:24:23",7,"/r d8 +4 Тарху\nR d8 +4 Ридли",112272,null],[116813,"2026-07-15T20:24:37",7,"/ хиты вам",116812,null],[116814,"2026-07-15T20:24:45",7,"/ 1 ячейка, моя устать...",112272,null],[116816,"2026-07-15T20:25:02",7,"/ а не вру, 2 ячейки\nСпасибо единицам чародейства",112272,null],[116819,"2026-07-15T20:25:40",17,"/ Дикую магию кидает?",112272,null],[116822,"2026-07-15T20:26:04",31,"Ридли почти фулл, я на треть. И то хлеб//",112272,null],[116824,"2026-07-15T20:26:57",60,"Голос Альфа сбавляется на пару тонов, он по-прежнему напряжен(в ярости), но отходит обратно к обожжённому вампиру, фиксируя цепи покрепче в стене, как может\n\n—Полежит здесь. Я не мастер медицины. Убивать всех подряд не могу. Не хочу. И не буду.\n\nОн переводит взор на Исмарка и святого отца\n\n—Быть может я ещё чего-то не знаю о вампирах? Он не может долго без крови. После ожогов ее много запечётся на нём. Ослабеет. Не убежит? Когда прибудут лекари?",116800,null],[116825,"2026-07-15T20:27:04",7,"/За каждый каст?",116819,null],[116827,"2026-07-15T20:27:21",17,"/ за каждую трату ячейки",112272,null],[116828,"2026-07-15T20:27:27",60,"//какое счастье, что я варвар..",116827,null],[116829,"2026-07-15T20:27:27",7,"/r 2d100",112272,null],[116831,"2026-07-15T20:27:33",7,"/ 45 и 5",112272,null],[116840,"2026-07-15T20:30:38",17,"Призрачные цепи хватают случайное существо в пределах 30 футов. Сила против Сл, иначе оно опутано до  \nконца следующего хода",112272,null],[116843,"2026-07-15T20:30:59",31,"- если не будет пить крови - будет без сил. Но его без сил жто все равно больно\n\nТарх говорит с надрывом, каким хером он жив и сам не понимает",116824,null],[116844,"2026-07-15T20:31:02",17,"Рядом появляется призрачный волк. Первое существо, попавшее по вам атакой, получает 1d6 урона силовым  \nполем, после чего волк исчезает.",112272,null],[116849,"2026-07-15T20:31:29",17,"/ Отыграй сам как это все происходит",112272,null],[116850,"2026-07-15T20:31:33",60,"//кого?",116840,null],[116851,"2026-07-15T20:31:55",31,"То есть его опутала цепь и еще и волк появился? Пиздец какой//",112272,null],[116852,"2026-07-15T20:31:59",7,"/ волчок кусает вампира",112272,null],[116854,"2026-07-15T20:32:06",9,"*Встал и просто сидит у стены.*\n\n— Надо больше верить записям. — *Бубнит под нос, Саван его совсем разодран.*",112272,null],[116856,"2026-07-15T20:32:30",17,"/ Цепь опутала немею и волк остаётся с тобой. До того как тебя кто то ударит",112272,null],[116858,"2026-07-15T20:32:38",31,"- надо меньше верить мертвякам...",116854,null],[116862,"2026-07-15T20:33:47",31,"А, это полезный волк, ну хорошо//",112272,null],[116868,"2026-07-15T20:34:51",31,"Встаю и плохо контролируя тело, иду к священнику, нужно осмотреть его раны, возможно ему нужна помощь",112272,null],[116869,"2026-07-15T20:34:54",7,"*Немейя тяжело дышит, а пламя тухнет. Она опирается на стену, однако ее охватывает цепь и роняет лицом в пол. Также рядом появляется волк, что воет. Она просто лежит без сил и смотрит в пол.*\n\n— Угу... Пожалуйста блять, рада помочь.\n\n*Устало и раздражённо произносит девушка, пробубнев в пол. Сил встать не то, чтобы есть. Большая часть ушла на психи и поддержку формы пламенной.*",112272,null],[116876,"2026-07-15T20:37:19",7,"/ Немейя валяться будет пока что. Сил нет, она злая, ее опутали тентакли за доброту",112272,null],[116889,"2026-07-15T20:40:34",60,"Альф выглядит самым целым и не уставшим. Он буквально дважды махнул мечом и не получил удара в ответ. Видя, как тифлинг ложится на слегка подогретый от огня пол, его взгляд меняется. Почему-то громаде-фирболгу всё это время казалось, что отряд ещё только разогрелся, и лишь теперь видит и реально понимает, что двое из них тяжело ранены, а третья физически изнемождена. Его взор пробивает сожаление. Он не понимал, что его предел стоит выше. Что ему просто не досталось, а даже если бы досталось, он бы был к тому готов\n\n—Сука...\n\nТихо шепчет низким голосом Альфарий, сидя у вампира и пока ждёт ответа исмарка и священника\n@dunchev",116869,null],[116893,"2026-07-15T20:41:27",31,"Я вышк делал заявку на осмотр священника, жив ли он и нужна ли ему помощь//",112272,null],[116896,"2026-07-15T20:41:43",7,"/ шашлык",116893,null],[116917,"2026-07-15T20:46:24",7,"/ она не легла, она как ее опутали цепи жмякнулось лицом вниз",116889,null],[116922,"2026-07-15T20:48:06",9,"— Прийдёт время, эти глаза станут мудрее. — *Признаёт что ему не хватает опыта, встаёт и помогает Тарху со святым отцом.*",112272,null],[116944,"2026-07-15T20:54:22",31,"//ладно ребята, я спать//",112272,null],[116945,"2026-07-15T20:54:46",7,"/ спокойной",112272,null],[116946,"2026-07-15T20:54:56",17,"/ Давай. Я седня занят вечером. Завтра. Спокойной",112272,null],[116950,"2026-07-15T20:55:15",7,"/ сегодня кина не будет?",116946,null],[116962,"2026-07-15T20:59:28",17,"/ Чуть позже. Я ещё не дочитал вашу перепалку даже.",112272,null],[116965,"2026-07-15T21:02:09",7,"/ немейя в обиде на варвара",112272,null],[117061,"2026-07-15T21:36:26",17,"/ Перепалка вышла что надо. Запишите по вдохновению себе.",116889,null],[117073,"2026-07-15T21:38:44",17,"Исмарк отходит от стены и заходит в подвал к вам. \n\n— Нет, от укуса не стать этой тварью. Нужно испить крови вампира и не самого слабого. Так что с Ридли и Тархом будет все не так плохо. Правда чудо, что выжили. Если бы не Немея и твой меч... На счёт лекарей я не знаю. Донавич без сознания. Ожоги на теле, я ему помогу. Он не плохой человек. Просто запутался.\n\nСадится",112272,null],[117079,"2026-07-15T21:40:08",7,"/ 2 вдохновения :>",117061,null],[117099,"2026-07-15T21:43:29",60,"—Скорее запугался. У меня еще не было детей, но я знаю, что смотреть за гибелью собственной крови, того, кого растил годы, больно. И ублюдки вроде меня не могут взять и лишить жизни их труды за две минуты. Это неправильно. Мы не на войне. У нас ещё есть выбор и право на этот выбор.\n\nАльфарий наконец \"сдувается\", выходя из сиюминутной концентрации и садясь на пол в позе лотоса, каким бы неестественно большим этот лотос не был. Он слегка усмехнулся, глядя в пол. На секунду его голос стал чуть более живым\n\n—Как там говорили? Не жди свобод, выметай господ.. Ну чё, хана мразоте, выходит...",117073,null],[117282,"2026-07-15T22:21:21",7,"*Немейя как только освободилась от цепей, начала по тихонько вставать. Она опиралась на стены и держала рукой рюкзак свой. Голодная была до ужаса, а пирога не хочется... Он весь помялся, пока сражение второе пережил... С грустным видом она молча выходит из церкви и садится возле крыльца.*\n\n— Угу... Сжечь бы что нибудь.\n\n*Произнесла мысли вслух Немейя, голос был раздражённым и уставшим. Она начала осматриваться и находила палочки. Касаясь их, она поджигала их и превращала в пепел. Так или иначе, побесившись, она пока просто молчит и ничего от злости не говорит, дабы не нагрубить.*",112272,null],[117288,"2026-07-15T22:22:16",17,"/ Пирога хочется всегда.",117282,null],[117290,"2026-07-15T22:22:20",17,"/ Он не помялся",112272,null],[117297,"2026-07-15T22:22:47",7,"/ не сгорел пока я дважды покрылся огнем?",117290,null],[117300,"2026-07-15T22:23:04",7,"/ что то тут не так...",112272,null],[117321,"2026-07-15T22:25:28",17,"/ Пирог идеален",112272,null],[117325,"2026-07-15T22:26:00",7,"/ мне кажется, или пирог подозрительный",112272,null],[117327,"2026-07-15T22:26:10",7,"/ надо Варвару снова скормить его",112272,null],[117340,"2026-07-15T22:29:12",7,"*Внезапно девушка задумалась и взяла пирог в руки. Она осматривала его и начала вертеть.*\n\n— А ты как еще не умер... Вроде дважды чуть не сожгла. Странный какой-то... Кушать хочу... Каши той... \n\n*Говорит недовольно девушка, откладывая пирог. Она не хочет его трогать, что про еду говорить. В таверне еда хотя бы не отравленная, надо таверну отыскать.*",112272,null],[117342,"2026-07-15T22:30:02",17,"Пирог так прекрасно пахнет. Манящий аромат. Напоминает тебе запах хлеба по праздникам в приюте.",117340,null],[117356,"2026-07-15T22:32:22",7,"/ у меня нету сопротивления к урону ядом и отравлению",112272,null],[117357,"2026-07-15T22:32:26",7,"/ xd",112272,null],[117358,"2026-07-15T22:32:34",7,"/ я не Рорик с стальным желудком",112272,null],[117554,"2026-07-15T23:06:37",60,"//а альф и не против",112272,null],[117913,"2026-07-16T05:12:53",31,"обыватель сожрал и жив. Хотя может так он стал привлекательнее для вмпира на вкус?) а вообще ту старуху надо бы найти, уж больнго мастер любит описывать волшебный эффект пирожка//",117356,null],[117915,"2026-07-16T08:35:18",31,"ну что там со священником, будет жить? Может говорить? сына его мы не убили, но обсудить что с ним делать нужно. Ну и бургомистра уже похоронить пора, третий день таскаем труп, уже воняет поди//",112272,null],[117916,"2026-07-16T09:07:11",7,"/ тэк",112272,null],[117917,"2026-07-16T09:08:26",7,"/ ну как хочешь, твои действия как никак. \nНемейя просто положила обратно пирог и он кажется очень подозрительным просто",117915,null],[117928,"2026-07-16T11:18:04",31,"Продолжать то будем? Во сколько собираемся?/",112272,null],[117930,"2026-07-16T11:32:36",17,"/ Сегодня много работы. Описывать буду по ситуации. Между собой можете рпешить свободно. За вампирское отродье всем +150 опыта. За Отыгрыш будет опыт тоже. Время сиять",112272,null],[117931,"2026-07-16T11:33:21",17,"Обгоревший священник без сознания лежит на полу подвала.\n\n/ его стабилизировали?\n\nЕго проклятый сын в цепях завязан у стены под надзором Альфа",112272,null],[117932,"2026-07-16T11:34:06",17,"Исмарк встаёт и говорит. \n\n— Пора сложить костер для моего отца. Помогите только Доновича вытащить наверх. Ему надо... Обработать ожоги.",112272,null],[117933,"2026-07-16T11:37:06",7,"*Немейя недовольная, встает с крыльца. Она подходит и начинает молча помогать сложить костёр. Она желает его поджечь и наблюдать за этим зрелищем. Сил и правда мало, но все же... Она позволить себе может нести немного дров.*",112272,null],[117935,"2026-07-16T11:43:33",31,"подхватываю вместе с Исмарком Доновича и вытаскиваем его наверх",117932,null],[117936,"2026-07-16T11:45:02",17,"Наверху Имарк оставляет священника на Тарха\n\n— Помоги ему, ты вроде говорил смвслишь во врачевании. В том шкафу есть бинты, а в чане есть чистая вода.",112272,null],[117937,"2026-07-16T11:45:37",17,"Сам исмарк выходит на улицу, проходя мимо тела отца у алтаря он бросает быстрый взгляд на него. Скорбит",112272,null],[117938,"2026-07-16T11:46:09",17,"На улице с Неиеей начинает искать дрова для костра\n\n— Давай уже покончим с этим. День только начался и уже так... Херово.",112272,null],[117939,"2026-07-16T11:46:53",31,"/roll d20 на медицину, осматриваю Доновича, вижу что ожоги легкие и можно обойтись компрессами, которые делаю из бинтов, воды и каких то целебных трав, что тоже находяться возле бинтов",112272,null],[117941,"2026-07-16T11:52:31",7,"*Собирая части забора и складывая их в костер, девушка тяжело вздыхает.*\n\n— Угу... Не каждый день услышишь, как описывают твое убийство.  Извиняюсь за пылкость, но цепи не удержат того вампира. Он убьёт всех раньше, если с ним не покончить сразу.",117938,null],[117955,"2026-07-16T12:59:21",31,"Оставив больного Доновича отдыхать и приходить в себя, выдвигаюсь на улицу, и слышу слова девушки-тифлинга\n\n- Цепи не удержат, а вот то что он на святой земле сидит, буквально под храмом - удержит.  Он если бы мог на освященную территорию вылезти, уже вылез бы. А так он пленник отца, хочет вырваться, но не может. Ну а подвал видимо не освящен, что не удивительно. Хотя я на месте отца Доновича утсановил бы какую-нибудь растяжку со святой водой над лазом в подвал. Так, на всякий случай",112272,null],[117956,"2026-07-16T13:01:17",17,"— Тяжело признать. Но я стобой согласен. Надо было уничтожить вампирское отродте. Бед будет только больше. Я уже решил отправить депешу в Валаки с просьбой прислать нам пастыря в церковь, а Донавича отправим на покой.",117941,null],[117957,"2026-07-16T13:01:40",17,"— Он в плохом состоянии и фиизически и ментально, хотя мужик хороший и пастырь праведный.",112272,null],[117958,"2026-07-16T13:08:06",31,"/roll d20 бросаю на религию. В меру своих скромных познаний, прогуливаюсь по храму, оцениваю его внешни вид и состоние, пытаюсь понять, а осталась ли святость в этом месте, сможет ли она удержать вампира в подвале",112272,null],[117960,"2026-07-16T13:08:28",31,"видимо, что то я понял//",112272,null],[117963,"2026-07-16T13:22:22",17,"Святости тут никакой не ощущается. В Багровии молятся утреннему богу. Доподлинно неизвестно существовал ли такой бог. Граф не запрещает эту религию. Вероятно, чтобы оставить надежду в сердцах людей. И разбивать её когда ему захочется.",117958,null],[117964,"2026-07-16T13:24:02",31,"*задумываюсь, похоже моя теория не верна. Что же держит вампира в подвале? Приказ хозяина, или остатки совести? или все сразу? сложно..*",117963,null],[117965,"2026-07-16T13:25:52",7,"Немейя\n— Помяни мои слова... Добром не кончится. Мне надо будет отдохнуть, я магию... Магия тяжело поддаётся. Будто выходит из под контроля. Еще пирог какой то странный. Он сколько бы не горел у меня, сколько бы не был, а свежий... Напоминает хлеб с пекарни, с приюта.",117957,null],[117966,"2026-07-16T13:27:15",17,"/ Кинь анализ",117964,null],[117967,"2026-07-16T13:27:57",17,"— А мне напоминает мамины пирожки по праздникам.... Но отец строго наказал не есть их.",117965,null],[117968,"2026-07-16T13:27:59",31,"/roll d20",117966,null],[117970,"2026-07-16T13:28:57",17,"Удерживала его цепь, а надеть её Донавич смог вероятно потому что смог достучаться до своего сына внутри этого судовища. Но голод превратили его окончательно в монстра. Или... не окончательно?",117968,null],[117974,"2026-07-16T13:29:59",31,"кажется, что угостившись нашей кровью, он таки окончательно принял сторону",112272,null],[117977,"2026-07-16T13:31:29",17,"Ты даже думаешь, что столкнул его в бездну собственными руками",117974,null],[117978,"2026-07-16T13:31:35",7,"Немейя\n— А почему? Не знаешь? Просто мне это кажется подозрительным самой...",117967,null],[117981,"2026-07-16T13:32:58",31,"это как с алкоголиками, никто не заставлял его пить, то что ему налили. моя вина тут минимальна, если вообше есть",117977,null],[117982,"2026-07-16T13:33:22",31,"и вообще, виноват тот, кто обратьил пацана",112272,null],[117983,"2026-07-16T13:33:37",31,"вот его надо выебать и высушить. если силенок хватит",112272,null],[117986,"2026-07-16T13:34:45",9,"//Отбитые крестьяне. Всё больше ощущение что Тарх Темноградец ^^",112272,null],[117988,"2026-07-16T13:35:00",7,"/ Немейя недовольно ворчит",112272,null],[117989,"2026-07-16T13:35:54",9,"*Ридли вышел из подвала, сел на пороге часовенки и сидит наблюдая уходящий марш мёртвых и облака, густые и непроглядные.*",112272,null],[117990,"2026-07-16T13:36:15",31,"Элазиец он. Это просто мир такой//",117986,null],[118004,"2026-07-16T15:14:17",17,"— Это очень подозрительно и жутко. Они ходят с тележками по всем городам и продают эти пироги. Не спорю на вид все прекрасно. Но как они с пирогами и деньгами избегают нападений? От бандитов, от мертвецов. Почему у графа нет у ним вопросов? Все это очень странно. Отец от того и запретил нам их есть и сам не ел.",117978,null],[118005,"2026-07-16T15:15:30",17,"Огонь погребального костра разгорается. Тело бургомистра начинает тлеть, позже гореть. \n\nИсмарк стоит все время у костра и смотрит в глаза мёртвому отцу. Перенимая бремя правления. Он внутренне принял свою судьбу.\n\nОсталось решить, что же делать с вампирским отродьем в подвале церкви?",112272,null],[118006,"2026-07-16T15:15:35",17,"/ Что вы будете делать?",112272,null],[118007,"2026-07-16T15:16:16",9,"//Минус ручки, минус ножки, получился вампир самовар ^^",112272,null],[118008,"2026-07-16T15:19:24",31,"- предлагаю поговорить со святым отцом, и убедить его что уничтожение - это единственный адекватный выход. Его сын уже не кго сын, а орудие воли графа",112272,null],[118009,"2026-07-16T15:20:39",9,"//А я хотел дать отцу паёк и не лезть в это дело 😏👌",112272,null],[118010,"2026-07-16T15:21:18",31,"Так ты собственно и дал паек. Самым первым/",118009,null],[118011,"2026-07-16T15:21:47",9,"//И вы полезли в подвал. Лан, я щас хз что отыгрывать",112272,null],[118012,"2026-07-16T15:21:57",9,"//Почилю ^^",117989,null],[118029,"2026-07-16T17:42:48",31,"Ну так что, какие у кого еще мысли по вампиренку? Валим, или пусть живет, вдруг пригодится? Есть у кого вопросы к святому отцу? Может уже и бургомистра сожжём? Весь день никуда не движемся, я уже спать через пару часов пойду)))//",112272,null],[118030,"2026-07-16T17:43:21",9,"//Перса никто не дёргаеь, он отдыхает",112272,null],[118031,"2026-07-16T17:47:00",7,"/ ну его уже сожгли же. А так, Немейя уставшая ничего не делает пока, ждет лишь товарищей, дабы уйти. Также очень сильно дуется и в плохом настроении",118029,null],[118055,"2026-07-16T18:20:22",17,"Через несколько часов отец Донавич пришел в себя.\n\nисмарк сидел на лавке в церкви и приглядывал за ним. Дернулся когда услышал хриплый голос Донавича\n\n— В-в-воды... прошу..",112272,null],[118058,"2026-07-16T18:21:05",17,"Он дал ему испить воды и помог подняться в позу сидя. Забинтованые ожоги сильно ссаднили искажая его осунувшееся лицо гримасой боли",112272,null],[118060,"2026-07-16T18:21:20",17,"/Вы можете говорить с Донавичем, с Исмарком или отправляться дальше куда хотите",112272,null],[118067,"2026-07-16T18:22:47",7,"/ Немейя не хочет говорить с святым отцом ( А кто оставил ожоги и намеренно их не убрал и пытался сына сжечь ), а Истмарком уже поболтала чутка по душам",112272,null],[118068,"2026-07-16T18:22:53",7,"/ даже попрощались",112272,null],[118071,"2026-07-16T18:23:30",7,"/ технически, если это вампир, то кол в сердце",112272,null],[118072,"2026-07-16T18:23:35",7,"/ паралич обеспечен",112272,null],[118108,"2026-07-16T18:32:19",9,"*Ридли когда понял что святой отец очнулся, вздознул и поднялся со своего места, пришёл помочь Исмарку.*\n\n— Отдохните святой отец. — *Он оторвал часть подола савана что уже и так похож на тряпку и смочил её положив ему на лоб.* — У нас есть немного времени подумать что делать с вашим сыном. Скорее всего его уже не спасти, если и есть шансы то они сыпятся как песок сквозь пальцы. Думаю граф не хочет видеть как он излечится, а это значит что у нас скорей всего ничего не выйдет.\n\n*Заменяет мокрую тряпку и даёт старику немного поесть.*\n\n— Простите святой отец, может в будущем, но сейчас слишком слаб чтобы на что-то повлиять.",118055,null],[118178,"2026-07-16T18:43:51",17,"— Нн-н есть же средство... Есть же лекартво... Точно есть...\n\nДонавич опускает голову, это смирение вперемешку с тотальной грустью",112272,null],[118180,"2026-07-16T18:44:16",17,"— Вы знаете как создают таких отродий?\n\nИсмарк вдруг задаёт прямой вопрос героям",112272,null],[118201,"2026-07-16T18:47:02",9,"— Как создают — примерно. Способы лечения? Кроме как убить прародителя не слышал, может и есть но о них не знаю. — *Покачал головой.*\n\n//Этот персонаж не знает того чего не знаю я или в чем не уверен, сам не ипу",112272,null],[118274,"2026-07-16T19:00:35",17,"— Высшая магия жреца утреннего бога может помочь. Такой есть, я слышал от отца. В Аббатстве Креск.",112272,null],[118282,"2026-07-16T19:01:29",17,"На улице проливной дождь. Ветер завывает и шатает рамы. Из разбитого окна видно замок графа. Молния сверкает на фоне освещаяя его электрическим блеском.",112272,null],[118284,"2026-07-16T19:01:31",17,"Замок Ривенкрофт.",112272,null],[118310,"2026-07-16T19:05:38",7,"/ я знаю",118201,null],[118312,"2026-07-16T19:05:44",7,"/ а персонаж нет:)",112272,null],[118343,"2026-07-16T19:08:39",9,"//Я создаю персов которые знают + - то же что и я, а я во многом не шарю)",112272,null],[118346,"2026-07-16T19:09:53",7,"/ а я просто знаю\nНо не скажу",112272,null],[118351,"2026-07-16T19:10:45",31,"- это очень эфемерная надежда, но я думаю мы можем проверить и спросить в Аббатстве. Как туда попасть?",118274,null],[118369,"2026-07-16T19:13:18",17,"— Аббадство находится далеко на краю графства. Нужно пройти Валаки, Виноградники, деревню Березы и только после этого будет Аббадство Креск.",118351,null],[118373,"2026-07-16T19:14:03",31,"Аббат примет нас?",112272,null],[118396,"2026-07-16T19:17:09",17,"— Я там не был. Говорят тамошний аббат - святой.",112272,null],[118405,"2026-07-16T19:18:07",31,"- сомневаюсь что на этой земле есть что то реально святое",112272,null],[118411,"2026-07-16T19:18:45",31,"*мысли про себя*\n- может этот аббат и не святой, но может подсказать, что делать с графом",112272,null],[118424,"2026-07-16T19:19:56",7,"/ сколько опыта за рп? :^",118396,null],[118426,"2026-07-16T19:20:05",7,"/ ти писаль позже напишешь",112272,null],[118433,"2026-07-16T19:21:06",17,"/ ЗА РП 50 опыта!",112272,null],[118438,"2026-07-16T19:21:47",60,"//кроме меня",118433,null],[118441,"2026-07-16T19:21:51",60,"//я опять",112272,null],[118446,"2026-07-16T19:22:07",7,"/   это за конфликт",118438,null],[118447,"2026-07-16T19:22:08",17,"/ Да",112272,null],[118448,"2026-07-16T19:22:16",7,"/ ты и я ток",112272,null],[118449,"2026-07-16T19:22:17",17,"/ Когда нибудь смит просто будет играть короткими постами в потоке",112272,null],[118452,"2026-07-16T19:22:21",17,"/ И будет счастлив",112272,null],[118454,"2026-07-16T19:22:43",17,"/ Там всем запишите 50 за всё",112272,null],[118458,"2026-07-16T19:23:03",7,"/ найс",112272,null],[118480,"2026-07-16T19:26:58",31,"- должен сказать, я не очень верю что вашего сына можно спасти, и считаю более милосердным и для вас и для него просто отпустить его. Он ведь по факту глаза и уши графа в вашем храме. Но, мы его уже один раз пощадили, пусть это и было не очень общее решение. Я думаю, мы все твуи сходим в Аббатство, но очень надеюсь что вы обеспечите невозмодность Дору покинуть подвал, не знаю как, установите чтоди ловушки со святой водой, или там с осиновыми колами. И не давайте ему крови, но своей, ни чужой. Так вы только кормите его тьму, и она растет, а он перестает быть человеком все больше и больше",112272,null],[118486,"2026-07-16T19:27:53",31,"- и да, будьте готовы к тому, что аббат не сможет помочь. Тогда останется только один выход. Смиритесь с этим",112272,null],[118488,"2026-07-16T19:28:40",31,"//надеюсь никто не против что я взял разговорную инициативу и пообещал посетить аббатство?//",112272,null],[118492,"2026-07-16T19:29:14",7,"/ придётся",112272,null],[118500,"2026-07-16T19:29:58",7,"/ я ничего не говорил",112272,null],[118505,"2026-07-16T19:30:41",9,"— Всё равно сидеть на месте плохая идея. Если есть способ лучше о нём знать. — *Согласился Ридли с намеченным планом.*",118486,null],[118510,"2026-07-16T19:31:44",31,"- святой отец, у вас есть какие то ресурсы для нашего путешествия? Та же святая вода, или может едой поделитесь? А то я своим крестьянским глазом оценил, что тут пустоваты поля.",112272,null],[118515,"2026-07-16T19:32:19",31,"/раскрутим пастора по полной, хочет спасти сына - пусть выворачивает карманы//",112272,null],[118526,"2026-07-16T19:34:07",9,"— Еды у меня есть немного, не нужно.",118510,null],[118638,"2026-07-16T19:56:45",17,"— Я поделюсь всем, что есть. Только прошу, не убивайте моего сына.",118510,null],[118640,"2026-07-16T19:57:12",17,"/ Вы можете получить 2 фляги святой воды. 1 паек в виде церковных просфирок.",112272,null],[118677,"2026-07-16T20:03:49",31,"*Забираю*",118640,null],[118678,"2026-07-16T20:04:16",31,"- думаю, нам пора. Держим путь на Валаки для начала",112272,null],[118679,"2026-07-16T20:04:33",17,"Рука священника сжимает твою ладонь\n\n— Забирай. Но дай слово, что мой сын не будет убит вами.",118677,null],[118681,"2026-07-16T20:05:02",31,"- только если он не оставит нам иного выхода",118679,null],[118917,"2026-07-16T20:52:24",17,"/ правильно понимаю тут ждём Смита. И ваше решение что делаете с Дору? Оставляете или что?",112272,null],[118918,"2026-07-16T20:52:34",17,"/ Весь вечер свободен был как бы.",112272,null],[118926,"2026-07-16T20:54:23",7,"/ я Дору бы сжег непринимая подношение священника",118918,null],[118928,"2026-07-16T20:54:33",7,"/ но увы, я жду товарищей",112272,null],[119078,"2026-07-16T21:32:04",60,"—Видно так.. Но пацана держать в цепях и не выпускать. Дождёмся лекарей, иначе я устроил херню на пустом месте. А я ненавижу ошибаться.",118678,null],[119107,"2026-07-16T21:42:14",17,"Сколько ты планируешь ждать лекарей?",112272,null],[119111,"2026-07-16T21:42:49",60,"//ну дня два, сколько там может быть. Может 3-4",119107,null],[119114,"2026-07-16T21:43:16",7,"/ ты будешь ждать?",119111,null],[119115,"2026-07-16T21:43:22",7,"/ мы планировали пойти просто",112272,null],[119132,"2026-07-16T21:46:30",17,"/ Ну жди. Остальные уходят? Исмарк просто уйдет ему надо делами деревни заниматься",112272,null],[119146,"2026-07-16T21:49:34",60,"//я с вами",119115,null],[119148,"2026-07-16T21:49:49",60,"//тип речь про то, что пацана не надо сейчас убивать",112272,null],[119228,"2026-07-16T22:08:27",9,"//Ахуенно, тот паёк что оставлял я — забрали",118640,null],[119240,"2026-07-16T22:10:46",9,"//Тоесть мы просто ждём?",112272,null],[119251,"2026-07-16T22:14:11",17,"/ нет вы уходите",112272,null],[119254,"2026-07-16T22:14:28",17,"/ Опишите как вы уходите и на этом арка будет закрыта, последствия настигнут вас позже",112272,null],[119264,"2026-07-16T22:16:35",9,"*Ридли втихаря оставляет отцу пару пайков, с него не убудет, а как грабят старика смотреть он не хотел.*\n\n//-2 рациона, больше решил не оставлять пока, дамаю отца подкармливают и так.",112272,null],[119271,"2026-07-16T22:18:04",9,"— Пусть направит вас восход святой отец. — *Сказал он и уходя прошептал уже себе под нос.* — А после солнце прольёт свет истины.",112272,null],[119299,"2026-07-16T22:22:38",7,"*Немейя без оглядки просто ступала. Она выглядела раздражённой и как минимум слегка отдалилась. На лице читалась обида, а также голод.*",112272,null],[119313,"2026-07-16T22:25:43",9,"//Да покормлю я тебя вечером, я списывал рацион с утра, этого на день должно хватить, тоесть Ридли условно готовил и утром и вечером. Надо побольше провизии с собой таскать, на будущее постараюсь запомнить ^^",119299,null],[119318,"2026-07-16T22:26:46",17,"/ У них с Альфом конфликт. На самом деле варвар заставил вас оставить вампирское отродье в живых. И дальше на самотёк)",119313,null],[119352,"2026-07-16T22:32:11",60,"//пока это не арба, не так страшно",119318,null],[119355,"2026-07-16T22:32:20",60,"//Но его нельзя особо много кормить",112272,null],[119362,"2026-07-16T22:33:26",7,"/ сюравно дуться будет",112272,null],[119498,"2026-07-16T23:02:44",9,"//Чур это наш граф ^^",119495,null],[119783,"2026-07-17T04:05:26",31,"*выяснив у Исмарка направление на Валаки, кладу на плечо свои вилы, и отправляюсь в путь*",112272,null],[119784,"2026-07-17T04:11:18",31,"//чую, дорогу тоже еще предстоит пережить//",112272,null],[119790,"2026-07-17T09:31:48",31,"@dunchev мастер, расскажешь, кто нас будет жопу надирать по дороге?)/",112272,null],[119792,"2026-07-17T09:39:14",17,"/ Щас поработаю и напишу",112272,null],[119998,"2026-07-17T15:58:24",31,"Заработался((",119792,null],[119999,"2026-07-17T15:58:58",7,"/ занят, работа дело такое",112272,null],[120000,"2026-07-17T15:59:01",7,"/ я ждать",112272,null],[120001,"2026-07-17T16:02:29",31,"/понятно что подождем. Просто у меня часы отыгрыша до 20-00 по Москве)/",112272,null],[120002,"2026-07-17T16:02:53",7,"У меня это 12 ночи",112272,null],[120003,"2026-07-17T16:03:01",7,"Я вообще ночью мало сплю ибо днд каеы",112272,null],[120004,"2026-07-17T16:04:07",31,"У меня тоже. Ты откуда?/",120002,null],[120005,"2026-07-17T16:04:37",7,"/ новосибирск",112272,null],[120006,"2026-07-17T16:04:46",7,"/ бывает я не сплю ночь :)",112272,null],[120007,"2026-07-17T16:04:58",7,"/ я конч не обращайте внимания",112272,null],[120008,"2026-07-17T16:05:58",31,"Я из Красноярска) ну я в молодости тоже мог ночь не спать без последствий, сейчас уже тяжело//",112272,null],[120012,"2026-07-17T16:08:46",17,"/ Ну да, сегодня никак. Сижу на созвоне и закрываю таски",112272,null],[120013,"2026-07-17T16:10:35",7,"/ всмысле в молодости, твоей аве больше 22 не дам",120008,null],[120017,"2026-07-17T16:14:32",31,"Ты угулал, на ней мне 22. Сделана в июне 2014))))//",120013,null],[120018,"2026-07-17T16:15:04",31,"Ок, отдыхаем, празднуем пятницу/",120012,null],[120019,"2026-07-17T16:15:09",7,"/ оу",120017,null],[120020,"2026-07-17T16:15:15",7,"/ прости:_",112272,null],[120021,"2026-07-17T16:15:31",7,"/ ты крупный довольно таки",112272,null],[120022,"2026-07-17T16:16:24",31,"/так и есть. В принципе я с тех пор в плане телосложения не изменился, только начал лысеть)))//",112272,null],[120023,"2026-07-17T16:17:41",7,"/ ну лысеть громко сказано, я вообще седею",120022,null],[120024,"2026-07-17T16:18:43",31,"Да я бы лучше седел)) надьседым дедом не так угарают, как над плешивым))//",120023,null],[120201,"2026-07-17T21:01:16",17,"/Кто тут жив?",112272,null],[120207,"2026-07-17T21:03:29",31,"Я, но скоро отключусь скорее всего",112272,null],[120213,"2026-07-17T21:04:31",7,"/ я сэр",120201,null],[120267,"2026-07-17T21:17:44",17,"/ Ожил?",112272,null],[120268,"2026-07-17T21:17:54",17,"/ А Лёшку отправили спать",112272,null],[120281,"2026-07-17T21:27:53",7,"/ грустна",112272,null],[120282,"2026-07-17T21:28:09",7,"/ ну я бензина надышался, рвёт ночью",120267,null],[120299,"2026-07-17T21:38:32",17,"/ Пиздец, зачем ты дышал бензом, ты че отыгрывал пироманта в реальной жизни",112272,null],[120326,"2026-07-17T21:48:05",7,"/ канистру нес и 2 часа сверху сидел возле заправки",120299,null],[120335,"2026-07-17T21:53:15",17,"/ Жоска",112272,null],[120582,"2026-07-18T06:40:08",31,"Ладно, если что, я тут и готов играть. На улице ливень, делать не хрен//",112272,null],[120585,"2026-07-18T08:38:12",7,"/ всем здарова",112272,null],[120637,"2026-07-18T11:49:59",31,"Сегодня опять не играем ?",112272,null],[120641,"2026-07-18T12:03:28",17,"/ В выходные у меня дел много. К обеду ближе возможно. Напишу вам",112272,null],[120708,"2026-07-18T13:18:02",17,"Вы решили оставить Дору в живых. Донавич благодарен вам. Исмарк выглядит напряженным. Теперь ему разбираться с этой проблемой.\n\nТак или иначе вы сделали выбор и отпрвляетесь.\n\nВы собрались и отправились по пути в город Валаки, где всё спокойно.\n\nВы идете под корявыми кронами деревьев которые образовали арку над дорогой.\n\nСейчас вы проходите мимо старого кукурузного поля. Пожухлая кукуруза так и не была убрана, стоит стеной за кривым заборчиком. На поле стоят страшные пугала.\n\n/Внимания групповое",112272,null],[120718,"2026-07-18T13:21:25",31,"- это кого же такое страшилище должно отпугивать?",112272,null],[120719,"2026-07-18T13:21:39",17,"Ты видишь что вороны спокойно садятся на пугала",112272,null],[120720,"2026-07-18T13:21:42",31,"/roll d20+1 на внимание",112272,null],[120723,"2026-07-18T13:22:00",17,"Всё спокойно для тебя",112272,null],[120725,"2026-07-18T13:22:56",60,"/r +3 пельмени прячутся в темноте...",120708,null],[120729,"2026-07-18T13:25:14",17,"Ты краем глаза явно заметил как пугало повернула за вами голову",120725,null],[120731,"2026-07-18T13:25:51",9,"/roll 1d20 внимание вродь без бонуса у меня",112272,null],[120734,"2026-07-18T13:26:12",17,"Ты тоже заметил что пугало дернулось",112272,null],[120735,"2026-07-18T13:27:15",60,"Альфарий пока ничего не сказал, но лишь повернул голову в сторону пугала. Он либо шизик, либо тут что-то нечисто. Он грозно посмотрел на это чучело, показав двумя пальцами жест \"я слежу за тобой\"\n\n—Пс, мне кажется, я знаю, кому тут зарплату не дали...",120729,null],[120741,"2026-07-18T13:29:21",7,"/r d20 +2",112272,null],[120743,"2026-07-18T13:29:33",7,"/просто кинул чтобы не задерживать на внимание",112272,null],[120746,"2026-07-18T13:30:12",17,"Да ты тоже видела. И желание сжечь это мёртвое поле... Появилось внезапно",112272,null],[120750,"2026-07-18T13:31:12",7,"/ так и поступим, я кастую ФАЕРБОЛЛ",120746,null],[120761,"2026-07-18T13:34:45",9,"*Резко поворачивается и стаёт напротив ближайшего пугала.*\n\n— Вы не против если мы пройдём дальше? Простите что тревожим вас, ничего красть или воровать мы не собираемся на поле. — *Сделал лёгкий поклон, но на деле сжал запонку внутри мантии рукой.*\n\n//Заготовленно действие спрятаттся в сосуд если агрессивно среагируют и попытаются атаковать",112272,null],[120764,"2026-07-18T13:35:15",17,"Пугало вдруг опустило голову вниз",112272,null],[120772,"2026-07-18T13:36:32",31,"Чью?/",112272,null],[120773,"2026-07-18T13:36:47",31,"Голову Ридли, чтобы не пялился?)/",112272,null],[120776,"2026-07-18T13:37:53",9,"— Спасибо. — *Поблагодарил и отошёл повернувшись к своим и тихо сказал им всё ещё на стороже.* — Думаю нам не стоит здесь задерживаться.",120764,null],[120786,"2026-07-18T13:41:31",60,"Альф лишь слегка кивнул вверх\n\n—Ты тут мне это, не эт самое.. Голову не морочь, чучело.",120764,null],[120790,"2026-07-18T13:42:47",31,"- поддерживаю. Лучше уйти, пока он не решило нас напугать. По настоящему",120776,null],[120796,"2026-07-18T13:44:48",9,"— Так, всё, пошли. Кыш кыш, не мешай охранять поля. — *Ридли задолбался обьяснять ход своих мыслей и оставаться здесь не хотел. Ему все равно насколько варвар сильнее, он его прогоняет с поля от боя да подальше.*",120786,null],[120801,"2026-07-18T13:46:08",9,"//Вы пока каждого монстра по пути не заипёте не успокоитесь, и вообще, Альф, мог бы прибить вампира или Немея, и слова бы против не сказал ни как перс, ни как игрок, отыгрывайте персов а не ищите лучших решений)",112272,null],[120922,"2026-07-18T14:13:33",17,"Вы идёте дальше. Прямо на вас бежит призрачный силуэт мужчины",112272,null],[120927,"2026-07-18T14:15:15",9,"*Отходит в сторону уступая ему дорогу.*",120924,null],[120937,"2026-07-18T14:18:36",17,"Призрак пока не добежал, всё еще движется на вас",112272,null],[120944,"2026-07-18T14:19:57",60,"Альф на всякий случай готовится, достав меч из-за спины, но отходит к краю дороги\n\n—Бежит мужик, торопится.. Куда бежит, хер знает... Может гонец",112272,null],[121005,"2026-07-18T14:38:28",31,"Тарх отходит в сторону, уступая дорогу",112272,null],[121008,"2026-07-18T14:38:42",17,"Призрак проносится мимо вас",112272,null],[121012,"2026-07-18T14:38:58",17,"Пробежав еще немного он резко изгибает спину\n\nПадает вперед лицом в грязь",112272,null],[121051,"2026-07-18T14:51:29",9,"//Так и помер посланец Максим!",121012,null],[121052,"2026-07-18T14:51:48",60,"—Эу, мужик, тебе нормально?\n\nАльфарий подходит ближе, несмотря на то, что это вроде бы нежить",121012,null],[121053,"2026-07-18T14:52:06",17,"Призрак медленно растворяется у твоих ног",112272,null],[121054,"2026-07-18T14:52:13",17,"Перед вами снова он бежит на вас",112272,null],[121055,"2026-07-18T14:52:22",60,"—...",121053,null],[121063,"2026-07-18T14:53:03",9,"— Просто не стойте у него на пути, идём. — *Страрается обминать ретивого призрака.*",112272,null],[121078,"2026-07-18T14:54:21",60,"—Чё.. Он застрял тут, походу. Бабка говорила мне, что это такое, вроде.. Отголосок. Когда кто-то не успевает что-то закончить и привязывается к какому-то месту, вынужденный лицезреть это вечно. Он уйдет либо когда отвяжется от места, либо когда небеса рухнут и этого места более не станет..",121054,null],[121164,"2026-07-18T15:17:25",17,"/Что ж Департамент видимо занят",112272,null],[121167,"2026-07-18T15:18:33",9,"//Я тогда тож вздремну пойду, через часок-два вернусь. Игры ни в таверне, ни тут ни ко мне на квест с экстрасенсами не идут, вечером надеюсь нормас будет",112272,null],[122420,"2026-07-18T19:12:38",7,"/ айм бэкс",112272,null],[122434,"2026-07-18T19:18:24",7,"*Немейя молча наблюдала за призраком. Она с голодным взглядом, лишь фыркнула и вздохнув сказала.*\n\n— Ребята, обычные души. Кому не безразличны отголоски прошлого? Я бы поняла, если можно было бы просто даже с ним поговорить. \n\n*Немейя говорила крайне недовольно, но не грубо. По крайней мере пыталась,  она просто наблюдала за ребятами.*",121054,null],[122440,"2026-07-18T19:20:08",60,"—Потому что если игнорировать их, то шанс стать таковым растёт.. Так говорили на моей родине. Помочь ему — час. Лицезреть цикл потом — вечность. Это выбор... Очевидный.",122434,null],[122443,"2026-07-18T19:21:50",7,"Немейя\n— Даже если ты хочешь помочь, что сделаешь? Поймаешь его и не дашь пасть лицом в грязь? Очевидный выбор, пф.",112272,null],[122459,"2026-07-18T19:24:49",60,"—Не думаю, что смогу его дотронуться. Об этом мне не говорили... Но он должен слышать слова, как и видеть этот мир. Отголосок уйдет лишь тогда, когда поймет, что его здесь больше ничего не держит. Если он действительно гонец, то ему нужно сказать лишь, что послание доставлено. Если нет.. Что всё получилось. Конкретика порой лишняя.",122443,null],[122470,"2026-07-18T19:26:56",7,"Немейя\n— Ну вот и говори ему, что работа закончена или он не справился с задачей и уже поздно, милосердный вы наш.",112272,null],[122486,"2026-07-18T19:32:58",9,"— В Веспирали полно нежити, часто она восстаёт сама по себе без помощи графа. Я предпочёл бы помогать всё ещё живым и тем кто в этом нуждается.",112272,null],[122525,"2026-07-18T19:42:35",17,"/Внимание всем можно",112272,null],[122534,"2026-07-18T19:43:38",31,"/roll d20+1",112272,null],[122545,"2026-07-18T19:44:47",17,"Позади там где он падает лежит сумка гонца",112272,null],[122550,"2026-07-18T19:45:31",31,"Проверю ее содержимое",112272,null],[122551,"2026-07-18T19:45:34",7,"/r d20 +2 нюк нюк Григорий",122525,null],[122553,"2026-07-18T19:45:45",7,"/ затупился от ярости)",122552,null],[122557,"2026-07-18T19:46:10",17,"/А григорий в другом замке",112272,null],[122558,"2026-07-18T19:46:15",7,"/ блять я перепутал",112272,null],[122559,"2026-07-18T19:46:21",7,"/ крыша едет дом стоит",112272,null],[122560,"2026-07-18T19:46:29",7,"/ ну внимание не отличается",112272,null],[122561,"2026-07-18T19:46:36",7,"/ но мало что дает)",112272,null],[122562,"2026-07-18T19:46:45",17,"Ты больше на призраке сосредоточена",112272,null],[122583,"2026-07-18T19:49:55",17,"Там письмо\n\nОт кого: Мельница последней надежды\nМорганта милосердная\n\nКому: Сиротский приют Валаки.\nНастоятельнице Маргарите Вельс.\n\nЗапечатано сургучом",122550,null],[122591,"2026-07-18T19:50:52",31,"- тут письмо. Недоставленное. И нам по пути",122583,null],[122627,"2026-07-18T19:56:42",9,"— Думаешь он умер от простого падения? — *Оглядывается на поле.* — Или его убили.",112272,null],[122632,"2026-07-18T19:57:21",31,"- ну, пока я только могу сказать что он мертвый, но очень ответственный",112272,null],[122642,"2026-07-18T19:58:28",7,"Немейя\n— Или может он болел чем-то, или может его убил туман что мог здесь быть и от чего он убегал. Кому не безразлично? Ладно, берите письма и пойдёмте... ( Недовольно )",112272,null],[122723,"2026-07-18T20:21:06",7,"/ Гайс?",112272,null],[122731,"2026-07-18T20:22:53",60,"/roll +3",122525,null],[122734,"2026-07-18T20:23:07",17,"да, сумка",122731,null],[122741,"2026-07-18T20:23:48",60,"—Ну вот, я ж говорил, он не справился.\n\nАльф поворачивается к призраку\n\n—Письмо доставлено. Твоя цель достигнута, ты свободен...",122642,null],[122756,"2026-07-18T20:25:59",9,"*Было одно но. Ридли, если ему показали на сумку, смотрит, она ж недавняя? Тоесть свежая ли пропажа.*",112272,null],[122777,"2026-07-18T20:29:17",7,"*Немейя поняв, что товарищи здесь на долго... Просто начала осматриваться. Она выглядела подготовленной, вдруг зомби проходить будут мимолётно... Будет крайне неприятно встретить их. Можно сказать, что она решила посторожить команду. Параллельно отвлекала себя от голода при помощи шарика пламени, что создала и периодически перекидывала из руки в руку.*",112272,null],[122787,"2026-07-18T20:30:00",9,"//Минута, может две от силы прошли, но ладно. У меня просто подозрение",112272,null],[122793,"2026-07-18T20:30:25",17,"Реакции на слова нет",122741,null],[122795,"2026-07-18T20:30:29",9,"//Достаточно узнать свежая ли сумка, не полежавшая под дождём и тд",112272,null],[122798,"2026-07-18T20:30:52",7,"/ моему персонажу безразличны детали и она встала на дозор, если что @dunchev",112272,null],[122810,"2026-07-18T20:32:57",60,"Фирболг чешет репу: он вообще впервые видит отголосок.\n\n—Ну, ты это.. Письмо... Да ну нахер, я не знаю, чё делать!",122793,null],[122832,"2026-07-18T20:35:52",17,"Уже не очень, но и не долго лежала",122795,null],[122872,"2026-07-18T20:42:56",31,"- я считаю, раз нам по пути, то стоит донести письмо. Не думаю что это будет сложно, зато поможем душе упокоится",112272,null],[122875,"2026-07-18T20:44:27",9,"— Тела нет, сумка не кажется такой сторой а костей не видно. — *Обернулся на поле, проведя глазами по нему.* — Думаю гонец стал удобрением. Надо идти, здесь опасно.",122832,null],[122904,"2026-07-18T20:47:44",17,"Вы идёте дальше перед вами столб буквой Г на нём висит мертвец в петле",112272,null],[122924,"2026-07-18T20:50:18",9,"*Закрывает глаза под маской, долго думает, потом спрашивает своих товарищей.*\n\n— Напомните куда мы идём?",112272,null],[122928,"2026-07-18T20:51:09",7,"*Немейя вздрагивает внезапно. Крылья слегка приподняли пыль, а также мурашки прошли по коже. Это был не испуг, а неприятное удивление и отвращение в одном лице.*\n\n— Твою мать... Сразу видно, граф хорошо устроился, страна развивается... А я кушать захотела, уже как пол часа... Вроде направляемся к целителям, нет?\n\n*Говорит сначала с отвращением, но после услышав вопрос, вполне себе спокойно отвечает.*",112272,null],[122929,"2026-07-18T20:51:17",60,"//он похож на гонца?",122906,null],[122934,"2026-07-18T20:51:54",9,"— Название места.",122928,null],[122935,"2026-07-18T20:52:07",9,"//Я забыл, буду вас спрашивать",112272,null],[122940,"2026-07-18T20:52:39",60,"—Ну вот, нашли.. И без понятия, как сумка оказалась отдельно даже и какого хрена вообще по дороге стоит виселица. Че за перевалочный пункт?. А идем мы в Валаку.",112272,null],[122967,"2026-07-18T20:55:20",9,"*Ридли стоит, думает, стоит ли, вздыхает... все де подходит к мертвецу что висит на виселице ближе и спрашивает.*\n\n— Простите что тревожу, подскажите, как пройти в Валаку.",112272,null],[122973,"2026-07-18T20:55:54",9,"//Вот и всё. Вы знаете что такое безумие?)))",112272,null],[122974,"2026-07-18T20:56:16",7,"Немейя\n— Ты серьёзно думаешь, что он тебе ответит? Ридли, ты в себе?",122967,null],[122989,"2026-07-18T20:58:27",9,"— Мёртвые знают больше живых. И вспомните поле, просто было достаточно попросить нас не трогать. Уверен мы бы могли повторить судьбу призрака. — *После смотрит на висящего человека.* — Хотя ты права, если его душа не здесь нам не ответят.",122974,null],[122992,"2026-07-18T20:58:47",17,"Ответа от мертвеца нет",112272,null],[122995,"2026-07-18T20:59:38",9,"— Как и догадывался. Если у вас ничего — пошли.",122992,null],[122999,"2026-07-18T20:59:57",9,"//Не попробовали бы не узнали)",122992,null],[123001,"2026-07-18T21:00:28",7,"Немейя\n— Клянусь пламенем, чушь какую то творите... Давайте поищем здесь ягод, не знаю. Что нибудь по пути съедобное отыскать хотелось бы, уж извольте простить за ворчание.",112272,null],[123007,"2026-07-18T21:01:47",9,"— Есть еда, поделюсь когда устроим привал.\n\n//Дм кстати, говори скок рационов списывать, а то я хз скок ыремени прошло, будем кормить группу, чё",112272,null],[123029,"2026-07-18T21:06:16",17,"/ Ну пока не сказал и не списывайте",112272,null],[123031,"2026-07-18T21:06:28",17,"/ вы идете дальше?",112272,null],[123083,"2026-07-18T21:12:06",7,"/ да идем. Только тихо наверно и не спеша",112272,null],[123110,"2026-07-18T21:18:04",17,"/Киньте внимание",112272,null],[123140,"2026-07-18T21:22:11",9,"/roll 1d20 Внимание",112272,null],[123143,"2026-07-18T21:22:34",17,"Вы отошли подальше и ты краем глаза смотришь назад. А тела на виселице уже нет",112272,null],[123144,"2026-07-18T21:22:37",31,"/r +1 внимание",112272,null],[123151,"2026-07-18T21:23:45",17,"/ Тоже замечаешь",123144,null],[123152,"2026-07-18T21:23:48",9,"— Мертвец решил погулять. — *Сказал не оборачиваясь и не сбавляя шага.*",112272,null],[123161,"2026-07-18T21:24:46",31,"- хреновые для нас новости. Нужно бы ускориться",112272,null],[123179,"2026-07-18T21:30:40",60,"/roll +3",123110,null],[123187,"2026-07-18T21:31:22",60,"—Чё...\n\nАльф оборачивается и замечает, что тела нет на месте. Он тихо говорит\n\n—Да ну нахер, и когда он вернется теперь?..",123152,null],[123229,"2026-07-18T21:41:04",7,"/r d20 +2 внимательная любительница огня",123110,null],[123231,"2026-07-18T21:41:13",7,"/roll@roll_bot",112272,null],[123233,"2026-07-18T21:41:29",7,"/ ну 21",123232,null],[123235,"2026-07-18T21:42:08",7,"/ обычно когда я так пинаю бота считается за мой бросок",112272,null],[123900,"2026-07-19T01:05:34",17,"И вы идете дальше висельник остаётся позади, точнее тело пропало, и только петля качается на ветру",112272,null],[123902,"2026-07-19T01:06:09",17,"Вы доходите развилки справа дорога идёт к Мельнице последней надежды \n\nДорога вперёд ведёт к Валаки",112272,null],[123903,"2026-07-19T01:06:29",17,"Мельница последней надежды",112272,null],[123909,"2026-07-19T01:07:58",9,"//Ну, думаю буду ждать остальных",112272,null],[124022,"2026-07-19T07:57:50",31,"- на мельницу нам не надо, мы идем в город, по дороге нужно занести письмо в приют",112272,null],[124026,"2026-07-19T09:51:44",17,"Со стороны мельницы чувствуется сладкий запах пирогов",112272,null],[124044,"2026-07-19T10:36:57",31,"- похоже, бабуля с пирогами там живёт. Запомним и позже навестим?",112272,null],[124047,"2026-07-19T10:39:32",9,"— Думаю не стоит. Это может быть карга, она откармливает себе добычу помясистее вкусными пирогами. Тут же мы сами на ужин заявимся. — *Одновременно немного пугает Тарха и строит догадки.*",124044,null],[124050,"2026-07-19T10:53:25",60,"—Ну подойти посмотреть то мож стоит, не? Мало ли что там творится. Чисто на всякий",124047,null],[124051,"2026-07-19T10:56:28",9,"*Пожимает плечами.*\n\n— Уже сказал что думаю об этом, но не решаю за вас. — *С теми кто пробудил свой потенциал и силы Ридли не сильно хотел спорить. Иметь во врагах таких личностей может быть опаснее чем граф или карга.*",124050,null],[124052,"2026-07-19T10:58:11",31,"- у нас есть цель, я бы лучше согласился с Ридли, всегда успеем вернутся",112272,null],[124053,"2026-07-19T11:12:07",60,"—А вдруг она уже кого поймала? Че нам, просто мимо идти?",112272,null],[124060,"2026-07-19T11:22:18",31,"- ты забыл что уже пожалел одного монстра и мы теперь ищем для него лекарство? Уверен что стоит отвлекаться и идти куда то еще, не закончив первое дело?",124053,null],[124066,"2026-07-19T11:23:34",60,"—Ясно, я понял. У вас другие взгляды. Большинство против. Похер, пусть сами разбираются. Двигаем.\n\nСказал Альф, но на всякий случай решил просто заглянуть в окно",124060,null],[124081,"2026-07-19T11:31:11",17,"/ Далеко до окна. Вы на развилке",112272,null],[124090,"2026-07-19T11:35:11",60,"Значит дыхалку отрабатываем, тыгыдык",124081,null],[124091,"2026-07-19T11:35:11",31,"Да пусть бы кинул на внимание, вдруг 20 выпадет)/",124081,null],[124125,"2026-07-19T13:13:01",17,"Вороны каркают на деревянной стрелке указывающей к мельнице\n\nЧто это призыв или знак предупреждения так сразу и непонятно",112272,null],[124126,"2026-07-19T13:14:04",17,"Вы идете дальше и находите табор циган у озера\n\nШатры высокие, костры большие, кибитки и повозки деревянные. И много лошадей посутся рядом.",112272,null],[124128,"2026-07-19T13:14:19",17,"/ приду позже. Занят",112272,null],[124129,"2026-07-19T13:17:59",9,"//Ахахха, хорошо что у меня нет коня и что красть, только цепи на руках и порванная мантия с маской, разве что шнурки на ботинках 😏👌",112272,null],[124130,"2026-07-19T13:21:27",31,"- цыгане-вистани. Кажется, о них нам говорили что они могут ходить сквозь туман. Интересно, нам они раскроют эту тайну? Мало ли, вдруг бежать придется",112272,null],[124140,"2026-07-19T13:29:09",9,"— Думаю они могут только потому что им разрешили. — *Ридли был скептически настроен по этому поводу, успел поубавить ожидания после последних наблюдений, хотя он мог и ошибаться в своём суждении.* — Но попытка не пытка.",124130,null],[124248,"2026-07-19T16:12:59",17,"/ Пост для реакций. Когда все будут тут продолжим",112272,null],[124249,"2026-07-19T16:23:37",31,"Тут/",112272,null],[124250,"2026-07-19T16:23:53",31,"Давайте продолжим, хочу к цыганам сходить/",112272,null],[124258,"2026-07-19T16:37:10",17,"Вам машет кучерявый парень. Жестами он зазывает подойти.",112272,null],[124259,"2026-07-19T16:39:12",31,"- зайдем? \n\n*обращаюсь к партии*\n\n- эти хотя бы живые. На вид",112272,null],[124260,"2026-07-19T16:40:12",17,"Вы видите что у большого костра цигане играют на музыкальных инструментах зажигательную мелодию. Пьют вино и танцуют",112272,null],[124268,"2026-07-19T16:58:16",7,"/ я вернулся гайс:_",112272,null],[124269,"2026-07-19T17:00:25",7,"*Девушка осматривая караваны, видит что то подозрительное... Может снова какая то разумная нежить, что маскируется под людей... Как иначе прошли бы они сквозь туман... Так или иначе, она закатив глаза отвечает недовольным тоном.*\n\n— Я не знаю, может и вежливей трупов, но... Мне кажется подозрительным... Особенно что это рядом с хижиной карги той...",124259,null],[124273,"2026-07-19T17:02:43",31,"Подхожу к костру, здороваюсь\n\n- добрый вечер, мир вашим кострам",112272,null],[124300,"2026-07-19T17:19:57",17,"— Добрые путники. Не бойтесь, мы мирный народ, приглашаем вас к костру, еда, вино, ночлег все у нас есть и всем мы поделимся безвозмездно. Добро пожаловать в табор Новолуния. Меня звать Мойша и я тутошнего барона сын.",112272,null],[124301,"2026-07-19T17:20:08",17,"Мойша. Барона сын.",112272,null],[124310,"2026-07-19T17:24:27",31,"На цыган будет распространяться мое умение деревенское гостеприимство?/",112272,null],[124311,"2026-07-19T17:24:58",9,"*Просто молча садится у костра.*",112272,null],[124314,"2026-07-19T17:31:22",17,"/ Ну давай да",124310,null],[124317,"2026-07-19T17:32:19",7,"/ Мойша, ты был избранником! ( Евреем был )",124301,null],[124319,"2026-07-19T17:32:59",17,"/ Но предал Христа",112272,null],[124321,"2026-07-19T17:33:23",31,"- Привет, Мойша! Я Тарх, а это мои друзья. Еда, вино и ночлег это звучит отлично. А беседа у костра под это самое вино и еду еще лучше",112272,null],[124323,"2026-07-19T17:34:23",17,"— Хорошей беседы мы всегда рады. Что на пути видели? Есть о чем рассказать?",112272,null],[124325,"2026-07-19T17:35:20",7,"*Немейя решает подойти тоже к цыганам. Однако она не отходит далеко от знакомых. Осматриваясь, ее терзают смутные сомнения. Оно и не мудрено, сколько нежити было... Так или иначе, она пытается лишний раз удовлетвориться в том, что цыгане хотя бы не вампиры.*\n\n/ Хочу осмотреться и проанализировать цыган",112272,null],[124326,"2026-07-19T17:35:27",31,"- ну, тут по дороге странное происходит. Призраки бродят, пугала кивают, от заброшенной мельницы запах свежих пирожков идет. Странная тут земля. А вокруг еще и туман какой то странный",112272,null],[124352,"2026-07-19T17:45:18",17,"— Все так. Лучше и не опишешь. Земля странная, местами страшная, но люди продолжают жить. Жизнь побеждает смерть, это ли не самое странное?",112272,null],[124357,"2026-07-19T17:46:22",31,"- Смерть все равно свое возьмет. Мы можем только оттягивать ее приход. И надеятся что в конце получим покой",112272,null],[124361,"2026-07-19T17:47:21",17,"— Ну не скажи. Мы создаём жизни новые. И смерть всегда проигрывает в этом колесе.",112272,null],[124362,"2026-07-19T17:47:48",7,"/r d20 +2 внимание",112272,null],[124364,"2026-07-19T17:47:58",7,"/  боженька подкинул",112272,null],[124383,"2026-07-19T17:56:06",17,"Ты замечаешь что детишки выглядывают позади из за кибитки. И в руках у них странная игрушка. Игрушечная гильятина.\n\nОни переговариваются и ты даже слышишь тонким слухом обрывки фраз \n\n— Демон! Крылатая бестия! Интересно они хвосты как ящерицы отбрасывают? Надо проверить!",112272,null],[124399,"2026-07-19T18:03:42",7,"*Проигнорировав детишек, она чувствует себя не в своей тарелке. Возвращаясь к ребятам, она становиться рядом и присаживается. Касается пола и создает пламя, рядом с которым может сидеть.*\n\n— Угу... Ребят, если что вдруг, я здесь посижу. Это все окружение меня выматывает.",112272,null],[124400,"2026-07-19T18:06:08",31,"- а чем вы тут занимаетесь? Вы выглядите слишком ярким пятном для местой серости",124361,null],[124407,"2026-07-19T18:13:10",17,"— Сейчас табор стоит на привале. Дальше мы поедем по Багровии торговать. Кочуем с места на место.",124400,null],[124418,"2026-07-19T18:18:36",31,"- а из самой Багровии выезжаете? Тут просто такое впечатление складыватся, что сюда легко попасть, а вот покинуть это место сложно",124407,null],[124425,"2026-07-19T18:38:18",9,"//Я тут, просто хз что делать",112272,null],[124426,"2026-07-19T18:38:32",9,"*Ридли просто сидит и слушает.*",112272,null],[124427,"2026-07-19T18:38:40",7,"/ я думаю как персонаж, что здесь все вампиры",112272,null],[124428,"2026-07-19T18:39:37",7,"/Везде почти одна нежить блуждает",112272,null],[124430,"2026-07-19T18:42:18",31,"/roll +d20 на восприятие. Оглядываю Мойшу и прочих цыган на предмет вампиризма",112272,null],[124482,"2026-07-19T20:07:08",17,"Обычные люди",124430,null],[124486,"2026-07-19T20:07:38",17,"— Да, у нас проблем нет. Мы свободны, как вольный ветер.",124418,null],[124487,"2026-07-19T20:08:30",17,"— Ешьте. Пейте. Танцуйте. Если надоест можете сходить в нашей гадалке, мадам Еве. Она вам судьбу предскажет на картах Таррока",112272,null],[124488,"2026-07-19T20:08:48",7,"/ хм, может Немейя чутка отдохнёт и расслабиться, в кругу цыган",112272,null],[124489,"2026-07-19T20:08:53",7,"/ ценного ничего нет",112272,null],[124508,"2026-07-19T20:23:24",31,"- Гадалка? Ну а почему бы и нет?\n\n*Тарх чутка захмелел от халявной выпивки, хочется действий*\n\n- Ребята, навестим мадам Еву?",124487,null],[124509,"2026-07-19T20:26:49",7,"Немейя\n— Угу... Почему нет, если бесплатно. У меня дырка в кошельке.",112272,null],[124513,"2026-07-19T20:34:54",17,"/ Тэгайте Смита он совсем уснул",112272,null],[124515,"2026-07-19T20:35:48",7,"/ @FSmit7 го дуэль?",112272,null],[124516,"2026-07-19T20:35:56",7,"/ должно сработать",112272,null],[124517,"2026-07-19T20:37:10",60,"//я на ирл игре пока",112272,null],[124518,"2026-07-19T20:37:53",7,"/ ну сработать сработало\nА дальше приказов не было, удачи на ирл катке",112272,null],[125180,"2026-07-20T07:00:37",7,"/ итак господа",112272,null],[125181,"2026-07-20T07:01:24",7,"/ го к цыганам? Погадают",112272,null],[125182,"2026-07-20T07:02:41",31,"да мы и так у цыган, бухаем у костра. Ну и к гадалке хотим сгонять. я во всяком случае//",112272,null],[125183,"2026-07-20T07:03:54",9,"//Я то проснулся, но дела, могу пропасть. Не обращайте внимания и не ждите если не реагирую 😏👌",112272,null],[125184,"2026-07-20T07:05:31",7,"/ я тоже к цыганке зайду. Раз бесплатно, надеюсь на то, что не обманут",125182,null],[125185,"2026-07-20T10:46:56",60,"//только я хотел как раз сбегать быстро до мельницы и заглянуть, что там..",124125,null],[125186,"2026-07-20T10:47:01",60,".",124090,null],[125187,"2026-07-20T10:47:10",60,"//ладно, это было написано не очевидно",112272,null],[125188,"2026-07-20T10:47:25",60,"//но я прям чую жопой, что там бабка из Арбы",112272,null],[125189,"2026-07-20T10:49:14",17,"/ Мельница никуда не денется. Пирожки должны течь по всем землям",112272,null],[125190,"2026-07-20T10:49:25",31,"что за Арба?/",125188,null],[125191,"2026-07-20T10:49:58",31,"кстати, а мы же можем гадалку спросить о пирожках и мельнице//",112272,null],[125192,"2026-07-20T10:50:36",17,"/ Да вы чё хотите можете. Ответит ли она другой вопрос",112272,null],[125193,"2026-07-20T10:51:01",17,"/ Смит напиши чё нить. Вопрос Мойше. К гадалке идёшь или как. Чтобы понимать",112272,null],[125194,"2026-07-20T10:54:10",60,"Альф сидит в общей толпе у костра, в основном слушая и размышляя. Наконец, он слегка поворачивается к Мойше, приоткрывая рот, чтоб что-то сказать\n\n—А.. Вы ведь странники. Вы видели мельницу там неподалёку? Знаете о ней что-то?",125193,null],[125195,"2026-07-20T10:54:31",60,"//да с одной книжки весёлый городок...",125190,null],[125196,"2026-07-20T10:58:28",17,"— Мельница? Да, кое что. Там хозяйничают Герда и ее дочери. Делают пирожки и торгуют ими. У нас табу на их стряпню, от барона к барону запрет передается давно. Но почему я не знаю. У нас еды хватает, так что мы не соблазняется на манящий запах свежей выпечки.",125194,null],[125197,"2026-07-20T10:59:25",60,"//Ля, да точно вайбы Арбы! \n\n—А чего так? Вроде вкусные пироги, весьма питательные. Еды тут.. Не слишком много можно найти",125196,null],[125198,"2026-07-20T11:00:41",17,"— У нас как я сказал, проблем с едой нет. \n\n— Мы чтим заветы предков (с)",112272,null],[125199,"2026-07-20T11:01:31",7,"/ я к гадалке если шо \nНапомню на всякий",112272,null],[125200,"2026-07-20T11:02:06",60,"—Ну, будь так.. Полагаю, тогда мы можем купить немного еды? Золото не имеет цены, если негде его тратить.\n\nАльф достает несколько золотых из своего кошелька",125198,null],[125201,"2026-07-20T11:02:23",17,"Немея заходит в шатер гадалки\n\nТут придушенный свет. Престарелая циганка обвешана платками и цепочками",112272,null],[125202,"2026-07-20T11:02:36",31,"- ьмкдрость предков это важно. тем более, если еще предки знали эту самкю Герду и она еще жива, то так тем более",125198,null],[125203,"2026-07-20T11:02:43",17,"— Да, конечно.\n\n( 1 паёк 5 золотых)",125200,null],[125204,"2026-07-20T11:03:00",31,"/тоже иду к гадлке. или по очереди надо?",112272,null],[125205,"2026-07-20T11:03:04",7,"/ нихрена себе\nДолги",112272,null],[125207,"2026-07-20T11:09:32",31,"да, эти цыгане коней не спиздят, но по другому обворуют все равно//",112272,null],[125208,"2026-07-20T11:10:19",7,"*Зайдя в шатер, девушка осмотрелась. Для нее все выглядело темно, однако осмотревшись, она машет приветливо рукой старушке.*\n\n— Здравствуйте, вы гадалка, так ведь?\n\n/ я не буду про приколы что гадалка не угадала что я ей дам двоечку",125201,null],[125209,"2026-07-20T11:10:57",31,"так нам всем к ней или по очереди?/",112272,null],[125210,"2026-07-20T11:13:19",17,"Огонь в шатре вспыхивает ярче. Старая женщина поднимает на тифлинга спокойный, почти незрячий взгляд и едва заметно улыбается.\n\n— Ты пришла не одна. даже если остальные ещё не переступили порог моего шатра. Позови их, Немея. Пусть войдут Альфарий Темпест, Ридли и Тарх.\n\nМадам Ева кладёт морщинистую ладонь на колоду тёмных карт.\n\n— То, что я должна поведать, касается каждого из вас. Пока не соберутся все, карты будут молчать.",112272,null],[125211,"2026-07-20T11:13:52",9,"//Охуеть у менясокровищк в кармане.",125203,null],[125212,"2026-07-20T11:14:52",31,"*тоже захожу в шатёр*\n\n- добрый вечер, госпожа",112272,null],[125213,"2026-07-20T11:15:00",17,"Гадалка. Мадам Ева.",112272,null],[125214,"2026-07-20T11:15:22",9,"*Ридли не реагирует на цены или другие вещи, что-то такое пожозревал. Раз его пригласили тоже заходит в шатёр.*",112272,null],[125215,"2026-07-20T11:24:07",7,"*Немейя чувствовала себя неловко, ибо не помнит, что здесь ее имя хоть как то упоминалась. Так или иначе она пропустив Ридли, выходит из шатра и зовёт всех в вовнутрь, после чего заходит обратно.*\n\n— Ребят, вас позвали. Заходите, если хотите.",112272,null],[125216,"2026-07-20T11:35:14",17,"/ Ладно делаем вид что Альф зашёл. Закидывает тонну гадания, веселитесь",112272,null],[125218,"2026-07-20T11:39:15",17,"Когда последний из гостей переступает порог шатра, Мадам Ева медленно поднимает голову.\n\nЕё взгляд проходит по по вам всем.\n\n— Хех, я думала с вами будет ещё девушка. Ирина. Но даже карты бывают обманчивы. Теперь нить замкнулась. Садитесь ближе. Не бойтесь огня и не отводите глаз от карт. Сегодня они будут говорить о том, что сокрыто и о тех, кто ещё способен сопротивляться тьме вместе с вами.\n\nМадам Ева снимает с колоды тёмный шёлковый платок.\n\nКарты под ним старые, потёртые, с почерневшими краями. На их рубашках изображён серебряный ворон, летящий над башнями замка. В его клюве зажат обрывок красной нити.\n\nПрорицательница кладёт ладонь на колоду и закрывает глаза.\n\nПламя свечей вытягивается вверх. За стенами шатра на мгновение стихает ветер. Даже далёкие голоса в лагере растворяются в тишине.\n\n— Эти карты не предсказывают будущее. Будущее слишком переменчиво. Они показывают дороги, по которым вы можете пройти.\n\nОна начинает медленно перемешивать карты. Сухой шелест разносится по шатру, словно кто-то перебирает опавшие листья на старой могиле.\n\nОдна карта сама выскальзывает из колоды.\n\nМадам Ева не смотрит на неё и кладёт рубашкой вверх в центр стола.\n\nЗатем появляется вторая.\n\nЗа ней третья.\n\nПосле короткой паузы прорицательница выкладывает ещё три карты полукругом над первыми.\n\nЕё пальцы касаются первых трёх карт.\n\nОна медленно переворачивает первую карту.",112272,null],[125219,"2026-07-20T11:40:33",31,"Атмосферно/",112272,null],[125220,"2026-07-20T11:41:09",17,"ПЕРВАЯ КАРТА\n\nНа карте изображена раскрытая книга. Её страницы исписаны красными чернилами, а над ней висит улыбающаяся маска. На заднем плане видны городские стены, праздничные флаги и виселица, спрятанная за гирляндами.\n\nМадам Ева проводит ногтем по изображению маски.\n\n— Ищите слова того, кто стал тьмой, в месте, где веселье объявлено законом.\n\n— Там люди улыбаются не от радости, а из страха. Они украшают улицы, пока за закрытыми дверями растёт отчаяние.\n\n— Его исповедь хранит женщина. Она живёт среди благородных стен и считает чудовище не палачом, а спасителем. В её мыслях уже звучит голос хозяина замка.\n\n— Будьте осторожны. Она отдаст вам тайну лишь тогда, когда поймёт, что не может обратить вас в свою веру.\n\n— В найденных страницах вы увидите не только историю врага. Вы узнаете, какую цену он заплатил за вечность и какая рана до сих пор не позволяет ему обрести покой.\n\nВТОРАЯ КАРТА\n\nНа карте изображён золотой знак, окружённый лучами белого света. Он лежит на алтаре, но сам алтарь покрыт хирургическими инструментами. Над ним склонилась крылатая фигура с лицом, скрытым под окровавленной повязкой.\n\nМадам Ева долго смотрит на изображение.\n\n— Святыня ждёт там, где молитвы смешались со стонами.\n\n— Ищите высокое место над западным поселением. Там обитает тот, кто помнит небеса, но уже не понимает милосердия.\n\n— Он пытается исправить несовершенство плоти. Он соединяет то, что должно было остаться разделённым, и называет свои творения даром.\n\n— Среди его трудов, безумных надежд и несчастных созданий скрыт знак древней веры.\n\n— Свет этого знака не уничтожит тьму сам по себе. Но в руках того, чья вера не сломлена, он заставит мёртвых вспомнить страх.\n\n— Не судите обитателей того места слишком поспешно. Некоторые из них чудовища лишь снаружи.\n\nТРЕТЬЯ КАРТА\n\nНа карте изображён клинок без лезвия. Из пустой рукояти вырывается золотой солнечный луч. Позади возвышается мёртвое дерево, а вокруг него танцуют фигуры в рогатых масках.\n\nПламя свечей становится зеленоватым.\n\n— Я вижу холм, помнящий кровь древних племён.\n\n— На его вершине стоит дерево, которое не даёт плодов. Его корни питаются смертью, а ветви царапают само небо.\n\n— Вокруг него собираются дети земли. Они забыли человеческие имена и слушают шёпот, поднимающийся из-под камней.\n\n— Там покоится оружие, утратившее сталь, но сохранившее свет.\n\n— Оно покажется сломанным тому, кто смотрит только глазами. Но в руках достойного из пустой рукояти вновь взойдёт солнце.\n\n— Дерево почувствует ваше приближение. Земля пробудится вместе с ним. И прежде чем свет станет вашим, холм потребует жертву.",112272,null],[125221,"2026-07-20T11:41:36",17,"ЧЕТВЁРТАЯ КАРТА\n\nНа карте изображён седой путник в широкополой шляпе. В одной руке он держит трость, в другой — деревянный кол. Его лицо отражается в разбитом зеркале, но каждое отражение выглядит иначе.\n\nМадам Ева едва заметно улыбается.\n\n— Среди вас есть охотники. Но тот, кого показывают карты, сделал охоту своей жизнью.\n\n— Он носит чужое имя и чужое лицо. Он прячет знания за шутками, подозрением и одиночеством.\n\n— Много лет он идёт по следу созданий ночи. Вампиры пугают детей его именем так же, как люди пугают детей вампирами.\n\n— Он не предложит вам помощь. Он скорее попытается отослать вас подальше.\n\n— Не принимайте его холодность за трусость. Он держится вдали от людей, потому что уверен: всякий, кто станет ему дорог, будет обречён.\n\n— Докажите, что вы не станете его новой потерей. Тогда рядом с вами встанет человек, который знает о нежити больше, чем многие жрецы и маги.\n\nПЯТАЯ КАРТА\n\nНа карте изображена стая чёрных воронов, летящих над виноградником. Под их крыльями видны человеческие силуэты. Высоко в небе проступает бледный женский лик в короне из перьев.\n\nМадам Ева касается изображения одного из воронов.\n\n— Чёрные крылья следят за вами с тех пор, как туман пропустил вас в эту землю.\n\n— Не бросайте в них камни. Не стреляйте в них. Некоторые птицы помнят человеческую речь, а некоторые люди умеют носить перья.\n\n— Ищите семью, связанную общей кровью, тайной и старой клятвой. Их дом стоит там, где из плодов рождается редкая радость этой мрачной земли.\n\n— Они давно противостоят хозяину замка, но предпочитают действовать из тени. Они могут стать вашими глазами, проводниками и вестниками.\n\n— Однако над ними есть другая госпожа. Та, что собирает воспоминания умерших и наблюдает за миром через бесчисленные чёрные глаза.\n\n— Она желает ослабить владыку этой земли не ради свободы смертных. Чем слабее станет он, тем глубже её собственные когти войдут в эту долину.\n\n— Пока ваш враг силён, ваши дороги совпадают. Но не забывайте: союз с воронами может привлечь внимание их королевы.\n\nШЕСТАЯ КАРТА\n\nНа карте изображён серебряный дракон, лежащий среди разрушенных башен. Вокруг него стоят мёртвые рыцари. Их мечи опущены, а над крепостью возвышается погасший маяк.\n\nЛицо Мадам Евы становится суровым.\n\n— На высоте, среди холодных камней, мёртвые всё ещё несут свою службу.\n\n— Когда-то они клялись защищать эту землю во имя серебряного змея небес. Их господин пал, их крепость была разрушена, а честь превратилась в ненависть.\n\n— Они ненавидят тирана сильнее, чем любят живых.\n\n— Поэтому они не спешат положить конец его правлению. Они считают, что вечные муки — более справедливая кара, чем быстрая смерть.\n\n— Не пытайтесь убедить их одними словами. Они слишком долго слушали лишь голоса мёртвых.\n\n— Найдите свет, который когда-то горел над их домом. Верните в башню то, что было утрачено, и позвольте маяку снова озарить долину.\n\n— Когда свет коснётся их знамён, рыцари вспомнят не день своего поражения, а клятву, данную ещё при жизни.\n\n— Тогда серебряные мечи вновь поднимутся. Но помните: воодушевить павших легче, чем удержать их ярость.",112272,null],[125222,"2026-07-20T11:46:28",17,"— Это. Ваша. Судьба.",112272,null],[125223,"2026-07-20T11:47:23",31,"//пафос. но круто//",112272,null],[125224,"2026-07-20T11:47:41",31,"// На карте изображён седой путник в широкополой шляпе. В одной руке он держит трость, в другой — деревянный кол. Его лицо отражается в разбитом зеркале, но каждое отражение выглядит иначе. - Ван Хельсинг?//",112272,null],[125225,"2026-07-20T11:48:15",9,"//Круто, но убейте меня, столько приключений морально не переживу 🫠",112272,null],[125226,"2026-07-20T11:48:23",9,"//Лан, попытаемся что-то",112272,null],[125227,"2026-07-20T11:49:28",17,"/ Я убью тебя скоро не парься. Выше 3 лвла обыватель не выстоит. Просто ноль шансов. Любое попадание - смерть",112272,null],[125228,"2026-07-20T11:49:52",31,"ну так кампания. ты не переживай, мы все равно сдохнем раньше//",125225,null],[125229,"2026-07-20T11:49:54",17,"/ Все же сюда нужны полноценные герои. Не обыватели.",112272,null],[125230,"2026-07-20T11:50:20",9,"*Ридли просто силел и внимательно слушал. Не перебивал. Его взгляд зацепился за спутников, ему была интересна их реакция, он понял что товарищи это сейчас единственный способ отсюда убраться и возможно решить проблему.*",125222,null],[125231,"2026-07-20T11:50:40",31,"если сдохну, могу стать призраком-помощником?//",125229,null],[125232,"2026-07-20T11:50:48",17,"/ Да",112272,null],[125233,"2026-07-20T11:50:50",17,"/ У графа",112272,null],[125234,"2026-07-20T11:50:52",60,"//много букав",112272,null],[125235,"2026-07-20T11:51:05",31,"тоже норм, карьера//",125233,null],[125237,"2026-07-20T11:58:17",31,"кстати, насчет призрака или перерождения в какую нибудь херь после смерти обывателя я вполне серьезно. Тем более, мы же идем в аббатсво к типа святому, может он мог бы помочь, если по слухам может даже вампира излечить. Было бы забавно играт сначала за обывателя - противника поднятия нежити, а в итоге самом стать нежитью)) перерождение в ХБ-расу, ну если такое правила сервера позволяют и воля мастера на то будет))//",112272,null],[125238,"2026-07-20T11:59:11",17,"/ воля мастера чтобы вы преодолели опасности или сдохли. Таскать призраков мне не интересно",112272,null],[125239,"2026-07-20T12:00:09",31,"- простите, госопожа Ева, я не очень понял, в чем наша судьба? для чего нам вся эта информация? мы должны посетить какие то места, и что то там найти? а дальше что? вы уж простите, я человек не очень образованный, не все понимаю в красивых словах",125222,null],[125240,"2026-07-20T12:01:19",31,"зачем тогда было пускать обывателя?) я же предлагал создать перса с нуля))// ну да ладно//",125238,null],[125244,"2026-07-20T12:06:53",9,"//Ты сам пошёл, такая уж судьба умереть приняв неосторожное решение. Персов нужно беречь на деле.",125240,null],[125245,"2026-07-20T12:08:02",31,"так я не спорю. просто ставить мне вину то что я играю обывателем когла я сам предлагал другой вариант это странно))//",125244,null],[125246,"2026-07-20T12:08:28",9,"— Нам лишь указали путь. — *Ридли посмотрел на гадалку и наклонил голову.* — Спасибо за наставление.",125239,null],[125247,"2026-07-20T12:09:56",9,"//Думаю, Николай просто не зочет таскать призраков. Обвинять ни в чём у него небыло намеренья",125245,null],[125248,"2026-07-20T12:10:00",31,"- позволите еще вопрос? по пути мы видели странную мельницу, от которой пахло пирожками на всю округу. Но как ам сказал Мойша, у вашего народа есть запрет на поедание этих пирожеов. Не расскажите, почему так?",112272,null],[125249,"2026-07-20T12:10:56",7,"/ я все еще читаю гадание",112272,null],[125250,"2026-07-20T12:11:01",7,"/ это к слову",112272,null],[125252,"2026-07-20T12:13:44",7,"*Немейя была удивлена многим... Состыковкам. Однако она ни словечка не поняла. Про Ирину она сказала так, будто бы шанс был ее увести... Девушка сидела пока не задавала вопросы, ибо за неё их задали. Ей интересно что за пирог, что ей дали... Что с ним не так.* \n/ Пафоса было много, я многое не понял как игрок",112272,null],[125253,"2026-07-20T12:16:16",7,"/ ну есть класс неупокоенная душа если кому интересно и кто шарит в ней. Дальше воля Николая",125238,null],[125254,"2026-07-20T12:17:45",17,"— Я не могу ответить на ваши вопросы. Карты сказали мне вашу судьбу и я передала её как есть.",112272,null],[125255,"2026-07-20T12:18:44",31,"//бабуля насыпала загадок. ну вообше интересно//",112272,null],[125257,"2026-07-20T12:21:21",9,"//Там почти чёрным по белому инструкция как у лекарств 😏👌",125255,null],[125258,"2026-07-20T12:23:03",31,"Трах задумывается:\n\n- веселье обьявлено законом... это цирк чтоли? нам нужно искать женщину-клоуна? это попервой карте. По второй похоже на больницу. Третьея вообще не понятно, какой то лес, рогатые фигуры, это в лесу искать стадо оленей? Четвертая более понятная, кол в руках - это явно намек на охотника на вампиров, я знаю о таких. Но где его искать не ясно. Пятая карта вороны могут стать друзяьями и глазами, значит надо поглядывать на небо и постараться с ними поговорить видимо. звучит как бред . последняя карта это какие то призраки похоже, котолрые ненавидят тирана, это графа наверное, возможно они могут помочь?",112272,null],[125259,"2026-07-20T12:24:15",31,"- жаль, я хотел спросить еще, сможем ли мы помочь сыну свяшенника. ну и про Ирину тоже, вы ждали что она будет с нами. Значит ее судьба не была решенной?",125254,null],[125260,"2026-07-20T12:26:49",7,"/ окак",125258,null],[125261,"2026-07-20T12:29:01",31,"гадалка сооблазнительна, ага//",125260,null],[125262,"2026-07-20T12:38:14",17,"— Это все, что у меня есть для вас. Гадание окончено. Покиньте шатер.",112272,null],[125263,"2026-07-20T12:43:33",31,"*встаем и уходим*",112272,null],[125264,"2026-07-20T12:44:11",31,"//прочитал кстати про класс неупокоенной души. Реально интересно//",112272,null],[125265,"2026-07-20T12:45:11",31,"- предлагаю всем занять место у костра и обсудить то, что мы только что услышали",112272,null],[125266,"2026-07-20T12:45:19",17,"У большого костра танцы, циганки и цигане кружатся и весело бьют чечётку. Приятная музыка акустических гитар. Много еды которую можно покушать бесплатно. Правда с собой не дают.\n\nВам устроили пристанище на сеновале\n\nСпать будете под открытым небом.",112272,null],[125268,"2026-07-20T12:45:25",17,"Что вы будете делать?",112272,null],[125271,"2026-07-20T12:46:14",9,"*Когда все вышли.*\n\n— Думаю гадалка не преследует наши интересы, скорее свои. Знает намного больше но не говорит об этом.",112272,null],[125273,"2026-07-20T12:48:03",31,"- ну, кто же ее осудит. Все в этом мире думают себе в первую очередь, это нормально. Вопрос вот в чем - а мы ей верим? Ничего не мешает ей ломать комедию и врать нам в лицо",125271,null],[125275,"2026-07-20T12:49:54",7,"*Немейя вышла, думая, что ничего не сумела понять. Она смотрит на большой костер и говорит.*\n— Я считаю, что многое могло быть приукрашено. Она назвала имя девушки, которую мы должны были защищать и... Сказала, что судьба пойдет иначе. После вас позвала. Я не знаю, верить или нет, но логически она рассказала то, что знать была не должна... Может она дергает за нитки...",112272,null],[125276,"2026-07-20T12:56:31",60,"—А может и так. Не будь мы в мире, где есть последствия, можно было бы поговорить иначе. Но что имеем. Сегодня перевал, завтра снова в путь.",125275,null],[125277,"2026-07-20T13:08:57",31,"- да, пожалуй нужно поспать. завтра продолжим путь, нам еще в Валаки нужно зайти и найти там приют, куда передать письмо из сумки призрака",112272,null],[125602,"2026-07-20T17:06:56",31,"Сегодня еще играть будем?/",112272,null],[126174,"2026-07-20T21:45:40",17,"/ Не, у меня денек напряженный",112272,null],[126985,"2026-07-21T10:48:09",31,"топаем в Валаки?/",112272,null],[126988,"2026-07-21T13:03:41",17,"/У меня ребята много работы срочной. Не могу продолжать пока, сори",112272,null],[126989,"2026-07-21T13:30:02",31,"Ок, как будешь свободен, напиши хоть",112272,null],[126991,"2026-07-21T13:37:48",17,"Перед снов несколько циганок хотят вас пригласить на танцы\n\nОгненно рыжие волосы кружатся как языки пламени вокруг костра.\n\nОни миловидные, пышногрудые и молодые.\n\nКак вы ответите?",112272,null],[126992,"2026-07-21T13:39:34",60,"—Нет. Я спать.. Ночь будет тяжелой.\n\nАльф отвечает довольно резко. Ему действительно хочется заснуть быстрее и пропустить эту ночь, чтобы меньше думать обо всём, что произошло за последнее время",126991,null],[126994,"2026-07-21T13:44:52",17,"И так утро. Серое, как и всегда. Свинцовые тучи снова насупились, тяжестью влаги в них, кажется уже начинает моросить мерзкий дождь\n\nОткуда спрашивается вода, ведь солнца нет и испарений от этого мало... - Загадка.\n\nЦигане еще спят когда вы просыпаетесь\n\nВы спокойно собираете вещи.\n\nМойша предлагает закупить провизии у них\n\n(1 Паёк - 5 золотых)",112272,null],[126995,"2026-07-21T13:45:30",31,"У меня в кармане нет ничего)/",112272,null],[126996,"2026-07-21T13:45:56",17,"Вы выходите из табора без проблем, все ваши вещи при вас. Никто не пытался вас ограбить\n\nТолько на хвосте Немеи висит та самая игрушка гильйотина. Хвост она не смогла отрубить, но сорванци ночью пытались это провернуть\n\nНа бирке внизу написано\n\n\"Магазин игрушек Блинского\"",112272,null],[126997,"2026-07-21T13:48:03",60,"—Возьму четыре. Не скоро пополним запасы.\n\nАльф достаёт 20 золотых и передает Мойше",126994,null],[126998,"2026-07-21T13:55:23",17,"Вы выдвигаетесь дальше.\n\nИдёте по грязной дороге, вдоль полей где ничего не растет кроме бурьяна.\n\nИ некоторое время идёте по ней, пока...\n\nИз тумана доносится размеренный стук копыт. На дорогу выезжает скелет верхом на костяной лошади. Истлевший плащ всадника колышется без ветра, а пустые глазницы внимательно смотрят на путников.\n\nВсадник останавливается и хрипло спрашивает\n\n— Где дорога из Багровии?",112272,null],[127000,"2026-07-21T13:57:10",60,"—Аэ.. Ну.. Там.\n\nАльф указывает туда, откуда они пришли\n\n—Мимо мельницы и деревни, оттуда через туман сюда я и пришёл. А вы, собсна, кто? Странный вид.. Ну не для этих мест.",126998,null],[127001,"2026-07-21T14:00:33",17,"— Я оттуда прискакал, там нет выхода. Обманываешь меня? Не советую... ГДЕ ВЫХОД ИЗ ЭТОГО ЧЕРТОВОГО ГРАФСТВА?",112272,null],[127002,"2026-07-21T14:02:15",31,"- только граф знает, спроси в замке",127001,null],[127003,"2026-07-21T14:02:36",17,"— Граф...",112272,null],[127004,"2026-07-21T14:03:33",60,"—Мы сами только пришли. И без понятия, чё тут как устроено. Но выхода особо нет, как видно",112272,null],[127005,"2026-07-21T14:04:09",17,"Дорога на замок немного дальше, тропа уходит на утёс где стоит замок графа.\n\n— Да. Поеду туда...\n\nОн стучит по крупу мёртвого коня ржавыми шпорами, от удара звёздочка с его сапога отваливается и шкпора у него только одна\n\nЛошадь резко начинает движение от вас\n\nШпора лежит в грязи",112272,null],[127006,"2026-07-21T14:05:04",31,"/roll d20+1 на внимательность, осматриваю шпору не трогая руками",112272,null],[127008,"2026-07-21T14:08:25",60,"/roll +3 ну го тоже кину",112272,null],[127010,"2026-07-21T14:09:00",60,"—Э.. Мужик, ты забыл...\n\nАльф поднимает шпору и показывает ему",127005,null],[127011,"2026-07-21T14:09:04",17,"Ты ыб никогда не подобрал этот хлам, ржавое говно",127006,null],[127012,"2026-07-21T14:09:25",17,"Для тебя есть кое что еще, всполох магической энергии проходит по ржавому металлу",127010,null],[127013,"2026-07-21T14:09:51",17,"Шпора мертвеца\n\nНеобычный предмет. Не требует настройки\n\nВаш максимум скорости повышается на 5",112272,null],[127014,"2026-07-21T14:10:40",60,"//ну варвар на спидах это конечно хорошо",112272,null],[127015,"2026-07-21T14:10:45",60,"//но может оно кому-то нужнее?",112272,null],[127016,"2026-07-21T14:11:19",17,"/Сами решайте",112272,null],[127017,"2026-07-21T14:13:05",31,"У меня и так скорость выше средней, но чисто чтобы сьебать куда из боя может пригодится//",112272,null],[127018,"2026-07-21T14:17:05",31,"Мне бы что то дальнобойное найти, что бы хоть поддержкой быть//",112272,null],[127019,"2026-07-21T14:17:17",31,"Владения правда нет все равно/",112272,null],[127020,"2026-07-21T14:19:38",17,"/Праща простое оружее вроде",112272,null],[127021,"2026-07-21T14:23:28",31,"Надо будет поискать, в городе по-любому рынок есть/",112272,null],[127022,"2026-07-21T14:23:48",17,"Вы идёте дальше\n\nНад ущельем протянулся старый каменный мост. По его углам сидят четыре покрытые чёрным мхом горгульи. Их когти впились в камень, а оскаленные морды повёрнуты в разные стороны.\n\nМост скользкий от водяной пыли. Где-то далеко внизу грохочет водопад.",112272,null],[127023,"2026-07-21T14:24:30",31,"/roll d20+1, с подозрением осматриваю горушлий, не хотят ли они нас убить?",112272,null],[127025,"2026-07-21T14:25:08",17,"Ты внимательно смотришь на гаргулью не отводя взгляд в течении некоторого времени\n\nКаменные скульптуры не двигают ни на миллиметр",112272,null],[127026,"2026-07-21T14:25:21",31,"- я все равно вам не верю",112272,null],[127027,"2026-07-21T14:27:49",9,"*Ридли просто переходит на другую сторону первым, он осторожничает сжимая запонку.*\n\n//Действие заготовленно \"спрятаттся в сосуд\" если они двинутся.",112272,null],[127028,"2026-07-21T14:28:03",17,"/Спас ловкости",112272,null],[127029,"2026-07-21T14:28:14",17,"/Нет давай силы",112272,null],[127030,"2026-07-21T14:28:36",17,"Сильный порыв ветра сносит тебя к краю, сопротивляйся стихии\n\nМокрый камень под ногами скользит",112272,null],[127031,"2026-07-21T14:28:43",17,"Товарищи могут помочь, как то",112272,null],[127032,"2026-07-21T14:30:02",31,"Протягиваю вилы, кричу хватайся!",112272,null],[127033,"2026-07-21T14:30:12",17,"/Преимущество от помощи",112272,null],[127034,"2026-07-21T14:30:34",9,"/roll +d20+2 сила спас",112272,null],[127036,"2026-07-21T14:30:55",17,"Ты смог удержаться за вилы товарища и ветер стих\n\nНо вы еще не перешли",112272,null],[127037,"2026-07-21T14:31:14",60,"Альф врубает ярость. Его мышцы напрягаются, он хватает двуручник и вонзает острие в землю, двигаясь вперёд.\n\n—За мной. Либо я перейду и кину верёвку.",112272,null],[127038,"2026-07-21T14:31:46",17,"/ Чтобы перейти Два броска Спаса силы выше 10. Если идёте группой можно с преимуществом.",112272,null],[127039,"2026-07-21T14:32:00",17,"/ Ридли и Тарх уже прошли половину пусть им еще один всего спас",112272,null],[127040,"2026-07-21T14:32:33",9,"*Смотрит насколько мост длинный.*",112272,null],[127041,"2026-07-21T14:33:25",60,"/roll +d20+5 хоп\n+d20+5 преимущество от ярости ес что",127038,null],[127043,"2026-07-21T14:34:23",9,"//Немеи тут нет? Я же видел хоть раз что она летает?",112272,null],[127044,"2026-07-21T14:34:39",60,"//ну у нее крылья есть по крайней мере",127043,null],[127045,"2026-07-21T14:35:03",17,"/ Немея работяга",112272,null],[127046,"2026-07-21T14:35:20",17,"/ Ну хули делать будем двигаться, на бой тормозиться и на ключевые события",112272,null],[127047,"2026-07-21T14:36:10",9,"//Ну, я могу почти ничего не весить 1 час, а Тарха думаю она мтгла потащить или вон пусть Альф с крестьянином играется)",112272,null],[127048,"2026-07-21T14:37:12",17,"/Хорошо, мост вы прошли",112272,null],[127049,"2026-07-21T14:37:21",17,"/Внимание киньте когда проходили вдруг заметили",112272,null],[127050,"2026-07-21T14:37:27",9,"//Эээээ, уууууу",112272,null],[127051,"2026-07-21T14:38:39",9,"/roll 1d20 восприятие но я бы немею подождал наверное а то так проскипаем половину игры",112272,null],[127053,"2026-07-21T14:40:07",31,"/roll d20+1",127049,null],[127055,"2026-07-21T14:40:24",17,"/ Ну че делать, Лёша хочет дальше ебашить, Еврея надо ждать, я хуй знает",112272,null],[127056,"2026-07-21T14:40:32",17,"/ Щас у меня есть полчасика еще и пойду работать",112272,null],[127057,"2026-07-21T14:40:51",31,"Я могу и подождать)/",112272,null],[127058,"2026-07-21T14:56:25",60,"/roll +3 ыбаб?",127049,null],[127060,"2026-07-21T14:56:31",60,"//он самый, ыбаб",112272,null],[127062,"2026-07-21T14:57:39",17,"В зубах у одной из Гаргулий свиток",112272,null],[127063,"2026-07-21T14:58:29",60,"Слегка с недоверием, вонзая меч меж камней, дабы его не откинуло, Альф подбирается ближе и хватает свиток\n\n—Тут чё-то есть!",127062,null],[127065,"2026-07-21T15:00:10",60,"//Пхахахаха",112272,null],[127066,"2026-07-21T15:00:28",60,"//у нас кстати Ридли вообще считается колдуном?",112272,null],[127067,"2026-07-21T15:01:05",60,"//потому что альф свиток юзать не может, он варвар. А немейя чародей, у неё в листе защиты от зла и добра нет и подавно",112272,null],[127069,"2026-07-21T15:08:38",17,"// Нет, вы ваще не можете их юзать",112272,null],[127070,"2026-07-21T15:10:44",31,"Ну чисто лут подразнить партию/",112272,null],[127071,"2026-07-21T15:12:16",31,"о, а мы ведь можем нанимать нпс? Может мага найдем?)/",112272,null],[127072,"2026-07-21T15:12:39",60,"Ты много магов тут видел? У тебя есть много денег?",127071,null],[127073,"2026-07-21T15:12:59",31,"Надо идейного искать, который за все хорошее и аротв всего плохого/",127072,null],[127426,"2026-07-21T20:43:22",17,"/ @Evreiskui_Department братан я видел что тебе хуево, но просто напиши стоит ебануть следующую сцену или подождать?",112272,null],[127427,"2026-07-21T20:46:40",7,"/ ебани сцену, не люблю заставлять ждать",112272,null],[127428,"2026-07-21T20:48:14",7,"/ я постараюсь включиться, извиняюсь за задержку",112272,null],[127429,"2026-07-21T20:56:05",17,"Вдоль дороги растут невысокие засохшие деревья. Их тонкие ветви покрыты длинными чёрными иглами, а переплетённые корни выступают из земли подобно кривым пальцам.",112272,null],[127430,"2026-07-21T21:04:16",7,"*Немейя осмотревшись, создает в руках пламя. Она начинает огнем управлять при помощи своего дара, после чего посмотрев на ребят говорит.*\n\n— Расчистить путь мне будет не сложно, хоть какое то развлечение, среди этого мрака.",112272,null],[127431,"2026-07-21T21:06:18",17,"Они растут вдоль дороги и не перегораживают саму дорогу. Ты хочешь кинуть в дерево пламя?",112272,null],[127432,"2026-07-21T21:08:00",7,"/ если остальные не против пожара в лесу",112272,null],[127433,"2026-07-21T21:08:37",60,"//тут итак мрачно, итак с едой перебои",112272,null],[127434,"2026-07-21T21:08:42",60,"//лес ломать грешно",112272,null],[127436,"2026-07-21T21:10:22",9,"*Ридли плевать на лес, не будет графа и с едой получше станет.*",112272,null],[127437,"2026-07-21T21:12:05",17,"/ Напиши что ты делаешь. Действие.",127432,null],[127441,"2026-07-21T21:21:22",7,"/ пока что создал огненный снаряд и управлением над огнем сделал такой шарик",127437,null],[127442,"2026-07-21T21:22:25",17,"/ таааак",127441,null],[127443,"2026-07-21T21:22:34",17,"Деревья выглядят напряженными",112272,null],[127445,"2026-07-21T21:23:16",17,"/ Что дальше?",112272,null],[127447,"2026-07-21T21:24:29",9,"— Если корни нападут на нас — сожги тут всё. — *Ридли после последних событий подозревает всё.*\n\n//Помощь на запугивание",112272,null],[127448,"2026-07-21T21:24:54",17,"/ Это мета чутка. Деревья выглядят как деревья просто так не отличить",127447,null],[127449,"2026-07-21T21:25:42",9,"//Думаю Ридли щас уверен что земля на них может напасть, я ещё до картинки заподозрил, все здесь проклято до усрачки",112272,null],[127450,"2026-07-21T21:27:11",9,"//Вообще по этой причине пытаюсь социалить с лесомс полем, мертвецами и говорю вслух не только давая понять намеренья противникам а и идеи союзникам.",112272,null],[127451,"2026-07-21T21:29:08",17,"/ Ну фактически деревья как деревья ладно.",112272,null],[127452,"2026-07-21T21:31:15",9,"//Вот с этого момента по описанию понял что страшные. Хотя страшнее было бы встретить яблоню с яблоками посреди этогг пипца, тут бы 100% сжечь 🤔",127429,null],[127453,"2026-07-21T21:41:55",7,"/ @QURTZZ",112272,null],[127454,"2026-07-21T21:42:14",7,"/ признай что ты хочешь опыта)",127452,null],[127456,"2026-07-21T21:43:11",17,"/ Обыватели давно пизды не получали. Уже не терпится",112272,null],[127457,"2026-07-21T21:44:12",7,"/ если будем сражаться, просто ради интереса спрошу\nПри взлете Немейю пво не собьет?",127456,null],[127458,"2026-07-21T21:44:32",7,"/ легендарным действием",112272,null],[127459,"2026-07-21T21:44:43",9,"//Я создал смертника а он жив до сих пор. Он или умрёт, или скорей всего умрёт, но с другой стороны личная сумка хранения для пати эт неплохо, поэтому постараюсь не сдохнуть",127454,null],[127666,"2026-07-21T23:28:42",17,"/ И так он так и не скинул огонь ) Что скип? Дальше пойдем?",112272,null],[127695,"2026-07-21T23:36:29",7,"/ будем скипать, ничего не добьемся и на 2 лвле против графа попрём\nНормально",112272,null],[127704,"2026-07-21T23:38:14",17,"/ Ваше решение. Делайте или не делайте.",112272,null],[127880,"2026-07-22T03:52:34",31,"Хуярим, пора умирать/",112272,null],[127884,"2026-07-22T12:37:52",17,"/ Пупупу",112272,null],[127885,"2026-07-22T12:39:24",60,"//То есть немейя хочет устроить поджог потому что да?",112272,null],[127886,"2026-07-22T12:39:26",7,"/ я за резню ибо что то продвигаемся скверно",112272,null],[127887,"2026-07-22T12:39:36",7,"/ почему бы и нет",127885,null],[127888,"2026-07-22T12:40:00",60,"//сюда бы друида моего",112272,null],[127889,"2026-07-22T12:40:10",60,"//законно-злого",112272,null],[127890,"2026-07-22T12:40:20",60,"//хотя стоп!",112272,null],[127891,"2026-07-22T12:40:27",60,"//Альф умеет говорить с растениями!",112272,null],[127892,"2026-07-22T12:40:41",7,"/ пусть спросит как хорошо они могут гореть",127891,null],[127893,"2026-07-22T12:41:35",60,"—Любопытная, однако, картина... Почему они так похожи на великанов?\n\nГоворит Альф, почти впритык рассматривая деревья.",127444,null],[127894,"2026-07-22T12:41:49",60,"//тут есть проблема",127892,null],[127895,"2026-07-22T12:41:58",60,"//ибо хоть они меня понимают, я их — нет",112272,null],[127896,"2026-07-22T12:42:27",9,"*Ридли не сходит с дороги, наблюдает за происходящим.*",112272,null],[127897,"2026-07-22T12:45:31",31,"Бросай на внимательность, можети что то расслышишь/",127895,null],[127898,"2026-07-22T12:46:03",60,"//ну может они листиками помашут, мало ли",127897,null],[127899,"2026-07-22T12:47:25",9,"//Вообще, если месить горшки пробуждения и вырастить свой лес. Лес не обязан отвечать чтобы понимать и слушаться 😏👌",112272,null],[127901,"2026-07-22T13:04:44",17,"/ Языки понимает Общий, но не говорит.",127893,null],[127902,"2026-07-22T13:07:13",17,"/ Че пиздануть вас заразами или вы дальше идёте, спрашиваю напрямую",112272,null],[127903,"2026-07-22T13:08:29",9,"//Жду союзников, мне интересно что будут делать.",112272,null],[127904,"2026-07-22T13:09:34",31,"/дохнуть от заразы не хочу, да и в принципе деревьям вряд ли что смогу сделать)) короче, отдаю право выбора нашим тяжеловесам, обыватель скромно присет судьбу)/",112272,null],[127905,"2026-07-22T13:10:20",17,"/ Бля обыватели сняли с себя отвественность",112272,null],[127906,"2026-07-22T13:10:30",17,"/ Как кровью кормить вампира так они первые",112272,null],[127907,"2026-07-22T13:10:47",31,"Ну мы же мудреем по ходу/",127906,null],[127908,"2026-07-22T13:11:02",31,"Сейчас мы параноим уже/",112272,null],[127909,"2026-07-22T13:14:29",9,"//Не в этрм дело, с деревьями лучше наши союзники, поговорить или сжечь. У меня нет идей банально",112272,null],[127910,"2026-07-22T13:16:15",17,"Деревья молчат.",127893,null],[127911,"2026-07-22T13:24:49",60,"Альф ну вообще не удивлён. Деревья итак всегда молчат\n\n—Я вот думаю.. Может одно такое с собой взять? Они выглядят прикольно. Очень даже.",127910,null],[127912,"2026-07-22T13:25:29",31,"- ты хочешь тащить с собой дерево?",127911,null],[127913,"2026-07-22T13:25:29",17,"Колючие и вытянутые деревья",112272,null],[127914,"2026-07-22T13:26:48",60,"—А че, они почти похожи на великанов. Обработать и норм, мне не тяжело.",127912,null],[127915,"2026-07-22T13:28:50",31,"+ ну дело твоё конечно. Опять же, запас дров",112272,null],[127916,"2026-07-22T13:30:27",60,"—Ну вот, собсна. Кто-то имеет чет против того, чтоб я забрал одно дерево с собой?\n\nHard @Evreiskui_Department",127915,null],[127917,"2026-07-22T13:39:40",7,"Немейя\n— Если хорошо горят, бери. Я так бы устроила костер из одного дерева здесь.",112272,null],[127919,"2026-07-22T13:44:11",60,"—Тут сжигать опасно.. Разойдётся ещё потом.",127917,null],[127920,"2026-07-22T13:47:03",17,"/ И тааааак фурборл тянет свои рученки к колючему стволу дерева ммммм?",112272,null],[127922,"2026-07-22T13:50:58",7,"Немейя\n— И что? Хуже станет от этого? Ты место видел здесь, может деревьей меньше будет и колючек тоже.",127919,null],[127923,"2026-07-22T14:01:37",60,"//нет, не тянет. Он начинает срубать мечом шипы, чтоб удобнее нести",127920,null],[127924,"2026-07-22T14:02:03",60,"//а потом и само дерево рубить будет, чтоб вообще поднять с земли",112272,null],[127925,"2026-07-22T14:02:04",17,"/ Ну в рп напиши и го инициативу",127923,null],[127926,"2026-07-22T14:03:21",60,"—А если огонь до посевов дойдет? Нечего есть будет людям.. А там и дома сгореть могут. Стихию не остановишь так просто.\n\nГоворит фирболг, входя в ярость, дабы придать себе сил, и с замаха начинает рубить шипы, дабы обтесать таким образом дерево",127922,null],[127927,"2026-07-22T14:03:37",60,"/roll +1 ну инициатива, да?",112272,null],[127929,"2026-07-22T14:04:13",60,"//в общем дерево я заберу с собой",112272,null],[127930,"2026-07-22T14:06:41",17,"Как только меч касается колючек дерева ты слышите визг \n\nДеревья вырывают корни из земли и выпускают облако острых игл. Они лезут с обеих сторон дороги на вас всех.",112272,null],[127931,"2026-07-22T14:06:46",17,"/Инициатива остальных",112272,null],[127932,"2026-07-22T14:07:13",60,"//сколько их?",127930,null],[127933,"2026-07-22T14:08:32",60,"//для битвы сойдёт",112272,null],[127935,"2026-07-22T14:08:34",17,"/r 2d4 Игольчатых 2d4 Ветвистых",112272,null],[127937,"2026-07-22T14:09:04",60,"//нормально",112272,null],[127938,"2026-07-22T14:09:26",17,"/r d4 Вьющихся",112272,null],[127940,"2026-07-22T14:09:44",60,"//вроде это к лучшему",112272,null],[127941,"2026-07-22T14:10:08",17,"/r +1 Ветвистые +1 Игольчатые +1 Вьющаяся",112272,null],[127943,"2026-07-22T14:11:15",7,"/r d20 +2 инициатива против зараз",112272,null],[127945,"2026-07-22T14:12:42",17,"Альф\nВьющаяся 31\nНемея\nИгольчатые (2) \nТарх\nРидли\nВетвистые (3/5)",112272,null],[127946,"2026-07-22T14:12:51",17,"/ Hard @QURTZZ ини",112272,null],[127947,"2026-07-22T14:13:30",7,"/ где то здесь умер вампир и насрал магией и эмоциями в лес",112272,null],[127948,"2026-07-22T14:13:30",60,"//надо чуть больше по позиционке. Где кто в основном, как далеко",127945,null],[127949,"2026-07-22T14:14:04",17,"/ Около тебя Ветвистая, недалеко еще ветвистая. в 20 Игольчатая. Остальные все на другой стороне дороги",127948,null],[127950,"2026-07-22T14:14:34",60,"//ну то бишь одновременно двоих не задену, окей",127949,null],[127951,"2026-07-22T14:15:50",17,"/ Двоих Ветвистых",112272,null],[127952,"2026-07-22T14:19:48",17,"/ Заслушался трек",112272,null],[127953,"2026-07-22T14:20:55",31,"/roll d20+1",127946,null],[127954,"2026-07-22T14:21:15",31,"/roll d20+1",112272,null],[127957,"2026-07-22T14:24:59",60,"//ждём ридли",112272,null],[127958,"2026-07-22T14:25:26",60,"//у него бонус +0",112272,null],[127959,"2026-07-22T14:25:34",60,"//я могу пока сходить, у меня так и так больше",112272,null],[127960,"2026-07-22T14:26:05",9,"//Пу пу пу",112272,null],[127961,"2026-07-22T14:26:18",9,"//Шустрые вы, не успел 3 абщацов в книге написать)",112272,null],[127962,"2026-07-22T14:26:24",9,"/roll 1d20 иня",112272,null],[127964,"2026-07-22T14:27:35",60,"Фирболг только сейчас понимает, что деревья решили дать отпор и рубить придётся сразу всех, чтоб не сдохнуть самим. Бежать он не собирается. Взмахивая сверкающим мечом, он прорубает сразу двоих, чтоб снести им ноги: не хочется повреждать саму фигуру тела, ибо её ещё можно будет унести с собой\n\n—ДА ВАШУ Ж МАТЬ, ДАЖЕ РАСТЕНИЯ ПРИБИТЬ ПЫТАЮТСЯ!",112272,null],[127965,"2026-07-22T14:28:00",60,"/r +d20 безрассудно тяжелая атака",112272,null],[127967,"2026-07-22T14:28:17",60,"//ну наверное будет пробитие",127966,null],[127968,"2026-07-22T14:28:29",31,"А модификаторы?/",112272,null],[127969,"2026-07-22T14:29:10",60,"//я использую черту мастера тяжелого, вычитая 5 из бонуса к попаданию. А он у меня как раз +5",127968,null],[127970,"2026-07-22T14:29:58",60,"/r d6+d4+13 урон если попал там",112272,null],[127972,"2026-07-22T14:45:06",17,"И сразу две ветвистых заразы Альф разрубает пополам",112272,null],[127973,"2026-07-22T14:45:59",17,"Под вами всеми вырастают вьющийся плющ\n\nМестность становится труднопроходимая, но заразам это не мешает\n\nВьющаяся бежит и бьёт Немею колючей веткой хлыстом",112272,null],[127974,"2026-07-22T14:51:52",17,"/ Всем нужно спас силы СЛ12 или будете опутаны",112272,null],[127975,"2026-07-22T14:52:16",17,"/r +4 Сжимание Немеи колючим хлыстом",112272,null],[127977,"2026-07-22T14:52:33",9,"/roll 1d20+2 спас силы",112272,null],[127979,"2026-07-22T14:53:35",9,"*Об руку обвиваеися корень, Ридли резко дёргает в сторону и рвет его пока не одеревенел на запястье.*",127978,null],[127980,"2026-07-22T14:56:22",31,"/roll d20+1 спас силы",127974,null],[127982,"2026-07-22T14:57:11",31,"Тарх ревет как медведь и вырывается из захвата",112272,null],[127983,"2026-07-22T15:00:07",60,"//стой, убил?",127972,null],[127984,"2026-07-22T15:00:43",60,"//я могу добежать до ближайшей игольчатой тогда?",112272,null],[127985,"2026-07-22T15:00:57",60,"//тогда бонуской еще атака по ней будет",112272,null],[127986,"2026-07-22T15:01:05",60,"/r +d20 бум",112272,null],[127988,"2026-07-22T15:01:26",60,"//тут хз попал не попал. Скорее всего нет",112272,null],[127989,"2026-07-22T15:01:58",17,"/ Это мимо",112272,null],[127990,"2026-07-22T15:02:17",60,"//главное попробовал",112272,null],[127991,"2026-07-22T15:02:25",17,"Ловкая игольчатая зараза отскакивает в сторону от твоего взмаха",112272,null],[127992,"2026-07-22T15:02:36",60,"/r +d20+5 врешь не возьмёшь",127974,null],[127994,"2026-07-22T15:02:42",17,"/ @Evreiskui_Department надо твой спас и КД",112272,null],[127996,"2026-07-22T15:30:37",7,"/ кд 12",127994,null],[127997,"2026-07-22T15:31:08",7,"/r d20 -1",112272,null],[127999,"2026-07-22T15:35:43",17,"Немею цепкие плющи опутывают",112272,null],[128000,"2026-07-22T15:36:12",17,"/r 2d6+2 Дробящего урона",112272,null],[128002,"2026-07-22T15:36:31",17,"/ Ты еще схвачена и путана вьющейся заразой дополнительно",112272,null],[128003,"2026-07-22T15:36:53",17,"/Твой ход Сл высвобождения 12 спас силы",112272,null],[128004,"2026-07-22T15:48:26",7,"/ тэк... Действие потратить лучше на уничтожение заразу",112272,null],[128005,"2026-07-22T15:48:37",7,"/ было больно",112272,null],[128006,"2026-07-22T15:49:26",7,"/ трачу реакцию на адское возмездие спас ловкости с заразы \nи уже действием бросаю огненный снаряд",112272,null],[128007,"2026-07-22T15:49:35",7,"/r 2d10 половина в случае успеха",112272,null],[128009,"2026-07-22T15:49:37",17,"/r -1",112272,null],[128011,"2026-07-22T15:49:50",7,"/ жив?",112272,null],[128012,"2026-07-22T15:50:03",17,"/ Да",112272,null],[128013,"2026-07-22T15:50:15",7,"/r d20 +6 огненный снаряд в тварину!",112272,null],[128015,"2026-07-22T15:50:20",7,"/ попал?",112272,null],[128016,"2026-07-22T15:50:28",7,"/r d10 если да",112272,null],[128018,"2026-07-22T15:50:31",17,"/С помехой ток",112272,null],[128020,"2026-07-22T15:50:36",17,"/Опутан и он близко",112272,null],[128021,"2026-07-22T15:50:44",17,"/12 попал",112272,null],[128022,"2026-07-22T15:51:23",17,"Вьющаяся зараза крепко держит тебя",112272,null],[128023,"2026-07-22T15:51:28",17,"/Реакция тратила ячейку?",112272,null],[128024,"2026-07-22T15:51:34",7,"/ ага",128023,null],[128025,"2026-07-22T15:51:40",17,"/ Кидай д100",112272,null],[128026,"2026-07-22T15:51:47",7,"/r d100",112272,null],[128028,"2026-07-22T15:52:07",17,"/ Пизда",112272,null],[128029,"2026-07-22T15:52:07",17,"Над полем боя на мгновение возникает кровавая луна. Следующая атака каждого существа в пределах 30\nфутов наносит дополнительно 1d6 некротического урона.",112272,null],[128030,"2026-07-22T15:53:06",17,"Через тучи пробивается луна, вы все видите как она сверху вниз начинает окрашиваться в алый, кровавый цвет\n\nСтановиться не по себе, все твари вокруг звереют их глаза светятся алым, но и ваши руки тоже загораются алым",112272,null],[128031,"2026-07-22T15:54:44",17,"Игольчатые заразы. Одна атакует Альфа шипами. А вторая выстреливает колючками по Немее, опутаной и беззащитной",112272,null],[128032,"2026-07-22T15:55:35",17,"/r +3 Удар когтями по Альфу  +d20+3 Выстрел колючками по Немее",112272,null],[128034,"2026-07-22T15:56:21",17,"/r 2d4+1 Колющий d6 Некротика Альфу \n2d6+1 Колющий d8 Некротика Немее",112272,null],[128036,"2026-07-22T15:56:37",17,"/Тарх",112272,null],[128039,"2026-07-22T15:56:56",17,"/ У этой заразы 13 КД а у той ловкость -1 и 12",128037,null],[128040,"2026-07-22T15:57:07",17,"/ ЧТО ВОПРОСИКИ СМИТ?",112272,null],[128041,"2026-07-22T15:57:10",17,"/ ПРОВЕРЯЕШЬ МЕНЯ",112272,null],[128042,"2026-07-22T15:57:19",60,"//у них даже статы разные? Они ведь обе игольчатые..",128039,null],[128043,"2026-07-22T15:57:27",31,"/Немею кто держит?",112272,null],[128044,"2026-07-22T15:57:33",17,"/ Он бил не по игольчатой, а по вьющейся",112272,null],[128045,"2026-07-22T15:57:36",17,"/ Если че",112272,null],[128046,"2026-07-22T15:57:49",60,"//а, понял",112272,null],[128047,"2026-07-22T15:57:52",17,"/ Вьющаяся",128043,null],[128048,"2026-07-22T15:57:54",60,"//маршрут перестроен",112272,null],[128049,"2026-07-22T15:58:16",60,"//с преимуществом, безрассудная",128033,null],[128050,"2026-07-22T15:58:22",31,"/roll d20+1 по вьющейся, что держит Немею",112272,null],[128052,"2026-07-22T15:58:24",60,"//но даже так попало",112272,null],[128053,"2026-07-22T15:58:53",31,"12 мимо?/",112272,null],[128054,"2026-07-22T15:59:12",60,"Альф 26/29",128034,null],[128055,"2026-07-22T15:59:22",60,"//попал",128053,null],[128056,"2026-07-22T15:59:30",60,"//немейя столько же кинула",112272,null],[128057,"2026-07-22T16:00:06",31,"/roll d6+1 колющий d6 некротикой",112272,null],[128059,"2026-07-22T16:00:20",60,"//я просто в говне немножко сейчас",128041,null],[128060,"2026-07-22T16:00:45",31,"/roll d20+1 бонусная атака древком вил, пытаюсь добить ту же заразу",112272,null],[128062,"2026-07-22T16:00:45",17,"/ Бывает. Вывезешь",128059,null],[128063,"2026-07-22T16:00:46",7,"/ перед тем, как вырубиться",128035,null],[128064,"2026-07-22T16:00:52",7,"/ спас ловкости с заразы",112272,null],[128067,"2026-07-22T16:00:56",7,"/ адское возмездие",112272,null],[128068,"2026-07-22T16:01:00",31,"Бонус мимо/",112272,null],[128069,"2026-07-22T16:01:02",31,"Ход/",112272,null],[128070,"2026-07-22T16:01:09",17,"/А ты кинь д100",128063,null],[128071,"2026-07-22T16:01:12",7,"/r 2d10 огнем и я вырубаюсь",112272,null],[128072,"2026-07-22T16:01:19",7,"/r d100",128070,null],[128074,"2026-07-22T16:01:28",7,"/r 2d10",128071,null],[128076,"2026-07-22T16:01:29",17,"/r -1",112272,null],[128078,"2026-07-22T16:01:39",60,"//ээээ, какой вырубиться",128063,null],[128079,"2026-07-22T16:01:44",60,"//стоять! Жить!",112272,null],[128080,"2026-07-22T16:01:45",7,"/ 13 огнём",128077,null],[128081,"2026-07-22T16:01:57",7,"/ я чародей ¯\\_(ツ)_/¯",128078,null],[128082,"2026-07-22T16:02:10",60,"//курварвар даже поднять не сможет",112272,null],[128083,"2026-07-22T16:02:34",17,"Тарк заколол вилами вьющуюся заразу после того как ее обожгло огнем тифлингши",112272,null],[128084,"2026-07-22T16:02:55",31,"Так у меня еще бонус получается оставался?/",128083,null],[128085,"2026-07-22T16:03:05",17,"/ Но ты не дойдешь",112272,null],[128086,"2026-07-22T16:03:09",17,"/ Местность трудная",112272,null],[128087,"2026-07-22T16:03:41",31,"Ну выдвигаюсь тем не менее, хоть часть пути прохожу",128086,null],[128088,"2026-07-22T16:03:43",17,"Все немагические источники огня в радиусе 60 футов гаснут. Магическое пламя тускнеет до конца\nследующего хода",128072,null],[128089,"2026-07-22T16:03:59",9,"//Рядом есть Немея? Враги? Где я 🤔",112272,null],[128090,"2026-07-22T16:04:11",17,"/ Рядом Тарх и Немея. Враги от тебя в 30 и в 20",112272,null],[128091,"2026-07-22T16:04:11",60,"//и буквально немейя потухла",128088,null],[128092,"2026-07-22T16:04:36",7,"/ спасибо не в форме феникса был)",128091,null],[128093,"2026-07-22T16:04:41",9,"/roll 1d10 облик нежити временные хиты",112272,null],[128095,"2026-07-22T16:05:22",17,"/ Бля я теперь всегда буду играть с дикой магией",112272,null],[128096,"2026-07-22T16:05:26",17,"/ Это такой мем",112272,null],[128097,"2026-07-22T16:05:45",7,"/ но у меня не чародей дикой магии! XD",128095,null],[128098,"2026-07-22T16:05:47",60,"//понял, видимо это была последняя прокачка анахрониса",128095,null],[128099,"2026-07-22T16:05:50",17,"/ Нагенерил таблицу д100 хуйни и сидишь кайфуешь",112272,null],[128100,"2026-07-22T16:06:12",17,"/ Да тебя никто не спрашивает) Скажи спасибо, ато кидал бы 2д100)",128097,null],[128101,"2026-07-22T16:06:38",17,"Ветвистые ближе к Ридли, Игольчатые дальше",112272,null],[128102,"2026-07-22T16:06:56",9,"*Ридли становится выше, руки слегка вытягиваются, при попытке на него взглянуть хочется отвести глаза в сторону. Он протягивает руку и касается Немеи, а после встаёт перед ней.*\n\n— Не время отдыхать, просыпайся.\n\n//Бонусным в ужасающий и основным 2 хита Немее",112272,null],[128103,"2026-07-22T16:07:34",9,"//Исцеляющие волшебные ручки детка\n🔥😎🔥\n   👉👉",112272,null],[128104,"2026-07-22T16:07:51",9,"//Ход",112272,null],[128105,"2026-07-22T16:09:54",9,"//Расовая абилка Аасимара с исцеляющими руками, тип того",112272,null],[128107,"2026-07-22T16:12:47",9,"//Бля, представляю как граф куколдит с таким же видом 😂👍",128106,null],[128108,"2026-07-22T16:13:07",17,"Три ветвистых заразы бегут атаковать Тарха своими колючими хлыстами",112272,null],[128109,"2026-07-22T16:13:21",17,"/r +3 q +3 q +3 q",112272,null],[128111,"2026-07-22T16:13:43",17,"/r 2d4+2 Колющий 2d6 Некротика",112272,null],[128113,"2026-07-22T16:13:56",17,"/ Тарха помянем",112272,null],[128114,"2026-07-22T16:14:04",17,"/ Дикая магия баровии его сдула",112272,null],[128115,"2026-07-22T16:14:33",9,"//Ту ту ту. Скок там у него хитов из скоки было🤔",112272,null],[128116,"2026-07-22T16:15:28",9,"//15 макс, в 0 скорей всего валяется, но может и помер дед Тарх",112272,null],[128117,"2026-07-22T16:17:12",31,"15 было",112272,null],[128118,"2026-07-22T16:17:15",7,"/ если больше максимума хитов снесли вроде смерть",112272,null],[128119,"2026-07-22T16:17:25",9,"// -3, живой пока, но присмерти",112272,null],[128120,"2026-07-22T16:17:40",60,"//так, постойте-ка... Ещё не поздно сюда ответить?",128032,null],[128121,"2026-07-22T16:18:18",60,"//остаток урона должен превышать максимум хитов",128118,null],[128122,"2026-07-22T16:18:36",60,"//плюс это две атаки, а не одна",112272,null],[128123,"2026-07-22T16:19:06",31,"Короче, Тарх чилит/",112272,null],[128124,"2026-07-22T16:19:37",9,"//Наелся и спит с ложкой в руках.",128123,null],[128125,"2026-07-22T16:20:01",31,"Ага, наебнул говнеца/",128124,null],[128126,"2026-07-22T16:22:17",9,"//Лан, Альф вродь ходит. Щас будет Баровский бурьян косить.",112272,null],[128127,"2026-07-22T16:22:54",60,"//обе игольчатые рядом ведь?",127945,null],[128128,"2026-07-22T16:24:43",17,"/ На твоей стороне одна игольчатая прямо перед тобой, остальные месят ребят на дороге",128127,null],[128129,"2026-07-22T16:26:40",60,"//если могу, то реакция",128120,null],[128130,"2026-07-22T16:27:59",60,"В ответ на неожиданно усиленную мертвенной энергией атаку Альф моментально отшатывается, но тут же разворачивается и бьёт в ответ что есть силы\n\n//Приём \"дикарское возмездие\". Просто тычка в ответ на попадание в меня, ну там еще доп к4 урона будет",112272,null],[128131,"2026-07-22T16:28:14",60,"/r +d20 бум сдохни",112272,null],[128133,"2026-07-22T16:28:19",60,"//бывает)",112272,null],[128134,"2026-07-22T16:28:29",60,"Теперь вот действием его луплю",112272,null],[128135,"2026-07-22T16:28:33",60,"/r +d20",112272,null],[128137,"2026-07-22T16:29:32",60,"/r 2d6+13+d4 сдохни",112272,null],[128139,"2026-07-22T16:30:35",60,"//как далеко до них?",128128,null],[128140,"2026-07-22T16:33:40",17,"/ Тебе до них 30 местность всё еще трудная",112272,null],[128141,"2026-07-22T16:34:03",17,"Игольчатая зараза зарублена",112272,null],[128142,"2026-07-22T16:34:24",60,"Варвар отсекает ноги почти по пояс очередной заразе, после чего, продираясь через кусты, бежит и орет\n\n—ЧЕ У ВАС ТУТ ПРОИСХОДИТ?! СТОЯТЬ, ВАШУ Ж ЗА НОГУ!",112272,null],[128143,"2026-07-22T16:34:49",60,"//пытаюсь привлечь внимание на себя, двигаюсь на 15 фт к ним. Конец хода",112272,null],[128144,"2026-07-22T16:35:20",17,"/ Немея стоит 2 хита",112272,null],[128145,"2026-07-22T16:35:26",9,"//Так, немею я вродь отхилил капельку, чуть чуть 🤏🤏🤏 на 2 хита.",112272,null],[128146,"2026-07-22T16:35:28",17,"/ @Evreiskui_Department",112272,null],[128179,"2026-07-22T16:55:55",7,"/ тэк ребят\nВ какой стороне Тарх? Сколько до него и не словлю ли провоцированные атаки?",112272,null],[128190,"2026-07-22T16:58:20",31,"Недалеко лежит, но лучше себя подлечи, толку больше будет",128179,null],[128191,"2026-07-22T16:58:24",31,"//",128190,null],[128192,"2026-07-22T16:58:53",17,"/ 5 от тебя и в 10 заразы которые его свалили",128179,null],[128319,"2026-07-22T17:50:55",7,"/ тэк извиняюсь, теперь здесь фокусирован",112272,null],[128321,"2026-07-22T17:51:55",7,"/ метамагии нет, как и смысла себя хилить, меня прикройте чтобы варвара лечить мог \nТак, 5 зараз... Бонусным использую форму пламенной вуали и кастую огненные ладони",112272,null],[128322,"2026-07-22T17:52:05",7,"/ д6 урона некро у меня будет?",128192,null],[128323,"2026-07-22T17:52:13",7,"/r d100 твоя дикая магия",112272,null],[128326,"2026-07-22T17:52:37",17,"/за рулем",112272,null],[128327,"2026-07-22T17:52:42",7,"/r 3d6 +1d6 +4",112272,null],[128331,"2026-07-22T17:53:44",17,"/ все мертвы",112272,null],[128332,"2026-07-22T17:53:47",7,"/ половина в случае провала, сл 14 \nТэкс 5 зараз сжечь",112272,null],[128336,"2026-07-22T17:54:17",9,"//Ну, все таки хил пригодился",112272,null],[128343,"2026-07-22T17:56:08",7,"*Немейя очнулась после атаки. Она открыв глаза, мгновенно вспыхнула огнем, после чего сжигает орду зараз. Она покрытая пламенем, отходит в укрытие от колючек и говорит.*\n\n— Помоги остальным, прикрой. Я постараюсь вылечить их, если смогу.",112272,null],[128346,"2026-07-22T17:57:54",9,"//Кому говоришь?",128343,null],[128347,"2026-07-22T17:58:05",17,"/ Тебе",112272,null],[128348,"2026-07-22T17:58:08",7,"/ всем",128346,null],[128349,"2026-07-22T17:58:15",7,"/ и тебе в первую очередь",112272,null],[128350,"2026-07-22T17:58:25",7,"/ чтобы прикрыли",112272,null],[128352,"2026-07-22T17:58:36",60,"//враги все кончились?",128343,null],[128353,"2026-07-22T17:59:09",7,"/ 5 убито, 10 осталось",128352,null],[128356,"2026-07-22T17:59:22",7,"/ приступай к нарубке праха вампира",112272,null],[128357,"2026-07-22T18:00:08",60,"//аэ?...",128353,null],[128360,"2026-07-22T18:00:15",60,"//ниче не понял",112272,null],[128361,"2026-07-22T18:00:32",60,"//их было всего 8",112272,null],[128363,"2026-07-22T18:00:56",7,"/ ?",128192,null],[128364,"2026-07-22T18:01:09",60,"//это расстояние в футах",128363,null],[128367,"2026-07-22T18:01:51",7,"/ ну ладно",112272,null],[128474,"2026-07-22T18:37:48",60,"Выпутываясь из корней, Альф, видя, как тлеют трупы деревьев, что даже звучит странно, подходит к тарху, пытаясь ему хотя бы не позволить умереть, перевязывая раны",128343,null],[128475,"2026-07-22T18:38:08",60,"/r +1 варвар медик",112272,null],[128477,"2026-07-22T18:38:14",60,"//сойдет",112272,null],[128482,"2026-07-22T18:39:33",60,"Уже после этого альф возвращается к первой срубленной заразе и обрабатывает её шипы: его желание взять дерево с собой всё ещё не исчезло.\n\n—Какие-то ублюдские деревья, если честно. Промолчать, когда говорят о тебе, а потом дать за это в лицо. Слишком самоуверенные кусты!",112272,null],[128485,"2026-07-22T18:39:56",60,"/r +d20+5 обтёсываю полено по атлетике",112272,null],[128493,"2026-07-22T18:42:48",9,"//А бой закончился?",112272,null],[128529,"2026-07-22T19:01:48",17,"/ Да. Я просто занят был.",112272,null],[128530,"2026-07-22T19:03:20",17,"/ Случайный противник в пределах 30 футов видит на вашем месте силуэт хозяина Баровии. Он совершает  \nМудрость против Сл или пугается до конца следующего хода.",128323,null],[128533,"2026-07-22T19:04:18",17,"Когда Немея из последних сил поднявшись от лечения Ридли сжигала всех этих колючих монстров\n\nВы вдруг видели не ее, а огромного демона огня страшного и могущественного",112272,null],[128535,"2026-07-22T19:05:18",31,"Кидать мудрость всем?/",112272,null],[128540,"2026-07-22T19:05:42",9,"/roll 1d20 мудрость",112272,null],[128544,"2026-07-22T19:06:23",9,"*Ридли исчезает у вас на глазах, на его месте падает лишь красная запонка.*",112272,null],[128545,"2026-07-22T19:06:47",60,"\"Случайный противник\"",128535,null],[128547,"2026-07-22T19:06:56",17,"/ Ну мастер сказал видите вы",112272,null],[128548,"2026-07-22T19:07:01",17,"/ Бояться или нет",112272,null],[128549,"2026-07-22T19:07:05",17,"/ Сами решайте",112272,null],[128550,"2026-07-22T19:07:11",60,"/r +1 ы",112272,null],[128552,"2026-07-22T19:07:14",31,"/roll d20 мудрость",112272,null],[128554,"2026-07-22T19:07:21",17,"/ Моя дикая магия и я тут жёсткий самодур",112272,null],[128555,"2026-07-22T19:07:26",31,"Обоссались всей партией/",112272,null],[128556,"2026-07-22T19:07:32",7,"/ бойтесь меня",112272,null],[128557,"2026-07-22T19:07:50",7,"/ а мне кидать от самого себя спас? 🤔",128547,null],[128558,"2026-07-22T19:08:09",31,"Кинь, будет Крит единица и инфаркт/",128557,null],[128559,"2026-07-22T19:08:11",7,"/ потенциально это первый персонаж что боится себя сам",112272,null],[128560,"2026-07-22T19:08:14",60,"Ровно так же, как и Ридли, на несколько секунд исчезает из виду Альф. Затем, когда до него доходит, что это иллюзия, он появляется вновь\n\n—Ты че творишь, только закончили..",112272,null],[128561,"2026-07-22T19:08:28",17,"/ Как хочешь я вообще не просил Спасов",128557,null],[128564,"2026-07-22T19:08:56",17,"Иллюзия быстро пропадает",112272,null],[128569,"2026-07-22T19:10:21",7,"/ ну хоть что то",112272,null],[128581,"2026-07-22T19:12:51",17,"Вы продолжаете путь немного передохнув.\n\nЛес расступается, открывая окружённый частоколом город. За стеной видны тесные крыши домов и шпили нескольких зданий. Перед воротами установлены колья с волчьими головами.\n\nСтражники на башнях направляют на путников арбалеты.\n\n— Назовите себя и цель визита! кричит один из них. \n\n— В Валаки запрещено служить дьяволу Саду, разводить беспорядки и произносить угрозы. Нарушителей ждут колодки. И все должны быть довольны и счастливы!\n\nОн говорит грубо но при этом улыбается вам.",112272,null],[128593,"2026-07-22T19:16:52",31,"- мы мирные путники, и не служим никому",112272,null],[128614,"2026-07-22T19:22:38",7,"/ щас домой приеду и бахну пост. Мастер а сколько мы получили за зараз? @dunchev",112272,null],[128615,"2026-07-22T19:22:46",17,"/ Копейки там",112272,null],[128616,"2026-07-22T19:22:49",17,"/ попозже посчитаю",112272,null],[128620,"2026-07-22T19:24:20",9,"— Так есть. Судьба свела нас по разным причинам, в Баровии недавно.",128593,null],[128647,"2026-07-22T19:31:13",31,"/roll d20+1 внимательно осматриваю волчьи бошки. Это точно просто волки, или кто пострашнее?",128581,null],[128649,"2026-07-22T19:31:31",17,"Это и головы волков и головы оборотней",112272,null],[128651,"2026-07-22T19:32:21",31,"Мысль:\n\n*о, раз тут умеют оборотней обезглавливать, похоже место более или менее безопасное. Если ты не оборотень конечно*",112272,null],[128654,"2026-07-22T19:32:45",9,"//Броски на внимательность всегда как у следака ей богу 😂👌",112272,null],[128691,"2026-07-22T19:39:27",17,"— Тоооочно? А чего остальные молчат?\n\nСмотрит на Тифлинга и Фурболрга",112272,null],[128694,"2026-07-22T19:41:35",60,"—Как видите.\n\nВарвар держит за спиной одревеневшую заразу с отрубленными по пояс ногами, на спине, в ножнах, сияет меч: обычно это не пригодно к использованию, но размеры фирболга позволяют доставать его спокойно",128691,null],[128697,"2026-07-22T19:43:35",17,"— Ладно... Эту хреноту за воротами оставляйте и проходите. Можете остановится в таверне. А потом сразу к бургомистру. Он всех новеньких собеседует лично.",112272,null],[128698,"2026-07-22T19:43:49",17,"Он улыбаться не прекращает и даже говорит с улыбкой что выглядит\n\nСтранно\n\nЖутко",112272,null],[128701,"2026-07-22T19:44:19",17,"— Как только переступите порог Валаки, улыбка не должна сходить с вашего лица! Это закон города.",112272,null],[128702,"2026-07-22T19:44:39",17,"— Будьте уверены в Валаки все спокойно.",112272,null],[128707,"2026-07-22T19:46:30",60,"—Ну, как хотите, попробуем.. Но за древесину обидно, мне за неё убить пришлось. Её. И её сестёр. Или братьев.. Хер их разберёт.\n\nАльф с силой вбивает заразу башкой вниз в землю, оставляя на потом, а после натягивает на лицо улыбку: не настоящую, а магическую, маскировкой, чтоб не лыбиться вечно",112272,null],[128708,"2026-07-22T19:47:03",31,"Мысль:\n\n*улыбка закон города. Как в пророчестве цыганки*",128701,null],[128724,"2026-07-22T19:50:40",31,"Улыбаюсь во все свои зубы. Хз сколько их, я средневековый крестьянин, у стоматолога не бывал/",112272,null],[128741,"2026-07-22T19:54:47",7,"*Немейя выглядела выдохшийся. Однако она начала черпать оптимизм из шарика огня, что рядом чуть выше правого плеча левитировать. Она услышав вопросы, остановилась и внимательно присмотрелась на вояку.*\n\n— Путешественница, цель визита возможность пополнить припасы еды.\n\n*Отвечает с улыбкой на лице и держит шарик огня при себе.*",128581,null],[128752,"2026-07-22T19:58:28",17,"/ За зараз по 100 опыта",112272,null],[128754,"2026-07-22T19:58:54",31,"Обращаюсь к партии:\n\n- ну что, к бургомистру зайдем длятначала, как стражники велели? А потом поищем приют чтобы передать письмо призрака?",112272,null],[128757,"2026-07-22T19:59:48",9,"— Мы это давно решили.",128754,null],[128760,"2026-07-22T20:00:20",31,"- ну айда тогда",112272,null],[128765,"2026-07-22T20:01:52",7,"Немейя\n— Пойдёмте. Позже будем обдумывать, чем займёмся здесь. Денег совсем мало, с продовольствием что то решить надо.",112272,null],[128767,"2026-07-22T20:02:31",9,"— Думаю дней десять протянем, двадцать если будем экономить.",128765,null],[128768,"2026-07-22T20:02:34",31,"- уверен, в большом городе найдется работа",112272,null],[128777,"2026-07-22T20:06:12",17,"Створки ворот с тяжёлым скрипом закрываются за вашими спинами. За частоколом обнаруживается тесный город с мокрыми крышами, грязными улицами и рядами выцветших флажков.\n\nПовсюду нарисованы жёлтые солнца с широкими улыбками. На ближайшем доме висит свежий плакат: «ПРАЗДНИК ПЫЛАЮЩЕГО СОЛНЦА — ЧЕРЕЗ ТРИ ДНЯ».\n\nСтражник записывает ваши имена, после чего внимательно рассматривает ваши лица. Его собственная улыбка слишком широкая и совершенно не касается глаз.\n\n— Добро пожаловать в Валаки. Здесь безопасно. Здесь весело. Постарайтесь соответствовать.",112272,null],[128784,"2026-07-22T20:08:08",7,"*Девушка проходит в Валахию и поблагодарив стражника, начала искать путь к бургомистру. Указали возможные, здания примечательные.*\n\n— Ну вот мы и здесь, давай-те осмотримся?",112272,null],[128789,"2026-07-22T20:09:03",9,"//Бля! Аскелатора называют пылающим солнцем, имба 🔥. (Напомню что у нас 2 солнца на небе, 1 обычное, а второе бог)",112272,null],[128803,"2026-07-22T20:14:34",31,"Ребята, я спать. Если что, пообщайтесь с бургомистром без меня, я утром почитаю//",112272,null],[128816,"2026-07-22T20:17:27",17,"/ подождем. Пару антуражных постом дам",128803,null],[128819,"2026-07-22T20:18:22",17,"К вам пригласили сопровождающего проводника из стражи.\n\n— Я Купер. Приятно видеть новые лица в городе. Прошу за мной к поместью бургомистра по это дороге.",112272,null],[128822,"2026-07-22T20:18:55",17,"У вас не отнимали оружия, но строго и с улыбкой попросили соблюдать приличия и законы. Иначе будет наказание.",112272,null],[128824,"2026-07-22T20:20:11",17,"Чем дальше вы идёте, тем сильнее ощущаете неладное.\n\nЛюди приветствуют друг друга улыбками, но делают это слишком быстро, словно выполняют приказ. Торговка натягивает улыбку перед появлением патруля и опускает глаза, едва стражники проходят мимо. Дети играют деревянными куклами, изображающими смеющихся солдат, сжигающих волков и вампиров.\n\nНа площади стоят железные клетки и колодки. В них сидят несколько оборванных горожан. На головы осуждённых надеты тяжёлые гипсовые маски ослов. На табличках указаны их преступления:\n\n«ЗЛОНАМЕРЕННОЕ УНЫНИЕ».\n«НЕУВАЖЕНИЕ К ПРАЗДНИКУ».\n«РАСПРОСТРАНЕНИЕ ТРЕВОЖНЫХ СЛУХОВ».\n\nОдин из заключённых тихо стонет под маской. Прохожие старательно не смотрят в его сторону.",112272,null],[128825,"2026-07-22T20:20:37",17,"Люди проходят мимо вас.\n\nИ улыбаются вам.\n\nВы улыбайтесь им?",112272,null],[128826,"2026-07-22T20:21:41",60,"/r +1 проницательность на эмоции?",128824,null],[128827,"2026-07-22T20:21:41",9,"*Ридли не снимал маску, ему становится скорее жутко когда ему так улыбаются.*",112272,null],[128859,"2026-07-22T20:32:05",7,"/ Город, где улыбаются из страха...",112272,null],[128864,"2026-07-22T20:32:50",17,"Женщина нервно улыбается и шепчет:\n\n— Вы новенькие, поэтому вам пока простят. Поднимите уголки губ. Быстрее, пока патруль не увидел.\n\nЗаметив стражников, она повышает голос:\n\n— Какой чудесный день! Всё будет хорошо!",112272,null],[128867,"2026-07-22T20:34:21",7,"*Немейя с беззаботной улыбкой изначально, играет с огненным шариком. Параллельно, она услышала женщину, что очень нервно себя ведёт.*\n\n— Мм? Ох...\n\n*Девушка и не убирала улыбку с лица. Она просто выглядела измотанной, будто набиралась сил.*",112272,null],[129193,"2026-07-23T06:52:09",31,"- ребята, я тут вспомнил что нам Мадам Ева нагадала. Мы явно там где нужно и нам надо как то найти тут благородную женщину, которая постарается обратить нас в свою веру. Жрица какая то может?",112272,null],[129361,"2026-07-23T14:30:42",31,"И никакой реакции///",112272,null],[129362,"2026-07-23T14:31:09",31,"Ладно, пиздуем в бургомистру, сияем наклеенными улыбками//",112272,null],[129363,"2026-07-23T14:44:15",17,"// нет ждём этих гадиков",112272,null],[129364,"2026-07-23T14:44:21",17,"// Или я нахуй всё закрываю",112272,null],[129365,"2026-07-23T14:44:28",17,"/ И соберу новую пати ебал дремал",112272,null],[129366,"2026-07-23T14:45:03",17,"// мастер сидит с заряженым дилдо, а они не пришли на фан встречу",112272,null],[129367,"2026-07-23T14:53:49",7,"Немейя\n— Мадам, что обратит в свою веру говоришь. Ну либо жрица, либо кто то связанный с религией. Не знаю, в религии не разбираюсь.",129193,null],[129368,"2026-07-23T14:53:54",7,"/ извиняюсь",129366,null],[129369,"2026-07-23T14:55:44",17,"/ Да ладно, че понятно, взрослая жизнь, по девченкам гоняешь, лето",129368,null],[129371,"2026-07-23T15:01:58",31,"- я думаю нам могут дать наводку в приюте, куда мы принесем письмо. Он же вроде в честь какого то святого назван",129367,null],[129374,"2026-07-23T16:16:04",7,"Немейя\n— Ну я тоже так думаю. Что остальные скажут? Может планы имеются? \n/ Hard",112272,null],[129375,"2026-07-23T16:16:11",7,"/ @FSmit7 го дуэль",112272,null],[129376,"2026-07-23T16:32:04",60,"//знаешь историю про мальчика и волков?",129375,null],[129378,"2026-07-23T16:53:25",7,"/ как никто другой",129376,null],[129379,"2026-07-23T16:53:37",7,"/ как тебя еще заманивать?",112272,null],[129380,"2026-07-23T16:55:45",17,"/ Ладно у смита тяжелая физическая работа. Можно только сказать ему \"Держись брат, никто не бьёт так сильно как жизнь\"",112272,null],[129381,"2026-07-23T16:56:28",60,"Альфарий кивает, не снимая маскировки\n\n—Идем. Разберёмся с этим местом и найдем наконец и выход и помощь.",112272,null],[129382,"2026-07-23T17:02:38",7,"/ ну у каждого свое\nА я наивно полагал что после учебы будет много времени свободного",129380,null],[129383,"2026-07-23T17:09:30",9,"*Ридли кивает и идёт за пати внимательно наблюдая за местными.*",112272,null],[129384,"2026-07-23T17:29:24",17,"/ Ну что я занят буду, опишу позже",112272,null],[129400,"2026-07-23T20:03:36",31,"Ну видимо сегодня опять не играем/",112272,null],[129401,"2026-07-23T20:05:48",7,"/ завтра уберусь обговорю работу и свободен как птица в полёте первые пять минут",112272,null],[129410,"2026-07-24T07:57:07",17,"/ Сегодня готов плотно поиграть, есть картинки, карта и куча историй и квестов внутри города. Советую не спешить и исследовать",112272,null],[129411,"2026-07-24T07:57:18",17,"/ А еще круто было бы чтобы все пришли поиграть",112272,null],[129412,"2026-07-24T08:00:24",17,"Карта Валаки",112272,null],[129414,"2026-07-24T08:01:02",17,"В Валаки всё спокойно!",112272,null],[129415,"2026-07-24T08:07:29",17,"Вы идёте дальше\n\nМокрая брусчатка покрыта обрывками старых праздничных лент. В центре площади стоят деревянные колодки. Несколько измученных горожан заперты в них под холодным дождём; на головы им надеты грубые маски ослов. Стражники лениво наблюдают за прохожими, а местные стараются не смотреть заключённым в глаза.",112272,null],[129416,"2026-07-24T08:08:04",17,"Главная площадь. В ожидании праздника Солнца.",112272,null],[129417,"2026-07-24T08:09:11",17,"Один из заключённых тихо обращается когда вы проходите рядом\n\n— Пожалуйста… воды. Я всего лишь сказал, что дождь испортит праздник.",112272,null],[129418,"2026-07-24T08:21:36",31,"протягиваю ему фляжку с водой, стараюсь делать это скрытно от стражи",129417,null],[129419,"2026-07-24T08:26:45",17,"/Скрытность!\\",112272,null],[129420,"2026-07-24T08:27:35",17,"Ваш проводник радостно говорит\n\n— Не беспокойтесь! Это нарушитель спокойствия, законно наказан за распространение уныния! В Валаки всё хорошо!",112272,null],[129421,"2026-07-24T08:29:07",31,"/roll d20+1",129419,null],[129423,"2026-07-24T08:29:33",31,"думаю, если дать ему воды, то он улыбнется",129420,null],[129424,"2026-07-24T08:30:48",17,"Тебе удаётся подобрать момент, поднять ослиную маску и незаметно напоить его\n\nПод Маской ты видишь его лицо, в ссадинах, кровопоттеках. Его явно избивали очень жестоко\n\n— С-спасибо. \n\nОн улыбнулся",112272,null],[129425,"2026-07-24T08:32:54",31,"- что с эти городом? почему всех застявлябт улыбаться ибьют если не получается?",129424,null],[129426,"2026-07-24T08:33:37",17,"— Тише, тише. Улыбнитесь и ступайте. Не повторяйте мою ошибку господин.\n\nОн с усилием тянет улыбку смотря тебе в глаза",112272,null],[129427,"2026-07-24T08:35:31",31,"киваю и отхожу",112272,null],[129428,"2026-07-24T08:47:22",9,"//Каким-то образом мы просто не можем собраться. Эх",112272,null],[129429,"2026-07-24T08:47:32",7,"/ я сегодня свободен",129428,null],[129430,"2026-07-24T08:47:44",7,"/ только единожды могу отойти на собеседование по поводу подработки",112272,null],[129431,"2026-07-24T08:49:57",9,"*Ридли страхует Тарха в его намереньи помочь, стоит так чтобы не увидели. Крестьянин делал некоторые вещи которые интересны ему самому, да и бесстрашие немного симпатизировало.*",112272,null],[129432,"2026-07-24T08:52:50",9,"— Интересно. — *Взглянул на Немею.* — Если сказать что тебя делает счастливой огонь, они всё сожгут?",129427,null],[129433,"2026-07-24T08:55:35",7,"*Немейя смотря на ребят, просто не лезет. Она не собирается помогать в нарушении местных законов, но и мешать точно не собирается. Услышав вопрос, девушка слегка рассмеялась, к слову тихонько.*\n\n— Было бы славно, хех. Огонь красивый и не знаю я почему бы не устраивать большие костры. А что тебя делает счастливым? \n\n*Отвечает девушка, параллельно расправив крылья, будто вытягивая. Очень сильно они затекать начали, от того, что не двигаешь ими.*",112272,null],[129434,"2026-07-24T09:03:22",9,"— Не знаю. — *Счастье? Строгое воспитание и... сжигание в огне ифрита и возрождение из плоти, посиделки с нежитью так близко пока тело не начало меняться. Ридли был Аасимаром, а значит мог пережить некоторые изменения, приобрести мистические силы за счёт лишений, упорства и тяги к жизни. Обвиняет ли он свой культ? Нет, его так воспитали. Насколько он помнит есть то что возможно сделает его счастливым.* — Хорошее место для сна, нормальная еда, книги и тишина. Когда все спокойно, всё есть и никому не нужный читаю книги или простая прогулка.\n\n*Парень не мог с точностью определить что слелает его счастливым. На ум приходили только свободные от рутины дни.*",129433,null],[129437,"2026-07-24T09:39:32",7,"*Девушка приподняв бровь, она выглядела задумчиво.*\n\n— Ну тоесть просто прочтение книг, как поняла. Может что то еще?",112272,null],[129531,"2026-07-24T11:31:38",9,"– Надо пробовать. Приятным помню только отдых без лишних забот.",129437,null],[129638,"2026-07-24T12:27:12",7,"/ @QURTZZ Hard @FSmit7 продолжим? Нам надо в приютик, поищем место?",112272,null],[129640,"2026-07-24T12:28:21",31,"Нас надо сначала к бургомистру, мы у нему и идем//",112272,null],[129649,"2026-07-24T12:30:35",17,"/ Эх, Альф всё проёбывает. Сраный Ирл надо его найти, найти его родителей и....",112272,null],[129659,"2026-07-24T12:36:31",7,"/ показать им историю его браузера?",129649,null],[129661,"2026-07-24T12:37:18",17,"/ Найти ИРЛ  этот",112272,null],[129662,"2026-07-24T12:37:18",60,"//Я спал сегодня 10 часов",129649,null],[129663,"2026-07-24T12:37:27",17,"/ Счастливчик",129662,null],[129664,"2026-07-24T12:37:29",60,"//а всё потому что сегодня работы мало",112272,null],[129665,"2026-07-24T12:37:35",60,"//так что я по сути тут",112272,null],[129667,"2026-07-24T12:39:06",17,"/ Микро реак или надпись скип",112272,null],[129668,"2026-07-24T12:40:35",60,"—Воистину счастье. Когда какая-то херобора не пытается запудрить тебе мозги и есть свобода пути. Предсказуемость есть счастье. Как бы не любил я махать клинком, я люблю, когда об этом предупреждают. А на всё остальное плевать.\n\nГоворит Альф, рассуждая и даже толком не следя за всем остальным. Он и не заметил, как ребята покормили заключенного. Шепотом он добавил\n\n—Но счастье — не про этот город. Тут его нет. Есть только натянутый покой. Знать бы, что его так натягивает..",129434,null],[129669,"2026-07-24T12:41:37",60,"//если мы на городской площади, то до особняка недалеко",112272,null],[129670,"2026-07-24T12:41:43",17,"Вы подходите к особняку бургомистра \n\nБольшой оштукатуренный дом возвышается за железной оградой. Его фасад украшен яркими лентами и деревянными изображениями улыбающихся солнц, но краска на них облупилась. У крыльца дежурят вооружённые стражники, а по двору ходят два крупных мастифа. Изнутри доносится торопливый стук молотков — слуги готовят украшения к очередному празднику.",112272,null],[129673,"2026-07-24T12:42:06",17,"Поместье бургомистра Варгоса.",112272,null],[129675,"2026-07-24T12:42:42",60,"—Здравия!\n\nАльф поднимает руку, приветствуя стражу\n\n—Мы только прибыли. Нас направили сюда.",129670,null],[129680,"2026-07-24T12:45:30",7,"*Немейя осматривает особняк, что красиво украшен. Яркие ленточки, изображения улыбающихся солнц, все так торжественно. Так или иначе, она пока что ничего не говорила, лишь страже помахала.*",112272,null],[129681,"2026-07-24T12:46:06",17,"— Чтож. Вот мы и пришли. \n\nПотом додходит с улыбкой к страже у ворот.\n\n— Доброго дня Глэн, Майкл. Новички к бургомистру. Он примет их?\n\nТот радостно отвечает\n\n— Конечно примет! Как же иначе! Заходите гости.\n\nИз особняка выбегает молодой слуга с охапкой бумажных солнц. Он спотыкается, и украшения падают прямо в грязь. Стражник хватает юношу за воротник и объявляет\n\n— Порча праздничных символов. Бургомистр должен об этом узнать.\n\nСлуга в панике смотрит на вас с глупой улыбкой под маской страха и шепчет\n— Это случайность… пожалуйста, скажите им.",112272,null],[129685,"2026-07-24T12:51:28",60,"—Это случайность. Он упал.\n\nКаменным голосом говорит фирболг, понимая, что скорее всего слуге действительно может быть от этого нехорошо.",129681,null],[129688,"2026-07-24T12:52:44",7,"Немейя\n— Это было не специально же. Всякое бывает, не казнить же за это.\n\n*Говорит девушка, чувствуя, что отрицательные эмоции здесь вне закона... Любые...*",129681,null],[129693,"2026-07-24T12:56:38",17,"— Гости должны быть поскрамнее..\n\nЕще не успел отойти ваш проводник. \n\n— Глэн, расслабься, всё хорошо! Он сейчас же всё исправит и отмоет украшения! Правильно говорю, любезный месье?\n\nТот поднимает все из грязи и судорожно кивает с глупой улыбкой\n\n— У госпей будет самое хорошее впечатление от великого города Валаки. Где ВСЁ спокойно!\n\nГлен смягчается\n\n— И то верно!",112272,null],[129698,"2026-07-24T13:04:39",60,"—Ну и славно.\n\nГоворит Альф, проходя в помещение.",129693,null],[129702,"2026-07-24T13:06:29",17,"Тяжёлые двери особняка открываются раньше, чем ваш проводник успевает подняться на крыльцо.\n\nНа пороге появляется высокий широкоплечий мужчина в форме капитана городской стражи. Его короткие чёрные волосы зачёсаны назад, лицо покрыто старыми шрамами. Правая рука мужчины выглядит чудовищно: красная кожа, толстые чёрные когти и бугрящиеся под ней мышцы, словно конечность принадлежит не человеку.\n\nДва мастифа подходят к нему и сразу замолкают.\n\nМужчина не улыбается.\n\n— Кто такие?\n\nВаш проводник отвечает\n\n— Новенькие. Только прибыли в город и пришли представиться бургомистру.\n\nВзгляд капитана медленно проходит по каждому из вас, задерживаясь на оружии, доспехах и магических принадлежностях.\n\n— Айзек. Капитан стражи Валаки.\n\nОн переводит взгляд на испачканные бумажные солнца, которые молодой слуга прижимает к груди.\n\n— Исправишь до вечера. Все до единого.\n\n— Да, господин Айзек! Всё будет хорошо!\n\n— Посмотрим.\n\nАйзек поворачивается к вам.\n\n— Бургомистр разрешает гостям оставить оружие при себе. Это знак доверия. Не заставляйте его пожалеть. Идите за мной.",112272,null],[129703,"2026-07-24T13:06:58",17,"Айзек. Капитан стражи Валаки.",112272,null],[129707,"2026-07-24T13:09:04",17,"За дверями особняка пахнет свечным воском, свежей краской и мокрой шерстью.\nПросторный вестибюль переполнен праздничными украшениями. Со стен свисают красные и жёлтые ленты. Между семейными портретами прибиты деревянные солнца с одинаковыми широкими улыбками. Некоторые украшения совсем новые, другие перекрашивали столько раз, что их черты почти исчезли под слоями краски.\nСлуги торопливо работают под присмотром двух стражников.\nОдин мужчина, стоящий на стремянке, промахивается молотком и ударяет себя по пальцу. Он судорожно втягивает воздух, но, заметив Айзека, немедленно растягивает губы в улыбке.\n\n— Всё хорошо, господин капитан.\n\n— Разумеется — отвечает Айзек.\n\nУ стены на коленях сел тот самый молодой слуга. Он оттирает грязь с бумажных солнц мокрой тряпкой. Когда Айзек отворачивается, юноша быстро смотрит на вас и едва заметно кивает в знак благодарности.\n\nИз соседней комнаты слышится женский голос\n— Ленту выше! Выше, дорогой! Она должна внушать радость!\n\nСледом раздаётся слишком громкий и слишком долгий женский смех.\nНесколько слуг негромко отвечают\n— Всё будет хорошо.\n\nАйзек ведёт вас дальше, не обращая на это внимания.",112272,null],[129709,"2026-07-24T13:11:10",7,"*Немейя увидев грязь, проводит взглядом, в после пальцем по воздуху. Бумажные солнца внезапно начали тлеть и покрылись огнем, но тут же потухли и будто грязь сгорела. После Немейя с чуть улыбчивым лицом смотрит на Айзека и с интересом разглядывала как ребёнок руку.*\n\n— Приятно познакомится, капитан Айзек.",129703,null],[129710,"2026-07-24T13:11:28",7,"/ я фокусами вычистил если что, не успел написать правда ну ладно",112272,null],[129712,"2026-07-24T13:12:04",7,"Немейя\n— Довольно приятная атмосфера, чем то напоминает приют когда начинались праздники.",129707,null],[129713,"2026-07-24T13:12:15",17,"/Можешь помочь ему пока мимо идёте",129712,null],[129714,"2026-07-24T13:12:44",7,"/ 6 секунд и фокусами всю грязь сжёг не задев ткань",129713,null],[129715,"2026-07-24T13:12:58",7,"/ уже описал как раз",129709,null],[129716,"2026-07-24T13:15:00",60,"//ща, я чуть за рулем",112272,null],[129717,"2026-07-24T13:15:38",7,"/ едешь по шоссе прям после пивка?",129716,null],[129725,"2026-07-24T13:24:13",17,"Возле лестницы вам навстречу выходит молодая служанка с длинной деревянной коробкой. Увидев Айзека, она пугается и едва не роняет её.\n\nКрышка сдвигается.\n\nВнутри лежит кукла, с фарфоровым лицом, подвижными частями на шанирчиках в кружевном белье, без платья. У неё длинные тёмные волосы, большие тёмные глаза и знакомые черты лица.\n\nКукла удивительно похожа на Ирину.\n\nАйзек мгновенно захлопывает крышку.\n\n— Откуда?\n\n— От господина Блинского, господин капитан. Он сказал, что сделал всё, как вы просили.\n\n— Отнеси в мою комнату.\n\nСлужанка торопливо кланяется и исчезает наверху. Айзек несколько секунд смотрит ей вслед, после чего поворачивается к вам.\n\n— Почти пришли.",112272,null],[129732,"2026-07-24T13:27:35",7,"*Немейя ступая за командиром, устала держать в узкэде крылья. Однако ее все больше смущает, что страха больше чем настоящего позитива... Город будто... Иллюзия...*",112272,null],[129763,"2026-07-24T13:56:56",60,"Альф напрягается, его инстинкты обостряются, глаз слегка мерцает океанической бездной. Видение мира слегка меняется, раскрывая его тайны\n\n//обнаружение магии, хочу куклу осмотреть получше",129725,null],[129786,"2026-07-24T14:05:20",17,"Кукла вовсе не магическая. А вот рука командира Айзека наполнена магией. Школы разрушения.",129763,null],[129791,"2026-07-24T14:07:04",60,"//Впервые слышу о такой школе",112272,null],[129793,"2026-07-24T14:07:22",17,"// Её еще называю воплощение.",112272,null],[129794,"2026-07-24T14:07:31",17,"/ Но я через скайримские понятия зашел",112272,null],[129796,"2026-07-24T14:08:36",60,"//не играл, увы",112272,null],[129853,"2026-07-24T14:38:43",7,"/ Разрушение, колдовство, восстановление, иллюзия, изменение",129794,null],[130105,"2026-07-24T17:41:59",31,"Ладно, посмотрели мы на супермена с горящей рукой и куколку, дальше то идем у бургомистру?/",112272,null],[130106,"2026-07-24T17:42:13",17,"/ Нет",112272,null],[130107,"2026-07-24T17:42:21",17,"/ Мы так всё проскипаем нафиг",112272,null],[130108,"2026-07-24T17:42:24",17,"/ Начинали в 4",112272,null],[130109,"2026-07-24T17:42:29",17,"/ И надо в 4 двигаться",112272,null],[130110,"2026-07-24T17:42:40",17,"/ Ну или как то пересобраться",112272,null],[130111,"2026-07-24T17:43:06",31,"Ок, продолжим тут же/",112272,null],[130112,"2026-07-24T17:44:38",9,"//Я тут",112272,null],[130113,"2026-07-24T17:44:48",31,"\"Мысли\"\n\n- Господин Блинский... Вроде такое имя было написано и на игрушке у детей цыган. Видимо местный кукольник. Но почему он сделал куклу с лицом Ирины? Надо бы его навестить\"",112272,null],[130114,"2026-07-24T17:49:48",31,"- скажите, господин Айзек, а в чем причина нашей встречи с бургомистром? Это довольно необычно, чтобы такой высокопоставленный человек общался со случайными путниками. Я прошёл немало земель по пути сюда, и нигде нет такой традиции. Разве у бургомистра нет иных забот?",112272,null],[130115,"2026-07-24T17:51:50",31,"/блин, я так понял что сам Айзек заказал куклу. Жаль что мы Ирину просрали в первом же бою. Было бы интересно ее расспросить об этой ситуации. Что если этот Айзек ее тайный воздыхатель? Мог бы стать нам напарником простив графа/",112272,null],[130116,"2026-07-24T17:52:48",17,"/Ну да, тут по разному может быть",130115,null],[130117,"2026-07-24T18:03:35",17,"Прежде чем вы успеваете ответить, где-то на верхнем этаже раздаётся резкий треск. Дом слегка вздрагивает. Между досками потолка на мгновение вспыхивает фиолетовый свет.\n\nНаверху что-то падает, а затем слышится раздражённый юношеский голос\n\n— Я сказал не входить!\n\nИз соседней комнаты снова раздаётся женский смех.\n\n— Наш Виктор так увлечён своими исследованиями! Какой талантливый мальчик!\n\nАйзек продолжает идти.\n\n— Сын бургомистра занимается науками. Наверх гостям нельзя.",112272,null],[130118,"2026-07-24T18:04:05",17,"— Таков порядок. Все гости показываются главному.",130114,null],[130119,"2026-07-24T18:05:02",17,"Вы проходите мимо длинного ряда портретов. На каждом изображён очередной городской праздник: улыбающиеся жители, деревянные солнца, волчьи головы и фигура Варгаса, возвышающаяся над толпой.\n\nОднако лица некоторых горожан на картинах старательно замазаны свежей краской.\n\nВ конце коридора Айзек останавливается перед тяжёлой дверью. За ней слышится громкий мужской голос:\n\n— Да, да, разумеется! Пусть входят! В Валаки всегда рады новым друзьям!\n\nАйзек открывает дверь.\n\nЗа массивным письменным столом стоит крупный мужчина в дорогой одежде. На столе лежат городские карты, списки жителей и эскизы огромного деревянного солнца. Возле кресла бургомистра устраиваются оба мастифа.\n\nВаргас Валлакович широко улыбается и разводит руки.\n\n— Новые лица! Добро пожаловать в самый безопасный город Багровии!\n\nЕго взгляд останавливается на ваших лицах.\n\n— Надеюсь, дорога не успела лишить вас хорошего настроения?",112272,null],[130120,"2026-07-24T18:06:02",17,"Варгос. Бургомистр Валаки.",112272,null],[130121,"2026-07-24T18:07:08",31,"*улыбаюсь*\n\n- ну что вы, ваша милость, как могут какие то мелкие неприятности испортить настроение нам, столь жизнерадостным путникам!",112272,null],[130122,"2026-07-24T18:10:43",9,"— Интересно что под свежей краской. — *Прошептал Ридли так чтобы слышала ток Немея. Он ранее наблюдал как она просто стёрла грязь.*",112272,null],[130123,"2026-07-24T18:11:11",17,"/Анализ если хочешь кинь или ловкость рук чтоб стереть незаметно",130122,null],[130124,"2026-07-24T18:11:17",17,"/ Если не хочешь не делай",112272,null],[130125,"2026-07-24T18:12:01",9,"//Не, у немеи есть фокусы для реальной грязи, раз видел что она может — рисковать самому не стоит 😏👌",112272,null],[130126,"2026-07-24T18:12:13",9,"//Щас читаю что с бургомистром, думаю",112272,null],[130127,"2026-07-24T18:19:37",17,"Варгас расплывается в ещё более широкой улыбке и звонко хлопает в ладони.\n\n— Превосходно! Наконец-то люди, понимающие, что правильный настрой сильнее любых невзгод!\n\nИз боковой двери появляется женщина с чайным подносом.\n\n— Как замечательно сказано!\nвосклицает она и торопливо смеётся. \n\n— Столь жизнерадостные путники! Ха-ха-ха!\n\nАйзек остаётся у двери. Его лицо не выражает ничего. Он не улыбается как вы заметили.\n\nВаргас указывает на кресла перед столом\n\n— Садитесь, друзья мои. В моём доме нет нужды стоять, словно на допросе. Мы просто хотим познакомиться с нашими новыми гостями.\n\nКогда все рассаживаются, он складывает руки на животе и внимательно осматривает каждого.\n\n— Итак, представьтесь. Откуда вы прибыли в Валаки? Полагаю, с востока — из деревни Багровия? Мне уже доложили, что вы пришли в восточным вратам.\n\nЕго улыбка сохраняется, но взгляд становится заметно внимательнее.\n\n— И какие вести вы принесли оттуда?",112272,null],[130128,"2026-07-24T18:24:57",9,"— Немного, но чтобы не омрачать день другим я ношу маску чтобы никто не видел моего плохого настроения. Нельзя расстраивать людей, пусть остаются счастливы. — *Ридли не стал врать, просто приукрасил. Маску он и правду носил основном для того чтобы люди не пугались его багровых глаз, с другой стороны использовал маску как отговорку чтобы не кривиться постоянно. Он поклонился перед тем как сесть.* — Это мои друзья, они всё понимают. Простите за мои манеры что не могу сейчас снять убор, хотя она не выглядит дружелюбно.\n\n*Ридли будто задумался а потом кивнул будто сам к себе и обратился к Бургомистру.*\n\n— Простите, у меня к вам прозьба. Мне нужно немного стойкой краски чтобы нарисовать на своей маске улыбку. Думаю так будет лучше.",112272,null],[130129,"2026-07-24T18:27:00",9,"//Сейчас и посмотрим насколько гибко Бургомистр относится к всему этому.",112272,null],[130130,"2026-07-24T18:27:12",17,"Лидия Петровна. Жена бургомистра Валаки",112272,null],[130131,"2026-07-24T18:33:12",17,"Варгас несколько мгновений молча смотрит на маску Ридли. Затем его лицо озаряет неподдельный восторг.\n\n— Вот! Вот человек, который понимает истинный дух Валаки!\n\nОн с силой ударяет ладонью по столу. Чашки на подносе Лидии тихо звенят.\n\n— Вы не позволяете собственным несчастьям отравлять настроение окружающих. Более того — вы сами просите помочь вам нести радость другим! Многим моим подданным следовало бы у вас поучиться.\n\nЛидия растягивает губы в широкой улыбке\n\n— Как необыкновенно мудро! Ха-ха-ха!\n\n— Краску! \nприказывает Варгас. \n\n— Красную праздничную краску и хорошую кисть!\n\nЛидия торопливо ставит поднос на стол, но бургомистр внезапно поднимает руку.\n\n— Нет. Я сам.\n\nСлуга приносит небольшую банку густой красной краски. Варгас открывает её, тщательно перемешивает содержимое кистью и подходит к Ридли.\n\n— Если позволите, мой друг. Улыбка должна быть искренней даже тогда, когда нарисована.\n\nОн склоняется к маске и медленно проводит по ней кистью. Сначала одну изогнутую линию, затем вторую, поднимая уголки всё выше. На безжизненном лице появляется широкая красная улыбка.\n\nВаргас отступает на шаг и любуется результатом.\n\n— Превосходно!\n\nЛидия хлопает в ладоши\n\n— Какая замечательная улыбка!\n\nАйзек возле двери ничего не говорит. Его взгляд задерживается на красной краске, а затем поднимается к багровым глазам за прорезями маски. Вот глаза его больше интересуют явно.\n\nВаргас кладёт кисть рядом с банкой.\n\n— Считайте краску подарком Валаки. Носите эту улыбку с гордостью. Более того, вы должны появиться в ней на Празднике Пылающего Солнца — рядом со мной.\n\nОн широко улыбается Ридли.\n\n— Пусть весь город увидит, что даже человек, скрывающий лицо, способен показать окружающим своё счастье.\n\nПосле короткой паузы Варгас добавляет\n\n— Всё будет хорошо.",130128,null],[130133,"2026-07-24T18:35:44",9,"*Ридли встал и поклонился бургомистру.*\n\n— Большое спасибо. Простите что не представился ранее, меня зовут \"Ридли\".",112272,null],[130134,"2026-07-24T18:36:13",9,"//Теперь враги будут обсираться в 2 раза эффективнее ^^",130132,null],[130135,"2026-07-24T18:36:25",17,"— Да, да. Всё хорошо. Сейчас мы со всеми вами познакомимся. \n\nон оглядывает остальных",112272,null],[130136,"2026-07-24T18:36:37",7,"/ я отошел на пять минут, а тут кипишь начался",112272,null],[130137,"2026-07-24T18:42:03",60,"Фирболг молча смотрел на сцену этого буквального лицемерия, подсвечивая магию для себя, пока ещё мог. Наконец, когда речь зашла про остальных, он кивнул, сложив руки на груди\n\n—Альфарий Темпест. Я из дальней земли, ещё дальше, чем выход из этого проклятого графства.\n\nНесмотря на то, что на лице его была улыбка, голос был не слишком счастливым",130135,null],[130138,"2026-07-24T18:43:03",17,"/ Ути пути улыбашка варвар",130137,null],[130144,"2026-07-24T18:47:51",7,"*Немейя зайдя в комнату, сделала лёгкий поклон. Она осматривалась и искала что то... Горящее — свечка, камин. Однако быстро приходит в себя и услышав Ридли, она не поняла про что он. После промолчала короткий разговор и представляется.*\n\n—  Я Немейя, волшебница специализирующаяся на огне. Путешественница, лекарь и просто дама с сюрпризами. \n\n*Она говорила с простой улыбкой на лице. Так или иначе, в голосе был какой то азарт, с нотками легкого оптимизма.*",130135,null],[130145,"2026-07-24T18:48:42",31,"- ну я просто крестьянин, который решил что сидеть на ферме это слишком грустно, и пустился в путешествие",112272,null],[130146,"2026-07-24T18:51:42",17,"Улыбка Варгаса на мгновение застывает.\n\n— Проклятого? Слова имеют силу, господин Темпест. Я предпочитаю говорить: \"земля, переживающая временные трудности.\"\n\nОн внимательно смотрит на фирболга.\n\n— Вы помните мир за туманом? Тогда расскажите: как вы попали в Баровию и почему Дьявол позволил вам дойти до моего города?\n\n*Магическим зрением Альфарий не замечает аур на присутствующих, но ощущает нестабильную магию где-то наверху.*",130137,null],[130147,"2026-07-24T18:54:17",7,"/ немейя с дикой магией: а?",112272,null],[130148,"2026-07-24T18:56:35",17,"Варгас заметно оживляется.\n\n— Волшебница огня? Само провидение привело вас в Валаки! Через три дня состоится Праздник Пылающего Солнца, и именно вы зажжёте его перед всем городом.\n\nЛидия восторженно хлопает в ладоши, а Айзек внимательно следит за руками Немейи.\n\n— Скажите, госпожа Немейя, сможете ли вы создать достаточно яркое пламя, даже если будет ветер или дождь?",130144,null],[130149,"2026-07-24T18:59:34",7,"*Немейя услышав про праздник, мгновенно заинтересованно переглянула взглядом на Варгаса.*\n\n— Дождь и ветер не помеха, если очень сильно постараться. Пламя податливо, а потухнет только если его магически потушить. Под водой еще не научилась им пользоваться. \n\n*Говорит девушка, проведя в воздухе руками и при помощи огненного шара создаёт разные фигурки.*",112272,null],[130150,"2026-07-24T19:00:58",60,"—Место воистину проклято, сэр. Будем честны. Я не маг и в моих словах нет такой силы, какая есть в моих зубах и руках. Отсюда нельзя выйти. Это и есть проклятие. Тот мир, что я видел до графства, по крайней мере имеет синее небо, как свечение моего клинка. И свободу всех путей. Я добрался сюда, потому что мне позволила судьба, выкованная отчасти не мной. Такова моя правда.",130146,null],[130151,"2026-07-24T19:15:43",17,"Айзек напрягается и кладёт руку на топор. Мастифы глухо рычат, наблюдая за огненными фигурками.\n\nНо Варгас восторженно поднимает руку\n\n— Спокойно, капитан! Это не угроза — это искусство!\n\nОн следит, как пламя принимает разные формы.\n\n— Великолепно! На празднике создайте пылающее солнце над площадью, а затем пусть оно поглотит фигуры волков. Жители будут в восторге!\n\nЛидия радостно хлопает.\n\n— Репетиция завтра утром, госпожа Немейя. Всё должно быть совершенно. Всё будет хорошо!",130149,null],[130156,"2026-07-24T20:46:57",17,"Улыбка Варгаса остаётся на месте, но пальцы медленно сжимаются на краю стола.\n\n— Клетка перестаёт быть проклятием, если её стены защищают от волков, господин Темпест. Здесь мы выбираем надежду, даже когда выхода не видно.\n\nИ́зек делает полшага вперёд.\n\n— Вы мой гость, поэтому я прощу подобную прямоту. Но на улицах Валаки выбирайте слова осторожнее.\n\nВаргас прищуривается.\n\n— Вы сказали, что судьба позволила вам попасть сюда. У этой судьбы было имя? ДЬЯВОЛ привёл вас в Баровию?",130150,null],[130158,"2026-07-24T20:58:37",60,"—Клетка, сэр Варгас — не ваш город. Ваш город старше тех оков, что ложно наложил на него один нехороший человек, считая, что сломит дух местного народа. Дисциплина оказалась выше этого, как вижу. А имя той судьбе.. Свобода. И никак иначе.",130156,null],[130159,"2026-07-24T21:14:55",7,"*Немейя не потушила пламя, она лишь его уменьшила и держала рядом.*\n\n— Зависит от габаритов. 4-5 футов мой максимум для поддержания, если будет сильный ветер и дождь. Так что на меня не надо ставить большие ставки. \n\n*Девушка говорила с улыбкой и пламя ярко горело рядом.*",130151,null],[130160,"2026-07-24T21:24:38",17,"/ ну кстате нет его город молодой",130158,null],[130161,"2026-07-24T21:29:32",60,"//а альф не знает. Ему кажется иначе",130160,null],[130162,"2026-07-24T21:31:43",17,"Потом Тарх представляется",112272,null],[130163,"2026-07-24T21:32:10",17,"Варгас одобрительно кивает.\n\n— Вот видите! Даже простой земледелец понимает, что унынию нельзя позволять управлять жизнью. Вы покинули грусть и выбрали надежду!\n\nОн оценивающе смотрит на Тарха.\n\n— Крепкие руки нам пригодятся. На празднике поможете поднять Пылающее Солнце над площадью. Пусть жители увидят, на что способен человек, решивший стать счастливым!",130145,null],[130164,"2026-07-24T21:37:52",17,"Улыбка Варгаса теплеет, а напряжение в его пальцах исчезает.\n\n— Вот теперь мы понимаем друг друга, господин Темпест! Страд воздвиг вокруг нас клетку, но дисциплина Валаки не позволяет ему сломить наш дух. И хоть вы ошибаетесь, городок у нас молодой, но именно мудрое правление делает его единственным спокойным местом!\n\nОн указывает на фирболга.\n\n— Повторите эти слова на празднике. Пусть весь город услышит: истинная свобода рождается из порядка, надежды и единства!",130158,null],[130165,"2026-07-24T21:40:00",60,"Альф немного нахмурился. Бургомистр явно переиначил его слова, но спорить сейчас не хотелось: нет смысла портить другим праздник, если сам не собираешься что-то праздновать. Он просто промолчал, кивнув",130164,null],[130166,"2026-07-24T21:49:35",17,"Варгас восхищённо наблюдает за пламенем.\n\n— Четырёх футов вполне достаточно! Сердцевина праздничного солнца будет пропитана маслом. От вас требуется лишь подарить ему жизнь.\n\nВ этот момент огонь Немейи неожиданно вытягивается в сторону двери, хотя в комнате нет ветра.\n\nРаздаются три размеренных удара.\n\nАйзек открывает дверь. На пороге стоит худой мужчина в чёрном сюртуке с запечатанным письмом.\n\n— Эрнст Ларнак, слуга леди Фионы Вахтер. Моя госпожа приглашает почтенных путешественников сегодня вечером разделить с ней ужин.\n\nОн передаёт письмо героям, вежливо кланяется и уходит.\n\nУлыбка Варгаса становится неподвижной. Айзек закрывает дверь.\n\n— Поразительно быстро она узнала о вашем прибытии\nтихо произносит бургомистр. \n\n— Фиона собирает вокруг себя недовольных и слишком благосклонно отзывается о Дьяволе.\n\nОн снова улыбается.\n\n— Примите приглашение. Выслушайте её и узнайте, чего она хочет от вас. После расскажете мне всё.\n\nВаргас поднимается, давая понять, что встреча закончена.\n\n— До ужина можете разместиться в трактире «Синяя Вода». А завтра утром жду вас на репетиции. Всё будет хорошо!",130159,null],[130167,"2026-07-24T21:54:05",17,"Эрнст Ларнак. Слуга леди Фионы Вахтёр. Аристократки из Валаки.",112272,null],[130168,"2026-07-24T22:04:35",17,"/ Hard спроси чё нить или не хочешь?",112272,null],[130169,"2026-07-24T22:05:51",9,"//Я не знаю что спрашивать у него, этот хер явно перекрцчивает все так как ему удобно. Мне интересно посмгтреть чем занимается малой валлаки, но уверен что получу  отворот поворот)",112272,null],[130170,"2026-07-24T22:06:04",17,"/ Малой?",112272,null],[130171,"2026-07-24T22:06:08",17,"/ Сын его?",112272,null],[130172,"2026-07-24T22:06:15",17,"/ Но тудя низяяяя))",112272,null],[130173,"2026-07-24T22:06:42",9,"//Всё что хотел узнать спросили мои соратники 😏👌",112272,null],[130174,"2026-07-24T22:08:31",9,"//Немного расположения добился, шоу с маской устроил, не отсвечивал сильно заняв пока нейтральную позицию, думаю сейчас что делать. Харизма у перса хоть и хорошп но для заговоров он не создан, так что чёрт знает что спросить",112272,null],[130175,"2026-07-24T22:26:42",17,"/ Эх. А как же залезть в кольцо и варвар кидает его в форточку в комнату к сыну на второй этаж?",112272,null],[130176,"2026-07-24T22:30:15",9,"//Да, имба. План слишком гениален для такого персонажа, нам нужен плут в пати с высокой интой и самоубийственными идеями 😏👌",112272,null],[130177,"2026-07-24T22:31:52",9,"// Слишком много сижу в пинтерест... у меня ассоциации с тем как любовник лезет в окно в тайне от родителей или тип того 🤔",130175,null],[130178,"2026-07-24T22:44:05",17,"/ Я лично не отыгрываю от цифры инты в характеристике перса. Считаю что у самого тупого варвара может появиться гениальная идея. Называю это проблеском гениальности или ход гения))",130176,null],[130179,"2026-07-24T22:45:39",9,"//Но это придумал не я а ты. Так хочешь чтобы я воспользовался твоей идеей? Ну, мне так не интересно, так что сорян.",130178,null],[130180,"2026-07-24T22:46:45",9,"//Если чего-то не сделают другие, и у меня будет идея — обязательно пристрою 👌",112272,null],[130181,"2026-07-24T22:47:01",17,"/ Не об идее нет и речи. Это как рофл закинул.",112272,null],[130182,"2026-07-24T22:48:08",9,"//Значит пора лезть в окно ^^",112272,null],[130183,"2026-07-24T23:24:12",17,"И Бургомистр Варгос добавляет в конце\n\n— И да... Не слушайте бредни святого отца Люциана. Он распространяет ересь, что город защищают мощи святого Андрала в церкви. Очевидно это глупости. Город, как вы уже поняли, живёт процветающе благодаря властям и правилам.",112272,null],[130185,"2026-07-25T14:43:05",17,"/ @FSmit7 давай что нибудь тут пукнуть надо. И мне понять чё вы куда вы",112272,null],[130186,"2026-07-25T14:45:51",60,"—Ну, оно и заметно.. Каменная стена прочнее чем чей-то труп, как бы грубо не звучало. Запомню. И.. Полагаю, это всё? У вас есть целители? Нам бы по-хорошему найти лекарство от вампиризма.. Но нет среди нас таких, не волнуйтесь.",130183,null],[130187,"2026-07-25T15:06:23",17,"Улыбка Варгаса на мгновение застывает. Лидия перестаёт звенеть чашкой, а Изек кладёт ладонь на рукоять топора.\n\n— Лекарство… от вампиризма? Любопытный вопрос. В Валаки вампиров не лечат — их сжигают.\n\nОн внимательно осматривает каждого из вас.\n\n— Но если речь идёт о вашем знакомом, обратитесь к отцу Люциану. В ранах и проклятиях он разбирается лучше, чем в политике. Заодно сообщите мне, если он вновь начнёт болтать о костях святого.\n\nВаргас снова широко улыбается и указывает на дверь.\n\n— На этом всё. Отдыхайте, осмотрите наш прекрасный город — и не опоздайте на подготовку к празднику!",130186,null],[130188,"2026-07-25T15:07:13",60,"—Ну, благодарю.. Узнаем, как он там. Всего доброго.\n\nАльф готов уходить, ждёт остальных",130187,null],[130189,"2026-07-25T15:56:01",31,"На выходе из кабинета Бургомистра Тарх резюмирует:\n\n- Итого у нас 4 точки интереса - отец Люциан, дворянка к которой нас пригласили, кукольник и приют, куда нужно донести письмо призрака. Куда пойдем? Я бы закрыл вопрос с приютом, а вечером отправимся к дворянке. Как вам?",112272,null],[130194,"2026-07-25T17:08:39",9,"*Кивнул.*\n\n— Скорей всего. Предлагаю прийти к дворянке в последнюю очередь. Возможно она не будет выгонять гостей в ночь и мы секономим на таверне, да и если она та самая из предсказания, лучше узнать побольше перед визитом.",130189,null],[130257,"2026-07-25T18:03:58",7,"Немейя\n— Звучит как экономия времени, я за.",130189,null],[130314,"2026-07-26T16:36:35",17,"/ Куда в итоге приют?",112272,null],[130315,"2026-07-26T16:36:53",7,"/ @dunchev мы все идём в приют сначала, да ребят? @QURTZZ @FSmit7 Hard",112272,null],[130316,"2026-07-26T16:36:59",31,"Я бы в приют пошел//",112272,null],[130317,"2026-07-26T16:37:21",31,"Там дети, может быть и выход на кукольника кстати))//",112272,null],[130318,"2026-07-26T16:38:07",9,"//Я хотел бы прийти к мадаме что нас пригласила в последнюю очередь. Пусть понерничает, подождёт, мы все такие важные 😏👌",112272,null],[130319,"2026-07-26T16:39:36",31,"Особенно ты со своей улыбочкой//",130318,null],[130320,"2026-07-26T16:40:15",31,"Бля, я понял, бургомистр это же Джокер из Тёмного Рыцаря))) не зватет только от него фразу: ты чего таклй серьезный//",112272,null],[130322,"2026-07-26T16:44:58",9,"//Этой? Ну, я застраховался немного, эту улыбку нарисовал сам Бургомистр, мне не надо кривить лицо и тд. Специально если Ридли будет реально улыбаться — буду кидать запугивание)",130132,null],[130677,"2026-07-26T22:15:37",7,"/ ну жду завтра",112272,null],[130694,"2026-07-26T22:50:54",17,"Здание приюта стоит в стороне от главной улицы, за низкой каменной оградой. Штукатурка местами осыпалась, окна затянуты тусклым стеклом, а над дверью висит выцветшая деревянная табличка с изображением солнца.\n\nИзнутри доносятся детские голоса, скрип половиц и чей-то сухой кашель. Когда вы приближаетесь, занавеска в одном из окон чуть шевелится, но лицо за ней тут же исчезает.",112272,null],[130695,"2026-07-26T22:51:19",17,"Детский приют святого Андрала в Валаки.",112272,null],[130696,"2026-07-26T22:52:23",17,"Дверь открывает высокая женщина лет пятидесяти в простом тёмном платье. Её седые волосы туго собраны на затылке, а под глазами лежат глубокие тени.\n\n— Я Маргарита, настоятельница этого приюта\n\nГоворит она, оценивая вас внимательным взглядом. \n\n— Если вы пришли с пожертвованием, мы будем благодарны. Если с жалобой на детей — встаньте в очередь.\n\n— Что вы хотели?",112272,null],[130697,"2026-07-26T22:52:48",17,"Маргарита. Настоятельница детского приюта в Валаки.",112272,null],[130704,"2026-07-26T23:22:51",9,"//Ох, завтра уже. Алексей тут будет и посмотрим",112272,null],[130720,"2026-07-27T05:44:01",31,"- Добрый день, добрая госпожа. Мы по иному делу. Кажется, у нас есть что то, что предназначено вам. Вы позволите нам войти?",112272,null],[130737,"2026-07-27T08:16:59",17,"— Говорите сразу, что нужно. Пока я не узнаю цель вашего визита, никто не войдёт в приют.",112272,null],[130739,"2026-07-27T08:19:52",31,"- у нас письмо для вас. Курьер спешил к вам, но увы, погиб",112272,null],[130753,"2026-07-27T08:22:31",17,"— Что ж. Где оно, я готова его принять. \n\nОна протягивает раскрытую ладонь",112272,null],[130762,"2026-07-27T08:24:21",31,"Протягиваю письмо",112272,null],[130763,"2026-07-27T08:24:46",31,"/roll d20+1 на внимательность, оцениваю как она отреагировала на ситуацию",112272,null],[130767,"2026-07-27T08:25:22",17,"Как и любая настоятельница, которая оберегает покой детей",112272,null],[130768,"2026-07-27T08:26:28",31,"- должен сказать, курьер спешил даже после смерти. Видимо, там что то важное. Если вам нужна помощь, скажите",112272,null],[130771,"2026-07-27T08:27:03",17,"Она берёт письмо и кивает",112272,null],[130772,"2026-07-27T08:29:27",17,"Маргарита берёт письмо двумя пальцами, словно бумага испачкана чем-то невидимым. Несколько мгновений она молча читает, затем возвращается к началу и перечитывает снова.\n\nОна вкратце передаёт вам суть письма после прочтения. В письме говорится, что добрые сёстры с мельницы готовы принять нескольких сирот. Дети будут помогать по хозяйству, а взамен получат тёплую постель, сытную пищу и заботливый надзор вдали от жестоких улиц Валаки.\n\nЛицо Маргариты остаётся неподвижным, но пальцы всё сильнее сминают край бумаги.",112272,null],[130773,"2026-07-27T08:30:49",17,"— Они уже приходили...\n\nОна открывает дверь и жестом приглашает вас пройти внутрь, подальше от окон.\n\n— Три женщины, пожелая и две её дочери. Называли себя сёстрами милосердия. Принесли хлеб, сладкие пироги и говорили так ласково, что дети ещё неделю спрашивали, когда они вернутся.\n\nМаргарита кладёт письмо на стол.\n\n— Я им отказала. Но вчера пропал один из наших мальчиков. Миливой. Двенадцать лет. Он говорил, что больше не хочет быть обузой и что на мельнице ему дадут работу.\n\nОна поднимает на вас взгляд.\n\n— Я не поверила им.",112272,null],[130774,"2026-07-27T08:32:30",31,"Оглядываю спутников\n\n- опять эта мельница. Зачем там дети? Там явно не место для них.\n\nНеожиданное воспоминание о первом дне в Бвгровии\n\n- я сейчас вспомнил, что когда мы прибыли сюда и у нас угостили пирогами, один мужик передал старухе шевелящийся мешок. Я подумал, что там кролик или голубь, для начинки. Но теперь мне так не кажется. Похоже, они похищают детей",112272,null],[130775,"2026-07-27T08:33:10",31,"- разве мальца выпустят из города?",130773,null],[130776,"2026-07-27T08:34:54",17,"— Как он пропал не известно, факты лишь в том, что он исчез. А за несколько дней у нас вышла ссора, по поводу этого его желания, уйти на мельницу.",112272,null],[130778,"2026-07-27T08:35:38",31,"- кто то из остальных детей может что то видел? Вы их не опрашивали?",112272,null],[130779,"2026-07-27T08:37:06",17,"— Опрашивала. Остальные говорят, что Миртон стал замкнутым и не общался с остальными. Одной девочке он еще раз заявил позавчера, что будет жить и работать как взрослый.",112272,null],[130780,"2026-07-27T08:38:03",31,"- а эти сестры больше не появлялись?",112272,null],[130804,"2026-07-27T09:01:10",17,"— Они появляются иногда у ворот, на сколько я знаю. Торгуют пирогами.",112272,null],[130805,"2026-07-27T09:01:45",31,"- надо бы с ними поболтать. И со стражниками на выходе из города",112272,null],[130806,"2026-07-27T09:01:54",17,"У всех кто ел пироги в момент упоминания о них слюна выделяется обильно. \n\nОчень хочется снова вкусить эту великолепную выпечку",112272,null],[130807,"2026-07-27T09:03:55",9,"— Надеюсь я был не прав, это не карга и её сёстры. — *Ридли произнёс под нос, кража детей старухами и женщинами в подобном месте у него ассоциировалась только с упоминанием когда ведьмы жрали людей.*",130774,null],[130808,"2026-07-27T09:05:56",31,"- их трое, очень похоже на карг. и детей к себе заманивают. и пироги у них с мясом, твою т мать",130807,null],[130809,"2026-07-27T09:09:04",9,"*Кивает.*\n\n— Мне это не нравится, я бы сжёг мельницу без разбирательств. Но там могут быть дети. — *Сделал паузу, а потом добавил:* — Значит это не вариант, дети это будущее не смотря на то насколько место считается гиблым. Они забирают будущее этого места.",130808,null],[130810,"2026-07-27T09:10:35",9,"— Надеюсь мы не правы, в пирогах мясо волков чьи головы на кольях у стен Валаки.",130808,null],[130811,"2026-07-27T09:11:14",31,"- справимся ли мы с тремя каргами на их территории?",112272,null],[130812,"2026-07-27T09:12:38",9,"//Приют \"Солнышко\"",130695,null],[130813,"2026-07-27T09:13:49",9,"//Ощущение что тут только мы, эх. Хочется подождать остальных, тем более без их мощи не решим ничего.",130811,null],[130814,"2026-07-27T09:14:16",31,"Ну подождём, хер ли еще делать/",112272,null],[130815,"2026-07-27T09:14:47",9,"//Хорошо, я + - тут, так что буду поглядывать",112272,null],[130816,"2026-07-27T09:15:22",31,"@Evreiskui_Department @FSmit7 почитайте хоть и отпишите//",112272,null],[130825,"2026-07-27T09:19:45",17,"/ Два обывателя такие нахуй этих героев, мы сами щас на вилы этих пекарей!",112272,null],[130826,"2026-07-27T09:20:30",31,"/вилы это моя тема, Ридли то более сложный тип, даром что обыватель/",112272,null],[130827,"2026-07-27T09:27:14",9,"//Ну, слегка похож на сумку хранения, чуть чуть на танка (надо доебаться до варвара, пусть научит лёгкие доспехи носить), а ещё жратвы пронёс в обход графа. Все мои заслуги",130826,null],[130828,"2026-07-27T09:27:51",9,"//Обожаю когда то что должны были решить герои решают простые люди)",130825,null],[130829,"2026-07-27T09:31:22",9,"//Думаю Тарх покруче. У него вилы и всё. Тупо пох на всё, решает все проблеммы и заговоры в соло. Не зря народный герой 😏👌",112272,null],[130830,"2026-07-27T09:32:04",31,"Одна беда, дохнет даже от пердежа бабочки/",112272,null],[130831,"2026-07-27T09:49:01",7,"/ я только проснулся xd",130816,null],[130832,"2026-07-27T09:50:25",7,"/ торгуют пирогами...",112272,null],[130833,"2026-07-27T09:52:11",7,"*Немейя мгновенно услышав про пирог, снимает свой рюкзак. Она достаёт пирог и смотрит снова на его состояние, затем показывает его спутникам и Маргарите.*\n\n— Извиняюсь, случайно не этот пирог? Он у меня уже три луны, а свежий до сих пор.",130806,null],[130834,"2026-07-27T09:52:57",31,"*сглатываю слюну*",112272,null],[130835,"2026-07-27T09:58:24",7,"/ ы",112272,null],[130836,"2026-07-27T10:04:41",9,"//Я тупой, надо было проверить поля на наличие наркотиков или волшебных трав.",112272,null],[130837,"2026-07-27T10:05:20",9,"*Ридли старается игнорировать страннуб тягу к пирогам, он их не ел и не собирается.*",112272,null],[130838,"2026-07-27T10:07:02",7,"/ Изначально Немейя не ела т.к. была сытой, а потом ее смутило что они вечно свежие",112272,null],[130839,"2026-07-27T10:07:30",7,"/ если бы пирог не был свежим, во второй день бы съела",112272,null],[130840,"2026-07-27T10:23:19",31,"Я и Альф ели/",112272,null],[130841,"2026-07-27T10:24:08",17,"— Да, такие они привозили. Я резала его детям на стол. Сама не пробовала. Дети были довольны, просили еще.",130833,null],[130842,"2026-07-27T10:24:12",7,"/ в диспансер от зависимости?",130840,null],[130843,"2026-07-27T10:26:24",7,"*Немейя застыла на мгновение. Она будто не знала, как реагировать. Тот факт, что детей могли кормить хрен пойми чем, довольно таки показывает... Хотя может она зря так относится... Но ощущение, что при виде пирога у некоторых начинается ломка.*\n\n— И как дети себя вели? Их не крутило, не было какой нибудь... Ломки?",130841,null],[130844,"2026-07-27T10:30:43",17,"— Они приходили... Дай те ка припомню. Кажется на той неделе. Дети продолжают просить меня принести те пироги. Говорили что вкуснее ничего не ели. Еда им вдруг наша стана не вкусная. НО у меня дисциплина не сломается от детских капризов.\n\nИз-за Маргариты в стекле межкомнатной двери несколько детей мальчик и девочка выглядывают, видят пирог и убегают резко назад",112272,null],[130845,"2026-07-27T10:34:26",17,"Через некоторое время в дверь начинается стук и много детей за ней барабанят кулачками\n\n— ТЁтя Маргарита! Дайте нам пирог пожалуйста! Пожалуйста мы мечтаем покушать пирога!\n\nМаргарита даже пугается\n\n— ЭТО ЧТО ТАКОЕ?! НУКА ТИХО! ВСЕ БУДЕТЕ В УГЛУ СТОЯТЬ!\n\nОна рявкает на детей, но те кажется не унимаются, настолько они хотят пирог\n\n— Извините обычно такого мы детям не позволяем...\n\nДверь трещит от давления",112272,null],[130846,"2026-07-27T10:34:29",17,"Что вы делаете?",112272,null],[130847,"2026-07-27T10:34:41",17,"/Детский зомбипокалипсис",112272,null],[130848,"2026-07-27T10:34:54",31,"- Немея, прячь пирог и ходу отсюда!",112272,null],[130849,"2026-07-27T10:37:17",7,"*Девушка мгновенно прячет пирог в рюкзак. Она еле удержалась, чтобы его не сжечь в своих руках. Вызванно ли это было с нежеланием портить перед детьми? А может пирог до сих пор так пахнет, что просто не удержаться...*\n\n—  в следующий раз сожгу его в пепел, чем покажу. Детей я трогать не стану, пойдёмте отсюда, мы ничего не сделаем.",112272,null],[130850,"2026-07-27T10:40:50",7,"/ Hard @FSmit7",112272,null],[130851,"2026-07-27T11:02:36",60,"Альф принюхивается. Пирог действительно был вкусным. Вкуснее всего остального. Но почему сейчас его так сильно не тянет? Может дело в количестве относительно веса? На всякий случай фирболг напрягается(ярость) и выглядывает к детям\n\n—Цыц. Чертовщина какая-то с пирогами.. Ждите.",130845,null],[130852,"2026-07-27T11:08:37",17,"/ Тебя тянет",112272,null],[130853,"2026-07-27T11:08:45",17,"/ Или кидай мудрость спас СЛ10",112272,null],[130854,"2026-07-27T11:08:45",9,"— Простите что потревожили. — *Ридли извинился и обратился к настоятельнице.* — Но, больше не кормите детей этими пирогами. Цыгане строго настрого запрещают всем своим даже прикасаться к пирогам. — *Посмотрел на место где дети, а потом на настоятельницу, явно подыгрывал.* — Может непослущные детишки что ели пироги превращаются со впеменем в козлят а потом злая ведьма готовит из них эти же пироги.\n\n*Последнее он явно сказал больше для детей, чтобы припугнуть страшилкой. Даже если временно, хорошо если сработает.*",130845,null],[130855,"2026-07-27T11:09:22",31,"Кинуть на убеждение бы)/",130854,null],[130856,"2026-07-27T11:09:25",17,"/Запугивание с преимуществом улыбки",130854,null],[130857,"2026-07-27T11:09:31",17,"/На детей",112272,null],[130858,"2026-07-27T11:11:30",9,"/roll +d20+2 не зря улыбку нарисовали, хе хе",112272,null],[130860,"2026-07-27T11:12:22",60,"/r d20+1",130853,null],[130862,"2026-07-27T11:12:33",9,"//Ну, это моя ужасная удача, что ужтам",112272,null],[130863,"2026-07-27T11:12:50",31,"Норм, откуда у детей высокая мудрость/",130862,null],[130864,"2026-07-27T11:13:22",17,"Не тянет потому что подсознательно ты понимаешь, что пироги опасны",130860,null],[130865,"2026-07-27T11:13:55",17,"Дети настолько хотят пирог, что продолжают стучать в дверь не взирая на твою страшилку",130858,null],[130866,"2026-07-27T11:14:27",7,"/ а если я приют сожгу, они успокоятся? ( Идея Немейи, наверно )",112272,null],[130867,"2026-07-27T11:15:23",60,"—А НУ ЦЫЦ!\n\nРявкает альф, хлопая по двери. Не будем думать о том, как воспитывают великанов",130865,null],[130868,"2026-07-27T11:16:22",17,"Дети убегают тут же врассыпную",112272,null],[130869,"2026-07-27T11:17:38",7,"*Немейя раздражённо отворачивается и увидев, как Альф рявкает, говорит спокойным тоном.*\n\n— Кто со мной чтобы лекарей послать сюда? Жрецы помогут с этим разобраться. \n\n*Девушка говорит очень раздражённо. Она обдумывает, кто и почему сделал такие пироги... Кто продал пироги Маргарите...*",112272,null],[130870,"2026-07-27T11:17:58",60,"—Пироги опасны, верю. Тянет. Подсознательно. С этим надо разобраться. Кто их печёт? И где.\n\nУже спокойным тоном говорит Альф, стоя у двери",112272,null],[130871,"2026-07-27T11:18:29",17,"/Историю можно всем если забыли",112272,null],[130872,"2026-07-27T11:18:46",60,"//ну бабку мы видели, видели мельницу",130871,null],[130873,"2026-07-27T11:18:56",60,"//видимо на мельницу нам и надо",112272,null],[130874,"2026-07-27T11:20:26",31,"- на мельнице, вероятно, три карги. Нам нужно что то придумать, в лоб мы их не победим. Нужен хоть какой то план",112272,null],[130875,"2026-07-27T11:21:31",60,"—Ну.. Святая вода как минимум. И побольше. Жреца хотя бы одного для защиты.. Этих мразей я от родных знаю, с ними шутки плохи, но пинка они редко ждут.",130874,null],[130876,"2026-07-27T11:22:07",31,"- у нас есть две бутылки святой воды, у священника Донавича взяли",112272,null],[130877,"2026-07-27T11:22:43",7,"Немейя\n— Угу... Ладно, карга так карга. Идёмте к мельнице?",112272,null],[130878,"2026-07-27T11:24:45",31,"- надо идти незаметно и не нападать на них когда они втроем",112272,null],[130879,"2026-07-27T11:24:54",31,"- в идеале подловить по одной",112272,null],[130880,"2026-07-27T11:25:47",31,"@dunchev мастер, а если я обманку свои вилы в святую воду, они получат бафф на урон против карги? Ну или вообще против нежити?/",112272,null],[130881,"2026-07-27T11:32:58",7,"/ первые пять минут, пока вода не высохнет на вилах xD",130880,null],[130882,"2026-07-27T11:34:20",31,"А больше и не надо, за пять минут кто то из нас точно сдохнет//",130881,null],[130883,"2026-07-27T11:34:29",17,"/Вы пропустите ужин и вероятно репетицию завтра утром. Но можете идти на мельницу. Займёт примерно несколько часов добраться туда.",112272,null],[130884,"2026-07-27T11:35:35",31,"/ну, думаю мой персонаж, хоть и боится, но считает что спасти детей важнее чем тусить у дворянки непонятной/",112272,null],[130885,"2026-07-27T11:36:25",60,"//\"Любая жертва ради цели\".\nОн тоже очень любил детей...",130884,null],[130886,"2026-07-27T11:37:03",17,"/ Тогда решайте. Идёте на мельницу?",112272,null],[130888,"2026-07-27T11:37:24",31,"я за мельницу, но бля, три карги...//",112272,null],[130889,"2026-07-27T11:37:27",60,"//я за",130886,null],[130890,"2026-07-27T11:44:40",9,"//Мы вышли из приюта? Скажете когда, есть у меня пару слов для союзников)",112272,null],[130891,"2026-07-27T11:47:31",7,"/ у меня персонаж сам из приюта, поэтому тоже пойдет",130884,null],[130892,"2026-07-27T11:47:58",7,"/ я за мельницу, но на 2 уровне это самоубийство)",130886,null],[130893,"2026-07-27T11:48:26",17,"/ Да я думаю вы ушли. Обсуждали ужасные вещи не внутри же",130890,null],[130894,"2026-07-27T11:48:42",7,"/ конечно",112272,null],[130895,"2026-07-27T11:52:09",31,"- у меня есть идея. Помните мужика, который за пирог расчитался мешком, где возможно сидел ребёнок? А что если один из нас прикинется таким же продавцом? Принесем мешок, один будет торговаться и отвлекать, а когда карга сункт нос в мешок оттуда ее обольем святой водой и двое нападут из засады. Предлагаю себя на роль мужика с мешком, в мешок спрячем Ридли, а Альф и Немня, как обовладетли сильнейших атак, ударят по карше из засады",112272,null],[130896,"2026-07-27T11:52:40",31,"- Ридли просто может спрятаться в лампу и поместится в мешок",112272,null],[130897,"2026-07-27T11:53:47",31,"- но критично подловить именно одну каргу",112272,null],[130898,"2026-07-27T12:03:59",9,"— Это могут быть не карги. Впервые сталкиваюсь с таким чтобы утверждать наверняка. — *Замолчал на мгновение а после добавил:* — Не расчитывайте на моё суждение, все знания из книг и те не очень внимательно читал.",112272,null],[130899,"2026-07-27T12:08:10",7,"Немейя\n— Звучит безрассудно, мне нравится. Остается лишь ещё дважды это провернуть и тогда может быть мы и не умрём. Идей лучше я не имею, я за. Только где мешки мы добудем под размер Альфа?",130895,null],[130900,"2026-07-27T12:09:08",31,"- не, ты не поняла. В мешке поедет Ридли, вы с Альфой пойдете перелесками, будет прятаться, пока я отвлекаю внимание",130899,null],[130901,"2026-07-27T12:12:02",9,"— От незнакомца мешок никто не примет. В плане есть недочёт. Никто из нас не должен знать и давать мешки с детьми или без, поэтому затея провалится.",112272,null],[130902,"2026-07-27T12:12:56",31,"- Ридли, посмотри на меня. Я, бляха муха, крестьянин, и выгляжу как крестьянин. Ты таки думаешь, что кто то нас различает?",130901,null],[130903,"2026-07-27T12:13:29",31,"- очень сомневаюсь что карга всех в лицо знает, тут земли немалые, вспомни как долго мы шли до города",112272,null],[130908,"2026-07-27T12:17:42",7,"Немейя\n— Путь был немалый... У меня есть очень странная идея, если интересно.",112272,null],[130909,"2026-07-27T12:18:30",31,"- говори",130908,null],[130910,"2026-07-27T12:18:36",9,"— Поджечь поле, а пока его будут тушить вывести из мельницы детей? Думаю без урожая печь пироги не выйдет.",130908,null],[130911,"2026-07-27T12:19:30",31,"- а это ттончо поля их? что если мпы так обречем на голодную смерть целую деревню?",130910,null],[130912,"2026-07-27T12:19:31",9,"//Предлагайте, щас 11 друзей оушена придумают идеальный план",112272,null],[130913,"2026-07-27T12:20:16",9,"— Нужно поспрашивать чьи это поля. — *Пожимает плечами.*",130911,null],[130914,"2026-07-27T12:20:42",7,"Немейя\n— Очень смешно. Я думаю, что магия как то может сохранять пирог, так вот... А что, если через пирог скажем так карга может управлять теми, кто его ел? Может я и специализируюсь в огне, но для магии мало невозможного существует. Поэтому как насчет того, чтобы приманить каргу \" на крючок \"?",130910,null],[130915,"2026-07-27T12:21:36",31,"- можно попробовать наверное",112272,null],[130916,"2026-07-27T12:23:52",9,"*Ридли задумывается, помнит ли он что-то осознаёт ли заклинатель очарованна ли его дерва или нет.*",112272,null],[130917,"2026-07-27T12:24:20",9,"/roll 1d20+1 на удивление он владеет магией, может что-то знает, это на магию",130916,null],[130923,"2026-07-27T13:48:36",17,"/ Я не понял что на магию анализируется. Уточни. Дервы очарованы",130916,null],[130925,"2026-07-27T14:42:45",9,"//Я хочу вспомнить, Ридли читал много хоть и не слишком внимательно. Вот заклинание очарование накладывается, заклинатель понимает сработало оно или нет?",130923,null],[130926,"2026-07-27T14:47:46",17,"/ Да, понимает",130925,null],[130928,"2026-07-27T14:59:01",9,"*Качает головой.*\n\n— Если это магия то они поймут что мы не околдованны.",130915,null],[130930,"2026-07-27T15:07:30",31,"- а если не магия? Если это привязанность, типа как к самогону или табаку, только сильнее?",112272,null],[130931,"2026-07-27T15:07:54",31,"- ты можешь по пирогу определить, есть ли в нем магия?",112272,null],[130932,"2026-07-27T15:10:41",9,"— Я не маг, не вижу есть ли в нем магия. Лучше попросить Немею плсмотреть. — *Не стал мудрить и сказал как есть.* — Но скорее всего есть. Он до сих порсвеж и не испортился. Хоть какая-то магия в нём есть.",112272,null],[130933,"2026-07-27T15:13:24",7,"Немейя\n— Ребята, у меня этот пирог огнем покрывался пока я сама горела, ему хоть бы хны. Я прожигаю что угодно в состоянии том, а пирог не покрыт чем либо. Я вам говорю же, он магический.",112272,null],[130934,"2026-07-27T15:20:15",31,"- что тогда нам делать? Если пойдем в лоб - сами станем начинкой. Наверное пирожки с нами будут подешевле, все таки мясцо уже не такое нежное",112272,null],[130935,"2026-07-27T15:21:30",31,"- кстати, а ведь если говорит об очаровании, я ведь ел пирог. Во мне они могут почуять его след",112272,null],[130941,"2026-07-27T15:34:33",7,"Немейя\n— Ну спасибо, обнадежил и чутка оскорбил. Так вот че ты слюни ронял, когда доставала пирог. И что делать с тобой? Самое рациональное — пойти тебя лечить в церкви.",130934,null],[130946,"2026-07-27T16:18:23",17,"И так вы покидаете Валаки? и хотите пойти к мельнице?",112272,null],[130947,"2026-07-27T16:19:17",7,"/ пока обдумываем план сражения, ибо битва потенциально с 3 каргами — смерть",130946,null],[130948,"2026-07-27T16:19:24",7,"/ а остальные куда то пропали",112272,null],[130949,"2026-07-27T16:19:33",7,"/ @QURTZZ Hard @FSmit7 ???",112272,null],[130950,"2026-07-27T16:24:27",31,"Я тут. Я свой план предложил, его не приняли, жду альтернатив/",112272,null],[130951,"2026-07-27T16:26:49",7,"/ ну у меня альтернатив нет,",112272,null],[130952,"2026-07-27T16:26:57",7,"/ может у кого то есть?",112272,null],[130953,"2026-07-27T16:38:22",31,"Если кто то не хочет идти, то хотя бы обоснуйте, почему персонажу туда не идут, хотя уже почти решили/",112272,null],[130954,"2026-07-27T16:39:49",7,"/ я за твой план ибо шансы есть",112272,null],[130955,"2026-07-27T16:42:10",60,"//я тоже",130954,null],[130956,"2026-07-27T16:42:24",60,"//это пока самое прямое решение",112272,null],[130957,"2026-07-27T16:42:58",31,"Тогда нужно начинать, а то скоро у мастера время закончится",112272,null],[130958,"2026-07-27T16:44:21",7,"/ @dunchev план капкан, мы топ топ их Валахи и действуем по этому плану",130895,null],[130959,"2026-07-27T16:46:56",17,"Выходя из города вас останавливает стража\n\n— Куда собрались?",112272,null],[130960,"2026-07-27T16:49:28",60,"—Защищать народ от некачественного питания, которое производят за пределами Валаки. Работаем.",130959,null],[130961,"2026-07-27T16:49:51",31,"- идём возвращать потерянные улыбки",112272,null],[130962,"2026-07-27T16:51:30",17,"— Праздник солнца через три дня. Возвращайтесь и будьте осторожны.\n\nВас выпускают",112272,null],[130963,"2026-07-27T16:53:01",17,"Вы идёте по старой дороге обратно к мельнице \"Последней надежды\" При вас святая вода. Мешок и хитрый план.\n\nВороны ан протяжении всего пути сопровождают вас и уже ближе к мельнице каркают, подлетают и даже начали тянуть за одежду.",112272,null],[130964,"2026-07-27T16:53:37",31,"- вороны? Нам что то говорили про ворон",112272,null],[130965,"2026-07-27T16:54:39",31,"- вроде мы можем им доверять",112272,null],[130966,"2026-07-27T16:54:50",31,"- у нас один враг",112272,null],[130967,"2026-07-27T16:54:57",31,"- они пытаются нас остановить?",112272,null],[130968,"2026-07-27T16:55:58",7,"*Немейя попрощалась. Она заметно ускорилась, стараясь вырываться вперед от команды. Видно рвение успеть на праздник, а также более позитивное настроение. Когда добрались, девушка смотрела на ворон и ничего не поняла.*\n\n— Вороны какие то... Странные. Нет ощущения предосторожности?\n\n*Говорит она, не используя пламени впервые. Она пытается пока понять, что на ворон нашло.*",112272,null],[130969,"2026-07-27T16:57:31",31,"/roll d20+1 уход за животными. Присаживаюьс на корточки и обращаюсь к вороне:\n\n- нам туда не стоит идти сейчас?",112272,null],[130971,"2026-07-27T16:57:53",17,"Ворона клюёт тебя в глаз.\n\n/1 урона",112272,null],[130972,"2026-07-27T16:58:24",7,"/r d20",130968,null],[130974,"2026-07-27T16:58:46",7,"/ это на анализ или уход за животным, статы одни",112272,null],[130975,"2026-07-27T17:00:04",17,"Вороны судя по предсказанию ваши союзники. Сейчас они пытаются вас удержать и не дать подойти к мельнице.",112272,null],[130976,"2026-07-27T17:00:35",31,"Потираю глаз\n\n- похоже, птички что то знают",112272,null],[130977,"2026-07-27T17:03:55",31,"- я не знаю, кто стоит за птицами, но очевидно этот кто то знает больше нас. Может и правда мы пока не готовы идти туда?",112272,null],[130978,"2026-07-27T17:04:53",7,"*Немейя смотрит на ворон с каким то непонятным взглядом. Непонимание, для чего они это делают не дает покоя. Это не противники, но тогда кто... Так или иначе, предостерегают птицы, будто что то знают.*\n\n— Ребят... Плохо у меня предчувствие. Вороны будто разумны и предостеречь пытаются. Они явно не враги...\n\n*Говорит она, смотря на ворон и пытающаяся понять. Не дрессированны ли они?*\n/ На что кидать? @dunchev",112272,null],[130979,"2026-07-27T17:06:18",17,"/ Кинь природу или уход за животными",112272,null],[130980,"2026-07-27T17:09:20",60,"—Если вы знаете, как нам помочь, то укажите, куда нам идти. \n\nГоворит фирболг птицам, хоть сам их язык не понимает",130975,null],[130981,"2026-07-27T17:10:47",17,"Птицы собираются в стаю и летят на второй этаж мельницы к небольшому окну в двадцати футах от земли. \n\nНесколько ворон стучат крыльями по нему.",112272,null],[130983,"2026-07-27T17:12:00",31,"- мальчик там?",112272,null],[130984,"2026-07-27T17:12:09",17,"— КАААР",112272,null],[130985,"2026-07-27T17:12:13",31,"- у нас есть шанс его вытащить без боя?",112272,null],[130986,"2026-07-27T17:12:35",17,"Молчание",112272,null],[130987,"2026-07-27T17:12:42",60,"—Там точно что-то, что нам нужно. Попробуем в тихую.\n\n//я не написал, но можно тот кусок дерева будет со мной?",112272,null],[130988,"2026-07-27T17:12:50",7,"/r d20",130979,null],[130990,"2026-07-27T17:13:07",17,"Вороны ведут себя странно, обычные так себя не ведут",130988,null],[130991,"2026-07-27T17:13:48",60,"Фирболг отходит в сторонку, вздыхает и отрубает деревянную ладонь, а затем, используя верёвку из своего набора, обвязывает её, собираясь использовать руку как крюк, чтоб закинуть её на окно и залезть так",112272,null],[130992,"2026-07-27T17:14:43",7,"Немейя\n— Может я гляну? Если что вдруг, пока буду падать не смотрите как просто падаю, пожалуйста. \n/ @dunchev я подлетаю на второй этаж",112272,null],[130993,"2026-07-27T17:15:07",60,"//действительно, удобно",130992,null],[130994,"2026-07-27T17:16:33",17,"Ты подлетаешь к окну и в этот момент оно распахивается изнутри и молодая девушка кричит на ворон\n\n— А НУ ПОШЛИ ОТСЮДА! ЧЕГО РАСКАРКАЛИСЬ?!\n\nОна с недоумением смотрит на летающую тифлингшу\n\n— Ой, а вам чего надо?",130992,null],[130995,"2026-07-27T17:16:45",17,"Где то недалеко на стене замер фирборлг",130991,null],[130996,"2026-07-27T17:19:08",7,"Немейя\n— Оу... Здрасьте... У вас пекутся пироги, что манят своим запахом?",130994,null],[130997,"2026-07-27T17:19:09",9,"//Мне сейчас хочется прийти и заявить что мы пришли забирать ребёнка. Мол пришёл Бургомистр в приют и недосчитался ребенка, отправил приключенцев за ним)))",112272,null],[130998,"2026-07-27T17:19:29",17,"— У нас у нас. Только заходите через дверь как все.",130996,null],[130999,"2026-07-27T17:19:46",9,"//Но ладно, эти уже решили штурмовать.",112272,null],[131000,"2026-07-27T17:20:12",7,"Немейя\n— Извините, хотела убедиться, что дома кто то есть. Стучала ранее, никто не открыл. \n/ Спускаюсь вниз",130998,null],[131001,"2026-07-27T17:20:23",7,"/ ребят, чтож, в мешок лезь",130999,null],[131002,"2026-07-27T17:23:39",60,"//а альф наоборот ждет пока снизу пойдет эта женщина открывать, и залезет в дом",131000,null],[131003,"2026-07-27T17:23:42",60,"//через окно",112272,null],[131004,"2026-07-27T17:24:05",9,"//Пару минут и я тут",112272,null],[131005,"2026-07-27T17:24:09",17,"/r +2 Проницательность",112272,null],[131007,"2026-07-27T17:24:31",7,"/r d20 +6 главный пиздабол района",131006,null],[131009,"2026-07-27T17:24:39",7,"/ проебался",112272,null],[131010,"2026-07-27T17:24:39",17,"/ Че вы молодцы собрались когда мне пора с работы уходить",112272,null],[131011,"2026-07-27T17:27:11",7,"/ xd",112272,null],[131012,"2026-07-27T17:30:28",17,"Окна захлопываются, штора перекрывает вид.\n\nНемея спускается ко входу, а Альф остаётся на стене\n\nЧто делают остальные?",112272,null],[131013,"2026-07-27T17:34:36",9,"//Пытаюсь понять что происходит, я не понимаю :D",112272,null],[131014,"2026-07-27T17:36:23",60,"Альф слушает шаги, ближе подбираясь к окну\n\n//оно открывается в какую сторону?",131012,null],[131015,"2026-07-27T17:37:01",31,"*стою в ахуе, думаю:\n\n- весь план по пизде пошел*",112272,null],[131016,"2026-07-27T17:37:41",17,"/Наружу",131014,null],[131017,"2026-07-27T17:37:56",31,"- Ридли, пойдем с Альфом, его пока не заметили вроде",112272,null],[131018,"2026-07-27T17:38:24",60,"//не ну я еще могу там скрытно пройти",131015,null],[131019,"2026-07-27T17:38:28",60,"//в теории",112272,null],[131020,"2026-07-27T17:38:47",9,"*Просто присел у мельницы под полем где-то.*\n\n— Кажется проще дать Немее поджечь крылья мельницы и крышу. Можно их маслом перед этим облить.",131015,null],[131021,"2026-07-27T17:38:55",60,"//я могу незаметно открыть окно, сжав его ладонью посильнее и потянув? Щель точно будет",131016,null],[131022,"2026-07-27T17:39:02",17,"/ Скрытность",112272,null],[131023,"2026-07-27T17:39:17",17,"/ Этот парень СЖИМАЕТ ОКНО\n\nСмотрим",112272,null],[131024,"2026-07-27T17:39:31",31,"- ладно, пока подождем, может что то заметим",131020,null],[131025,"2026-07-27T17:40:01",31,"/roll d20+1 на внимательность, оцениваю обстановку, смотрю есть ли тут предметы что помогут в потенциальной битве или при отходе",112272,null],[131027,"2026-07-27T17:40:04",9,"//Что варвар кричит в скрытности? — \"МЕНЯ НИКТО НЕ ВИДИТ!!!\"",112272,null],[131028,"2026-07-27T17:40:22",31,"//что характерно, все с ним согласны/",131027,null],[131029,"2026-07-27T17:40:26",17,"Ситуация аховая, что делать не понятно",131025,null],[131030,"2026-07-27T17:41:59",31,"Ладно, сидим с Ридли в кустах, хз что делать/",112272,null],[131031,"2026-07-27T17:43:09",17,"Немея у входа и дверь распахивается.\n\n— Да, сестра кричала, что вы хотите купить пирогов? По золотому за штуку. Сколько вам?\n\nЕще одна молодая девушка похожая на ту, что была наверху и открывала окно",131011,null],[131032,"2026-07-27T17:44:19",9,"— Однажды, один из знакомых стражей говорил что на случай нечем заняться он носит с собой колоду карт. Сейчас я понимаю его как никогда.",131030,null],[131033,"2026-07-27T17:46:39",31,"- слушай, а ведь мы сейчас можем остучать в дверь и атаковать ту, что откроет двери, наши союзники уже за ее спиной. Правда, и за их спиной как минимум одна из карг",112272,null],[131034,"2026-07-27T17:47:04",7,"*Немейя расправила крылья, будто подтянулась когда приземлилась. Она поправила волосы, чтобы проще было видно и присматривается на молодую девушку. Она снимает рюкзак и достаёт оттуда пирог.*\n\n— Вот таких... Пять пирожков. Что скажете? Сделаете такие же свежие как и этот?\n\n*Говорит девушка, держа в руках пирог. Она можео сказать, специально показала пирог, дабы взглянуть на реакцию. Она знает, сколько времени этому пирогу...*",131031,null],[131035,"2026-07-27T17:52:21",60,"/roll +3 будет прикол если пройду",131022,null],[131037,"2026-07-27T17:52:25",60,"//ага, да",112272,null],[131038,"2026-07-27T17:52:47",60,"//трачу героическое вдохновение",112272,null],[131040,"2026-07-27T17:52:54",60,"//понятно..",112272,null],[131041,"2026-07-27T17:53:03",9,"//Это моё проклятие двоек, сорян ^^",112272,null],[131042,"2026-07-27T17:55:02",17,"— Уже готовы твои пять пирогов. Давай монетки а я пока схожу за ними.\n\nГрохот и звон стекла раздаётся сверху.\n\nАльф сломал старое ветхое окно и стекла разбились\n\n— ЧТО ЭТО ТАМ! ПРОВЕРЬ, БЕЛЛА!",131034,null],[131043,"2026-07-27T17:57:41",9,"*Видит всё это, толкает в бок Тарха.*\n\n— Возьми запонку и закрепи на воротник, если что я выйду внезапно. — *Ридли даёт запонку Тарху и исчезает во вспышке пламени что затянулось в не сильно примечательное украшение.*",131042,null],[131044,"2026-07-27T17:57:44",17,"/Что делаете?",112272,null],[131045,"2026-07-27T17:58:15",9,"//Охрениваю насколько тупо мы слились 😂👍",131044,null],[131046,"2026-07-27T17:58:33",7,"*Немейя слегка скукожилась о звука разбитого стекла. Однако не предаёт этому вида и просто достаёт свой кошель.*\n\n— Да, конечно...\n/ Заготовить действие подумаю на что. Мы слились xD",131044,null],[131047,"2026-07-27T17:59:12",31,"- поверил ебаным воронам, твою то мать...",112272,null],[131048,"2026-07-27T17:59:24",17,"/Альф ты внутрь лезешь или как?",112272,null],[131049,"2026-07-27T18:01:29",60,"Альф моментально запрыгивает внутрь, тихо ругаясь, и пытается спрятаться хоть где-нибудь. Как только шаги станут очень близки, он моментально растворится в воздухе, словно его здесь и нет",131048,null],[131050,"2026-07-27T18:03:11",17,"/Скрытность",112272,null],[131051,"2026-07-27T18:04:04",60,"/r +3 не подведи меня курва-кубик",112272,null],[131053,"2026-07-27T18:04:11",60,"//ну и славно",112272,null],[131054,"2026-07-27T18:05:16",17,"Ты запрыгнул внутрь чудом не содрав занавеску из старой мешковины.\n\nПеред твоими глазами оказалась машина с огромным прессом. Дробилка. Тут множество ящиков и что то большое накрытое тентом.\n\nТы будто бы играешь в прятки нырнул под тент",112272,null],[131055,"2026-07-27T18:05:21",17,"/r +2 Внимание",112272,null],[131057,"2026-07-27T18:06:09",17,"Ты слышишь шаги девушка прибежала и начала осматривать окно\n\n— Сестра! Сучьи вороны сломали окно!",112272,null],[131058,"2026-07-27T18:06:36",17,"Под тентом клетка в которой спят четыре ребёнка. Они спокойно мирно посапывают.",112272,null],[131059,"2026-07-27T18:07:00",60,"//да, это арба.",112272,null],[131060,"2026-07-27T18:07:08",60,"//я знаю, как применить дробилку",112272,null],[131061,"2026-07-27T18:07:13",17,"Вторая отдаёт Немеи пирожки\n\n— Платите и забирайте.",112272,null],[131062,"2026-07-27T18:08:04",60,"//в оригинале после того, как раскрылось, что в арбе скрытый каннибализм, главная героиня психует и вырезает вообще весь город",112272,null],[131063,"2026-07-27T18:08:23",60,"//тут города нет, лишь три карги.. Сильный варвар.. И дробилка...",112272,null],[131066,"2026-07-27T18:09:03",31,"Что за Арба? Откуда это вообще?/",112272,null],[131067,"2026-07-27T18:12:05",60,"//с книжки одной фанатской... С фоллаута отчасти",131066,null],[131068,"2026-07-27T18:12:30",60,"//но я был прав с самого начала",112272,null],[131069,"2026-07-27T18:14:36",17,"/ Возьми с полки пирожок он так приятно пахнет",112272,null],[131070,"2026-07-27T18:15:01",31,"Думай что с детьми делать, может в окно их, чтобы мы ловили?) хотя зная наши кубы...//",131068,null],[131072,"2026-07-27T18:17:06",60,"//активируем нейроны",131070,null],[131073,"2026-07-27T18:17:29",9,"//Вы где детей увидели?",112272,null],[131074,"2026-07-27T18:17:45",60,"//прямо сейчас тут есть карга, которая в курсе о происходящем, есть варвар, которого она не видит, и дробилка, которую можно включить",112272,null],[131075,"2026-07-27T18:17:45",31,"В клетке сидят, за окном где альф/",131073,null],[131076,"2026-07-27T18:17:58",9,"//Где это написанно?",131075,null],[131077,"2026-07-27T18:18:11",60,"//ТАЩИТЕ ПАДАЛЬ ПО ОДНОЙ, устроим им похороны стоунвинга",131074,null],[131078,"2026-07-27T18:18:18",60,"Hard",131058,null],[131079,"2026-07-27T18:18:25",31,"Под тентом клетка в которой спят четыре ребёнка. Они спокойно мирно посапывают.",112272,null],[131080,"2026-07-27T18:18:43",9,"//Вклбчаешь дробилку, каргу в захват и в дробилку ^^",131074,null],[131081,"2026-07-27T18:20:06",60,"/r d20-1 нейронная активация варвара чтоб понять устройство махины\nd20+3 а это банальная внимательность на поиск кнопки/рычага включения",131054,null],[131083,"2026-07-27T18:20:16",60,"//ооо даааа",112272,null],[131086,"2026-07-27T18:23:40",7,"*Немейя взяла пирожки в руки и отдает деньги. Дышит редко, чтобы запах не манил все сожрать и в принципе касаться этого лишний раз. Она кивает и спокойно идёт от двери... Однако она ожидает момента, пока та девушка не отвернётся, чтобы после выждать момент и взлететь вверх.*\n\n\" Осталось момент выждать. Что остальные придумали, интересно... Также что внутри, еще интереснее. \"",131061,null],[131087,"2026-07-27T18:24:09",7,"/ жду пока иду, чтобы от двери отошла та девушка или закрыла ее, дабы в окно к Варвару полететь",112272,null],[131089,"2026-07-27T18:25:39",31,"*вижу выходящую из дверей Немею и ее раскрывающиеся крылья. Понимаю что она хочет взлететь в то же окно. Думаю, надо будет постучать в дверь после этого, чтобы хотя бы одну из карг отвлечь разговором*",112272,null],[131092,"2026-07-27T18:29:01",9,"//Надеюсь моя запонка на всякий случай у тебя на шивороте, и я в ней",131089,null],[131093,"2026-07-27T18:29:09",31,"Да/",131092,null],[131094,"2026-07-27T18:29:43",9,"//Чтош, надеюсь стразовать не прийдётся, мы с тобой вместе как 0,5 землекопа в уравнении",131093,null],[131095,"2026-07-27T18:30:30",31,"Я продумываю образ пирогового нарика, который будет умолять о дозе)/",131094,null],[131260,"2026-07-27T21:13:51",17,"Девушка закрыла дверь.",112272,null],[131296,"2026-07-28T04:42:50",31,"Дождавшись взлета Немеи, и выждав для верности еще минутку, выдвигаюсь к двери и начинаю неуверенно стучать, одновременно наложив на себя вид страдающего от ломки человека",112272,null],[131300,"2026-07-28T08:09:08",17,"Дверь снова открывается, миловидная девушка на пороге\n\n— ЧТо хотели молодой человек?",112272,null],[131302,"2026-07-28T08:13:45",31,"*я прерывисто дышу, глаза бегают, стараюсь их даже не поднимать, говорю с жаром, с мольбой и словно через силу*\n\n- мне..., мне бы, это... Пи... Пироог...",112272,null],[131304,"2026-07-28T08:14:54",17,"— Ой, как глазки забегали. Даненько не кушал наших пирожков парень?",112272,null],[131305,"2026-07-28T08:14:58",17,"/Выступление или обман",112272,null],[131306,"2026-07-28T08:15:35",31,"/roll d20-1",112272,null],[131309,"2026-07-28T08:16:00",31,"- дддавно, госпожа, слишком давно",112272,null],[131312,"2026-07-28T08:16:43",31,"- жена говорит, брось это, детям жрать нечего, а ты тут душу травишь",112272,null],[131313,"2026-07-28T08:17:02",31,"- а я не могу уже без того...",112272,null],[131317,"2026-07-28T08:19:28",17,"— А детишкам чтоже и жене ни кусочка не давал пирожка?",112272,null],[131318,"2026-07-28T08:19:37",17,"— Всё в одну харю хамячишь?",112272,null],[131319,"2026-07-28T08:20:51",31,"*про себя думаю о всякой мерзости в жизни, чтобы на лице гнев проступил*\n\n- нет! Это мое!",112272,null],[131320,"2026-07-28T08:22:17",17,"— Ой ой, полегче. Сколько тебе пирогов? По золотому за штуку, у тебя монеты то есть?",112272,null],[131325,"2026-07-28T08:27:00",31,"*опускаю глаза, типа от стыда*\n\n- нету. Откуда деньги то у нас, граф ведь все сто можно и нельзя забирает...\n\n*испугано оглядываюсь, типа зря я это сказал*\n\n- ой, ну то естт это самое, я про то что ч отработать могу, я много че умею",112272,null],[131328,"2026-07-28T08:28:49",17,"— Не. Ты вижу мужик крепкий, работу найти сможешь. Но говоришь дети у тебя... Если дитятку приведёшь к нам на помощь в мельнице, могу предложить тебе по пирогу в неделю. На всю оставшуюся жизнь! \n\nОна улыбается\n\n— А ребетёнка мы тут обучим работать, помогать. Накормим, оденем. Теплом добрым согреем.\n\n— ЧТо скажешь?",112272,null],[131333,"2026-07-28T08:33:11",60,"//а я в это время пытаюсь врубить дробилку тихонько",112272,null],[131335,"2026-07-28T08:34:22",17,"Ничего нет. Ты не понимаешь как включить дробилку. Кажется она вообще сломана.",131081,null],[131336,"2026-07-28T08:34:50",60,"//может её можно вручную крутить?",131335,null],[131337,"2026-07-28T08:35:08",17,"/ Ага велосипедо цепная тяга",112272,null],[131338,"2026-07-28T08:35:15",17,"/ Садись крути педали",112272,null],[131339,"2026-07-28T08:35:27",60,"//ща понять бы, шутка ли это..",112272,null],[131340,"2026-07-28T08:35:50",17,"Какой то скрытый рычаг которого ты не нашел пока что",112272,null],[131341,"2026-07-28T08:35:52",31,"- это как же, ребёнка отдать? А что он тут делать то будет? Зерно что ли дробить? Так на то сил не хватит же, у меня даже старшему всего 7...",112272,null],[131342,"2026-07-28T08:36:15",60,"//если могу кинуть еще, пока там отвлекают, то кину",131340,null],[131344,"2026-07-28T08:36:35",17,"— С зерном мы и сами справимся. По дому помогать, готовить пироги. Для этого твоих мышц не надобно нам, а у дитя рот поменьше кормить попроще, чем тебя амбала",131341,null],[131345,"2026-07-28T08:36:37",31,"/там немея к тебе должна прийти, может помочь/",131342,null],[131346,"2026-07-28T08:36:45",17,"/Скрытность, а потом повтори",131342,null],[131347,"2026-07-28T08:37:00",60,"/roll +3 о Господи",131346,null],[131349,"2026-07-28T08:37:23",17,"Находишь рычаг в углублении машины",112272,null],[131350,"2026-07-28T08:37:46",60,"//тогда ждём немею и можно начинать",131349,null],[131352,"2026-07-28T08:39:31",31,"- а как же вы вообще без мужиков то? Сами мешки таскаете с зерном? Вы же хрупкая такая...\n\n*подкатываю яйца типа*",112272,null],[131357,"2026-07-28T08:46:16",17,"— Откуда тебе знать есть у нас мужики, нет у нас мужиков? Мы дамы завидные, за нами вереница водится. И каждый готов слюни пускать и мешки таскать. Так что пошел бы ты со своими вопросами. Денег нет, нет пирогов. Если надумаешь дитятку привести, условия в силе. Не боись будет жить как у бога за пазухой. Сытым, одетым, при деле. Всё, думай мужик!\n\nОна захлопывает дверь перед твоим лицом",131352,null],[131358,"2026-07-28T08:48:42",31,"*мысли в голове*\n\n- да Тарх, правильно тебе говорили, не умеешь ты с бабами говорить. Может, побриться хоть?\n\nОтхожу за кусты, чтобы меня не видели, надеюсь, я дал достаточно времени товарищам",112272,null],[131359,"2026-07-28T08:49:28",17,"/ Помощник)))",112272,null],[131360,"2026-07-28T08:49:35",31,"/обожду с полчаса, и если ничего не изменится, вернусь с мешком, скажу что принес ребёнка, а в мешке он потом что сам не хотел идти и жена против была, пришлось по башке ей дать/",112272,null],[131361,"2026-07-28T08:49:43",17,"/Иди ход сделай за Себу",112272,null],[131424,"2026-07-28T10:00:52",31,"Тут кого ждем?/",112272,null],[131425,"2026-07-28T10:02:20",17,"/@Evreiskui_Department",112272,null],[131489,"2026-07-28T11:54:13",7,"/ доброго утра",131425,null],[131490,"2026-07-28T11:55:25",7,"/ тэкс",112272,null],[131492,"2026-07-28T11:58:17",7,"*Немейя выждав момент, расправляет крылья. Она взлетает вверх и увидев грубияна Альфа, она с неохотой подлетает и полушёпотом говорит*\n\n— Эй, долго ты будешь прятаться под тентом?",131336,null],[131493,"2026-07-28T11:58:33",7,"/ будем устраивать наверно пожарчик",112272,null],[131494,"2026-07-28T11:58:41",60,"//я под тентом прячусь",131492,null],[131495,"2026-07-28T12:00:33",7,"/ окак ща",131494,null],[131496,"2026-07-28T12:04:07",17,"/Скрытность Немеи",112272,null],[131497,"2026-07-28T12:07:57",7,"/r d20 +4 летс гоу гемблинг",112272,null],[131499,"2026-07-28T12:08:33",31,"/ща Альф тебя с каргой перепутает и в дробилку сунет(",112272,null],[131500,"2026-07-28T12:10:33",17,"Ты пролезая через небольшое разбитое окно задеваешь крыльями и шумишь\n\n— ДА ЧТО ТАМ ОПЯТЬ!",112272,null],[131501,"2026-07-28T12:10:39",17,"/Прячся",112272,null],[131502,"2026-07-28T12:10:46",17,"/Или готовся",112272,null],[131503,"2026-07-28T12:11:00",17,"Ты слышишь шаги по лестнице",112272,null],[131504,"2026-07-28T12:13:43",7,"/r d20 +4",131500,null],[131506,"2026-07-28T12:14:14",17,"/r +2 Внимание",112272,null],[131508,"2026-07-28T12:15:23",60,"Альф слегка показывается немейе из-под тента, указывая на рычаг и беззвучно, чисто губами произнося\n\n\"Я хватаю её, ты включаешь\"",112272,null],[131509,"2026-07-28T12:16:19",17,"Поднимается красивая девушка и смотрит вокруг.\n\n— Да кто тут шумит, проснулись чтоле? Не могли же они...\n\nОна идёт к Альфу там где под тентом спят дети в клетке",112272,null],[131510,"2026-07-28T12:16:53",7,"/ каво включай, не ясна",131508,null],[131511,"2026-07-28T12:17:45",60,"//огромная дробилка",131510,null],[131512,"2026-07-28T12:18:23",60,"//я не знаю, является ли девушка каргой...",131509,null],[131513,"2026-07-28T12:18:32",7,"*Увидев и еле разобрав что Альф сказал, Немейя осматривается. Она увидела огромную дробилку и рычаг, после чего будто уже поняла примерный план. Она кивает одобрительно и кажется уже готова творить... Добро :)*",112272,null],[131514,"2026-07-28T12:18:47",7,"/ ну знаешь ли\nНекоторые становятся каргами",131512,null],[131515,"2026-07-28T12:19:00",7,"/ иллюзии никто еще не отменял",112272,null],[131518,"2026-07-28T12:20:20",60,"Альф сворачивается в клубок и использует маскировку, создавая неприметный образ очередного ящика. На самом деле он маскируется под тортла, но панцирь очень похож на ещё один кусок дерева",131509,null],[131538,"2026-07-28T13:20:41",7,"/ я жду когда схватишь, чтобы дернуть рычаг если что",112272,null],[131540,"2026-07-28T13:21:12",60,"//уверен, она еще разгоняться будет",131538,null],[131541,"2026-07-28T13:21:16",17,"/Ну она идёт прямо к тебе. Маскировка делает тебя невидимым?",131518,null],[131544,"2026-07-28T13:22:19",7,"/ я как понял, он стал тортлом, что притворяется коробкой",112272,null],[131545,"2026-07-28T13:22:30",17,"/Скрытность)",112272,null],[131547,"2026-07-28T13:24:17",7,"/ киньте скрытность",131540,null],[131552,"2026-07-28T13:28:08",60,"/r +3 черепашки-ниндзя",131545,null],[131560,"2026-07-28T13:49:52",17,"Она поднимает тент и осматривает детей\n\n— А это кто тут у нас спрятался?! СЕСТРАААА!",112272,null],[131562,"2026-07-28T13:50:08",17,"/ что делаете?",112272,null],[131563,"2026-07-28T13:51:14",60,"//впадаю в ярость и хватаю курву",131562,null],[131564,"2026-07-28T13:51:28",17,"/Инициатива",112272,null],[131565,"2026-07-28T13:51:34",60,"//надеюсь немейя среагирует и врубит дробилку",112272,null],[131566,"2026-07-28T13:51:40",60,"/r +1 иня",112272,null],[131568,"2026-07-28T13:51:57",17,"/r +2 Оливия. +2 Белла",112272,null],[131570,"2026-07-28T13:52:09",31,"Сейчас херак и у карги иммунитет к дробящему урону/",112272,null],[131574,"2026-07-28T13:55:51",60,"//у мобов бестиария есть иммунитет к физ урону только от атак. Дробилка — не атака",131570,null],[131577,"2026-07-28T13:57:18",17,"Прямо перед тобой девушка меняется её руки удлиняются а кожа приобретает волыри и зеленый оттенок, нос вытягивается\n\nЭто карга",112272,null],[131578,"2026-07-28T13:57:51",17,"Оливия",112272,null],[131579,"2026-07-28T13:59:12",60,"//вот теперь не перепутаю",112272,null],[131581,"2026-07-28T14:02:28",7,"/r d20 +2",112272,null],[131584,"2026-07-28T14:02:47",7,"/ извиняюсь за задержку",112272,null],[131585,"2026-07-28T14:03:57",17,"Мамочка 49\nБелла 38\nТарх \nНемея\nОливия\nАльф\nРидли???",112272,null],[131586,"2026-07-28T14:04:53",31,"/roll d20+1",112272,null],[131588,"2026-07-28T14:08:20",31,"Ридли принял образ запонки и висит у меня на одежде. Я хз как его инициативу считать. Видимо, ему придется ее кидать позже, когда я дойду. А пока он в засаде/",112272,null],[131589,"2026-07-28T14:11:28",17,"Тарх слышит как с грохотом внутри мельницы началась возня",112272,null],[131590,"2026-07-28T14:11:46",17,"Белла бежит к сестре с нижнего этажа на помощь",112272,null],[131592,"2026-07-28T14:12:05",17,"/Ход",112272,null],[131594,"2026-07-28T14:12:46",60,"//Ридли внутри всё слышит, если что",112272,null],[131595,"2026-07-28T14:12:52",60,"//это особенность сосуда",112272,null],[131597,"2026-07-28T14:15:42",31,"- все пошло не по плану. Как всегда\n\nДостаю сосуд со святой водой, обливаю зубцы вил и несусь к двери, выбивая ее",112272,null],[131598,"2026-07-28T14:16:07",31,"Атлетику на выбивание двери, или не заперто?/",112272,null],[131599,"2026-07-28T14:16:58",31,"/roll d20 атлетика если нужна",112272,null],[131601,"2026-07-28T14:17:51",31,"Если не выбил, то ору:\n\n-хозяйка, я с мальцом, вернулся за пирогом",112272,null],[131603,"2026-07-28T14:18:01",31,"Ход наверное/",112272,null],[131605,"2026-07-28T14:19:17",31,"Надежда на то что она откроет и попытается взять ребёнка в заложники))//",131601,null],[131607,"2026-07-28T14:27:59",17,"Ты выбил дверь, она гнилая, но повредил ногу о ржавые гвозди, которыми она была сколочена\n\n/1 урона",112272,null],[131608,"2026-07-28T14:28:11",17,"На первом этаже ты никого не видишь",112272,null],[131609,"2026-07-28T14:28:26",31,"Оглядываюсь, может есть что то полезное в бою",112272,null],[131610,"2026-07-28T14:29:07",31,"/может у них на стене висит ментальная карта с надписью особо уязвимые места карг*",112272,null],[131611,"2026-07-28T14:30:14",31,"Hard подключайся, умирать будем/",112272,null],[131612,"2026-07-28T14:31:19",9,"/roll 1d20 иня я ирл готовлю конечно но тпк пропустить не интересно",112272,null],[131614,"2026-07-28T14:31:40",17,"Пироги на столе, вот бы кусочек",131609,null],[131615,"2026-07-28T14:36:02",31,"Игнорирую и бегу к лестнице. Думаю движения не хватит подняться\n\nХод/",131614,null],[131616,"2026-07-28T14:36:49",17,"Чуть впереди ты видишь что по лестнице только что поднялась зеленокожая Карга\n\nона Оборачивается на тебя\n\n— Мужик! Ну куда же ты вломился, осёл?!",112272,null],[131617,"2026-07-28T14:40:01",31,"- так яж за пирогами",112272,null],[131618,"2026-07-28T14:40:36",17,"— Вот балван, теперь придётся делать каравай из тебя...",112272,null],[131619,"2026-07-28T14:41:28",31,"- я невкусный",112272,null],[131621,"2026-07-28T14:46:28",17,"/@Evreiskui_Department",112272,null],[131622,"2026-07-28T14:53:59",7,"/ извиняюсь",112272,null],[131623,"2026-07-28T14:55:53",7,"/ действие тратить надо чтобы рычаг дёрнуть?",131621,null],[131624,"2026-07-28T14:56:36",17,"/Не",112272,null],[131625,"2026-07-28T14:56:58",7,"/ бонусное :)",112272,null],[131626,"2026-07-28T15:00:53",7,"*Немейя мгновенно взлетает. Она подлетает внутрь второго этажа и к рычагу, за который собственно и дёргает. После она с улыбкой на лице не долго думая, швыряет огненный снаряд прям в лицо карги.*\n\n— Могли бы пироги хоть правдоподобнее стряпать, а не гниющую хрень!",112272,null],[131627,"2026-07-28T15:00:59",7,"/r d20 +6",112272,null],[131629,"2026-07-28T15:01:06",7,"/ мима",131628,null],[131630,"2026-07-28T15:01:29",7,"/ конец хода, рычаг дернул действие просрал ход @dunchev оливки",112272,null],[131631,"2026-07-28T15:02:42",9,"//Идеально, нам конец ^^",112272,null],[131632,"2026-07-28T15:03:52",31,"Мастер не даст нам умереть!/",131631,null],[131633,"2026-07-28T15:05:42",9,"//Думаб мастер, он забил хрен на наши способки и возможности ещё с самого начала. Пох наколько ты сильнее или слабее, тут карги. Или с ними справляемся, или не справляемся и всё 😏👌",131632,null],[131634,"2026-07-28T15:07:21",9,"//Я так веду, самое честное это не подстраиваться под игроков и не подкручивать кубы. Хотя мб нам и не дадут помереть, посмотрим. Надеюсь хотя бы у карг есть страх, а то спас и так маленький, всего 11.",112272,null],[131635,"2026-07-28T15:08:16",9,"//Не расчитывай на д-ма, старайся не помереть сам)",131632,null],[131636,"2026-07-28T15:08:47",41,"( погружайтесь, не играйте",112272,null],[131637,"2026-07-28T15:09:45",7,"/ всмысле?:_",131636,null],[131638,"2026-07-28T15:10:06",41,"( это Харду",131637,null],[131639,"2026-07-28T15:10:20",41,"( который метагейм разводит",112272,null],[131640,"2026-07-28T15:10:39",9,"//Да я хочу играть а не ждать д-ма)",112272,null],[131641,"2026-07-28T15:11:10",17,"Ты дёрнула рычаг и старая костедробилка завелась с утробным рёвом\n\nШестерёнки загрутились внутри остатки чего то домололись с треском костей. \n\nСверху начал ударять огромный молот.\n\nБУМ\n\nБУМ\n\nБУМ",131630,null],[131642,"2026-07-28T15:11:16",9,"//Типа, ждать помощи потому что перс слаб — наивно как по мне 😏👌",112272,null],[131643,"2026-07-28T15:12:27",17,"Как только Оливия перевоплотилась в ужасную каргу, Альф и Немея лицезреют её и кровь стынет в жилах.\n\n/ Спас Мудрости СЛ11",112272,null],[131645,"2026-07-28T15:12:50",7,"/r d20 +0",112272,null],[131647,"2026-07-28T15:13:04",7,"/ Буква Ю\nИди в дробилку",131646,null],[131648,"2026-07-28T15:13:07",17,"Тебя не пугает её ужасная аура",112272,null],[131649,"2026-07-28T15:13:40",7,"Немейя\n— Вот уж кому магия для красоты жизненно необходима уж точно.",131643,null],[131650,"2026-07-28T15:17:37",7,"/ @FSmit7 спас мудрости сл 11 кинь",112272,null],[131651,"2026-07-28T15:18:48",17,"/ Щас я пиздану вашего танка",112272,null],[131652,"2026-07-28T15:18:51",17,"/ А дальше уже легко",112272,null],[131653,"2026-07-28T15:19:08",17,"/ Помним\n\nСмертельный взгляд. Карга нацеливается на одно испуганное существо, которое видит в пределах 30 футов от себя. Если цель видит каргу, она должна преуспеть в спасброске Мудрости Сл 11 от этой магии, иначе её хиты опускаются до 0.",112272,null],[131654,"2026-07-28T15:20:54",7,"/ — Насколько вам надоели ваши игроки?\n— Да\n— В смысле надоели? \n— Да\n— И что делать будете?\n— Да",112272,null],[131655,"2026-07-28T15:23:27",60,"/roll d20+1 вот сюда надо было вдохновение оставить",131643,null],[131657,"2026-07-28T15:23:42",17,"Ты тоже не испугался(",112272,null],[131659,"2026-07-28T15:24:13",60,"//я испугался, а альф не очень",112272,null],[131660,"2026-07-28T15:24:30",31,"Как из может напугать какая то то карга, если они видели как обыватели вампира кровью добровольно поят/",112272,null],[131661,"2026-07-28T15:27:31",60,"//мне ходить?",131643,null],[131662,"2026-07-28T15:27:52",60,"//или у карги есть ещё козыри?",112272,null],[131663,"2026-07-28T15:28:22",17,"/r +5 Когти карги",112272,null],[131665,"2026-07-28T15:28:46",17,"Она вонзает тебе все пять когтей в живот и прокручивает\n\n— Щас посмотрим какого цвета у тебя кровь, чудоюдо",112272,null],[131666,"2026-07-28T15:28:53",17,"/r 2d6+3 рубящий",112272,null],[131668,"2026-07-28T15:32:00",60,"Альф 24/29",112272,null],[131670,"2026-07-28T15:33:42",60,"//или уже считается, что я в ярости? Вроде написал, что впадаю в ярость, и сказали кидать иню",112272,null],[131671,"2026-07-28T15:33:47",60,"//пофиг, пусть так",112272,null],[131672,"2026-07-28T15:34:52",17,"/В ярости",112272,null],[131673,"2026-07-28T15:35:00",17,"/Ходи",112272,null],[131674,"2026-07-28T15:36:08",60,"—А! Сука!\n\nИстошно орёт тортл, хватая каргу за руки, пока за его спиной сияет клинок\n\n—ЩА Я ПОКАЖУ ТЕБЕ КАК ПЕЧЬ КОВРИЖКИ ИЗ ДЕТИШЕК!",112272,null],[131675,"2026-07-28T15:36:25",60,"//че там, проверка атлетики/акробатики",112272,null],[131676,"2026-07-28T15:36:45",60,"/roll +d20+5 это не просто гнев",112272,null],[131678,"2026-07-28T15:37:03",17,"/r +4 Атлетика",112272,null],[131680,"2026-07-28T15:37:09",17,"Схватил",112272,null],[131682,"2026-07-28T15:38:57",60,"Безэмоциональная иллюзия лица черепахи поворачивается в сторону пыхтящей дробилки. Тяжелыми шагами альф тянет каргу за собой, каждым своим движением сближая её с последствиями собственных выборов. Добравшись до этой самой дробилки, он с силой пихает каргу внутрь",112272,null],[131683,"2026-07-28T15:40:06",60,"//механически я могу двигать её как угодно, расходуя скорость, поэтому сейчас похрустим",112272,null],[131684,"2026-07-28T15:40:08",17,"— ААРКХХХ НУКА ПОСТАВЬ МЕНЯ, СУКА, СУКА, СУКА",112272,null],[131686,"2026-07-28T15:41:18",60,"—У МЕНЯ ЕСТЬ ЗНАКОМОЕ ДЕРЕВО, ПОД КОТОРОЕ Я ЗАКОПАЮ ТВОИ ОШМЁТКИ!\n\nГоворит варвар, делает глубокий вдох и повторяет одну из сцен \"зайчика\"",131684,null],[131689,"2026-07-28T15:45:10",9,"//Кстати, она ешё ниче такая по сравнению с ведьмами из ведьмака 😂👍",131591,null],[131695,"2026-07-28T15:49:49",17,"— НЕЕЕЕАААААААА \n\nКХРКХРКХР\n\nВедьму затягивает в костедробилку ужасные чавкающие звуки молота прекращают её ор.\n\nКостедробилку заклинило, но это ведьме уже не поможет",112272,null],[131696,"2026-07-28T15:49:54",17,"— СЕСТРААААААААААААААААААА!?",112272,null],[131697,"2026-07-28T15:50:52",41,"( пиздец",112272,null],[131698,"2026-07-28T15:52:07",17,"/Ридли ход",112272,null],[131699,"2026-07-28T15:52:12",7,"/ чиназес",131695,null],[131700,"2026-07-28T15:52:33",31,"Начинка для нового пирога/",131699,null],[131701,"2026-07-28T15:52:57",60,"Взгляд альфа переносится на вторую каргу. Холодный, жутковатый. А затем он исчезает прямо в воздухе\n\n//Бонуской инвиз, свободным действием закрываю глаза, чтоб не смотреть на неё",131695,null],[131702,"2026-07-28T15:53:09",31,"Ридли в виде запонки на моей одежде, мы внизу лестницы на первом этаже, над нами Белла//",112272,null],[131703,"2026-07-28T15:53:16",60,"//всё, сходил",131701,null],[131704,"2026-07-28T15:54:06",31,"Hard подключайся",112272,null],[131705,"2026-07-28T15:59:36",9,"//Что я вижу хоть",112272,null],[131706,"2026-07-28T16:00:59",9,"//Понимаю ли что у нас замес?",112272,null],[131707,"2026-07-28T16:01:13",9,"//На Тарха щас нападут?",112272,null],[131708,"2026-07-28T16:01:51",17,"/Видишь Тарха внизу лестницы. И наверху Девушку, она еще не превратилась",112272,null],[131709,"2026-07-28T16:02:11",9,"//Шум сверху слышу?",112272,null],[131710,"2026-07-28T16:02:26",17,"/ Да, очень близко, всё слышишь",112272,null],[131711,"2026-07-28T16:02:48",9,"/roll 1d10 временных хитов бонусным вхожу в ужасный облик",112272,null],[131713,"2026-07-28T16:04:16",9,"*Ридли готовится вылезти, он понимает что прийдётся сражаться, но сейчас... выжидает...*\n\n//Ход пока что, остабсь внутри сосуда",112272,null],[131714,"2026-07-28T16:04:54",31,"Ша она нас двоих когтями проткнет, разом, комбо фаталити/",112272,null],[131715,"2026-07-28T16:05:45",9,"//Та пох, разобьет сосуд перед ней из вспышки огня материалищуется страшная фиговина в маске на которой нарисованна улыбка. Ещё и по сосуду попасть надо 😏👌",112272,null],[131716,"2026-07-28T16:06:09",7,"/ вылечу обоих",131714,null],[131717,"2026-07-28T16:06:30",17,"Женщина оборачивается ужасной каргой\n\n/Спас мудрости от всех кроме Альфа он закрыл глаза СЛ11",112272,null],[131719,"2026-07-28T16:06:38",17,"/И Ридли не надо",112272,null],[131720,"2026-07-28T16:06:50",9,"//Я виду всё изнутри",112272,null],[131721,"2026-07-28T16:07:02",17,"/Ну кинь",112272,null],[131722,"2026-07-28T16:07:04",9,"//Так что скорей всего надо?",112272,null],[131723,"2026-07-28T16:07:06",31,"/roll d20",112272,null],[131725,"2026-07-28T16:07:12",9,"/roll 1d20 мудрость",112272,null],[131727,"2026-07-28T16:07:16",31,"Мне пизда/",112272,null],[131728,"2026-07-28T16:07:32",17,"Тарх сильно испуган внешним видом этой карги",131723,null],[131729,"2026-07-28T16:07:47",9,"//Ты просто в 0 упал, по моему в этом случае даж спасы кидать не надо? Но хз",112272,null],[131730,"2026-07-28T16:08:00",31,"- ебать ты страшная, умереть можно",131728,null],[131731,"2026-07-28T16:08:11",17,"Тарх она указывает на тебя кривым пальцем\n\n— Я ЧУЮ ТВОЙ СТРАХ! АХАХАХ ЦИПЛЁНОЧЕК! ТЫ МОЙ!",112272,null],[131732,"2026-07-28T16:08:48",31,"/ссу под себя свободным действием, спас ловкости ей если решит подойти, чтобы не подскользнутся/",112272,null],[131733,"2026-07-28T16:09:27",9,"//а, она сама должна это сделать",131653,null],[131734,"2026-07-28T16:09:40",7,"/ Ридли который находится под иммунос к страху такой: 😎👈",112272,null],[131735,"2026-07-28T16:10:04",9,"//А, тот облик даёт имун? Перечитаю как нить",112272,null],[131736,"2026-07-28T16:11:31",17,"/ Спас Мудрости СЛ 11 Тарх",112272,null],[131737,"2026-07-28T16:11:46",17,"/ Она испугала тебя при превращении и только сейчас может тебя в 0 положить",112272,null],[131738,"2026-07-28T16:13:15",31,"/roll d20",131736,null],[131740,"2026-07-28T16:13:35",31,"- я примсотрелся, не такая ты и страшная. Пойдем на свидание?",112272,null],[131741,"2026-07-28T16:13:51",17,"— КАААК?! ТЫ ДОЛЖЕН СДОХНУТЬ, СДОХНУТЬ, СДОХНУТЬ!",112272,null],[131742,"2026-07-28T16:14:38",31,"Мой ход?/",112272,null],[131743,"2026-07-28T16:16:19",31,"- давно уже был должен, сам в шоке",112272,null],[131744,"2026-07-28T16:16:36",31,"/roll d20+1 бью ее вилами",112272,null],[131746,"2026-07-28T16:16:47",31,"/roll d6+1",112272,null],[131748,"2026-07-28T16:17:09",31,"/roll d20+1 бонусом бью древком вил",112272,null],[131750,"2026-07-28T16:17:18",31,"/roll d4+1",112272,null],[131752,"2026-07-28T16:17:45",31,"А, еще же вилы были смочены святой водой, сколько на урон от нее кинуть?/",112272,null],[131753,"2026-07-28T16:18:05",7,"/ а ты колдуна нежить перечитай",131735,null],[131754,"2026-07-28T16:18:55",31,"/roll 2d6 от святой воды, я погуглил урон",112272,null],[131756,"2026-07-28T16:19:24",31,"Короче, 4 колющего, 4 дробящего и 9 лучистого от святой воды",112272,null],[131757,"2026-07-28T16:19:54",9,"//Вродь испуг даёт помеху на попадание 🤔",112272,null],[131758,"2026-07-28T16:20:05",31,"Так я же прошёл спас/",131757,null],[131759,"2026-07-28T16:20:20",60,"От смерти прошел",131758,null],[131760,"2026-07-28T16:20:23",7,"/ помеха на попадание, ты не подходишь к цели которую видишь",131757,null],[131761,"2026-07-28T16:20:25",31,"Ну придет мастер, скажет, перекину",112272,null],[131762,"2026-07-28T16:20:31",60,"А от испуга нет",131759,null],[131763,"2026-07-28T16:20:55",31,"@dunchev прочитай, скажи если нужно перекинуть/",112272,null],[131764,"2026-07-28T16:22:09",17,"/ ты вообще не можешь приблизится к ней))",112272,null],[131765,"2026-07-28T16:22:40",31,"Ну бля, а так красиво все попал(((",112272,null],[131766,"2026-07-28T16:22:41",17,"/ Ты испуган ей",112272,null],[131767,"2026-07-28T16:22:57",17,"/ Кинь д20 удача",112272,null],[131768,"2026-07-28T16:23:06",31,"/d20",112272,null],[131769,"2026-07-28T16:23:13",31,"/roll d20",112272,null],[131771,"2026-07-28T16:23:46",31,"Приблизится не могу, а вторую склбну со святой водой могу швырнуть?/",112272,null],[131772,"2026-07-28T16:23:53",17,"Ты пытался не бояться её, даже подбадривал себя шуткой, но тело не обманешь, колени дрожат вилы в руках ходят ходуном",112272,null],[131773,"2026-07-28T16:23:57",17,"/Можешь кинуть вилы",112272,null],[131774,"2026-07-28T16:24:00",17,"/В неё",112272,null],[131775,"2026-07-28T16:24:09",17,"/Возьмём попадание",112272,null],[131776,"2026-07-28T16:24:26",17,"/ Два броска было считай с помехой уже кинул 2д20",112272,null],[131777,"2026-07-28T16:24:46",31,"Ну хер с ним, кинул вилы, попал",112272,null],[131778,"2026-07-28T16:24:57",31,"4 колющего и 9 лучистого",112272,null],[131779,"2026-07-28T16:25:08",31,"В руках остался только серп",112272,null],[131780,"2026-07-28T16:25:13",31,"Ход/",112272,null],[131781,"2026-07-28T16:25:26",17,"/ @Evreiskui_Department",112272,null],[131783,"2026-07-28T16:28:58",7,"/ тэкс... У нас же была одна карга и она в фарш превратилась же?",112272,null],[131784,"2026-07-28T16:29:22",7,"/ вторая на первом этаже и явно слышно особенно \" Ебать ты страшная \" отчётливо",112272,null],[131785,"2026-07-28T16:30:46",17,"/ Вторая тоже на втором этаже недалеко от тебя",112272,null],[131786,"2026-07-28T16:30:52",17,"/ Ты спас кидал от страха?",112272,null],[131787,"2026-07-28T16:30:55",17,"/Второй раз",112272,null],[131788,"2026-07-28T16:32:24",7,"/ вроде нет",131787,null],[131789,"2026-07-28T16:32:27",7,"/ ща кину",112272,null],[131790,"2026-07-28T16:32:32",7,"/r d20 БУ",112272,null],[131792,"2026-07-28T16:32:50",17,"В тебя вселяется первобытный страх перед этой каргой",112272,null],[131793,"2026-07-28T16:33:04",17,"/Альф Умни, он глаза закрыл",112272,null],[131794,"2026-07-28T16:33:15",17,"/ Но получил статус слепой ибо, если откроет будет проходить спас",112272,null],[131795,"2026-07-28T16:33:39",7,"/ я и сходить не успел не думала что они без макияжа настолько страшны",131793,null],[131796,"2026-07-28T16:35:12",60,"//8 интеллекта рулят",131793,null],[131797,"2026-07-28T16:35:22",60,"//он закрыл глаза и теперь его не видно",112272,null],[131798,"2026-07-28T16:36:29",60,"//лучше помеха на атаки, чем помеха атаки, невозможность подойти и ваншот",112272,null],[131799,"2026-07-28T16:40:31",7,"/ ну я могу щас закрыть в свой ход глазки и подумал подумал",131798,null],[131800,"2026-07-28T16:40:33",7,"/ решил",112272,null],[131801,"2026-07-28T16:40:54",7,"/ технически подойди я не могу пока ее вижу пока в страхе. Закрыв глаза я могу к ней подойти?",112272,null],[131802,"2026-07-28T16:41:29",17,"/ Нет ты уже испуган",112272,null],[131803,"2026-07-28T16:41:40",17,"/ Даже с закрытыми глазами страх внутри тебя рисует ее ужасом на крыльях ночи",112272,null],[131804,"2026-07-28T16:41:53",17,"/ Закрыть можно было до её превращения",112272,null],[131805,"2026-07-28T16:41:54",7,"/ жаль, но ладно",112272,null],[131806,"2026-07-28T16:42:05",7,"/ ну не в моем случае к сожалению",131804,null],[131807,"2026-07-28T16:44:34",7,"*Немейя побоялась подходить. Вместо этого, она смотря на каргу приулыбнувшись говорит.*\n\n— Как насчет того... Чтобы сгореть за сироток, которых ты трогала тупой кусок невыебанной идиотки?\n\n*Она решает сама спровоцировать каргу подойти к себе, не подавая вида. Может мало что даст, зато... Она покрывается огнем и использует целый огромный выплеск пламени, чтобы задеть как можно больше горючего и устроить настоящий пожар.*\n/ Кастую огненные ладони, спас ловкости\nИ провоцирую каргу подойти к себе, а бонусным активирую огненную вуаль.",112272,null],[131808,"2026-07-28T16:44:41",7,"/r 3d6 +4",112272,null],[131810,"2026-07-28T16:44:48",7,"/ не слабо",112272,null],[131811,"2026-07-28T16:45:12",17,"/ д100 кинь",112272,null],[131812,"2026-07-28T16:45:18",7,"/r d100",112272,null],[131814,"2026-07-28T16:45:25",7,"/ окак",131813,null],[131815,"2026-07-28T16:45:27",17,"/r +1 Спас",112272,null],[131818,"2026-07-28T16:45:52",7,"/ хммм 8 +4 +2 провал спаса, полный урон огнем.",131816,null],[131819,"2026-07-28T16:46:40",31,"И она продолжит гореть, или разовая акция?/",131818,null],[131820,"2026-07-28T16:47:08",7,"/ огненные ладони( \nГореть не продолжит, но пусть подойдет, провоцирую :))",131819,null],[131821,"2026-07-28T16:47:53",17,"Поток огня в этот раз совсем необычный. Карга горит и вопит.\n\nНо в этот раз вместе с синим пламенем из-за твоей спины появляется огромная призрачная карета.\n\nМгновение и она собьёт и тебя и каргу.\n\nКарета пробивает стену мельницы и уносится вдаль, здание сильно повреждено.\n\n/Призрачная карета проносится по линии длиной 30 и шириной 10 футов. Ловкость против Сл; 2d6 дробящего\nурона и падение ничком, при успехе половина урона.",112272,null],[131822,"2026-07-28T16:48:01",17,"/Кидай спас я и ты",112272,null],[131823,"2026-07-28T16:48:04",17,"/r +1",112272,null],[131825,"2026-07-28T16:48:20",17,"Каргу карета сносит и сбивает с ног\n\n— ЧЕ ЗА ХУй..,!",112272,null],[131826,"2026-07-28T16:49:12",17,"/r 2d6 Дробящего от дикой кареты",112272,null],[131828,"2026-07-28T16:49:13",7,"/r d20 +2 ох тыш бле",112272,null],[131830,"2026-07-28T16:49:19",17,"/Половина тебе",112272,null],[131831,"2026-07-28T16:49:27",7,"/ записал 5 урона",112272,null],[131832,"2026-07-28T16:49:45",17,"/Альфи",112272,null],[131833,"2026-07-28T16:50:14",7,"/ Альф, ты не представляешь, но я случайно призвала карету и сбила нахуй каргу а она упала со второго этажа(",112272,null],[131834,"2026-07-28T16:50:23",7,"/ это случайность и трагедия(",112272,null],[131835,"2026-07-28T16:51:08",17,"/ Карга не упала со 2 этажа, она ничком упала, карета пробила стену и улетела",112272,null],[131836,"2026-07-28T16:53:05",60,"Альф прекрасно представляет, где сейчас это чмо, а посему он появляется там же, где был, и не открывая глаз идёт к карге: при этом иллюзорные глаза тортла открыты, и они полны бесстрашия. Варвар подходит ближе и с силой заносит двуручный меч над каргой, не проронив на сей раз ни слова",112272,null],[131837,"2026-07-28T16:53:24",60,"/r +5 а го чисто так тыкну",112272,null],[131839,"2026-07-28T16:53:33",60,"//можно было с гвм(",112272,null],[131840,"2026-07-28T16:53:47",60,"/r 2d6+d4+3 бум маг рубящий",112272,null],[131842,"2026-07-28T16:53:50",7,"/ она итак сбита с ног, так что норм",131838,null],[131843,"2026-07-28T16:54:01",60,"//поэтому без помехи",131842,null],[131844,"2026-07-28T16:54:17",60,"//бонуской.. Ничего не делаю. Конец хода",112272,null],[131845,"2026-07-28T16:55:47",31,"Hard",112272,null],[131846,"2026-07-28T16:56:57",7,"/ бонуской мог бы попросить пнуть ее ногой",131844,null],[131847,"2026-07-28T16:57:27",31,"/девушка красивая в кустах лежит нагой, другой бы изначиловал, а я лишь пнул ногой/",112272,null],[131848,"2026-07-28T17:02:08",17,"/ Ридли кинь Внимание. АТо эти испуганы или закрыли глаза",112272,null],[131849,"2026-07-28T17:11:18",9,"/roll 1d20 внимание ^^",112272,null],[131851,"2026-07-28T17:12:21",9,"//Надеюсь это не действие на моём ходу было",131850,null],[131852,"2026-07-28T17:13:47",9,"*Крепче перехватив цепи, из запонки вырывается вихрь огня. Ридли окружает чертову каргу вместе с Альфом и бьет по ней.*",112272,null],[131853,"2026-07-28T17:14:01",9,"/roll +d20+3 по карге",112272,null],[131855,"2026-07-28T17:14:38",9,"//Я сомневаюсь, но попал?",112272,null],[131856,"2026-07-28T17:17:18",17,"/Нет КД15",112272,null],[131857,"2026-07-28T17:17:49",17,"Выбираясь из своего сосуда ты заметил через дыру в стене как старушка с повозкой загруженой мешками катит её в мельнице в далеке",112272,null],[131858,"2026-07-28T17:19:09",9,"— Заканчиваем, быстро. Настоящая ведьма близко. — *Ворчит через маску так чтобы свои слышали.*",112272,null],[131859,"2026-07-28T17:19:23",9,"//Ну, хоть заметил и то збс, ход",131857,null],[131860,"2026-07-28T17:20:59",17,"Карга поднимается и сразу вонзает в Ридли когти\n\n— Да! Щас матушка вернёт и пиздец вам котята!",112272,null],[131861,"2026-07-28T17:21:00",17,"/r +5 Когти карги",112272,null],[131863,"2026-07-28T17:21:11",17,"/r 2d6+3 Рубящий",112272,null],[131865,"2026-07-28T17:21:40",17,"/ Тарх. В конце хода кто испуган кидайте спас сл 11 по мудрости. Чтоб от страха избавится",112272,null],[131866,"2026-07-28T17:23:32",9,"*Просто ловит когти своим телом, его свободная рука тянется к маске и он снимает её. Багровые глаза на пустом бледном лице словно смотрят в саму душу.*\n\n— Ты умрёшь быстрее...",131860,null],[131867,"2026-07-28T17:24:12",9,"//Ну хотя бы от обычных монстряк могу затанчить пару атак если повезёт и на том спасибо",112272,null],[131868,"2026-07-28T17:26:57",7,"/ на каждую матушку найдется своя призрачная карета",131860,null],[131869,"2026-07-28T17:32:42",17,"/ @QURTZZ",112272,null],[131870,"2026-07-28T17:51:17",31,"Я могу приблизится?/",112272,null],[131871,"2026-07-28T18:04:35",17,"/ Кинь мудрос сл11 чтобы окончить страх",112272,null],[131872,"2026-07-28T18:12:26",31,"/roll d20",112272,null],[131874,"2026-07-28T18:13:48",31,"Бегу как молодой носорог наверх, прихватываю по пути оброненные вилы, заношу их над распостертым телом и наношу удар, пробивая каргу насквозь",112272,null],[131875,"2026-07-28T18:13:57",31,"/roll +d20+1",112272,null],[131877,"2026-07-28T18:14:08",31,"Мимо, сука/",112272,null],[131878,"2026-07-28T18:14:36",31,"/roll +d20+1 бонусный удар древком",112272,null],[131880,"2026-07-28T18:14:50",31,"Опять мимо, видать со страху я был точнее/",112272,null],[131881,"2026-07-28T18:14:52",31,"Ход/",112272,null],[131882,"2026-07-28T18:16:01",31,"@Evreiskui_Department",112272,null],[131883,"2026-07-28T18:21:22",7,"/ тэкс ну хочу от страха\n@dunchev действие тратить?",112272,null],[131884,"2026-07-28T18:23:08",17,"/ Вы бросаете в конце хода. Тарх кидай и ты кидатй",112272,null],[131885,"2026-07-28T18:23:38",31,"Так я же кинул/",131884,null],[131886,"2026-07-28T18:23:42",31,"13 выбил/",112272,null],[131887,"2026-07-28T18:25:17",7,"/тэк ну раз в конце хода.",112272,null],[131888,"2026-07-28T18:26:46",7,"*Немейя не осмеливается подойти. Она боится в некотором смысле до сих пор, будто умереть от взгляда может. Однако она не поддается и решает использовать снова тоже заклинание, что ранее, дабы добить старую суку.*\n\n— Лови еще тупая пизда.\n\n/ Огненные ладони еще раз чтобы точно устроить пожар и так чтобы не задеть Альфа.",112272,null],[131889,"2026-07-28T18:26:56",7,"/ спас ловкости с старухи",112272,null],[131890,"2026-07-28T18:27:03",7,"/r 3d6 +4",112272,null],[131892,"2026-07-28T18:27:11",7,"/ найс",112272,null],[131893,"2026-07-28T18:27:50",17,"/ Твой магический огонь синий и не поджигает ))) кидай д100",112272,null],[131894,"2026-07-28T18:28:38",17,"/r +1 Спас",112272,null],[131896,"2026-07-28T18:29:02",17,"/ Русик решил слить все ячейки на массовый закл и со старшей картой драться вилкой",112272,null],[131897,"2026-07-28T18:29:36",31,"Хардкорщик, элден ринг ногами проходит/",131896,null],[131898,"2026-07-28T18:30:30",7,"/r d100",131895,null],[131900,"2026-07-28T18:30:56",7,"/ но-но-но\nПочему все?)\nПоловина, 2 бесполезные единицы чародейства восстановить и 2 в общей сумме будет",131896,null],[131901,"2026-07-28T18:41:21",7,"/ каков эффект? Все что горит потухает?",112272,null],[131902,"2026-07-28T19:13:26",17,"/ Я занят пока. Отдыхаю в бане и бассейне. Вот вам дикая магия опиши сам",112272,null],[131903,"2026-07-28T19:13:28",17,"Чёрные корни обвивают ваши ноги. Ваша скорость становится равной 0, но КД повышается на 2 до начала  \nследующего хода.",112272,null],[131904,"2026-07-28T19:20:29",41,"( с легким паром",131902,null],[131905,"2026-07-28T19:41:07",31,"Ладно, видимо пиздюлей от старшей карги будем завтра уже огребать",112272,null],[131906,"2026-07-28T19:47:00",7,"/ нельзя позволить вам сдохнуть",131905,null],[131940,"2026-07-28T23:02:11",17,"/ @FSmit7 ходи",112272,null],[131941,"2026-07-28T23:05:09",60,"//вот смотри",131940,null],[131942,"2026-07-28T23:05:19",60,"//у меня есть большая острая светящаяся палка",112272,null],[131943,"2026-07-28T23:05:28",60,"//знаешь, что она делает?",112272,null],[131944,"2026-07-28T23:06:06",60,"/r d20 правильно, дает звездюлей карге",112272,null],[131946,"2026-07-28T23:06:15",60,"//ровно в кд вроде",112272,null],[131947,"2026-07-28T23:06:29",9,"//Да, вродь говорил 15)",112272,null],[131948,"2026-07-28T23:06:58",60,"/roll 2d6+d4+13 бум палкой",112272,null],[131950,"2026-07-28T23:07:40",17,"/ Опиши как добил",112272,null],[131951,"2026-07-28T23:10:54",60,"//ля ну палка меч головка с плеч... У варвара вообще не меняются способы убийства, он тупо тыкает всех палкой. Но если хотите кровяки, будет кровяка.\n\n\nВ очередной раз Альф доказал, что порой просто тяжёлый кусок стали — это охеренно весомый аргумент. Именно этим клинком он в тупую распустил позвоночник лежачей карги надвое, даже будучи с закрытыми глазами. Её просто порвало на две части от грубой силы фирболга, забравшего жизнь уже второй ведьмы. Но есть ещё третья.. Альф быстро подходит к Тарху и Ридли\n\n—Вода. Святая. Она работает? Если да, то мне надо смазать меч. Осталась последняя.",112272,null],[131956,"2026-07-28T23:18:05",17,"/r +1 Мамочка",112272,null],[131959,"2026-07-28T23:18:43",17,"Ридли что делаешь?",112272,null],[131964,"2026-07-28T23:20:52",9,"/roll 1d20 пытается спрятаться где нить от ведьмы, за углом, мешком или ящиком чтобы атаковать из засады если получится",112272,null],[131966,"2026-07-28T23:21:05",17,"Спрятался",112272,null],[131967,"2026-07-28T23:21:07",9,"//Ход",112272,null],[131968,"2026-07-28T23:21:21",17,"/ Ведьма что то делает. Ход.",112272,null],[131970,"2026-07-28T23:21:41",17,"/ @QURTZZ спишь?",112272,null],[131972,"2026-07-28T23:21:55",17,"/r +d20+1 Скрытность",112272,null],[131990,"2026-07-29T04:19:08",31,"Это карга спряталась? Или она на первом этаже тусит?/",131973,null],[131993,"2026-07-29T06:26:00",17,"/ Да. Она стала невидима и это попытка скрыться была",112272,null],[131994,"2026-07-29T06:26:20",17,"/ На небольшом расстоянии ее можно будет услышать щас она ещё не подошла к мельнице",112272,null],[131995,"2026-07-29T06:28:49",31,"Тогда я встаю за дверью и подготавливаю засаду со скрытой атакой серпом",112272,null],[131996,"2026-07-29T06:29:52",31,"Передаю Альфу последнюю склянку со святой водой",131951,null],[131997,"2026-07-29T06:33:29",31,"Ход/",112272,null],[131998,"2026-07-29T06:43:53",7,"/ тэкс чей ходик...",112272,null],[131999,"2026-07-29T06:44:11",7,"/ 0 футов перемещения это страшно",112272,null],[132000,"2026-07-29T06:46:40",7,"*Немейя после использования своей магии, мгновенно переключается на клетку с детьми. Она не долго думая, попыталась подойти. Но корни намертво ее удержали, от чего она создает огненный снаряд в руке и метает его точно в замок.*\n/ Тэк я двигаться не могу, но планирую устроить пожар... @dunchev могу ли накалить снаряд до такого состояния чтобы замок начал плавится? Внимание у Немейи слабое",112272,null],[132001,"2026-07-29T06:47:31",31,"А детей не запечешь? Клетка если железная, температура быстро разойдется //",112272,null],[132002,"2026-07-29T06:53:29",7,"/ только замок",132001,null],[132003,"2026-07-29T06:53:37",7,"/ не клетку",112272,null],[132005,"2026-07-29T07:39:09",17,"/ Кидай попадание по замку КД 8 и урон хиты 5",112272,null],[132006,"2026-07-29T07:58:15",7,"/r d20 +6 пиу",112272,null],[132008,"2026-07-29T07:58:29",7,"/ меня Кубы не любят((",112272,null],[132009,"2026-07-29T08:01:18",17,"/Пиздец",112272,null],[132010,"2026-07-29T08:02:19",17,"Твой огненный снаряд попадает на тент и мгновенно поджигает его.\n\nДети внутри спокойно спят. Их не разбудил ни грохот дробилки, ни крики карг.\n\nМельница начинает разгораться, вспыхивает что то сухое в ящиках и сами ящики",112272,null],[132011,"2026-07-29T08:02:54",31,"спички тифлингу не игрушки/",112272,null],[132013,"2026-07-29T08:47:41",60,"//могу бонуской намазать оружие, а действием скинуть тент с клетки и бросить его в сторону? В окно, например?",132010,null],[132014,"2026-07-29T09:24:28",17,"/ Да, но горит не только Тент, пожар сильным тут были сухие ящики с чем то внутри типо сухой пшеницы.\n\nВЫ ГОРИТЕ В СТАРОЙ КОСТЕДРОБИЛКЕ",132013,null],[132015,"2026-07-29T09:26:02",17,"Сильный пожар разгорелся\n\nСпящие дети в клетке под замком\n\nМамаша карга невидима и приближается\n\nНе сложно понять, что она увидела карету или дыру в мельнице и спешит наказать вторженцев",112272,null],[132016,"2026-07-29T09:26:07",17,"Что вы делаете?",112272,null],[132017,"2026-07-29T09:26:52",31,"/roll d20+1 Подскакиваю к клетке и бью по замку древком вил",112272,null],[132019,"2026-07-29T09:27:01",31,"/roll d4+1",112272,null],[132021,"2026-07-29T09:27:42",31,"- немея, сбиваем замок и вытаскивай детей, ты хоть можешь вылететь отсюда",112272,null],[132022,"2026-07-29T09:31:45",60,"//немейя может вылететь с детьми на руках",112272,null],[132023,"2026-07-29T09:31:48",60,"//удобно",112272,null],[132024,"2026-07-29T09:32:29",31,"- альф, добей замок, мне сил не хватает",112272,null],[132025,"2026-07-29T09:32:32",7,"/ я могу расплавить руками замок",132021,null],[132026,"2026-07-29T09:32:48",7,"/ это и хотел если бы футы не отняли",112272,null],[132027,"2026-07-29T09:34:44",7,"*Немейя подходит и в своей форме, она трогает замок и начинает его сильно плавить.*\n\n— Пока я в таком состоянии, я могу навредить детям. Попробуйте из безопасно спрятать, где меньше дыма. Я постараюсь что то придумать, если у кого сильные раны, дайте знать.\n\n/ Если я сейчас 7 раундов буду трогать детей, они сгорят. А так я касанием сжигаю замок нанося 4 урона огнём и умением добью наверно, поджигать что угодно касанием",112272,null],[132028,"2026-07-29T09:35:55",31,"- какой прятать, тут пожар кругом, надо валить",132027,null],[132029,"2026-07-29T09:36:24",17,"/Детишки в собственном соку ммм",112272,null],[132030,"2026-07-29T09:36:30",7,"Немейя\n— Можете как нибудь сами детей спасти - делайте. Сейчас я могу в таком состоянии их сжечь.",112272,null],[132031,"2026-07-29T09:36:39",31,"/roll d20 на анализ, оцениваю, выживу ли если спрыгну с мельницы через пробитую стенц с ребенклом на руках",112272,null],[132033,"2026-07-29T09:37:02",17,"Ну наверное хороший план, не пострадаешь ни ты ни ребёнок",132031,null],[132034,"2026-07-29T09:37:22",31,"хватаю двоих и прыгаю на улицу",132033,null],[132035,"2026-07-29T09:37:30",17,"/Акробатика",112272,null],[132036,"2026-07-29T09:37:55",31,"/roll d20+1",112272,null],[132038,"2026-07-29T09:38:30",17,"Ты удачно приземляешься слегка подвернув ногу, но это чудо для такого прыжка",112272,null],[132039,"2026-07-29T09:38:33",31,"- Ридли, Альф, вытаскивайте детей!",112272,null],[132040,"2026-07-29T09:38:58",17,"/r +d20+6 Когти карги по Тарху",112272,null],[132043,"2026-07-29T09:39:54",17,"/r 2d8+4",112272,null],[132045,"2026-07-29T09:40:02",17,"/ Ты живой?",112272,null],[132046,"2026-07-29T09:41:25",31,"нет, ровно 14 хитов было, если бы 1 хит не потерял выбивая дверь, то устоял бы, а атк падаю/",112272,null],[132048,"2026-07-29T09:42:12",31,"/ладн хоть святую воду передал Альфу. И мой трупик послужит указателем где карга тусит/",112272,null],[132049,"2026-07-29T09:42:49",17,"Ты держишь детей и вдруг становиться тяжело\n\nПозади тебя из ниоткуда появляется ужасная зеленая карга её когти пробивают тебя насквозь когтистой ручищей\n\nОрганы не задеты сильно, но это выше твоих сил\n\nОна выдёргивает руку с ужасным смехом \n\n— ИИИИИХАХАХХАХАХАХАХ. ЯГНЯТА НА ЗАКЛАНЬЕ!\n\n— ГДЕ МОИ ДОЧЕРИ, СВОЛОЧИ?!",112272,null],[132050,"2026-07-29T09:43:14",31,"/могу ей перед падением ответить?/",132049,null],[132051,"2026-07-29T09:43:17",17,"Ты падаешь на колени и из последних сил пытаешься не уронить спящих детей \n\nКладёшь их на землю рядом \n\nПосле падаешь вперед лицом",112272,null],[132052,"2026-07-29T09:43:21",17,"/Да",132050,null],[132053,"2026-07-29T09:43:33",60,"Спас за то, что её увидел?",132049,null],[132054,"2026-07-29T09:43:44",17,"/ Ход Немеи и далее по ИНи",112272,null],[132055,"2026-07-29T09:44:20",31,"- в аду мразина, не волнуйся, ты догонишь",112272,null],[132056,"2026-07-29T09:44:24",17,"/ Нет. Это особенность морских карг. Эта зеленая",132053,null],[132057,"2026-07-29T09:44:43",60,"//пронесло",132056,null],[132058,"2026-07-29T09:45:17",60,"//как высоко падать из окна мельницы?",112272,null],[132059,"2026-07-29T09:47:57",17,"/ 10 футов",112272,null],[132060,"2026-07-29T09:48:02",17,"/Акробатика 14",112272,null],[132061,"2026-07-29T09:48:05",17,"/Без урона",112272,null],[132062,"2026-07-29T09:48:22",60,"//ых",112272,null],[132063,"2026-07-29T09:48:30",60,"//значит не будет джон сина",112272,null],[132064,"2026-07-29T09:52:10",31,"/мои вилы остались в огне. если выживы, найду их и надо будет искать новое древко, старое явно сгорит. Надеюсь, Альф поделится со мной палкой из той заразы?)) может она еще и бонусы даст на урон при атаке древком?))//",112272,null],[132065,"2026-07-29T09:52:32",31,"а жаль, было бы красиво/",132063,null],[132066,"2026-07-29T09:57:00",31,"//бляяя, сгорит мельница, а там по-любому вагон лута был(((//",112272,null],[132067,"2026-07-29T10:23:57",31,"@Evreiskui_Department твой ход",112272,null],[132068,"2026-07-29T10:30:20",7,"/ итак...",132067,null],[132069,"2026-07-29T10:30:30",7,"/ пиздим каргу, сколько до неё футов?",112272,null],[132070,"2026-07-29T10:35:18",31,"очевидно, недалеко. я выпрыгнул и получилось что упал прямо около нее/",132069,null],[132071,"2026-07-29T10:41:13",7,"/ ну мне лететь а не падать",132070,null],[132072,"2026-07-29T10:41:20",7,"/ я считаю хватит ли 30 футов...",112272,null],[132073,"2026-07-29T10:41:24",7,"/ ладно летим",112272,null],[132074,"2026-07-29T10:43:53",7,"*Немейя следом выходит из дыры. Она смотрит вниз, будто оценивала обстановку. Карга же видела очень яркий силуэт, а после и горящую Немейю, что набрасывается прям на нее и хватается руками за ее лицо.*\n\n— Сгори в огне, карга тупая.\n\n*С этими словами, девушка прочитала заклинание и мгновенно заполнила себя магией.*\n\n/ Бонусным восстанавливаю ячейку, набрасываюсь на нее и касаясь использую огненные ладони. Надеемся на ваншот",112272,null],[132075,"2026-07-29T10:44:03",7,"/ @dunchev спас ловкости",112272,null],[132076,"2026-07-29T10:44:15",7,"/r 3d6 +4 +4",112272,null],[132078,"2026-07-29T10:44:41",7,"/ 16 урона при провале, 8 при успехе",112272,null],[132079,"2026-07-29T10:44:46",7,"/ и конец хода",112272,null],[132080,"2026-07-29T10:45:52",31,"А про дикую магию не забыл?)/",112272,null],[132081,"2026-07-29T10:45:59",17,"/r +1 Спас",112272,null],[132083,"2026-07-29T10:46:33",7,"/ грустно, 4 урона и 8 огнем в лицо",132082,null],[132084,"2026-07-29T10:46:42",7,"/r d100 no",132080,null],[132086,"2026-07-29T10:46:52",7,"/ душить будете этой дикой магией",112272,null],[132087,"2026-07-29T10:47:39",17,"/ Вы меняетесь местами со случайным существом в пределах 30 футов. Несогласное существо может\nсовершить Харизму против Сл.\n\n1 Ридли 2 Альф 3 Карга",112272,null],[132088,"2026-07-29T10:47:43",17,"/r d3",112272,null],[132090,"2026-07-29T10:48:05",17,"/r +2 Спас Карги по харизме",112272,null],[132092,"2026-07-29T10:49:16",60,"Не понял, карга внутри мельницы или уже снаружи?",112272,null],[132093,"2026-07-29T10:49:32",31,"Она и была снаружи/",132092,null],[132094,"2026-07-29T10:50:30",60,"//значит сейчас устрою ей прыжок эль примо",112272,null],[132095,"2026-07-29T10:50:31",17,"Снаружи, из дыры выпрыгнул Тарх и она тут как тут",112272,null],[132096,"2026-07-29T10:50:43",60,"//но надо детей вытаскивать.",112272,null],[132097,"2026-07-29T10:51:05",60,"//я могу схватить двоих детей и спрыгнуть карге на лицо?",112272,null],[132098,"2026-07-29T10:52:00",60,"Альф не раздумывая спасает оставшихся жертв каннибализма и со всего размаху выпрыгивает из окна прямо на каргу, дабы смягчить себе падение\n\n—ЛОВИ, СКОТИНА!",112272,null],[132099,"2026-07-29T10:52:34",60,"//Если взять детей это свободное действие, то сейчас будет тык",112272,null],[132100,"2026-07-29T10:53:24",17,"/Давай акробатику",112272,null],[132101,"2026-07-29T10:55:06",60,"/r +1 держите меня семеро",132100,null],[132103,"2026-07-29T10:56:16",60,"//шмяк",112272,null],[132104,"2026-07-29T10:56:31",7,"/ жаль не атлетика",132102,null],[132105,"2026-07-29T10:57:19",17,"/r d6 Дробящего",112272,null],[132107,"2026-07-29T10:57:29",60,"//единичку записал",112272,null],[132108,"2026-07-29T10:59:03",60,"//как там, ещё могу тык или не могу?",112272,null],[132109,"2026-07-29T11:15:25",17,"/ КД17",112272,null],[132110,"2026-07-29T11:16:21",9,"//Наверху есть ещё дети? Можно карге упасть на голову?)",112272,null],[132111,"2026-07-29T11:16:42",17,"// Нет 4 ребёнка на улице. Два вытащил Тарх и два Альф",112272,null],[132112,"2026-07-29T11:17:23",9,"//На каргу можнг упасть с окна, она в досягаемости если падать?",112272,null],[132113,"2026-07-29T11:17:45",7,"/ преимущество, ибо я рядом... И не только я",132108,null],[132114,"2026-07-29T11:20:18",60,"/roll +d20 а мы будем гэмблить как всегда~",132109,null],[132116,"2026-07-29T11:20:29",60,"//ход закончил",112272,null],[132117,"2026-07-29T11:21:35",9,"//Чё там, можно упасть на бабку?",112272,null],[132118,"2026-07-29T11:22:04",31,"Валяй/",132117,null],[132119,"2026-07-29T11:22:18",9,"//Лан, пох, щас ^^",112272,null],[132120,"2026-07-29T11:23:30",31,"Мастер просил акробатику на приземление на каргу/",132119,null],[132121,"2026-07-29T11:26:02",9,"*Ридли выглядывает из окна, всё горит, тихо вздыхает, Немея опять всё подожгла. Став на подоконник парень сделал прыжок прямо на их противника, скоординировавшись в полёте так чтобы по карге прилетело локтём в лицо. Без воинственных выкриков и не шумел, лучше это сделать после удара когда карга сама его увидит.*",112272,null],[132122,"2026-07-29T11:26:38",9,"/roll +d20+3 падение метеором в бабку, я скрывался и она окружина домую для преимущества норм",112272,null],[132124,"2026-07-29T11:28:02",9,"/roll 1d4+2+1 дробящий с локтя по голове и одиничка огнём",112272,null],[132126,"2026-07-29T11:28:46",9,"/roll 1d20+2 атлетика, захват этой хрени бонусным от черты",112272,null],[132128,"2026-07-29T11:29:24",9,"//И спас мудрости от бабки сл 11 иначе она испугается ужасного облика, конечно если нет у неё имуна",112272,null],[132129,"2026-07-29T11:29:49",31,"А дл выхода из захвата ей что нужно?/",132127,null],[132130,"2026-07-29T11:30:30",9,"//Проверка атлетики акробатики, но подожди может и не захвачу ещё. или чтобы её отпустил",112272,null],[132131,"2026-07-29T11:31:39",9,"//Я бы ещё хотел получить урон от падения, чтобы и бабка его получила тоже, мол всем весом на нее упал, нг ждём д-ма)",112272,null],[132132,"2026-07-29T11:31:56",9,"//Щас узнаю результаты и как опишу",112272,null],[132133,"2026-07-29T11:32:56",17,"/r +4 Атлетика сопротивляется",132126,null],[132135,"2026-07-29T11:33:06",9,"//От страха нет?",112272,null],[132136,"2026-07-29T11:33:22",17,"/r +1 Спас мудрости",132128,null],[132138,"2026-07-29T11:33:28",9,"//И что с падением, можно?)",132131,null],[132139,"2026-07-29T11:33:38",17,"/Акробатика СЛ14",112272,null],[132140,"2026-07-29T11:33:48",9,"//Мехь, ладно",112272,null],[132141,"2026-07-29T11:34:07",9,"/roll 1d20 акробатика просто",112272,null],[132143,"2026-07-29T11:37:51",9,"*Ридли скоординировался в полёте, по ведьме прилитело локтём в голову. Не то чтобы эффективно, но это слегка встряхнуло её и это был шанс. Крепкие хоть и худые руки схватили ведьму за одежду.*\n\n— Твои дочери сгорят... — *Сказал он не человеческим голосом, Ридли был все ещё без маски, с тем же ничем не выражающим лицом и красными пронизывающими душу глазами.*",112272,null],[132144,"2026-07-29T11:42:02",31,"/ща бабка даст все просратся/",112272,null],[132145,"2026-07-29T11:42:26",7,"/ а вы ей рот закройте",112272,null],[132146,"2026-07-29T11:43:49",9,"//Ну, я могу подругому взять её в зазват)",112272,null],[132147,"2026-07-29T11:44:01",9,"//Засосать ведьму 😂👌",112272,null],[132148,"2026-07-29T11:44:14",7,"/ как Джотаро взял Дио за плечо в таймстопе?",132146,null],[132149,"2026-07-29T11:44:20",7,"/ крутит крутит крутит",112272,null],[132150,"2026-07-29T11:45:08",9,"//Ну, к сожелению ход, как есть. Нас сейчас того самого, этого",112272,null],[132151,"2026-07-29T11:46:51",7,"/ ты мог описать как закрыл ей рот типо ты не писал вроде конец хода",112272,null],[132152,"2026-07-29T11:48:31",9,"//Ребят, я не додумался, сорян, походил и описал. Так бы я ей хоть руку по локоть в рот засунул, пох уже.",112272,null],[132153,"2026-07-29T12:19:53",17,"— Мелкий говнюк! ТЫ СДОХНЕШЬ, СДОХНЕШЬ, СДОХНЕШЬ!\n\nКарга бьёт Ридли окровавленными кровью Тарха когтями",112272,null],[132154,"2026-07-29T12:19:57",17,"/r +6 Бам",112272,null],[132156,"2026-07-29T12:20:07",17,"— АЙ ГАД!",112272,null],[132157,"2026-07-29T12:20:10",17,"/Ход",112272,null],[132159,"2026-07-29T12:30:13",9,"//Хоть иногда моё проклятие приносит пользу)",132155,null],[132161,"2026-07-29T12:36:21",60,"@Evreiskui_Department ходи",112272,null],[132162,"2026-07-29T12:46:13",7,"/ такс...",112272,null],[132163,"2026-07-29T12:46:53",7,"/ описать я не могу, но я повторю свою атаку. Повторю так, чтобы попала только карга, с карги спас ловкости огненные ладони каст",112272,null],[132164,"2026-07-29T12:47:01",7,"/r d100 дикая магия",112272,null],[132166,"2026-07-29T12:47:09",7,"/r 3d6 +4 +4",112272,null],[132168,"2026-07-29T12:48:45",17,"/r +1 Спас",112272,null],[132170,"2026-07-29T12:49:10",17,"/Вызвавшее всплеск заклинание также поражает случайную подходящую цель в пределах его дальности.",112272,null],[132171,"2026-07-29T12:49:30",17,"/ У меня вопрос",112272,null],[132173,"2026-07-29T12:49:53",17,"/ Ты вплотную встал в бабке чтобы не задеть остальных? Или жгешь ее на расстоянии при этом Альф и Ридли будут в зоне, а так же детишки и Тарх",112272,null],[132174,"2026-07-29T12:50:26",17,"/А ну подошел, ок",132163,null],[132175,"2026-07-29T12:50:50",17,"/ 1 Альф, 2 Ридли 3 Снова в каргу",112272,null],[132176,"2026-07-29T12:50:53",17,"/r d3",112272,null],[132178,"2026-07-29T12:51:02",17,"/ Сжег пацана",112272,null],[132179,"2026-07-29T12:51:25",17,"/ Урон половина. Через спас можно еще в половину снизить",112272,null],[132180,"2026-07-29T12:51:31",17,"/ Ридли кидает спас ловкости",112272,null],[132181,"2026-07-29T13:03:06",9,"/roll 1d20 спас ловкости",112272,null],[132183,"2026-07-29T13:03:22",9,"//20 урона?",112272,null],[132184,"2026-07-29T13:04:01",9,"//Сколько всего то урона то)",112272,null],[132185,"2026-07-29T13:04:26",17,"/ 10",112272,null],[132186,"2026-07-29T13:04:50",17,"/ Ну или пусть департамент ещё раз кинет кубы. Оттуда половина",112272,null],[132187,"2026-07-29T13:05:07",17,"/ Альф",112272,null],[132188,"2026-07-29T13:06:02",9,"//Пф,\n\n*Стоит с одним хитом, гордо, обгорелый. Саван уже скоро рассыпется, пора надевать новую одежду.*",132185,null],[132189,"2026-07-29T13:06:37",9,"//Всего 14 хитов, по мне раз попадали и с временными ещё 3 хп снесли. Всего было 11)",112272,null],[132190,"2026-07-29T13:13:36",60,"Я делаю боньк, делаю второй..",132187,null],[132191,"2026-07-29T13:13:44",60,"/r +d20 лови зараза",112272,null],[132193,"2026-07-29T13:13:51",60,"Мисс",112272,null],[132194,"2026-07-29T13:14:00",60,"Ход окончен, расходимся",112272,null],[132195,"2026-07-29T13:16:16",9,"*Ридли понимает что он сам уже на последнем издыхании, на мгновение его взгляд цепляется за Тарха, он умирает, он умрет если ничего не сделать, или лучше удержать ведьму?*\n\n//Ну, щас решим, я хз что делать",112272,null],[132196,"2026-07-29T13:16:40",9,"/roll 1d2 один это ведьма два это Тарх",112272,null],[132198,"2026-07-29T13:18:57",9,"Действием Использование вы можете накинуть Цепь на несогласное существо в пределах 5 футов от вас, если у него есть состояние Недееспособный, Опутанный или Схваченный, и вы преуспеете в проверке Силы (Атлетика) Сл 13. Если ноги существа скованы, оно получает состояние Опутанный, пока не освободится. Чтобы освободиться от Цепи, существо должно действием преуспеть в проверке Ловкости (Акробатика) Сл 18. Чтобы разорвать Цепь, существо должно действием преуспеть в проверке Силы (Атлетика) Сл 20.",112272,null],[132199,"2026-07-29T13:19:26",9,"/roll 1d20+2 атлетика на падлу, обвяжу чертовку цепью",112272,null],[132201,"2026-07-29T13:19:54",17,"— Сволочь!",112272,null],[132202,"2026-07-29T13:20:35",9,"*Ридли накидывает цепи на шею ведьме и тащит на себя.*\n\n— Заткнись ведьма, ты сгоришь в огне вместе со своими дочерьми.",112272,null],[132203,"2026-07-29T13:21:05",9,"//Тащу падлу к горящей мельнице 15 футов",112272,null],[132204,"2026-07-29T13:21:10",9,"//Ход",112272,null],[132205,"2026-07-29T13:29:13",9,"//Кандалы конечно покруче, но цепи тоже неплохи, поэтому просто купил 10 штук с самого начала 😏👌",132198,null],[132206,"2026-07-29T13:29:46",17,"/r +4 Рвём цепи",112272,null],[132208,"2026-07-29T13:30:06",31,"На цепи гравировка: нихуя//",132207,null],[132209,"2026-07-29T13:30:22",17,"Она тащится за тобой опутаная цепями и наступает на гвоздь! Ауч это больно",112272,null],[132210,"2026-07-29T13:30:28",17,"/r d6 Колющий",112272,null],[132212,"2026-07-29T13:30:36",31,"Хера там гвоздь/",112272,null],[132213,"2026-07-29T13:30:49",17,"Гвоздь от старой мельницы пробил ей стопу насквозь",112272,null],[132214,"2026-07-29T13:30:56",9,"//Там точно те говозди старинные по несколько дюймов",132211,null],[132215,"2026-07-29T13:31:19",31,"Ещё и ржавый поди, спас тела от столбняка/",112272,null],[132216,"2026-07-29T13:32:59",9,"//Тарх в отключке, Немея?",112272,null],[132217,"2026-07-29T13:33:20",17,"Карга превращается в Ирину.\n\n— Куда ты тащишь меня парень... Я ничего не сделала...",112272,null],[132218,"2026-07-29T13:33:30",9,"//Хорошо что у этой твари похоже нет туманного шага",132215,null],[132219,"2026-07-29T13:33:49",31,"Мастер такой: о, точно/",132218,null],[132220,"2026-07-29T13:34:33",9,"//Я отвечу в свой ход, есть у меня идейки 😎",132217,null],[132221,"2026-07-29T13:34:40",31,"/вообще я почитал про карг, у них есть крутая тмв сбежать на астральный план//",112272,null],[132222,"2026-07-29T13:36:45",9,"//Да думаю твари разные бывают. У меня есть Бабка Йотилла, она хоть и не жрет детей но творит всякую жуть при этом добренькая чекнутая старушка.",112272,null],[132223,"2026-07-29T13:37:00",9,"//Ждём Немею, думаю Ирину видят все?",112272,null],[132224,"2026-07-29T13:37:11",31,"@Evreiskui_Department",112272,null],[132225,"2026-07-29T13:38:17",7,"/ извиняюсь, щас домой приеду",112272,null],[132226,"2026-07-29T13:46:39",7,"/ Тарх в отключке?",112272,null],[132227,"2026-07-29T13:46:47",31,"Да/",112272,null],[132228,"2026-07-29T13:46:50",7,"/ тэкс... Провоцировать атаку могу",112272,null],[132230,"2026-07-29T13:47:37",60,"//ну Ридли же её тащит",112272,null],[132231,"2026-07-29T13:47:42",60,"Значит не можешь//",112272,null],[132232,"2026-07-29T13:48:01",7,"/ класс",132230,null],[132233,"2026-07-29T13:48:10",7,"/ щас Тарха вернём в строй",112272,null],[132241,"2026-07-29T14:12:33",7,"*Немейя видя то, как начали нести старуху в огонь, отвлекается на Тарха. Она подходит к нему и касается рукой, стараясь не обжечь. Наоборот, она контролировала температуру и с трудом начала лечить раны.*\n\n— Эй, соня. Вставай давай.",112272,null],[132242,"2026-07-29T14:12:38",7,"/r d8 +4 хилка",112272,null],[132244,"2026-07-29T14:12:49",7,"/ 10 хитов восстанови и конец хода",112272,null],[132245,"2026-07-29T14:15:22",31,"Тарх встает, в очередной раз пребывая в ахуе от возможностей некоторых чуть ли не мёртвых поднимать\n\n- спасибо...\n\nСмотрит на детей, которых вытащил, они живы и все ещё спят\n\n- ничего, сейчас жта моазь сгорит, и вы проснетесь. Надеюсь",112272,null],[132246,"2026-07-29T14:15:58",31,"@FSmit7 ход Альфа/",112272,null],[132247,"2026-07-29T14:16:30",7,"*Немейя отходит, чтобы впервые не обжечь кого либо и присев, наблюдает за тем, как из карги хотят сделать шашлык.*\n\n— Да... Жаль не я сожгу ее. Зато она сгорит.",112272,null],[132248,"2026-07-29T14:16:49",60,"Тыркаем скотину",132246,null],[132249,"2026-07-29T14:17:07",31,"Пинком ее в огонь/",112272,null],[132250,"2026-07-29T14:17:19",60,"/r +d20 да, я действительно приношу ноль пользы из-за гэмблинга",112272,null],[132252,"2026-07-29T14:17:28",60,"/roll +d20",112272,null],[132254,"2026-07-29T14:17:38",60,"Есть пробитие",112272,null],[132255,"2026-07-29T14:17:56",60,"Го она кинет спас силы или ловкости на выбор",112272,null],[132256,"2026-07-29T14:18:06",60,"Если ловкость, то с помехой",112272,null],[132257,"2026-07-29T14:18:09",60,"Ибо опутана",112272,null],[132258,"2026-07-29T14:18:38",31,"Да ей и сила поди с помехой, она же связана, а чтобы освободится 20 надо выкинуть",112272,null],[132259,"2026-07-29T14:18:43",60,"/roll 2d6+2d4+13 бум урон",112272,null],[132261,"2026-07-29T14:19:08",60,"Ля, тут одинаковые кубы",132253,null],[132262,"2026-07-29T14:20:14",60,"/r 2d6 забыл там же ещё святая вода",112272,null],[132264,"2026-07-29T14:20:32",60,"35 урона суммарно",112272,null],[132265,"2026-07-29T14:20:41",17,"/r +4 Атлетика",112272,null],[132267,"2026-07-29T14:20:56",60,"Прошла",112272,null],[132268,"2026-07-29T14:21:07",60,"Никаких доп эффектов",112272,null],[132269,"2026-07-29T14:21:58",31,"Hard",112272,null],[132270,"2026-07-29T14:23:05",9,"*Ридли тащит ведьму перед собой, прямо в огонь.*\n\n//Суммарно 30 футов хватило её в огонь пихнуть?",112272,null],[132274,"2026-07-29T14:28:11",9,"*Ридли пихает ведьму в огонь. Ему плевать что рна выглядит как Ирина, даже если бы сама Ирина ела детей и готовила из низ пироги он бы поступил так же.*\n\n— Ложь тебя не спасёт.",112272,null],[132275,"2026-07-29T14:28:46",9,"/roll +d20+2 толкаю её в огонь",112272,null],[132277,"2026-07-29T14:29:19",9,"//Ну, от неё акробатика или что там, атлетика?",112272,null],[132278,"2026-07-29T14:38:38",17,"/r +4 Атлетика",112272,null],[132280,"2026-07-29T14:38:49",17,"/ Опиши как ты пихнул ее в огонь и сжег",112272,null],[132281,"2026-07-29T14:46:10",9,"*Ридли натягивает цепи выставляя ведьму перед собой, идёт прикрываясь ею от жара и огня и прямо перед самым пламенем отпускает цепи и с ноги толкает внутрь прямо в пламя. Он оборачивается и надевает маску выходя из горящей мельницы.*\n\n— Сгори до тла, старая пепельница.\n\n*Ридли выходит наружу, с каждым шагом он становился всё меньше, руки короче и немного живыми. Он весь в ожогах и в груди зияла рана от когтей. Ноги уже не несут, падает на ровном месте и просто садится на землю.*\n\n— Хорошо горит. — *Закашлялся кровью и коснулся ран на груди, те слегка затянулись, достаточно чтобы не умереть, ожоги не так сильно пекли.*",112272,null],[132282,"2026-07-29T14:47:14",9,"//2 хита мне исцеляющими руками, пох, отыгрываю а то перс выходя из облика без мистической поддержки точно бы был бещ сознания",112272,null],[132283,"2026-07-29T14:47:39",9,"*Посмотрел на Тарха.*\n\n— Ты жив? Что с детьми.",112272,null],[132284,"2026-07-29T14:54:55",31,"- жив. И они тоже",132283,null],[132295,"2026-07-29T16:03:48",31,"Присаживаюсь на землю, вытягиваю ноги:\n\n- бля, жалко пива и хлеба с салом собой не взяли, так бы на костре пожарили, посидели бы душевно, отметили",112272,null],[132297,"2026-07-29T16:06:19",31,"Оглядываюсь:\n\n- твою то мать, вилы внутри осталось. Надо бы найти, все таки от прадеда остались, реликвия семейная",112272,null],[132298,"2026-07-29T16:20:49",7,"*Немейя сидела и наблюдала издали. Ей нравился пожар, что поглощал мельницу. Однако она услышав про вилы, закатывает глаза. Может она и любит огонь, но не любит ссоры внутри команды. Она встав и встряхнув с себя пыль, отправляется в пожар. При помощи управления пламенем она освобождает себе проход внутрь горящей мельницы. А жар, что испытывают обычные существа ей безразличен, с рождения. Она осматривается и пытается обнаружить какие нибудь вилы.*\n/ @dunchev вилы ищу, внимание кинуть?",112272,null],[132299,"2026-07-29T16:25:49",9,"— Есть с собой еда. Не сало, готовить надо.",132295,null],[132300,"2026-07-29T16:27:13",9,"//Вы кстати хрен знаете что Ридли с собой носит, он говорил только о еде и от сосуда только каличный начальный вариант в который он может прятаться сам и то на 1 час всего)",112272,null],[132301,"2026-07-29T16:30:06",31,"- да я не про еду, я про романтику и приключения",132299,null],[132302,"2026-07-29T16:30:16",31,"- про поход, про битву",112272,null],[132303,"2026-07-29T16:30:39",7,"/r d20 +2",112272,null],[132305,"2026-07-29T16:31:41",9,"— Ладно. — *Парень не знает что добавить или возразить. В некотором роде сжёг ведьму, а с другой стороны он бы с радостью сидел в библиотеке культа и гнил в ней ещё пару лет.*",112272,null],[132306,"2026-07-29T16:32:05",17,"Вилы можно спасти, ты их видишь",132303,null],[132307,"2026-07-29T16:32:19",17,"/r d6 Огнем Немее",112272,null],[132309,"2026-07-29T16:32:32",7,"/ 2 урона, так и запишем",132308,null],[132310,"2026-07-29T16:34:13",17,"Горящая карга в виде Ирины дергалась в цепях как уж на сковороде, она меняла обличия, туда сюда, визжала, потом начала обугливаться, и наконец замерла и затихла",112272,null],[132311,"2026-07-29T16:34:29",17,"/ Всем по 400 опыта за карг и спасение детей",112272,null],[132312,"2026-07-29T16:34:52",7,"*Девушка погружается частично в пламя, получая незначительные ожоги. Вроде больно, но в тоже время приятно... Так или иначе, она хватает вилы и выносит их с собой.*\n\n— Мальчики, я нашла ваши вилы.\n\n*Немейя с приятным наслаждением слушала, как Карга сгорала заживо, а ее легкие наполнялись дымом.*",112272,null],[132313,"2026-07-29T16:35:11",9,"— Пахнет пирогами. — *Ридли прокоментировал чуя смрад из мельницы, смрад горелой ведьмы был неахти... но ради баланса вселенной он был бы не против сьёсть пару пирогов из самой ведьмы. Она ела, сьёли её, все честно.*",112272,null],[132315,"2026-07-29T16:37:10",7,"*Немейя держа в руках вилы, подходит к Тарху.*\n\n— Чтобы не разбрасывался своими игрушками. Может позже смогу их починить.\n\n*Говорит девушка, передавая из рук в руки.*",112272,null],[132316,"2026-07-29T16:37:40",31,"- спасибо. Еще раз",112272,null],[132318,"2026-07-29T16:39:33",31,"3 лвл вроде взяли//",112272,null],[132319,"2026-07-29T16:39:45",31,"Еще один и два очка характеристик упадет обывателю//",112272,null],[132321,"2026-07-29T16:43:04",9,"— Я слишком слаб. — *Ридли осознаёт что он был на грани уже не первый раз и поворачивается к Альфу.* — Альф, научишь меня носить броню? Хотел бы потренироваться в свободное время, это может не единожды жизнь.\n\n// @FSmit7 хочу попросить тебя учить Ридли носить лёгкие длспехи, от тебя особо ничего не требуется кроме согласия и присутствия условно на одной локации, условно мы делаем это вне кадра.",112272,null],[132325,"2026-07-29T16:48:57",7,"/ я где то пропустил опыт? )",132319,null],[132326,"2026-07-29T16:49:39",60,".",132311,null],[132327,"2026-07-29T17:00:32",9,"//всё, я теперь лампочка. Сделаем короткий?",112272,null],[132328,"2026-07-29T17:01:05",31,"Мне кажется мы уже нарративно его устроили/",112272,null],[132329,"2026-07-29T17:02:17",9,"/roll 2d6 рес хиты на коротком",112272,null],[132331,"2026-07-29T17:03:54",31,"/roll d10 тоже похилюсь",112272,null],[132333,"2026-07-29T17:04:06",31,"/не хватило до фула)/",112272,null],[132334,"2026-07-29T17:04:12",31,"/roll d10",112272,null],[132336,"2026-07-29T17:04:21",31,"Теперь фулл)))/",112272,null],[132337,"2026-07-29T17:05:55",7,"/r 2d6 +2",112272,null],[132339,"2026-07-29T17:12:10",60,"/r d12+3 мне всего пять хп надо реснуть",112272,null],[132341,"2026-07-29T17:12:22",60,"//Варвара вообще в лицо не бьют",112272,null],[132342,"2026-07-29T17:12:26",60,"//непорядок",112272,null],[132343,"2026-07-29T17:12:58",7,"/ ее варики метамагии",112272,null],[132344,"2026-07-29T17:13:44",9,"//Какого-то фига пиздюлей выхватывают все, кроме тебя 😏👌",132341,null],[132345,"2026-07-29T17:14:06",7,"/ ну танка не бьют, чтобы убить слабаков",132344,null],[132346,"2026-07-29T17:14:13",7,"/ тоесть нас троих",112272,null],[132347,"2026-07-29T17:14:37",7,"/ а я над метамагией подумал\nБеру ускоренное и неуловимое заклинание",112272,null],[132348,"2026-07-29T17:14:52",7,"/ если рядом появился фаерболл, это не Немейя",112272,null],[132349,"2026-07-29T17:16:31",9,"//У меня +2 хита от крепкого и абилка \"Сияние\" от расы аасимара защитника теперь работает, весь ап ^^",112272,null],[132350,"2026-07-29T17:17:20",31,"@dunchev опиши ситуацию, может лут если есть, ну и что там по детям?",112272,null],[132351,"2026-07-29T17:18:06",60,"//мне +2 кд в ярости, +1к4 урона раз в ход, +2 бесполезных приёма, и теперь у меня сопротивление психическому урону",112272,null],[132352,"2026-07-29T17:19:43",31,"Откуда? У обывателя же до 4 уровня никаких плюшек нет/",132349,null],[132353,"2026-07-29T17:20:48",9,"//расовая хрень, с 3го лвла начинает работать. Ну и от черты крепкого за уровень +2 макс хитов",132352,null],[132354,"2026-07-29T17:30:05",17,"Позади вас рушится догорающая мельница, всё что внутри объято огнем. Четыре спящих ребенка вы вытащили. Карги мертвы. \n\nЧто вы будете делать?",112272,null],[132355,"2026-07-29T17:31:31",31,"- ну что, раз мы тут все сожгли, то надо бы детей увести в город, в приют наверное. Жаль золотом не разжились, карги ведь за золото продавали пирожки. Или поищем на пепелище?",112272,null],[132357,"2026-07-29T17:32:28",60,"—Поищем. Херня вопрос.\n\nАльф поднимается и идёт прямо на мельницу, копаться в грудах углей и их собственных вещей",132355,null],[132358,"2026-07-29T17:33:21",31,"Все кидаем на внимание и ищем лут?)/",112272,null],[132359,"2026-07-29T17:33:41",31,"/roll d20+1 копаюсь на пепелище, ищу ништяки",112272,null],[132361,"2026-07-29T17:33:46",9,"— Это займёт много времени, все похороненно под обломками. До завтра если ислеет уже хорошо.",112272,null],[132362,"2026-07-29T17:35:30",17,"/ если будете ждать пока остынет пепелище +1 степень истощения будет",112272,null],[132363,"2026-07-29T17:35:47",17,"/ киньте д6 кто ищет",112272,null],[132364,"2026-07-29T17:35:57",31,"/roll d6",112272,null],[132366,"2026-07-29T17:36:15",17,"Пять золотых нашел",112272,null],[132367,"2026-07-29T17:36:55",31,"Юху, первые деньги перса/",112272,null],[132368,"2026-07-29T17:38:59",9,"*Ридли не ищет ничего, просто наблюдает за окружением. Вспоминает о воронах и смотрит нет ли тех рядом.*",112272,null],[132369,"2026-07-29T17:39:19",17,"/ 5 золотых найдено",132367,null],[132370,"2026-07-29T17:40:20",17,"Да пару ворон рядом есть. наблюдают с ветвей дерева",132368,null],[132371,"2026-07-29T17:40:21",31,"Как помародерем, отправляемся в город, ведем детей в приют/",112272,null],[132372,"2026-07-29T17:42:02",9,"*Вспомнив что через ворон за нами скорей всего наблюдают, парень кивнул им и перестал обращать на них внимания. Наблюдал за детьми и за большими детьми что роются на пепелище.*",132370,null],[132373,"2026-07-29T17:44:22",60,"/r d6",132363,null],[132375,"2026-07-29T17:46:02",17,"/ 4 монетки",132373,null],[132377,"2026-07-29T17:54:20",17,"/",112272,null],[132378,"2026-07-29T18:00:31",31,"Это тоже лут?/",132377,null],[132379,"2026-07-29T18:15:53",17,"И так что вы делаете? Идёте назад?",112272,null],[132380,"2026-07-29T18:16:01",17,"К приюту Валаки?",112272,null],[132381,"2026-07-29T18:16:48",31,"Для начала я бы хотел у детей узнать кто они и откуда, и кчть ли среди них тот мальчик что сбежал из приюта",112272,null],[132382,"2026-07-29T18:19:07",31,"Подхожу к детям (они же проснулись?)\n\n- привет, мальцы. Я дядька Тарх, а вас как зовут? Откуда вы и как оказались тут, на этой мельнице? Ваши родители знают о том, где вы?",112272,null],[132383,"2026-07-29T18:23:19",31,"У меня ечть умение деревенское гостеприимство, надеюсь его хватит чтобы дети ко мне прониклись",112272,null],[132384,"2026-07-29T18:24:49",17,"А дети спят беспробудным сном",112272,null],[132385,"2026-07-29T18:25:22",31,"- так, народ, херовые новости, дети то спят все еще. Надо бы их к лекарю тащить, или к жрецу",112272,null],[132386,"2026-07-29T18:26:21",31,"/roll d20 бросок на медицины, пытаюсь оценить состояние детей по внешним признакам и понять причину их беспробудности",112272,null],[132388,"2026-07-29T20:53:57",7,"/r d6",132363,null],[132431,"2026-07-30T10:02:38",31,"Ну что, все помарадерили? Берем спящих детей и тащим в город?/",112272,null],[132434,"2026-07-30T10:05:05",7,"/ берем детей, но могу взять только одного",112272,null],[132436,"2026-07-30T10:07:12",31,"Ну нас три мужика, один из которых размером с машину, думаю, мы и понесём детей. А тебе лучше быть нашей разведкой и артиллерией в случае чего/",112272,null],[132437,"2026-07-30T10:08:56",7,"/Разведкой ладно, артиллерия вряд ли ибо ячейки сдохли",112272,null],[132438,"2026-07-30T10:09:01",7,"/ а нет, появились чутка",112272,null],[132439,"2026-07-30T10:10:31",31,"@dunchev мастер, а если Тарх возьмет у Альфа ту палку, что он вырезал из заразы, и сделает из нее новое древко для вил, у этого древка не будет так, чисто случайно, какого нибудь дополнительного урона?) может ядом?/",112272,null],[132442,"2026-07-30T12:02:34",17,"Вилы из заразы\n\nЭти вилы сделаны из колючей заразы, сколько бы их не обтёсывали, на них продолжают расти колючки.\n\nПри атаке враг получает дополнительно 1д4 колющего урона\n\nКаждый удар вы получаете 1 колющий урон",132439,null],[132443,"2026-07-30T12:03:31",31,"Это при ударе как вилами, так и древком?/",132442,null],[132444,"2026-07-30T12:08:17",17,"/ Да",132443,null],[132445,"2026-07-30T12:09:42",31,"Не, ну в целом норм, механизм справедливый, если это будет работать как на основную, так и на бонусную атаку, я буду терять 2 хита за ход, но давать от основной атаки d6+1+d4 и от бонусной d4+1+d4, то есть если избежать рака кубов, в среднем где то 12 урона, неплохо, учитывая что больше 2-3 раундов я вряд ли проживу)/",112272,null],[132446,"2026-07-30T12:16:44",31,"Спасибо, мастер, рад что моя идея не пропала зря))/",112272,null],[132447,"2026-07-30T12:16:55",7,"/ а у меня идей нет)",112272,null],[132448,"2026-07-30T12:17:13",7,"/ уставшая и голодная тифлингша хотеть кушац",112272,null],[132449,"2026-07-30T12:18:12",31,"- Идем уже в город, детей разбудить надо",112272,null],[132450,"2026-07-30T12:20:21",7,"*Немейя уставше посмотрела на Тарха. Она скептически относиться к тому, чтобы уставшей тоскать ребёнка. Однако пожав плечами, подходит к одному из спящих детей и говорит.*\n\n— Кому пирог карги? У меня остался, если будет ломка у вас, хе-хе... Да, звучит ужасно если говорить это в слух.\n\n*Сказала Немейя и приготовилась идти.*",112272,null],[132452,"2026-07-30T12:26:48",17,"/Пишите идеи всегда, не бойтесь",132446,null],[132457,"2026-07-30T12:44:13",17,"Вы движетесь по направлению к Валаки\n\nИ видите небольшой лагерь в лесу неподалеку от дороги.",112272,null],[132458,"2026-07-30T12:47:43",31,"/roll d20+1 на внимание, пытаюсь оценить, не ловушка ли это",112272,null],[132460,"2026-07-30T12:47:54",31,"Ого, Крит/",112272,null],[132461,"2026-07-30T12:48:20",17,"Видя детей у вас на руках они техонько молча кивают\n\nТы четко понимаешь это знак уважения вам и тому что вы делаете.\n\nВероятно они понимают что вы детей спасаете.",132458,null],[132462,"2026-07-30T12:51:46",31,"Подойдем, познакомимся. Все согласны?/",112272,null],[132463,"2026-07-30T12:51:57",31,"@Evreiskui_Department @FSmit7 Hard",112272,null],[132464,"2026-07-30T12:55:41",7,"/ я согласен",112272,null],[132465,"2026-07-30T13:15:32",9,"*Ридли несёт одного из детей на спине, так немного легче чем на руках перед собой.*",112272,null],[132466,"2026-07-30T13:15:44",9,"//Да можно, чё нет? Делайте",112272,null],[132479,"2026-07-30T13:56:59",31,"Подходим к костру:\n\n- здравствуйте, добрые путники. Вы не будете против, если мы составим вам компанию у вашего костра? На этой земле всегда приятнее быть у огня",112272,null],[132480,"2026-07-30T13:57:20",17,"Девушка отвечает, мужчина в маске шакала молчит",112272,null],[132481,"2026-07-30T13:57:34",7,"*Немейя еле держит в руках ребёнка. Сказать что ей мягко говоря тяжело, взять и промолчать. Однако натянув лёгкую улыбку она помахала при помощи созданного ею магией пламени, сделав из нее руку.*\n\n— Здравствуйте спутники, не против легкой компании?",112272,null],[132482,"2026-07-30T13:58:28",17,"— Присаживайтесь, уложите детей на лежаки, земля холодная. Приятно видеть, что в багровии кто-то пытается делать добро. Мы видели зарево над лесом, старая мельница горит? Вы сожгли?",112272,null],[132483,"2026-07-30T13:58:47",17,"Мужчина кивает",112272,null],[132484,"2026-07-30T14:01:02",7,"*Немейя аккуратно кладёт при помощи рук и крыльев ребенка на лежак. Она услышав про подхог, слегка улыбнулась шире.*\n\n— Хвастаться не хочу, но огонька добавила я. Это было прекрасно сжигать карг, что этих детей на пироги пускали. \n\n*Говорит девушка, посмотря вниз на холодную землю и начиная поджигать ее чтобы согреть.*",112272,null],[132485,"2026-07-30T14:03:01",17,"— Ааа, так это были карги? Господи, какой ужас. Мы встречали бабушку с повозкой, но смекнули, что пироги необычные и удержались, хотя запах был очень приятный. В Валаки есть детский приют, можете туда их отнести. Тамошняя настоятельница приличная женщина, сможет о них позаботится. Мы жертвуем иногда туда немного денег.",132484,null],[132486,"2026-07-30T14:04:10",9,"— Я бы сьел пирог из самой карги. — *Ридли мрачно прокоментировал что думает по этому поводу и сел греть руки, ему было холодно, оставшийся ожоги сильно холодили и пройдут не скоро.*",112272,null],[132487,"2026-07-30T14:05:03",7,"Немейя\n— У меня сохранился пирог, до сих пор приятно пах. Хотя пока я была покрыта огнем он почему то не пострадал, а еще ему уже 4 или 5 луна. Ранее не ела потому что не хотела, потом были шибко долго у меня свежими.",132485,null],[132488,"2026-07-30T14:05:57",17,"— Лучше выбрось его. Пока он рядом будет соблазн попробовать. Но если всё так, как вы говорите. Его нельзя есть.",112272,null],[132489,"2026-07-30T14:06:21",17,"— Дети спят? Может нам говорить потише?",112272,null],[132490,"2026-07-30T14:07:32",7,"Немейя\n— Дети спят будто убитые. Их ни крики не разбудили, ни мимо пролетевшая карета призрак. А пирог я думаю отдать честно говоря животным. Пусть птички покушают. Да противно из чего он сделан, но не мы же кушать будем.",112272,null],[132497,"2026-07-30T15:12:17",17,"/r +3 Магия",112272,null],[132499,"2026-07-30T15:14:38",17,"Она проводит ладонью над лбом ребёнка \n\n— Да, на них заклятье. Нужно сварить одно зелье. Оно поможет их пробудить. Мне будет нужны игридиенты, шалфей, трутень и сыроежки. Если хотите и принесёте я бы могла помочь детям.\n\nМужчина в маске шакала смотрит на неё\n\nПауза\n\nПотом она добавляет\n\n— Если собираетесь нужно поторопиться, мы уходим утром.",112272,null],[132503,"2026-07-30T15:19:36",9,"— Я смыслю. Могу сварить нужное зелье если есть рецепт. — *Сказал Ридли. Он взглянул на детей и добавил:* — Правда лучше не затягивать.\n\n*Немного подумав Ридли понял что заклятие не спало.*\n\n— Немея... пирог все так же цел?",112272,null],[132504,"2026-07-30T15:20:23",9,"// @Evreiskui_Department",132503,null],[132505,"2026-07-30T15:23:26",7,"*Немейя с улыбкой на лице достаёт пирог из рюкзака. Она передает его молча в руки Ридли.*",132503,null],[132506,"2026-07-30T15:23:55",9,"// @dunchev пирог до сих пор цел?",132505,null],[132511,"2026-07-30T16:06:35",17,"/ Да",132506,null],[132512,"2026-07-30T16:21:59",7,"*Немейя была уставшей, но могла себя заставить пойти на поиски ингредиентов. По крайней мере поиск того, что можно добыть будет... Так или иначе, позже планирует спросить рецепт и выжечь его на чем нибудь... Если пергамента не будет у кого либо.*\n\n— Итак, знаешь как выглядят шалфеи, трутени и сыроежки? Я без понятия.",112272,null],[132514,"2026-07-30T16:30:33",31,"/roll d20+1 бросок на природу Тарх напрягает мозги, он жил в лесу, он партизанил в лесу, он лечил товарищей в лесу. Может получится вспомнить эти травы и где их лучше искать?",112272,null],[132517,"2026-07-30T16:31:06",31,"Сорян второй случайно ткнул/",112272,null],[132518,"2026-07-30T16:31:22",17,"Тарх узнает их легко если найдёте",112272,null],[132519,"2026-07-30T16:31:44",7,"/ помощь действие поздно, не?",132514,null],[132520,"2026-07-30T16:31:53",7,"/ оу",132516,null],[132521,"2026-07-30T16:32:25",31,"- Давайте поищем. Альф, как самый сильный, пусть с детьми остается, а мы втроем с Немеей и Ридли поищем",112272,null],[132522,"2026-07-30T16:36:30",7,"*Немейя недовольно цокает, но встает и создаёт огненный шарик. Она освещает себе путь и старается, на огонь не отвлекаться.*\n\n/ @dunchev кинуть внимание?",112272,null],[132523,"2026-07-30T16:48:26",17,"/Внимание, Выживание, Природа",112272,null],[132524,"2026-07-30T16:49:00",7,"/r -d20 +2",112272,null],[132526,"2026-07-30T16:49:28",7,"/ отвлеклась",132522,null],[132528,"2026-07-30T17:04:33",31,"/roll d20+1 природа",132523,null],[132530,"2026-07-30T17:05:39",31,"А почему с помехой?",132524,null],[132531,"2026-07-30T17:09:04",17,"Вы ходите по лесу в поисках нужных ингридиентов\n\nНичего на глаза не попадается\n\nВдруг ветка щелкает и вы обнаруживаете что вокруг вас куча накачаных мужчин в шкурах и с оружием\n\n— ХТО ТАКИЕ?",112272,null],[132533,"2026-07-30T17:10:37",7,"/ \" Стараюсь не отвлекаться на огонь \" отыгрыш",132530,null],[132534,"2026-07-30T17:15:30",7,"*Немейя удивлённо оглядывается, обдумывая момент когда это она успела найти ещё неприятностей. Она поправила прическу и усилила чутка пламя.*\n\n— Да так, местные, помогает Белле найти грибочки. Пирожки печёт на своей мельнице. А вы кто такие? Не видела вас ранее.\n\n*Импровизировала девушка, смотря на из реакцию. Ощущения были откровенно плохими, начиная от подозрений что мужики бандиты, заканчивая нежеланием попасть в рабство.*",132531,null],[132535,"2026-07-30T17:16:51",17,"— ПИРОГИ? У ВАС ЕСТЬ ПИРОГИ?",112272,null],[132536,"2026-07-30T17:18:27",7,"Немейя \n— Да, только один пирог. Мальчики, если дадите нам ингредиенты собрать, завтра приходите и по скидке покупайте пирожки, Белла сказала что будет всех ждать.\n\n*Сказала Немейя, доставая еще 5 пирожков из рюкзака и передавая ребятам, если те возьмут.*",112272,null],[132537,"2026-07-30T17:18:45",7,"/ Технически пиздабол, по факту не соврал",112272,null],[132538,"2026-07-30T17:20:53",7,"/ если что я помню там покупал 5 пирожков прежде чем одну из ведьм сунут в Шредер",112272,null],[132581,"2026-07-30T18:50:06",9,"//Быстро вы",112272,null],[132586,"2026-07-30T18:53:26",9,"*Дети околдованны, пирог цел. Ридли пытается вспомнить.*\n\n*Вроде бы если заклинатель мёртв заклинания спадает. Но, если магия в пироге и на детях сохранилась, то с той мельницей связанно что-то пострашнее?*\n\n//Что мне кинуть чтобы понять, должна ли была пропасть магия если мы убили того кто её наложил?",112272,null],[132590,"2026-07-30T18:55:09",9,"/roll 1d20 и пусть выживание, природа или что там, всё одинаковое, скорей всего со своими же ползу",112272,null],[132643,"2026-07-30T19:40:11",17,"— Мельница горела. Зарево на весь лес видать было. Давай сюда пироги, все что есть у тебя рогатая!",132536,null],[132645,"2026-07-30T19:41:45",9,"//Нас грабят или?",112272,null],[132646,"2026-07-30T19:41:57",9,"//Да и понять хочу как нить",132586,null],[132649,"2026-07-30T19:43:16",17,"Какая то сила ещё темнее и ещё мрачнее контролирует проклятья а ведьмы только ими пользовались",132590,null],[132650,"2026-07-30T19:43:16",17,"/ Гоп стоп от диких варваров",132531,null],[132653,"2026-07-30T19:43:49",9,"//Запомню. Сук, детектив какой-то 🤔",132649,null],[132682,"2026-07-30T19:58:44",7,"/ у Немейи рога отломлены, технически их почти не видно",132643,null],[132683,"2026-07-30T19:58:47",7,"/ но ладно",112272,null],[132687,"2026-07-30T20:02:06",7,"Немейя\n— Это переезд был, а мельницу сносить планировали. Теперь в городе будут пироги печь, а если хотите больше, то платить надо! Если вы попытаетесь меня ограбить и я не вернусь, моя подруга Белла занесет вас в черный список и не отдаст пирогов. Более того, она с сестрами тебя еще и накажут, сам знаешь как. \n\n*Говорит Немейя, без капли совести. Врёт? Разумеется, а что делать, когда силы тратить не охота на сражение.*\n/ Кидать убеждение?",132643,null],[132711,"2026-07-30T20:12:56",17,"/ Какое убеждение обман",112272,null],[132733,"2026-07-30T20:26:33",7,"/r d20 +6 одно и тоже)))",112272,null],[132741,"2026-07-30T20:28:56",17,"/r +1 Проницательность",112272,null],[132743,"2026-07-30T20:29:13",7,"/ весь мне, брат",132742,null],[132749,"2026-07-30T20:30:18",17,"— Ладна, пирог давай и шуруйте отсюда. Если вы с пекарнями друзья трогать не будем.",112272,null],[132757,"2026-07-30T20:31:41",7,"*Немейя закатив глаза отдаёт протягивает пироги и говорит.*\n\n— Угу, с вас 2 золотых, скидка за 5 пирожков и 1 пирог, да Ридли? \n\n/ Hard",112272,null],[132763,"2026-07-30T20:33:00",17,"— Отдавай бесплатно. Убивать не будем. Но поколотить ещё как можем если будешь наглой бабой!",112272,null],[132765,"2026-07-30T20:33:58",9,"— Пусть забирает. Но мы ищем шалфей и сыроежки, у вас с собой нет?",112272,null],[132769,"2026-07-30T20:35:24",7,"Немейя\n— Повторить? Я итак со скидкой отдаю тебе пироги, а получать синяки от вас или от пекарей как то не принципиально. Просто оплату, чтобы дальше печь пироги. Ну или вы поможете нам найти ингредиенты для нового пирога. Если поможете, замолвлю словечко и вы первыми получите новый сорт пирога, секретный рецепт!",112272,null],[132770,"2026-07-30T20:35:37",7,"/ язык мой враг, язык мой besto frendo",112272,null],[132772,"2026-07-30T20:36:06",17,"/ Ну давайте попиздимся из за золотой монеты",112272,null],[132774,"2026-07-30T20:36:19",17,"/ Кидайте ини вам щас дадут пизды толпа варваров",112272,null],[132775,"2026-07-30T20:37:17",7,"/ я торгуюсь с варвами просто, либо заплатят, либо помогут ингредиенты найти",132772,null],[132776,"2026-07-30T20:37:25",7,"/ или непонятно написал? ._ .",112272,null],[132777,"2026-07-30T20:38:00",7,"/ либо заплатите, либо поможете найти ингредиенты и получите первыми пирог \" По новому секретному рецепту \"",112272,null],[132779,"2026-07-30T20:40:48",17,"/ У них численное преимущество.\nОни привыкли все брать силой.\nТвоя жалкая проверка просто удержала их от прямого нападения сразу.\nТы продолжаешь наглеть.\nОни идут бить.\n\nЭто их логика",132775,null],[132780,"2026-07-30T20:41:19",17,"/ Твоё предложение их не волнует. Даже требование. Я бы сказал",112272,null],[132781,"2026-07-30T20:41:19",60,"//бррр, надо собраться и че-то написать",112272,null],[132783,"2026-07-30T20:42:57",9,"//Обе9главь самого сильного и наглого одним ударом и возглавь",132781,null],[132784,"2026-07-30T20:43:37",9,"//Похоже мы миром не разойдёмся ~",112272,null],[132785,"2026-07-30T20:44:05",60,"//если я верно понял, то альф остался у лагеря",112272,null],[132786,"2026-07-30T20:44:17",60,"//а эти мужики в лесу",112272,null],[132787,"2026-07-30T20:44:29",7,"/ попытка договориться о будущих поставках провалилась",132780,null],[132788,"2026-07-30T20:44:30",9,"//Эх, ну, будем решать с Немеей. Похоже там она да я",112272,null],[132789,"2026-07-30T20:45:06",7,"/ ну я то улететь могу просто \nА что делать тебе вопрос хороший",112272,null],[132790,"2026-07-30T20:45:36",7,"/ грустно что Варвары настолько тупые что их обмануть на помощь нельзя",112272,null],[132791,"2026-07-30T20:45:40",31,"Я тоже с вами таскаюсь, просто молчу/",112272,null],[132792,"2026-07-30T20:46:00",9,"//Ну, ты легео понесешь меня, у меня есть сосцл, я там от силы минут 30 сегодня сидел, столько же примерно осталось",132789,null],[132793,"2026-07-30T20:46:03",7,"/ ну да, ты же в сосуд спрячешься нет?",132791,null],[132794,"2026-07-30T20:46:31",9,"//У меня обрезанная версия этой хни. Только я сам могу быть там, передышки нет",112272,null],[132795,"2026-07-30T20:46:39",60,"//(Это Ридли умеет)",132793,null],[132797,"2026-07-30T20:49:25",9,"*Ложит руку на плечо Немеи.*\n\n— Просто отдай пирог, господа голодны, может они станут немного добрее после этого. — *Вот сейчас намёк союзнику.* — Ихдостать не трудно, правда нас послали искать некоторые ингридиэнты.",132769,null],[132798,"2026-07-30T20:49:57",9,"— Господа, вы не знаете где можно собрать немного сыроежек, трутеней и шалфея?",112272,null],[132799,"2026-07-30T20:50:38",7,"/ это то что я пытался сделать... Ладно",132798,null],[132800,"2026-07-30T20:50:52",7,"/ отдаю если что, у меня 5% просто",132797,null],[132876,"2026-07-30T21:56:45",7,"/ я тут",112272,null],[132877,"2026-07-30T21:56:55",7,"/ вообще труба без меня???",112272,null],[132878,"2026-07-30T21:57:14",7,"/ ну емае попытался по мирному решить проблему подведя к помощи",112272,null],[132882,"2026-07-30T22:03:52",17,"Один из варваров забирает пирог\n\nПринюхивается около тебя",112272,null],[132883,"2026-07-30T22:03:58",17,"/r +1 Восприятие",112272,null],[132885,"2026-07-30T22:04:06",17,"Но не учуял ещё пироги",112272,null],[132887,"2026-07-30T22:05:55",17,"— Собирайте. Мы уходим. Скажите пекаркам, что мы хотим пирогов, детей у нас больше не попадалось, так что пусть скажут кого убить. Одна голова за три пирога и не меньше!\n\nВожак сплевывает на землю \n\n— Валим!\n\nВсе послушно начинают скрываться в кустах",112272,null],[132890,"2026-07-30T22:11:00",7,"*Немейя частично вздрагивает. Она не поняла, почему Варвары резко спрятались и с улыбкой смиренной на лице оборачивается.*\n\n— Чтож... Дальше искать будем? Что происходит...\n\n*Говорит девушка, слегка разочарована.  Попытка не пытка, грустно что Варвары оказались глупыми. Однако унывать времени нет, надо подготовиться к тому, от чего бандиты спрятались и найти ингредиенты.*",112272,null],[132974,"2026-07-30T22:34:18",9,"— Пошли искать, но мне кажется. — *Ридли оглянулся.* — Мы плохие сборщики, ничего не найдём, мне прийдется самому сварить лекарство от марева позже. Лишь бы они были не против поделиться его рецептом.",112272,null],[133069,"2026-07-31T05:27:41",31,"Предлагаю еще раз всем кинуть на природу, выживание или внимательность, прошлый раз нашли варваров, может на второй раз повезет найти травы/",112272,null],[133070,"2026-07-31T05:28:09",31,"/roll d20+1 на природу, Тарх пучит глаза, выискивая нудные ингредиенты",112272,null],[133072,"2026-07-31T05:28:40",9,"//Если дм разрешит — кину ^^",133069,null],[133073,"2026-07-31T05:31:46",31,"Я бы вообще с преимуществом кидал, типа мы стали более внимательны, так как не хотим еще раз найти варваров)))//",133072,null],[133078,"2026-07-31T08:17:52",17,"Тарх ходит по округе и вскоре находит немного растущего шалфея",112272,null],[133079,"2026-07-31T08:18:30",31,"отлично. Жду от других тоже броски и пошли уже будить детей/",112272,null],[133080,"2026-07-31T08:18:42",31,"Hard @Evreiskui_Department",112272,null],[133083,"2026-07-31T08:34:55",9,"/roll 1d20 раз по второму кругу пошли",112272,null],[133085,"2026-07-31T08:37:25",17,"Ты находишь Трутень на дереве",112272,null],[133086,"2026-07-31T08:37:29",17,"/r",112272,null],[133092,"2026-07-31T08:54:50",31,"//думал о кастомизации оружия. жаль что карг просто сожгли, из их костей полюбому можно было бы сделать крутое лезвие для серпа))) правда, для применения навреное нужно было бы спас мудрости проходить))//",112272,null],[133093,"2026-07-31T09:07:34",7,"/r d20 +2",112272,null],[133112,"2026-07-31T10:25:08",31,"@dunchev я так понимаю, мы все собрали? можем идти к костру?",112272,null],[133117,"2026-07-31T10:42:33",17,"Ты находишь Бутылку",133093,null],[133119,"2026-07-31T10:42:52",17,"Осталось найти Сыроежку но её никак нет",112272,null],[133147,"2026-07-31T14:55:38",31,"- чертова сыроежка, так хорошо спряталась. Мы вроде все осмотрели, нужно наверное вернуться к костру и спросить совета, может ее чем то можно заменить?",112272,null],[133149,"2026-07-31T14:59:30",17,"На сук рядом сели два ворона",112272,null],[133150,"2026-07-31T14:59:50",9,"//Вижу их?",133149,null],[133151,"2026-07-31T15:00:08",31,"- опять эти птицы\n\nПотираю клеваный глаз",112272,null],[133152,"2026-07-31T15:03:07",9,"*Ридли достаёт из рукава немного еды, такой чтобы воронам было вкусно.*\n\n— Держите, хорошие мои. — *Ридли пытается их накормить.*",112272,null],[133153,"2026-07-31T15:03:12",9,"// - рацион",112272,null],[133161,"2026-07-31T15:13:03",17,"Вороны с удовольствием клюют твою еду и после улетают",112272,null],[133162,"2026-07-31T15:13:03",17,"Через некоторое время один возвращается а в ларе у него пара сыроежек",112272,null],[133163,"2026-07-31T15:13:31",31,"- спасибо птичка",112272,null],[133166,"2026-07-31T15:14:16",9,"— Спасибо. — *Берёт сыроежки.*",133162,null],[133170,"2026-07-31T15:14:45",9,"— Умные птицы, не успел попросить — помогли.",133163,null],[133187,"2026-07-31T15:19:32",31,"- слишком умные. Ладно, пошли к детям",133170,null],[134156,"2026-08-01T09:25:03",7,"*Немейя обнаружив необычную бутылку с жидкостью, берет с собой. Она кладёт его в рюкзак и идет за товарищами.*\n\n— Ничего не нашла, но вижу нашли вы. Отлично, вы молодцы.\n\n*Говорит Немейя без какого либо сарказма. Она идет позади, уже начиная слегка зевать.*",112272,null],[134157,"2026-08-01T09:47:34",31,"Ну ждем описания возвращения к костру/",112272,null],[134158,"2026-08-01T09:58:49",9,"— Нам немного помогли. — *По пути Ридли расказывает Немее и Тарху о своих думах.*\n\n— Обычно, когда заклинатель умирает, его магия развеивается если её не удерживал магический предмет, пентаграмма или что-то ещё... — *Он расказывал об основах магии, хотя и сам знал о исключениях и других вещах не так уж и много.* — На остаточное влияние не похоже. С ведьмами было слишком легко справиться, они бы не выжили сами в этих условиях. Склоняюсь к тому что над ними стоит кто-то пострашнее и он является источником той силы. Как вы заметили дети не проснулись а пироги... даже не горели в огне.",134156,null],[134164,"2026-08-01T12:01:59",31,"- ну, я не удивлюсь если сам граф этих карг и прикрывал, он тут главный хищник, очевидно. Я правда сомневаюсь что он до того в детали лезет, что детей лично околдовывает",112272,null],[134166,"2026-08-01T12:03:38",7,"Немейя\n— Сомнительно, что он бы прикрывал карг ибо какая ему от них польза? Потенциальное население сокращали только и все. Я думаю, что они просто удобно зажиличь в одном месте и все.",112272,null],[134168,"2026-08-01T12:07:07",31,"- а ты прямо думаешь что он так уже бережет свой народ? Напомню, мы с ним познакомились когда его зомби штурмовали дом. Какжстя, ему просто нравится мучить, а карги могли быть его, как бы это сказать, подрядчиками чтоли",134166,null],[134170,"2026-08-01T12:08:26",7,"Немейя\n— Народ нет, в целостность тел вполне себе. Или из пирогов и фарша можно собрать зомби, что будет тебе подчиняться? Думаешь он бы позволил боевую единицу на пироги пускать?",112272,null],[134177,"2026-08-01T12:10:37",9,"— Не знаю. Гадать лишнее, все детали и зацепки сгорели вместе с мельницей. — *Неспешно шагает вперёд.* — Лишь хотел сказать, у нас может быть ещё один могущественный противник, или переменная.",112272,null],[134183,"2026-08-01T13:46:36",7,"Немейя\n— Может быть, а может накручивать себя не надо. Так или иначе, я бы не отказалась поспать.",112272,null],[134870,"2026-08-01T17:49:17",31,"Что то мы зависли тут основательно/",112272,null],[134944,"2026-08-01T18:12:17",7,"/ ну я за прод отдых, поискать приключений на зад и пойти сжечь солнце! :>",112272,null],[135245,"2026-08-02T08:59:36",31,"Скажите пожалуйста, играем ли сегодня, и если да, то когда? Ну просто чтобы не забывать открывать телегу и проверять",112272,null],[135764,"2026-08-03T07:56:23",31,"я тут на ближайшие 5 часов",112272,null],[135765,"2026-08-03T07:58:33",7,"А я только веки открыл",112272,null],[135766,"2026-08-03T08:47:05",17,"Вы возвращайтесь с ингредиентами обратно к костру.\n\nАльф приглядывает за детьми.\n\nБеловолосая и шакал всё там же. Женщина говорит\n\n— Ну как успехи? Нашли нужное для зелья?",112272,null],[135768,"2026-08-03T09:08:29",31,"да, вот посмотри\n\n*передаю е компоненты*",135766,null],[135770,"2026-08-03T09:11:12",17,"— Хорошо, всё верно.\n\nДевушка встаёт и из рюкзака достаёт небольшой походный котелок и две рогатины, она над костром вешает этот колёт. Наливает из бурдюка туда воды. Бросает по одному игридиенты и помешивает половником шепча что-то себе под нос\n\nВ конце когда зелье нагревается она бросает в него синюю пыль от чего происходит пуф. И зелье меняет цвет.\n\n— Готово, остудить и можно дать детям. Это должно из пробудить.",112272,null],[135771,"2026-08-03T09:15:04",31,"- а отчего они так крепко спят? мы думали, что сон на них аслали карги, но карги мертвы, а дети не проснклись",112272,null],[135772,"2026-08-03T09:16:00",9,"*Молчит, раз Тарх взял инициативу на себя.*\n\n//Я скоро тут буду 👌",135771,null],[135773,"2026-08-03T09:17:07",17,"— В этом графстве магия ведёт себя странно, проклятья не проходят после смерти наложившего их колдуна. Тёмные силы туманов влияют. Будьте осторожны.",112272,null],[135774,"2026-08-03T09:17:42",31,"- если позволите узнать, а вы кто? вы не очень похожи на местных жителей",112272,null],[135776,"2026-08-03T09:19:40",17,"— Мы... Не из этих мест и попали сюда случайно. Можете звать меня Мара, а это Морок. Мы охотимся на нежить и ищем путь через туманы. Вам, что то известно об этом?\n\nДевушка разглаживает подол плаща а мужчина в шакалиной маске подбрасывает дрова в костёр",112272,null],[135778,"2026-08-03T09:21:13",31,"/roll d20+1 на проницательность, оцениваю их честность в меру своих сил",112272,null],[135781,"2026-08-03T09:22:24",31,"- ну, нежити тут точно хватает, буквально за каждым пеньком можно встретить. А насчет пути через туман - говорят что цыгане его знают, только я не знаю, водят ли они через него кого либо",112272,null],[135783,"2026-08-03T09:23:37",7,"*Немейя услышав, что магия ведёт себя странно... Чувствует себя слегка подавленно. Она садиться рядом и просто достаёт бутылку, начав ее изучать.*\n\n\" Магия странно ведёт себя... Хммм... Объясняет это сбои моей магии, но... Что поделать то... \"\n\n*С этими мыслями, Немейя пока готовилась ко сну. Она чувствовала себя более менее безопасно, но пока желание поспать нарастало.*",135773,null],[135785,"2026-08-03T09:27:51",17,"— Да, Вистани. Мы заходили в табор циган, общались с ними. Они не берут золото, оно им не нужно. Они рассказали, что могут покидать Багровию сами, но только потому что у них есть дозволение. Но они не рискуют вывозить местных. Это может плохо кончится. Такое было лишь раз и за, то, что отец одной девочки по имени Трисс очень сильно выручил табор Вистани. Точно не знаю, что там было, они не рассказали подробностей. Но барон был у отца этой девочки в долгу.\n\nВсё больше общаясь в девушкой Тарх может заметить особенности помимо белых волос",135781,null],[135786,"2026-08-03T09:27:54",17,"/Внимание",112272,null],[135787,"2026-08-03T09:29:37",31,"/roll d20+1",135786,null],[135790,"2026-08-03T09:31:58",17,"Приятынй голос",135787,null],[135791,"2026-08-03T09:34:31",31,"ну а поводу нежити - я так понимаю, тут всем заправляет местный лендлорд - граф Фон Зрович. есть у меня подохрение, что все зомби и прочие гниляки ему подчиняются",135785,null],[135792,"2026-08-03T09:35:44",17,"— Да, мы встречались с ним. ДУмали это наш конец. Но он просто попривествовал нас и сказал, что будет присматривать. Пожелал удачи и ушел. Его аура была подавляющей, я сразу поняла, одно не верное движение и — смерть.",112272,null],[135793,"2026-08-03T09:38:01",31,"- интересно конечно, откуда такая сила. но думаю если пытаться это выяснить - это как самому петлю на шею затягивать\n\n*проверяю, остыло ли варево для детей. если да - то пытаюсь их напоить",112272,null],[135794,"2026-08-03T09:44:54",17,"Варево остыло и ты поишь первого мальчугана.\n\nОн морщится от вкуса зелья и открывает глаза, протирая их.\n\n— Здраствуйте... Где это мы? А где тёти Белла и Олафия?",112272,null],[135795,"2026-08-03T09:45:13",9,"//Ахаха, варево)",112272,null],[135796,"2026-08-03T09:50:15",9,"// https://youtu.be/f4Bpaj479XU?si=u5kh6woz_Zx9K5XJ",112272,null],[135797,"2026-08-03T09:52:52",31,"- эти тети были не теми, кем казались, парень. И сейчас их нет. И мельницы больше нет. ты сам то как? и как тебя зовут? как оказался на мельнице?",135794,null],[135798,"2026-08-03T09:55:16",17,"— Я Миртон, сэр.",112272,null],[135799,"2026-08-03T09:57:37",31,"- откуда ты и как попал на мельницу?\n\n*пока говорю с Миртоном, пою следущих детей*",135798,null],[135800,"2026-08-03T09:58:21",9,"*Ридли сидит, греется у костра, веткой передвигает угли.*",112272,null],[135801,"2026-08-03T10:01:03",17,"— К нам в приют святой Марии в Валаки приходили эти прекрасные дамы. Они принесли очень вкусные пироги, вкуснее которых я никогда не пробовал. Я услышал, что они просили взять под опеку нескольких из нас, но наша злая настоятельница Маргарита отказала им. Почему она так сделала?... Не пойму.\n\n\nОн шмыгает носом и вытирает его рукавом\n\n— Я тайком сбежал после отбоя и догнал тётю Оливию, на тележке он отвезла меня на мельницу, накормила и уложила спать. И вот я проснулся тут.",135799,null],[135802,"2026-08-03T10:05:02",31,"- эх парень, молодой ты еще, не знаешь что если тебе что то хорошее за просто так обещают - это значит только то, что тебя хотят использовать. Тетя Оливия хотела пустить тебя и твоих товарищей на те самые пирожки. И если бы ваша настоятельница нам не рассказала о том, что детей ъоели сманить на мельницу, пирожком бы ты и стал. не забудь ее поблагодарить, когда вернемся в приют",135801,null],[135804,"2026-08-03T10:05:34",17,"Его глаза округляются он сильно испугался, по коже мурашки и сам стал бледный",112272,null],[135805,"2026-08-03T10:07:12",31,"- не бойся, эти тети до тебя уже не доберутся. нечем им добираться, ни ног ни рук у них не осталось. просто запоми что нельзя слепо верить всем кто тебе обещает сахарные горы",112272,null],[135806,"2026-08-03T10:08:10",17,"Он кивает",112272,null],[135808,"2026-08-03T10:10:44",31,"пока отпаиваю других детей, продолжаю разговор с мальчиком, пытаюсь сменить тему:\n\n- говорят, в Валаки скоро праздник, что то связанное с огнем и солнцем. Это веселый праздник, или церковный, тягучий и заунывный?",112272,null],[135810,"2026-08-03T10:13:26",17,"— Да, праздник солнца у нас раз в год, будут циркачи, жонглеры, сладости. Бургомистр скажет речь, а потом подожжет огромное деревянное солнце и оно будет красиво гореть, возвещая, что в валаки всё спокойно",112272,null],[135813,"2026-08-03T10:15:39",31,"обращаюсь к Маре:\n\n- вас не заносило в Валаки? Любопытный городок",112272,null],[135814,"2026-08-03T10:15:40",7,"/r d20 +2 думаю поздняк уже, но все же",135786,null],[135816,"2026-08-03T10:16:58",17,"— Нет, мы движемся к Абааству Крезка, говорят тамошний аббат настоящий ангел во плоти. Хотим проверить, может он знает как выбраться через туманы.",135813,null],[135818,"2026-08-03T10:19:48",31,"- прямо ангел? сильное заявление. Хотя, для нас тоже он своего рода цель, мы изначально к нему и шли, чтобы он помог найти лекарство от вампиризма для одного мальчика из Багровии",135816,null],[135825,"2026-08-03T10:24:15",31,"/roll d20+1 на внимательность. приглядываюсь еще раз, псле слов об ангеле",112272,null],[135829,"2026-08-03T10:25:40",7,"*Немейя не лезла в разговор. Она обожгла землю под собой, чтобы было тепло. После достаёт спальник, раскладывает его и сложив крылья, спрятав большую часть тела, просто ложиться. Укутавшись в спальник, что почти головы не видать, она начала слушать окружающих и после когда все притихнут, будет уже спать.*",112272,null],[135830,"2026-08-03T10:25:42",17,"— Слухи ходят, что настоящий.\n\nТы присматриваешься к девушке внимательнее, её кожа бела слишком сильно, даже мертвенно бледна, множество шрамов которые заросли на руках и за ухом например. А зрачки глаз бледные метвецкого оттенка.",112272,null],[135831,"2026-08-03T10:27:09",7,"/ блять вампиры",135830,null],[135832,"2026-08-03T10:27:26",7,"/ были же норм типочки с добрыми искренне намерениями",112272,null],[135834,"2026-08-03T10:27:54",31,"*мысли Тарха*\n\n- твою мать, так она тоже мервяк. но вроде не тупой кусок мяса, а видить что то пострашнее. но с детьми то помогла. чо делать*",135830,null],[135835,"2026-08-03T10:28:32",31,"/roll d20+1 на скрытность, пытаюсь удержать лицо и не дать понять что увидел что то странное и страшное",112272,null],[135840,"2026-08-03T10:30:01",31,"- что ангел бы тут мог забыть?\n\n*проолжаю разговор, а сам вспоминаю, что Ридли у нас тоже отчасти ангел, и тоже ведь как то его сюда занесло*",135830,null],[135994,"2026-08-03T14:37:03",7,"/ Немейя почти спит",112272,null],[140000,"2026-08-05T07:54:19",31,"живые есть?))//",112272,null],[140001,"2026-08-05T08:04:23",9,"//Умерли будто все)",112272,null],[140002,"2026-08-05T08:04:48",9,"//Можешь спросить кстати 😏👌",135840,null],[140003,"2026-08-05T08:05:40",9,"//Ридли связан с одной сюжетной составляющий сервера, хотя сама по себе его личность не важна, смертник, чё",112272,null],[140004,"2026-08-05T08:06:46",17,"— Это мы и хотим выяснить, целлестиалы тут выглядят как нечто инородное. Если граф пустил его, значит у него есть какой то план.\n\nДевушка бросила гость листьев и ягод в котелок с кипяченой водой и помешала такой травяной чай деревянной ложкой",135840,null],[140005,"2026-08-05T08:09:02",31,"- Ридли, а ты что скажешь? Мне кажется, из нас всех ты больше всех разбираешься в ангелах",112272,null],[140006,"2026-08-05T08:13:03",9,"— Нет. Полукровок достаточно много. — *Ридли поковылял веткой костёр.* — Говорят все должны слышать своих наставников, родителей, каждый в ком течёт кровь ангела.",140005,null],[140007,"2026-08-05T08:13:38",9,"*Парень задумался, стоит ли сейчас открывать своё происхождение.*",112272,null],[140009,"2026-08-05T08:17:57",9,"— Во мне течёт кровь, кровь того кто нес свет. Но ни я, никто из тех кого знаю не слышал голос происхождения, возможно потому что он давно мёртв. Не сказал бы что \"ангел\", если таковым можно назвать меня, как-то особо отличается от человека. Просто пару чудес и немного крепче тело.",112272,null],[140010,"2026-08-05T08:19:43",9,"— Не ждите что обычный человек окажется существом за гранью. Реальными могут оказаться лишь крылья. — *Полностью высказался что думает об этом.*",140005,null],[140011,"2026-08-05T08:22:47",31,"- мне стало еще интреснее пообщатся с этим аббатом. но сначала нужно детей довести до Валаки, а и там дела есть\n\n*решил игнорировать мертвость Мары, она не нападает, так что вероятно мы вне опасности*",112272,null],[140013,"2026-08-05T08:27:07",9,"//Я честно хз, меня мало что тригерит, да и жаль как то что Департ и Смит не играют почти. Типа, они тут герои, а мы так, в итоге нам двум каличам надо всё решать. Только и того что Тарх без тормозов а у меня встроена сумка хранения и хп на пару ударов в лучшем случае",112272,null],[140031,"2026-08-05T08:39:31",17,"/ Дыа, подстава конечно.",112272,null],[140034,"2026-08-05T08:41:05",9,"//Ну, с лругой стороны, если они отпадут то у нас будет хардкор гейм на сложности \"нихуя невозможно\" + будем мурыжить графа в 2 раза дольше если нам оч будет везти.",140031,null],[140058,"2026-08-05T09:11:49",9,"//Хочу чтобы всё збс было, и никто не отпал)",112272,null],[140153,"2026-08-05T12:07:34",7,"/ извините,_,",140013,null],[140159,"2026-08-05T12:08:18",7,"/ из грязи в грязи",140034,null],[140161,"2026-08-05T12:09:04",7,"/ ну я отписал, что в спальник лёг и готовлюсь ко сну. Вы общаетесь, место более менее безопасно можно сил набраться",135829,null],[140249,"2026-08-05T12:46:52",17,"/ Хорошо можно сделать долгий отдых",112272,null],[140572,"2026-08-05T14:36:12",9,"//Делаем, ммммм... длинный отдых",112272,null],[140573,"2026-08-05T14:36:20",9,"//Рес все способки",112272,null],[140606,"2026-08-05T14:42:43",7,"/ итак.... @FSmit7  жив?",112272,null],[140670,"2026-08-05T15:17:43",7,"/ понятно... Как долго ты будешь отсутствовать? На кого дуться?",140606,null],[141230,"2026-08-05T19:18:20",60,"//у меня скоро будет выходной, вроде бы. Половинка выходного",140670,null],[141232,"2026-08-05T19:19:03",7,"/ надеюсь, что все соберёмся... Я проголодался по рп, а времени у меня больше и больше на рп",112272,null],[141258,"2026-08-05T19:22:37",9,"//Я мог бы взять на обывателей 4м, если времени рил много",141232,null],[141260,"2026-08-05T19:22:57",9,"//Но играть надо активно будет, да",112272,null],[141261,"2026-08-05T19:23:08",9,"//Постараюсь каждый день)",112272,null],[141263,"2026-08-05T19:23:20",7,"/ я активно изза личных проблем не мог, скажем так период набирания сил перед учебой)",112272,null],[141265,"2026-08-05T19:23:28",7,"/ а так старался отписываться",112272,null],[141267,"2026-08-05T19:23:38",7,"/ так что извиняюсь снова, но теперь я тут",112272,null],[141268,"2026-08-05T19:23:40",9,"//Во флудго",112272,null],[141271,"2026-08-05T19:23:53",7,"/ не, я ждать ребят",141268,null],[141278,"2026-08-05T19:24:26",9,"//Лан, мб кого другого вощьму",112272,null],[141298,"2026-08-05T19:27:32",7,"/ я Николая уважаю и не уйду с квеста, сори:_",141278,null],[141301,"2026-08-05T19:28:32",9,"//Я за другого перса приглашал, никакой санта барбары",112272,null],[141303,"2026-08-05T19:29:00",7,"/ а тогда я за, но я спатки иду",141301,null],[141304,"2026-08-05T19:29:04",7,"/ напиши позже:_",112272,null],[141392,"2026-08-05T19:45:17",17,"/ Да тебе он предлагает ещё вписаться в один блудняк а не уйти",141298,null],[146915,"2026-08-08T18:09:41",9,"//Умерло, да?",112272,null],[146917,"2026-08-08T18:10:09",9,"//Я вас все время жду",112272,null],[146925,"2026-08-08T18:10:33",31,"Ну я живой, а хули толку?)/",112272,null],[146953,"2026-08-08T18:13:27",17,"/ Смит сказал в понедельник",112272,null],[146954,"2026-08-08T18:13:33",17,"/ Проверим его на пиздеж",112272,null],[147007,"2026-08-08T18:21:29",60,"//у меня завтра последний день работы",146953,null],[147008,"2026-08-08T18:21:54",60,"//Если я не появлюсь в понедельник, значит либо меня переехал камаз, либо я в гостях у роналду",112272,null],[147408,"2026-08-08T19:45:36",7,"/ а если был бы у Месси, то пришел бы сюда?)",147008,null],[147412,"2026-08-08T19:47:26",60,"//ну, это третье исключение, пожалуй",147408,null],[149546,"2026-08-09T23:07:30",60,"//*звуки воскрешения*",112272,null],[149548,"2026-08-09T23:08:26",60,"//типки сейчас вернулись к стоянке в лесу?",112272,null],[149551,"2026-08-09T23:09:26",60,"//да, вернулись, вижу",135766,null],[149555,"2026-08-09T23:13:27",60,"Альфарий просыпается в числе первых. Почти весь вечер он сидел у костра безмолвно, глядя в огонь с каменным лицом. Но на утро, кажется, его экзистенциальный ужас отошёл на второй план, а может и вовсе исчез: магия Баровии хоть сколько-то подавляет видения из пучины. Сегодня ему снилась чешуя. Золотистая, но почти изумрудная, холодная, почти мертвенная. Тяжелые крылья и вытянутое тело. Нечто.. Среди тех, кого смело можно бы спутать с богами. Но не сейчас. Сейчас это просто сон. Ему нет места в реальности. Откинув мысли, с протяжным, похожим больше на крик звуком, фирболг проснулся, потягиваясь, настраивая глаза на солнечный... Ах да. Его тут ожидать не стоит. Слегка гнетёт, наверное...",112272,null],[149593,"2026-08-10T09:15:42",17,"Вы проснулись утром, Мара и Морок уже собрали лагерь и кормили детей.\n\n— Пора прощаться, мы отправляемся в аббатство Креск. Может еще свидимся. Хорошо, что в этом прогнившем графстве еще есть те, кто не боиться бороться с тьмой. Удачи вам.\n\nМара сделала жест и над каждым из вас на мгновение сверкнул фиолетовый свет.\n\n/Благословение до долгого отдыха\n\nТеперь вы готовы отправляться обратно в Валаки",112272,null],[149647,"2026-08-10T09:49:26",60,"—Ну че вы, как погуляли ночью? Меня немного рубануло. Но теперь обратно пёхаем.\n\nСказал Альф, устраиваясь за трапезу у утреннего костра. Затем он обратился к Маре\n\n—И вам спасибо. Делаем, что можем.. Всего доброго.",149593,null],[149651,"2026-08-10T09:50:24",31,"- и ваи доброй дороги\n\n*мысли про себя*: какие добрые мертвяки, не тронули нас. подозрительно",149593,null],[149653,"2026-08-10T09:53:00",31,"Hard @Evreiskui_Department подтягивайтесь//",112272,null],[149681,"2026-08-10T10:00:26",9,"— Мёртвые, воля или дух некоторых из усобших настолько стльны что они сохраняют разум в посмертии. — *Смотрит на тёмные свинцовые тучи некротики в небе.* — Не всё так однозначно как может показаться. Думаю не все они здесь подчиняются графу.",112272,null],[149725,"2026-08-10T10:17:29",7,"/ тэкс",112272,null],[149736,"2026-08-10T10:22:07",7,"*Немейя проснувшись, встаёт. Она сложила свой спальник и положила в рюкзачок. После начинает подтягиваться и магией умываться. Она попрощалась с незнакомцами, помахав им рукой и из бутылки начинает пить непонятную, горькую, но бодрящую жидкость.*\n\n— Всего доброго! \n\n*После посмотрев слегка недовольно на Альфа, закатив глаза говорит.*\n\n— Встретили варваров, что помешаны на пирогах. Пойдемте в Валахию? Я думаю, что меня могли потерять.",112272,null],[149787,"2026-08-10T10:43:05",31,"- да, пора идти. Дети, айда в город, встаньте в середине между нами",112272,null],[149811,"2026-08-10T10:47:49",17,"Дети кивают вам и держатся близко, они поблагодарили Мару и Морока и вместе вы двинулись к Валаки",112272,null],[149813,"2026-08-10T10:48:02",17,"Стены Валаки появляются впереди сквозь серую морось. У ворот сегодня больше стражников, чем прежде.\n\nСтоит вам приблизиться, как один из них поднимает руку.\n\n— Стойте.\n\nЕго взгляд скользит по оружию, грязной одежде, следам крови — и наконец останавливается на четырёх детях.\n\nСтражник заметно теряется.\n\n— Это… дети из города?",112272,null],[149839,"2026-08-10T10:51:04",9,"— Украденные ранее из приюта. Мы их возвращаем домой.",149813,null],[149843,"2026-08-10T10:51:42",17,"За воротами, прислонившись плечом к стене караульни, стоит Айзек.\n\nПри виде вас он медленно выпрямляется.\n\nСначала его взгляд проходит по каждому из вас. Потом — по детям.\n\n— Утреннюю репетицию вы пропустили.\n\nОн делает несколько шагов ближе.\n\n— Ужин у госпожи Вахтер, как мне сообщили, тоже.\n\nПауза.\n\n— А теперь вы возвращаетесь в город с четырьмя детьми на руках.\n\nАйзек смотрит на ближайшего ребёнка, затем снова на вас.\n\n— Бургомистру это понравится.",112272,null],[149848,"2026-08-10T10:53:24",7,"*Немейя посмотрев на Айзека, указывает на ребенка. Она сделав вдох говорит.*\n\n— Извините, но надо было помочь ребятам. Деток вернуть надо было, а репетироваться всегда можно же успеть? Так что надеюсь, что не злитесь на меня. Когда будет репетиция следующая?",112272,null],[149865,"2026-08-10T11:00:53",17,"— Детей отнесёте в приют.\n\nАйзек кивает двум стражникам.\n\n— Они пойдут с вами.\n\nЗатем переводит взгляд обратно на героев.\n\n— После этого — площадь.\n\n— Бургомистр проявил терпение. Не заставляйте его проявлять что-нибудь другое.",112272,null],[149885,"2026-08-10T11:02:55",7,"Немейя\n— Конечно, конечно! Еще раз извиняюсь, пойдемте проводим детей!",112272,null],[149886,"2026-08-10T11:03:01",7,"/ @QURTZZ Hard @FSmit7",112272,null],[149888,"2026-08-10T11:04:25",31,"я тут, согласен, провожаем детей, затем на площадь/",112272,null],[149889,"2026-08-10T11:05:03",60,"—Не беспокойтесь. Мы просто разбирались с тем, что надо было сделать до похода сюда.. И справились. Добра вам. Дуем, народ!\n\nСказал варвар, снова втыкая в землю деревяку у ворот и проходя в город",149865,null],[149890,"2026-08-10T11:05:44",9,"— Хорошо. — *Надевает маску, на этот раз Ридли в простой своей одежде, кожа его бледна, но он все ещё носит маску. Бережёт мантии так сказать, от прошлой ничего не осталось.*",112272,null],[149892,"2026-08-10T11:05:58",31,"деревяшку ты мне подарил, я из нее вилы сделал новые))//",149889,null],[149893,"2026-08-10T11:06:06",60,"//всю?",149892,null],[149894,"2026-08-10T11:06:12",60,"//тогда мне нужна новая!",112272,null],[149895,"2026-08-10T11:06:32",31,"а она была болшая?/ мне чисто на ручку вил/",149893,null],[149896,"2026-08-10T11:07:28",60,"//ну я думаю там хватит, если с позвоночника вырезать",149895,null],[149897,"2026-08-10T11:07:48",31,"ок, тогда я кусок взял, остльное осталось/",149896,null],[149898,"2026-08-10T11:08:14",7,"/ а я топ топ топ провожать",112272,null],[149909,"2026-08-10T11:21:00",17,"Дверь приюта распахивается прежде, чем вы успеваете постучать второй раз.\n\nМаргарита появляется на пороге — и впервые её суровое лицо полностью теряет самообладание.\n\nОна видит детей.\n\nНесколько секунд женщина просто стоит неподвижно.\n\nПотом быстро подходит и опускается перед ними на колени.\n\n— Все четверо?..\n\nОна касается лица одного ребёнка, словно проверяя, настоящий ли он.\n\n— Милостивое утро… Все четверо.",112272,null],[149910,"2026-08-10T11:21:12",17,"Дети плачат и обнимают мать настоятельницу",112272,null],[149911,"2026-08-10T11:21:57",60,"—Живые, и, надеюсь, здоровые.. Берите.",112272,null],[149912,"2026-08-10T11:22:45",7,"Немейя\n— Они живы, здоровы и скучали по вам. Берегите их.",112272,null],[149913,"2026-08-10T11:22:57",17,"Маргарита поднимается.\n\nТолько теперь она замечает двух стражников у калитки.\n\nЕё лицо снова становится жёстким.\n\n— Спасибо за вашу неоценимую помощь, герои. Мы этого не забудем. \n\n— Денег у приюта нет, но дети нарисовали вам картинки, примите их пожалуйста.\n\nОна даёт каждому по листочку, где цветными карандашами нарисованы герои.",112272,null],[149915,"2026-08-10T11:23:41",31,"- мило",112272,null],[149916,"2026-08-10T11:23:58",31,"- спасибо ребата, увидимся на празднике",112272,null],[149917,"2026-08-10T11:24:38",7,"*Немейя остановилась будто. Она застыв, берет аккуратно на руки этот рисунок. Она смотрит на него и почти не моргает. Видимо ее это даже тронуло, в некотором смысле...*\n\n— Вау... Спасибо...",112272,null],[149921,"2026-08-10T11:27:44",9,"— Больше не берите странные вещи, у странных людей. — *Он достает 4-ре рациона на меду и каше, тех что более сладкие, у него больше таких нет.* — Небольшое пожертвование в приют, ничего не надо в замен.",112272,null],[149922,"2026-08-10T11:28:16",9,"//- 4 рациона, осталось 30 не сладких",112272,null],[149931,"2026-08-10T11:33:45",17,"/ Каждый получает вдохновение",112272,null],[149933,"2026-08-10T11:34:06",7,"/ рога даже нарисовали, хоть они и сломаны. Нравица",149929,null],[149935,"2026-08-10T11:34:48",31,"блин, круто)",112272,null],[149977,"2026-08-10T12:02:34",7,"/ итак, продолжим?",112272,null],[149978,"2026-08-10T12:02:49",7,"/ мы после идем на площадь",112272,null],[149979,"2026-08-10T12:03:48",9,"//Бабайка клоун, Соник, Пугало огородное и Демонёнок",112272,null],[149980,"2026-08-10T12:04:00",9,"//Вот так нас видят дети",149979,null],[149981,"2026-08-10T12:04:01",17,"/ Работой занят сори",112272,null],[149985,"2026-08-10T12:05:49",17,"На площади возвышается огромное деревянное солнце. Его лучи обмотаны жёлтой тканью, местами уже промокшей от мороси.\n\nРабочие тянут верёвки. Несколько стражников стоят вокруг помоста. Перед сценой зачем-то согнали около двух десятков горожан.\n\nВсе они улыбаются.\n\nВаргас Валлакович замечает вас почти сразу.\n\nЕго лицо расплывается в широкой улыбке.\n\n— А вот и наши герои!\n\nОн спускается с помоста, широко разводя руки.\n\n— Мне уже сообщили о детях. Великолепно. Просто великолепно!\n\nНа мгновение кажется, что он собирается спросить, здоровы ли они.\nВместо этого Варгас говорит\n\n— Нам придётся немного изменить программу.",112272,null],[149988,"2026-08-10T12:06:46",17,"— Понимаете ли вы, что произошло?\n\nВаргас начинает ходить перед вами, возбуждённо жестикулируя.\n\n— Вы покинули Валаки, столкнулись с ужасами, скрывающимися за нашими стенами, и вернули детей домой.\n\nОн поднимает палец.\n\n— Именно об этом я говорю каждый день!\n\n— Порядок защищает. Надежда защищает. Валаки защищает!\n\nОн явно не замечает противоречия.\n\n— На празднике дети выйдут вместе с вами. \n\n— ВЕДЬ КУДА ЖЕ ЕЩЕ ПРИВЕСТИ ДЕТЕЙ В ЭТОМ УЖАСНОМ ГРАФСТВЕ, КРОМЕ КАК В ВАЛАКИ! ГДЕ ВСЁ СПОКОЙНО!\n\nПоследние слова он чуть ли не кричит раскинув руки в стороны и запрокинув голову к небу",112272,null],[149992,"2026-08-10T12:09:21",7,"*Немейя аккуратно сложила рисунок, положила в рюкзак. Она начала идти к площади. Прослушав речь и чуть не убрав улыбку от некоторого... Смущения в речи, стольких противоречий, она кивает.*\n\n— Да... Спокойно в Валаки. Очень спокойно.\n\n/ Типичная Америка с улыбчивыми гражданами.",112272,null],[149994,"2026-08-10T12:11:53",9,"— Детей бы не украли если бы в Валаки не пускали карг, но, так понял мы это опустим? — *Ридли был не очень доволен, но он не показывпл виду, скорее будто смирился с логикой этого места.*",112272,null],[149997,"2026-08-10T12:14:02",31,"- знаешь, мне кажется что он просто пытается удержать свой город от страха и паники, держивая лицо. это странно, но может это рабоатет?",149994,null],[149999,"2026-08-10T12:20:54",9,"— Это имеет смысл. Да и не наше это дело. — *Повернул голову к Варгасу.* — Пока детям, будущему этого места, ничего не угрожает.",149997,null],[150000,"2026-08-10T12:25:01",7,"Немейя шёпотом\n— Мальчики блять, тише говорите. Вы забыли что бывает за такое поведение или напомнить про людей в клетках? После речи поболтаете о политике.",112272,null],[150001,"2026-08-10T12:29:51",9,"— Смерть? Я чуть не умер вчера. Да и мы говорим с самим Валаки, не распросраняем смуту в народе, за второе нам будут последствия. Ложь, при этом будучи гостем, неуважительно к хозяину. — *Махнул рукой.*",150000,null],[150112,"2026-08-10T14:40:41",17,"Вам люди Варгоса раздают листочки\n\n— Это сценарий, прочтите внимательно, ежеле не умеете читать мои люди вам прочтут в слух. Запомните всё в точности, и начинаем репетицию!",112272,null],[150114,"2026-08-10T14:44:28",31,"- эмм, ну я бы не отказался от чтения вслух. Я только по слогам умею и чтобы слова были из 2 слогов",112272,null],[150117,"2026-08-10T14:45:15",60,"—Ща посмотрим, я не самый тупой в своём клане...\n\nСказал фирболг, щурясь и вчитываясь в бумажку сценария, казавшегося ему чем-то ± бесполезным",112272,null],[150121,"2026-08-10T14:49:02",17,"Первым должен выйти Ридли и сказать\n\n\"Народ должен увидеть перемены\"\n\nДалее Варгос спросит у Альфария\n\n\"Расскажите, как вы увидели опасности за стенами и поняли ценность порядка\"\n\nАльфарий хвалит руководство Валаки говоря прямо, что только благодаря им всё спокойно!\n\nТарх должен помогать рабочим и детям поднимать солнце наверх\n\nА после Варгос поставит его среди детей и скажет: \n\n\"Простой земледелец, ставший защитником невинных! Потому что его направили на нужный путь власти Валаки!\"\n\nПосле этого Немейя зажгет солнце и оно воссияет.",112272,null],[150127,"2026-08-10T14:49:47",60,"//обязательно внесу свои коррективы",150121,null],[150153,"2026-08-10T14:55:10",9,"— Согласен, в моих словах ни капли лжи. — *Этого не видно, нг под маской улыбается, Ридли уверен остальные придумают чет интересное.*",150121,null],[150269,"2026-08-10T15:23:06",7,"/ я щас ем",112272,null],[150381,"2026-08-10T16:05:38",7,"*Немейя уже обдумывала, как можно было устроить самое яркое солнце. Может стоило бы... Добавить больше масла в солнце? А может магией питать чтобы горело даже в дождь.*\n\n— Угу... Сжечь солнце. Жаль большего не сожжёшь.",112272,null],[150932,"2026-08-10T19:07:59",7,"/ ну прогресс есть.",112272,null],[151987,"2026-08-11T08:38:40",17,"На площади стоит несколько десятков согнанных горожан. Перед ними — сцена, огромное деревянное солнце и помощник Варгаса с табличкой «АПЛОДИСМЕНТЫ».\n\nВаргас хлопает в ладони.\n\n— Начинаем! Ридли, вы первый.\n\nОн указывает на середину помоста.\n\n— Просто выйдите. Пусть народ увидит перемены.",112272,null],[151988,"2026-08-11T08:38:44",17,"/Hard",112272,null],[152042,"2026-08-11T10:20:10",9,"*Выходит и поднимает руки к деревянному солнцу, громко говоря.*\n\n— Пусть народ увидит перемены!",151987,null],[152043,"2026-08-11T10:20:55",9,"*Это был настолько фарс на самом деле, что Ридли даже было забавно.*",112272,null],[152049,"2026-08-11T10:29:51",17,"— Да! Да! Хорошая экспрессия, уловите эту интонацию, идеально!\n\n— Так далее...",112272,null],[152050,"2026-08-11T10:30:33",7,"/ жду не дождусь сжечь солнце",112272,null],[152051,"2026-08-11T10:33:02",17,"Из толпы раздаётся один нервный смешок.\n\nПомощник Варгаса поспешно поднимает табличку «АПЛОДИСМЕНТЫ».",112272,null],[152052,"2026-08-11T10:33:16",17,"Варгас поворачивается к Альфарию.\n\n— Теперь ваша речь.\n\nОн становится напротив него, изображая торжественного ведущего.\n\n— Расскажите нам: как вы увидели опасности за стенами и поняли ценность порядка?\n\nВаргас делает приглашающий жест.\n\n— Своими словами, разумеется.",112272,null],[152053,"2026-08-11T10:33:26",17,"/@FSmit7",112272,null],[152054,"2026-08-11T10:41:26",60,"Альф кивает, делает шаг вперед, слегка прокашливается и говорит\n\n—Порядок, тащемта.. И ведёт к цветению народа. Дисциплина хранит покой. Без неё... Стены города просто клетка внутри дома сумасшедших. Но с теми, кто верит в эту сплоченность и с теми, кто делает всё ради неё.. Город и будет стоять дольше любых оков.\n\nХаллоунест будет стоять вечно!",152052,null],[152055,"2026-08-11T10:54:46",17,"Варгас несколько секунд молчит.\n\nЗатем разворачивается к публике.\n\n— Прекрасно сказано!\n\nОн поднимает палец.\n\n— Даже человек из далёкой земли понимает. Cвобода ничего не стоит без порядка!\n\nКто-то в толпе медленно начинает хлопать.\n\nПоднимается табличка «БУРНЫЕ АПЛОДИСМЕНТЫ».",112272,null],[152057,"2026-08-11T10:56:31",17,"Двое рабочих подводят Тарха к огромному деревянному солнцу.\nВблизи конструкция выглядит ещё тяжелее. К ней привязано сразу несколько верёвок, две проходят через скрипучие блоки над сценой.\nСреди рабочих стоят и несколько детей постарше.\nОдин рабочий показывает Тарху на левую верёвку.\n\n— По команде тянем эту.\n\nВторой тут же качает головой.\n\n— Нет. Эту держим. Тянем правую.\n\nОни смотрят друг на друга.\n\n— Ты вчера говорил наоборот.\n\n— Вчера солнце было другой стороной. Вроде...\n\nСмотрят на Тарха",112272,null],[152058,"2026-08-11T10:56:48",17,"@QURTZZ",112272,null],[152061,"2026-08-11T10:59:28",31,"- делаем так как вчера, если не двинется солнце, то меняем тактику",112272,null],[152062,"2026-08-11T11:05:33",17,"/Атлетика",112272,null],[152064,"2026-08-11T11:08:35",31,"/roll d20+1",152062,null],[152066,"2026-08-11T11:08:43",31,"я могуч/",112272,null],[152070,"2026-08-11T11:12:09",17,"Ты чуть ли не в одиночку понимаешь солнце на системе лебедок.\n\n— Какая силища! Сила нашего духа!\n\n\nКогда солнце поднято.\n\nВаргас быстро расставляет спасённых детей возле Тарха, будто переставляет фигурки на доске.\n\n— Вот так. Тарх — чуть вперёд. Дети — вокруг.\n\nОн отходит, любуясь композицией.\n\n— Простой земледелец, ставший защитником невинных! Потому что его направили на нужный путь власти Валаки!\n\nОдин из детей смотрит сначала на Варгаса, потом на Тарха.\n\n— Но нас спасли не власти.\n\nПоднимается табличка «ООООУУУУУ.",112272,null],[152080,"2026-08-11T11:15:07",31,"шепотом:\n\n- хорошо что ты помнишь об этом, парень",112272,null],[152084,"2026-08-11T11:16:34",17,"— Конечно. Конечно. Герои спасли вас и привели в самый защищенный город в графстве!\n\nОн хлопает в ладоши\n\n— Продолжаем\n\nПоднимается табличка «АПЛОДИСМЕНТЫ».",112272,null],[152087,"2026-08-11T11:17:32",17,"— Держите солнце наверху! Именно так!\n\nВаргас поворачивается к краю площади.\n\n— А теперь нам необходим настоящий восторг!\n\nИз-за декораций выходит незнакомый вам мужчина в ярком плаще и широкополой шляпе. Он делает преувеличенно изящный поклон.\n\n— Риктавио, к вашим услугам.\n\nВаргас сияет.\n\n— Знаменитый путешественник! Артист! Хозяин диковин со всех концов света!\n\nУлыбка Риктавио на мгновение становится чуть менее естественной.\n\n— Бургомистр несколько преувеличивает.\n\n— Нисколько! Покажите им тигра.",112272,null],[152101,"2026-08-11T11:20:11",7,"/ сигнал ФАС уже есть, сжигаем солнце или нельзя во время репетиции?",112272,null],[152102,"2026-08-11T11:20:37",17,"Риктавио медленно поворачивает голову к Варгасу.\n\n— Тигра.\n\n— Именно!\n\n— На площади.\n\n— Именно!\n\nРиктавио смотрит на рабочих. На детей. На поднятое деревянное солнце. Потом снова на Варгаса.\n\n— Обычно перед выступлениями с крупными хищниками существует такая скучная традиция, как подготовка.\n\nВаргас добродушно смеётся.\n\n— Всё уже подготовлено! Посмотрите, сколько стражи.",112272,null],[152104,"2026-08-11T11:21:09",31,"- ох не к добру это\n\n*рука на вилах*",112272,null],[152113,"2026-08-11T11:22:42",7,"*Немейя ожидает команды. Она не до конца поняла, сжигать ли ей сейчас солнце и все было занято этой мыслью. Однако она начала чувствовать напряжение, будто... Что то намечается вне сценария.*",112272,null],[152114,"2026-08-11T11:23:07",17,"Риктавио.",112272,null],[152115,"2026-08-11T11:23:59",9,"//Калдун, чую калдун. Его надо сжечь",152114,null],[152116,"2026-08-11T11:24:34",9,"// *Просыпаются инсктинты инквизитора, жеть все подозрительное и непонятное*",112272,null],[152117,"2026-08-11T11:24:52",27,"// Он мне напомнил Шегораха из TES. Боюсь это он вас сожжёт",152115,null],[152118,"2026-08-11T11:25:33",60,"//в прошлый раз это закончилось тем, что одного клоуна пришлось собирать по кусочкам, а выступление было сорвано доппельгангерами",152113,null],[152119,"2026-08-11T11:26:02",9,"//Не спойлери, я не играл ^^",152118,null],[152120,"2026-08-11T11:26:12",17,"Со стороны боковой улицы раздаётся металлический грохот.\n\nПотом чей-то вопль\n\n— ЗВЕРЬ!\n\nНа площади становится тихо.\n\nИз переулка выбегает мужчина.\n\nСледом появляется огромная механическая полосатая кошка.\n\nТигр останавливается посреди улицы.\n\nНизко пригибает голову.\n\nВокруг него десятки людей.\n\nИ десятки людей одновременно начинают кричать.",112272,null],[152125,"2026-08-11T11:27:20",60,"//ниче не понял. Это просто большая кошка? Люди прям от страха орут, или как?",152120,null],[152126,"2026-08-11T11:27:40",17,"/ Механическая кошка",112272,null],[152128,"2026-08-11T11:28:04",60,"//прикол",112272,null],[152129,"2026-08-11T11:28:35",9,"//Убиваем изобретателя и его мех спутник откинется следом, победа",112272,null],[152130,"2026-08-11T11:29:42",17,"— СТОЯТЬ! — ревёт Айзек.\n\nНикто его не слушает.\n\nТолпа шарахается от тигра.\n\nОдин рабочий бросает верёвку и убегает.\n\nСледом второй.\n\nГде-то наверху раздаётся скрип.\n\nОгромное солнце наклоняется.\n\nОдин из детей смотрит вверх.\n\n— Господин Тарх?..\n\nВерёвка начинает быстро уходить через блок свистя.",112272,null],[152131,"2026-08-11T11:29:55",17,"За несколько секунд площадь превращается в хаос.\n\nТигр пятится от кричащей толпы.\n\nТрое стражников целятся в него из арбалетов.\n\nАйзек идёт вперёд, и его чудовищная рука уже начинает напрягаться.\n\nУ помоста толкаются дети.\n\nНад ними медленно кренится деревянное солнце.\n\nА Риктавио больше не улыбается.\n\nОн смотрит только на тигра.",112272,null],[152132,"2026-08-11T11:30:41",17,"Огромное деревянное солнце начинает заваливаться на вас",112272,null],[152133,"2026-08-11T11:31:37",60,"Изо всех сил хватая конструкцию, фирболг впадает в ярость и пытается удержать эту дрянь, чтобы остальные успели разбежаться и никого не убило",152132,null],[152134,"2026-08-11T11:31:40",17,"Барон Варгос кричит со злостью\n\n— УЛЫБАЙТЕСЬ, В ВАЛАКИ ВСЁ СПОКОЙНО!",112272,null],[152135,"2026-08-11T11:31:54",17,"/ Атлетика СЛ22",152133,null],[152136,"2026-08-11T11:32:09",31,"могу помочь?/",152135,null],[152137,"2026-08-11T11:32:09",60,"//ух...",152135,null],[152138,"2026-08-11T11:32:20",17,"/ Дети рядом с тобой",152136,null],[152139,"2026-08-11T11:32:20",60,"/roll +d20+5 ыыыыыааааа",112272,null],[152141,"2026-08-11T11:32:29",60,"//не хватило ±",112272,null],[152142,"2026-08-11T11:32:32",9,"*Помогает ему, руки вытягиваются становясь длиннее и сильнее, подхватывает и сам!*",152133,null],[152143,"2026-08-11T11:32:46",9,"//Бонусным в облик ужасный и щас тоже силу",112272,null],[152144,"2026-08-11T11:32:51",60,"//у меня есть мощное телосложение, если это сыграет роль",112272,null],[152145,"2026-08-11T11:32:52",31,"хватаю детей и рывком из зоны поражения",152138,null],[152146,"2026-08-11T11:32:53",17,"/ Ну кидайте Каждые 5 в вашем броске +1 к броску Альфа",112272,null],[152147,"2026-08-11T11:33:18",60,"//надо суммарно 15 еще значит",112272,null],[152148,"2026-08-11T11:33:18",9,"/roll 1d20+2 сила!",112272,null],[152150,"2026-08-11T11:33:27",17,"/ Не хватает 1",112272,null],[152151,"2026-08-11T11:33:45",60,"@Evreiskui_Department чародей, время напрячь мышцы",112272,null],[152152,"2026-08-11T11:33:58",17,"Айзек готовиться уничтожить тигра",112272,null],[152153,"2026-08-11T11:33:59",9,"//Вот бы ровно 22 выбросить самому конечно, но судьба она такая",112272,null],[152155,"2026-08-11T11:34:37",60,"//я уже не понимаю, кто за нас а кто против",152152,null],[152156,"2026-08-11T11:35:31",17,"Айзек вытягивает обычную руку в сторону зверя.\n\n— Арбалетчики.\n\nТрое стражников одновременно поднимают тяжелые арбалеты.\n\nРиктавио резко говорит\n\n— Не стреляйте!\n\nАйзек даже не смотрит на него.\n\n— Убрать зверя.\n\n— Если вы сейчас попадёте в него.\nОтвечает Риктавио уже совершенно другим голосом, без прежней театральности\n\n— Вот тогда у вас действительно появится разъярённый тигр.",112272,null],[152157,"2026-08-11T11:36:02",17,"/ @Evreiskui_Department  твоё действие",152155,null],[152163,"2026-08-11T11:39:08",7,"/ нашел кого просить, сила -1",152151,null],[152174,"2026-08-11T11:40:58",60,"//тебе надо выкинуть 6 на кубе",152163,null],[152176,"2026-08-11T11:41:12",7,"/ ну была не была, помогаю.",152174,null],[152177,"2026-08-11T11:41:18",7,"/r d20 -1",112272,null],[152180,"2026-08-11T11:41:58",60,"//репку победили",112272,null],[152182,"2026-08-11T11:42:30",9,"//Мы остановили падение, но как отпустим оно начнет падать 100%",112272,null],[152183,"2026-08-11T11:42:34",17,"Вы в троём удержали падающиее солнце и аккуратно спустили его на землю, почти не повредив\n\nТарх вынес детей",112272,null],[152185,"2026-08-11T11:42:53",9,"//А, хеппи енд)",152183,null],[152186,"2026-08-11T11:42:54",17,"Осталось придумать что делать с Тигром",112272,null],[152188,"2026-08-11T11:43:58",60,"варвар тупит и не понимает, че, собственно, происходит. Он просто стоит и смотрит",112272,null],[152189,"2026-08-11T11:44:46",17,"— Пристрелите эту машину... или кто юы это нибыл!\nСерьёзно говорит Айзек\n\n— Неет кричит Риктавио",112272,null],[152190,"2026-08-11T11:44:53",17,"/ Последний шанс вмешаться",112272,null],[152194,"2026-08-11T11:46:00",60,"—ЧЕ У ВАС ПРОИСХОДИТ?! ЗАЧЕМ СТРЕЛЯЕМ???",152189,null],[152196,"2026-08-11T11:46:40",9,"*Ридли не понимает что происходит, он ждет развязки, плевать. ЕслиВалаки навлечёт на себя беду то он сам виноват.*",112272,null],[152197,"2026-08-11T11:46:57",7,"*Немейя скрепя душой, еле помогла удержать гребанное солнце. Она была головой уже на механическом звере, что внушал ужас... Ощущение — надо уничтожить гребаного... Но с другой стороны оно пока никому не навредило, вроде бы... Девушка как только освободилась, подходит к Айзеку и перекрывает собой вид на зверя.*\n\n— Подождите! Механизм пока никому не навредил. Давайте просто это... Чудо юдо из железа унесут обратно и все. Давайте успокоимся, в Валахии безопасность превыше всего, а также улыбка. Паника не дарит ни улыбки, небезопасности.",152186,null],[152199,"2026-08-11T11:47:43",17,"/Убеждение",152197,null],[152200,"2026-08-11T11:48:05",7,"/r d20 +6 поверь мне брат!",152199,null],[152203,"2026-08-11T11:48:19",31,"*продолжаю укрывать детей за собеой, хер его знает что эта железяка может",112272,null],[152208,"2026-08-11T11:48:33",9,"//Мой любимый гряжный крит, вот куда наше 22 убежало)",112272,null],[152213,"2026-08-11T11:49:11",17,"Айзек поднимает руку\n\n— Ладно, стоять!\n\n— Убери эту штуку с площади старик!\n\n— Сейчас сейчас...\n\nГоворит Риктавио",112272,null],[152214,"2026-08-11T11:49:38",17,"Риктавио медленно снимает шляпу.\n\n— Хороший мальчик…\n\nОн делает шаг.\nТигр поворачивает голову.\nРиктавио делает ещё один.\n\n— Вот так. Смотри на меня.\n\nТигр перестаёт скалиться.\n\nРиктавио тихо произносит что-то ещё, слишком тихо, чтобы разобрать слова.\n\nИ огромный зверь медленно идёт к нему.",112272,null],[152216,"2026-08-11T11:49:46",17,"/Восприятие сл 16 чтобы разобрать",112272,null],[152218,"2026-08-11T11:50:03",60,"/roll d20+3 глазеем",112272,null],[152220,"2026-08-11T11:50:09",31,"/roll d20+1",152216,null],[152224,"2026-08-11T11:50:53",7,"/r d20 +2",112272,null],[152228,"2026-08-11T11:51:34",17,"Немея слышит краем уха как Риктавио сказал \"Спать\"",112272,null],[152235,"2026-08-11T11:53:00",17,"Вы видите как механический тигр ложится на пол. Скрежет металла и он складывается снова и снова пока не превращается в чемоданчик на колёсиках\n\nРиктавио берет его за ручку и откатывает в сторону\n\n— Прошу прощения, что то потревожило моего друга. Такого больше не повториться",112272,null],[152237,"2026-08-11T11:53:46",17,"Когда опасность почти миновала, Варгас наконец приходит в себя.\n\n— Великолепно!\n\nВаргас выходит вперёд.\nРиктавио медленно поворачивается к нему.\n\n— Простите?\n\n— Именно это нам необходимо!\n\nВаргас показывает сначала на чемодан, затем на поднятое солнце.\n\n— Опасность внешнего мира! Укрощённая порядком Валаки!\n\nРиктавио несколько секунд смотрит на него.\n\n— Нет.\n\nВаргас моргает.\n\n— Что?\n\n— Тигра на празднике не будет.\n\n— НЕТ ОН НУЖЕН НАМ НА ПРАЗДНИКЕ!",112272,null],[152247,"2026-08-11T11:54:38",7,"/ моя придумать идея",112272,null],[152262,"2026-08-11T11:58:06",7,"*Снова обернувшись, девушка начинает идти к Варгасу. Она закатила глаза, но не убрала улыбки и просто чтобы не нервничать, создаёт пламенный кружочек на правом плече.*\n\n— А если механизм заклинит? Сколько может людей пострадать из-за этого мистер Варгас? Может найдем альтернативу? Я могу сделать сцену, как огненный зверь подобный этому... Куску ожившего железа прыгнет в солнце и зажжёт его. Будет к слову как олицетворение храбрости воинов и пылающей их решимости сохранять местный порядок. \n\n*Говорит спокойно, не скрепя зубами, в надежде отговорить от глупой затеи.*",152237,null],[152268,"2026-08-11T12:00:13",17,"Его глаза расширяются\n\n— Оооо да, это будет великолепно!\n\n— Чтож Рик, забирайте зверя и присматривайте за ним лучше. Немея я жду от вас невероятное шоу на празднике через два дня. \n\nОн хлопает в ладоши.\n\n— Поднимите солнце, почините леса. На сегодня репетиция окончена. Да благословит утренний бог великий город Валаки",112272,null],[152288,"2026-08-11T12:10:00",7,"*Закатив глаза, девушка внимательно осмотрела живой металл. Запомнив фигуры, она кивнула и создает при помощи огненного снаряда копию данного существа. Огненная фигура, что позже мгновенно сжалось в шарик и обратно на плечо вернулось.*\n\n— Угу, и вас тоже благословит... \n\n*С этими словами, Немейя направляется к ребятам. Она выглядит слегка грустной, но улыбается спокойно без напряжения на лице.*\n\n— Мальчики, что делать будем?",112272,null],[152293,"2026-08-11T12:10:29",17,"— Герои, вы пока свободны! Следующий раз сразу на праздник!",112272,null],[152296,"2026-08-11T12:10:58",17,"/ Вам по 300 опыта за репетицию",112272,null],[152299,"2026-08-11T12:11:29",9,"— Не знаю можно ли ещё прийти к пригласившей нас госпоже. Мы не пришли вчера когда нас пригласили.",112272,null],[152313,"2026-08-11T12:13:12",17,"Когда репетиция подходит к концу, среди стоящих у края площади людей обнаруживается знакомая фигура.\nЭрнст Ларнак снимает шляпу.\n\n— Госпожа Вахтер просила передать, что вчера вечером вы так и не появились.\n\nОн улыбается.\n\n— Она совершенно не сердится.\n\nПауза выходит чуть длиннее необходимого.\n\n— Более того, услышав, чем вы были заняты, она заинтересовалась вами ещё сильнее.\n\nЭрнст протягивает сложенный лист бумаги.\n\n— Её стол сегодня вечером снова будет накрыт. Приходите",112272,null],[152323,"2026-08-11T12:15:40",7,"*Почувствовав себя неловко, что она совершенно забыла... Немейя принимает повторное приглашение. Она выглядит довольно задумчивой, в этот раз.*\n\n— Ааа, да... Приглашение... Ну, я думаю мы сегодня точно придём! Я постараюсь! Надо будет еды купить...\n\n*С этими словами девушка с легкой улыбкой смотрит на Альфа и Тарха.*",112272,null],[152412,"2026-08-11T12:44:19",31,"Тарх, с крестьянской простотой:\n\n- а зачем покупать, если и так кормить будут?",112272,null],[152437,"2026-08-11T12:53:32",7,"Немейя \n— Обычного яблока хочу, фрукта какого нибудь... Устала от каш, пирогов, супов...",152412,null],[152441,"2026-08-11T12:56:26",9,"— Сладкие каши с сушеными фруктами закончились, я отдал их детям. Только капчёности и солёности осташись.",112272,null],[152460,"2026-08-11T13:01:21",17,"/Куда вы направитесь, сейчас полдень",112272,null],[152463,"2026-08-11T13:01:26",17,"/Карта в закрепе",112272,null],[152481,"2026-08-11T13:04:29",9,"— У нас нет денег, думаю можно заглянуть в церковь и погулять по площади перед ужином. В торговые дворы и магазины идти смысла нет.",112272,null],[152497,"2026-08-11T13:09:15",31,"- мы хотели поговорить м кукольником и узнать почему Айзек заказывал куклу с лицом Ирины",112272,null],[152520,"2026-08-11T13:18:10",9,"— Ладно, уже забыл об этом.",152497,null],[153716,"2026-08-11T18:48:43",7,"Немейя\n— А мимо рынка пройдем? Хоть фруктами побалую себя. У меня есть три золотых вроде.",112272,null],[153923,"2026-08-11T20:10:56",17,"/ @FSmit7 все ждут тебя чтобы определиться куда идти. Я удивлен что настолько похуй",112272,null],[153925,"2026-08-11T20:11:28",60,"//ля, не заметил, что меня спрашивали",112272,null],[153926,"2026-08-11T20:11:34",60,"//Альф тип не тактик вообще",112272,null],[153927,"2026-08-11T20:11:52",60,"//тут как бы да",152497,null],[153928,"2026-08-11T20:11:57",60,"//у нас задача такая",112272,null],[153929,"2026-08-11T20:12:19",60,"//туда и идём, Ридли тоже согласен. Ну и дорожку через рынок пихнём",112272,null],[153931,"2026-08-11T20:13:32",17,"/ Кайф ну седня я сонный пипец. Так что завтра. За компом буду и продолжим",112272,null],[153932,"2026-08-11T20:13:42",17,"/ В городе ещё примерно 15 квестов ахазах",112272,null],[153936,"2026-08-11T20:16:09",7,"/ звучит как карьерный рост!",153932,null],[154104,"2026-08-12T06:39:29",31,"- значит сначала на рынок, а потом навестим кукольника. А вечером сходим на прием к местной знатной даме",112272,null],[154106,"2026-08-12T06:52:05",7,"*Радостно девушка кивает и улыбка становится чуть шире.*\n\n— Меня устраивает, идём!",112272,null],[154113,"2026-08-12T07:17:50",9,"*Кивает.*\n\n— Хорошо.",112272,null],[154151,"2026-08-12T09:06:47",17,"Риктавио успокаивает металлического тигра",112272,null],[154156,"2026-08-12T09:15:24",17,"Полдень, рынок полон людей. Здесь заметно живее, чем на улицах: торговцы ругаются из-за места, пахнет капустой, копчёным мясом, мокрой шерстью и свечным воском.\nНо новость о репетиции уже добралась сюда.\nПричём в пяти разных версиях.\nОдни утверждают, что механический тигр съел человека. Другие — что герои подняли солнце голыми руками. Третьи — что Айзек уничтожил зверя одним ударом, а четвёртые, что  зверь спокойно сложился в чемодан.",112272,null],[154157,"2026-08-12T09:15:46",31,"- немея, глянь на эту металлическую тварь. Она же явно волшебная. Но я так понял, что магия тут работает с перебоями. Может ты что то заметишь, почему эта железяка так хорошо слушается хозяина и при этом не случается всяких призрачных карет?",154106,null],[154158,"2026-08-12T09:15:47",17,"Едва вы входите на рынок, откуда-то впереди раздаётся звон колокольчика.\n\n— Граждане! Граждане! Радостная весть!\n\nНа ящике стоит городской глашатай с листком в руках.\n\n— Во время сегодняшней праздничной репетиции благодаря бдительности бургомистра Валаковича предотвращено несчастье! Огромное праздничное солнце было спасено, а свирепый механический зверь укрощён!\n\nОн переворачивает лист.\n\n— Очередное доказательство того, что порядок побеждает хаос!\n\nКто-то в толпе тихо произносит:\n\n— А я слышал, тигра укротил какой-то циркач.\n\nСосед тут же толкает его локтем.",112272,null],[154160,"2026-08-12T09:17:16",17,"Один предприимчивый торговец моментально начинает продавать дешёвые деревянные значки в виде солнца.\n\nНа некоторых уже кое-как нарисованы маленькие полосатые кошки.\n\n— Герои площади! Подходите, подходите! Первым экземплярам — скидка!\n\nНа его прилавке лежат грубо вырезанные деревянные солнца.\n\nОдно почему-то снабжено четырьмя ногами и зубастой пастью.\n\n— Это что?  \nспрашивает покупатель.\n\n— Механический тигр.\n\n— Не похож. Я был там!\n\n— Убежал быстро. Я рисовал по памяти.",112272,null],[154162,"2026-08-12T09:18:23",17,"Одна торговка бесплатно суёт Альфу хлеб или яблоки, когда вы проходите мимо.\n\n— Маргарита сказала, вы их вернули.\n\nЖенщина быстро заворачивает несколько ещё тёплых лепёшек в ткань.\n\n— Денег не надо.\n\nОна бросает взгляд по сторонам.\n\n— Если самим понадобится помощь… сходите к отцу Люциану. Он хотя бы сначала выслушает, а потом уже решит, грешники вы или нет.",112272,null],[154170,"2026-08-12T09:23:53",7,"/ фантастические твари и где они обитают",154156,null],[154175,"2026-08-12T09:27:26",7,"*Девушка оглядывается и выглядит слегка необычно задумчивой. Легкомысленность довела ее до упущения такой детали...*\n\n— А ведь и правда... Может магические существа созданные искусственно или таковыми являющиеся не попадают под влияние? Или когда только силы используешь...",154157,null],[154180,"2026-08-12T09:29:42",31,"- может это Риктавио и правда сильный колдун?",154175,null],[154182,"2026-08-12T09:29:54",31,"или простот очень итрый, раз обошел систему",112272,null],[154183,"2026-08-12T09:30:00",9,"— Магия бывает живой а бывает искуственной. Чаще магические предметы более стабильны. Надо найти тебе пару магических вещей для подстраховки, каждый раз выпуская волшебство ты рискуешь не только собой.",154175,null],[154184,"2026-08-12T09:30:04",31,"или это вообще граф под личиной?",112272,null],[154202,"2026-08-12T09:43:31",17,"/ Если что механически тигр не магически а как трансформер сложился",112272,null],[154203,"2026-08-12T09:44:07",31,"ну так я то откуда знаю? я крестьянин, для меня всякая самоходная железяка - магия)/",154202,null],[154204,"2026-08-12T09:44:13",17,"Возле лавки сладостей двое подростков спорят. Один говорит, что видел ночью какого-то мальчика, который стоял неподвижно под дождём и смотрел в окно.\n\nДругой смеётся\n\n— Это тот деревянный псих убийца!",112272,null],[154209,"2026-08-12T09:45:43",31,"- это вы о ком, пацаны? деревянный убийца?",154204,null],[154214,"2026-08-12T10:03:23",7,"Немейя\n— Ой ну простите, будто я сама не поняла с того момента, как меня переехала колесница или я стала видеть со стороны крысы в углу. У нас даже денег нет на это.",154183,null],[154215,"2026-08-12T10:03:39",7,"/ я в качалку почапал пока что",112272,null],[154216,"2026-08-12T10:08:16",9,"— Не всё впирается в деньги, может что-то придумаю. — *Реально пытается, но пока идей 0.*",154214,null],[154217,"2026-08-12T10:09:55",60,"—Сомневаюсь, что здесь золото стоит хоть чего-то. Им не откуда брать новые деньги, а еда кончается. Если они торгуют только золотом, то изживут сами себя.",154216,null],[154219,"2026-08-12T10:11:31",17,"— Дядь, вы чего уши греете! Это наши секретики и тёмные тайны. Но вот если договоримся о цене... Может и расскажем эту страшилку, которая тут у нас на улице произошла...",154209,null],[154226,"2026-08-12T10:27:35",17,"Рынок Валаки",112272,null],[154227,"2026-08-12T10:27:56",31,"- пацан, ты на меня посмотри. Ты что, реально думаешь что у меня есть что то ценное? Нужны мне ваши детские тайны\n\n*Отхожу, типа с замыслом что они теперь назло расскажут, типа обратная психология*",154219,null],[154228,"2026-08-12T10:28:15",17,"/ Обман",154227,null],[154229,"2026-08-12T10:28:26",31,"/roll d20-1",154228,null],[154233,"2026-08-12T10:30:53",9,"*Даже Ридли сейчас в обычной одежде, только и того что в маске той жуткой.*",112272,null],[154234,"2026-08-12T10:31:49",17,"— ДА ЭТОТ ЯНЕК ЖОРУ ЗАМОЧИЛ! КИШКИ ЕМУ ВЫПУСТИЛ! А Я ВСЕМ СРАЗУ СКАЗАЛ, ОН НЕНОРМАЛЬНЫЙ! ГОВОРИЛ СТРАННО И НИЧЕГО НЕ ЕЛ!",154227,null],[154235,"2026-08-12T10:31:55",9,"//Не хочу в саваннах ходить просто такс их никто новые не пошьёт! А если и да то дорого",112272,null],[154237,"2026-08-12T10:34:16",31,"Где можно найти Янека? Мы с друзьями бы проверили, насколько он ненормальный",154234,null],[154238,"2026-08-12T10:35:09",17,"— Он сбежал, мы не знаем... В лавку кукольника понёсся как всегда",112272,null],[154239,"2026-08-12T10:36:30",9,"— Тарх не плохо ладит с детьми. — *Пробормотал Ридли.*",112272,null],[154243,"2026-08-12T10:39:23",17,"— Мы немножко колотили его, за его глупый вид и непонятный говор\n\n\nМальчик опускает глаза",112272,null],[154244,"2026-08-12T10:39:30",17,"— Не брали играть с нами...",112272,null],[154246,"2026-08-12T10:39:37",60,"//а альф идет с светящимся мечом за спиной",112272,null],[154247,"2026-08-12T10:39:43",60,"//беспалебный",112272,null],[154248,"2026-08-12T10:40:16",17,"/ Тебе сунули хлеб и яблоки",112272,null],[154249,"2026-08-12T10:40:16",17,"/ Они упали на землю?",112272,null],[154250,"2026-08-12T10:40:18",9,"//Пипец, там пацан из Темнограда 100%, у них странный говор и боевой настрой)))",112272,null],[154251,"2026-08-12T10:40:48",9,"//Лан, просто предположил",112272,null],[154252,"2026-08-12T10:40:51",60,"//мне?",154248,null],[154253,"2026-08-12T10:41:04",17,"/.",154162,null],[154254,"2026-08-12T10:41:15",60,"//ага",154162,null],[154255,"2026-08-12T10:41:43",60,"//у меня оч странное говно с отображением сообщений непрочитанных",112272,null],[154258,"2026-08-12T10:41:58",60,"//чат лезет вверх, но плашку новых сообщений не показывает",112272,null],[154259,"2026-08-12T10:42:13",60,"//раньше это было только с одним чатом, теперь со всеми",112272,null],[154260,"2026-08-12T10:42:41",60,"//но нет, не упали, рюкзак там же",154249,null],[154261,"2026-08-12T10:42:59",31,"ну, это конечно не самое правильное поведение, но бывает, чего уж там. мы навестим кукольника",154244,null],[154262,"2026-08-12T10:44:46",7,"/ @dunchev хочу купить фруктов",112272,null],[154263,"2026-08-12T10:44:47",7,"/ покушац",112272,null],[154264,"2026-08-12T10:45:34",9,"//У меня 30 чёртовых рационов осталось, интересно скак это в местных деньгах 🤔",112272,null],[154265,"2026-08-12T10:45:49",9,"*Ридли интересуется о местных ценах на еду.*",112272,null],[158248,"2026-08-13T17:07:51",7,"/ :^",112272,null],[158284,"2026-08-13T17:26:06",17,"Вы можете закупиться тут провизией полноценный паёк примерно по золотому",112272,null],[158298,"2026-08-13T17:30:14",31,"Тарх оглядывается в поисках оружейной лавки, хочет купить пращу",112272,null],[158309,"2026-08-13T17:33:06",17,"Ты находишь небольшой закуток, это не оружейная лавка, оружее тут не продаётся, кузница оружия только для людей бургомистра\n\nНо пращу там где куют топоры для двровосеков ты можешь найти \n\n5 золотых",112272,null],[158321,"2026-08-13T17:37:51",31,"Покупаю пращу",112272,null],[158339,"2026-08-13T17:40:36",17,"/ ЧТо куда дальше",112272,null],[158344,"2026-08-13T17:41:06",60,"//еда, которую мне насыпали, это сколько в пайках?",158284,null],[158345,"2026-08-13T17:41:27",31,"Немея хотела фруктов, а так планировали к кукольнику, там  и задагка с куклами Ирины и убийца Янек/",112272,null],[158347,"2026-08-13T17:41:40",17,"/ 2",158344,null],[158368,"2026-08-13T17:48:35",17,"/ @Evreiskui_Department го играть паша нихуя тебе не разрешит, он консерватор",112272,null],[158378,"2026-08-13T17:52:14",7,"/ я буду Лениным, я возьму свою клятву гениев! \nНо играть тоже надо, ято по яблокам?",158368,null],[158379,"2026-08-13T17:52:31",7,"/ Немейя ищет фрукты побаловать себя",112272,null],[158380,"2026-08-13T17:52:34",17,"/ Да купи че те надо паёк тут 1 зм",112272,null],[158402,"2026-08-13T17:58:38",17,"/ Тут всё просто у вас есть карта, везде есть контент, идите и берите его",112272,null],[158406,"2026-08-13T17:59:25",7,"/ беру короче яблок корзину за 1 золотой.",158402,null],[158407,"2026-08-13T17:59:31",7,"/ яблок груш что было",112272,null],[158420,"2026-08-13T18:03:21",7,"*Немейя ненадолго отбилась от группы, ее и след простыл на рынке. Она позже приходит к ребятам с корзиной полной фруктов.*\n\n— Ребята! Фрукты будете? Я буду!\n\n*С этими словами девушка хватает яблоко и начинает постепенно кушать, параллельно протягивая корзину ребятам.*",112272,null],[158430,"2026-08-13T18:05:30",60,"—Мне лично уже отсыпали, есть ещё, спасибо.\n\nСказал фирболг, откусывая яблоко и осторожно перемещаясь по населённой местности, чтоб кого не раздавить",158420,null],[158467,"2026-08-13T18:09:22",7,"Немейя\n— Угу...\n\n* В голосе слышится лёгкое недовольство.*\n/  Ваш спутник помнит обиду.",158430,null],[158585,"2026-08-13T18:28:59",9,"*Ридли взял одно яблоко, но он в маске.*\n\n— Спасибо, позже съем.\n\n//Я тут ленивый игрок, сорян, остальные трое ведут группу основном :)",112272,null],[158607,"2026-08-13T18:32:05",17,"/ Ведут ага))))",112272,null],[158612,"2026-08-13T18:32:46",7,"/ ага)))",112272,null],[158617,"2026-08-13T18:33:00",7,"/ @QURTZZ",112272,null],[158638,"2026-08-13T18:36:49",9,"//Где наш всемогущий крестьянин",112272,null],[158641,"2026-08-13T18:37:09",9,"//Без него мы стоим и безыинициативны, негласный лидер)))",112272,null],[158643,"2026-08-13T18:37:34",17,"/ Я удивлён, мне когда ждать заёбывает я соло начинаю вылизывать весь контент",112272,null],[158646,"2026-08-13T18:37:39",17,"/ Тут тянем уже хуй знает сколько",112272,null],[158648,"2026-08-13T18:37:54",17,"/ А еще можно отыграть между собой разок другой и я может появлюсь и навалю кринжа",112272,null],[158649,"2026-08-13T18:37:59",9,"//У меня тут Ридли, я его не люблю, перс не нарится(",112272,null],[158676,"2026-08-13T18:42:56",31,"Беру предложенной Немеей яблоко, смачно в него вгрызаюсь, закидываю вилы на плечо и топаю между рыночных рядов в сторону магазина игрушек",112272,null],[158678,"2026-08-13T18:43:28",31,"Я бы и рад, но я же не выживу в одного)/",158643,null],[158679,"2026-08-13T18:43:32",9,"*Идёт следом.*",158676,null],[158682,"2026-08-13T18:44:20",7,"/ :___",158643,null],[158684,"2026-08-13T18:44:27",17,"/ Ну хочешь замени при случае на другого обывателя",158649,null],[158685,"2026-08-13T18:44:42",7,"/ или персонажа чтобы жили а не выживали",158684,null],[158691,"2026-08-13T18:45:17",17,"/ Да или перса",112272,null],[158692,"2026-08-13T18:45:24",9,"//Ну, я могу взять кого-то, ток Ридли надо где то оставить или прибить. Не люблю вот так выходить",158684,null],[158693,"2026-08-13T18:45:50",31,"Следующий монстр будет кидаться только на тебя/",158692,null],[158695,"2026-08-13T18:46:08",17,"/ Да я придумаю, ты только скажи",158692,null],[158696,"2026-08-13T18:46:22",9,"//Го в бою где нить, пока с вами",158695,null],[158700,"2026-08-13T18:46:44",9,"//Пусть с меня залутают вещей хотя бы",112272,null],[158709,"2026-08-13T18:48:05",17,"/ Ну тогда двигайтесь куда то",112272,null],[158711,"2026-08-13T18:48:10",31,"Глянь моего перса Оголодана. Он мимик. Если получится, я бы на него Тарха поменял. Хз как, можно Тарха скормить мимику, а тот окажется каким нибудь ментальным слепком с Оголодана и так он переродится в Багровии. Уровень у него как раз подходящий, третий//",158695,null],[158724,"2026-08-13T18:49:42",31,"Тарха жалко конечно, но у меня и так многовато персов, да всех играь не могу/",112272,null],[158734,"2026-08-13T18:50:54",31,"Перс мутант получится, Тархододан. Они кстати знакомы, Оголодан Тарха спас от вампира на квесте/",112272,null],[158737,"2026-08-13T18:51:34",17,"/ Завтра или ночью придумаю",158711,null],[158741,"2026-08-13T18:52:13",9,"//А я наверное не пойду тогда, мне сейчас сложно создать \"не\" обывателя. Хотя есть в планах юркий кобольд через арбалеты)",112272,null],[158748,"2026-08-13T18:52:42",17,"/ Ну создай обывателя который тебе будет нравится",112272,null],[158750,"2026-08-13T18:52:45",17,"/ И сюда его",112272,null],[158755,"2026-08-13T18:53:30",9,"//Я немного еще с командой похожу и останусь в городе по своим причинам",112272,null],[158758,"2026-08-13T18:54:42",9,"*Ридли пока щёл мимо лавок заметил несколько знакомых символов... это знаки Багрового Саванна, надо будет зайти к своим. Конечно команде он ничего не сказал.*",112272,null],[158760,"2026-08-13T18:54:55",9,"//Свалит домой по связям",112272,null],[158764,"2026-08-13T18:55:43",9,"*Пока идет с остальными, думает стоит ли покидать команду или нет.*",112272,null],[158831,"2026-08-13T19:06:45",7,"/ грустно же будет(",158700,null],[158839,"2026-08-13T19:07:52",7,"*Немейя не замечает пока пропажи. Она выглядит легкомысленной, кушая яблоко недоеденное и держа в левой руке корзину с яблоками.*",112272,null],[158908,"2026-08-13T19:27:51",7,"/ позже идем про копию спрашивать",112272,null],[159105,"2026-08-13T20:23:14",60,"/roll d20 ну-ка кину проницательность, может быть альф обратит на это внимание",158467,null],[159109,"2026-08-13T20:24:15",7,"/ ну ты замечаешь, потому что Немейя не то чтобы шифруется",159105,null],[159114,"2026-08-13T20:25:51",17,"/ Вот это куда вы идете. Что это значит?",158908,null],[159115,"2026-08-13T20:26:29",7,"/ куда ранее планировали через рынок попасть же. Я просто сам уже не помню... Щас пролистаю",159114,null],[159117,"2026-08-13T20:27:52",7,"/ Кукольник",158345,null],[159119,"2026-08-13T20:28:16",17,"/ а копия Ирины пон",112272,null],[159120,"2026-08-13T20:28:27",60,"//по карте это хз где",112272,null],[159121,"2026-08-13T20:28:34",60,"//быть может лавка игрушек",112272,null],[159123,"2026-08-13T20:28:48",17,"/ Да уж варвар",112272,null],[159124,"2026-08-13T20:28:50",17,"/ угадал",112272,null],[159254,"2026-08-14T07:44:41",17,"/Сёдня жесткая игра намечается",112272,null],[159255,"2026-08-14T07:45:02",17,"/ @QURTZZ Hard вопрос к вам, вы хотите сейчас поменять персов? Я могу устроить.",112272,null],[159256,"2026-08-14T07:45:54",17,"Лавка кукольного мастера Блинского",112272,null],[159257,"2026-08-14T07:46:35",17,"Между мрачными домами Валаки обнаруживается здание, которое словно отчаянно пытается притвориться весёлым.\nНад дверью раскачивается деревянная вывеска с нарисованными игрушками. Краска яркая, но выцветшая от дождей. В витрине стоят деревянные солдатики, куклы, заводные звери и маленький игрушечный гробик, из которого при движении рычажка высовывается вампир.\nРядом устроена целая праздничная композиция: улыбающееся деревянное солнце обнимает перепуганного ребёнка.\n\nИзнутри доносится тихое\n\nтик-тик-тик-тик.\n\nА затем звон маленького колокольчика.",112272,null],[159259,"2026-08-14T07:47:33",17,"На витрине множество игрушек\n\nДеревянный волк, который кусает собственный хвост\n\nКукла-палач с вынимающимся топором\n\nШкатулка, из которой вместо балерины поднимается маленький призрак\n\nФигурка бургомистра с механически поднимающимися руками. Последняя, конечно, официально называется «Счастливый руководитель».",112272,null],[159262,"2026-08-14T07:49:38",31,"Я хочу мутировать в Тархолодана/",159255,null],[159263,"2026-08-14T07:50:28",17,"Перед тем как вы пришли к лавке блинского Тарх заметил в тёмной подворотне Мужчину, очень напоминающего его самого, он подзывал его к себе",112272,null],[159265,"2026-08-14T07:50:57",31,"- что за нахер?\n\nПодхожу",159263,null],[159266,"2026-08-14T07:51:18",17,"/ Отыграй как мимик съел тарха и мутировал в его тело",112272,null],[159267,"2026-08-14T07:51:21",17,"/ ВОт и всё)))",112272,null],[159268,"2026-08-14T07:52:20",17,"/ Импостер в пати",112272,null],[159269,"2026-08-14T07:52:53",31,"Это же должен быть не какой то случайный мимик, а знакомый))// ща придумаю//",112272,null],[159270,"2026-08-14T07:53:11",17,"/ Давай придумай)",112272,null],[159271,"2026-08-14T07:53:37",17,"/ Может оголодан присмерти и ему нужно тело новое, как симбиоту",112272,null],[159272,"2026-08-14T07:53:50",31,"Ага, Веном такой/",112272,null],[159275,"2026-08-14T07:56:27",17,"/ Че сам напишешь пост или мне че нить написать?",112272,null],[159276,"2026-08-14T07:57:45",31,"Оголодан, очень херово выглядит:\n\n- Привет, Тарх, давно не виделись. Прости что украл твой облик, в этом месте носить свой больно, тут какая то неправильная магия, она уничтожает и извращает суть моей природы. Я тут не выживу без помощи, мне нужен носитель. Но учти, это навсегда\n\nТарх: \n\n- ну, ты меня вытащил, так что не вижу смысла тебе не верить. Да и сам устал быть слабаком\n\nХерак, симбиот готов//",112272,null],[159278,"2026-08-14T07:59:07",31,"Статблок от Оголодана, потом пропишу что осталось от Тарха",112272,null],[159279,"2026-08-14T07:59:31",31,"- какой охеренный топор у меня теперь появился",112272,null],[159280,"2026-08-14T07:59:43",17,"/ Можешь увеличить значения характеристик на +1 всех",112272,null],[159281,"2026-08-14T08:00:05",17,"/ Как тебя звать?",112272,null],[159282,"2026-08-14T08:00:13",17,"/ МЫ ТАРХУУУУУН",112272,null],[159283,"2026-08-14T08:00:48",31,"Тархолодан, можно Тархун или Тарх, как и прежде. Лицо тоже, пасти и глаза я уже научился прятать/",112272,null],[159284,"2026-08-14T08:05:52",17,"/ Вся память, желания и стремления Тарха перешли оголодану в целости",112272,null],[159285,"2026-08-14T08:06:37",31,"Ок/",112272,null],[159288,"2026-08-14T08:21:21",31,"Тарх выходит из переулка, топает с остальными в магазин игрушек и в целом выглядит почти также как раньше, разве что словно чуть крупнее стал и теперь его вилу за спиной, а в руках немалая такая двуручная секира",112272,null],[159289,"2026-08-14T08:33:47",31,"- однако, игрушки то тут не сказать что веселые. будь у меня в детсет такия, я был бы конечно очень счастливым. и седым скорее всего",159259,null],[159300,"2026-08-14T09:57:28",9,"//У меня не на кого пока что",159255,null],[159301,"2026-08-14T09:57:59",17,"/ Окей жду пока кто то скажет \"Мы заходим\" или чето такое",159300,null],[159302,"2026-08-14T10:01:38",9,"— Я не могу здесь более оставаться, мне наверное пора. Простите. — *Ридли некоторое время повагался, подумал и в руках у него появился комплект одеждаы в который было что-то завёрнуто.* — Буду только мешать и вы не обязанны меня беречь. Немея, ты красавица, сожги того кто скажет иначе. Альфарий, надебсь мы всё ещё встретимся, в другой раз.",112272,null],[159303,"2026-08-14T10:03:02",9,"*Парень вам передаёт куль из одёжки в котором есть несколько полезных вещей, и снимает маску.*\n\n— Надеюсь, мы ещё встретимся, свет озарит вам путь.",112272,null],[159306,"2026-08-14T10:05:47",9,"Отдал Команде:\n\n— \"Простая одежда\" в которую завёрнуты припасы.\n— Рационы 13 шт.\n— Цепи 2 шт\n\nPs: С инвентаря не списал, п4рса закрываю, но если открою — не забудь Хард!",112272,null],[159307,"2026-08-14T10:07:10",9,"//Если у вас есть что сказать перед тем как перс свалит — говорите",112272,null],[159308,"2026-08-14T10:07:12",17,"/ Хард ты перса пока делай",112272,null],[159417,"2026-08-14T13:51:48",17,"/  @Evreiskui_Department @FSmit7 вы че там? двигаемся?",112272,null],[159490,"2026-08-14T14:20:17",60,"//если никого не ждём то да, к кукольнику",159417,null],[159573,"2026-08-14T14:33:16",31,"Я вернулся. Если никого не смущает появление у меня двуручной секиры, то идем",112272,null],[159611,"2026-08-14T15:13:53",7,"/ я щас чутка занят :_\nПростите",159417,null],[160021,"2026-08-14T18:45:41",7,"*Видно, как Немейя расстроилась. Она прикусив губу, бросает остатки яблока. Обняв Ридли на прощание, она создает из огня довольное лицо, в знак прощания.*\n\n— Обязательно сожгу тех, кто скажет иначе. Обязательно, только береги себя.\n\n*После отходит и провожает взглядом, что был частично грустным.*\n\n— Чтож... Пойдем к кукольнику... Я думаю, что у нас есть дела.",159302,null],[161041,"2026-08-15T10:33:56",60,"//ну мы на рыночной площади, так что.. Не особо",159573,null],[161140,"2026-08-15T11:28:37",7,"/ я же корзину с яблоками купил также)",161041,null],[161167,"2026-08-15T12:01:01",7,"/ если что мы думаю все готовы...",112272,null],[161187,"2026-08-15T12:13:28",17,"/ Щас гайз",112272,null],[161188,"2026-08-15T12:13:35",17,"/ Я в выходные урывками беру телефон",112272,null],[161435,"2026-08-15T14:23:36",17,"Колокольчик над дверью звякает.\n\nВнутри почти не осталось свободных стен.\n\nПолки от пола до потолка заставлены игрушками: расписными куклами, деревянными зверями, крошечными каретами, марионетками, музыкальными шкатулками и заводными механизмами. Многие выглядят немного… неправильно. У одной куклы слишком много зубов. У плюшевого волка пришиты человеческие сапожки. Маленькая виселица исправно поднимает и опускает деревянного человечка.\n\nИ всё же работа великолепна. Тонкие шарниры, резьба, миниатюрные шестерёнки — вещи сделаны руками настоящего мастера.\n\nПо высокой полке над вашими головами пробегает маленькая обезьянка в нелепой одежде. Она останавливается, смотрит на вас и торжественно снимает крошечную шапочку.\n\nИз-за занавеса появляется хозяин.\n\n— Покупатели!\n\nМужчина широко раскидывает руки.\n\n— Или ценители? Пожалуйста, скажите, что ценители.",112272,null],[161440,"2026-08-15T14:27:48",17,"— Гадоф Блинский! Игрушечник, мастер, предприниматель и человек с совершенно катастрофическими финансовыми решениями.\n\nБлинский кланяется.\n\nОбезьянка наверху немедленно повторяет поклон.\n\n— А это Пикколо. Он отвечает за отношения с покупателями.\n\nПикколо протягивает лапку.\n\n— Я отвечаю за всё остальное.\n\nБлинский некоторое время смотрит на обезьянку.\n\n— Поэтому дела идут плохо.",112272,null],[161442,"2026-08-15T14:28:12",41,"( туда мне надо...",112272,null],[161452,"2026-08-15T14:30:40",17,"Гадоф Блински. Мастер игрушечник.",112272,null],[161453,"2026-08-15T14:31:13",17,"Пикколо. Ручная обезьянка Блински. Чей то подарок.",112272,null],[161474,"2026-08-15T14:38:54",31,"- пожалуй, мы и правда ценители. У меня в детстве не было игрушек, кроме тех что отец мог вырезать из дерева, и обычно было непонятно, что там получилось, сова или медведь. Так что теперь я у вас как в музее",112272,null],[161476,"2026-08-15T14:40:07",60,"—Доброго.. Времени. Любопытное место, и обезьянка на меня похожа немного.. В общем. Мы по делу. Кто-то брал куклу в виде одной нашей знакомой.\n\nСказал Альф, ведя себя как слон в посудной лавке, из-за чего старался быть осторожнее",161435,null],[161482,"2026-08-15T14:42:30",17,"— Куклу? В виде вашей знакомой?..\n\nОн задумывается.\n\n— Извините так и не припомню. Я иногда делаю кукол с лицами людей, по описаниям это правда. Но таких заказов были уже десятки. Можете уточнить?",112272,null],[161487,"2026-08-15T14:43:50",31,"- мы говорим о заказе Айзека, я не уверен в его должности, но очевидно он большой человек в страже или охране бургомистра",112272,null],[161491,"2026-08-15T14:44:47",17,"Видно как жизнерадостный весельчак Блински погруснел\n\n— Простите я не буду обсуждать заказы этого господина.",112272,null],[161499,"2026-08-15T14:46:13",31,"//народ, бросьте на убеждение, у меня просто с харизмой беда//",112272,null],[161504,"2026-08-15T14:46:54",17,"/ Проницательность, убеждение, обман любое",112272,null],[161505,"2026-08-15T14:46:58",17,"/ Запугивание",112272,null],[161512,"2026-08-15T14:48:10",31,"/roll d20+2 проницательность",112272,null],[161515,"2026-08-15T14:48:41",17,"Ты видишь, что Блински боится говорить. Айзек запугал его. Заставляет делать то, что он не хочет",161512,null],[161516,"2026-08-15T14:48:55",17,"Прочитав его как открытую книгу ты можешь это уверено заключить",112272,null],[161526,"2026-08-15T14:51:49",31,"- мастер Блинский, не переживайте, дальше нас это не пойдет. Должен вам сказать, мы были наняты чтобы охранять девушку, лицо которой у созданной вами куклы. И если Айзек как то с ней связан, нам нужно это знать. Возможно, он мог бы нам помочь спасти ее",112272,null],[161530,"2026-08-15T14:52:41",17,"/ Убеждение с преимуществом",112272,null],[161535,"2026-08-15T14:53:36",31,"/roll +d20-1",161530,null],[161538,"2026-08-15T14:53:48",31,"Прощу помощи//",112272,null],[161598,"2026-08-15T15:23:14",17,"/ @FSmit7  @Evreiskui_Department  алоооо",112272,null],[161619,"2026-08-15T15:28:33",60,"—Да. Мы наёмники. Не распространяемся о предметах найма. Но если что.. Вы будете в подозреваемых, когда что-то случится.\n\nСказал альф, слегка встряхивая светящийся меч за спиной, как бы поправляя рюкзак",161526,null],[161620,"2026-08-15T15:29:25",17,"— Эм... Простите? Что вы имеете ввиду?",161619,null],[161621,"2026-08-15T15:29:33",17,"/ Это запугивание чтоль?",112272,null],[161622,"2026-08-15T15:29:45",17,"/ Кстате вы забыли про необычного мальчика убийцу",112272,null],[161626,"2026-08-15T15:33:37",7,"/ ну вовремя, когда отхожу",161435,null],[161628,"2026-08-15T15:34:25",7,"/ я кушал :__",161598,null],[161629,"2026-08-15T15:36:01",17,"/ Ладно ладно. Оправдан.\n\n\"Удар судейского молотка\"",112272,null],[161630,"2026-08-15T15:36:52",7,"*Немейя зайдя, остывает на месте. Она смотрит на игрушки, будто что то диковенькое. Новенькое будто. Она в частичном изумлении осматривает куколки и на ладони даже попыталась сделать копию из огня. Однако быстро приходит в себя, после чего говорит.*\n\n— Здравствуйте, мы работы осмотреть бы хотели. Могли бы представить куколки пожалуйста? Они выглядят... Необычно...",112272,null],[161631,"2026-08-15T15:37:02",60,"—Имею ввиду, что люди могут пострадать невинные. Будьте добры, помогите расследованию.",161620,null],[161632,"2026-08-15T15:37:05",7,"/ блять там угрозы кидают",161619,null],[161633,"2026-08-15T15:37:43",17,"— Я.. я ничего не знаю. Особенно про заказы мистера Айзека лучезарного капитана стражи Валаки.",161631,null],[161634,"2026-08-15T15:38:03",17,"Пикколо смотрит за Блински с укором",112272,null],[161635,"2026-08-15T15:40:59",31,"- ладно, сменим тему. По дороге мы встретили встречоженных детей, их товарищ Янек вроде как очень странно себя ведет и скрылся в вашем магазине. Расскажите, что с ним не так, все ли в порядке с ребенком?",112272,null],[161652,"2026-08-15T15:51:09",17,"— Да, что ж такое. Вы покупатели или устраиваете мне допрос?",112272,null],[161654,"2026-08-15T15:51:40",17,"Пикколо подпрыгивает на месте и тычет пальцев в шокированного Блински",112272,null],[161655,"2026-08-15T15:51:50",17,"По обезьяни смеется",112272,null],[161656,"2026-08-15T15:53:17",60,"—Скорее второе. Работаем же, дел немало. Нам нужна эта информация, чтобы продолжать работу. Я.. Могу заплатить, сколько есть.",161652,null],[161659,"2026-08-15T15:55:42",31,"- ну, ничто не мешает нам совмещать эти роли. Я бы с удовольствием купил что то на память",112272,null],[161661,"2026-08-15T15:56:59",7,"Немейя\n— Извините, а я могу глянуть на работы? Пожалуйста. \n\n/ Хочу среди кукл найти копию Арины вроде, вроде так девушку звали которую граф украл",112272,null],[161664,"2026-08-15T15:57:52",17,"/ Ирина звали. Тут нет такой куклы",112272,null],[161665,"2026-08-15T15:58:47",7,"/ подозрительно...",161664,null],[161746,"2026-08-15T16:27:01",7,"/ так, @FSmit7 @QURTZZ господа. Мы здесь чисто узнать откуда кукла копия Ирины же?",112272,null],[161752,"2026-08-15T16:29:00",7,"/ но куклы нет, значит она либо в подвале, либо забрана...",112272,null],[161753,"2026-08-15T16:29:05",31,"Не только, по дороге еще пацаны намекнули на пацана маньяка, который тут прячется. И дв, мы хотим узнать на кой хер стражнику кукла с лицом Ирины, моя ставка - Айзек ее воздыхатель и хотел сделать себе типа фотку на память. Я вообще хочу его к нам в пати затащить как сюпосощника против графа//",161746,null],[161754,"2026-08-15T16:29:31",7,"/ давай!",161753,null],[161765,"2026-08-15T16:30:51",7,"*Немейя не обнаружив Ирину, грустно вздыхает. Она выглядит довольно задумчиво.*\n\n— А можно посмотреть на ваше искусство, куклы что вы храните? Я бы с удовольствием рассмотрела ваше искусство! Оно выглядит... Обжигающе красиво!\n\n/ Убеждение? @dunchev",112272,null],[161779,"2026-08-15T16:35:02",17,"/ Убеждение с преимуществом",112272,null],[161782,"2026-08-15T16:35:59",7,"/r +d20 +6",112272,null],[161784,"2026-08-15T16:36:27",17,"— Чтоооож. Девушка жива? Скажите мне",112272,null],[161791,"2026-08-15T16:42:11",31,"- когда мы видели ее в последний раз, была жива",112272,null],[161797,"2026-08-15T16:44:50",7,"Немейя\n— Угу... Жива...",112272,null],[161798,"2026-08-15T16:44:50",60,"//не будем уточнять обстоятельства",161791,null],[161802,"2026-08-15T16:45:51",17,"Он вздыхает...\n\n\n— Да.. я делал несколько кукол, точнее несколько десятков для капитана. Что вы хотите знать? Он надиктовывал мне ее образ по памяти. Говорил что четко видит ее во снах.",112272,null],[161805,"2026-08-15T16:47:51",7,"Немейя\n— Ох, сны... Чтож, звучит как то... Грустно даже. Ну чтож, благодарю за информацию, он к вам заходил ещё ранее до нас?",112272,null],[161812,"2026-08-15T16:50:42",17,"— Я недавно отдал ему новую куклу в этот раз не в полный рост он заказывал. Верно курьер уже доставил",112272,null],[161816,"2026-08-15T16:51:54",17,"— Что касается Янека... О мой мальчик. Он потерялся. Сбежал и я не могу его найти. В последний раз он прибежал ко мне весь... В крови... Представляете. Потом ещё приходила страда, допрашивали. Но... Тут я не причем. Я сделал его и он вдруг ожил.",112272,null],[161819,"2026-08-15T16:52:20",17,"— Если бы вы нашли его. Приведите ко мне. Я щедро заплачу вам. Он уникален.",112272,null],[161822,"2026-08-15T16:53:11",31,"- простите, что? Ваша игрушка ожила?!",161816,null],[161833,"2026-08-15T16:56:15",7,"Немейя\n— Вау, ожившая игрушка... А она из дерева? А какой у нее раскрас?",112272,null],[161834,"2026-08-15T16:56:46",17,"— Да. Я создал игрушку мальчика. Старался сделать его особенным. И на утро... Удивился. Он разговаривал. Думал и чувствовал! Как живой!",112272,null],[161837,"2026-08-15T16:57:47",17,"— Мальчик из металла. Алюминий и сталь. Немного деревянных вставок.",112272,null],[161838,"2026-08-15T16:58:02",31,"- и другие дети не поняли его природы?",112272,null],[161845,"2026-08-15T16:59:32",7,"*Немейя начала задумываться... Случайно не связаны ли рассказы о мальчике убийце с его словами... Магия не стабильна, детская обида... Она можно сказать себя вспомнила, как подожгла и бежала с приюта. Этими мыслями она ожидала товарищей, чтобы им сказать о своим подозрениях.*\n\n— Угу, спасибо...",112272,null],[161882,"2026-08-15T17:14:20",17,"— О.. я не знаю. Видел в окно как другие били его... Я хотел с ним поговорить но вечером он прибежал в крови и ... После сбежал из дома",161838,null],[161883,"2026-08-15T17:16:40",31,"- а откуда у него кровь? Он кого то обидел? И где вы посоветуете начать поиски?",161882,null],[161887,"2026-08-15T17:19:16",17,"— Он... Он сказал что толкнул мальчика в ответ на то что его обижали...",112272,null],[161889,"2026-08-15T17:19:36",17,"— А после просто закрыл лицо руками и убежал прочь",112272,null],[161934,"2026-08-15T18:25:20",17,"/ м?",112272,null],[161939,"2026-08-15T18:36:25",60,"Альф стоит молча и кивает с серьезным лицом. Он не в курсе о части происходящего и сам пытается вникнуть в суть",112272,null],[161940,"2026-08-15T18:37:20",17,"/ Ну ладно ждём движухи. Вопросов или чего то",112272,null],[161941,"2026-08-15T18:38:12",7,"Немейя\n— А как давно он убежал? Две три луны назад?",161889,null],[161942,"2026-08-15T18:40:11",17,"— Позавчера",161941,null],[161954,"2026-08-15T18:45:41",7,"Немейя\n— Луну назад... Хм... Мальчики, поищем того железного мальчика? Я думаю... Что могу предположить, где он. Пожалуйста, время же есть до сеанса?",112272,null],[161963,"2026-08-15T18:52:20",31,"- да, давайте займемся поисками. Не хотелось бы чтобы парень кого то поранил",112272,null],[161970,"2026-08-15T18:53:29",7,"/ @FSmit7 @",112272,null],[161971,"2026-08-15T18:53:39",7,"/ а хард перса поменял? Я забыл...",112272,null],[161974,"2026-08-15T18:54:23",9,"//Хотел, но не смог создать, наверное без меня. Тоесть у меня есть все 3 перса, а идей для новых нет.",112272,null],[161976,"2026-08-15T18:55:10",9,"//Тамблер вам тут точно не надо, его полезность заканчивается на уровне кастонуть \"понимание языков\" раз в день",112272,null],[161977,"2026-08-15T18:55:12",17,"/ Хард возможно потом залетит к группе 2. Если захочет",112272,null],[161979,"2026-08-15T18:56:21",7,"/ грустно... Не забудем Ридли:___",161976,null],[161983,"2026-08-15T19:02:00",17,"— У меня из лавки пропал наборчик инструментов и маслёнка. Точно помню они были. Может Янек прихватил. Пожалуйста не навредить ему. Он всего лишь ребенок.",112272,null],[161984,"2026-08-15T19:02:31",31,"- хмм, зачем ему это? Хочет себя починить или исправить?",112272,null],[161985,"2026-08-15T19:02:42",17,"— А ещё... Если сменить тему. Дошли слухи что утром на площади солнца был механизм, тигр! Это правда? Расскажите если видели, прошу вас! Это так интересно.",112272,null],[161987,"2026-08-15T19:03:03",31,"- думаю, нужно поболтать с местными пацанами, наверняка кто то что то видел",112272,null],[161988,"2026-08-15T19:03:03",17,"— Да, вероятно. Или может он захотел что то себе добавить... Я не знаю.",161984,null],[161989,"2026-08-15T19:03:50",31,"- да, был, довольно страшная тварь, но господин Риктавио ее быстро угомонил. Он ваш коллега, я полагаю?",161985,null],[161990,"2026-08-15T19:04:05",17,"— Скажу чесно. Он намного сильнее обычного мальчика. Скорее всего он опасен. Но потому что испуган. Опасный не всегда значит, что злой, верно?",112272,null],[161991,"2026-08-15T19:04:10",7,"Немейя\n— Позже расскажу, когда придем с вашим сыном. Я снаружи подожду, пока обдумаю...",161985,null],[161992,"2026-08-15T19:05:02",17,"— Ооо Рик! Да. Это он подарил мне Пикколо. Замечательный человек. И гений в полном смысле. А эти его колометы, многозарядные арбалеты и великолепные бомбочки с чесноком. Такое искусство!",161989,null],[161994,"2026-08-15T19:07:35",31,"- Колометы? Бомбы с чесноком? Похоже он не только игрушки делает, но и оружие для борьбы с нечистью делает. Любопытно... Надо бы его еще разок увидеть и поболтать",161992,null],[161995,"2026-08-15T19:12:45",17,"— Ооо нет. Игрушки он вообще не делает.",161994,null],[161996,"2026-08-15T19:13:05",31,"- а тигр это что?",161995,null],[161997,"2026-08-15T19:13:49",17,"— Вероятно его боевая единица. Против нечисти. \n\nОн перекрывает рукой рот\n\n— Ой, я же обещал никому не рассказывать. Забудьте пожалуйста! И не говорите, что я проболтался.",112272,null],[161998,"2026-08-15T19:14:48",31,"- договорились",112272,null],[161999,"2026-08-15T19:15:22",31,"- ладно, ребята, кажется нам пора.",112272,null],[162000,"2026-08-15T19:15:53",31,"Выходим на улицу. Оглядываюсь в поисках местной пацанвы",112272,null],[162001,"2026-08-15T19:17:32",17,"Они играют в ножички в переулке",162000,null],[162008,"2026-08-15T19:25:15",31,"Подхожу\n\n- привет парни. Неплохо у вас получается. Можно мне тоже попробовать, детство дать вспомню?",162001,null],[162009,"2026-08-15T19:25:31",31,"/roll d20-1 убеждение",112272,null],[162011,"2026-08-15T19:25:57",31,"Выгнали с криком педофил//",112272,null],[162014,"2026-08-15T19:28:42",60,"—А я сильнее взрослых мальчиков. Если придётся тащить его силой, то в этом проблем не будет. Особенно если он убийца.",161990,null],[162023,"2026-08-15T19:36:20",17,"— Нет нет. Что вы он и мухи не обидит!",162014,null],[162024,"2026-08-15T19:36:42",17,"— Дядь, чё надо?",162011,null],[162025,"2026-08-15T19:37:13",60,"—На то и уповаю. Люди нынче всякие бывают.. Особенно в таких хороших местах.",162023,null],[162026,"2026-08-15T19:38:49",31,"- ладно, вас не проведешь. Я Янека ищу, он говорят куда то в слезах убежал, не знаете куда? Отец его волнуется сильно, как бы чего не вышло",162024,null],[162027,"2026-08-15T19:43:11",17,"— Он убийца сраный. Зачем его ищите? Убьете его?",162026,null],[162029,"2026-08-15T19:43:45",31,"- а кого он убил? Я об этом не слышал",112272,null],[162031,"2026-08-15T19:45:20",17,"— Жору замочил, над. Мальчика 7 лет",112272,null],[162033,"2026-08-15T19:45:45",31,"- как это произошло? Вы уверены что это он сделал?",112272,null],[162034,"2026-08-15T19:46:23",17,"— Ну мы над ним прикалывались. Толкали чутка. Он Жору в ответ толкнул так что насквозь его пробил руками и кишки наружу... Это просто ужас дядь",112272,null],[162036,"2026-08-15T19:48:30",31,"- какой кошмар. Его нужно найти, пока он еще кого то не ранил. Не знаете где он может прятаться?",112272,null],[162045,"2026-08-15T19:52:38",17,"— Не знаем... Мы видели последний раз как он бежал в башню часовщика и убежали прочь, дядь",162036,null],[162066,"2026-08-15T20:00:28",7,"*Немейя осматривалась и принимала информацию. Она примерно помнила, где находится башня, от чего подошла и на ухо прошептала Тарху.*\n\n— Я полечу проверю башню, если что будет подам знак, ну или можете сами прийти. Я быстрее проверю. Не против?",162036,null],[162070,"2026-08-15T20:04:14",31,"- конечно, это лучшее решение, лети",162066,null],[162073,"2026-08-15T20:05:37",7,"*Получив одобрение, девушка выпревляет крылья, также протягивая руки. Это было сопровождено огненными искрами, будто птица готовилась взлететь. Полетев, она направляется в сторону башни, дабы отыскать мальчика.*",112272,null],[162267,"2026-08-15T22:13:50",7,"/ если шо я в башню полетел первее всех чтобы срезать",112272,null],[162667,"2026-08-16T16:16:02",31,"Отправляюсь вслед за улетевшей Немеей",112272,null],[162710,"2026-08-16T17:04:10",17,"/ щас я колупаюсь на улице с бассейном и ещё траву покормить надо",112272,null],[162718,"2026-08-16T17:14:41",7,"/ траву покормить, камень выгулять",162710,null],[162720,"2026-08-16T17:17:42",17,"/ ))",112272,null],[162724,"2026-08-16T17:19:05",31,"Я машину бросил в городе, уехал домой, тут сука бойлер надо почистить. Пиздец а не воскресенье//",112272,null],[163334,"2026-08-17T09:31:32",17,"Башня Часовщика в Валаки",112272,null],[163336,"2026-08-17T09:32:34",17,"Среди тесных домов поднимается узкая башня из потемневшего камня и дерева.\n\nБольшие часы под самой крышей давно остановились: стрелки показывают без четверти три.\n\nНесколько окон заколочены, но одно окно наверху приоткрыто. Из него на ветру покачивается тонкая полоска ткани.\n\nГде-то внутри раздаётся один металлический удар.\n\nДзинь.\n\nИ снова тишина.",112272,null],[163338,"2026-08-17T09:32:52",17,"Немея летит к башне \n\n/Восприятие",112272,null],[163339,"2026-08-17T09:33:18",17,"Тарх бежит вместе с Альфом по земле ко входу, но пока не добрались, летающий тифлинг куда быстрее",112272,null],[163387,"2026-08-17T10:23:04",7,"/r d20 +2",163338,null],[163389,"2026-08-17T10:24:50",17,"Ты летишь прямо к открытому окну и не замечаешь натянутую леску, где то в глубине сразу же звонит будильник",112272,null],[163391,"2026-08-17T10:24:59",17,"Его кто то выключает",112272,null],[163393,"2026-08-17T10:25:15",17,"За окном находится тесная комната, заполненная внутренностями часов.\n\nШестерни лежат кучами на полу. Со стены свисают цепи. На столе разложены отвёртки, напильники и маленькие кусочки дерева.\n\nВ углу стоит зеркало.\n\nПеред зеркалом — несколько вырезанных деревянных лиц.\n\nДетских.\n\nУ одного слишком широкая улыбка. У второго слишком большие глаза. У третьего вообще нет рта.",112272,null],[163396,"2026-08-17T10:26:12",17,"/Расследование",112272,null],[163397,"2026-08-17T10:26:38",7,"/r d20 земля мне пухом)",112272,null],[163400,"2026-08-17T10:28:08",17,"Тут много чего разбросано маталлические пальцы, куски исскуственной кожи, масло, иголка и нитка, десткий букварь",112272,null],[163402,"2026-08-17T10:28:21",17,"Из-за большого часового механизма голос",112272,null],[163403,"2026-08-17T10:28:26",17,"— Ты от Блинского?\n\nГолос детский.\n\n— Он сказал тебе, что я сделал?",112272,null],[163406,"2026-08-17T10:31:29",7,"*Немейя зайдя, осматривается. Рядом парит огненный шарик, что частично освещает ярче чем свет от окна. Осмотревшись и услышав детский голос, девушка улыбнулась. Она достаёт яблоко из рюкзака.*\n\n— А ты так понимаю мальчик из железа? Подойди, не бойся, я не обижу тебя. \n\n*Говорит спокойным голосом девушка. Она присаживается на корточки, сложив крылья и ожидая когда появится мальчик. По крайней мере надеется на беседу.*",163403,null],[163410,"2026-08-17T10:39:49",17,"Остальные добегают в этот момент до заколоченной двери \n\n/ @QURTZZ @FSmit7",112272,null],[163412,"2026-08-17T10:40:47",7,"/ мне на убеждение кинуть? Может он испуган",112272,null],[163415,"2026-08-17T10:42:12",17,"/ Нет щас посмотрим что сделают остальные",112272,null],[163416,"2026-08-17T10:42:13",60,"Альф подбегает, неуклюже тормозит и трижды стучится в дверь, стараясь выглядеть более дружелюбно. Он использует маскировку и становится на вид как обычный человек, весьма бедный на вид с испещеренным морщинами лицом",163410,null],[163418,"2026-08-17T10:42:35",17,"— Кто это там? Вы пришли меня схватить?!",112272,null],[163420,"2026-08-17T10:43:09",31,"- мы пришли помочь Янек",112272,null],[163424,"2026-08-17T10:44:08",17,"/ Он не слышит это высоко от вас",163420,null],[163426,"2026-08-17T10:44:34",31,"Сорян, думал он стук услышал//",112272,null],[163427,"2026-08-17T10:44:46",17,"/ Ну на стук там тоже леска и тд",112272,null],[163430,"2026-08-17T10:46:18",7,"*Девушка услышав шаги, закатывает глаза. Она бросает в окно огненный шар, что создаст надпись.*\n\n\" Не тревожить, пока не подам сигнал. \"\n\n*После нескольких секунд оно сжимается в шарик, будто если он потухнет... То это сигнал к действию.*\n\n— Лично я поговорить хочу. Выйди на свет, я тебя не обижу, обещаю.\n\n/ Убеждение?",112272,null],[163486,"2026-08-17T11:14:06",17,"/ Убеждение да",112272,null],[163491,"2026-08-17T11:19:21",7,"/r d20 +6 Дормаму, я пришел договориться",112272,null],[163506,"2026-08-17T11:24:40",17,"Из-за огромной бронзовой шестерни появляется лицо ребёнка.\n\nНа первый взгляд — обычный мальчик.\n\nПотом становится заметна тонкая линия металлического шарнира у шеи.\n\nОдна щека повреждена, и под кожей виднеется гладкое дерево.\n\nОн смотрит на тебя.\n\n— Ладно. Вы пришли вернуть меня?\n\n— Или разобрать?",112272,null],[163508,"2026-08-17T11:24:58",17,"Янек.",112272,null],[163512,"2026-08-17T11:28:46",17,"/Внизу че делаете?",112272,null],[163515,"2026-08-17T11:30:18",7,"*Увидев мальчика, девушка опускает голову слегка вбок, на левое плечо.*\n\n— Ну, ты почти прав. Поговорить не хочешь? Выглядишь плоховато.\n\n*Говорит Немейя довольно спокойным голосом. Можно сказать даже слегка веселым выражением лица, но не издевательски, а скорее... Будто зацепил интерес.*",163506,null],[163517,"2026-08-17T11:31:27",17,"— Я убрал лишнее и усилил себя. В этом мире меня обижают. Я буду теперь защищаться, так и знайте!",163515,null],[163519,"2026-08-17T11:33:02",7,"Немейя\n— Хех, правильный подход, со стороны морали. Но зачем ты себя ломал, чтобы сделать таким? Ммм? Знаешь ли, делать себе больно чутка не правильно.",163517,null],[163521,"2026-08-17T11:33:51",17,"— Да мне... Не больно. И когда камнями кидались и когда толкали не больно. Но как то грусно и вот очень обидно.",112272,null],[163522,"2026-08-17T11:35:43",31,"- Альф, может выломаем дверь? Чует мое сердце, там может быть опасно для Немеи",163512,null],[163523,"2026-08-17T11:36:22",7,"Немейя\n— Ну, это другой вид боли. Дай угадаю, ты... Ммм... Ты толкнул мальчика? Тот упал и с него красная жидкость потекла, правильно?",163521,null],[163524,"2026-08-17T11:36:33",17,"— Почему я какой то не такой? Я не понимаю",163519,null],[163538,"2026-08-17T11:44:26",7,"/ :^",112272,null],[163550,"2026-08-17T11:55:15",17,"— Да, я испугался, я не хотел этого...",163523,null],[163551,"2026-08-17T11:56:07",7,"Немейя\n— А что он сделал до этого? Как ты думаешь, заслужил ли он такой участи?",112272,null],[163563,"2026-08-17T12:07:42",60,"—Да. Никогда не открывают.. Но тут осторожно надо. Дело техники.\n\nАльф впал в ярость и приставил клинок между стеной и дверью, чтобы ударом вниз сбить замок/засов с той стороны и дверь открылась без нереально громкого шума",163522,null],[163587,"2026-08-17T12:20:17",17,"В Альфа летит арбалетный болт",112272,null],[163588,"2026-08-17T12:20:21",17,"/ Спас ловкости",112272,null],[163589,"2026-08-17T12:20:42",17,"— Не знаю. Они обзывались, говорили что я игрушка, кидали камнями и пинали меня",163551,null],[163593,"2026-08-17T12:21:32",60,"/roll +1 похер, прорвёмся!",163588,null],[163603,"2026-08-17T12:24:04",17,"Болт пролетает по касательной ты успел среагировать",112272,null],[163604,"2026-08-17T12:24:25",17,"Дверь открыта, арбалет системой лесок был взведён как ловушка, впереди видна лестница на второй этаж",112272,null],[163605,"2026-08-17T12:24:28",17,"Что делаете?",112272,null],[163607,"2026-08-17T12:25:55",60,"Альф тихой поступью, внимательно осматриваясь на наличие ловушек, движется вперёд, к лестнице, подслушивая диалог по возможности",112272,null],[163609,"2026-08-17T12:26:23",60,"//Вот я думаю, а можно ли будет если вдруг поменять альфу класс с альт варвара на варвара 24е?",112272,null],[163621,"2026-08-17T12:29:16",7,"Немейя\n— И они не правы. Ты думать можешь, чувствовать как вижу. Как насчёт того, чтобы... Вернуться к Блинскому? Он тоскует по тебе. Но сначала надо тебя привести в порядок. Что думаешь?",163589,null],[163662,"2026-08-17T12:49:22",17,"/ Hard",163609,null],[163663,"2026-08-17T12:49:32",17,"/Внимание",163607,null],[163665,"2026-08-17T12:50:18",60,"/roll d20+3 слепой варвар",163663,null],[163668,"2026-08-17T12:51:32",17,"Ты наступаешь на колючки, а с потолка на етбя летит заточеная большая стрелка от часов",163665,null],[163669,"2026-08-17T12:51:34",17,"/Спас ловкости",112272,null],[163670,"2026-08-17T12:51:40",17,"/r d4 Колючки",112272,null],[163674,"2026-08-17T12:52:06",60,"/roll +1 да тут дохера всего",112272,null],[163676,"2026-08-17T12:52:21",17,"/r 2d6 Уебало стрелкой",112272,null],[163679,"2026-08-17T12:53:06",60,"Альф 40/46",112272,null],[163684,"2026-08-17T12:53:47",9,"//Ну, если надо. Ток бля не частите с этим, он и так хб,так что на вашей совести)",163662,null],[163692,"2026-08-17T12:55:04",31,"альфа херачит, а я за ним чтоли прячусь выходит?)/",112272,null],[163694,"2026-08-17T12:55:49",7,"/ и Немейя тем временем\n— Яблочко будешь?)",112272,null],[163695,"2026-08-17T12:56:22",17,"— Он правда тоскует? Как он сказал? Ребята говорили что он мой хозяин, что я его игрушка и всё....",163621,null],[163701,"2026-08-17T12:58:46",7,"Немейя\n— Врали тебе, твой отец скучает по тебе. Можно сказать, что мы по доброй воле пришли тебя найти. Он рассказывал как создал тебя, ухаживал за тобой и пытался понять, что происходит. Ему жаль, что с тобой так поступили нехорошо.",163695,null],[163930,"2026-08-17T14:17:14",17,"/ Че делает Альф и Тарх внизу?",112272,null],[163931,"2026-08-17T14:17:32",17,"— Отец...",163701,null],[163932,"2026-08-17T14:17:37",17,"/Убеждение с преимуществом",112272,null],[163936,"2026-08-17T14:19:38",7,"/r +d20 +6",163932,null],[163940,"2026-08-17T14:24:50",60,"//слушает, подбирается к лестнице, тщательнее высматривая ловушки",163930,null],[163942,"2026-08-17T14:26:49",17,"Внимание",163940,null],[163944,"2026-08-17T14:34:07",60,"/r +3 ща будет крит луз",163942,null],[163946,"2026-08-17T14:35:02",17,"Ты наступаешь аккуратно туда где точно ничего на полу нет\n\nНо это оказывается люк прямо в подвал который напичкан острыми деталями часов",163944,null],[163947,"2026-08-17T14:35:09",17,"/r 4d6 Урона",112272,null],[163949,"2026-08-17T14:35:55",60,"Альф 32/46",112272,null],[163952,"2026-08-17T14:37:09",60,"Варвар падает вниз, с трудом цепляясь рукой за край люка и стараясь подтянуться выше. Он понимает, что сильно шумит, и решает пока больше ничего не предпринимать, тихо вытаскивая шипы из ног",163946,null],[163953,"2026-08-17T14:38:05",17,"— Ладно, ты права. Нужно пойти назад, домой и всё рассказать.\n\n\nОн смотрит на свои руки превращенные в лезвия\n\n— Зачем я это всё сделал... Я такой глупый",163936,null],[163954,"2026-08-17T14:42:57",7,"*Девушка кладет на пол яблоко, после встаёт и подходит к мальчику, встав на колено, дабы быть на одном уровне.*\n\n— Все исправимо, но так нельзя тебя на улице показываться. Ты вовсе не глупый, я вот... Полюбуйся, рожки потеряла. Но в отличии от меня ты можешь исправить все. Где твои ручки? Я тебе помогу своей магией.\n\n/ Я хочу починкой восстановить ему ручки, если так получиться",112272,null],[163955,"2026-08-17T14:44:48",17,"/О прикольно, да он коснтрукт",112272,null],[163956,"2026-08-17T14:44:58",17,"Руки лежат на столе чуть поломаные",112272,null],[163957,"2026-08-17T14:46:13",7,"Немейя\n— Я чутка глупа, не умею ухаживать за детками, особенно за такими как ты особенными. Лезвия можешь снять? Я твои ручки тебе прикреплю.",163956,null],[163958,"2026-08-17T14:46:37",17,"Он кивает что то щелкает и лезвия падают на пол",112272,null],[163962,"2026-08-17T14:49:16",7,"*Немейя с улыбкой на лице, подходит к ручкам. Она берет их аккуратно и отряхивает. Можно сказать начала чистку при помощи огня. После чистые ручки в руках девушки начали приближаться вместе с ней к мальчику. Распределив левую с правой, она вставляет их куда надо, а при помощи огня... Начинает восстанавливать.*\n\n— Не бойся, не обожжёшься. Сейчас будешь как новенький.",163958,null],[163963,"2026-08-17T14:49:25",7,"/ 2 минуты надо чтобы руки прикрепить.",112272,null],[163964,"2026-08-17T14:49:35",17,"/ Тарк и Альф в это время",112272,null],[163965,"2026-08-17T14:49:39",7,"/ могу в это время только болтать. Ну или к нам вломяться",112272,null],[163966,"2026-08-17T14:49:43",17,"/ Там немея может уже мертва",112272,null],[163967,"2026-08-17T14:49:47",17,"/ Надо спешить",112272,null],[163970,"2026-08-17T14:50:15",7,"/ щас пердеж огнем в окно был таким себе знаком",163967,null],[163972,"2026-08-17T14:50:47",17,"— А вы кто такая, тётя?",112272,null],[163975,"2026-08-17T14:52:01",7,"Немейя\n— Я искательница приключений, или ты про то, что я не выгляжу как обычные люди в округе?",112272,null],[163978,"2026-08-17T14:54:35",60,"//Не",163966,null],[163979,"2026-08-17T14:54:51",60,"//у неё там 100% всё норм, ибо нет ни запаха дыма, ни шума огня",112272,null],[163983,"2026-08-17T14:55:41",7,"/ удивительно, часовня не окружена огнём",163979,null],[163984,"2026-08-17T14:55:46",7,"/ надо исправлять",112272,null],[163987,"2026-08-17T14:56:00",7,"/ я кастую огненный замедленный шар",112272,null],[163988,"2026-08-17T14:56:37",17,"— Угу, не как обычные.",163975,null],[163994,"2026-08-17T14:59:18",7,"Немейя\n— Хех, не знаю. Мне говорили что я \"Тифлинг\" и у меня ещё были рога. Но мне без разницы, я такая же как и все. Просто чутка одарённая магией. Можно сказать, что мы немного похожи.",112272,null],[165258,"2026-08-19T14:02:21",7,"/ ходят слухи, что на второй этаж до сих пор поднимаются",112272,null],[165259,"2026-08-19T14:02:53",7,"/ а у ребенка есть куб и уравнение антижизни",112272,null],[165260,"2026-08-19T14:05:46",17,"/Сёдня нету времени играть совсем",112272,null],[165261,"2026-08-19T14:06:41",7,"/ я знаю.",112272,null],[165729,"2026-08-20T09:48:47",17,"Внизу всё затихло\n\n— Подожди мне надо снять ловушки и... пора вернуться домой к отцу.",112272,null],[165732,"2026-08-20T09:49:25",17,"Янек пробегает за механизм дергает там некотырые рычаги и обрезает пучек лески которые протянуты были туда",112272,null],[165733,"2026-08-20T09:49:32",17,"— Всё, можем спускаться",112272,null],[165750,"2026-08-20T09:54:09",7,"*Немейя улыбнувшись, протягивает руку, прежде чем отправиться вниз. Она решает провести Янека, планируя присматривать за ним дабы избежать в его сторону взглядов косых.*\n\n— Пойдём, уверена, то тебя заждались.",112272,null],[165757,"2026-08-20T09:55:00",17,"Вы спустились вниз, где Тарх вытаскивал израненого Альфа из ямы ловушки \n\n— Ой, простите, это от незванных гостей",112272,null],[165764,"2026-08-20T09:57:46",31,"- в мы то думали это такое приветствие для друзей. Хорошо что у Альфа шкура что кора дуба",112272,null],[165784,"2026-08-20T10:06:04",7,"*Немейя хихикнула, прикрыв лицо левой рукой.*\n\n— Как мило, прям как ёжик! Весь в иголках.",112272,null],[165956,"2026-08-20T13:10:26",17,"/ И так вы пошли обратно отводить мальца к Блинскому?",112272,null],[165969,"2026-08-20T13:16:28",7,"/ да, Малого  к блинскому, а также по приглашению идем:)",112272,null],[165991,"2026-08-20T13:26:00",17,"/ @FSmit7 Дальше нас ждёт большой увлекательный политический блок социального отыгрыша, тебе ваще хочется продолжать?",112272,null],[165992,"2026-08-20T13:27:23",60,"//варвар действительно больше про бой, особенно Альф",112272,null],[165993,"2026-08-20T13:27:33",60,"//фоном постоять могу, хз",112272,null],[165994,"2026-08-20T13:29:30",7,"/ Немейя про сжигать неугодных. Почему я должен быть УмНыМ? 😭",112272,null],[165995,"2026-08-20T13:29:47",7,"/ придётся умнеть",112272,null],[165996,"2026-08-20T13:30:02",17,"/ Ну что поделать вы ходите сами названные ужины, репетиции и тд)",112272,null],[165997,"2026-08-20T13:30:39",7,"/ ну ладна умнеем. ( Когда нибудь я сожгу лес )",112272,null],[166001,"2026-08-20T13:33:36",17,"Когда вы заходите к Блинскому там стоят двое женщин в церковных нарядах\n\nОни перешептываются между собой\n\n/Внимание СЛ12 подслушать\n\nЯнек бежит к Блинскому\n\n— Я... Я... Не хотел! Прости! \n\n— Янек! Сынок! Ты нашелся! Ой, как же тебя потрепали, ничего ничего родной мы сможем всё исправить!\n\n— Они придут за мной? Стражники?\n\n— Эм... Возможно. Но я тебя им не отдам.\n\nЯнек бросается\\ на шею Блински. Но боится крепко обнять, сжимает легонько и даже так Блински кряхтит под натиском\n\n— Всё будет хорошо, и по настоящему сынок! \n\nПотом поворачивается на вас\n\n— Спасибо, что нашли его! Я даю вас скидку в полцены на любую игрушку в магазине, каждому!",112272,null],[166018,"2026-08-20T13:39:33",7,"*Немейя с улыбкой на лице, пока не хочет ничего брать. Однако с интересом разглядывала куклы, но не решалась пока что покупать. На еду должны остаться золотые, так что она не берет.*\n\n— Благодарю, но не стоит. Я рада, что Янек успокоился. Надеюсь все будет в порядке... Ну чтож, нам уже пора, темнеть начинает. Мальчики, жду снаружи.\n\n*С этими словами, девушка помахала рукой на прощание и вышла из лавки.*",112272,null],[166019,"2026-08-20T13:40:01",17,"/ ПОдслушивать кто то будет?",112272,null],[166020,"2026-08-20T13:40:39",7,"/ ну Немейя не хочет подслушивать чужие разговоры, ее тронуло воссоединение",112272,null],[166095,"2026-08-20T14:17:33",60,"/r d20+3 ай похеру",166001,null],[166102,"2026-08-20T14:19:49",31,"/roll d20+2 пытаюсь прослушать",112272,null],[166108,"2026-08-20T14:44:34",17,"— Я слышала точно тебе говорю! Отец Люциан отчитывал Дементия за то, что он кому то рассказал про святые мощи.\n\n— Дааа и алтарь перевёрнут и статую утреннего бога сломали, варвары\n\n— Как же мы теперь... Не знаю, наступают тёмные времена Даниэла. \n\n— Да... будем молиться еще усерднее сестра.",166095,null],[166130,"2026-08-20T15:34:52",17,"/ Такс ну что. Куда мы? На ужин к Фионе Вахтер или в церковь или куда то еще?",112272,null],[166131,"2026-08-20T15:35:38",7,"/ на ужин можем опоздать, церковь подождёт",166130,null],[166133,"2026-08-20T15:38:00",31,"Давайте сначала еще мастера блинского спросим про кукол для Айзека. Он нам теперь как бы должен за сына//",112272,null],[166134,"2026-08-20T15:38:32",7,"/ спрашивай, у Немейи флешбеки приятные и снаружи ждет вас",166133,null],[166139,"2026-08-20T15:41:35",31,"Обращаюсь к Блинскому:\n\n- мастер, возвращаясь к нашему прошлому разговору, о кукле для господина Айзека... Скажите, а господин Айзек не говлрил, что нибудь еще поо эту девушку из снов? Откуда то она же к нему приходила, точнее ее образ. Я думал, может они знакомы, или вдруг из связывает какая то романтическая история. Скажите, как давно вы делаете для него этих кукол?",112272,null],[166947,"2026-08-21T09:04:46",17,"Он отводит вас в сторонку\n\n— Хорошо, давайте еще раз по существу.",166139,null],[166949,"2026-08-21T09:06:18",17,"— Я сделал для капитана Айзека уже 31 куклу, по одной каждые пол года. Он не платит мне за работу, запугивает и требует чтобы я снова и снова создавал в точности по его описанию. Да, образ приходит ему во снах. Эта девушка как то связана с ним. Но подробностей мне не извесно, лучше не спрашивайте его напрямую, если не хотите попасть в клетку с головой осла.",112272,null],[166955,"2026-08-21T09:27:24",31,"- спасибо за совет. 31 штука, каждые полгода, это же почти 16 лет. Ирина слишком молода чтобы быть в таком случае любовным интересом. Есть овд чем подумать, спасибо",112272,null],[178363,"2026-08-30T13:28:58",7,"/ sadness",112272,null],[178369,"2026-08-30T13:30:08",17,"/ Куда вы идете?))",112272,null],[178370,"2026-08-30T13:30:15",17,"/ Что делаете",112272,null],[179325,"2026-08-30T16:01:37",7,"/ мы хотели пойти на застолье xd",178369,null],[179530,"2026-08-30T17:12:18",31,"Да, если дело к вечеру, то надо заглянуть к старой дворянке/",112272,null],[181967,"2026-08-31T15:21:11",17,"Вечер окончательно опускается на Валаки.\nНа фоне тесных домов и грязных улиц особняк Вахтеров выглядит почти вызывающе достойно. Большой старый дом стоит за невысокой каменной оградой, почерневшей от сырости. В окнах первого этажа горит тёплый свет.\nНикаких праздничных лозунгов.\nНикаких улыбающихся солнц.\nНикаких плакатов о том, что «всё будет хорошо».\n\nТолько старый особняк.\n\nПеред входом горят два фонаря. За занавешенными окнами иногда проходят человеческие тени.\nГде-то внутри негромко звякает посуда.\nКогда вы подходите ближе, одна из занавесок на втором этаже едва заметно шевелится.\nЧерез мгновение она снова неподвижна.\n\nПеред вами тяжёлая входная дверь Вахтерхауса.",112272,null],[181979,"2026-08-31T15:24:50",17,"За дверью почти сразу слышатся неторопливые шаги.\nЩёлкает замок.\nДверь открывает знакомый худой мужчина в чёрном сюртуке.\n\nЭрнст Ларнак.\n\nОн окидывает гостей коротким взглядом и снимает шляпу.\n\n— Добрый вечер, господа. Леди Вахтер ожидала вас.\n\nНи упрёка.\nНи напоминания о вчерашнем приглашении.\nЭрнст отступает в сторону, освобождая проход.\n\n— Прошу. Оружие можете оставить при себе. В этом доме гостей не заставляют доказывать свои добрые намерения ещё до того, как им подали ужин.\n\nЗа его спиной открывается просторный прихожий зал.\nВнутри тепло.\nПахнет воском, старым деревом и жареным мясом.\nНа стенах висят потемневшие семейные портреты. Большинство изображённых на них мужчин и женщин смотрят строго и почти одинаково.\n\nГде-то глубже в доме негромко смеётся молодой мужчина.\n\nА сверху раздаётся короткий звук.\nБудто что-то тяжёлое задело деревянный пол.\n\nЭрнст никак на него не реагирует.\n\n— Леди Вахтер присоединится к вам через несколько минут.",112272,null],[184485,"2026-09-01T17:10:49",17,"Особняк Вахтеров. Вахтерхаус.",112272,null],[184492,"2026-09-01T17:12:17",31,"_ жутковатое местечко. Хотя, тут все такие",112272,null],[187153,"2026-09-03T07:48:06",7,"Немейя\n— А как по мне, миленько. Привыкнуть уже пора, что все мрачное, так что это роза, а не дом! Пойдем, ребят?",112272,null],[187154,"2026-09-03T07:48:20",7,"/ прикольно, что я не видел вчера эти постики",184492,null],[187170,"2026-09-03T08:22:29",31,"- да, нет так заставили пожилую даму нас слишком долго ждать. А вообще это странно, не находите? На кой черт мы ей сдались? Да еще она даже нас готова ждать. Это как то странно для аристократки",187153,null],[187171,"2026-09-03T08:25:30",7,"Немейя\n— Ну... Может узнала через главу стражей? Как никак, она в курсе о наших подвигах...",112272,null],[187172,"2026-09-03T08:27:34",31,"- я не о том. Ну вот просто представь, ты аристократка, привыкла что вокруг тебя все на цырлах ходят, стараются угодить и все такое. А тут не пойми кто заявился в город и к тебе по первому зову не прибежали. А ну как она обиду затаила и захочет нас на гуляш пустить?",187171,null],[187173,"2026-09-03T08:34:41",7,"Немейя\n— Сомнительно, но не безосновательно. Я думаю, что ты себя накручиваешь, ибо как минимум, нам еще выступать и гуляш из нас делать точно уж не будут! Будь спокойней, но если что, думаю все обойдётся.",187172,null],[187276,"2026-09-03T13:24:48",7,"/ :/",112272,null],[187282,"2026-09-03T13:28:31",31,"Ждьом/",187276,null],[187285,"2026-09-03T13:29:45",17,"/Ну пусть Смит придёт и скажет \"Я не буду играть, играйте без меня, я начну дальше писать\"",112272,null],[187286,"2026-09-03T13:29:52",17,"/ Вы бы тэгнули его",112272,null],[187288,"2026-09-03T13:30:05",17,"/ @FSmit7",112272,null],[188235,"2026-09-03T21:09:10",60,"//я сейчас в таком дерьме оказался",112272,null],[188236,"2026-09-03T21:09:14",60,"//мляяяяяя...",112272,null],[188237,"2026-09-03T21:09:23",60,"//это правда",187285,null],[188324,"2026-09-03T21:27:10",7,"/ что такое?",188235,null],[188328,"2026-09-03T21:29:17",60,"//не могу и не буду говорить",188324,null],[188329,"2026-09-03T21:29:24",60,"//я так давно не ревел, аааааа, сука...",112272,null],[188332,"2026-09-03T21:30:34",7,"/ я не об этом, не против?",112272,null],[188333,"2026-09-03T21:30:52",7,"/ если в личку вломлюсь",112272,null],[188334,"2026-09-03T21:31:14",60,"//не сейчас",112272,null],[188337,"2026-09-03T21:32:15",7,"/ восстанавливайся, чайку бахни, можешь попробовать поспать. Все в порядке если что:_",188334,null],[188346,"2026-09-03T21:34:06",60,"//мне как минимум придётся успокоительным закинуться",112272,null],[188347,"2026-09-03T21:34:12",60,"//твою мать..",112272,null],[188355,"2026-09-03T21:35:08",7,"/ если будет легче, выпей:_\nНе надо так убиваться",112272,null],[188949,"2026-09-04T08:15:49",7,"/ ну думаю готовы...",187285,null],[191471,"2026-09-05T16:59:06",7,"/ :/",112272,null],[191683,"2026-09-05T17:36:52",17,"/ Готовы продолжать? пишу пост",112272,null],[191690,"2026-09-05T17:37:46",31,"Давай/",112272,null],[191696,"2026-09-05T17:38:19",17,"/Играем как есть, кто есть те и играем",112272,null],[191701,"2026-09-05T17:39:30",31,"Давай, а то мы не закончим никогда/",112272,null],[191710,"2026-09-05T17:41:51",17,"Дверь почти сразу открывает пожилая служанка в строгом чёрном платье. Она смотрит на гостей без удивления. Словно их действительно ждали.\n\n— Госпожа велела проводить гостей в гостиную.\n\nВнутри тепло. Пахнет воском, древесиной, пряностями и готовящимся мясом. На стенах висят старые семейные портреты. На мебели нет пыли, но сам дом кажется значительно старше большей части Валаки.\n\nГде-то наверху раздаётся короткий тяжёлый стук. Будто что-то упало на пол.\nСлужанка на мгновение поднимает глаза к потолку. И тут же продолжает идти.\n\nВас провожают в гостинную. В камине горит огонь. На небольшом столике уже стоят графин тёмного вина и несколько бокалов.\n\n— Госпожа Фиона скоро присоединится к вам.\n\n— Располагайтесь.",112272,null],[191712,"2026-09-05T17:42:21",17,"Наверху вы слышите будто царапают потолок над вами\n\nПриглушенный голос молодой девушки \n\n— Мама?.. Мама?.. Я хорошо себя веду...\n\nА затем тихое \n\n— Мяу.",112272,null],[191753,"2026-09-05T17:48:39",17,"/ Давайте так. если реакций нет напишите /скип или типо того",112272,null],[191767,"2026-09-05T17:52:25",31,"/roll d20+2 внимание, пытаюсь понять, это мяуканье тем же голосом девушки? Или она с кошечкой говорит мне самой зовет?",112272,null],[191771,"2026-09-05T17:53:51",17,"Голос человеческий. Молодой девушки",191767,null],[191773,"2026-09-05T17:54:04",17,"Большая картина семейства висит напротив вас",112272,null],[191775,"2026-09-05T17:54:15",17,"На портрете пятеро.\n\nСтатный аристократ средних лет.\nФиона в центре и на портрете значительно моложе.\nДвое сыновей молодые юноши. Они почти копия друг друга.\nДевочка стоит около отца, она странно держит руки будто, согнув ладони как лапки.",112272,null],[191776,"2026-09-05T17:54:24",17,"Служанка разливает вам вино по бокалам",112272,null],[191779,"2026-09-05T17:55:11",31,"Мысленно:\n\n- с девушкой что то не так, может проклятие какое?",112272,null],[191815,"2026-09-05T18:01:55",7,"Немейя\n— Извиняюсь, но правда, что случилось с девушкой? Проклятие сильное?",112272,null],[191833,"2026-09-05T18:04:47",17,"Немного растеряная служанка отвечала\n\n— Нет нет, что вы. Это дочь госпожи Вахтер, просто.. Занимается поэзией наверняка.",191815,null],[191858,"2026-09-05T18:07:48",7,"/ хочу проницательность кинуть",112272,null],[191875,"2026-09-05T18:10:23",17,"Дверь гостиной открывается.\nВ комнату входит женщина лет сорока с небольшим. Чёрное платье дорогое, но почти лишено украшений. Тёмные волосы аккуратно собраны, на шее тонкая серебряная цепочка.\nФиона Вахтер останавливается у двери и оглядывает гостей.\n\n— Господа, дама.\n\nОна слегка склоняет голову.\n\n— Прошу простить, что заставила ждать.\n\nФиона подходит ближе.\n\n— Я Фиона Вахтер. Добро пожаловать в мой дом.\n\nОна указывает на графин.\n\n— Вино, вода. Не стесняйтесь.\n\nИз столовой появляется служанка.\n\n— Госпожа, всё готово.\n\nФиона кивает.\n\n— Прекрасно.\n\nОна смотрит на гостей.\n\n— Тогда предлагаю сначала поесть. О политике значительно приятнее спорить на полный желудок.",112272,null],[191878,"2026-09-05T18:10:34",17,"Леди Фиона Вахтер",112272,null],[191879,"2026-09-05T18:10:39",17,"На стол приносят блюда, закуски\n\nЖареная птица или свинина.\n\nКорнеплоды.\n\nХлеб.\n\nГрибы.\n\nСыр.\n\nВино.\n\nвсё в достатке но не чрезмерно",112272,null],[191945,"2026-09-05T18:20:42",7,"/ а проницательность мона кинуть?",191858,null],[191985,"2026-09-05T18:27:13",7,"/ ладно кину если да и наверно будет ответ",112272,null],[191989,"2026-09-05T18:27:25",7,"/r d20 +2 чую ли я ложь?",191833,null],[192001,"2026-09-05T18:29:22",7,"*Немейя радостно закатив глаза и изобразив смешок прикрыв лицо, заходит в дом. Она присаживается за один из столов и поправляет сидение. После осмотревшись, у нее разбегаются глаза. Она протягивает руку за хлебом и начинает его покусывать, начав такой легкий перекус.*",191875,null],[192008,"2026-09-05T18:31:19",17,"Служанка умалчивает истинную причину",191989,null],[192032,"2026-09-05T18:34:28",17,"— И так дорогие гости. Я пригласила вас, что бы познакомиться. Мне интересны вы, кто вы, какие у вас взгляды на всё вокруг. Расскажите пожалуйста.",112272,null],[192057,"2026-09-05T18:37:34",7,"*Немейя закончив звать хлеб, смотрит на Фиону Вахтер(а).  Она без задней мысли говорит частично о себе.*\n\n— Я путешественница, что жаждет увидеть прекрасные места в мире... Ну и люблю огонь. А также здесь хотелось бы всем помочь, но не получается пока что.",112272,null],[192095,"2026-09-05T18:42:44",17,"— А что же или кто вам мешает в Валаки помочь всем?",192057,null],[192134,"2026-09-05T18:49:56",7,"Немейя\n— Абсолютно ничего, просто недавно здесь и я чутка путаюсь в местности... Но уже помогали и не раз! Город вроде улыбчивый, но мало кто искренне улыбается, это видно.",112272,null],[192185,"2026-09-05T18:57:59",17,"— И даже Варгос Валакович вам никак не мешает? Знаете с его правилами бывает тяжело делать добро.",112272,null],[192414,"2026-09-05T19:46:13",7,"Немейя\n— Ну... Странный он, помешан на улыбке как на выражении, а не на чувстве. Почему так не пойму, удивлена, что даже стража не взбунтовалась против него, но... Ничего против не имею.",192185,null],[192415,"2026-09-05T19:46:20",7,"/ @QURTZZ присоединяйся",112272,null],[192416,"2026-09-05T19:46:29",7,"/ извиняюсь, про И'лнот слушал",192185,null],[192420,"2026-09-05T19:47:28",31,"- Господин бургомистр несомненно странно себя ведет, но судя по тому что город еще стоит, его методы работатют",112272,null],[209999,"2026-09-14T06:17:55",7,"/ чтож. Видимо квест не будет продвигаться",112272,null],[210000,"2026-09-14T06:25:55",17,"/ Сегодня сделаем",112272,null],[210002,"2026-09-14T06:53:59",17,"— Методы работают. Безусловно. Безусловно нет. Он держит город в страхе заставляя улыбаться. \n\n— Так почему же нет недовольных вы спросите?\n\nФиона крутит в руке бокал омывая стенки вином\n\n— Потому что придет его цепной пёс Айзек и схватит лббогоо несогласного. Бросит в тюрьму. И там сломает. \n\n— Это идеальный тоталитарный строй. Манрхия в лице одного человека.\n\n— Айзек так предан бургомистра потому что...",112272,null],[210003,"2026-09-14T06:54:33",31,"- и почему же?",112272,null],[210004,"2026-09-14T06:54:45",17,"Дверь столовой внезапно распахивается.\n\n— Мам, мы дома!\n\nНа пороге появляются двое молодых мужчин. Оба хорошо одеты. И оба совершенно очевидно уже где-то успели выпить. Первый пытается снять пальто одним красивым движением, цепляется рукавом за дверную ручку и едва не падает. Второй ловит его за плечо. Они оба смеются и хихикают\n\n— Осторожнее, Николай. У нас гости.\n\n— Я вижу, Карл.\n\n— Тогда почему ты чуть не лёг перед ними?\n\n— Это называется поклон.\n\nФиона закрывает глаза.\n\nВсего на секунду.\n\n— Мои сыновья. Николай и Карл.\n\nОба синхронно кланяются.\n\nКарл замечает накрытый стол.\n\n— О. Птица осталась?\n\nФиона смотрит на него.\n\n— Добрый вечер, мама.\n\n— Добрый вечер, Карл.\n\n— Теперь птица?\n\n— Сядьте.\n\nБратья немедленно занимают свободные места.\n\nНиколай осматривает гостей.\n\n— Так это те самые чужаки?\n\nКарл уже наливает себе вина.\n\n— Какие именно?\n\n— Которые детей спасли\n\nКарл заинтересованно поднимает голову.\n\n— А-а-а. Тогда хорошие люди.",112272,null],[210005,"2026-09-14T06:54:59",17,"Сыновья Фионы. Николай и Карл. Близнецы.",112272,null],[210006,"2026-09-14T06:55:55",31,"- рад слышать столь высокую оценку, госопда",112272,null],[210007,"2026-09-14T06:58:14",17,"Фиона собирается продолжить но Калл врывается с бестактным вопросом глядя на Немею\n\n— А что с рогами? Спилила как сучки у вишни?\n\n— Карл!\n\n— Что? Просто вопрос",112272,null],[210008,"2026-09-14T06:59:22",7,"/ я щас на паре. Извиняюсь за задержку.",112272,null],[210011,"2026-09-14T08:00:15",7,"*Немейя кушая курочку, оглядывается на Карла. Она видимо не рада была этому вопросу, тема больная. Она даже не скрывает своего раздражения.*\n\n— Тебе бы манерам поучиться, потом уже разговаривать лезть. Не твоего ума дела.\n\n*Говорит скрипя зубами, но сдержанно. Частично, уважая Фиону и ее приглашение на ужин.*",210007,null],[210020,"2026-09-14T08:27:46",17,"— Лучше и не скажешь. Прошу простить моего сына. После смерти их отца они совсем отбились от рук.\n\nКарл хмурится затем растекается в улыбке\n\n— Прошу простить меня. Вопрос и правда слишком откровенный. Я просто думал у нас сегодня неформальное общение за ужином",112272,null],[210022,"2026-09-14T08:32:32",7,"Немейя\n— Извинения приняты, мои соболезнования. Надеюсь, быстро придете в себя...",112272,null],[210023,"2026-09-14T08:33:52",17,"— Кстати, мам, Эрнст сказал, ты сегодня пятьдесят золотых страже отдала. Это за кого?\nТишина.\n\nФиона\n— За вашу сестру.\n\nКарл смотрит на брата.\n— Пятьдесят?!\n\n— За меня мама больше двадцати никогда не платила.\n\nФиона\n— Потому что тебя приходилось выкупать неоднократно и мне уже выписали скидку на эти траты.\n\nКарл\n— Вот видите? Постоянным клиентам есть привилегии.\n\nНиколай\n— А кто ее выпустил из дома?\n\nФиона\n— Слушайте это плохая тема для обсуждения за столом. Так что сыновья. Призываю вас прекратить.\n\nОба брата улыбнулись между собой ехидно но кивнули и примолкли",112272,null],[210024,"2026-09-14T08:34:03",17,"— Так вот Варгос... Айзек...",112272,null],[210025,"2026-09-14T08:36:39",17,"За дверьми раздаётся быстрый топот. Кто-то бежит на четвереньках.\nФиона мгновенно метает туда взгляд.\n\nЗа приоткрытой дверью появляется молодая девушка в длинной черном платье. Растрёпанные волосы падают ей на лицо. Она босая.\nДевушка замечает незнакомцев и замирает.\n\nПотом медленно приседает. На корточки. Голова чуть наклоняется набок.\n\n— Мяу.\n\nКарл прекращает жевать. Николай опускает бокал.\n\nФиона очень тихо произносит\n\n— Стелла.\n\nДевушка смотрит на мать.\n\n— Мяу.\n\nЗатем её взгляд замечает Тарха и Немею. Зрачки расширяются. Стелла медленно поднимается.\n\nДелает один осторожный шаг вниз. Потом ещё один.\nИ крайне серьёзно спрашивает\n\n— Ты пахнешь странно? \n\nГоворит она подойдя близко к Тарху\n\n— Ты тоже вынужден скрывать свою суть?",112272,null],[210026,"2026-09-14T08:36:55",17,"Стелла Вахтер.",112272,null],[210027,"2026-09-14T08:37:21",17,"/ Гм ультанул",112272,null],[210028,"2026-09-14T08:42:43",7,"*Немейя держит в руке часть курицы и замирает. Она смотрит на Стеллу с неким... Недоумением... Молчит и думает, что с ней случилось... Проклятие?*",112272,null],[210029,"2026-09-14T08:46:50",31,"- у всех есть тайны, юная леди. И опасно их раскрывать всем и каждому",210025,null],[210030,"2026-09-14T08:47:02",31,"Это девушка-квадробер я так понимаю?/",112272,null],[210031,"2026-09-14T08:48:22",7,"/ Ага",210030,null],[210032,"2026-09-14T08:49:30",17,"Стелла переводит глаза на Немею а точнее на ножку курочки в ее руке\n\nОна внимательно фокусируется на ножке и пригибается",210028,null],[210033,"2026-09-14T08:49:51",17,"— Стелла Господи вмогущий. Прошу тебя. Ступай в свою комнату",112272,null],[210034,"2026-09-14T08:53:12",7,"*Немейя кладет на тарелку часть своей курочки. Она смотрит на Фиону, после на Стеллу. По ней видно, как сильно она неловко себя чувствует.*\n\n— Ээ...",112272,null],[210035,"2026-09-14T09:00:20",17,"Фиона кивает слугам и несколько женщин подходят к Стелле и помогают ей покинуть обеденную залу\n\n— Пойдёмте госпожа. Свежего молочка привезли\n\nУводят ее з адвери и куда то наверх",112272,null],[210036,"2026-09-14T09:01:10",31,"Перевожу вопросительный взгляд на хозяйку",112272,null],[210037,"2026-09-14T09:01:31",7,"*Немейя решает промолчать, пока что. Чувствуя себя неловко, она просто не знала как реагировать и что именно говорить. С одной стороны предложение о помощи, с другой...*",112272,null],[210038,"2026-09-14T09:03:20",17,"Уходя Стелла вопрошала\n\n— Там Виктор?\n\nНа сто Фиона овтчала\n\n— Виктора там нет\n\n— Нет он там, мама. Он снова будет делать голове больно!\n\n— Милая там никого нет. Виктор не придет сюда. Его никто не пустит.",112272,null],[210039,"2026-09-14T09:05:01",17,"Некоторое время Фиона смотрит вслед дочери.\nКогда дверь наверху закрывается, она возвращается за стол.\n\nСадится и закрывая глаза массирует виски. \n\n— Простите за эту сцену... \n\nОна делает глубокий печальный вздох \n\n— Когда-то я считала, что конфликт наших семей Вахтер и Валакович можно закончить иначе.\n\n— Моя дочь общалась с Виктором Валаковичем.\n\nФиона смотрит в сторону лестницы.\n\n— Это была ошибка.\n\n— Я не знаю всего, что произошло между ними. Но девушка, которую вы только что увидели, не всегда была такой.\n\nПальцы Фионы чуть сильнее сжимают бокал.\n\n— Поэтому, когда я говорю, что семья Валаковичей разрушает этот город, для меня это не только теория.",112272,null],[210040,"2026-09-14T09:05:56",17,"— Я убью его. Рано или поздно. Он покажет свой нос из своей лаборатории в защищённом папкином особняке\n\nВосклицает Николай\n\n— Даже думать об этом не смей, сын. У нас иной путь.",112272,null],[210041,"2026-09-14T09:06:49",17,"— Айзек... Дело все в том. Что он выполняет все приказы Варгоса по особой причине. Которую мало кто знает. \n\n\n— Он внебрачный сын Варгоса. Бастард. И маниакально ищет признания от отца.",112272,null],[210042,"2026-09-14T09:07:19",17,"/ Русик",112272,null],[210043,"2026-09-14T09:07:23",17,"/ Все же понял?",112272,null],[210047,"2026-09-14T09:08:45",7,"/ если нет, кидать анализ?",210043,null],[210048,"2026-09-14T09:09:42",7,"/ Тип что улыбается довёл девушку до квадроберства",112272,null],[210049,"2026-09-14T09:12:49",7,"/ короче, кое кто хочет нас склонить к революции",112272,null],[210050,"2026-09-14T09:12:54",17,"/ Ну не Бургомистр только. А его сын.",210048,null],[210051,"2026-09-14T09:13:02",17,"/ В точку",210049,null],[210052,"2026-09-14T09:13:18",7,"/ Немейя за! Революция это перерождение!",112272,null],[210053,"2026-09-14T09:14:17",7,"Немейя\n— Я так... Понимаю... Вы жаждете революции, свергнуть Валаковичей?",112272,null],[210054,"2026-09-14T09:15:39",17,"— Да. Но конечно ненасильственными методами. У Варгоса вся стража в подчинении. Точнее у Айзека. Его все боятся. И слушаются как командира. А он безумно предан Варгосу.\n\nФиона отпивает вина\n\nБлизнецы навлстрили ушки и придвинулись с заговорщической ухмылкой к столу",112272,null],[210055,"2026-09-14T09:16:07",17,"— Уберите Айзека из этого уравнения. И карточный домик Варгоса посыпится.",112272,null],[210056,"2026-09-14T09:16:51",17,"— Праздник солнца завтра. Если мы публично выступим. И если Айзек иже будет устранен ищу равнения. Народ поддержит. Многие аристократические семьи города согласны. Просто боятся выступать против Айзека.",112272,null],[210057,"2026-09-14T09:17:13",17,"— Я возьму власть если народ будет согласен с этим. Но у меня огромная поддержка элит.",112272,null],[210058,"2026-09-14T09:17:34",7,"Немейя\n— Вы хотите, чтобы Айзека... Не стало?",112272,null],[210059,"2026-09-14T09:21:28",17,"— Метод мне не принципиален. Я не кровожадна как Варгос поймите. Мне нужно, чтобы он не мешал. Чтобы он не спалил меня или моих людей на сцене праздника своей этой... Дьявольской магией",112272,null],[210060,"2026-09-14T09:33:12",7,"Немейя\n— Ох, не беспокойтесь, я за огонь отвечаю и никто живой не сгорит... Но... Ничего не хочешь сказать про Айзека?",210036,null],[210062,"2026-09-14T09:38:47",17,"/Ждём Лёшу",112272,null],[210064,"2026-09-14T09:47:59",31,"Я тут/",112272,null],[210079,"2026-09-14T09:57:20",31,"- пока мне кажется, что вы нас хотите использовать как наемных громил, которых не жалко в расход пустить. а я знаете ли, просто крестьянин, и не очу лезть в дворянские разборки никаким боком",112272,null],[210100,"2026-09-14T10:09:19",17,"— Я говорю как есть. Вы можете игнорировать и просто оставить всё как есть, конечно. Это вариант. Вы город покинете пойдете по своим делам. А жители Валаки так и будут натягивать улыбки и стоять в колодках в маске осла. Чего хуже на каждом празднике солнца Варгом вжигает внутри деревянной фигуры несколько особо буйных \"врагов его режима в ослиных масках\" и все молчат",112272,null],[210104,"2026-09-14T10:13:03",31,"- ну, это вы так говорите. еще и сам до того сказали, чтос Валаковичами у вас вражда",112272,null],[210107,"2026-09-14T10:20:03",17,"— Что ж. У меня есть одна вещица. Если вы не приверженцы улучшения политической ситуации в городе может вас замотивирует материальное вознаграждение.\n\n— Я говорю не о золоте. Золото это слишком дёшево. У меня есть кое что бесценное",112272,null],[210108,"2026-09-14T10:21:22",31,"- хмм, удивите",112272,null],[210113,"2026-09-14T10:23:45",17,"— Дневник с автобиографией Страда Фон Заровича. Хранится у моей семьи около трёхсот лет.",112272,null],[210114,"2026-09-14T10:24:01",31,"- однако",112272,null],[210115,"2026-09-14T10:24:02",17,"— Подумайте сами.\n\nФиона спокойно обводит гостей взглядом.\n\n— Варгос произносит речи.\n\n— Его жена улыбается и помогает развешивать украшения. Виктор прячется от города в своём доме. А когда кто-нибудь говорит \"нет\"...\n\nОна постукивает пальцем по столу.\n\n— Приходит Айзек. Уберите из этой картины одного человека, и внезапно окажется, что власть господина Валаковича держится куда менее прочно, чем кажется.",112272,null],[210116,"2026-09-14T10:24:26",17,"— Дневник станет вашим после того как власть сменится. Это моё предложение.",112272,null],[210117,"2026-09-14T10:24:46",31,"//так стоп//",112272,null],[210118,"2026-09-14T10:24:56",31,"ща перечитаю предсказания//",112272,null],[210119,"2026-09-14T10:25:02",17,"/ Да там про это было",112272,null],[210120,"2026-09-14T10:25:10",17,"/ Вам стоит на них обращать внимание очевидно",112272,null],[210121,"2026-09-14T10:25:14",17,"/Там всё правда",112272,null],[210124,"2026-09-14T10:27:12",31,"- это... действительно ценно. Но Айзек это очень сильный противник, от него прямо веет жутью. ст ли у него слабые места? я бы не хотел лезть на такого противника очертя голову",112272,null],[210127,"2026-09-14T10:28:14",17,"— Да. У меня есть сведения, о том, что он заказывал множество раз у Блинского куклу с одним и тем же лицом. Некая девушка занимает его мысли последние десяток лет. О других слабостях мои информаторы не сообщали.",112272,null],[210128,"2026-09-14T10:28:14",7,"Немейя\n— Меня не интересует материальное, если город станет лучше, этого будет достаточно. ( Кидать на обман? )",210107,null],[210131,"2026-09-14T10:36:34",17,"— Времени на принятие решения мало. завтра если Айзек покинет сцену на празднике я прикажу действовать своим людям. Чтобы сделать Валаки снова великим.",112272,null],[210132,"2026-09-14T10:36:43",17,"— Но без вас шансов нет.",112272,null],[210133,"2026-09-14T10:40:45",31,"- вы узнвете о нашем выборе. завтра. либо Айзек придет на праздник, либо нет",112272,null],[210134,"2026-09-14T10:41:05",31,"_ думаю, нам пора. спасибо за гостепреимство",112272,null],[210135,"2026-09-14T10:42:29",17,"— Хорошо. Спасибо, что приняли предложение. \n\nФиона привстаёт вытирая края губ платочком\n\n— Эрнст. Проводи гостей.\n\nПарень что передал сообщение вам кивает \n\nДва брата тоже приподнимаются\n\n— Мама мы проводим.\n\n— Хорошо, пусть так.",112272,null],[210136,"2026-09-14T10:42:39",17,"Близнецы предлагают вам проследовать к выходу",112272,null],[210142,"2026-09-14T10:44:35",31,"выходим ьвместе с ними. Оборачиваюсь к Карлу:\n\n- вы хотели что то предложить?",112272,null],[210146,"2026-09-14T10:45:40",17,"— Мы знаем куда можно выманить Айзека. Он приходит на одну могилу каждую ночь.",112272,null],[210147,"2026-09-14T10:51:12",31,"- один?",112272,null],[210148,"2026-09-14T10:52:01",17,"— Обычно да. Это что то типо ритуала для него. В одно и тоже время. В одно и тоже место. На одну могилу.",112272,null],[210149,"2026-09-14T10:52:17",17,"— Там похоронена Ирина Индировна.\n\nДобавляет второй",112272,null],[210150,"2026-09-14T10:53:28",31,"- а кто это?",112272,null],[210151,"2026-09-14T10:53:50",17,"— Дочка бургомистра деревни Багровая как мы выяснили",112272,null],[210152,"2026-09-14T10:55:25",31,"- вы уверены? По нашим сведениям, Ирина жива, и уж точно не лежи на кладбище годами. да и что дочке бургомистра деревни делать на городском кладбище? в Багровии и свое кладбище есть",112272,null],[210153,"2026-09-14T10:55:45",17,"— Этого мы не знаем",112272,null],[210155,"2026-09-14T10:55:56",17,"— Но факт есть факт",112272,null],[210156,"2026-09-14T10:56:55",31,"- покажите это место?",112272,null],[210157,"2026-09-14T11:00:26",17,"Они синхронно кивают",112272,null],[210158,"2026-09-14T11:00:50",17,"По пути еще решили поболтать, вино в их крови даёт знать. Языки у них без костей",112272,null],[210159,"2026-09-14T11:02:07",17,"— Сегодня пошалили немножко. В Фургоне у площади какой то железный зверь находился. Ну фургончик этого фокусника Риктавио. Мы через окошечко подсмотрели\n\nВторой добавляет\n\n— Да, вот умора. Начали его качать, а зверь тут озверел и вырвался\n\n— Давно мы так не убегали брат.\n\n— Да последний раз из спальни Аннет",112272,null],[210160,"2026-09-14T11:03:00",31,"- а если бы зверь вас поймал и порвал? совсем нет чувства самосохранения?",112272,null],[210161,"2026-09-14T11:05:43",17,"— Да мы пьяные были. Повеселиться хотели просто",112272,null],[210162,"2026-09-14T11:06:47",17,"Вы доходите до могилы. В вазе у могильной плиты свежие лилии. Плита начищена до блеска нет ни пылинки\n\n\"Ирина индировна\"\n\n\"Любимая дочь и сестра\"",112272,null],[210163,"2026-09-14T11:09:10",7,"/ я вернусь не скоро, если что. Немейя сидит кушает невтыкает ( Я на паре жестко занят )",112272,null],[210164,"2026-09-14T11:09:22",31,"/так, мы же вдвоем остались, Альфа не учитываем никак?/",112272,null],[210165,"2026-09-14T11:09:25",17,"/ Ладно паузимся мы уже поели))",210163,null],[210166,"2026-09-14T11:09:33",17,"/ Да хуй знает. Смит кидок",210164,null],[210167,"2026-09-14T11:09:40",17,"/ Придумайте сами куда он съебал",112272,null],[210168,"2026-09-14T11:09:42",17,"/ Мне лень",112272,null],[210169,"2026-09-14T11:10:15",17,"/Пойду гладить под сириал, сёдня у меня отгул, но домашние дела куда тяжелее",112272,null],[210170,"2026-09-14T11:10:17",31,"чо тут думать, туман поглотил его, затуманил голову и он ушел. вернется или нет - загадка",112272,null],[210171,"2026-09-14T11:10:24",17,"/Да, отлично",112272,null],[210172,"2026-09-14T11:10:52",31,"есть бог из машины, а у нас бцдкт бог из тумана в финальной битве/",112272,null],[210865,"2026-09-14T16:31:02",7,"/ что я пропустил?",210164,null],[210868,"2026-09-14T16:31:19",7,"/ черт из 4 челиков 2 остались, а нам еще превозмогать вчетвером было тяжело",112272,null],[210871,"2026-09-14T16:32:15",31,"Читай/",210865,null],[210872,"2026-09-14T16:32:42",31,"Видимо, нас ждет объединение со второй партией. И я буду шизеть общаясь сам с собой/",210868,null],[210880,"2026-09-14T16:34:38",7,"/ сука, это будет угарно",210872,null],[210882,"2026-09-14T16:35:01",7,"/ я то читаю. Просто пока отвечал читал +- ( Пары, 5 штук ). Я про важное",210871,null],[210885,"2026-09-14T16:35:25",31,"Потом еще и вы с Элей уйдете, я добавлю сюда Орочи и будет полных психодел/",112272,null],[210886,"2026-09-14T16:35:42",7,"/ я не уйду",210885,null],[210887,"2026-09-14T16:35:47",7,"/ я играц хочу",112272,null],[210902,"2026-09-14T16:40:35",17,"/ Себас более каноничный тут",112272,null],[210904,"2026-09-14T16:40:57",31,"Ну да, он для этого и создан/",112272,null],[210953,"2026-09-14T16:51:43",7,"/ итак",112272,null],[210954,"2026-09-14T16:51:43",7,"*Немейя ходила не роняя ни слова. Она смотрит на могилу, начав думал... А когда похороны были... Возможно... Это были ложные похороны? Чтобы спрятаться, от графа. Так или иначе, сейчас ее оттуда ещё вытаскивать и вытаскивать...*\n\n— Чтож... А когда ее хоронили, не знаете? Примерно, точно не нужно.",210162,null],[210955,"2026-09-14T16:51:44",7,"/ пост надо вставить",112272,null],[211078,"2026-09-14T17:23:54",31,"- мне кажется, надо будет поговорить с ним, с Айзеком. Может, он и не знает что Ирина на самом деле жива?",210954,null],[211227,"2026-09-14T18:21:50",7,"Немейя\n— Возможно ты прав... Кстати, а где громила Альф? И... Куда ещё человек делся. Я думала, они снаружи подождут.",211078,null],[211234,"2026-09-14T18:23:43",31,"- точно, Альф пропал. Проклятое место, неужели его утащил туман?",211227,null],[211251,"2026-09-14T18:29:57",7,"Немейя\n— Громила... Блять... \n\n*Произносит грустно девушка. Она не хотела, чтобы кто либо погибал, хоть и на Альфа таит обиду. Она приняла как должное и делает глубокий вдох.*\n\n— Тогда... Пойдём за Айзеком? Убедим, что Ирина жива и сделаем все, чтобы он не участвовал завтра?",112272,null],[211272,"2026-09-14T18:34:31",31,"- по крайней мере, попробуем убедить. Может т не придется самим его убивать, он может сам пойдет графа убивать за Ирину",112272,null],[211359,"2026-09-14T19:08:15",7,"Немейя\n— Он же слепой предан этому... Забыла уже его имя... Что правит городком. Убедить будет крайне тяжело.",112272,null],[211360,"2026-09-14T19:08:17",17,"На могильной плите даты вы понимаете что ей при смерти было 10 лет. Прошло сейчас со дня ее смерти ещё 10",112272,null],[211363,"2026-09-14T19:08:47",7,"/ так, погоди ка",112272,null],[211364,"2026-09-14T19:08:54",7,"/ что то здесь не так",112272,null],[211365,"2026-09-14T19:09:08",7,"/ мы точно об одной и той же женщине говорим...",112272,null],[211369,"2026-09-14T19:10:29",17,"/ Ирине 20 лет примерно которую вы видели",112272,null],[211371,"2026-09-14T19:11:05",7,"/ а куклы у кукольника для Айзека были 10 летними или 20 летними примерно?",112272,null],[211373,"2026-09-14T19:12:11",17,"/ 20",112272,null],[211381,"2026-09-14T19:14:49",7,"/ ага...",112272,null],[211382,"2026-09-14T19:14:57",7,"/ @QURTZZ",211359,null],[211383,"2026-09-14T19:15:20",31,"Я тут",112272,null],[211384,"2026-09-14T19:15:34",31,"Не стесняйся, пиши, я подхвачусь",112272,null],[211388,"2026-09-14T19:16:09",31,"- что то связывает его ч Ириной. Надеюсь, он нас расскажет",112272,null],[211390,"2026-09-14T19:24:06",7,"Немейя\n— Чтож... Помнишь, где его обычно найти можно? Пойдем и проведаем его...",211388,null],[211391,"2026-09-14T19:29:56",31,"- так мы для этого на могилу пришли, он сам сюда явится, соберись Немея",211390,null],[211399,"2026-09-14T19:38:35",7,"Немейя\n— Мне кажется не лучшей идеей его на могиле просить просто... Понимаешь? Лишние уши, крики могут быть, а стража везде. Я не хочу в клетке сидеть, мне повезло что у меня улыбку вызывает буквально все что горит...",211391,null],[211414,"2026-09-14T19:44:02",31,"- На могиле он будет один, и никого тут не будет ночью. Лучшее место для разговора по душам",112272,null],[211419,"2026-09-14T19:48:03",7,"Немейя\n— Как знаешь, мне не по себе от подобного места. Предупреждаю заранее. Итак грустно, что двоя остались...\n\n*Сказала девушка, присаживаясь и опираясь спиной на один из крестов. Она сейчас просто отдохнуть решила, пока что. Частично крыльями свернулась.*",112272,null],[211423,"2026-09-14T19:49:55",7,"/ ждем Айзека \nНадеемся на чудо",112272,null],[212593,"2026-09-15T08:41:44",7,"/ я все еще с Алексеем жду Айзека",112272,null],[212594,"2026-09-15T08:44:56",17,"/ Еду на работу",112272,null],[212697,"2026-09-15T10:28:35",7,"/:_",112272,null],[212866,"2026-09-15T12:53:58",17,"/Вы спрятались?",112272,null],[212867,"2026-09-15T12:54:03",17,"/Или стоите у могилы?",112272,null],[212868,"2026-09-15T12:54:22",31,"отошли в стороны и скрылись в тенях надгробий",112272,null],[212869,"2026-09-15T12:54:54",17,"Ночь окончательно накрывает Валаки.\n\nЗа кладбищенской оградой почти не слышно города. Только ветер перебирает голые ветви, а где-то далеко несколько раз лает собака.\n\nМежду могильными плитами лежит низкий туман.\n\nВремя тянется медленно.\n\nНаконец со стороны дороги появляется человек.\n\nОдин. Ни стражников. Ни факела.\n\nВысокая широкоплечая фигура проходит через кладбищенскую калитку и уверенно сворачивает между могил, будто ходила этой дорогой сотни раз.\n\nАйзек.\n\nСегодня на нём нет привычного выражения человека, которому достаточно посмотреть на кого-нибудь, чтобы тот замолчал.\n\nОн выглядит уставшим.\n\nАйзек останавливается у старой могилы Ирины.\n\nНесколько секунд просто стоит перед ней.\n\nПотом медленно опускается на одно колено.\n\nИз внутреннего кармана он достаёт маленькую деревянную фигурку. Грубая работа. Человечек в платье, вырезанный явно очень давно.\n\nАйзек кладёт её на камень.\n\nМолчание затягивается.\n\nНаконец он тихо говорит\n\n— Опять ты мне снилась.\n\nПальцы чудовищной руки медленно сжимаются.\n\n— Только теперь взрослая.\n\nОн смотрит на надпись на могильной плите.\n\n— Какого хрена, Ирина?\n\nАйзек опускает голову.\n\n— Ты же умерла.",112272,null],[212871,"2026-09-15T12:55:53",31,"- она жива, Айзек. Пока жива",112272,null],[212873,"2026-09-15T12:56:24",17,"Он вскакиевает от неожиданности и рука демона наполняется огнём освещая вокруг\n\n— КТО ЗДЕСЬ! ПОКАЖИСЬ!",112272,null],[212875,"2026-09-15T12:57:00",31,"выхожу из тени, делаю жест Немее пок не высовывться",112272,null],[212876,"2026-09-15T12:57:07",31,"- это я, Тарх",112272,null],[212877,"2026-09-15T12:57:18",31,"- и я знаю,  о чем говрю",112272,null],[213023,"2026-09-15T14:09:49",17,"— Что ты сказал?\n\nОн поворачивает голову к Тарху.\n\nВ темноте кладбища лицо Айзека будто каменеет.\n\n— Повтори.\n\nЧудовищная рука с тихим скрипом сжимается в кулак.\n\n— Её имя ты откуда знаешь?\n\nАйзек делает один шаг от могилы к Тарху.\n\n— Кто тебе сказал про Ирину?",112272,null],[213089,"2026-09-15T14:39:11",31,"- я лично ее видел. И говорил с ней. Несколько дней назад. Не знаю, откуда тут эта могила, но Ирина жива, ей около 20 лет и она до недавнего времени жила в Багровии, с отцом и братом",112272,null],[213277,"2026-09-15T15:17:42",7,"*Девушка выходит из тени. Она выглядывает и продолжает.*\n\n— Нас наняли ее спасти, но... Нежити было слишком много. Мы боролись как могли, пока не пришел граф. Он ее похитил, к сожалению.",112272,null],[213278,"2026-09-15T15:17:55",7,"/ пупу, продолжаем! Я готов",112272,null],[213452,"2026-09-15T16:15:38",7,"/ что там?:'",112272,null],[213455,"2026-09-15T16:16:19",17,"— Докажите. Опишите как она выглядит!",112272,null],[213456,"2026-09-15T16:17:24",31,"- описываем, используя все доступное красноречье. Я хз ка кона выглядела, забыл давно)",112272,null],[213457,"2026-09-15T16:18:47",17,"/История",112272,null],[213459,"2026-09-15T16:18:59",17,"/ Вот гадик! Хер вам!",213456,null],[213461,"2026-09-15T16:19:59",31,"/roll d20 Аскелатор, помоги с памятью, умоляю. Иначе меня тут похоронят",213457,null],[213465,"2026-09-15T16:20:12",31,"Немея, вспоминай/",112272,null],[213621,"2026-09-15T17:12:44",7,"/ инта... Ща",213465,null],[213622,"2026-09-15T17:12:44",7,"/ а че туплю",112272,null],[213630,"2026-09-15T17:14:50",31,"Историю кидай/",112272,null],[213631,"2026-09-15T17:14:53",7,"*Немейя закатив глаза, создаёт иллюзию при помощи малой иллюзии \"куклу Ирины\". Однако отличающуюся, что была у мастера по дереву. Кукольника... Возле шеи видно два ровных следа от укуса.*\n\n— Да также, как и куклы. Только вкус возле шеи, Граф постарался.",112272,null],[213632,"2026-09-15T17:15:10",7,"/ а че историю кидать, не вчера видел ее куклу",213630,null],[213633,"2026-09-15T17:15:20",31,"О, крутяк/",213631,null],[213634,"2026-09-15T17:15:49",17,"/ Вы видели мою куколку ☹️",112272,null],[213635,"2026-09-15T17:16:07",17,"/ Я домой, прайм закончился, завтра жду всех, вечером отписать постараюсь",112272,null],[213636,"2026-09-15T17:16:10",7,"/ мой Альцгеймер не так сильно прогрессировал",112272,null],[213637,"2026-09-15T17:16:12",17,"/ МЫ ДВИЖЕМСЯ ГОСПОДА",112272,null],[213638,"2026-09-15T17:16:17",17,"/ СЕМИМИЛЬНЫМИ ШАГАМИ!",112272,null],[213642,"2026-09-15T17:16:35",7,"/ восстанавливай свой прайм",112272,null],[213645,"2026-09-15T17:17:15",17,"/ Пошел кулдаун",112272,null],[213647,"2026-09-15T17:17:47",31,"Я думаю Немея сделала внешность более похожей на живую Ирину, а не на куклу/",213634,null],[213651,"2026-09-15T17:18:47",7,"/ да, но нет",213647,null],[213653,"2026-09-15T17:19:08",7,"/ малая иллюзия не позволяет делать живых существ \nА чучел реалистичных или кукол вполне",112272,null],[220734,"2026-09-18T12:22:34",17,"— Не знаю убить тебя прямо сейчас... Будто дьявол послал тебя мучать меня.\n\nОн вздыхает\n\n— Или ты просто больная\n\nАйзек садится на траву у могилы Ирины\n\n— Садить, выпьем и я расскажу тебе историю",112272,null],[220735,"2026-09-18T12:22:44",17,"Он достает бутылку виски и щелбаном демонической руки сбивает пробку вместе с куском горлышка\n\nРовно будто срезал раскаленной струной",112272,null],[220737,"2026-09-18T12:23:22",17,"— Ирина моя сестра. Была ей.",112272,null],[220741,"2026-09-18T12:23:31",17,"— С чего же блять начать... Как тяжело это все бередить после стольких лет...",112272,null],[220743,"2026-09-18T12:23:45",17,"/ @Evreiskui_Department",112272,null],[220747,"2026-09-18T12:24:04",17,"— Когда Ирина родилась у Варгоса, это был праздник. Завтра ее день рождения. Как и праздник солнца который Варгос сделал на самом деле в ее честь.",112272,null],[220751,"2026-09-18T12:24:23",17,"— Мы были близки. Я защищал ее как старший брат конечно играл с ней. Приглядывал. Когда ей стукнуло 10 на следующий день пришел граф Страд. Дьявол. \n\nАйзек ещё отпивает",112272,null],[220753,"2026-09-18T12:24:35",17,"— Он потребовал у Варгоса отдать Ирину ему. Что то там говорил, что она это реинкарнация его возлюбленной... Ебаный псих... Татьяны вроде.",112272,null],[220754,"2026-09-18T12:24:45",17,"— Не стал забирать силой. Дал сутки на подумать. Или угрожал стереть Валаки с лица земли.",112272,null],[220755,"2026-09-18T12:24:52",17,"— Отец... Отец сдался. Я слышал как он приказал готовить приданное и карету до замка Ривенлофт.",112272,null],[220756,"2026-09-18T12:25:04",17,"— Но я не мог допустить этого. Ночью мы бежали из города. И... Граф конечно все знал, все видел. Дьявол хули. У озера Зарович он нагнал нас.",112272,null],[220758,"2026-09-18T12:25:15",17,"— Я... Отвёл ее на пристань, мостик к воде. Мы стояли у края. Граф шел на нас...",112272,null],[220759,"2026-09-18T12:25:30",17,"— Я толкнул Ирину в воду, чтобы она не досталась дьяволу. Думал потом достану ведь... Граф не войдёт в воду, бабка говорила.",112272,null],[220760,"2026-09-18T12:25:40",17,"— Но он оказался быстрым, очень. Ирина упала, плавать она не умела. Граф подскочил и оторвал мне руку",112272,null],[220762,"2026-09-18T12:25:52",17,"— А Ирина пошла на дно. Я упал без сознания от боли.",112272,null],[220765,"2026-09-18T12:26:08",17,"— Но тела мы не нашли. Похоронили пустой гроб.",112272,null],[220766,"2026-09-18T12:26:19",17,"— Граф ушел и с этих пор не жалует Валаки. Но он знал, что Варгос дал добро. Поэтому город стоит. Граф держит слово. Даже которое не смог обеспечить.",112272,null],[220768,"2026-09-18T12:26:31",17,"— А я выкарабкался. Жил без руки около года. А потом пришли сны. Каждую ночь я вижу Ирину у озера на том самом пирсе и не могу спасти.",112272,null],[220770,"2026-09-18T12:26:37",17,"— Дьявол измывается так надо мной.",112272,null],[220771,"2026-09-18T12:26:43",17,"— Со снами пробудилась и эта мерзость. Рука дьявола.",112272,null],[220773,"2026-09-18T12:26:53",7,"/ 0-0",112272,null],[220774,"2026-09-18T12:26:56",17,"— Вот такая история. Десять лет я вижу как взрослеет моя сестра во снах.",112272,null],[220776,"2026-09-18T12:27:10",17,"— И не могу её спасти.",112272,null],[220777,"2026-09-18T12:27:26",17,"Пьёт",112272,null],[220781,"2026-09-18T12:29:47",31,"- я е знаю как это случилось, но она выжила. Это хорошая новость. но есть и плохая. СТрад все таки захватил ее. Несколько недель назад мы прибыли в Багровию, по приглашению тамошнего бургомистра, он сообщил, что его дочь подвергается нападкам грфа, что страсно желает ее заполучить в невесты. его чудища раскидали нас как котят, но Ирина спасла нас, добровльно уйдя с ним.",112272,null],[220785,"2026-09-18T12:30:58",7,"*Немейя села рядом. Она чувствовала себя крайне дискомфортно. Рассказ о прошлом но... Почему эта женщина похожа на Ирину. Либо она была спасена, либо... Переродилась?*\n\n— Это так... Грустно... Но граф, он получил ее, а наши жизни — доказательство, что не врем. Она отдала себя ему, чтобы нас спасти...",112272,null],[220786,"2026-09-18T12:31:01",17,"— Чушь собачья. Варгос ее отец. Вы просто... Обознались. Это другая Ирина. Моя сестра утонула.",112272,null],[220796,"2026-09-18T12:35:34",31,"- у нее довольно приметная внешность. Тут сожно ошибится. Да и увидев кукол, ктоыхз ты заказываешь, у нас не осталоось сомнений. Твоя сестра жива, во всяком случае пока еще ива. Я не знаю, что с ней хочет сделать граф.но врядли что то хорошее. Мы не смогли ее защитить, но пообещали сами себе что сделаем все возможное для ее спасения. И как бы это не звучало, мы бы порадовались твоей помощи",112272,null],[220797,"2026-09-18T12:35:59",17,"— Где... Где она сейчас?",112272,null],[220798,"2026-09-18T12:36:07",17,"— Не смогли защитить...",112272,null],[220799,"2026-09-18T12:36:14",7,"Немейя\n— У графа... В замке.",112272,null],[220800,"2026-09-18T12:36:38",17,"— Черт... Дьявол её забрал. Он всегда получает, что хочет.",112272,null],[220803,"2026-09-18T12:38:20",17,"— А вы... Зачем пришли сюда? Меня искали?",112272,null],[220804,"2026-09-18T12:39:06",7,"Немейя\n— Попросить о помощи. Думаю, ты помнишь, что нас было больше... Теперь нас осталось двое. Мы без помощи не сможем просто помощь Ирине...",112272,null],[220805,"2026-09-18T12:42:18",31,"/бля, нам же его мочить нужно/",112272,null],[220807,"2026-09-18T12:42:44",31,"/или достаточно просто чтобы из города ушел?/Ъ",112272,null],[220808,"2026-09-18T12:43:37",7,"/ может мирно договориться?",220807,null],[220809,"2026-09-18T12:43:47",7,"/ нас два осталось",112272,null],[220810,"2026-09-18T12:44:20",31,"нам нужна книга, которую нам отдадут если Айзека завалим/",112272,null],[220811,"2026-09-18T12:44:37",7,"/ против страда ничтожны буквально. Один крестьянин, а я в любой момент могу сам себя дикой магией сбить при помощи кареты с летальным исходом",112272,null],[220812,"2026-09-18T12:44:54",7,"/ не обязательно убивать сказали же.",220810,null],[220813,"2026-09-18T12:46:01",31,"да, я перепроверил\nи я уже не просто крестьянин, я мутироовал в варвара-мимика))/",112272,null],[220814,"2026-09-18T12:46:53",31,"- значит убалтываем его свалить из города/",112272,null],[220815,"2026-09-18T12:47:03",17,"— Да. Я помню.\n\n— Завтра праздник солнца. Отец Луциан донимает меня второй день, в церкви пропажа. А Варгос запретил мне отвлекаться и выстраивать защиту на празднике. Говорит у него предчувствие нехорошее.",112272,null],[220816,"2026-09-18T12:48:21",17,"— Так что вам то нужно от меня? Вы собрались в замок? Хотите чтобы я пошел с вами Ирину спасать? \n\nОн пьёт\n\n— Хорошее дело, сдохнем все как пить дать",112272,null],[220817,"2026-09-18T12:49:44",31,"- сдохнут можно когда угодно. От вас нам нужно содействие. И дещертирство. Нам нудн кое что получить от мадам Вихтер, но она поставила условие - никакого Айзека в городе во время праздника",112272,null],[220818,"2026-09-18T12:50:10",31,"- убивать вас она не просила, если что",112272,null],[220819,"2026-09-18T12:50:23",31,"/похуй, правду ебашу/",112272,null],[220822,"2026-09-18T12:53:46",7,"/ я помогу. Если нужна проверка будет.",220819,null],[220823,"2026-09-18T12:54:31",17,"— Вот же сучья гадючка старая. Никак не угомонится.",220817,null],[220824,"2026-09-18T12:55:16",17,"— Нет, помогать этой старой манде я не буду. Она не считает, что дьявол это раковая опухоль. Слепая. Или просто не хочет видить",112272,null],[220825,"2026-09-18T12:56:01",17,"— Отец это отец. Какой бы небыл. А Фиона под него постоянно копает и зуб точит. Настроила некоторые семьи",112272,null],[220826,"2026-09-18T12:57:02",31,"- ну, мне она тоже не симпатична. Но у нее есть то, что нам нужно, то что нам предсказано для победы над Страдом",112272,null],[220827,"2026-09-18T12:58:08",7,"*Немейя не зная что сказать, смотрела на товарища. Она не знала, как сказать... Боялась конфликта, но после сделала вдох.*\n\n— Мы прости возможности избежать битвы, просто давай обговорим. Нам нужно то, что поможет над Страдом. Давайте просто договоримся.",220819,null],[220839,"2026-09-18T13:05:46",17,"— Да и мне не хочется вас сжигать. Вы вроде как помогаете. Детей вон вернули. Я ценю этот поступок не думайте.",112272,null],[220840,"2026-09-18T13:06:02",17,"— Ну... Значит Фионе надо, чтоб меня там небыло на празднике? А для чего?",112272,null],[220841,"2026-09-18T13:06:06",17,"— Что она задумала?",112272,null],[220843,"2026-09-18T13:06:20",31,"- похоже, готовит переворот",112272,null],[220844,"2026-09-18T13:06:39",17,"— Ясно. Ничего нового. Звучит паршиво",112272,null],[220846,"2026-09-18T13:07:26",17,"— Думаю лучше вам будет просто забрать у неё, то что вам нужно. А я могу закрыть глаза на это. На том и порешим",112272,null],[220847,"2026-09-18T13:07:53",7,"Немейя\n— Она хочет, чтобы улыбка перестала быть искусственной. Вот и все...",112272,null],[220848,"2026-09-18T13:08:13",31,"- а можете организовать как бы официао=льный арест, обыск там",112272,null],[220849,"2026-09-18T13:08:14",17,"— С отцом я договорюсь, а переворот просто уничтожит Валаки. Может Граф только из-за старого решения моего отца и потому что любит потешаться над нами еще оставляет город",112272,null],[220851,"2026-09-18T13:08:32",17,"— Лучше исскуственная улыбка чем сырая земля",220847,null],[220853,"2026-09-18T13:08:59",17,"— Можно, что то придумать. Есть какие нибудь свидетельсва нарушения правопорядка со стороны Вахтеров?",220848,null],[220856,"2026-09-18T13:09:09",17,"— Их два осла сынка постоянно влипают в неприятности",112272,null],[220857,"2026-09-18T13:09:12",7,"Немейя\n— А зачем заставлять улыбаться? Почему не сделать условия.... Чтобы улыбка появлялась сама? Почему люди в клетках?",112272,null],[220860,"2026-09-18T13:09:55",17,"— Не знаю. Пока что всё идёт не плохо",220857,null],[220862,"2026-09-18T13:10:01",17,"— Могло быть куда хуже",112272,null],[220864,"2026-09-18T13:10:10",17,"— Сами знаете, вы же из Багровии",112272,null],[220867,"2026-09-18T13:11:00",7,"Немейя\n— Значит, лучше искусственное хоть что то, чем руины... Багровия таковой стала не из-за графа, а из-за революции?",112272,null],[220879,"2026-09-18T13:14:19",17,"— Я не знаю. Вы мне скажите. Каково там?",112272,null],[220883,"2026-09-18T13:15:53",31,"так, я пропаду на час или больше, Немея, убалтывай его, пускай идет валит эту бабу, а мы пошерстим по шумое ее дом и найдем книгу/",112272,null],[220891,"2026-09-18T13:17:49",7,"*Девушка тяжело вздохнула. Она сначала достает из рюкзака яблоко, протягивая Айзеку. Затем проводить рукой рядом с землей, создавая иллюзию города. Видны лишь руины, грязь, зелень имитирующая мертвецов...*\n\n— Ужасное место, ничего нет... Только руины, сырость, болезни и смерть. Ужас одним словом.",220879,null],[220902,"2026-09-18T13:21:32",17,"— Вот и ответ. Да, исскуственное спокойствие лучше, реальных руин",112272,null],[220953,"2026-09-18T13:41:24",31,"- лично мое, крестьянское мнение, в том, что если что то работает, то это лучше не ломать",112272,null],[220957,"2026-09-18T13:42:18",31,"- а по поводу госпожи Вахтер - мне кажется она не успокоится пока не получит по ушам. Желательно прилюдно",112272,null],[220962,"2026-09-18T13:43:03",7,"Немейя\n— А я не знаю, мне без разницы, но последнее время столько разрухи видела, что мне даже потухший огонек жаль.",112272,null],[220993,"2026-09-18T13:48:35",17,"— Нет у вас ничего на Вахтеров? Кроме того, что она меня убрать хочет? Это я давно знаю",112272,null],[220999,"2026-09-18T13:50:43",31,"- есть подозрение. Она как  т связана с графом. У неё кчть его дневник, который нам и нужен. Откуда ей его взять то, если не от него самого?",112272,null],[221015,"2026-09-18T13:58:44",17,"— Хороший вопрос.",112272,null],[221016,"2026-09-18T13:59:48",7,"Немейя\n— Ну... Не знаю... Ничего не приходит на ум...",112272,null],[227880,"2026-09-21T09:03:34",17,"/ Что делаем? Кому помогаем? Кого убиваем? Кого обворовываем?",112272,null],[227887,"2026-09-21T09:19:14",31,"- ну так может по этому поводу ее и проверить? пока вы ее покошмарите, мы найдем то что нам нужно?",112272,null],[227889,"2026-09-21T09:19:36",17,"— За ней богатые семьи Валаки, Варгоса потом с говном съедят",112272,null],[227892,"2026-09-21T09:20:28",31,"- они вас бояться. подавятся",227889,null],[227894,"2026-09-21T09:21:21",17,"— Так, что вы предлагаете, взять дружину и ворваться в особняк Вахтеров с досмотром?",112272,null],[227895,"2026-09-21T09:21:37",31,"- ну да. Это в вашей власти?",112272,null],[227897,"2026-09-21T09:22:45",17,"— Закон этого не позволяет. Но мы могли бы нарушить закон, вот только... Накануне праздника солнца, такой скандал",112272,null],[227905,"2026-09-21T09:34:04",17,"/ @Evreiskui_Department пора родной пора",112272,null],[227907,"2026-09-21T09:34:17",31,"на учебе поди/",112272,null],[227908,"2026-09-21T09:35:05",7,"/ был",227907,null],[227910,"2026-09-21T09:37:22",7,"Немейя\n— Ну... Возможно стоит попробовать другой подход? Законный? Какой угодно, я в законах слаба...",227897,null],[227911,"2026-09-21T09:38:18",31,"- для законного нужны улики. а у нас времени не хватит их собрать",112272,null],[227914,"2026-09-21T09:47:43",7,"Немейя\n— Ну... Тогда без понятия. Я просто не знаю, ибо в законах мало понимаю.",112272,null],[227915,"2026-09-21T09:50:40",31,"обращаюсь к Айзеку:\n\n- так у нас есть шанс как о с вашей помощью осмотреть дом Вихтер? Просто нужная нам кига очевидно не спрятана сейчас, раз уж она ее нам обещала. в ином случае нам ее не нати, а значит не буде шнаса проив Страда  и мы не сможем помочь Ирине. Идти  к его змку просто так и без подготовки просто глупо",112272,null],[227916,"2026-09-21T09:52:02",31,"/roll d20+1 на запугивание. только я пугаю не Айзека собой, а сорее пугаю его последствиями для сетсры если он нам не поможет, без провакации агрессии по себе",112272,null],[227936,"2026-09-21T10:46:12",17,"— Книга Страда, да? Такая улика может уничтожить Вахтеров. Но вламываться накануне праздника солнца в их дом с отрядом стражи я не пойду. Могу... Обеспечить вам время, если вас засекут стража не появиться как это обычно бывает - быстро. Задержу реагирование насколько смогу.\n\n— Но вламываться к ним в дом, придётся вам",112272,null],[227937,"2026-09-21T10:46:51",17,"— В идеале, чтобы до утренней церемонии у вас была книга, тогда на празднике весь город узнает о связи Вахтеров и дьявола",112272,null],[227939,"2026-09-21T10:54:03",31,"- и то хлеб,та ки договоримся",112272,null],[227940,"2026-09-21T10:55:44",17,"— Я займусь стражей, бессонная ночь нас ждёт.\n\nОн оставляет лилии в вазе и надгробия Ирины и выдвигается в сторону казарм стражи\n\nВы остаётесь наедине с тишиной ночного города Валаки",112272,null],[227941,"2026-09-21T10:56:11",17,"/ Начинаем энкаунтер проникновение в Вахтерхаус. Опишите как вы планируете проникать в дом? Мысли, предложения",112272,null],[227944,"2026-09-21T11:04:48",31,"Тарх чешет голову:\n\n- ну, нам явно не стоит лезть черещ парадный ыход. Я вижу два варинта, либо через задний двор, либо через крышу, благо Немея умеет летать",112272,null],[227945,"2026-09-21T11:05:13",31,"- может через крышу или окно будет лучше",112272,null],[227946,"2026-09-21T11:05:39",31,"- а если подлететь к окну дочери леди Вахтер? он с прибабахом, может и открыть",112272,null],[227948,"2026-09-21T11:09:20",7,"*Немейя закрывается крыльями. Она чувствует себя неуютно на кладбище, учитывая контекст, что осталось всего два из четверых. Однако вздохнув, она говорит.*\n\n— Я фокусами и иллюзией могу имитировать голоса... А скрытность не мое... Что же делать... Дочь леди Вахтер, ты видел ее? Она явно не в себе, что с ней будет...",112272,null],[227950,"2026-09-21T11:09:54",31,"- ну да, девчонку жалко. и так себя кошкой считает",112272,null],[227951,"2026-09-21T11:10:06",31,"попробуем через заднюю дверь?",112272,null],[227952,"2026-09-21T11:11:48",7,"Немейя\n— А что то еще будто остаётся... Но я как лошадь в лавке с посудой. Искра в бочке с порохом. Меня трудно не заметить...",227951,null],[227953,"2026-09-21T11:14:19",31,"- предлагаешь мне одному пойти? впрочем, это может сработать. Нука, оцени\n\nТарх используя свое тело мимика меняет облик на леди Вахтер",112272,null],[227954,"2026-09-21T11:14:36",31,"но стоит шевельнутся и облик пропалдает",112272,null],[227955,"2026-09-21T11:15:16",31,"- не могу держать облик движимого обьекта долго, плохо... кровь нужна, чтобы был образец",112272,null],[227956,"2026-09-21T11:15:58",31,"- зато могу превратится в сундук. если меня кто заметит, просто стану сундуком, или еще чем то незаметным",112272,null],[227958,"2026-09-21T11:18:36",7,"*Немейя слегка испугалась, аш вздрогнула.*\n\n— Т-тарх? Ты всегда ТАК мог? Это... Необычно... \n\n*Девушка явно удивленна и испугана одновременно. Она слегка задумавшись, начинает уходить в мысли.*\n\n— Тогда... Может попробуешь стать кем то из слуг, попробовав чуть крови? Фу, что я говорю, будто вампир...",112272,null],[227959,"2026-09-21T11:20:01",31,"- не всегда, ты права. Во недавно встетил старого приятеля и научился. Я бы не хотел слугу убивать, если честно. но если поймаем кого, и я возьму чуток крови, то смогу держать облик достаточно долго",112272,null],[227960,"2026-09-21T11:25:08",17,"Тревога: 3",112272,null],[227962,"2026-09-21T11:25:53",17,"Вы подошли тёмной ночью к дому Вахтеров. До начала официальной части на площади, которое ожидается в 9:00 осталось около 8 часов",112272,null],[227963,"2026-09-21T11:27:12",17,"Обойдя вокруг вы нашли несколько вариантов проникновения. \n\nПарадный вход.\n\nОкно первого, второго этажей\n\nС обратной стороны дома задний вход. А рядом спуск в подвальное помещение. там дверь",112272,null],[227964,"2026-09-21T11:28:54",31,"/roll d20+2 на внимательность. Нет ли тут кого из слуг, которых можно поймать и использовать как образец?",112272,null],[227966,"2026-09-21T11:29:42",7,"/ а я могу устроить пожар в особняке",112272,null],[227967,"2026-09-21T11:29:43",17,"Внутри тихо, даже слуги спят по ночам",112272,null],[227968,"2026-09-21T11:32:38",31,"Отличная мысль. А погасить потом?/",227966,null],[227971,"2026-09-21T12:02:40",31,"- Немея, а давай устроим пожар. Выкурим их. Ты устрой пожар, а я проникну в дом. Пока я буду там, ты следи за хозяйкой дома. Если книга так ценна, она ведь может с ней вместе выскочить из дома. тут то ты ее и сцапаешь. Или хотя бы проследишь",112272,null],[227973,"2026-09-21T12:10:46",7,"/ а зачем?",227968,null],[227975,"2026-09-21T12:11:44",7,"Немейя\n— А ты уверен? Не думаю, что нас за пожар покроют. И тем более как он мог естественно \"начаться\"?",227971,null],[227976,"2026-09-21T12:12:17",31,"- ну мне то откуда знать? Это ты у нас разбираешься в огне",227975,null],[227977,"2026-09-21T12:12:45",31,"- если считаешь что это невозможно, то будем просто проникать внутрь",112272,null],[227980,"2026-09-21T12:20:50",7,"Немейя\n— Нет... Можно просто устроить пожар заметный \"случайно\", по типу масленая лампа разбилась. Так ты поймаешь одного из слуг, что будет тушить. Возможно одного из сыновей. После прими его облик и иди спокойно. Так будто и легче даже будет...",112272,null],[227981,"2026-09-21T12:21:41",31,"- хорошо, действуй. Я буду ловить тушильщика",112272,null],[227982,"2026-09-21T12:23:06",7,"/ @dunchev мы хотим устроить \"случайный\" пожар. Можно ли вспомнить какой нибудь ангар в поместье или место, где было что то крайне огнеопасное.",112272,null],[227983,"2026-09-21T12:23:50",17,"Внутри дома вы были в прихожей, гостинной где обедали и ведели лестницу наверх. Рядом нет других строений. Постройки стоят в отдалении от сада поместья Вахтеров",112272,null],[227984,"2026-09-21T12:24:14",17,"/ КОнкретно что где и как поджигаешь, если решили поджигать",112272,null],[228015,"2026-09-21T13:20:56",7,"/ хочу чисто внимание пожаром привлечь. Что то поджечь рядом и вероятно принадлежащее Вахтерам. Потом Тарх сватит одного из слуг и примит его облик. Будет ходить и шпионить",227984,null],[228018,"2026-09-21T13:23:37",17,"На заднем дворе за особняком есть хозяйственная постройка.",112272,null],[228019,"2026-09-21T13:25:39",7,"/ за забором, разумеется.",228018,null],[228021,"2026-09-21T13:27:24",7,"/ @QURTZZ начнём мухаха?\nПожар",112272,null],[228023,"2026-09-21T13:28:48",31,"давай. я правдя сейчас уже домой поеду и буду не очень доступен)",112272,null],[228037,"2026-09-21T13:43:35",7,"/ итак. Идем к заднему дворику ночью. Осмотреться хочу. Опиши и я опишу:_",228018,null],[228049,"2026-09-21T14:12:33",17,"Постройка это небольшой сарайчик, но с печью. В окне ты можешь заметить мужчину который спит внутри на койке. Много хозяйственного инвентаря. Похоже это садовник, который живёт в этом сарайчике.",112272,null],[228137,"2026-09-21T14:44:51",17,"/ Жгём мужика заживо?",112272,null],[228992,"2026-09-21T17:22:57",7,"/ устроим рядом пожар. Накаляем угли в печи и рядом бросаем соломы, от чего мог начаться \"пожар\".",228137,null],[228993,"2026-09-21T17:23:24",17,"/ Ну так сарай заперт, внутри спит садовник",112272,null],[229013,"2026-09-21T17:38:13",7,"*Немейя осмотревшись, подлетает к выхлопной трубе. Она достаёт из рюкзака бутыль с маслом. Держала, на всякий. Кое чему после сражения с грифоном она да научилась, как никак. Она задевает внутрь аккуратно по стенке, после чего опустошив бутыль, касается масляной поверхности. Она поджигает его, сама мгновенно слетает с крыши подальше.*",112272,null],[229014,"2026-09-21T17:38:41",7,"/ заливаю масла в дымоход",112272,null],[229015,"2026-09-21T17:38:46",7,"/ и поджигаем",112272,null],[229017,"2026-09-21T17:39:00",7,"/ звук должен разбудить садовника.",112272,null],[229019,"2026-09-21T17:39:49",31,"Тарх притаился за дверью, жду что садовник выскочит из двери",112272,null],[229020,"2026-09-21T17:40:05",17,"/ А какой звук?",112272,null],[229022,"2026-09-21T17:40:35",17,"Садовник крепко спит сарай начинает разгораться в пожаре",112272,null],[229026,"2026-09-21T17:41:27",31,"Набухался и спит скотина, план нам ломает/",229022,null],[229061,"2026-09-21T17:47:07",7,"/ совсем ничего не смутило?",229022,null],[229064,"2026-09-21T17:47:16",7,"/ тогда я на дереве в тени буду любоваться огнем",112272,null],[229069,"2026-09-21T17:47:59",17,"/ Ну налилось масло очень тихо поджёг ты тоже тихо",229061,null],[229070,"2026-09-21T17:48:10",17,"/ А пожар тоже не особо шумный пока не разгорелся",112272,null],[229074,"2026-09-21T17:49:18",7,"/ ну вспыхнул думал громко. Это же масло",229070,null],[229076,"2026-09-21T17:49:28",17,"Через 15 минут начинается настоящий пожар \n\nИз дверей ломится человек, орущий от боли\n\nОттергивает внутреннюю защёлку и вываливается наружу \n\nТарх ты видишь что волосы садовника горят, одежда горит",112272,null],[229078,"2026-09-21T17:49:32",7,"/ в трубе. Же",112272,null],[229079,"2026-09-21T17:49:35",17,"/ Он пьяный был",229074,null],[229082,"2026-09-21T17:49:51",7,"/ шанс Тарха сожрать садовника",229079,null],[229087,"2026-09-21T17:53:40",31,"Мысли Тарха: \"ебаный пиздец. Прости, мужик\"\n\nБью его по голове и пожираю, открыв пасть на груди. Тут же принимаю образ покойного",112272,null],[229088,"2026-09-21T17:54:21",31,"Принимаю облик легко пострадавшего от огня, постанываю в ожидании подмоги из дома хозяев",112272,null],[229089,"2026-09-21T17:54:37",7,"/ удачи, держу за тебя кулачки.",229088,null],[229091,"2026-09-21T17:54:48",7,"/ а я на дереве в листве сижу втыкаю.",112272,null],[229092,"2026-09-21T17:54:53",31,"Наконец-то мой мимик кого то реально сожрал/",112272,null],[229096,"2026-09-21T17:56:07",7,"/ может в этом и есть секрет мимика",112272,null],[229102,"2026-09-21T17:57:45",17,"И так\n\nМимикрировавший под облысевшего от огня садовника Тарх идёт в дом...",112272,null],[229103,"2026-09-21T17:57:50",17,"/ К главному входу?",112272,null],[229104,"2026-09-21T17:58:07",7,"/ он ожидает подмоги.",112272,null],[229107,"2026-09-21T17:59:41",31,"Тарх делает вид что ему плохо и ждет что придут тушить пожар а его унечу в дом для оказания помощи",112272,null],[229112,"2026-09-21T18:03:09",17,"Так и получается через минут 10 пожар замечают в доме, бегут тушить, но уже поздно, Тарха в образе садовника заносят в дом. В гостиной на полу около ковра слуги оказывают ему помощь\n\n— Редольф! Господи помилуй. Живой! \n\nДелают тебе холодную повязку",112272,null],[229115,"2026-09-21T18:05:31",31,"Кряхчу театрально",112272,null],[229138,"2026-09-21T18:16:17",17,"Тут только слуги никто из Вахтеров не спустился",112272,null],[229140,"2026-09-21T18:18:40",17,"Эрнст Ларнак распоряжается\n\n— Перебинтуйте, бедного Рудольфа. Можете положить его на диване.",112272,null],[229142,"2026-09-21T18:21:38",17,"Тебя несут в гостиную и укладывают на диван. С тобой остаётся крупная женщина экономка.\n\nЕе звали между собой — Лорала",112272,null],[229143,"2026-09-21T18:21:44",17,"Что будешь делать?",112272,null],[229146,"2026-09-21T18:23:19",31,"Я знаю ее имя?/",112272,null],[229147,"2026-09-21T18:23:30",7,"/ ты не поглощаешь знания жертв?",229146,null],[229154,"2026-09-21T18:25:36",31,"Не прописывал такого, если честно. Если только мастер своим произволом даст такую возможность",229147,null],[229156,"2026-09-21T18:26:41",17,"Ты слышал что ее называли Лорана",229146,null],[229161,"2026-09-21T18:27:00",17,"/ Нет. Только внешность",229154,null],[229164,"2026-09-21T18:27:09",17,"/ И так хб кусочек",112272,null],[229167,"2026-09-21T18:27:29",31,"Ну справедливо, это было слишком, согласен/",112272,null],[229174,"2026-09-21T18:29:15",31,"- Лорана... Это ты? Может тут кчть что то обезбаливающее... Кажется, я слишком сильно обжёгся.... Ой, я знаю. За моим сарайчиком рос кровавый подорожник... Можешь сходить, проверить? Он бы мне так помог...",112272,null],[229176,"2026-09-21T18:29:23",31,"Пытаюсь отослать наблюдательницу/",112272,null],[229193,"2026-09-21T18:31:25",17,"— Какое обезболивающее старый дурак! Опять курил в пастели! Вот госпожа узнает, тебя высекут!",112272,null],[229194,"2026-09-21T18:31:46",17,"/ Убеждение",112272,null],[229200,"2026-09-21T18:33:58",31,"/roll d20-1 курил, да... Но и пострадал за это...",112272,null],[229292,"2026-09-21T19:42:52",17,"— Ох ослиная ты башка. Ладно, сейчас схожу тебе за обезболивающим. Полбутылки ещё в заначке припрятано.",112272,null],[229293,"2026-09-21T19:43:04",17,"Она уходит куда то на кухню",112272,null],[229298,"2026-09-21T19:45:30",31,"Срываюсь с места, едва за ней захлопнулась дверь. Мысль:\n\n\"Так, где искать книгу? В Библиотеке наверное. А как пройти в библиотеку? Она наверное наверху, на хозяйском этаже.\"\n\nДобираются до лестницы и отправляюсь в второй этаж дома в поисках библиотеки",112272,null],[229301,"2026-09-21T19:46:38",17,"На втором этаже шесть дверей три слева и три справа",112272,null],[229307,"2026-09-21T19:48:52",31,"Мысль Тарха:  \n\n\"Надо приложить ухо к двери и слушать, дышат ли там, если да, значит спальня, туда мне не надо\"",112272,null],[229308,"2026-09-21T19:49:47",31,"/roll d20+2 восприятие",112272,null],[229393,"2026-09-21T20:50:49",17,"За двумя дверьми храп за остальными услышать ничего не удалось",112272,null],[229495,"2026-09-22T04:37:46",31,"Тарх напряжённо думает:\n\n\"Так, эти две исключаются. Тогда начну с тех, за которыми стоит тишина, начну с дальних, книги это вещи ценные, вряд ли бы их поставили близко к лестнице\"",112272,null],[229496,"2026-09-22T04:39:00",31,"/roll d2+4 на скрытность. Осторожно открываю самую дальнюю из дверей, стараясь не скрипеть",112272,null],[229498,"2026-09-22T04:40:53",31,"Но она, сука, скрипит. Бросаю взгляд в комнату, чтобы оценит что там, и принимаю облик вазы, очень похожий на те, что стоят в коридоре",112272,null],[229524,"2026-09-22T08:16:56",17,"/Ты кинул д2 а не д20",229496,null],[229525,"2026-09-22T08:17:08",17,"/Перебрось",112272,null],[229526,"2026-09-22T08:18:10",31,"/roll d20+4",112272,null],[229528,"2026-09-22T08:20:42",17,"Из открытой двери входит кошка",112272,null],[229529,"2026-09-22T08:20:58",17,"За ней еще одна",112272,null],[229530,"2026-09-22T08:21:01",17,"И еще одна",112272,null],[229531,"2026-09-22T08:21:09",17,"Они принюхиваются к вазе",112272,null],[229532,"2026-09-22T08:21:25",17,"/r 3d20+1 Проницательность",112272,null],[229535,"2026-09-22T08:22:04",17,"И две из них начинают шипеть. Третья садится вылизываться",112272,null],[229542,"2026-09-22T08:28:53",31,"на вазе появляются глаза и рот. Говорю кошкам ласково:\n\n- хорошие котики... ложитесь спать, ч просто чуток ошибся",112272,null],[229543,"2026-09-22T08:29:06",31,"/roll d20+2 уход за животными",112272,null],[229545,"2026-09-22T08:29:12",31,"не поверили(",112272,null],[229547,"2026-09-22T08:29:59",17,"Пара щупалец с зубами из вазы кошек явно не обрадовали две пустились наутёк вниз по лестнице, а одна вцепилась в твою ложноножку зубами\n\n/ 1 урона +1 тревога",112272,null],[229548,"2026-09-22T08:30:23",31,"кошку проглатываю",112272,null],[229549,"2026-09-22T08:30:34",17,"/ Минус карма",112272,null],[229550,"2026-09-22T08:30:34",31,"дверь в спальню дочери закрываю",112272,null],[229551,"2026-09-22T08:30:45",17,"Дверь в спальню дочери не была открыта",112272,null],[229552,"2026-09-22T08:30:50",17,"Кошки вышли из библиотеки",112272,null],[229553,"2026-09-22T08:31:08",31,"в багровии жить по вампирьи выть/",229549,null],[229554,"2026-09-22T08:31:36",31,"захожу тогда в библиотеку в образе садовника, начинаю осмотр",112272,null],[229555,"2026-09-22T08:32:37",31,"/roll d20+2 проницательность. где тут может быть особо ценная книга?",112272,null],[229557,"2026-09-22T08:36:30",17,"Кошки с шумом исчезают вниз по лестнице.\n\nНесколько секунд библиотека снова кажется совершенно тихой.\n\nВдоль стен стоят высокие книжные шкафы. Большинство книг старые, кожаные, многие покрыты слоем пыли.\n\nТы замечаешь еще одно. Деревянная кошка сидит на полке. Она смотрит прямо на дальний книжный шкаф.\n\nНа нём стоят пять одинаковых толстых томов.\n\nНа корешках вытиснены названия\n\n«Смерть»\n\n«Рождение»\n\n«Предательство»\n\n«Служба»\n\n«Брак»\n\nКаждый том немного выступает из ряда.\n\nНад полкой в дереве вырезана старая надпись\n\n«Род начинается с крови, крепнет союзом, служит дому и переживает смерть. Предательство рода непростительно»",112272,null],[229558,"2026-09-22T08:39:33",31,"\"загадка? ну а чего ты ждал, олень лесной, что тут просто лежит то что тебе нужно?\"",112272,null],[229559,"2026-09-22T08:40:56",31,"\"хорошо хоть бабка читать научила\"",112272,null],[229560,"2026-09-22T08:41:40",31,"\" так, ну это подсказка явно для порядка. книги нужно вытащить в правильной последовательности\"",112272,null],[229561,"2026-09-22T08:42:20",31,"достаю книгу Рождение, по загадке род первый идет",112272,null],[229562,"2026-09-22T08:42:41",31,"жду реакции, недоверчиво поглядываю на деревянную кошку",112272,null],[229563,"2026-09-22T08:42:58",17,"Книга оттягивается не достаётся но что то щелкает за шкафом",112272,null],[229564,"2026-09-22T08:43:30",31,"\"ага, я похоже на правильном пути. Дальше союз, а это явно брак\"",112272,null],[229565,"2026-09-22T08:43:38",31,"вытягиваю книгу Брак",112272,null],[229566,"2026-09-22T08:44:18",31,"дальше просто, книги Служба, Смерть и Предательство прямо по тексту",112272,null],[229567,"2026-09-22T08:45:34",17,"Прямо перед книгой \"Предательство\" шкаф скрепит и начинает движение, но ты тянешь эту книгу и громкий колокольчик звучит на весь дом",112272,null],[229568,"2026-09-22T08:45:36",17,"/Тревога +2",112272,null],[229569,"2026-09-22T08:46:04",17,"Приглушенные вскрики слышны за дверью, весь дом переполошен",112272,null],[229570,"2026-09-22T08:46:27",17,"Шкаф отодвигается оооочень медленно. Механизм старый и требует смазки",112272,null],[229571,"2026-09-22T08:46:29",31,"шкаф открылся?",112272,null],[229572,"2026-09-22T08:47:01",31,"книга пролезет в щель?/",112272,null],[229573,"2026-09-22T08:47:15",31,"ложноножкой могу проникнуть и достать ее",112272,null],[229574,"2026-09-22T08:48:25",17,"Там комната, а не ниша в стене",112272,null],[229575,"2026-09-22T08:49:59",31,"могу тогда целиком туда пролезть, став протоплазмой, или как там называется то из чего тело мимика на самом деле состоит?",112272,null],[229576,"2026-09-22T08:52:01",17,"/Ок",112272,null],[229579,"2026-09-22T08:52:24",31,"становлюсь аморфной массой и пролезаю за шкаф",112272,null],[229581,"2026-09-22T08:53:53",17,"Снизу тут же слышится движение.\n\nЧей-то голос.\n\nХлопает дверь.\n\nТайная секция книжного шкафа тем временем уже открылась.\n\nЗа ней скрывается маленькая тесная кладовая.\n\nВ центре стоит тяжёлый чёрный сундук с серебряным гербом Вахтеров.\n\nСлева - высокий шкаф, забитый свитками, договорами и старыми книгами.\n\nСправа - маленький письменный стол.\n\nНа нём лежит раскрытая записная книжка.\n\nСлышатся быстрые шаги.\n\nКто-то поднимается по лестнице.",112272,null],[229583,"2026-09-22T08:56:20",31,"/я буду беззастенчиво сейчас пользоваться фишками ХБ, если не ок, то скажи/\n\nБлагодаря своему внутреннему хранилищу, я могу таскать все внутри себя. Хватаю записную книжку и в рот ее,по возможности сгребаю все думаги мз шкафа и закусываю сундуком. Все внутри меня. Сам принимаю облик сожранного сундука",112272,null],[229587,"2026-09-22T09:09:02",17,"/Скинь где почиатть",112272,null],[229589,"2026-09-22T09:18:11",31,"Этож самоделка)",112272,null],[229590,"2026-09-22T09:18:19",17,"/ Окей ладно",112272,null],[229591,"2026-09-22T09:18:56",31,"Думаю, норм ХБ было бы куда круче, я то люблю сложности придумывать себе, скромничаю)",112272,null],[229592,"2026-09-22T09:19:15",31,"Как минимум тесное зрение я себе не дал, какого то хера)/",112272,null],[229594,"2026-09-22T09:20:49",17,"Записная книжка исчезает во рту.\n\nСледом один за другим пропадают свитки, папки, старые документы.\n\nПоследним Тарх заглатывает тяжёлый чёрный сундук.\n\nТело меняется.\n\nКожа темнеет, затвердевает, вытягивается древесной фактурой. Металл проступает по краям. Через несколько мгновений на месте Тарха стоит тот самый чёрный сундук с серебряным гербом Вахтеров.\n\nШаги уже совсем рядом. Дверь библиотеки резко открывается.\nВ помещение вбегает мужчина в одежде домашнего слуги.\n\n— Госпожа?..\n\nОн замечает отодвинутый книжный шкаф. Замирает. Медленно подходит к открывшемуся тайнику.\nЗаглядывает внутрь. Его взгляд проходит по пустому столу. По шкафу. По сундуку.\n\n— Какого...\n\nМужчина быстро оглядывается через плечо.\n\n— Господин Ларнак!\n\nОн снова смотрит на тайник.\n\n— Тут кто-то был!\n\n— Уже бегу! \n\nСлышится тише где то снизу",112272,null],[229595,"2026-09-22T09:20:52",17,"/ Твой ход",112272,null],[229612,"2026-09-22T10:35:29",31,"могу атаковать в преимуществом от засады? Хочу оглушить парня нелетально и свалить через окно/",112272,null],[229618,"2026-09-22T10:36:50",31,"/roll +d20+5",112272,null],[229621,"2026-09-22T10:37:37",31,"урон нужен? или и так его вырубил?/",112272,null],[229680,"2026-09-22T11:25:01",17,"/ Вырубил это обыватель",112272,null],[229683,"2026-09-22T11:36:35",31,"Вырубив парня, возвращаюсь в библиотеку и хочу сбежать через окно, разбиваю его к херам и выпрыгиваю вниз",112272,null],[229797,"2026-09-22T12:21:12",17,"Ты выпрыгиваешь в окно со второго этажа\n\nОно со звоном разбивается\n\nОсколки ранят тебя, внизу ждёт тяжелая встреча с землёй\n\nПозади уже подбегает к разбитому окну человек с тяжелым арбалетом",112272,null],[229798,"2026-09-22T12:21:28",17,"/ Кинь акробатику СЛ12 чтобы снизить урон от падения",112272,null],[229800,"2026-09-22T12:22:24",31,"/roll d20+2",112272,null],[229808,"2026-09-22T12:23:54",31,"Тарх тяжело приземляется, но вроде цел. на какую сторону дома я выскочил?/",112272,null],[229837,"2026-09-22T12:26:29",17,"/r d4 Осколки 2d6 Половина от падения\n\n+5 Выстрел по тебе из арбалета\n\nd10+3 Урон если попадание",112272,null],[229841,"2026-09-22T12:26:54",31,"промах из арбалета/",112272,null],[229842,"2026-09-22T12:26:56",17,"Ты выскочил на левую сторону, противоположную от горящего сарая",112272,null],[229843,"2026-09-22T12:27:10",17,"Как ты выглядел когда выскакивал?",112272,null],[229844,"2026-09-22T12:27:19",31,"садовник/",112272,null],[229845,"2026-09-22T12:27:21",17,"Менял ли ты своё тело чтобы мягче приземлиться?",112272,null],[229846,"2026-09-22T12:27:50",31,"нет, просто прыгал в образе садовника, раз уж не упоминал иного/",112272,null],[229850,"2026-09-22T12:28:18",31,"6 урона вроде, если верно считаю/",112272,null],[229853,"2026-09-22T12:29:13",31,"упав из окна и каким то зверинным чутьем квернувшись от выстрала из арбалета, устремляюсь на рывке в ограде и перебираюсь через нее",112272,null],[229870,"2026-09-22T12:34:47",17,"Ты успешно скрылся, как и обещал Айзек стража задержалась очень прилично. Это было явно \"вялое реагирование\"",112272,null],[229872,"2026-09-22T12:35:15",17,"Вы встретились с Немеей неподалёку в переулке подальше от чужих глаз\n\nВсё что ты смог забрать внутри тебя",112272,null],[229875,"2026-09-22T12:36:21",31,"- Вылазка удалась. Надеюсь. надо глянуть что мы добыли",112272,null],[229876,"2026-09-22T12:36:43",31,"//опиш что я принес пожалуйста/",229872,null],[229880,"2026-09-22T12:37:43",7,"*Немейя сидя на дереве, издалека наблюдала за пожаром. Огонь доставлял удовольствие, что расслабило ее полностью. Однако заметив Тарха, она приземляется рядом.*\n\n— Мне интересно, почему ты обычный крестьянин так не умел ранее. Показывай, что взял.",229875,null],[229882,"2026-09-22T12:40:31",17,"/Будет много лора",112272,null],[229889,"2026-09-22T12:44:10",17,"Тарх и Немейя наконец могут спокойно разобрать то, что он унёс из особняка Вахтеров.\n\nДобычи оказалось значительно больше, чем одна книга.\n\nИз чёрного сундука\n\nДневник графа Страда фон Заровича.\n\nШёлковый мешочек со 180 золотыми монетами. \n\nКожаный кошель со 20 платиновыми.\n\nНа каждой отчеканен профиль Страда.\n\nСтарая деревянная курительная трубка с гербом Вахтеров. (Трубка дымных чудовищ)\n\nПять нотариально заверенных земельных грамот. Всем около четырёхсот лет. Согласно им, земли передавались семье Вахтер лично графом Страдом фон Заровичем.\n\nРукопись Фионы Вахтер под названием «Дьявол, которого мы знаем». В ней она рассуждает о том, что страх перед дьяволами порождён невежеством, а сотрудничество с могущественными тёмными силами способно принести человеку свободу, достаток, власть и долгую жизнь.\n\nОчень старое письмо, адресованное Ловине Вахтер.\n\nАвтор подписался\n\n«Лорд Васили фон Хольц»\n\nЭто короткое благодарственное письмо. Васили благодарит Ловину за многолетние гостеприимство, верность и дружбу.\n\n\nПомимо содержимого сундука Тарх унёс множество семейных бумаг Вахтеров. долговые записи, старые договоры, переписку, родословные, счета и записи о владениях.\n\nБольшинство из них не представляет особого интереса.\n\nНо среди них есть свежие бумаги, касающиеся влиятельных семей Валаки, денежных выплат и подготовки завтрашнего Праздника Солнца.\n\nИ есть личная записная книжка Фионы Вахтер.",112272,null],[229900,"2026-09-22T12:47:26",17,"Записная книжка Фионы:\n\nБольшинство записей короткие.\n\nИмена.\n\nДаты.\n\nСуммы.\n\nИногда несколько слов напротив фамилии.\n\nНо последние страницы посвящены завтрашнему Празднику Солнца.\n\n\"Айзек должен отсутствовать\"\n\nНиже\n\n\"Без него Варгас остаётся человеком с громким голосом и несколькими десятками испуганных стражников\"\n\nНа следующей странице\n\n\"Люди Арсения готовы\"\n\n\"Не вооружать всех. Оружие превращает толпу в мятежников раньше времени\"\n\n\"После первого крика площадь уже не удержать\"\n\n\"Не начинать раньше, чем барон взойдёт на помост\"\n\nНесколько строк перечёркнуты.\n\nДальше:\n\n\"Стража должна выбирать между приказом и собственными семьями\"\n\n\"Не трогать церковь\"\n\n\"Не допустить пожаров\"\n\n\"Варгаса желательно взять живым\"\n\nОтдельной строкой\n\n«Айзек - единственный человек, способный удержать площадь силой. Поэтому его там быть не должно»\n\nЧуть раньше находятся записи о чужаках, недавно появившихся в Валаки.\n\nИмена не указаны.\n\n\"Спасли детей. Значит, способны рисковать не только ради золота\"\n\n\"К графу настроены враждебно\"\n\n\"Им нужна книга\"\n\n\"Приняли предложение. Книга за отсутствие Айзека во время праздника.\"\n\nНа последней заполненной странице всего одна фраза\n\n\"Если завтра всё пройдёт правильно, Валаки впервые за много лет проснётся без Валаковича\"",112272,null],[229965,"2026-09-22T13:15:05",17,"ДНЕВНИК СТРАДА ФОН ЗАРОВИЧА\n«Я — Древний. Я — Земля».\n\nПервые страницы написаны твёрдой, почти военной рукой. Страд начинает свою историю не как чудовище, а как человек, который до сих пор уверен, что когда-то был героем. Он пишет о войне, бесконечных походах, крови, грязи, осадах и погребальных кострах. Когда-то, утверждает он, был добрым. Когда-то был справедливым. Когда-то верил, что несёт порядок туда, где прежде был хаос. Но война продолжалась слишком долго. Годы убийств медленно стирали его душу так же, как ветер превращает камень в песок.\nКогда победы закончились, Страд обнаружил страшную для себя истину: он победил всех врагов и проиграл времени. Его молодость ушла. Лучшие годы жизни остались на полях сражений. От прежнего человека остались титулы, армия, власть и приближающаяся смерть. Его войска подчинили долину, и Страд сделал её своей. Здесь появилась Багровия. Здесь возвышался Равенлофт. Сюда он призвал остатки своей семьи.\n\nСреди прибывших был его младший брат — Сергей. На этих страницах почерк впервые становится тяжелее.\n\n«Он был красив. Он был молод. Я ненавидел его за одно. И ненавидел за другое».\n\nСергей не прожил жизнь Страда. Не отдал юность войне. Не видел, как друзья превращаются в трупы, а победы становятся одинаковыми. Перед ним ещё находилось всё то, что Страд уже потерял.\nА затем появилась Татьяна.\n\nПосле этого её имя возникает на страницах снова и снова. Иногда несколько раз на одной странице. Страд описывает её как женщину, рядом с которой всё остальное в долине становилось серым. Радость. Красота. Жизнь. Молодость. Всё то, что он считал навсегда потерянным, словно воплотилось в одном человеке.\n\n«Я любил её всем сердцем».\n\nНо дальше становится понятно, что значило для него это слово. Он любил её молодость. Её радость. Её красоту. Он хотел, чтобы всё это принадлежало ему.\nТатьяна же смотрела на него иначе. Она называла его старшим. Братом. Иногда — стариком. И каждый раз эти слова ранили сильнее оружия, потому что в её глазах Страд видел не великого полководца, не завоевателя и не властителя. Он видел собственную старость. Собственную смерть.\nА затем сердце Татьяны досталось Сергею.\nОни полюбили друг друга. Была назначена свадьба.\n\nНа следующих страницах почерк меняется. Некоторые строки продавлены пером почти до следующего листа. Страд пишет, что ненавидел смерть, но больше всего ненавидел собственную смерть. Он не хотел быть человеком, чьё время прошло. Не хотел стоять рядом с молодым братом и видеть, каким сам уже никогда не станет.\nИ потому начал искать выход.\nВ дневнике почти нет подробностей того пути, который привёл его к ответу. Есть только итог.\n\nСтрад заключил договор. Не с человеком. Не с королём. Не с богом. Со Смертью.\n\nДоговор крови. Цена должна была быть уплачена кровью.\nВ день свадьбы Сергея и Татьяны Страд заплатил.\nОн убил собственного брата.\n\nКровью Сергея договор был скреплён.\n\nПосле этого Страд отправился искать Татьяну. Он нашёл её плачущей возле часовни. Страд пишет, что хотел всё объяснить. Что она должна была понять. Что всё совершённое им было ради неё.\nТатьяна не стала слушать.\nОна бежала.\nСтрад погнался за ней.\nЧем дальше продолжается описание, тем меньше в нём остаётся раскаяния. Он пишет уже не о женщине, которую любит. Он пишет о том, что принадлежало ему и пыталось уйти.\nТатьяна добежала до стен Равенлофта. Внизу лежала пропасть, скрытая туманом. Позади приближался Страд.\nОна сделала выбор.\n\nТатьяна бросилась вниз.\n\nСтрад видел её падение. Сотни футов сквозь туман. Он видел, как всё, чего он желал, исчезает из его рук.\nЕё тела никогда не нашли.\nДаже Страд не знает, что произошло после падения.\n\nДальнейшие строки становятся почти сухими. Стража Равенлофта обратила оружие против своего господина. Стрелы одна за другой вошли в его тело.\nОн должен был умереть.\nНо договор уже был заключён.\nСтрад не умер.\nНо и живым больше не был.\nНа следующей странице написано одно слово.\n\n«Вампир».",112272,null],[229966,"2026-09-22T13:15:05",17,"Так он называет себя отныне.\nСтрад пишет, что продолжает желать жизни именно потому, что сам её больше не имеет. Жаждет молодости именно потому, что потерял её навсегда. Живые напоминают ему обо всём, чего он лишился.\nИ потому он ненавидит их.\nЗа столетия Страд изучил собственную природу и оставил несколько особенно важных записей.\n\nСолнце. Из всех вещей в мире именно его свет он ненавидит и боится больше всего.\n\nДеревянный кол, пробивший сердце, способен остановить его. Приковать к месту. Но одного кола недостаточно, чтобы уничтожить его окончательно.\nОднако существует ещё одна вещь.\n\nМеч Сергея.\nЗдесь спокойный почерк снова исчезает.\n\n«Этот проклятый меч».\n\nСтрад пишет о нём так, словно даже спустя столетия оружие брата продолжает оскорблять его одним фактом своего существования. Он должен найти клинок. Уничтожить его. Избавиться от последнего оружия Сергея.\nПотому что боится его.\n\nПочти так же сильно, как солнечного света.\n\nНо даже после Сергея, крови, смерти и веков существования дневник неизбежно возвращается к одному имени.\nТатьяна.\n\nСтрад пишет, что охотился за ней снова. И снова. Бывали времена, когда ему казалось, что она наконец почти принадлежит ему. Когда оставалось только протянуть руку.\nИ каждый раз она исчезала.\nУскользала.\nСудьба снова отнимала её.\nНа одной странице несколько раз подряд написано\n\n«Она смеётся надо мной».\n\nСтрад не допускает мысли, что Татьяна никогда его не любила. Не допускает мысли, что выбор всегда принадлежал ей. В его версии происходящего виновата судьба. Смерть. Сергей. Время. Сам мир.\nВсе, кроме него.\n\nИ потому спустя столетия он всё ещё задаёт один и тот же вопрос:\n\nЧто ещё нужно сделать, чтобы заставить её полюбить его?\n\nПоследние страницы посвящены Равенлофту. Страд пишет, что теперь живёт далеко под замком. Среди мёртвых. Под камнями крепости, которую когда-то предназначал для своей семьи.\nТам находится место его сна.\nТам он возвращается к мёртвым, когда миру живых удаётся причинить ему достаточно боли.\nОн собирается скрыть пути туда. Замуровать лестницы. Закрыть проходы. Сделать так, чтобы никто больше не смог потревожить хозяина Равенлофта.\nПоследняя сохранившаяся запись написана отдельно от остальных.\nЧернила вокруг неё расплылись.\n\n«Я потерял царства. Я потерял брата. Я потерял жизнь. Но Татьяна всё ещё где-то существует. И однажды она станет моей».",112272,null],[229967,"2026-09-22T13:19:15",7,"/ короче все проблемы из-за баб",112272,null],[229968,"2026-09-22T13:19:23",7,"/ щас отпишу.",112272,null],[230395,"2026-09-22T15:54:52",17,"/ И так компромат у вас. Дневник графа тоже",112272,null],[230396,"2026-09-22T15:55:11",17,"/ Висит вопрос, а где была Фиона сегодня ночью?",112272,null],[230404,"2026-09-22T16:00:47",31,"Что то мутила перед переворотом. Может есть что то отее планахьв дневнике?",112272,null],[230406,"2026-09-22T16:01:12",17,"/ .",229900,null],[230412,"2026-09-22T16:02:20",31,"- какой то Арсений упомянут...",112272,null],[230413,"2026-09-22T16:02:46",31,"- а вообще, это дело не мое, пусть Айзек разберется. Я ему компромат и солью",112272,null],[230414,"2026-09-22T16:03:04",31,"- айда к Айзеку",112272,null],[230492,"2026-09-22T16:34:58",7,"Немейя\n— Угу.. Пойдем...\n\n*Сказала девушка, смотря на Тарха.*",230414,null],[230884,"2026-09-22T19:02:40",31,"Решаю таки поговорить откровенно, сам понимаю что изменился слишком сильно и слишком быстро\n\n- Немея, если у тебя есть вопросы - задавай. Я отвечу. Не хочу недомолвок",230492,null],[230885,"2026-09-22T19:08:02",7,"*Девушка чувствует себя дискомфортно, ее беспокоит мысль. Один ушел сам, с ним даже попрощались, но потом... Пропажа грубого зверя, Тарх ведет себя странно... Будто подменили... Будто того Тарха нет...*\n\n— Ты раньше так не мог сделать с одной из ведьм и даже не предлагал. Ты раньше вёл себя намного скромнее...\n\n*Сказала девушка с явным недоверием. Она отошла на пару шагов от \"товарища\". Долгие размышления, пока смотрела на огонь дали ей... Чувство тревоги.*",230884,null],[230905,"2026-09-22T19:12:06",31,"- да, еще неделю назад я был просто человеком. А ещё пару месяцев до того был человеком в плену у вампира. Тогда меня спасли. Один из спасителей был мимиком, который ударился в рыцарство. Странный он тип. И буквально позавчера я увидел его вновь. Прямо тут, в Валаки. Он не понимал как попал сюда и ему было плохо от мечтой магии. Он предложил мне симбиоз, и я согласился, потому что выжить тут простому человеку нереально. Симбиоз случился и теперь у меня есть силы и способности мимика. Ну и видимо некоторые черты его характера тоже наложились. Но ощущаю т помню себя я как старого Тарха",230885,null],[230932,"2026-09-22T19:15:35",7,"Немейя\n— Ты тот Тарх, что брал задание на спасение Ирины или нет? \n\n*Сказала девушка, будто не доверяя. Если бы и правда так было, то такое скрывать от союзников нельзя. Это доверие у девушки еще сильнее вызывает, особенно фраза \"старого Тарха\".*",112272,null],[230941,"2026-09-22T19:18:25",31,"- психически да, это я и есть. Но физически уже не совсем. Прости что скрывал, это что то подсознательное наверное, мимикам свойственно быть скрытными",230932,null],[230950,"2026-09-22T19:21:05",7,"*Девушка явно не питает теперь доверия. Как минимум, долго будет восстанавливаться. Так или иначе, надо быть теперь вместе. Задание и цели одни как никак.*\n\n— Думаю, ты понимаешь, что я долго буду это переваривать. Вдруг ты меня сожрёшь.",230941,null],[230953,"2026-09-22T19:21:51",31,"- тебя то пожалуй сожрешь...",112272,null],[230954,"2026-09-22T19:22:08",31,"- Несварение, изжога, муки совести",112272,null],[230958,"2026-09-22T19:23:24",31,"- на самом деле, мне не нужно какой то особо обильное питание. Тут минуса от мимика во мне нет. Я могу поглощать много, но не нуждаюсь в этом сильнее чем обычный человек",112272,null],[230964,"2026-09-22T19:24:26",31,"- а еще я могу быть саможодным сейфом и хранить в себе много вещей",112272,null],[230966,"2026-09-22T19:24:43",7,"*Немейя взглянула на Тарха, будто всматриваясь. Как минимум на предмет обмана, мало ли...*\n\n— Эй, я не настолько ужасна. Моюсь каждый день. \n\n*Сказано было с легкой насмешкой.*",112272,null],[230967,"2026-09-22T19:24:54",7,"/ проницательность кинуть хочу",112272,null],[230970,"2026-09-22T19:25:03",31,"Кидай",112272,null],[230971,"2026-09-22T19:25:20",31,"Коля разрешает кидать без спроса",112272,null],[230976,"2026-09-22T19:26:33",7,"/r d20 +2",112272,null],[230979,"2026-09-22T19:26:41",7,"/ врешь ли ты мне?",112272,null],[230981,"2026-09-22T19:27:14",31,"Тарх не врёт. Или по крайней мере, сам верит в свои слова",112272,null],[230985,"2026-09-22T19:29:09",7,"*Немейе все еще нужно чуть времени, чтобы переварить информацию. По крайней мере, то, что Тарх оказался мимиком, один ушел хоть сам, а другой... Погиб? Так или иначе, время...*\n\n— И вообще, я...  Думаю, что говорить Айзеку. Ненавижу потом жалеть о своих решениях.",112272,null],[230989,"2026-09-22T19:30:51",31,"- да что тут думать? Отдадим доказательства заговора леди Вахтер, он ее повяжет и все дела. Ты же видела ее записи, она бы отдала город графу. А так хоть какое то защищенное место. Вроде как",112272,null],[230996,"2026-09-22T19:34:12",7,"Немейя\n— Дурная у меня голова, но... Может это месть? Как никак, мистер \"улыбайся или сиди в клетке\" или его сын довели до безумия одну ее дочь...",112272,null],[231012,"2026-09-22T19:37:54",17,"/ Попозже почитаю)",112272,null],[231014,"2026-09-22T19:38:53",31,"- я думаю, там с обеих сторон гадят. Это игры благородных, бесятся с жиру",230996,null],[231017,"2026-09-22T19:40:02",7,"Немейя\n— Угу... Я хочу поспать, сегодня мне ещё праздник организовывать и пламя контролировать...",112272,null],[231022,"2026-09-22T19:43:26",31,"Кстати, в где мы живем в Валаки?)/",112272,null],[231026,"2026-09-22T19:45:28",17,"/ Таверна синяя вода.",231022,null],[231029,"2026-09-22T19:48:13",7,"*Немейя потягивается, расправив крылья и тянет руки в стороны. Она зевнула слабо и закрыла рот левой рукой.*\n\n— После Айзека, я хочу пойти спать... И я буду долго это повторять. \n\n*Говорит уже сонно, но полная сил девушка.*",112272,null],[231031,"2026-09-22T19:52:40",31,"- кажется, мы уже добрались до места встречи с Айзеком",112272,null],[231231,"2026-09-23T06:27:19",31,"да, забыл уточнить, мы получаем лично в свое пользование по 90 золотых и 10 платиновых каждый и трубку дымных чудовищ",112272,null],[231232,"2026-09-23T06:27:23",31,"кому трубка?",112272,null],[231233,"2026-09-23T06:28:25",7,"/ я ворованное не возьму °-°",112272,null],[231234,"2026-09-23T06:29:43",31,"ок, принципы это дело такое. тогда все мне)",112272,null],[231235,"2026-09-23T06:33:56",7,"/ да не, сгорели бы примерно все в здании ещё ладно, а тут ну",112272,null],[231241,"2026-09-23T07:15:56",17,"В особняке Валаковичей ещё горит несколько окон.\n\nНа стук дверь открывают далеко не сразу.\n\nЧерез несколько минут в коридоре появляется Айзек. Он всё ещё одет, только тяжёлый плащ брошен поверх рубахи. Судя по лицу, после кладбища он так и не ложился.\n\n— Вы опять?\n\nОн замечает принесённые бумаги.\n\nВыражение лица сразу меняется.\n\n— Заходите.\n\nНесколько минут спустя документы уже лежат на большом столе.\n\nАйзек читает молча.\nСначала записную книжку.\nПотом записи о празднике.\nПотом список людей.\n\nНа строке \"Айзек должен отсутствовать\" он коротко усмехается.\n\n— Старая сука.\n\nЛист переворачивается. \"Страже придётся выбирать между приказом и собственными семьями\" \nУлыбка исчезает.\n\nАйзек перечитывает эту строку ещё раз.\nОчень медленно.\n\n— Семьями...\n\nОн поднимает взгляд.\n\n— Она собиралась послать людей по домам стражников.\n\nСледующая бумага. Связи Вахтеров. Старые грамоты.\n\nАйзек откидывается на спинку стула.\n\n— Хорошо. Этого достаточно.\n\nОн собирает бумаги в одну стопку.\n\n— Заговор против бургомистра. Подготовка беспорядков во время праздника. Попытка устранить командира городской стражи. Угрозы семьям моих людей.\n\nАйзек встаёт.\n\n— Законное основание.\n\nОн стучит пальцем по записной книжке.\n\n— Вот оно.\n\nОн подходит к двери и распахивает её.\n\n— СТРАЖА!\n\nДом мгновенно оживает. Где-то наверху хлопает дверь.В коридорах зажигаются фонари.\nЧерез несколько минут во дворе уже собираются вооружённые люди.\nАйзек выходит на крыльцо.\n\n— Двенадцать человек со мной. Четверо к заднему выходу особняка Вахтеров. Четверо перекрывают улицу. Предупредите людей на воротах никого не выпускать, никого не выпускать!\n\nОдин из стражников спрашивает\n\n— А если окажут сопротивление?\n\nАйзек смотрит на него.\n\n— Валите на землю. Вяжите. Всех брать живыми.\n\nОн натягивает перчатку на человеческую руку. Демоническая остаётся открытой.\n\n— Фиона Вахтер, её сыновья, слуги, гости. Всех, кто находится внутри.\n\nАйзек оборачивается к Тарху и Немее.\n\n— Дальше это уже моя работа.\n\nОн несколько секунд смотрит на них.\n\n— Вы сделали достаточно на одну ночь. Жду вас завтра на празднике. \n\nЗа воротами один за другим зажигаются фонари. Отряд городской стражи выходит на тёмную улицу. Через несколько мгновений Айзек уходит вслед за ними.\n\nВпереди, над крышами Валаки, едва виден тёмный силуэт Вахтерхауса.",112272,null],[231247,"2026-09-23T07:36:37",31,"- кажется, мы запустили лавину с горы. Ладно, надо и впрямь выспаться, завтра день будет ничуть не проще. Пойдем в Синюю Воду",112272,null],[231249,"2026-09-23T07:39:22",17,"/ Можем жестко отыграть синюю воду или перейти к празднику, решайте",112272,null],[231250,"2026-09-23T07:41:25",31,"если важна жесть в таверне, я бы поиграл. Если нет - тот спим/",112272,null],[231253,"2026-09-23T07:53:58",7,"/ я бы в таверне поспал. Персонаж не спит большую часть дня)",231249,null],[231254,"2026-09-23T07:54:11",7,"/  интересно, за обывателя будет опыт 🤔",112272,null],[231255,"2026-09-23T07:56:19",17,"/ 5 опыта",112272,null],[231256,"2026-09-23T07:58:42",7,"/ за сгоревшую хату садовника и самого садовника",231255,null],[231258,"2026-09-23T08:19:10",17,"Вы доходите до трактира \"Синяя вода\"\n\nБольшое здание из дерева, доски потемнели от влаги и времени, вывеска красуется на цепочках, качается на слабом ветру\n\nВ трактире шумно, тепло и впервые за долгое время пахнет нормальной едой. Даника встречает гостей у стойки, а Урвин готовит похлёбку.\n\nУрвин замечает усталость героев\n\n— Похлёбка, хлеб и крыша. Остальные беды подождут до утра.",112272,null],[231259,"2026-09-23T08:19:25",17,"Семья Мартиковых. \n\nУрвин. Даника и их сыновья.\n\nХозяева таверны \"Синяя вода\"",112272,null],[231260,"2026-09-23T08:24:21",7,"*Немейя проходит в здание, складывая крылья так, чтобы не мешали. Она оглядывает трактир, смотря на первого попавшегося — Урвина.*\n\n— Здравствуйте, я бы хотела снять комнату... На ночь...\n\n*Говорит слегка уставшей, но еле заметной улыбкой девушка. Она готовит в кармане золотой, пытаясь не зазеваться.*",231258,null],[231261,"2026-09-23T08:31:50",17,"— Сутки 5 монет. В комнате всё необходимое, уборная на улице, помывочная общая, на втором этаже.",231260,null],[231262,"2026-09-23T08:32:07",17,"Отвечает тебе бармен",112272,null],[231263,"2026-09-23T08:32:39",17,"В закрытое окно несколько раз стучит ворон.\nУрвин подходит к нему, открывает ставню и тихо что-то произносит\n\nПтица каркает и улетает.",112272,null],[231264,"2026-09-23T08:33:02",7,"Немейя\n— Серебряных монет?",231261,null],[231265,"2026-09-23T08:33:31",17,"— Серебра уж как пару столетий нет нигде, госпожа. Золотом расплачиваемся.",112272,null],[231266,"2026-09-23T08:34:48",17,"За ближайшим столом сидят два охотника. На полу лежат свёрнутые волчьи шкуры, рядом стоят луки.\n\nОдин - худой и внимательный. Второй - крепкий, неразговорчивый и постоянно ест.\n\nПервый поднимает кружку\n\n— Новенькие, чего не спите?\n\nВторой осматривает оружие героев\n\n— Или очень смелые, или ещё не поняли, куда попали.\n\nЗатем они представляются\n\n— Сэм.\n\n— Дин. Волков убиваем. Иногда тех, которые притворяются людьми.",112272,null],[231267,"2026-09-23T08:34:54",17,"Сэм и Дин. Охотники на волков.",112272,null],[231268,"2026-09-23T08:35:25",7,"/ отсылка понятна",231267,null],[231269,"2026-09-23T08:35:36",7,"/ \"А обязательно было с языком?\"",112272,null],[231270,"2026-09-23T08:38:55",17,"— Еду заказывать будете? Свежая грибная похлёбка с подосиновиками готова",112272,null],[231276,"2026-09-23T09:11:48",31,"- я сыт, спасибо. но выпил бы",112272,null],[231277,"2026-09-23T09:12:41",31,"с любопытстыом смотрю на хозяина, что общался с вороном.\n\n_- это ваш питомец? и как, хорошо вас понимает? какие команды знает?",112272,null],[231278,"2026-09-23T09:13:02",31,"/вороны - союзники по предсказанию/",112272,null],[231279,"2026-09-23T09:13:34",7,"*Немейя долго двигая монетки в руках, тяжело вздыхает. Она протягивает последние золотые и тяжело вздохнув, ждет ключи.*\n\n— Угу... Вот...",112272,null],[231282,"2026-09-23T09:15:55",17,"— Нет, не петомец. Это наши друзья. Стая воронов приносит нам вести с полей. На виноградниках сейчас беда, заразы захватили поля и поставок вина в ближайшее время не ожидается. Это очень плохие вести.\n\nОтвечает Даника, она достала бутылку вина и погладила ее.\n\n— Осталось немного роскошного вина, желаете?",231277,null],[231283,"2026-09-23T09:16:27",17,"Даника отдаёт тебе ключ от комнаты.\n\n— Да, она двухместная, две кровати раздельно. Других нет",231279,null],[231284,"2026-09-23T09:18:10",31,"роскошного? ну давайте попробуем. Хмм, а нам тоже попадались на пути необычные вороны. Очень умные птицы. Тоже из числа ваших друзей?",231282,null],[231285,"2026-09-23T09:18:36",17,"— Скорее всего да.",112272,null],[231287,"2026-09-23T09:19:04",31,"- и о нас говорили?",112272,null],[231288,"2026-09-23T09:25:33",17,"— Да, рассказывали о том, что случилось у старой мельницы.",231287,null],[231290,"2026-09-23T09:31:15",7,"*Немейя держа ключе, слегка выглядела злой. Спасибо яблоки остались и перед сном может покушать. Она смотрела на Тарха, ожидая его.*",112272,null],[231291,"2026-09-23T09:33:55",31,"- ложись, Немея, я еще посижу. Роскошное вино не часто предлагают",231290,null],[231294,"2026-09-23T09:37:53",7,"*Девушка фыркает и взглянув на ключ, идёт в комнату. Она открывает дверь, заходит и закрывает за собой. Есть хоть время переодеться, а не спать как животное на улице в одежде. Пользуясь моментом, она этим и занимается, после чего ложиться спать.*",231291,null],[231299,"2026-09-23T10:08:38",17,"/Такс Дальше заявочек нет? Тарх пьёт, Немейя спит?",112272,null],[231300,"2026-09-23T10:12:04",7,"/ Немейя кемарит, чтобы  потом Тарху дать зайти. Если кто то чужой зайдет \"не в ту комнату\"",231299,null],[231336,"2026-09-23T10:44:37",31,"я если честно ждал что за вино там роскошное, думал зацепка. потому что и в предсказании говорилось про виноград, и хозяева про виноградники говорили/",231299,null],[231340,"2026-09-23T10:48:51",17,"— Вино роскошное, потому, что другого нет. Да и не предвидится.",112272,null],[231341,"2026-09-23T10:49:21",17,"/ Виноградники это зацепка прямая) Еще вон знакомятся охотники на волков)",231336,null],[231342,"2026-09-23T10:50:41",31,"беру алкашку, подсаживаюсь к охотникам\n\n- доброй ночи. Я Тарх. Гляжу, у вас дело неплохо идет?\n\nКиваю на волчьи шкуры\n\n- Шалят волки и не-совсем-волки?",112272,null],[231346,"2026-09-23T10:58:59",17,"— Да и не говори, Тарх. Целая стая! Оборотни с ручными волками таскают скот и даже людей из деревни неподалёку. Наше оружее оборотней не берет, но волков мы успешно смогли пристрелить.\n\nПоглаживает свой арбалет",112272,null],[231347,"2026-09-23T11:03:17",31,"- чем бить оборотней? если серебра нет? огнем жечь?",112272,null],[231348,"2026-09-23T11:03:38",31,"- вы ксати только по волкам?",112272,null],[231349,"2026-09-23T11:03:51",31,"- или еще какую нечисть валите?",112272,null],[231351,"2026-09-23T11:36:15",17,"— Да, огонь или серебро, простая сталь их не берёт.",112272,null],[231353,"2026-09-23T11:36:41",17,"— Мы с братом стараемся помогать по возможности всем нуждающимся за звонкую монету.",112272,null],[231360,"2026-09-23T11:42:37",31,"Тарх ухмыльнулся, сделал долгий глоток и выдал:\n\n- а сколько бы взяли за заказ на самого?\n\n\"Самого\" было выделено голосом так, чо становилось понятно, что речь о Страде\n\n- ну или может знаете кого, кто на такое самоубийство готов пойти? Не подумайте что я вас как то подставить хочу. Просто интесно, есть ли в Багровии по настоящему крутые охотники?\n\n/дадут же нам обещенного Ван Хельсинга?/",231353,null],[231361,"2026-09-23T11:43:21",7,"/ контракт с языком.",231360,null],[231362,"2026-09-23T11:43:49",31,"мой мимикский язык мало где поместится/",231361,null],[231397,"2026-09-23T12:19:00",17,"Они оба рассмеялись\n\n— Нет, не взялись бы. Верная смерть наша никому пользы не принесёт. Охотники есть, да все мелкие. Как и мы. Граф истребил всех более талантливых.",231360,null],[231402,"2026-09-23T12:20:12",31,"- жаль. я как то слышал о том, кого все вампиры бояться. байка, наверное. типа чтобы людям жилось не так страшно",112272,null],[231436,"2026-09-23T12:28:27",17,"Рядом с охотниками в углу сидел Риктавио\n\n— Господин, Тарх. Прошу вас, присядьте ко мне. У меня кажется есть кое что для вас.",112272,null],[231453,"2026-09-23T12:30:53",31,"Перевожу взгляд на кукольника? или он оружейник?\n\n- Доброй ночи, господин Риктавио. Как ваша механическая кошка?",231436,null],[233450,"2026-09-24T07:17:30",17,"— О, все хорошо. Я кое что подправил и теперь хулиганы не смогут потревожить его.",112272,null],[233451,"2026-09-24T07:18:32",17,"— Я наблюдал за вами. Давно нам пора поговорить. \n\nОн передает тебе по столу сложенный листок бумаги\n\n— Там карта, как добраться до моей одинокой башни. По пути множество ловушек. Поэтому идите строго по этой карте.",112272,null],[233452,"2026-09-24T07:18:56",17,"— После праздника солнца я буду вас ждать. Сейчас из города не выпускают.",112272,null],[233459,"2026-09-24T07:25:54",31,"- мы конечно заглянем к вам в гости. Но зачем? Разве нельзя поговорить прямо здесь?",112272,null],[233460,"2026-09-24T07:32:30",17,"— В моей башне находится весь мой арсенал. Для борьбы сами знаете с кем. А в повозке только ничтожная часть.",112272,null],[233462,"2026-09-24T07:39:53",31,"- хорошо. тогда завтра мы вас навестим. Доброй ночи\n\nУхожу спать, пора уже/",112272,null],[237528,"2026-09-26T18:17:31",17,"Утро в Валаки начинается непривычно рано.\n\nС самого рассвета над улицами развешивают жёлтые ленты и выцветшие знамёна. На домах появляются нарисованные солнца, на площади устанавливают торговые прилавки, а стражники уже с раннего часа сгоняют жителей к центру города.\n\nСегодня - Праздник Солнца.\n\nИ сегодня  весь город Валаки, как и всегда, должнен улыбаться.\n\nНа площади возвышается огромное плетёное солнце. Его каркас собран из дерева и лозы, внутри набита сухая солома, а по краям закреплены десятки факелов. Конструкция настолько огромна, что закрывает собой часть ратуши.\n\nВокруг помоста стоят стражники. Людей становится всё больше.\nМногие действительно улыбаются. Но улыбки получаются странными.\n\nНа помосте уже готово место для бургомистра Варгоса. Рядом стоят Айзек и несколько офицеров городской стражи.\n\nПосле ночного ареста Вахтеров город гудит слухами.\n\nСегодня должна состояться публичная церемония.\n\nИ Варгос обещал, что этот Праздник Солнца станет самым великим за всю историю Валаки.",112272,null],[237562,"2026-09-26T18:27:38",31,"За завтраком рассказываю Немее о приглашении Риктавио:\n\n- нас приглашают в гости после праздника. Судя по всему, у оружейника есть что то интересное",112272,null],[237607,"2026-09-26T18:39:28",17,"Когда площадь окончательно заполняется, раздаётся звон колокола. Разговоры постепенно стихают.\n\nНа помост выходит Варгос.\n\nНа нём праздничная одежда, расшитая золотыми нитями. На лице - широкая улыбка.\nОн поднимает руки.\n\n— Жители Валаки!\n\nТолпа отвечает нестройным\n\n— С праздником!\n\nВаргос улыбается ещё шире.\n\n— Сегодня мы празднуем не просто солнце.\nСегодня мы празднуем то, что Валаки снова свободна от тех, кто хотел отнять у нас наше будущее.\n\nПо площади проходит гул.\nВаргос поворачивается к Айзеку.\n\n— Благодаря нашей страже заговор был раскрыт.\n\nЗатем его взгляд останавливается на вас.\n\n— Но не только благодаря ей.\n\nОн делает шаг вперёд.\n\n— Сегодня среди нас находятся люди, которые доказали, что готовы защищать Валаки, даже не будучи её уроженцами.\n\nТолпа поворачивается к вам.\n\nВаргос улыбается.\n\n— Поднимайтесь сюда, прошу вас, герои!",112272,null],[237608,"2026-09-26T18:39:43",7,"/ скипаем таверну видимо.",237562,null],[237609,"2026-09-26T18:39:46",7,"/ ладно",112272,null],[237612,"2026-09-26T18:41:49",7,"*Немейя проснувшись, еле глаза открыла. Она выглядит крайне сонно, а глаза раздражённо.*\n\n— Угу... Звучит интересно, но задумывался, а почему так \"удобно\" сложилось?\n\n*С этими словами, девушка крайне сонно выглядя осматривает окружение. На ней нет улыбки, лишь в спешке собранные волосы и невыспавшееся лицо.*",237562,null],[237619,"2026-09-26T18:54:49",31,"- не проверим - не узнаем. Ладно, у нас на сегодня и другие дела есть. Тебе еще целое солнце зажигать",237612,null],[237620,"2026-09-26T18:56:22",31,"Неохотно поднимаюсь. Не люблю я эту славу, ещё с партизанских времен не люблю. Но сам ввязался в эту дворянскую свару, теперь уже поздно отступать.\n\nПоднимаюсь, кланюсь Валаковичу и поднимаю руку в знак приветствия толпы горожан",237607,null],[237622,"2026-09-26T19:01:42",7,"*Немейя услышав про сжигание \"солнца\", мгновенно меняется в лице. Она начинает приводить себя в порядок и уже не фальшивая улыбка появляется. Поднимаясь вслед, она всем машет рукой, а после создает пламя и множество огненных рук также машут горожанам.*",237620,null],[237635,"2026-09-26T19:07:48",17,"— Итак, народ Валаки! Вы должны увидеть перемены!\n\nАплодисменты со всех сторон\n\nВаргос поднимает руку, становится тихо, он продолжает\n\n— Досточтимый, Тарх.  Расскажите как вы узрели опасности в городе и поняли ценность порядка?\n\n— Немея, совсем скоро мы зажжем солнце!",112272,null],[237675,"2026-09-26T19:31:54",31,"- ну дык я парень простой и за всегда считаю, что коли во дворе все ровно, то не надо колобродить. И как узнал, что смута затевается, вот и решил, что надо ее перехватить\n\nТарх отыгрывает деревенщину. Простака. С таких и сроса нет обычно",237635,null],[237676,"2026-09-26T19:32:48",7,"*Девушка в предвкушении того, как можно будет сжечь солнце. Она не перебивает речь Тарха и магией делает голос его более выразительным.*",112272,null],[238177,"2026-09-27T12:24:15",17,"Варгос медленно выпрямляет спину. Он подходит к краю помоста и поднимает руку, дожидаясь, пока площадь снова стихнет.\n\n— Вот оно.\n\nВаргос обводит взглядом площадь.\n\n— Вы слышали его. Все ровно и никакая смута не пройдет! Обычный парень из глубинки понимает!\n\nУлыбка Варгоса становится шире. Он медленно указывает рукой на толпу.\n\n— Смута легко превращается в пожар. \n\nПо площади проходит гул.\n\n— Каждый из вас может стать таким же бдительным нражданином. Донесите на соседа, который затевает недоброе против властей и мы сможем присечь смуту! Вместе! \n— Верьте властям! Если каждый будет решать сам, кого считать врагом, кого считать невиновным и каким законом руководствоваться - очень скоро этот город превратится в пепел.\n\nВаргос поворачивается к Айзеку.\n\n— Именно поэтому у нас есть стража.\n\nЗатем к огромному деревянному Солнцу.\n\n— Именно поэтому у нас есть закон. И именно поэтому сегодня мы должны закончить то, ради чего вы все сюда пришли.\n\nОн щёлкает пальцами. Стражники резко натягивают цепи. На помост выводят Фиону Вахтер, Стеллу, Карла и Николая. Эрнста нет.\n\nНа лицах всех четверых ослиные маски. Толпа сначала молчит.\nПотом идут шепотки и Варгос срывает маску осла с Фионы.\n\n— Эти люди не просто хотели власти.\n\nЕго голос становится холоднее.\n\n— Они готовили заговор. Они заключали сделки с теми, кто желает видеть Валаки на коленях. Они готовили предательство.\n\n— И пока вы праздновали, пока вы улыбались, пока вы пытались верить в завтрашний день...\n\nВаргос смотрит прямо на Фиону.\n\n— Они готовили вам могилы.",237675,null],[238180,"2026-09-27T12:30:25",17,"Варгос поворачивается к героям.\n\n— Вы нашли доказательства. Вы раскрыли заговор. Вы дали этому городу возможность дожить до сегодняшнего дня.\n\nОн разводит руками.\n\n— Так позвольте же Валакии увидеть, что происходит с теми, кто пытается погасить её Солнце.\n\nК спинам где кожаные ремни и цепи всех Вахтеров цепляют крюки \n\n— Тарх, честь поднять этих предателей в центр солнца доверена вам!\n\nВ его руке появляется факел.\n\n— Вы хотели показать им свет.\n\nОн протягивает факел Немее\n\n— Так покажите.\n\nУлыбка Варгоса становится почти отеческой.\n\n— Пусть сегодня каждый человек в Валакии запомнит этот день. День, когда порядок победил страх. День, когда предатели получили то, что заслужили.\n\nОн делает шаг назад.\n\n— Зажгите Солнце.",112272,null],[238181,"2026-09-27T12:30:51",17,"/ Тарху предлагается тянуть веревки чтобы поднять Вахтеров в центр солнца а Немее поджечь его",112272,null],[238191,"2026-09-27T12:59:46",7,"*Девушка осматривала толпу, столько внимания она в жизни не получала. После обращения к ней, как ей попытались передать факел. Она касается огня факела и будто берёт в руку. После концентрируется и двигая рукой, бросает ее вверх. Рука указывает на солнце, после чего пламя очень сильно сжимается и выстреливает ярким лучом света. Попадание ровно в солнышко, от чего то вспыхивает и контролируется так, чтобы ничего другого кроме солнца не горело.*\n\n— Благодарю! \n\n/ Устраиваем шоу",238180,null],[238199,"2026-09-27T13:55:12",31,"Тяну, тут некуда отступать. Хотя девочку кошку жалко",238181,null],[238200,"2026-09-27T13:55:36",31,"А Эрнст это кто?/",112272,null],[238201,"2026-09-27T13:59:42",17,"/ Эрнс Ларнак тот кто стрелял по тебе из арбалета. Правая рука Фионы. Он передал приглашение вам и проводил в особняк",112272,null],[238203,"2026-09-27T14:00:14",31,"Мсить будет, сука/",112272,null],[238442,"2026-09-27T19:30:11",17,"Тарх замечает подойдя ближе к Фионе, что у нее отрезан язык, вероятно страховка чтобы она не начала выкрикивать разное и заводить толпу. Вероятно тоже и у всех остальных Вахтеров. Все они подняты на цепях в центр солнца.\n\nИ тогда начинается дождь.\n\nТяжёлые капли шипят на разгорающейся солнце, стекают по золотым знамёнам и лицам горожан. Но сквозь тучи внезапно пробивается луч настоящего солнца. Он падает прямо на огромное деревянное светило над помостом.\n\n— Видите?! \n\nВаргос вскидывает руки.\n\n—  Солнце над Валаки!\n\nТолпа отвечает ему криками.\n\n— Церковь стоит! Не позволяйте страху говорить вместо разума! Святой Андрал с нами!\n\nНо огонь на солнце начинает затухать\n\n— Госпожа Немея! Прибавьте огня прошу вас! Пусть солнце сияет!\n\nИ почти получается.",112272,null],[238590,"2026-09-27T20:16:40",7,"/ Вы можете увеличить или уменьшить вдвое область яркого и тусклого света, излучаемого пламенем, а также поменять его цвет. Эффект действует 1 час.\nВы можете мгновенно распространить огонь на 5 футов в одном направлении, если там присутствует дерево или другое топливо.\nЭто заговор власть над огнем.",238442,null],[238595,"2026-09-27T20:16:55",7,"/ тратить ячейки не надо. Поддерживаю концентрацию",112272,null],[238609,"2026-09-27T20:18:23",7,"*Девушка видя дождь, мгновенно заставляет огнем ещё сильнее вспыхнуть. Он начинает сильно сиять, от чего и выглядит крайне необычно. Цвет начинает переливаться между ярким жёлтым и ало-оранжевым.*\n\n— Минутку.",238442,null],[239994,"2026-09-28T09:12:56",17,"Действительно, деревянная конструкция разгорается даже под проливным дождём.\n\nНарод в восторге.",112272,null],[239995,"2026-09-28T09:14:59",17,"Вы сделали дело, вся семья Вахтеров горит, они безвольно мычат, трое в головах ослов а Фиона без. Она не стонет\n\nЕё взгляд до самом смерти холоден и направлен в одну точку вдаль, в небо. Пока языки пламени пожирали её тело",112272,null],[239996,"2026-09-28T09:20:56",17,"В той точке куда смотрела Фиона, появилось пятнышко. Оно росло приближаясь и вскоре силуэт черной кареты запряженной двумя конями кошмарами с огненной гривой и копытами.\n\nЧерная карета летит по воздуху и приземляется на дальнем конце площади за толпой.\n\nИз нее выходит дьявол. Под проливным дождём к помосту идёт Страд фон Зарович.\n\nТолпа расступается в срахе.\n\n— Прекрасно\n\nПроизносит он\n\n— Особенно про церковь.\n\nУлыбка исчезает с лица Варгоса.\n\n— Скажи им, Варгос. Скажи ещё раз, что у Святого Андрала всё хорошо.\n\nОн делает взмах в сторону неба и черные дождевые тучи затягивают порогал.\n\nСолнца больше нет.",112272,null],[239999,"2026-09-28T09:24:22",17,"Голос Страда усилен магией. Как гром он раздается над площадью. Его слышат все.\n\n— Церковь Святого Андрала пала сутки назад\n\n спокойно говорит Страд. Гул от людей начинается. Бургомистр кричит.\n\n— Он лжёт! Люди выжили! Значит все не так уж плохо!\n\n— О да... Выжили\n\nотвечает Страд.\n\nОн переводит взгляд на Варгоса.\n\n— Вот только домой они не вернулись.\n\n— Где они?! \n\nКричит кто-то из толпы. Страд позволяет вопросу повиснуть.\n\n— В казематах под особняком вашего бургомистра.\n\nТеперь люди смотрят уже не на графа, а на Варгоса.\n\n— Раненые. Напуганные. Те, кто видел, как пала ваша святыня. Те, кто мог рассказать вам, что произошло на самом деле.\n\nЖенщина в толпе выкрикивает имя мужа. Кто-то другой - имя дочери.\n\nВаргос срывается\n\n— Я защищал город! Они могли распространить панику!\n\nСтрад чуть склоняет голову.\n\n— Конечно. Поэтому ты не позволил им вернуться к семьям. Заерыл в клетках. И решил казнить после праздника пол шумок.\n\nТарх видит, как вера в его слова исчезает из лиц людей.\nСтрад произносит почти мягко\n\n— Вот что особенно удобно во лжи. Иногда для неё не нужно ничего придумывать. Достаточно запереть тех, кто знает правду. А после убить их всех. И лепить новую правду.\n\nОн достает из под плаща голову святого отца Люциана, оторванную от тела и кидает на помост под ноги Варгосу\n\nТолпа ахает\n\nА вы вспоминаете, что ходили слухи, что в церкви Святого Андрала была украдена святыня. И похоже дело было серьёзное.",112272,null],[240000,"2026-09-28T09:25:02",17,"Первым летит камень.\nОн ударяет в ступени помоста.\n\n— ОТКРОЙТЕ КАЗЕМАТЫ!\n\nПотом второй голос\n\n— ВЕРНИТЕ НАШИХ!\n\nВаргос отступает и кричит страже\n\n— Арестовать зачинщиков!\n\nИ этим окончательно ломает площадь.\n\nСтражники входят в толпу. Люди начинают пятиться и толкаться. Среди них несколько фигур в капюшонах переглядываются. Один выхватывает нож.\n\nАйзек замечает его первым.\n\nОн хватает заговорщика, с силой валит его на камни и одним ударом прекращает сопротивление.\n\nНо сигнал уже подан.\n\nПо площади мелькают клинки.\n\n— ЗА ФИОНУ!\n\nЛюди Вахтеров бросаются на стражу и чиновников. Один режет подвернувшегося торговца. Другой кидается к женщине, пытающейся вывести детей из толпы. Начинается давка.\n\nТеперь уже никто не понимает, кто на чьей стороне.\n\nСтража избивает горожан. Сторонники Вахтеров нападают на всех подряд. Обычные жители хватают палки и камни.\n\nСтрад остаётся неподвижен.\n\n— Вот она. Ваша безопасность. Вот оно. Ваше спокойствие. \n\nВаргос показывает на него\n\n— ЭТО ОН! ОН СДЕЛАЛ ЭТО!\n\nГраф впервые смотрит на него без улыбки.\n\n— Нет.\n\nОн указывает на тела Вахтеров.\n\n— Я не бросал факел.\n\nНа стражу.\n\n— Я не запирал свидетелей в подземельях.\n\nНа обезумевшую толпу.\n\n— И я не учил этих людей улыбаться, пока вы решаете, кто из них достоин дожить до утра.\n\nРаздаётся треск.\n\nОгромное деревянное солнце начинает рушиться.\n\nСтрад разворачивается.\n\n— Открывайте казематы. Спасайте семьи. Защищайте бургомистра. Ловите убийц.\n\nОн оглядывается на героев.\n\n— Мне действительно любопытно, что вы выберете первым.\n\nИ уходит под проливным дождём, пока позади него Валаки начинает пожирать сама себя.\n\n— АЙЗЕК! УБЕЙ ДЬЯВОЛА!\n\nБургомистра разрывает от бешенства \n\nАйзек бежит на Страда его Дьявольская рука загорается пламенем",112272,null],[240002,"2026-09-28T09:27:42",17,"Страд разворачивается и хватает Айзека за руку.\n\n— Опять ты... Наглец. Интересно что у тебя вырастет теперь...\n\nОдним движением он отрывает демоническую руку Айзека от тела. Вместо крови из неё брызжут во все стороны горячие угли\n\nАйзек ревёт от боли и падает на колени подле Графа\n\n— Немея, может вам это будет нужнее.\n\nОторванная демоническая рука летит в сторону Немеи и падает рядом, не гаснет на удивление",112272,null],[240004,"2026-09-28T09:28:16",17,"На площади началась давка\n\nЛюди валят и топчат людей.\n\nЗаговорщики пытаются убить Варгоса, а часть толпы требует открыть казематы.\n\nСтража пытается защищать бургомистра.\n\nЭрнст Ларнак сидит на крыше и стреляет из арбалета по толпе. Чтобы создать панику.",112272,null],[240005,"2026-09-28T09:28:21",17,"Что вы будете делать?",112272,null],[240010,"2026-09-28T09:34:50",31,"Хера замес/",112272,null],[240011,"2026-09-28T09:35:10",31,"Айзек все, труп? А я думал будет нам помогать/",112272,null],[240014,"2026-09-28T09:41:11",17,"/ Айзек жив, но теперь без руки",112272,null],[240015,"2026-09-28T09:45:44",31,"\"Так, а казематы где? И какие семьи защищать нужно? Бургомистр то хер с ним, и на людей Фионы плевать\"\n\nМысли Тарха выше. Хочет помочь, но не знает кому и куда бежать",112272,null],[240016,"2026-09-28T09:46:07",17,"Тарх\nНемейя\nЗаговорщики\nЭрнст Ларнак\nСтража\nТолпа",112272,null],[240018,"2026-09-28T09:46:17",17,"/Особняк бургомистра, под ним казематы",240015,null],[240019,"2026-09-28T09:46:48",31,"Особняк далеко?/",112272,null],[240020,"2026-09-28T09:47:19",31,"И что там по семьям? Тех кого в толпе давят нужно защитить?/",112272,null],[240023,"2026-09-28T09:51:15",17,"/ Давку прекратить проблематично, Часть людей бежит с площади из-за заговорщиков и Эрнста, потому что они устроили резню. Часть рвётся к дому бургомистра.\n\nСитуация произошла следующая за кадром.\n\nВ церкви пропали святые мощи и граф явился и убил священика вчера, множество прихожан там же убили его упыри. Но часть он оставил в живых. Бургомистр скрыл это, всех выживших закрыл в казематы. А граф сейчас раскрыл их родным что ни там находятся.",240020,null],[240025,"2026-09-28T09:53:45",31,"- Немея, расправляй крылья! Лети к дому бургомистра, вытаскивай оттуда заключённых, я прикрою отход мирных жителей, а люди бургомистра и Вахтеров пусть убивают друг друга столько, сколько им хочется!",112272,null],[240027,"2026-09-28T09:55:09",31,"Бегу в сторону отступающих горожан, на ходу впадаю в ярость и отращиваю хвос, цель - прикрыть отступление мирняка",112272,null],[240046,"2026-09-28T10:33:40",7,"/ нихрена себе",112272,null],[240048,"2026-09-28T10:42:13",7,"/ читаю больше офигеваю",112272,null],[240049,"2026-09-28T10:43:31",31,"Тебе там граф подгон сделал/",240048,null],[240050,"2026-09-28T10:44:44",7,"/ рука Айзека?",240049,null],[240051,"2026-09-28T10:48:39",7,"/ итак. Чтобы разобраться",112272,null],[240052,"2026-09-28T10:49:34",7,"/ мы бургамистру помогать не станем, напротив пусть перебивают друг друга и идем спасать мирняк, так?",240049,null],[240055,"2026-09-28T10:56:02",7,"/ я потерялся в пространстве просто.",112272,null],[240056,"2026-09-28T10:56:15",31,"Ну моя мысль такая. Ты можешь решить по своему)",240052,null],[240059,"2026-09-28T11:04:29",17,"/ Тут хаос, так что это понятно",240055,null],[240065,"2026-09-28T11:20:04",7,"/ тэк. Давай решим, мы примем чью то сторону или нет? Спасем бургомистра — Айзек наш товарищ если выживет. Нет, тогда как страду на 3 лвле сопротивляться. Я из-за долгих обрывов забываю частично квест и тупо теряюсь, что сейчас наглядно и происходит.",112272,null],[240066,"2026-09-28T11:20:04",7,"/ извиняюсь за метогейм, но сейчас я чувствую себя ежиком в тумане",112272,null],[240068,"2026-09-28T11:27:24",31,"Страд срать на нас хотел, он нам ничего не будет, мы для него пыль. Он развлекается/",240065,null],[240070,"2026-09-28T11:28:15",31,"Бургомистр мутный тип, псих видать. Хотя тут все такие. Айзек без демонской руки нам уже не помощник/",112272,null],[240095,"2026-09-28T12:08:48",17,"/ Давайте механику накину\n\n\nВы можете:\n\nСпасать бургомистра в свой ход от убийц заговорщиков / помочь заговорщикам добраться до него\n\nСпасать людей от бессмысленной резни. Эрнст расстреливает толпу с крыши\n\nПомочь Айзеку выбраться\n\nПойти к особняку бургомистра:\n\nЗащитить его от толпы / помочь толпе\n\nМоё любимое - напасть на графа Страда\n\nСбежать из города куда глаза глядят",112272,null],[240101,"2026-09-28T12:26:12",31,"Правильно, меньше персов надо/",240095,null],[240102,"2026-09-28T12:26:30",31,"Мой ход - я буду защищать народ от резни",112272,null],[240103,"2026-09-28T12:27:14",17,"/Можешь описать как ты это делаешь, если хочешь",112272,null],[240104,"2026-09-28T12:27:38",17,"Заговорщики режут в спину любого и продвигаются через толпу убегающих горожан к помосту, где стража закрыла Варгоса",112272,null],[240107,"2026-09-28T12:39:55",7,"/ с другой стороны можно руку Айзеку вернуть. Вдруг срастется",240070,null],[240108,"2026-09-28T12:42:02",31,"Просто бегу в сторону будущего столкновения, стараясь отбрасывать вооружённые людей от мирных, что пытаются убежать. Использую хвост, он у сеня со свойством досягаемость, могу им далеко размахивать/",240104,null],[240118,"2026-09-28T13:09:06",17,"/ Ждём действие Немейи и опишу реакцию мира @Evreiskui_Department",112272,null],[240137,"2026-09-28T13:55:32",7,"/ щас, у меня проблемы.",112272,null],[242743,"2026-09-30T06:21:22",7,"/ тэкс.",112272,null],[242744,"2026-09-30T06:23:29",7,"*Немейя мгновенно хватает руку демона, с некой брезгливостью. Рука необычная, возможно удастся обратно приделать. После отвечает Тарху.*\n\n— А сам Бургомистр? С ним что делать?",240118,null],[242745,"2026-09-30T06:24:55",7,"/ решение за тобой. Я как персонаж думал(а) что поможем бургомистру.",240108,null],[242747,"2026-09-30T06:35:43",31,"На бегу кричу:\n\n- пусть сам расхлебывает, это его война. Я прикрою людей от стражи и мятежников!",242744,null],[242749,"2026-09-30T06:50:17",7,"*Пожав плечами, девушка взлетает и кладёт руку в сумку. После направляется в сторону дома, дабы освободить заключённых.*",242747,null]]);
